insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('robinson-crusoe', 'Robinson Crusoe', 'Daniel Defoe', 'Un naufragio lo deja solo en una isla. Veintiocho años después sigue ahí, y ha tenido que aprenderlo todo desde cero.', 'novela', 81, 483, array['aventura', 'supervivencia', 'clásico']::text[], true)
