insert into public.activities (book_id, chapter_id, kind, prompt, hint)
select 'cuento-de-navidad', c.id, 'reflexionar', '¿A quién de tu vida se parece alguno de estos personajes?', 'No hace falta que se parezcan en todo.' from public.chapters c
