insert into public.activities (book_id, chapter_id, kind, prompt, hint)
select 'platero-y-yo', c.id, 'crear', 'Describe el lugar donde pasa esto. Un detalle basta.', 'Si te sale mejor dibujarlo, dibújalo y cuéntalo en una línea.' from public.chapters c
