insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('tradiciones-peruanas', 'Tradiciones peruanas', 'Ricardo Palma', 'Historias breves de la Lima virreinal contadas con chisme, humor y mala leche. Se leen sueltas, en cualquier orden.', 'cuento', 39, 153, array['perú', 'historia', 'cortos']::text[], true)
on conflict (id) do update set
  title = excluded.title, author = excluded.author,
  synopsis = excluded.synopsis, category = excluded.category,
  chapter_count = excluded.chapter_count,
  minutes_to_read = excluded.minutes_to_read,
  tags = excluded.tags, is_published = true;

insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 0, 'Inicio', $lira$[{"type": "p", "text": "D. Dimas de la Tijereta"}, {"type": "p", "text": "Cuento de viejas que trata de cómo un escribano le ganó un pleito al diablo Érase que se era y el mal que se vaya y el bien se nos venga, que allá por los primeros años del pasado siglo existía, en pleno portal de Escribanos de las tres veces coronada ciudad de los Reyes del Perú, un cartulario de antiparras cabalgadas sobre nariz ciceroniana, pluma de ganso u otra ave de rapiña, tintero de cuerno, gregüescos de paño azul a media pierna, jubón de tiritaña y capa española de color parecido a Dios en lo incomprensible, y que le había llegado por legítima herencia pasando de padres a hijos durante tres generaciones."}, {"type": "p", "text": "Conocíale el pueblo por tocayo del buen ladrón a quien Don Jesucristo dio pasaporte para entrar en la gloria; pues nombrábase D. Dimas de la Tijereta, escribano de número de la Real Audiencia y hombre que, a fuerza de dar fe, se había quedado sin pizca de fe, porque en el oficio gastó en breve la poca que trajo al mundo. Decíase de él que tenía más trastienda que un bodegón, más camándulas que el rosario de Jerusalén que cargaba al cuello, y más doblas de a ocho, fruto de sus triquiñuelas, embustes y trocatintas, que las que cabían en el último galeón que zarpó para Cádiz y de que daba cuenta la Gaceta. Acaso fue por él por quien dijo un caquiversista lo de"}, {"type": "p", "text": "«Un escribano y un gato"}, {"type": "p", "text": "en un pozo se cayeron,"}, {"type": "p", "text": "como los dos tenían uñas por la pared se subieron»."}, {"type": "p", "text": "Fama es que a tal punto habíanse apoderado del escribano los tres enemigos del alma, que la suya estaba tal de zurcidos y remiendos que no la reconociera su Divina Majestad, con ser quien es y con haberla creado. Y tengo para mis adentros que si le hubiera venido en antojo al Ser Supremo llamarla a juicio, habría exclamado con sorpresa: «Dimas, ¿qué has hecho del alma que te di?»."}, {"type": "p", "text": "Ello es que el escribano, en punto a picardías era la flor y nata de la gente del oficio, y que si no tenía el malo por donde desecharlo, tampoco el ángel de la guarda hallaría asidero a su espíritu para transportarlo al cielo cuando le llegara el lance de las postrimerías."}, {"type": "p", "text": "Cuentan de su merced que siendo mayordomo del gremio, en una fiesta costeada por los escribanos, a la mitad del sermón acertó a caer un gato desde la cornisa del templo, lo que perturbó al predicador y arremolinó al auditorio. Pero D. Dimas restableció al punto la tranquilidad, gritando: «No hay motivo para barullo, caballeros. Adviertan que el que ha caído es un cofrade de esta ilustre congregación, que ciertamente ha delinquido en venir un poco tarde a la fiesta. Siga ahora su reverencia con el sermón»."}, {"type": "p", "text": "Todos los gremios tienen por patrono a un santo que ejerció sobre la tierra el mismo oficio o profesión; pero ni en el martirologio romano existe santo que hubiera sido escribano, pues si lo fue o no lo fue San Aproniano está todavía en veremos y proveeremos. Los pobrecitos no tienen en el cielo camarada que por ellos interceda. Mala pascua me dé Dios, y sea la primera que viniere, o déme longevidad de elefante con salud de enfermo, si en el retrato, así físico como moral, de Tijereta, he tenido voluntad de jabonar la paciencia a miembro viviente de la respetable cofradía del ante mí y el certifico. Y hago esta salvedad digna de un lego confitado, no tanto en descargo de mis culpas, que no son pocas, y de mi conciencia de narrador, que no es grano de anís, cuanto porque esa es gente de mucha enjundia con la que ni me tiro ni me pago, ni le debo ni le cobro. Y basta de dibujos y requilorios, y andar andillo, y siga la zambra, que si Dios es servido, y el tiempo y las aguas me favorecen, y esta conseja cae en gracia, cuentos he de enjaretar a porrillo y sin más intervención de cartulario. Ande la rueda y coz con ella."}]$lira$::jsonb, 687);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 1, 'II', $lira$[{"type": "p", "text": "No sé quién sostuvo que las mujeres eran la perdición del género humano, en lo cual, mía la cuenta si no dijo una bellaquería gorda como el puño. Siglos y siglos hace que a la pobre Eva le estamos echando en cara la curiosidad de haberle pegado un mordisco a la consabida manzana, como si no hubiera estado en manos de Adán, que era a la postre un pobrete educado muy a la pata la llana, devolver el recurso por improcedente; y eso que, en Dios y en mi ánima, declaro que la golosina era tentadora para quien siente rebullirse una alma en su almario. ¡Bonita disculpa la de su merced el padre Adán! En nuestros días la disculpa no lo salvaba de ir a presidio, magüer barrunto que para prisión basta y sobra con la vida asaz trabajosa y aporreada que algunos arrastramos en este valle de lágrimas y pellejerías. Aceptemos también los hombres nuestra parte de responsabilidad en una tentación que tan buenos ratos proporciona, y no hagamos cargar con todo el mochuelo al bello sexo."}, {"type": "p", "text": "¡Arriba, piernas,"}, {"type": "p", "text": "arriba, zancas!"}, {"type": "p", "text": "En este mundo"}, {"type": "p", "text": "todas son trampas."}, {"type": "p", "text": "No faltará quien piense que esta digresión no viene a cuento. ¡Pero vaya si viene! Como que me sirve nada menos que para informar al lector de que Tijereta dio a la vejez, época en que hombres y mujeres huelen, no a patchoulí, sino a cera de bien morir, en la peor tontuna en que puede dar un viejo. Se enamoró hasta la coronilla de Visitación, gentil muchacha de veinte primaveras, con un palmito y un donaire y un aquel capaces de tentar al mismísimo general de los padres beletmitas, una cintura pulida y remonona de esas de mírame y no me toques, labios colorados como guindas, dientes como almendrucos, ojos como dos luceros y más matadores que espada y basto. ¡Cuando yo digo que la moza era un pimpollo a carta cabal! No embargante que el escribano era un abejorro recatado de bolsillo y tan pegado al oro de su arca como un ministro a la poltrona, y que en punto a dar no daba ni las buenas noches, se propuso domeñar a la chica a fuerza de agasajos; y ora la enviaba unas arracadas de diamantes con perlas como garbanzos, ora trajes de rico terciopelo de Flandes, que por aquel entonces costaban un ojo de la cara. Pero mientras más derrochaba Tijereta, más distante veía la hora en que la moza hiciese con él una obra de caridad, y esta resistencia traíalo al retortero."}, {"type": "p", "text": "Visitación vivía en amor y compaña con una tía, vieja como el pecado de gula, a quien años más tarde encorozó la Santa Inquisición por rufiana y encubridora, haciéndola pasear las calles en bestia de albarda, con chilladores delante y zurradores detrás. La maldita zurcidora de voluntades no creía, como Sancho, que era mejor sobrina mal casada que bien abarraganada; y endoctrinando pícaramente con sus tercerías a la muchacha, resultó un día que el pernil dejó de estarse en el garabato por culpa y travesura de un pícaro gato. Desde entonces si la tía fue el anzuelo, la sobrina, mujer completa ya según las ordenanzas de birlibirloque, se convirtió en cebo para pescar maravedises a más de dos y más de tres acaudalados hidalgos de esta tierra. El escribano llegaba todas las noches a casa de Visitación, y después de notificarla un saludo, pasaba a exponerla el alegato de bien probado de su amor. Ella le oía cortándose las uñas, recordando a algún boquirrubio que la echó flores y piropos al salir de la misa de la parroquia, diciendo para su sayo: «Babazorro, arrópate que sudas, y límpiate que estás de huevo», o canturriando:"}, {"type": "p", "text": "«No pierdas en mí balas,"}, {"type": "p", "text": "carabinero,"}, {"type": "p", "text": "porque yo soy paloma"}, {"type": "p", "text": "de mucho vuelo."}, {"type": "p", "text": "Si quieres que te quiera"}, {"type": "p", "text": "me has de dar antes"}, {"type": "p", "text": "aretes y sortijas,"}, {"type": "p", "text": "blondas y guantes»."}, {"type": "p", "text": "Y así atendía a los requiebros y carantoña de Tijereta, como la piedra berroqueña a los chirridos del cristal que en ella se rompe. Y así pasaron meses hasta seis, aceptando Visitación los alboroques, pero sin darse a partido ni revelar intención de cubrir la libranza, porque la muy taimada conocía a fondo la influencia de sus hechizos sobre el corazón del cartulario."}, {"type": "p", "text": "Pero ya la encontraremos caminito de Santiago, donde tanto resbala la coja como la sana."}]$lira$::jsonb, 725);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 2, 'III', $lira$[{"type": "p", "text": "Una noche en que Tijereta quiso levantar el gallo a Visitación, o, lo que es lo mismo, meterse a bravo, ordenole ella que pusiese pies en pared, porque estaba cansada de tener ante los ojos la estampa de la herejía, que a ella y no a otra se asemejaba D. Dimas. Mal pergeñado salió éste, y lo negro de su desventura no era para menos, de casa de la muchacha; y andando, andando, y perdido en sus cavilaciones, se encontró, a obra de las doce, al pie del cerrito de las Ramas. Un vientecillo retozón, de esos que andan preñados de romadizos, refrescó un poco su cabeza, y exclamó:"}, {"type": "p", "text": "—Para mi santiguada que es trajín el que llevo con esa fregona que la da de honesta y marisabidilla, cuando yo me sé de ella milagros de más calibre que los que reza el Flos-Sanctorum. ¡Venga un diablo cualquiera y llévese mi almilla en cambio del amor de esa caprichosa criatura!"}, {"type": "p", "text": "Satanás, que desde los antros más profundos del infierno había escuchado las palabras del plumario, tocó la campanilla, y al reclamo se presentó el diablo Lilit. Por si mis lectores no conocen a este personaje, han de saberse que los demonógrafos, que andan a vueltas y tornas con las Clavículas de Salomón, libros que leen al resplandor de un carbunclo, afirman que Lilit, diablo de bonita estampa, muy zalamero y decidor, es el correvedile de Su Majestad Infernal."}, {"type": "p", "text": "—Ve, Lilit, al cerro de las Ramas y extiende un contrato con un hombre que allí encontrarás, y que abriga tanto desprecio por su alma que la llama almilla. Concédele cuanto te pida y no te andes con regateos, que ya sabes que no soy tacaño tratándose de una presa."}, {"type": "p", "text": "Yo, pobre y mal traído narrador de cuentos, no he podido alcanzar pormenores acerca de la entrevista entre Lilit y D. Dimas, porque no hubo taquígrafo a mano que se encargase de copiarla sin perder punto ni coma. ¡Y es lástima, por mi fe! Pero baste saber que Lilit, al regresar al infierno, le entregó a Satanás un pergamino que, fórmula más o menos, decía lo siguiente:"}, {"type": "p", "text": "«Conste que yo, don Dimas de la Tijereta, cedo mi almilla al rey de los abismos en cambio del amor y posesión de una mujer. Ítem, me obligo a satisfacer la deuda de la fecha en tres años». Y aquí seguían las firmas de las altas partes contratantes y el sello del demonio."}, {"type": "p", "text": "Al entrar el escribano en su tugurio, salió a abrirle la puerta nada menos que Visitación, la desdeñosa y remilgada Visitación, que ebria de amor se arrojó en los brazos de Tijereta. Cual es la campana, tal la badajada."}, {"type": "p", "text": "Lilit había encendido en el corazón de la pobre muchacha el fuego de Lais, y en sus sentidos la desvergonzada lubricidad de Mesalina. Doblemos esta hoja, que de suyo es peligroso extenderse en pormenores que pueden tentar al prójimo labrando su condenación eterna, sin que le valgan la bula de Meco ni las de composición."}]$lira$::jsonb, 502);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 3, 'IV (1/2)', $lira$[{"type": "p", "text": "Como no hay plazo que no se cumpla ni deuda que no se pague, pasaron, día por día, tres años como tres berenjenas, y llegó el día en que Tijereta tuviese que hacer honor a su firma. Arrastrado por una fuerza superior y sin darse cuenta de ello, se encontró en un verbo transportado al cerro de las Ramas, que hasta en eso fue el diablo puntilloso y quiso ser pagado en el mismo sitio y hora en que se extendió el contrato. Al encararse con Lilit, el escribano empezó a desnudarse con mucha flema, pero el diablo le dijo:"}, {"type": "p", "text": "—No se tome vuesa merced ese trabajo, que maldito el peso que aumentará a la carga la tela del traje. Yo tengo fuerzas para llevarme a usarced vestido y calzado."}, {"type": "p", "text": "—Pues sin desnudarme, no caigo en el cómo sea posible pagar mi deuda."}, {"type": "p", "text": "—Haga usarced lo que le plazca, ya que todavía le queda un minuto de libertad. El escribano siguió en la operación hasta sacarse la almilla o jubón interior, y pasándola a Lilit le dijo:"}, {"type": "p", "text": "—Deuda pagada y venga mi documento."}, {"type": "p", "text": "Lilit se echó a reír con todas las ganas de que es capaz un diablo alegre y truhán."}, {"type": "p", "text": "—Y ¿qué quiere usarced que haga con esta prenda?"}, {"type": "p", "text": "—¡Toma! Esa prenda se llama almilla, y eso es lo que yo he vendido y a lo que estoy obligado. Carta canta. Repase usarced, señor diabolín, el contrato, y si tiene conciencia se dará por bien pagado. ¡Como que esa almilla me costó una onza, como un ojo de buey, en la tienda de Pacheco!"}, {"type": "p", "text": "—Yo no entiendo de tracamandanas, señor D. Dimas. Véngase conmigo y guarde sus palabras en el pecho para cuando esté delante de mi amo."}, {"type": "p", "text": "Y en esto expiró el minuto, y Lilit se echó al hombro a Tijereta, colándose con él de rondón en el infierno. Por el camino gritaba a voz en cuello el escribano que había festinación en el procedimiento de Lilit, que todo lo fecho y actuado era nulo y contra ley, y amenazaba al diablo alguacil con que si encontraba gente de justicia en el otro barrio le entablaría pleito, y por lo menos lo haría condenar en costas. Lilit ponía orejas de mercader a las voces de D. Dimas, y trataba ya, por vía de amonestación, de zabullirlo en un caldero de plomo hirviendo, cuando alborotado el Cocyto y apercibido Satanás del laberinto y causas que lo motivaban, convino en que se pusiese la cosa en tela de juicio. ¡Para ceñirse a la ley y huir de lo que huele a arbitrariedad y despotismo, el demonio!"}, {"type": "p", "text": "Afortunadamente para Tijereta no se había introducido por entonces en el infierno el uso de papel sellado, que acá sobre la tierra hace interminable un proceso, y en breve rato vio fallada su causa en primera y segunda instancia. Sin citar las Pandectas ni el Fuero Juzgo, y con sólo la autoridad del Diccionario de la lengua, probó el tunante su buen derecho; y los jueces, que en vida fueron probablemente literatos y académicos, ordenaron que sin pérdida de tiempo se le diese soltura, y que Lilit lo guiase por los vericuetos infernales hasta dejarlo sano y salvo en la puerta de su casa. Cumpliose la sentencia al pie de la letra, en lo que dio Satanás una prueba de que las leyes en el infierno no son, como en el mundo, conculcadas por el que manda y buenas sólo para escritas. Pero destruido el diabólico hechizo, se encontró D. Dimas con que Visitación lo había abandonado corriendo a encerrarse en un beaterío, siguiendo la añeja máxima de dar a Dios el hueso después de haber regalado la carne al demonio. Satanás, por no perderlo todo, se quedó con la almilla; y es fama que desde entonces los escribanos no usan almilla. Por eso cualquier constipadito vergonzante produce en ellos una pulmonía de capa de coro y gorra de cuartel o una tisis tuberculosa de padre y muy señor mío."}, {"type": "p", "text": "Y por más que fuí y vine, sin dejar la ida por la venida, no he podido saber a punto fijo si, andando el tiempo, murió D. Dimas de buena o de mala muerte. Pero lo que sí es cosa averiguada es que lió los bártulos, pues no era justo que quedase sobre la tierra para semilla de pícaros. Tal es, ¡oh lector carísimo!, mi creencia."}, {"type": "p", "text": "Pero un mi compadre me ha dicho, en puridad de compadres, que muerto Tijereta quiso su alma, que tenía más arrugas y dobleces que abanico de coqueta, beber agua en uno de los calderos de Pero Botero, y el conserje del infierno le gritó: «¡Largo de ahí! No admitimos ya escribanos»."}]$lira$::jsonb, 783);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 4, 'IV (2/2)', $lira$[{"type": "p", "text": "Esto hacía barruntar al susodicho mi compadre que con el alma del cartulario sucedió lo mismo que con la de judas Iscariote; lo cual, pues viene a cuento y la ocasión es calva, he de apuntar aquí someramente y a guisa de conclusión."}, {"type": "p", "text": "Refieren añejas crónicas que el apóstol que vendió a Cristo echó, después de su delito, cuentas consigo mismo, y vio que el mejor modo de saldarlas era arrojar las treinta monedas y hacer zapatetas, convertido en racimo de árbol."}, {"type": "p", "text": "Realizó su suicidio, sin escribir antes, como hogaño se estila, epístola de despedida, donde por más empeños que hizo se negaron a darle posada."}, {"type": "p", "text": "Otro tanto le sucedió en el infierno, y desesperada y tiritando de frío regresó al mundo buscando dónde albergarse."}, {"type": "p", "text": "Acertó a pasar por casualidad un usurero, de cuyo cuerpo hacía tiempo que había emigrado el alma cansada de soportar picardías, y la de Judas dijo: «Aquí que no peco», y se aposentó en la humanidad del avaro. Desde entonces se dice que los usureros tienen alma de Judas."}, {"type": "p", "text": "Y con esto, lector amigo, y con que cada cuatro años uno es bisiesto, pongo punto redondo al cuento, deseando que así tengas la salud como yo tuve empeño en darte un rato de solaz y divertimiento."}, {"type": "p", "text": "El Cristo de la Agonía"}, {"type": "p", "text": "(Al doctor Alcides Destruge)"}, {"type": "p", "text": "San Francisco de Quito, fundada en agosto de 1534 sobre las ruinas de la antigua capital de los Scyris, posee hoy una población de 70.000 habitantes y se halla situada en la falda oriental del Pichincha o monte que hierve."}, {"type": "p", "text": "El Pichincha descubre a las investigadoras miradas del viajero dos grandes cráteres, que sin duda son resultado de sus vanas erupciones. Presenta tres picachos o respiraderos notables, conocidos con los nombres del Rucu-Pichincha o Pichincha Viejo, el Guagua-Pichincha o Pichincha Niño, y el Cundor-Guachana o Nido de Cóndores. Después del Sangay, el volcán más activo del mundo y que se encuentra en la misma patria de los Scyris, a inmediaciones de Riobamba, es indudable que el RucuPichincha es el volcán más temible de América. La historia nos ha transmitido sólo la noticia de sus erupciones en 1534, 1539, 1577, 1588, 1660 y 1662. Casi dos siglos habían transcurrido sin que sus torrentes de lava y rudos estremecimientos esparciesen el luto y la desolación, y no faltaron geólogos que creyesen que era ya un volcán sin vida. Pero el 22 de marzo de 1859 vino a desmentir a los sacerdotes de la ciencia. La pintoresca Quito quedó entonces casi destruida. Sin embargo, como el cráter principal del Pichincha se encuentra al Occidente, su lava es lanzada en dirección de los desiertos de Esmeraldas, circunstancia salvadora para la ciudad que sólo ha sido víctima de los sacudimientos del gigante que la sirve de atalaya. De desear sería, no obstante, para el mayor reposo de su moradores, que se examinase hasta qué punto es fundada la opinión del barón de Humboldt, quien afirma que el espacio de seis mil trescientas millas cuadradas alrededor de Quito encierra las materias inflamables de un solo volcán."}, {"type": "p", "text": "Para los hijos de la América republicana, el Pichincha simboliza una de las más bellas páginas de la gran epopeya de la revolución. A las faldas del volcán tuvo lugar el 24 de mayo de 1822 la sangrienta batalla que afianzó para siempre la independencia de Colombia."}, {"type": "p", "text": "¡Bendita seas, patria de valientes, y que el genio del porvenir te reserve horas más felices que las que forman tu presente! A orillas del pintoresco Guayas me has brindado hospitalario asilo en los días de la proscripción y del infortunio. Cumple a la gratitud del peregrino no olvidar nunca la fuente que apagó su sed, la palmera que le brindó frescor y sombra, y el dulce oasis donde vio abrirse un horizonte a su esperanza. Por eso vuelvo a tomar mi pluma de cronista para sacar del polvo del olvido una de tus más bellas tradiciones, el recuerdo de uno de tus hombres más ilustres, la historia del que con las inspiradas revelaciones de su pincel alcanzó los laureles del genio, como Olmedo con su homérico canto la inmortal corona del poeta."}]$lira$::jsonb, 690);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 5, 'II', $lira$[{"type": "p", "text": "Ya lo he dicho. Voy a hablaros de un pintor: de Miguel de Santiago."}, {"type": "p", "text": "El arte de la pintura, que en los tiempos coloniales ilustraron Antonio Salas, Gorívar, Morales y Rodríguez, está encarnado en los magníficos cuadros de nuestro protagonista, a quien debe considerarse como el verdadero maestro de la escuela quiteña. Como las creaciones de Rembrandt y de la escuela flamenca se distinguen por la especialidad de las sombras, por cierto misterioso claroscuro y por la feliz disposición de los grupos, así la escuela quiteña se hace notar por la viveza del colorido y la naturalidad. No busquéis en ella los refinamientos del arte, no pretendáis encontrar gran corrección en las líneas de sus Madonnas; pero si amáis lo poético como el cielo azul de nuestros valles, lo melancólicamente vago como el yaraví que nuestros indios cantan acompañados de las sentimentales armonías de la quena, contemplad en nuestros días las obras de Rafael Salas, Cadenas o Carrillo. El templo de la Merced, en Lima, ostenta hoy con orgullo un cuadro de Anselmo Yáñez. No se halla en sus detalles el estilo quiteño en toda su extensión; pero el conjunto revela bien que el artista fue arrastrado en mucho por el sentimiento nacional."}, {"type": "p", "text": "El pueblo quiteño tiene el sentimiento del arte. Un hecho bastará a probarlo. El convento de San Agustín adorna sus claustros con catorce cuadros de Miguel de Santiago, entre los que sobresale uno de grandes dimensiones, titulado La genealogía del santo Obispo de Hipona. Una mañana, en 1857, fue robado un pedazo del cuadro que contenía un hermoso grupo. La ciudad se puso en alarma y el pueblo todo se constituyó en pesquisidor. El cuadro fue restaurado. El ladrón había sido un extranjero comerciante en pinturas."}, {"type": "p", "text": "Pero ya que, por incidencia, hemos hablado de los catorce cuadros de Santiago que se conservan en San Agustín, cuadros que se distinguen por la propiedad del colorido y la majestad de la concepción, esencialmente el del Bautismo, daremos a conocer al lector la causa que los produjo y que, como la mayor parte de los datos biográficos que apuntamos sobre este gran artista, la hemos adquirido de un notable artículo que escribió el poeta ecuatoriano don Juan León Mera."}, {"type": "p", "text": "Un oidor español encomendó a Santiago que le hiciera su retrato. Concluido ya, partió el artista para un pueblo llamado Guápulo, dejando el retrato al sol para que se secara, y encomendando el cuidado de él a su esposa. La infeliz no supo impedir que el retrato se ensuciase, y llamó al famoso pintor Gorívar, discípulo y sobrino de Miguel, para que reparase el daño. De regreso Santiago, descubrió en la articulación de un dedo que otro pincel había pasado sobre el suyo. Confesáronle la verdad. Nuestro artista era de un geniazo más atufado que el mar cuando le duele la barriga y le entran retortijones. Encolerizose con lo que creía una profanación, dio de cintarazos a Gorívar y rebanó una oreja a su pobre consorte. Acudió el oidor y lo reconvino por su violencia. Santiago, sin respeto a las campanillas del personaje, arremetiole también a estocadas. El oidor huyó y entabló acusación contra aquel furioso. Este tomó asilo en la celda de un fraile; y durante los catorce meses que duró su escondite pintó los catorce cuadros que embellecen los claustros agustinos. Entre ellos merece especial mención, por el diestro manejo de las tintas, el titulado Milagro del peso de las ceras. Se afirma que una de las figuras que en él se hallan es el retrato del mismo Miguel de Santiago."}]$lira$::jsonb, 592);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 6, 'III', $lira$[{"type": "p", "text": "Cuando Miguel de Santiago volvió a aspirar el aire libre de la ciudad natal, su espíritu era ya presa del ascetismo de su siglo. Una idea abrasaba su cerebro: trasladar al lienzo la suprema agonía de Cristo."}, {"type": "p", "text": "Muchas veces se puso a la obra; pero, descontento de la ejecución, arrojaba la paleta y rompía el lienzo. Mas no por esto desmayaba en su idea."}, {"type": "p", "text": "La fiebre de la inspiración lo devoraba; y sin embargo, su pincel era rebelde para obedecer a tan poderosa inteligencia y a tan decidida voluntad. Pero el genio encuentra el medio de salir triunfador."}, {"type": "p", "text": "Entre los discípulos que frecuentaban el taller hallábase un joven de bellísima figura. Miguel creyó ver en él el modelo que necesitaba para llevar a cumplida realización su pensamiento."}, {"type": "p", "text": "Hízolo desnudar, y colocolo en una cruz de madera. La actitud nada tenía de agradable ni de cómoda. Sin embargo, en el rostro del joven se dibujaba una ligera sonrisa."}, {"type": "p", "text": "Pero el artista no buscaba la expresión de la complacencia o del indiferentismo, sino la de la angustia y el dolor."}, {"type": "p", "text": "—¿Sufres?—preguntaba con frecuencia a su discípulo."}, {"type": "p", "text": "—No, maestro —contestaba el joven, sonriendo tranquilamente."}, {"type": "p", "text": "De repente Miguel de Santiago, con los ojos fuera de sus órbitas, erizado el cabello y lanzando una horrible imprecación, atravesó con una lanza el costado del mancebo. Éste arrojó un gemido y empezaron a reflejarse en su rostro las convulsiones de la agonía."}, {"type": "p", "text": "Y Miguel de Santiago, en el delirio de la inspiración, con la locura fanática del arte, copiaba la mortal congoja; y su pincel, rápido como el pensamiento, volaba por el terso lienzo."}, {"type": "p", "text": "El moribundo se agitaba, clamaba y retorcía en la cruz; y Santiago, al copiar cada una de sus convulsiones, exclamaba con creciente entusiasmo:"}, {"type": "p", "text": "—¡Bien! ¡Bien, maestro Miguel! ¡Bien, muy bien, maestro Miguel!"}, {"type": "p", "text": "Por fin el gran artista desata a la víctima; vela ensangrentada y exánime; pásase la mano por la frente como para evocar sus recuerdos, y como quien despierta de un sueño fatigoso, mide toda la enormidad de su crimen y, espantado de sí mismo, arroja la paleta y los pinceles, y huye precipitadamente del taller."}, {"type": "p", "text": "¡El arte lo había arrastrado al crimen!"}, {"type": "p", "text": "Pero su Cristo de la Agonía estaba terminado."}]$lira$::jsonb, 369);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 7, 'IV (1/2)', $lira$[{"type": "p", "text": "Éste fue el último cuadro de Miguel de Santiago. Su sobresaliente mérito sirvió de defensa al artista, quien después de largo juicio obtuvo sentencia absolutoria. El cuadro fue llevado a España. ¿Existe aún, o se habrá perdido por la notable incuria peninsular? Lo ignoramos."}, {"type": "p", "text": "Miguel de Santiago, atacado desde el día de su crimen artístico de frecuentes alucinaciones cerebrales, falleció en noviembre de 1673, y su sepulcro está al pie del altar de San Miguel en la capilla del Sagrario."}, {"type": "p", "text": "Mujer y tigre"}, {"type": "p", "text": "Siempre es grato elevar nuestro pensamiento a los días de la infancia, esa edad de ilusiones color de rosa, en que libres de toda zozobra sobre el mañana, creemos que el mundo no se extiende mas allá de nuestros juguetes y del espacio que abarcan nuestros ojos. ¡Bienaventuradas horas en las que nos imaginamos orégano todo el monte, y en las que nadie ha murmurado aún a nuestros oídos que la amistad es una explotación y el amor un artículo de comercio!"}, {"type": "p", "text": "Recorría ayer el álbum de mi memoria, y me detuve de pronto ante el recuerdo de una niña, compañera de mi infancia, enredadora y traviesa si las hubo. Cuando escondía las gafas de la abuela, prendía un petardo a la cola del gato o hacía alguna otra picardihuela, solía la buena anciana aplicarla un par de azoticos, exclamando:"}, {"type": "p", "text": "—Esta niña es el mismo pie de Judas. Es más mala que la señora de***."}, {"type": "p", "text": "De mí sé decir que tanto recalcaba la vieja sobre esto de la maldad de la señora de***, que tomé por la susodicha un miedo más cerval que por el coco. Andando, andando, descifré errante viejo manuscrito cayó por mi cuenta, no dejé bruja a vida de las que penitenció en Lima la Santa Inquisición cuyas marrullerías no me fuesen conocidas, y cuando menos lo esperaba, cata que me encontré con que en uno de los libros del Cabildo y en la Estadística de Fuentes existen datos auténticos sobre mi señora la de***. ¡No que nones! Pues yo tengo de escribir esta leyenda, aunque no sea más que para probar que por pícara y taimada y bellaca que llegase a ser, con el tiempo y las aguas, la pobre niña a quien tan desastroso fin auguraba la abuela, y por mucho que más tarde se afanase en dar al diablo la carne para ofrecer a Dios los huesos, nunca, en los siglos de los siglos, se presentará mujer que exceda en crímenes a la dama de mi historia."}, {"type": "p", "text": "Basta de introito, ¡Al avío y picar puntos!"}, {"type": "p", "text": "La señorita de*** era por los años de 1601 un fresco y codiciable pimpollo de diez y seis primaveras, tal como lo sueña un libertino para curarse de la dispepsia. El señor de***, su padre y la primera fortuna acaso de la tres veces coronada ciudad, cometió la tontuna de morirse dejando a su heredera doña Sebastiana bajo la tutela de D. Blas Medina, asturiano severo y con más penacho que el mismo D. Pelayo. Imagínese el lector si sería codiciable y capaz de despertar el apetito del hombre menos goloso una chica que amén de su juventud, buen coramvobis y riqueza, tenía la rara fortuna de no llevar suegro ni suegra al matrimonio."}, {"type": "p", "text": "Por aquel siglo la cuestión casorio no se llevaba tan al vapor como en los tiempos que alcanzamos. ¡Ya se ve! Aquél era un siglo de obscurantismo y no de progreso, como el actual, en que hoy mañana toma marido la mozuela que ayer noche jugaba a las muñecas. No faltan malditos de cocer que afirman que los matrimonios del día no son para la mujer más que un cambio de juguete, y por eso anda ello enredado como costura de beata o conciencia de escribano. Repito, pues, que en 1601 el matrimonio era un punto que calzaba muchos puntos; y el bueno del tutor, que barruntaba en doña Sebastiana comezones de responder quiero al primer ganapán que la dijese envido, resolvió no permitir tertulia de mozos en casita y guardar a la niña como tesoro en arca de avaro."}]$lira$::jsonb, 678);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 8, 'IV (2/2)', $lira$[{"type": "p", "text": "La educación de la mujer de calidad, por entonces, se reducía a leer lo bastante para imponerse de la vida del santo del día, escribir no muy de corrido lo suficiente para hacer el apunte del lavado, y tocar el arpa, con más o menos primor, lo preciso para lucir su habilidad en una misa de aguinaldo. Esto, un mucho de repetir de coro trisagios y novenas, un poco de condimentar dulces y ensaladas y un nada de trato de gentes, y pare usted de contar, fue la educación de la millonaria y bella damisela. ¡Téngame Dios de su mano y líbreme de culpar de ella al tutor! Culpemos al siglo, que buenos lomos tuvo su merced para soportar esa y todas las cargas que me venga en antojo echarle a cuestas."}, {"type": "p", "text": "La sociedad obligada de doña Sebastiana, aparte del maestro rascador de arpa, que era un viejo capaz por lo feo de dar un espanto al mismo miedo, se reducía a un rechoncho fraile seráfico, al tutor y a su hijo, muchacho seminarista de diez y ocho años y a quien su padre soñaba convertir en todo un canónigo de merced. El D. Carlitos, en presencia de su padre y comensales, adoptaba un airecito de unción y bobería que lo asimilaba a un ángel de retablo. Pero fíate de bobalicones, lector mío, y a puto el postre si no te dan un día cualquiera sarna que rascar."}, {"type": "p", "text": "Seis meses contaba ya doña Sebastiana en poder de su tutor. El mocito abandonaba el claustro del colegio todos los domingos para pasar el día en casa de su señor padre, y a punto de oraciones un negro lo acompañaba hasta entregarlo a los bedeles del seminario."}, {"type": "p", "text": "Pero estaba escrito, D. Carlos tenía más afición que a los infolios teológicos a estudiar en ese libro misterioso que se llama la mujer. El jesuita Sánchez, con su churrigueresco tratado De Matrimonio, exalta la curiosidad de los muchachos más que la serpiente que tentó a Eva. Quizá alguno de sus capítulos cayó en manos del seminarista, y he aquí cómo un mal librajo llevó a carrera de perdición a un joven, casto como el cándido José, y privó acaso a la iglesia de Lima de una de sus más espléndidas luminarias o lumbreras. Este preámbulo debe darte, lector, por informado de que magüer las precauciones de D. Blas para conservar ilesa la prenda que se le dio en depósito, al primer arrumaco que a quemarropa lanzó el fogoso muchacho sobre la inflamable doncella, no se hizo ella de pencas, y cada domingo la enamorada pareja aprovechaba de la hora en que el tutor, como buen hijo de la perezosa España, acostumbraba dormir la siesta, para darse un hartazgo de palabras almibaradas y demás cosas que sospecho deben darse entre amantes."}, {"type": "p", "text": "El hombre es fuego, la mujer estopa, y como una chispa basta para producir un incendio mayor que el cantado por Homero, viene el demonio de repente y... ¡sopla!"}]$lira$::jsonb, 495);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 9, 'II', $lira$[{"type": "p", "text": "Así transcurrieron cinco años en los que, habiendo fallecido D. Blas Medina, entró la joven en el libre goce de su pingüe mayorazgo; y don Carlos colgó la sotana del seminarista, convencido de que Dios no lo llamaba camino de la Iglesia. D. Blas, que en sus mocedades había desempeñado un valioso corregimiento en el Cuzco y acrecido después su fortuna en el comercio, legó a su heredero un caudal nada despreciable."}, {"type": "p", "text": "Echose el mocito a campar por sus respetos, a frecuentar el mundo, del que la austeridad de su difunto padre lo había mantenido a distancia, y a triunfar en toda regla."}, {"type": "p", "text": "El amor que había sentido por Sebastianita se desvaneció. Era amor gastado, y el mozo necesitaba andar a caza de novedades. Olvidó la palabra empeñada de casarse y legitimar a los dos niños habidos de sus secretos amores, y cuando menos lo esperaba la pobre enamorada, recibió una carta en que D. Carlos la noticiaba que había contraído matrimonio in facie ecclesiæ con una hija del capitán de arcabuceros D. Santiago Pedrosa, llamada doña Dolores."}, {"type": "p", "text": "Imagínese el lector el efecto que produciría la esquela en el ánimo de la apasionada mujer. Durante algún tiempo anduvo su honra en lenguas de las comadres de Lima, que hacían de ella mangas y capirotes. Rugíase también que doña Sebastiana no tenía el juicio muy en sus cabales. A la postre, como toda mujer que ha amado"}, {"type": "p", "text": "frenéticamente a la criatura, se volvió al Creador, lo que en buen romance quiere decir que se tornó beata, y beata de correa, que es otro ítem más; beata de las que leían el librito publicado por un jesuita con el título de Alfalfa espiritual para los borregos de Jesucristo, en el cual se llamaba a la Hostia consagrada pan de perro (pan de pecador). No obstante, siempre que en el templo o en la calle encontraba al perjuro amante tenían lugar escenas escandalosísimas. Doña Sebastiana no retrocedía en su empeño de volver a cautivar al rebelde, y éste se había empestillado en el tonto capricho de dar al mundo un ejemplo de fidelidad conyugal."}, {"type": "p", "text": "Y así pasaron tres años, hasta que la infeliz se convenció de que nada tenía que esperar del amor de D. Carlos, y entonces resolvió cambiar de táctica y consagrarse a la venganza."}]$lira$::jsonb, 384);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 10, 'III', $lira$[{"type": "p", "text": "Era un día lunes, y al salir D. Carlos de la misa de San Agustín se encontró con su sombra o pesadilla encarnada en Sebastiana."}, {"type": "p", "text": "—Hacedme la merced, Sr. D. Carlos, de escuchar unas pocas palabras que por última vez os quiero decir."}, {"type": "p", "text": "—Estoy a vuestras órdenes, señora mía, siempre que no insistáis en ponerme un afecto que hoy sería un crimen —la contestó el joven."}, {"type": "p", "text": "—Pláceme veros tan leal esposo. Sabéis que observo una vida religiosa y severa, y por ende desechad la aprensión de que os diga nada que recuerde nuestros extravíos."}, {"type": "p", "text": "—Hablad, señora,"}, {"type": "p", "text": "—Tengo un hijo bastante rico, como sabéis. En Lima y bajo mi amparo no es posible que adquiera la educación que merece. Mañana zarpa el galeón del Callao para España, y en él marchará el niño a Madrid, donde será asistido por sus parientes. Os ruego que vos, su padre, le echéis la bendición para que alcance próspero viaje."}, {"type": "p", "text": "—Vuestra demanda es justa, señora, y os ofrezco que luego pasaré por vuestra casa. Mediodía era por filo cuando D. Carlos abrazaba a sus dos hijos en el salón de Sebastiana. Su corazón de padre rebosaba de amor por ellos, y sus caricias y consejos al niño próximo a partir para Europa no tenían límite. La hija, a una indicación de doña Sebastiana, ofreció a su enternecido padre unos bizcochos y una copa de vino de Alicante. D. Carlos comió y bebió con los niños, no sin que la madre les hiciese también la razón, y de pronto su cuerpo se desplomó sobre el canapé."}, {"type": "p", "text": "El infeliz había bebido un narcótico."}]$lira$::jsonb, 266);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 11, 'IV (1/2)', $lira$[{"type": "p", "text": "Dos horas más tarde una calesa se detenía en el patio de una hacienda próxima a la ciudad."}, {"type": "p", "text": "De ella salieron doña Sebastiana y sus dos niños. El calesero, ayudado de otro esclavo, condujo a D. Carlos exánime al lecho que en una de las habitaciones le tenía preparado la vengativa dama."}, {"type": "p", "text": "Ésta, a solas con su víctima, le ató fuertemente los brazos y los pies, y esperó a que saliese de su fatal letargo."}, {"type": "p", "text": "La impresión de D. Carlos, al volver en sí, no alcanza a pintarla nuestra pluma. Cedemos aquí la palabra al cronista:"}, {"type": "p", "text": "«Sebastiana, después de llenar a D. Carlos de improperios, le dijo se preparase para morir en satisfacción de sus perfidias. Llamó en seguida a su hijo, y colocándolo a la vista de su padre, le dijo: «Te quise cuando tu padre fue mi amante. Él me abandonó, burlando mi inocencia, y es esposo de otra mujer, que por él no ha hecho como yo el sacrificio de su honra. Tan vil proceder es el origen del odio que ahora te tengo, en fuerza del que quiero que mueras a presencia de este infame, de quien rechazo conservar prendas que le pertenezcan». Entonces hirió furiosamente al niño, le cortó la cabeza y la arrojó sobre D. Carlos. En seguida llamó a la hija, y con la misma relación y de igual manera la dio muerte. Luego, prodigándole las más atroces injurias, principió a cortar miembro por miembro del cuerpo de D. Carlos, hasta que le vio expirar. Concluida tan horrible carnicería, enterró por la noche, en unión del calesero, los tres cadáveres, y regresó tranquilamente a Lima."}, {"type": "p", "text": "»El alboroto que originó en la ciudad la desaparición de un sujeto tan bienquisto como lo estaba D. Carlos y las diligencias de la familia de su esposa obligaron al virrey a ofrecer por bando dos mil pesos al que diese noticia de Medina, y este aliciente impelió al calesero a revelar el crimen. Grande fue la indignación pública. La delincuente confesó sus delitos en el tormento, y fue sentenciada por la Real Audiencia, a la pena de horca y que le cortasen después las manos, colocándolas en una pica a extramuros de la ciudad, en dirección a la hacienda donde cometió tan horribles crímenes."}, {"type": "p", "text": "»En las cuarenta y ocho horas que permaneció en capilla, no se le notó a tan feroz mujer la menor aflicción. Con gran serenidad decía: «Después de satisfecha mi venganza, aguardo sin temor la muerte»."}, {"type": "p", "text": "La señora de*** fue la primera mujer ahorcada en la plaza mayor de Lima. El Nazareno"}, {"type": "p", "text": "De cómo el cordero vistió la piel del lobo"}, {"type": "p", "text": "El 30 de marzo de 1763 dio fondo en la bahía del Callao el navío San Damián, portador de pliegos de la corona para el Excmo. Sr. D. Manuel de Amat y Juniet, caballero de la orden de San Juan y virrey del Perú. Por entonces era acontecimiento de gran importancia para los habitantes de Lima la llegada de un buque de Ultramar, y las noticias de que él era conductor proporcionaban por largo tiempo el gasto de las tertulias, comentándose y abultándose hasta tal punto, que en breve no las conociera el que las puso en circulación."}, {"type": "p", "text": "Entre los pasajeros del San Damián venía el capitán de arcabuceros D. Diego de Arellano, nombrado por S. M. para encargarse del mando de una compañía. Era el D. Diego mozo de gentil apostura, alegre como unas castañuelas, decidor como un romance de Quevedo y acaudalado como un usurero de hogaño. Hizo en Italia sus primeras armas, logrando amén de la reputación de valiente, que él tenía en mucho, el grado de capitán, que estimaba en no poco. Traíalo también a América el reclamo de una pingüe herencia, legado de un su tío, minero en el Alto Perú, herencia que sin dificultad fue entregada al sobrino, porque éste no quiso tomarse el trabajo de examinar las cuentas que le presentaban. Con lo que, a costa del generoso heredero y del tío que en mal hora pasara a mejor vida, hicieron su agosto esas hambrientas sanguijuelas que el Diccionario de la lengua llama albaceas. El presente se le ofrecía, pues, ligero, derecho y sin tropiezo como camino de hierro."}, {"type": "p", "text": "Justo es añadir que Arellano encontró en Lima una soberbia acogida. Sus hechos militares le daban fama en el ejército; su empleo y distinción le abrían las puertas de las capas más encopetadas; su gallardía le captaba el interés de las damas, y sus riquezas le aseguraban amigos; porque, antes como ahora, averiguada cosa es que nada hay más simpático que el sonido del oro."}, {"type": "p", "text": "Pero de pronto, los más extraños rumores empezaron a correr acerca del capitán, y aunque en ellos había mucho de verdad, concedamos que algo sería fruto de la maledicencia y de la envidia. La conducta misma de D. Diego daba pábulo a la chismografía, porque todas las noches los espléndidos salones de su casa eran teatro de las más escandalosas orgías. Dejó de visitar la sociedad de buen tono que hasta entonces frecuentara, y diose perdidamente al trato de mujerzuelas y gente de mal vivir."}]$lira$::jsonb, 853);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 12, 'IV (2/2)', $lira$[{"type": "p", "text": "Un coplero de tres al cuarto, cuyos versos gozaban de gran boga, sin tener ni la chispa satírica ni la originalidad del poeta limeño Juan de Caviedes, escribió unas jácaras contra el capitán, en las que lo llamaba"}, {"type": "p", "text": "«sustentador de querellas,"}, {"type": "p", "text": "cuba ambulante de vino,"}, {"type": "p", "text": "ocupado de contino"}, {"type": "p", "text": "en descomponer doncellas»."}, {"type": "p", "text": "Y corriendo de mano en mano las maldecidas rimas, y arrebatándoselas los unos a los otros, que de humanos es buscar lo que tiende a la difamación, vino día en que llegaron a las de D. Diego, quien armando de sendas estacas a dos de sus criados, les mandó descargarlas sobre las espaldas del malhadado hijo de Apolo, para"}, {"type": "p", "text": "escarmiento de poetas vergonzantes y desvergonzados. El pobrete quedó como jaco de gitano: «con el pellejo curtido y ni un solo hueso sano»."}, {"type": "p", "text": "No tanto por defender al zurrado coplero cuanto por aversión hacia el capitán, entablaron varios jóvenes pudientes juicio contra él; mas como no alcanzasen a probar que los criados de D. Diego hubiesen sido los instrumentos de la tunda, resultó a la postre que perdieron el pleito con costas, y ainda mais con la obligación de satisfacer al agraviado. Por supuesto que el de Arellano no se conformó con que sus enemigos cantasen el peccavi, y les dijo muy llanamente que era llegada la ocasión de que hablasen los hierros. En consecuencia, tuvo tres desafíos, y tres de sus adversarios sacaron otras tantas heridas de a cuarta; con lo que los demás, acatando la elocuencia que encierra un argumento de lógica toledana, declararon que dejaban al capitán en su buena reputación y fama. Echose tierra sobre el negocio, que terminó como la misa del Viernes Santo, y no se volvió a hablar más de las coplas."}, {"type": "p", "text": "Seguía en tanto el capitán su licencioso sistema de vida, y contábase que estando un domingo en el portal con varios camaradas de vicio, acertó a pasar una dama, notable por su hermosura y recato. Oyendo D. Diego que los otros mancebos hablaban de ella con respeto, se sintió picado y apostó que antes de un mes sería dueño de ese tesoro de virtudes. Desde tal día consagrose a obsequiar a la dama y, en mérito de la brevedad, diremos tan sólo que una noche, después de haber invitado a sus amigos para una orgía, los condujo hasta su dormitorio, en el que se hallaba una mujer."}, {"type": "p", "text": "—¡Mentecatos que creéis en la virtud! —les dijo—. Esa mujer iba hoy a pertenecerme. Pues bien: yo no gusto de gazmoñas Y la cedo al que quiera tomarla."}, {"type": "p", "text": "Por corrompidos que fuesen aquellos calaveras no pudieron reprimir un gesto de horror y salieron de la habitación."}, {"type": "p", "text": "Pocas horas después había en Lima un escándalo más. La deshonra de una mujer hermosa es una victoria para las que envidian su belleza. La desventurada, después de buscar vengador en su hermano, que fue muerto en duelo por D. Diego, tuvo que esconder sus lágrimas y su vergüenza entre las rejas de un claustro."}, {"type": "p", "text": "El descrédito que ésta y otras no menos escandalosas aventuras echaron sobre Arellano, no germinaba tan sólo entre la gente acomodada. Su mala reputación se había popularizado hasta tal punto, que ningún mendigo se atrevía a llegar a la puerta de su casa; porque, a bien librar, llevaba la certidumbre de salir derrengado. Jamás tendió el capitán una mano generosa al infortunio, y hablarle de practicar actos caritativos era excitar su hilaridad, desatándola en epigramas contra las busconas y vagabundos."}, {"type": "p", "text": "Sólo se contaban de él malas acciones, y es fama que su vino fue siempre borrascoso. Con la multitud de historias repugnantes de que era el héroe nuestro capitán, excitó las sospechas del Santo Oficio. No sabemos cómo se las compuso con el terrible Tribunal de la Fe. Ello es que éste se conformó con amonestarle y recomendarle que oyese misa, práctica devota a la que nunca se le vio asistir."}, {"type": "p", "text": "Tal era D. Diego do Arellano, uno de los hombres que en la culta capital del virreinato daba, por sus excentricidades y escándalos, asunto a los corrillos de los desocupados. Y nótese que no lo llamamos el único proveedor de la crónica popular, porque existía otro personaje a quien llamaban el Nazareno, ser misterioso que, al contrario del capitán, representaba sobre la tierra la Providencia de los que sufren."}]$lira$::jsonb, 717);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 13, 'II', $lira$[{"type": "p", "text": "Había por entonces en Lima una asociación de devotos conocida con el nombre de Cofradía de los nazarenos. Reuníanse las noches de los viernes en una celda del convento de la Merced, de donde salían a la capilla que aún existe contigua al templo, para celebrar la religiosa distribución de las caídas del Señor; terminada la cual esparcíanse por la ciudad, recogiendo y dando limosnas."}, {"type": "p", "text": "Vestían los cofrades aquellas noches una larga túnica morada, ceñida por una cuerda de cáñamo, cubriéndoles la cabeza una capucha del mismo color. Gozaban de gran predicamento en el pueblo; porque, al cabo, él era quien sacaba provecho de la caritativa hermandad."}, {"type": "p", "text": "La estimación por los nazarenos tomó mayores creces desde que en 1763 se afilió en ella un hombre de distinguido continente, que recatándose el rostro en el embozo asistía a las sesiones, que se escondía de los demás para vestir la túnica de la orden, a quien nadie oyó tomar parte en los debates. Todo hacía presumir que fuese persona notable el callado y misterioso nazareno."}, {"type": "p", "text": "Un comerciante muy estimado por su probidad, se encontró un día por consecuencia de malas especulaciones en completa bancarrota. Sus émulos, como sucede siempre, empezaron a murmurar de su honradez; y desesperado el buen hombre, se encerró en su cuarto, preparó un veneno, y resuelto al suicidio, principió a poner en orden los documentos que justificaban su conducta mercantil. Terminaba ya esta operación cuando se le apareció un nazareno; y aunque no ha llegado hasta nosotros la conversación que medió, baste decir que pocas horas más tarde el comerciante satisfizo a sus acreedores y que en breve tiempo restableció su fortuna y el crédito de su casa. Dos años después quiso devolver al nazareno la fuerte suma que le prestara; pero su incógnito salvador le ordenó que fundase una escuela para niños y que el resto lo dividiese entre los necesitados."}, {"type": "p", "text": "En los conventos de monjas se encontraban muchas jóvenes que, anhelando tomar el velo, no podían verificarlo por carecer de la dote prevenida por las constituciones monásticas. Un día el encubierto nazareno se acercó a las superioras o abadesas, poniendo en sus manos el dinero necesario para que fueran admitidas las nuevas esposas del Señor."}, {"type": "p", "text": "Todo aquel que sufría esperaba la noche del viernes. El nazareno parecía multiplicarse y nunca era aguardado en vano. Siempre tenía un alivio para la miseria, un consuelo para el dolor."}, {"type": "p", "text": "Pero este hombre, que era el protector del huérfano y la esperanza del pobre, ¿por qué se encerraba en tan profundo misterio? Nadie logró ver jamás su rostro, y como practicaba el bien sin ostentarlo, el pueblo, que es supersticioso con lo que está fuera de lo común y que en toda buena acción encontraba la huella del nazareno, dio en reverenciarlo como a santo y aun en atribuirle milagros."}, {"type": "p", "text": "Mas antes de abandonar al nazareno, plácenos referir una aventura, que entre las muchas consejas que sobre él corren y que dejamos en el tintero, nos ha parecido digna de ver la luz. Cumple también a nuestro propósito abandonar por un momento la pluma del cronista, para copiar de ese libro que se llama la sociedad uno de los cuadros más íntimos."}]$lira$::jsonb, 532);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 14, 'Episodio de la historia de un libertino', $lira$[{"type": "p", "text": "Nunca, hasta aquella noche, habían mis ojos contemplado una mujer tan bella. En su frente juvenil llevaba un no sé qué de vaga y misteriosa melancolía, y al través de sus largas y negras pestañas se adivinaba una lágrima."}, {"type": "p", "text": "¿Cómo la conocí?"}, {"type": "p", "text": "Mancebo emprendedor y calavera la había encontrado al cruzar una calle; y aunque el manto que la cubría no me permitió ver sus facciones, presentí que era joven y hermosa. La dirigí algunas triviales galanterías que, después de obstinado silencio, rechazó con dignidad. Me encapriché en acompañarla a su casa, sin que su resistencia fuera bastante a obligarme a desistir de mi propósito."}, {"type": "p", "text": "Al arrojar el manto que la ocultaba el rostro, quedé inmóvil y extasiado ante un tesoro tal de hermosura y perfecciones. Esa niña llevaba en su ser algo de seráfico, porque su magnífica belleza no hablaba a los sentidos."}, {"type": "p", "text": "Cuando, pasada la primera impresión, examiné la habitación en que me hallaba, vi que era un pequeño cuarto con puerta a la calle de la Recoleta. La más espantosa miseria reinaba en torno suyo."}, {"type": "p", "text": "Mi fascinación se cambió entonces en respeto por esa criatura tan joven y tan sublimemente bella, que, en medio de la corrupción que domina a la humanidad, había podido resistir a la indigencia. Su pobreza me revelaba que era una flor que crecía al borde del abismo. Y sin embargo, si ella lo hubiera querido habría cambiado su situación por el lujo y la opulencia, poniendo como otras desventuradas en subasta sus encantos. Sobre la tierra abundan viejos cínicos, que derrochan el oro para comprar las caricias de esos ángeles manchados con el lodo de la prostitución. La joven abrió una segunda puerta y me hizo penetrar en otro cuarto escasamente alumbrado por una lamparilla colocada ante la imagen de María. En los extremos se descubrían dos camas de tabla. En una de ellas estaba acostada una mujer y en la otra un anciano, los que al vernos entrar gritaron con voz angustiosa:"}, {"type": "p", "text": "—¡Rosa... tengo hambre!"}, {"type": "p", "text": "La pobre niña los acarició y les repartió una escudilla de comida. Los ancianos devoraron el alimento, hasta que, saciados, volvieron a gemir exclamando:"}, {"type": "p", "text": "—¡Rosa... tengo sed!"}, {"type": "p", "text": "Después de haberlos hecho beber, la joven se arrodilló en medio de ambos lechos, repartiendo sus cuidados y consuelos entre los dos infelices, mientras que yo, mudo de estupor, apartaba la vista de tan doloroso cuadro."}, {"type": "p", "text": "Pocos momentos después quedaron dormidos y Rosa me hizo una seña de que la siguiera a la habitación inmediata. Balbuceaba ya una pregunta, cuando ella, anticipándose a mi pensamiento, me dijo ahogando un sollozo:"}, {"type": "p", "text": "—Son mis padres... y están locos por mi causa."}, {"type": "p", "text": "Y el llanto bañó abundosamente sus mejillas. Yo comprendí y respeté ese dolor sin nombre permanecimos por largo rato silenciosos."}, {"type": "p", "text": "Al fin se decidió a contarme su historia, que era sobrado sencilla."}, {"type": "p", "text": "Hija única de padres que gozaban de una decente medianía, fue seducida y más tarde abandonada por un libertino. Ante la publicidad de su deshonra y sin medio alguno para repararla, porque el infame había huido de Lima, los padres de Rosa perdieron la razón, sin que los sacrificios y desvelos de ella, que desde ese día se consagró a cuidarlos, bastasen a devolverles el destello divino que distingue al racional del bruto. La miseria, por otra parte, es mal médico; y Rosa no se atrevió a enviarlos al hospital de locos, porque comprendía el bárbaro tratamiento que allí se daba a los enfermos. La niña calló; y yo, profundamente conmovido, me despedí con religioso respeto de aquel ángel que, lleno de abnegación y de ternura, había sido colocado por Dios para velar sobre los últimos días de dos ancianos."}, {"type": "p", "text": "Cristo que perdonó a Magdalena porque amó mucho, habría también compadecido a esta mujer, que con tan severa expiación purgaba el delito de haber sentido latir un corazón dentro del pecho, de haber obedecido a esa ley de todos los seres que se llama amor."}]$lira$::jsonb, 657);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 15, 'IV', $lira$[{"type": "p", "text": "¿Quién contó al Nazareno el episodio que acabamos de bosquejar?"}, {"type": "p", "text": "Sólo sabemos que a la siguiente noche, vestido con el hábito penitente, se apareció en el humilde cuarto de Rosa y que, a fuerza de esmero y de una costosa asistencia, consiguió poco a poco devolver la razón a los ancianos y la calma a la desventurada joven."}, {"type": "p", "text": "Pero como la gratitud casi siempre es bulliciosa, la hija publicó cuanto debía al Nazareno, a pesar del empeño que éste mostró para que el misterio rodease su buena acción."}, {"type": "p", "text": "Era la última hora de la tarde de un día de septiembre del año 1767. La campana de San Pablo acababa de dar el solemne toque de oración, cuando el Nazareno penetró en la portería del convento de los padres jesuitas y se dirigió a la celda del Superior. Recibido por éste, puso en sus manos un pliego cerrado. El jesuita examinó detenidamente el sello, y sin abrir el pliego, como si por alguna marca de la cera hubiera adivinado el contenido, se volvió hacia el portador y le dijo:"}, {"type": "p", "text": "—Gracias, hermano. Los hijos de Loyola no olvidaremos nunca todo el bien que nos hacéis."}, {"type": "p", "text": "Aquel Oía había fondeado en el Callao un buque de guerra con procedencia de España. El comandante pasó inmediatamente a Lima y entregó al virrey Amat las comunicaciones de que era conductor."}, {"type": "p", "text": "En el mismo instante daba el Nazareno al Superior de los jesuitas el pliego de que ya hemos hablado."}, {"type": "p", "text": "El virrey se encerró en su gabinete a leer la correspondencia. A las once de la noche regresó del teatro, convocó a la Real Audiencia y, vivamente afectado, puso en su conocimiento que se iba a proceder a la expulsión de los jesuitas. El virrey dictó algunas providencias, y tanto a los oidores como a los individuos que venían a contestarle sobre el cumplimiento de las medidas que les había ordenado, les impuso su excelencia arresto en una sala de palacio. El objeto era que no fuese conocida por los padres la real orden hasta que llegase el momento de la sorpresa."}, {"type": "p", "text": "Pero averiguada cosa es —dice un escritor contemporáneo— que el mismo buque que condujo las comunicaciones para el virrey, traía también instrucciones privadas del Superior de los jesuitas en Madrid. Está envuelto en el misterio el medio que empleó para comunicar sus instrucciones al Superior de Lima, y por la misma nave, y no habiendo en ese día pisado tierra más persona que el comandante, quien ignoraba el contenido de la comunicación real."}, {"type": "p", "text": "Daban las doce de la noche cuando un alcalde de casa y corte, seguido de escribas, corchetes y demás familia menuda de la cohorte que se ocupa en justiciar, tocaban en la portería de San Pablo para cumplir la disposición del ministro de Carlos III, por la que en un mismo día fueron expulsados de las Indias los temidos discípulos de Loyola. El hermano portero recibió a la comitiva como quien esperaba la visita."}, {"type": "p", "text": "Y así era la verdad. El Superior había congregado desde las ocho de la ocho de la noche a los demás padres, hecho venir a cinco o seis que se hallaban ausentes del convento, y dádoles cuenta del pliego que recibió del Nazareno. Al llegar la comisión del virrey, todos los hermanos, sin faltar uno, estaban sentados en el espacioso y monumental salón del refectorio, con el breviario en la mano y un pequeño bulto de ropa a los pies."}, {"type": "p", "text": "Las instrucciones del conde de Aranda prevenían al virrey que la comunidad se reuniese al toque de campana, que se mantuviese a los padres en la sala capitular y que el Superior mandase buscar a los ausentes. Los comisionados nada tuvieron que hacer en tales puntos. Esto demuestra que también al Superior de Lima le había remitido el de la orden, en Madrid, copia de las prevenciones del ministro. La real orden fechada en el Pardo a 5 de abril de aquel año fue cumplida en todas sus partes. A la una de la madrugada marcharon los jesuitas al Callao, y a las cinco ponían la planta sobre la cubierta del navío de guerra San José Peruano, que por la tarde se perdió de vista en el horizonte, conduciendo a los que por ciento noventa y nueve años habían ejercido gran dominio en el virreinato."}, {"type": "p", "text": "Los jesuitas —dice Scribener— supieron tomar venganza de la traición practicada con ellos, burlando la avaricia. Por eso se cree que hay fabulosas riquezas enterradas en San Pedro, y hemos visto en nuestros días una sociedad que, con permiso del gobierno, se ocupó en hacer excavaciones para encontrar un tesoro que no había guardado y que puso el templo a riesgo de desplomarse sobre los fieles."}, {"type": "p", "text": "Es fama que también el Superior de las misiones del Paraguay, que se hallaba aquel día a cuarenta leguas de Salta, en una reducción de indios llamada Miraflores, tuvo aviso del golpe que iba a recibir la Compañía, cuatro horas antes de la designada, y que al intimársele el regio mandato contestó sonriendo:"}, {"type": "p", "text": "—Tomad las llaves, y ved que nos llevamos un tesoro en el breviario."}, {"type": "p", "text": "Mucho se ha repetido que la expulsión de los jesuitas fue para ellos una sorpresa. Algunos documentos históricos que hemos consultado, y los pormenores mismos sobre la manera como se cumplió la real cédula en Lima, nos están demostrando lo contrario."}, {"type": "p", "text": "Esa orden, tan tenazmente combatida, vuelve en pleno siglo XIX a pretender el dominio de la conciencia humana. Cadáver que como el fénix mitológico renace de sus cenizas, se presenta con nuevas y poderosas armas al combate. La lucha está empeñada. ¡Que Dios ayude a los buenos!"}]$lira$::jsonb, 938);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 16, 'VI (1/11)', $lira$[{"type": "p", "text": "Una mañana de noviembre del año 1774, al abrirse las puertas de la iglesia de la Merced, fueron invadidas sus naves por inmensa muchedumbre."}, {"type": "p", "text": "En el centro del templo, débilmente iluminado, y sobre un modesto catafalco, se veía una caja mortuoria rodeada de los indispensables blandones."}, {"type": "p", "text": "Indudablemente iba a celebrarse allí un oficio de difuntos, y el menos avisado podía conocer, por la pobreza de adorno y de luces, que no se trataba de un funeral como los que la vanidad humana consagra a los magnates. Tampoco era de pensar que el muerto fuese persona querida para el pueblo por sus virtudes o respetada por su talento; porque a serlo, algún signo de dolor se habría notado en los semblantes. Por el contrario, se diría que la multitud se hallaba convidada para una fiesta; y si el observador se acercaba a los grupos oiría sólo imprecaciones, en escala cada vez mayor, a la memoria del difunto."}, {"type": "p", "text": "—Es un escándalo que entierren a ese perro excomulgado en lugar santo —"}, {"type": "p", "text": "murmuraba una vieja, santiguándose con la punta de la correa que pendía de su hábito de beata."}, {"type": "p", "text": "—Calle usted, comadre— añadía un lego del convento, mozo de cara abotargada, con un costurón de más en el jeme y algunos dientes de menos—. Apuesto un rosario de quince misterios a que su patrón el demonio se ha robado ya de la caja el cuerpo de ese hereje."}, {"type": "p", "text": "—Doy fe y certifico que el dichoso capitán está ya achicharrado en el infierno— declaraba, con el estupendo aplomo de la gente de su oficio, un escribano de la Real Audiencia, sorbiendo entre palabra y palabra sendas narigadas del cucarachero. Pero estos murmullos aislados no justifican aún lo bastante el motivo que atraía al templo a la multitud; y para que el lector no se devane el cerebro por acertarlo, le diremos brevemente que, arruinado en su salud por los excesos de la vida caprichosa, y en su fortuna, que se creía inagotable, acababa de pasar al mundo de la verdad el capitán D. Diego de Arellano, disponiendo en su testamento que se vendiese el mezquino y gastado ajuar de su casa, repartiéndose el importe entre los pobres el día del entierro. Así, el que vivo no había dado limosna, era útil en su muerte a los mendigos."}, {"type": "p", "text": "Ítem más, mandaba el susodicho capitán que, al terminarse la función fúnebre y antes de ser su cuerpo conducido a la bóveda, leyese el sacerdote oficiante, en voz clara y sonora, un pliego que, cerrado y lacrado, se hallaba aquella mañana sobre el ataúd, y al que nadie osaba tocar, de miedo que despidiese algún calorcillo infernal. Queda explicado, pues, que la afluencia del pueblo no era por recibir escasa limosna, en mi entierro al que hasta las plañideras (mujeres cuyo oficio era llorar por aquellos a quienes habían conocido tanto como a la ballena de Jonás) se negaron a funcionar, sino por la curiosidad de saber el contenido del pliego."}, {"type": "p", "text": "La fúnebre ceremonia había ya terminado y se acercaba el momento con tanta ansiedad esperado. Un glacial silencio reinó en la iglesia, cuando el sacerdote tomó en sus manos el pliego y rompió el sello. En el papel sólo había dos líneas escritas. Pero apenas dio a ellas lectura el ministro de Jesucristo, cuando el pueblo todo, como impelido por un resorte, cayó de rodillas."}, {"type": "p", "text": "Al salir del templo, más de una lágrima no había sido aún enjugada y el dolor estaba pintado en todos los semblantes."}, {"type": "p", "text": "Aquellas lágrimas, hijas de corazones agradecidos, debieron llegar al trono del Altísimo, como una ofrenda purificadora para el alma de aquel que, desde su lecho de muerte, decía en el pliego que leyó el sacerdote:"}, {"type": "h", "text": "¡Rogad Por Mí! Yo He Sido El Nazareno."}, {"type": "p", "text": "Un litigio original"}, {"type": "p", "text": "Tradición en que el autor halaga pantorrillas o vanidades como candidato que anda a pesca devotos para calzarse una diputación al próximo congreso"}, {"type": "p", "text": "Entre el segundo marqués de Santiago D. Dionisio Pérez Manrique y Villagrán y el primer conde de Sierrabella D. Cristóbal Mesía y Valenzuela había, por los tiempos del virrey conde de la Monclova, una enemistad de mil demonios. El título del primero databa desde Felipe IV, y el del segundo desde Carlos el Hechizado; apenas treinta años de distancia entre la nobleza del uno y la del otro."}, {"type": "p", "text": "La guerra era, digámoslo así, de casa a casa; asunto de pergaminos más o menos amarillentos, y de un arminio, roel o dragante de más o de menos en el escudo de armas."}, {"type": "p", "text": "A no ser los jefes de ambas casas hombres que ya peinaban canas, de fijo que habría llegado la sangre al río. Por mucho menos ardió Troya."}, {"type": "p", "text": "Un día (que por más señas fue el 8 de septiembre de 1698) todo lo que Lima encerraba de aristocrático estaba congregado en la iglesia de San Agustín para oír el sermón panegírico que, con motivo de la fiesta de la Natividad de la Virgen, debía pronunciar uno de los frailes pico de oro que abundaban en ese convento, foco de hombres de gran saber y de portentosa elocuencia."}, {"type": "p", "text": "Terminada la función, el señor de Sierrabella subió a su carruaje, y queriendo de paso hacer una visita a la condesa de la Vega del Ren doña Josefa Zorrilla de la Gándara, dio al fámulo la orden correspondiente. Al doblar éste la esquina de Lártiga, se halló de sopetón con el carruaje del marqués de Santiago, también en actitud de torcer la bocacalle de Lescano."}, {"type": "p", "text": "Ambos cocheros detuvieron las bridas, y el del conde dijo al otro:"}, {"type": "p", "text": "—¡A la izquierda, negro bruto!"}, {"type": "p", "text": "—¡Déjame la derecha, negro chicharrón! —contestó el auriga del marqués."}, {"type": "p", "text": "Y los dos macuitos siguieron insultándose de lo lindo."}, {"type": "p", "text": "Los amos asomaron la cabeza por la portañuela y, al reconocerse, dijeron a sus esclavos:"}, {"type": "p", "text": "—No cedas, negro, porque te mato a latigazos."}, {"type": "p", "text": "Y siguió el escándalo, y cuantos nobles salían de la iglesia rodearon las portañuelas de los coches."}, {"type": "p", "text": "Allí estaba D. Juan de Mendoza e Híjar, segundo marqués de San Miguel, en cuyo escudo de gules lucían las barras de Aragón y los eslabones de Navarra; D. Alonso Pérez de los Ríos y Rivero, vizconde de San Donás, que era título de Flandes y no de Castilla; D. Luis Ibáñez de Segovia y Peralta, marqués de Corpa, que por Peralta tenía escudo de gules, cuartelado en cruz con un grifo de oro; D. Juan de Urdánegui, marqués de Villafuerte, con su escudo cortado, en oro y plata, con bordura de gules; D. Nicolás Dávalos de Rivera, conde de Santa Ana de las Torres, que por Dávalos ostentaba escudo partido, en gules y oro; don José Hurtado de Chávez, conde de Cartago, con las cinco llaves de azur, en campo de oro, blasón de los Chávez; D. Francisco León y Sotomayor, marqués de Celada de la Fuente, que traía león de gules, linguado y rapante, en campo de plata; D. Pedro Carrillo de Albornoz, conde de Montemar, con su escudo partido a mantel, castillo de oro, en gules, y banda de sinople, en oro; D. Jerónimo Velazco y Castañeda, marqués de Villablanca, cuyo escudo cortado tenía, en el primer cuartel, en plata, seis barras de azur, y en el segundo, cinco calderos de sable, en orla de plata. D. Luis Santa Cruz y Padilla, conde de Lurigancho, luciendo la espléndida divisa de los Santa Cruz: escudo tronchado, el primer cuartel en sinople, con castillo de oro y pendones de plata y gules; el segundo en azur, con castillo de plata y cruz llana de gules en el homenaje; en cuartel inferior, también en gules, tres cabezas de moros, y en orla de plata este mote Por el amor de la cruz se torre; D. Francisco Delgadillo y Sotomayor, marqués de la Puente, que por Delgadillo ostentaba siete estrellas de plata, en campo de azur, y ocho calderos de sable en bordura de oro; D. Juan Arias de Saavedra, marqués de Moscoso, que por Arias tenía escudo a mantel con dos cuarteles, en plata, con la cruz llana de Montesa en el primero y un águila, de sable, explayada en el segundo, y por Saavedra, escudo de plata con escaques o jaqueles de oro y gules, bordura de gules con ocho aspas de oro; y D. Francisco Remírez de Laredo, conde de San Javier, de quien, antes de proseguir, y por si no se me vuelve a presentar oportunidad de nombrarlo, quiero contar una agudeza."}]$lira$::jsonb, 1403);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 17, 'VI (2/11)', $lira$[{"type": "p", "text": "Parece que el Sr. Remírez de Laredo andaba algo retrechero para arreglar con sus hermanos unas cuentas testamentarias, y que estos le tenían, para exigírselas, más miedo que a un tigre, pues el señor conde era de un geniazo y de una soberbia como ya no se usan. Los Remírez de Laredo tenían una hermana, fea como una maldición, siempre desgreñada y sucia, tartamuda y tonta para colmo de desdicha. Esta, firmó una carta o memorial de cuatro pliegos, abundante en quejas y recriminaciones, a que contestó el mayorazgo con este billete que, al pie de la letra, copio de su original: Señora mía y hermana: El más ruin cochino rompió el chiquero.—Besa a V. las manos, si por casualidad se las ha lavado. —El conde de San Javier y Casa-Laredo. Volvamos a la cuestión de los coches."}, {"type": "p", "text": "Iban los caballeros, cuyos nombres he apuntado, y otros tantos que no estoy con humor para mencionar, de uno a otro lado, proponiendo partidos para allanar el conflicto; pero el asunto no admitía más soldadura que la de tomar uno de los contrincantes por la izquierda, y precisamente en eso estaba el quid."}, {"type": "p", "text": "—Yo no me muevo —decía el de Santiago, repantigándose en el asiento de terciopelo verde con rapacejos de oro, sacando la caja de rapé con orla de brillantes y sorbiendo con deleite una narigada del macabá legítimo."}, {"type": "p", "text": "—Aquí me planto —decía a su vez el de Sierrabella, encendiendo un riquísimo puro en el mechero de Guamanga con esmeraldas y rubíes."}, {"type": "p", "text": "Una hora llevaban ya de gresca y ambos revelaban firme propósito de mandar a su casa por la comida y aun de vivir en plena calle hasta la semana de los tres miércoles. Y habrían ido adelante con su terna si el vizcondesito de San Donás, que era mozo de salidas y expedientes oportunos, no les dijera:"}, {"type": "p", "text": "—Pero, señores, esto es una majadería, a la que conviene poner término. Quédense los coches como están, y vamos donde el virrey para que él decida el caso. Hubo de parecer a todos sesuda la idea; apeáronse los rivales, y el de Sierrabella, con la mitad del grupo, tomó por la calle de Lártiga para palacio, a la vez que el de Santiago, con sus amigos se dirigía al mismo punto por la calle de Lescano. En palacio se aumentó el cortejo con cuanto noble de apellido encerraba Lima. Sólo dejaran de presentarse los paralíticos o los que estaban con la extremaunción. Se trataba de materia en que a toda pantorrilla hidalga le iba por lo menos el color de la liga."}, {"type": "p", "text": "Acudieron los Aliaga, con su escudo de plata y una mata de aliaga florida en medio de dos osos; los La-Puente con su castillo de tres torres en campo de oro, puente de tres arcos defendida por dos leones de gules y la leyenda Por pasar la puente me pondré a la muerte; los Prieto con su escudo partido, el primero en azur con león de oro, y el segundo en oro con águila de gules; los Silva con su león de gules coronado y linguado en campo de plata; los Aguilar con su águila imperial de sable en campo de oro; los Aldana con sus tres coronas de oro y espada de plata en campo de sinople; los Rojas con sus cinco estrellas de azur en fondo de oro; los Varela con su escudo de gules cortado, seis barras de sinople en la parte superior, cuatro flores de lis de oro en la inferior, y cadena de oro con candado; los Vera con su águila coronada en campo de plata, y el mote Veritas vincit; los Pando con su espada de plata en campo de gules, teniendo un pan de oro en la punta y seis panecillos a cada lado; los Villamil con su cruz negra en campo de oro, y el lema Avante con la cruz delante; los Díaz con su corneta de oro en campo de azur; los Oliva con su lechuza en campo de plata; los González con su castillo de oro en gules; los Carvajal con su banda de sable en campo de oro; los Cárdenas con sus dos lobos pasantes en oro; los Novoa con su águila de oro, castillo de plata y león de gules; los Pereira con su escudo tronchado, cruz roja en plata, y las quinas de Portugal en azur; los Escalante con su león de plata en campo de gules y el mote Osar morir, dar la vida; los Álvarez con su lobo al pie de un tronco; los Elizalde (palabra que en vascuence significa cerca de la iglesia) con su león rapante en gules y tres fajas de azur en oro; los Fonseca con sus cinco luceros de gules en oro; los Gaviria (que quiero decir ahora es de noche) con su gavilán que lleva un gallo entre las garras; los Idiáquez con su toro de plata al pie de un árbol; los Salazar con sus trece estrellas de oro en campo de gules, armas dadas por D. Alfonso XI a Lope de Salazar en premio de haber muerto en desafío a un gigante moro que vestía marlota colorada con higas de oro; los Ramírez con su león linguado grimpante a una encina y barra de gules con dos dragantes en sinople; los Salinas con su castillo de plata en oro y dos leones de gules; los Carranza con su lobo de sable y castillo de plata en campo de sinople; los Román con su bastón de gules y cuatro flores de lis de azur en campo de oro; los Ibarrola con sus tres fajas de gules en campo de oro y el mote Ave María; los Goyeneche con su escudo ajedrezado de quince escaques de plata y quince de gules; los Zavala (palabra que en vascuence significa ancho) con sus tres fajas de gules fileteadas de oro en campo de azur; los Roca con su guijarro de oro en campo de azur; los Osma con su león de gules coronado en plata, dos espadas cruzadas y una flor de lis sobre gules; los Aramburú (que significa cabeza de ciruelo en vascuence) con su castillo de azur en campo de gules y losanges de oro y plata; los Roncal con la cabeza ensangrentada del rey Abderramen en campo de azur; los Iriarte (que en vasco significa hasta la ciudad) con su escudo cuartelado en cruz con las barras aragonesas, cadenas de Navarra, árbol y lobo pasante; los Oquendo con sus dos cabezas de dragones, torre, corona regia y la cifra OQ, todo en oro sobre azur y gules; los Aparicio con su estrella de oro, castillo de gules, cruz de Calatrava y león rojo; los Quiñones con sus quince escaques, ocho en gules y siete en plata; los Tudela con sus dos torres en sinople y seis bandas de azur en oro; los Nena con su lebrel atado a un árbol y dos dragantes sobre banda roja en campo de azur; los Gándara con su ninfa con espada desnuda y rodela a la puerta de un castillo; los Quiroga con su águila de oro en azur; los Caviedes con su castillo de plata en sinople; los Recalde con sus seis manzanas de oro en azur; los Cavero con sus dos campanas de plata en gules; los Bermúdez con sus jaqueles de oro y sable; los Arrese con su escudo de cuatro cuarteles con castillo, árbol, oso, lobos, luna y estrellas; los Coloma con sus dos garzas blancas en campo de oro; los Morote con sus tres estrellas de oro, espadas, torre, monte, río y cisne; los Osorio con sus dos lobos linguados en campo de oro; los Pastor con su torre de gules en plata coronada por una águila; los Domínguez con su estrella de oro de seis puntas en azur; los Figueroa con sus cinco hojas de higuera en oro; los Martínez con su paloma sobre un árbol y las quinas portuguesas; los Riquelme con su yelmo de plata en campo de gules; los Unzueta con sus tres lobos sobre oro y la leyenda Todos magnánimos en bordura de gules; los Zúñiga con su banda de sable en plata con la cadena de Navarra por orla; los Esparza con su sol de oro atravesado por una flecha en gules; los Molina con su rueda de molino en campo de azur; los Viana con su águila de sable en oro; los Mollinedo con sus diez y seis crucecitas de gules en campo de oro; los Oviedo con sus dos águilas en azur, sosteniendo un cáliz de oro y encima la cruz de Oviedo: los Sanz con las barras de Aragón en oro y medio vuelo de gules; los López con su estrella de oro, jinete en caballo blanco, león de gules y castillo de plata; los Cevallos con su leyenda Ardides de caballeros, Zeballos para vencellos; los Paredes con su laurel, castillo de plata y jabalí encadenado; los Jiménez con su escudo de cuatro cuarteles, dos en oro y dos en gules, con tres fajas de azur los primeros y tres espadas de plata los otros; los Bada con su cruz de Calatrava sobre oro; los Soria con su barra volteada en forma de N, dragantes y cuatro estrellas de oro en azur; los Escudero con su espada de plata en cuya hoja se lee Sine dolo; los Rebolledo con sus tres troncos de árbol sobre oro; los Guerrero con su banda de oro, con dragantes de sinople en gules, y por mote en letras de oro el de los Garcilaso de la Vega: Ave María gratia plena; los Vives con su mata de siemprevivas en campo de plata; los Zorrilla con su encina de sinople, dos lobos pasantes rojos en campo de plata y la leyenda Se ha de vivir de tal suerte, que vida quede en la muerte; los Mazo con la maza ensangrentada en azur; los Benites con sus dos lobos de sable, linguados y empinantes a una encina en campo de oro; los Villalva con su torre de plata en azur; los Sosa con su burelado de plata y gules; los Tovar con su banda de oro sobre azur engolada de dos dragantes; los Benavente con sus cinco leones en plata equipolados con cuatro castillos en gules; los García con su leyenda De García arriba nadie diga; los Andrade con su banda de oro sobre sinople engolada de dos grifos; los Angulo con sus cinco bezantes de sinople en sautor sobre campo de oro; los Romero con sus tres bastones de oro en gules; los Arteaga (voz que en vascuence significa rama de encina) con sus dos calderas jaqueladas de oro y sable y banda de oro con dragantes de sinople; los Acuña con sus nueve cuñas de azur sobre oro y cinco bezantes de plata en sautor; los Terán con sus dos estrellas de gules entre barras de azur y oro; los Oliver con su olivo de sinople en oro; los Arzola con sus tres áncoras en azur y torre de oro sobre sinople; los Vivero con sus cinco custodias y león coronado sobre un puente; los Valdivia con sus dos serpientes enroscadas y la leyenda La muerte menos temida da más vida; los Palacio, cuyas armas son dos doncellas bailando con dos mancebos, en campo de sinople; los Lucio con su gran estrella de oro sobre azur; los Pimentel con sus cinco conchas de plata en sinople; los Gayangos con sus cinco espadas de plata sobre sinople y oro; los Saravia con sus tres fajas ondeadas de oro y azur; los Rivas con su cruz de oro floreada de gules; los Mendiola con su árbol en sinople y dos lobos pasantes en oro; los Bolaños con su cordero engulléndose un bollo sobre sinople; los Basurto con sus cinco panelas de oro sobre gules; los Velarde en cuyo escudo partido a mantel hay una serpiente y un caballero que la atraviesa con su lanza, una doncella que presencia la escena y en orla de plata el mote Este es el Velarde que a la sierpe mató y con la infanta casó; los Pancorbo con sus cinco arminios de sable en sautor sobre campo de plata; los Ovalle con sus tres barras de azur y tres espadas en oro; los Iraola con sus trece corazones o panelas de plata y león de gules en campo de oro; los Freire con su banda de gules con dragantes de oro sobre sinople; los Villacorta con sus nuevo roeles de oro sobre azur; los Bejarano con sus cinco cabezas de sierpe de oro sobre plata; los Moya con su escala de oro en gules y veros de plata y azur; los Cámara con un corazón atravesado por una saeta sobre oro; los Urrutia (que en vasco significa lejano) con su cruz llana de sinople y cinco panelas de gules en sautor; los Chaparro con su castillo de plata sobre gules y una encina sobre oro; los Guerra, en cuyo escudo en oro había una bandera con este lema en plata: ¡A la guerra!; los Burguillos con una flecha de oro sobre gules; los Palomeque con sus palomas en azur y bordura de gules; los Arriola con sus tres panelas verdes en gules; los Menéndez con sus ocho rosas y tres bandas de azur en plata; los Navarrete con su campana de sinople en campo de plata; los Barrios con sus dos perros atigrados y dos castillos de oro sobre sinople; los Polo con sus siete estrellas de gules sobre oro y la divisa In motu lumine; los Zárate con sus cinco panelas de gules en sautor y una águila en campo de oro; los Ron, en cuyo escudo había un soldado tocando una trompeta a la puerta de un castillo; los Mora con su morera de sinople sobre plata; los Chamorro con sus dos lebreles atados a un árbol sobre oro; los Prada con sus cinco tizones encendidos en gules; los Oyarzabal (que significa cama ancha en vascuence) con su jabalí empinante a un árbol sobre oro; los Corvacho con su espada de plata sobre gules luciendo en la hoja este mote: A el valor y la lealtad; los Barrenechea (que en vasco significa casa de adentro) con su castillo de plata y dos leones grimpantes en gules; los Feliú con su cruz de Calatrava en oro; los Alcocer con sus tres fajas de azur sobre oro; los Sánchez con sus dos calderas de oro y torre con bandera blanca en el homenaje; los Colmenares con su escudo mantelado con nueve roeles de oro en sinople, cuatro bandas de sable en plata y cinco flores de lis en oro; los Cobián con su manojo de ortigas y cinco flores de lis en oro; los Irigoyen (en vascuence ciudad de arriba) con su apóstol San Juan sobre plata y tres torres de oro sobre gules; los Medina del Campo con sus trece roeles de plata en campo de azur y el mote Ni el Papa beneficio ni el rey oficio; los Egúsquiza (voz que significa debajo del sol) con su lobo pasante y cuatro barras de gules; los Retes con su cruz de Portugal sobre plata y la leyenda Para siempre jamás; los Dávila con sus seis bezantes de oro sobre azur; los Ríos con sus dos fajas de azur ondeadas sobre oro y cinco cabezas de serpiente en bordura de plata; los Villar con su ajedrez de diez cuadros de plata y diez de sinople; los Ariza con su ajedrez de diez cuadros de oro y diez de plata; los Aguirre con su leyenda Piérdase todo y sálvese la honra; los Echenique (palabra que en vascuence significa no tengo casa) con su escudo ajedrezado de plata y sable; los Mújica (durazno en vasco) con un oso de sable sobre plata; los Vivanco con su castillo de oro en campo de azur y la divisa Son las armas del vencido; los Sandoval con su banda de sinople sobre oro; los Cueto con sus diez flores de lis de oro en campo de azur; los Barca con su torre de plata sobre azur y la leyenda Por la fe moriré; los Barrantes con sus grifos engolados sobre gules; los Castelbravo con su muy historiado escudo, en el que se ve un artillero a la boca de un cañón y este mote: Si muero en la llama, viviré en la fama; los Cisneros con sus jaqueles de gules y oro y dos cisnes de plata con corona al cuello; los Vidaurre con su faja de azur sobre oro; los Vergara con su leyenda Según mis obras; los Núñez con sus cinco flores de lis sobre oro; los Orellana con sus diez roeles de azur sobre plata; los Arcilla con su pantera de oro sobre unos peñascos; los Centeno con sus cinco manojos de espigas sobre sinople; los Tejada con su castillo de oro con bandera blanca y en ella una cruz de gules sobre sinople; los Mansilla con su escudo de cuatro cuarteles, luciendo en el principal un cacique con cadena al pescuezo; los Menacho con su cáliz de oro sobre gules y el mote Nosotros lo llevamos porque lo ganamos; los Rubio con su árbol sobre el cual hay una corona; los Rotalde con su escudo verado de plata y sable; los Ferreira con sus seis menguantes de plata sobre azur; los Ibáñez con su ballesta de plata sobre azur; los Padilla con tres palas de horno sobre azur; los Jimeno con tres lobos en sautor sobre plata; los Garcés con su divisa Creedlo, que de infante viene; los Odriozola con sus torres de plata sobre sinople y dos árboles sobre plata; los Sarmiento con trece roeles de oro sobre gules; los Gómez con sus tres fajas de sable sobre plata; los Agüero con su león llevando una bandera; los Vázquez con sus seis roeles de azur sobre oro; los Alfaro con su menguante de plata sobre azur; los Ugarte con un jabalí sobre oro; los Somonte con seis luneles de gules sobre oro; los Anduaga con su grifo rapante de gules; los Ruiz con su encina de bellotas de oro; los Fajardo con sus tres ortigas de siete hojas sobre oro; los Valladares con ochenta jaqueles de oro y gules; los Valenzuela con su león de sable coronado sobre plata; los Villegas con su cruz de sable sobre plata y ocho calderas; los Meneses con su cadena de azur en banda sobre oro; los Muñoz con su cruz de Calatrava sobre oro; los Segura con sus cuatro trébedes en las aspas de una cruz de gules sobre oro; los Bahamonde con su M de oro coronada sobre azur; los Herrera con sus calderas de oro sobre gules; los Godoy con sus ocho escaques de azur y otros ocho de oro; los Cabrera con una cabra montaraz sobre plata; los Roldán con su corneta de plata sobre sable y catorce estrellas de plata en bordura de azur; los Arrieta con su faja ancha de oro sobre gules; los Beltrán con su escudo cuartelado en sinople con águila explayada, estrellas de plata, jabalíes y lanzas; los Camacho con su banda y barras de gules sobre oro; los Gil con sus tres escudetes de oro bordados de azur en campo de sinople; los Carrión con su escudo cortado en el que se ve un león de oro y un yelmo de azur; los Galdeano con su media luna jaquelada de oro, plata y sable sobre gules; los Lazarte con sus tres lobos pasantes de plata sobre sinople y tres céspedes sobre oro; los Sosa con sus seis lagartos sobre oro; los Loyola con su enredado escudo de cuatro cuarteles tal como se ve en las estampas de San Ignacio, y... basta ¡por Dios!, que sería fatiga seguir enumerando apellidos de la gente hidalga de mi tierra o el cuento de las cabras de Sancho. Por lo menos dejo cien más en el fondo del tintero. Consuélese con saberlo todo el que no ha sido mencionado en esta pantorrillesca nomenclatura; y si hay alguno que crea que lo haya omitido por malicia o envidia, reclame con confianza y figurará en otra edición. Aunque me humille confesarme plebeyo debo declarar, a fuer de veraz cronista, que allí no hubo ningún Palma; pues si alguno de este apellido comía por aquel siglo pan en Lima, debió estar aquejado de dolor do muelas o de punzada en el hueso palomo. Con su inasistencia me hizo un flaco servicio, porque me privó de conocer mis armas para lucirlas sobre el papel de cartas."}]$lira$::jsonb, 3426);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 18, 'VI (3/11)', $lira$[{"type": "p", "text": "El virrey, que tenía grandes vínculos con ambos querellantes, se vio, como dicen, entre la espada y la pared. Los dos defendían con igual copia de argumentos, lo que llamaban su perfecto derecho. El uno decía que en su escudo, puesto a mantel, había un león linguado y rapante en campo de plata, con cinco grifos de sinople sobre oro y dos castillos almenados sobre azur. El otro contestaba con un águila de sable y coronada en campo de gules, cuatro grifos y tres torres. Argüía el uno que el león no podía bajar la melena ante el águila, y replicaba el otro que quien cruzaba por los aires sin rival, no debía humillarse en la tierra. En suma, a oírlos no sabía uno decidir cuál de los dos era de nobleza más limpia y acuartelada; pues al que le faltaba un grifo le sobraba un castillo, y váyase lo uno por lo otro. El de Santiago decía que un marqués era más que un conde; pues la palabra marqués en casi todas las lenguas conocidas (y esta es una curiosa observación de los filólogos) significa vigilante o custodio de las fronteras, límites o marcas del territorio. El de Sierrabella contestaba que el título de conde viene del comes latino, que quiere decir compañero, y por ello todo conde era un compañero del príncipe y guardián obligado de su persona."}, {"type": "p", "text": "¿A que no aciertan ustedes con la decisión del virrey? La doy en una, en dos, en tres, en mil. Ya veo que se dan ustedes por vencidos; porque ni a Salomón, que imaginó hacer dos rebanadas de un muchacho, se le habría ocurrido lo que al muy Excmo. Sr. D. Melchor Portocarrero Lazo de la Vega, conde de la Monclova."}, {"type": "p", "text": "—Señores —dijo—, no me tengo por bastante instruido en la ciencia del blasón que, como ustedes saben, es la ciencia heroica, la ciencia de las ciencias, ni creo que en estos reinos del Perú haya voto facultativo. El punto es de lo más intrincado que cabe, y con más habilidad me sospecho para convertir en oro una piedra de cantería, que para dar sentencia acertada en el presente litigio. Aquí no hay más sino ocurrir a su majestad. Entretanto, vuelvan los caballos a la caballeriza y quédense los coches donde están y sin variar de posición, hasta que venga de España la solución del problema."}, {"type": "p", "text": "El conde de la Monclova era hombre de gran talento y conocía ese rinconcito del alma humana donde se alberga la vanidad. Digo, así me parece a mí, y perdón si me equivoco."}, {"type": "p", "text": "Los interesados acreditaron en la corte representantes letrados y reyes de armas que tuvieran la heráldica en la punta de los dedos y se gastaron un dineral en el proceso. Por supuesto que cuando, al cabo de un par de años, llegó a Lima el fallo del monarca, fallo que el vencedor celebró con un espléndido banquete, no existía ya ni un clavo de los coches; porque estando los vehículos tanto tiempo en la vía pública y a la intemperie, no hubo transeúnte que no se creyera autorizado para llevarse siquiera una rueda."}, {"type": "p", "text": "Ahora estoy segurísimo de que en los labios de todos mis lectores retoza esta pregunta: «¡Y bien, señor tradicionalista! ¿Quién ganó el pleito? ¿El de Santiago o el de Sierrabella?»."}, {"type": "p", "text": "—Averígüelo Vargas. (Y a propósito. Este Vargas debió haber sido un gran husmeador de vidas ajenas, pues siempre anda metido en chismes y averiguaciones)."}, {"type": "p", "text": "Yo lo sé; pero es el caso que no quiero decirlo. Amigos tengo en ambos bandos, y no estoy de humor para indisponerme con nadie por satisfacer curiosidades"}, {"type": "p", "text": "impertinentes."}, {"type": "p", "text": "Conque lo dicho. Averígüelo Vargas."}, {"type": "p", "text": "La casa de Pilatos"}, {"type": "p", "text": "Frente a la capilla de la Virgen del Milagro hay una casa de especial arquitectura, casa sui géneris y que no ofrece punto de semejanza con ninguna otra de las de Lima. Sin embargo de ser anchuroso su patio, la casa es húmeda y exhala húmedo vapor. Tiene un no sé qué de claustro, de castillo feudal y de casa de ayuntamiento."}, {"type": "p", "text": "Que la casa fue de un conquistador, compañero de Pizarro, lo prueba el hecho de estar la escalera colocada frente a la puerta de la calle; pues tal era una de las prerrogativas acordadas a los conquistadores. Hoy no llegan a diez las casas que conservan la escalera fronteriza."}, {"type": "p", "text": "El extranjero que pasa por la calle del Milagro se detiene involuntariamente en su puerta y lanza al interior mirada escudriñadora. Y lo particular es que a los limeños nos sucede lo mismo. Es una casa que habla a la fantasía. Ni el Padre Santo de Roma le hará creer a un limeño que esa casa no ha sido teatro de misteriosas leyendas. Y luego, la casa misteriosa fue conocida, desde hace tres o cuatro generaciones, con nombre a propósito para que la imaginación se eche retozar. Nuestros abuelos y nuestros padres la llamaron la casa de Pilatos, y así la llamamos nosotros y la llaman nuestros hijos. ¿Por qué? ¿Acaso Poncio Pilatos fue propietario en el Perú? Entre mis manos y bajo mis espejuelos he tenido los títulos que el actual dueño, compadeciendo acaso mi manía de embelesarme con antiguallas, tuvo la amabilidad de permitirme examinar; y de ellos no aparece que el pretor de Jerusalén hubiera tenido arte ni parte en la fábrica del edificio, cuya área mide cuarenta varas castellanas de frente por sesenta y ocho de fondo."}, {"type": "p", "text": "Y sin embargo, la casa se llama de Pilatos. ¿Por qué?"}, {"type": "p", "text": "Voy a satisfacer la curiosidad del extranjero, contando lo mismo que las viejas cuentan y nada más. Se pela la frente el lector limeño que piense que sobre la casa de Pilatos voy a decirle algo que él no se tenga sabido."}, {"type": "p", "text": "La casa se fabricó en 1590, esto es, medio siglo después de la fundación de Lima y cuando los jesuitas acababan de tomar cédula de vecindad en esta tierra de cucaña. Fue el padre Ruiz del Portillo, Superior de ellos, quién delineó el plano; pues ligábalo estrecha amistad con un rico mercader español apellidado Esquivel, propietario del terreno."}, {"type": "p", "text": "Con maderas y ladrillos sobrantes de la fábrica de San Francisco y que Esquivel compró a ínfimo precio, se encargó el mismo arquitecto que edificaba el colegio máximo de San Pablo de construir la casa misteriosa, edificio sólido y a prueba de temblores, que no pocos ha resistido sin experimentar desperfecto."}]$lira$::jsonb, 1068);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 19, 'VI (4/11)', $lira$[{"type": "p", "text": "Por medio de una ancha galería, sótano o bóveda subterránea, de seis cuadras de longitud, está la fábrica en comunicación con el convento de San Pedro que habitaron los jesuitas."}, {"type": "p", "text": "Ese subterráneo que, previo permiso del actual propietario de la casa, puede visitar el curioso que de mis afirmaciones dude, les vendrá de perilla a los futuros escritores de novelas patibularias. En el sótano pueden hacer funcionar holgadamente"}, {"type": "p", "text": "contrabandistas, y conspiradores, y monederos falsos, y caballeros aherrojados, y doncellas tiranizadas, y todo el arsenal romántico romancesco. ¡Cuando yo digo que la casa de Pilatos está llamada a dar en el porvenir mucha tela que cortar! ¿Para qué se hizo este subterráneo? Ni lo sé ni me interesa saberlo."}, {"type": "p", "text": "La casa hasta 1635 sirvió de posada y lonja a mineros y comerciantes portugueses. Treinta y siete mil pesos de a ocho había invertido Esquivel en la fábrica, y los arrendamientos le producían un interés más que decente del capital empleado. Época hubo también en que, hallándose la plaza del mercado situada en San Francisco, fue el patio de la casa de Pilatos ocupado por los vendedores de fruta."}, {"type": "p", "text": "Heredó la casa doña María de Esquivel y Járava, esposa de un general español; y muerta ella, la Inquisición, que por censos tenía un crédito de ochocientos pesos, y otros acreedores, formaron concurso. Duró tres años la tramitación del expediente, y en 1694 se decretó el remate de la finca para satisfacer acreencias que subían a doce mil pesos."}, {"type": "p", "text": "D. Diego de Esquivel y Járava, natural del Cuzco, caballero de Santiago y que en 1687 obtuvo título de marqués de San Lorenzo de Valleumbroso, no quiso consentir en que la casa de su tía abuela pasara a familia extraña; y después de pagar acreedores, dio a los herederos veintiocho mil pesos."}, {"type": "p", "text": "Después de la Independencia cesó la casa de formar parte del mayorazgo de Valleumbroso y pasó a otros propietarios, circunstancia muy natural y sin importancia para nosotros."}, {"type": "p", "text": "Olvidaba apuntar que en tiempo del virrey Amat, a propósito de la expulsión de los jesuitas, se dijo que del sótano de la casa se había sacado un tesoro. No afirmo, consigno el rumor."}, {"type": "p", "text": "Pero a todo esto, ¿por qué se llama esa la casa de Pilatos? No digas, lector, que se me ha ido el santo al cielo. Ten paciencia, que allá vamos."}, {"type": "p", "text": "Cuenta el pueblo que por agosto de 1635 y cuando la casa estaba arrendada a mineros y comerciantes portugueses, pasó por ella, un viernes a media noche, cierto mozo truhán que llevaba alcoholizados los aposentos de la cabeza. El portero habría probablemente olvidado echar cerrojo, pues el postigo de la puerta estaba entornado. Vio el borrachín luces en los altos, sintió algún ruido o murmullo de gente, y confiando hallar allí jarana y moscorrofio, atreviose a subir la escalera de piedra, que es, dicho sea de paso, otra de las curiosidades que el edificio ofrece."}, {"type": "p", "text": "El intruso adelantó por los corredores hasta llegar a una ventana, tras cuya celosía se colocó, y pudo a sus anchas examinar un espacioso salón profusamente iluminado y cuyas paredes estaban cubiertas por tapices de género negro."}, {"type": "p", "text": "Bajo un dosel vio sentado a uno de los hombres más acaudalados de la ciudad, el portugués D. Manuel Bautista Pérez, y hasta cien compatriotas de éste en escaños, escuchando con reverente silencio el discurso que les dirigía Pérez y cuyos conceptos no alcanzaba a percibir con claridad el espía."}, {"type": "p", "text": "Frente al dosel y entre blandones de cera había un hermoso crucifijo de tamaño natural."}, {"type": "p", "text": "Cuando terminó de hablar Pérez, todos los circunstantes menos éste fueron por riguroso turno levantándose del asiento, avanzaron hacia el Cristo y descargaron sobre él un fuerte ramalazo."}, {"type": "p", "text": "Pérez, como Pilatos, autorizaba con su impasible presencia el escarnecedor castigo. El espía no quiso ver más profanaciones, escapó como pudo y fue con el chisme a la Inquisición, que pocas horas después echó la zarpa encima a más de cien judíos portugueses."}, {"type": "p", "text": "Al judío Manuel Bautista Pérez le pusieron los católicos limeños el apodo de Pilatos, y la casa quedó bautizada con el nombre de casa de Pilatos."}, {"type": "p", "text": "Tal es la leyenda que el pueblo cuenta. Ahora veamos lo que dicen los documentos históricos."}, {"type": "p", "text": "En la Biblioteca de Lima existe original el proceso de los portugueses, y de él sólo aparece que en la calle del Milagro existió la sinagoga de los judíos, cuyo rabino o capitán grande (como dice el fiscal del Santo Oficio) era Manuel Bautista Pérez. El fiscal habla de profanación de imágenes; pero ninguna minuciosidad refiere en armonía con la popular conseja."}, {"type": "p", "text": "El juicio duró tres años. Quien pormenores quiera, búsquelos en mis Anales de la Inquisición de Lima."}, {"type": "p", "text": "Pérez y diez de sus correligionarios fueron quemados en el auto de fe de 1639, y penitenciados cincuenta portugueses más, gente toda de gran fortuna. Parece que al portugués pobre no le era lícito ni ser judío, o que la Inquisición no daba importancia a descamisados."}, {"type": "p", "text": "Y no sé más sobre Pilatos ni sobre su casa."}, {"type": "p", "text": "¡Pues bonita soy yo, la Castellanos!"}, {"type": "p", "text": "(A Simón y Juan Vicente Camacho)"}, {"type": "p", "text": "Mariquita Castellanos era todo lo que se llama una real moza, bocado de arzobispo y golosina de oidor. Era como para cantarla esta copla popular:"}, {"type": "p", "text": "«Si yo me viera contigo,"}, {"type": "p", "text": "la llave a la puerta echada,"}, {"type": "p", "text": "y el herrero se muriera,"}, {"type": "p", "text": "y la llave se quebrara...»."}, {"type": "p", "text": "¿No la conociste, lector?"}, {"type": "p", "text": "Yo tampoco; pero a un viejo, que alcanzó los buenos tiempos del virrey Amat, se me pasaban las horas muertas oyéndole referir historias de la Marujita, y él me contó la del refrán que sirve de título a este artículo."}, {"type": "p", "text": "Mica Villegas era una actriz del teatro de Lima, quebradero de cabeza del excelentísimo señor virrey de estos reinos del Perú por S. M. Carlos III, y a quien su esclarecido amante, que no podía sentar plaza de académico por su corrección en eso de pronunciar la lengua de Castilla, apostrofaba en los ratos de enojo, frecuentes entre los que bien se quieren, llamándola Perricholi. La Perricholi, de quien pluma mejor cortada que la de este humilde servidor de ustedes ha escrito la biografía, era hembra de escasísima belleza. Parece que el señor virrey no fue hombre de paladar muy delicado."}, {"type": "p", "text": "María Castellanos, como he tenido el gusto de decirlo, era la más linda morenita limeña que ha calzado zapaticos de cuatro puntos y medio."}, {"type": "p", "text": "«Como una y una son dos,"}]$lira$::jsonb, 1067);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 20, 'VI (5/11)', $lira$[{"type": "p", "text": "por las morenas me muero:"}, {"type": "p", "text": "lo blanco, lo hizo un platero;"}, {"type": "p", "text": "lo moreno, lo hizo Dios»."}, {"type": "p", "text": "Tal rezaba una copla popular de aquel tiempo, y a fe que debió ser Marujilla la musa que inspiró al poeta. Decíame, relamiéndose, aquel súbdito de Amat que hasta el sol se quedaba bizco y la luna boquiabierta cuando esa muchacha, puesta de veinticinco alfileres, salía a dar un verde por los portales."}, {"type": "p", "text": "Pero así como la Villegas traía al retortero nada menos que al virrey, la Castellanos tenía prendido a sus enaguas al empingorotado conde de ***, viejo millonario, y que, a pesar de sus lacras y diciembres, conservaba afición por la fruta del paraíso. Si el virrey hacía locuras por la una, el conde no le iba en zaga por la otra. La Villegas quiso humillar a las damas de la aristocracia, ostentando sus equívocos hechizos en un carruaje y en el paseo público. La nobleza toda se escandalizó y arremolinó contra el virrey. Pero la cómica, que había satisfecho ya su vanidad y capricho, obsequió el carruaje a la parroquia de San Lázaro para que en él saliese el párroco conduciendo el Viático. Y téngase presente que, por entonces, un carruaje costaba un ojo de la cara, y el de la Perricholi fue el más espléndido entre los que lucieron en la Alameda."}, {"type": "p", "text": "La Castellanos no podía conformarse con que su rival metiese tanto ruido en el mundo limeño con motivo del paseo en carruaje."}, {"type": "p", "text": "—¡No! Pues como a mí se me encaje entre ceja y ceja, he de confundir el orgullo de esa pindonga. Pues mi querido no es ningún mayorazgo de perro y escopeta, ni aprendió a robar como Amat de su mayordomo, y lo que gasta es suyo y muy suyo, sin que tenga que dar cuenta al rey de dónde salen esas misas. ¡Venirme a mí con orgullitos y fantasías, como si no fuera mejor que ella, la muy cómica! ¡Miren el charquito de agua que quiere ser brazo de río! ¡Pues bonita soy yo, la Castellanos! Y va de digresión. Los maldicientes decían en Lima que, durante los primeros años de su gobierno, el excelentísimo señor virrey don Manuel de Amat y Juniet, caballero del hábito de Santiago y condecorado con un cementerio de cruces, había sido un dechado de moralidad y honradez administrativas. Pero llegó un día en que cedió a la tentación de hacerse rico, merced a una casualidad que le hizo descubrir que la provisión de corregimientos era una mina más poderosa y boyante que las de Pasco y Potosí. Véase cómo se realizó tan portentoso descubrimiento."}, {"type": "p", "text": "Acostumbraba Amat levantarse con el alba (que, como dice un escritor amigo mío, el madrugar es cualidad de buenos gobernantes), y envuelto en una zamarra de paño burdo descendía al jardín de palacio, y se entretenía hasta las ocho de la mañana en cultivarlo. Un pretendiente al corregimiento de Saña o Jauja, los más importantes del virreinato, abordó al virrey en el jardín, confundiéndolo con su mayordomo, y le ofreció algunos centenares de peluconas por que emplease su influjo todo con su excelencia a fin de conseguir que él se calzase la codiciada prebenda."}, {"type": "p", "text": "—¡Por vida de Santa Cebollina, virgen y mártir, abogada de los callos! ¿Esas teníamos, señor mayordomo? —dijo para sus adentros el virrey; y desde ese día se dio tan buenas trazas para hacer su agosto sin necesidad de acólito, que en breve logró contar con fuertes sumas para complacer en sus dispendiosos caprichos a la Perricholi, que, dicho sea de paso, era lo que se entiende por manirrota y botarate."}, {"type": "p", "text": "Volvamos a la Castellanos. Era moda que toda mujer que algo valía tuviese predilección por un faldero. El de Marujita era un animalito muy mono, un verdadero dije. Llegó a la sazón la fiesta del Rosario, y asistió a ella la querida del conde muy pobremente vestida y llevando tras sí una criada que conducía en brazos al chuchito. Ello dirás, lector, que nada tenía de maravilloso; pero es el caso que el faldero traía un collarín de oro macizo con brillantes como garbanzos."}, {"type": "p", "text": "Mucho dio que hablar durante la procesión la extravagancia de exhibir un perro que llevaba sobre sí tesoro tal; pero el asombro subió de punto cuando, terminada la procesión, se supo que Cupido con todos sus valiosos adornos había sido obsequiado por su ama a uno de los hospitales de la ciudad, que por falta de rentas estaba poco menos que al cerrarse."}, {"type": "p", "text": "La Mariquita ganó desde ese instante, en las simpatías del pueblo y de la aristocracia, todo lo que había perdido su orgullosa rival Mica Villegas; y es fama que siempre que la hablaban de este suceso, decía con énfasis, aludiendo a que ninguna otra mujer de su estofa la excedería en arrogancia y lujo: «¡Pues no faltaba más! ¡Bonita soy yo, la Castellanos!»."}, {"type": "p", "text": "Y tanto dio en repetir el estribillo, que se convirtió en refrán popular, y como tal ha llegado hasta la generación presente."}, {"type": "p", "text": "Justos y pecadores"}, {"type": "p", "text": "De cómo el lobo visitó la piel del cordero"}, {"type": "p", "text": "(A don José María Torres Caicedo)"}, {"type": "p", "text": "I. Cuchilladas Allá por los buenos tiempos en que gobernaba estos reinos del Perú el Excmo. Sr. D. Gaspar de Zúñiga y Acevedo, conde de Monterrey, arremolinábase a la caída de una tarde de junio del año de gracia 1605, gran copia de curiosos a la puerta de una tienda con humos de bodegón situada en la calle de Guitarreros, que hoy se conoce con el nombre de Jesús Nazareno, calle en la cual existió la casa de Pizarro. Sobre su fachada, a la que daba sombra el piso de un balcón, leíase en un cuadro de madera y en deformes caracteres:"}, {"type": "h", "text": "Ibirijuitanga Barbería Y Bodegón"}, {"type": "p", "text": "Algo de notable debía pasar en lo interior de aquel antro, pues entre la apiñada muchedumbre podía el ojo menos avizor descubrir gente de justicia, vulgo corchetes, armados de sendas varas, capas cortas y espadines de corvo gavilán."}, {"type": "p", "text": "—¡Por el rey! ¡Ténganse a la justicia de su majestad! —gritaba un golilla de fisonomía de escuerzo y aire mandria y bellaco si los hubo."}, {"type": "p", "text": "Y entretanto menudeaban votos y juramentos, rodaban por el suelo desvencijadas sillas y botellas escuetas, repartíanse cachetes como en el rosario de la aurora, y los alguaciles no hacían baza en la pendencia, porque a fuer de prudentes huían de que les tocasen el bulto. De seguro que ellos no habrían puesto fin al desbarajuste sin el apoyo de un joven y bizarro oficial que cruzó de pronto por en medio de la turba, desnudó la tizona, que era de fina hoja de Toledo, y arremetió a cintarazos con los alborotadores, dando tajos a roso y velloso; a este quiero, a este no quiero; ora de punta, ora de revés. Cobraron ánimo los alguaciles, y en breve espacio y atados codo con codo condujeron a los truhanes a la cárcel de la Pescadería, sitio adonde en nuestros democráticos días, y en amor y compaña con bandidos, suelen pasar muy buenos ratos liberales y conservadores, rojos y ultramontanos. ¡Ténganos Dios de su santa mano y sálvenos de ser moradores de ese zaquizamí!"}]$lira$::jsonb, 1188);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 21, 'VI (6/11)', $lira$[{"type": "p", "text": "Era el caso que cuatro tunantes de atravesada catadura, después de apurar sendos cacharros de lo tinto hasta dejar al diablo en seco, se negaban a pagar el gasto, alegando que era vitriolo lo que habían bebido, y que el tacaño tabernero los había pretendido envenenar."}, {"type": "p", "text": "Era éste un hombrecillo de escasa talla, un tanto obeso y de tez bronceada, oriundo del Brasil y conocido sólo por el apodo de Ibirijuitanga. En su cara abotagada relucían dos ojitos más pequeños que la generosidad de un avaro, y las chismosas vecinas cuchicheaban que sabía componer hierbas; lo que más de una vez le puso en relaciones con el Santo Oficio, que no se andaba en chiquitas tratándose de hechiceros, con gran daño de la taberna y de los parroquianos de su navaja, que lo preferían a cualquier otro. Y es que el maldito, si bien no tenía la trastienda de Salomón, tampoco pecaba de tozudo, y relataba al dedillo los chichisbeos de las tres veces coronada ciudad de los Reyes, con notable contentamiento de su curioso auditorio. Ainda mais, mientras él jabonaba la barba, solía alcanzarle limpias y finas toallas de lienzo flamenco su sobrina Transverberación, garrida joven de diez y ocho eneros, zalamera, de bonita estampa y recia de cuadriles. Era, según la expresión de su compatriota y tío, una linda menina, y si el cantor de Los Lusiadas, el desgraciado amante de Catalina de Ataide, hubiera, antes de perder la vista, colocado su barba bajo las ligeras manos y diestra navaja de Ibirijuitanga, de fijo que la menor galantería que habría dirigido a Transverberación habría sido llamarla:"}, {"type": "p", "text": "Rosa de amor, rosa purpúrea y bella."}, {"type": "p", "text": "Y ¡por el gallo de la Pasión! que el bueno de Luis de Camoens no habría sido lisonjero, sino justo apreciador de la hermosura."}, {"type": "p", "text": "No embargante que los casquilucios parroquianos de su tío la echaban flores y piropos, y la juraban y perjuraban que se morían por sus pedazos, la niña, que era bien doctrinada, no los animó con sus palabras a proseguir el galanteo. Cierto es que no faltó atrevido, fruta abundante en la viña del Señor, que se avanzase a querer tomar la medida de la cenceña cintura de la joven; por ella, mordiéndose con ira los bezos, levantaba una mano mona y redondica, y santiguaba con ella al insolente, diciéndole:"}, {"type": "p", "text": "—Téngase vuesa merced, que no me guarda mi tío para plato de nobles pitofleros. Ello es que toda la parroquia convino al fin en que la muchacha era linda como un relicario y fresca como un sorbete, pero más cerril e inexpugnable que fiera montaraz. Dejaron, por ende, de requerirla de amores y se resignaron con la charla sempiterna y entretenida del barbero."}, {"type": "p", "text": "¡Pero es un demonio esto de apasionarse a la hora menos pensada! Puede la mujer ser todo lo quisquillosa que quiera y creer que su corazón está libre de dar posada a un huésped. Viene una día en que la mujer tropieza por esas calles, alza la vista y se encuentra con un hombre de sedoso bigote, ojos negros, talante marcial..., y ¡échele usted un galgo a todos los propósitos de conservar el alma independiente! La electricidad de la simpatía ha dado un golpe en el pericardio del corazón. ¿A qué puerta tocan que no contesten quién es?"}, {"type": "p", "text": "«Es el amor un bicho"}, {"type": "p", "text": "que, cuando pica,"}, {"type": "p", "text": "no se encuentra remedio"}, {"type": "p", "text": "ni en la botica»."}, {"type": "p", "text": "Razón sobrada tuvo don Alfonso el Sabio para decir que si este mundo no estaba mal hecho, por lo menos lo parecía. Si él hubiera corrido con esos bártulos, como hay Dios que nos quedamos sin simpatía, y por consiguiente sin amor y otras pejigueras. Entonces hombres y mujeres habríamos vivido asegurados de incendios. Repito que es mucho cuento esto de la simpatía, y mucho que dijo bien el que dijo:"}, {"type": "p", "text": "«El amor y la naranja"}, {"type": "p", "text": "se parecen infinito:"}, {"type": "p", "text": "pues por muy dulces que sean"}, {"type": "p", "text": "tienen de agrio su poquito»."}, {"type": "p", "text": "Transverberación sucumbió a la postre, y empezó a mirar con ojos tiernos al capitán don Martín de Salazar, que no era otro el que en el día que empieza nuestro relato prestó tan oportuno auxilio al tabernero. Terminada la pendencia, cruzáronse entre ella y el galán algunas palabras en voz baja, que así podían ser manifestaciones de gratitud como indicación de una cita; y aunque no pararon mientes en ellas los agrupados curiosos, no sucedió lo mismo con un embozado que se hallaba en la puerta de la tienda y que murmuró:"}, {"type": "p", "text": "—¡Por el siglo de mi abuela! ¡Lléveme el diablo si ese malandrín de capitán no anda en regodeos con la muchacha y si no es por ella su resistencia a devolver la honra a mi hermana!"}, {"type": "p", "text": "II. Doña Engracia en Toledo"}, {"type": "p", "text": "En un salón de gótico mueblaje está una dama reclinada sobre un mullido diván. A su lado y en una otomana se halla un joven leyéndola en voz alta y en un infolio forrado en pergamino la vida del santo del día. ¡Benditos tiempos en los que, más que el sentimiento, la rutina religiosa hacía gran parte del gasto de la existencia de los españoles!"}, {"type": "p", "text": "Pero la dama no atiende a los milagros que cuenta el Año Cristiano, y toda su atención está fija en el minutero de un reloj de péndola, colgado en un extremo del salón. No hay más impaciente que la mujer que espera a un galán."}, {"type": "p", "text": "Doña Engracia de Toledo, que ya es tiempo de que saquemos su nombre a relucir, es una andaluza que frisa en los veinticuatro años, y su hermosura es realzada por ese aire de distinción que imprimen siempre la educación y la riqueza. Había venido a América con su hermano D. Juan de Toledo, acaudalado propietario de Sevilla, que ejercía en Lima el cargo de proveedor de la real armada. Doña Engracia pasaba sus horas en medio del lujo y el ocio, y no faltaron damas que sintiéndose humilladas se echaron a averiguar el abolengo de la orgullosa rival, y descubrieron que tenía sangre alpujarreña, que sus ascendientes eran moros conversos que alguno de ellos había vestido el sambenito de relapso. Para esto de sacar los trapitos a la colada las mujeres han sido y serán siempre lo mismo, y lo que ellas no sacan en limpio no lo hará Satanás con todo su poder de ángel precito. Rugíase también que doña Engracia estaba apalabrada para casarse con el capitán D. Martín de Salazar; mas como el enlace tardaba en realizarse, circularon rumores desfavorables para la honra y virtud de la altiva dama."}]$lira$::jsonb, 1090);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 22, 'VI (7/11)', $lira$[{"type": "p", "text": "Nosotros, que estamos bien informados y sabemos a qué atenernos, podemos decir en confianza al lector que la murmuración no era infundada. D. Martín, que era un trueno deshecho, una calavera de gran tono y que caminaba por senda más torcida que cuerno de cabra, se había sentido un tiempo cautivado por la belleza de doña Engracia, cuyo trato dio en frecuentar, acabando por reiterarla mil juramentos de amor. La joven, que tenía su alma en su almario, y que a la verdad no era de calicanto, terminó por sucumbir a los halagos del libertino, abriéndole una noche la puerta de su alcoba."}, {"type": "p", "text": "Decidido estaba el capitán a tomarla por esposa, y pidió su mano a don Juan, el que se la otorgó de buen grado, poniendo el plazo de seis meses, tiempo que juzgó preciso para arreglar su hacienda y redondear la dote de su hermana. Pero el diablo, que en todo mete la cola, hizo que en este espacio el de Salazar conociese a la sobrina de maese Ibirijuitanga y que se le entrase en el pecho la pícara tentación de poseerla. A contar de ese día, comenzó a mostrarse frío y reservado con doña Engracia, la que a su turno le reclamó el cumplimiento de su palabra. Entonces fue el capitán quien pidió una moratoria, alegando que había escrito a España para obtener el consentimiento de su familia, y que lo esperaba por el primer galeón que diese fondo en el Callao. No era éste el expediente más a propósito para impedir que se despertasen los celos en la enamorada andaluza y que comunicase a su hermano sus temores de verse burlada. Don Juan echose en consecuencia a seguir los pasos del novio, y ya hemos visto en el anterior capítulo la casual circunstancia que lo puso sobre la pista."}, {"type": "p", "text": "El reloj hizo sonar distintamente las campanadas de las ocho, y la dama, como cediendo a impulso galvánico, se incorporó en el diván."}, {"type": "p", "text": "—¡Al fin, Dios mío! ¡Pensé que el tiempo no corría! Deja esa lectura, hermano... Vendrá ya D. Martín, y sabes cuánto anhelo esta entrevista."}, {"type": "p", "text": "—¿Y si apuras un nuevo desengaño?"}, {"type": "p", "text": "—Entonces, hermano, será lo que he resuelto."}, {"type": "p", "text": "Y la mirada de la joven era sombría al pronunciar estas palabras."}, {"type": "p", "text": "D. Juan abrió una puerta de cristales y desapareció tras ella."}, {"type": "p", "text": "III. Un paso al crimen"}, {"type": "p", "text": "—¿Dais permiso, Engracia?"}, {"type": "p", "text": "—Huélgome de vuestra exactitud, D. Martín."}, {"type": "p", "text": "—Soy hidalgo, señora, y esclavo de mi palabra."}, {"type": "p", "text": "—Eso es lo que hemos de ver, señor capitán, si place a vuesarced que hablemos un rato en puridad."}, {"type": "p", "text": "Y con una sonrisa henchida de gracia y un ademán lleno de dignidad, la joven señaló al galán un asiento a su lado."}, {"type": "p", "text": "Justo es que lo demos a conocer, ya que en la tienda de maese Ibirijuitanga nos olvidamos de cumplir para con el lector este acto de estricta cortesía, e hicimos aparecer al capitán como llovido del cielo. Esto de entrar en relaciones con quien no se conoce ni nos ha sido presentado en debida forma, suele tener sus inconvenientes. D. Martín raya en los treinta años, y es lo que se llama un gentil y guapo mozo. Viste el uniforme de capitán de jinetes, y en el desenfado de sus maneras hay cierta mezcla de noble y de tunante."}, {"type": "p", "text": "Al sentarse cogió entre las suyas una mano de Engracia, y empezó entre ambos esa plática de amantes, que, cuál más, cuál menos, todos saben al pespunte. Si en vez de relatar una crónica escribiéramos un romance, aunque nunca nos ha dado el naipe por ese juego, enjaretaríamos aquí un diálogo de novela. Afortunadamente, un narrador de crónicas puede desentenderse de las zalamerías de enamorados e irse derecho al fondo del asunto."}, {"type": "p", "text": "El reloj del salón dio nueve campanadas, y el capitán se levantó."}, {"type": "p", "text": "—Perdonad, señora, si las atenciones del servicio me obligan a separarme de vos más pronto de lo que el alma desearía."}, {"type": "p", "text": "—¿Y es vuestra última resolución, D. Martín, la que me habéis indicado?"}, {"type": "p", "text": "—Sí, Engracia. Nuestra boda no se realizará mientras no vengan el consentimiento de mi familia y el real permiso que todo hidalgo bien nacido debe solicitar. Vuestra ejecutoria es sin mancha, en vuestros ascendientes no hay quien haya sido penitenciado con el sambenito de dos aspas, ni en vuestra sangre hay mezcla de morería; y así Dios me tenga en su santa guarda, si el monarca y mis parientes no acceden a mi demanda."}, {"type": "p", "text": "Ante la insultadora ironía de estas palabras que recordaban a la dama su origen, se estremeció ella de rabia y el color de la púrpura subió a su rostro; mas serenándose luego y fingiendo no hacer atención en el agravio, miró con fijeza a D. Martín, como si quisiera leer en sus ojos la respuesta a esta pregunta:"}, {"type": "p", "text": "—Decidme con franqueza, capitán, ¿tendríais en más la voluntad de los vuestros que la honra que os he sacrificado y lo que os debéis a vos mismo?"}, {"type": "p", "text": "—Estáis pesada en demasía, señora. Aguardad que llegue ese caso, y por mi fe que os responderé."}, {"type": "p", "text": "—Suponedlo llegado."}, {"type": "p", "text": "—Entonces, señora... ¡Dios dirá!"}, {"type": "p", "text": "—Id con él, D. Martín de Salazar... Tenéis razón... ¡Dios dirá!"}, {"type": "p", "text": "Y don Martín se inclinó ceremoniosamente, y salió."}, {"type": "p", "text": "Doña Engracia lo siguió con esa mirada de odio que revela en la mujer toda la indignación del orgullo ofendido, se llevó las manos al pecho como si intentara sofocar los latidos del corazón, y luego, con la faz descompuesta y los vestidos en desorden, se lanzó a la puerta de cristales, bajo cuyo dintel, lívido como un espectro, apareció el proveedor de la real armada."}, {"type": "p", "text": "—¿Lo has oído?"}, {"type": "p", "text": "—¡Pluguiera a Dios que no! —dijo don Juan con acento reconcentrado."}, {"type": "p", "text": "—Pues entonces, ¿por qué no heriste sin compasión? ¿Por qué no le diste muerte de traidor? ¡Mátale, hermano! ¡Mátale!"}, {"type": "p", "text": "IV. ¡Dios dirá!"}, {"type": "p", "text": "Siete horas después, y cuando el alba empezaba a colorar el horizonte, un hombre descendía, con auxilio de una escala de seda, del balcón que en la calle de Jesús Nazareno y sobre la tienda de maese Ibirijuitanga, habitaba Transverberación. Colocaba ya el pie sobre el último peldaño, cuando saltó sobre él un embozado, e hiriéndole por la espalda con un puñal, murmuró al oído de su víctima:"}, {"type": "p", "text": "—¡Dios dirá!"}, {"type": "p", "text": "El escalador cayó desplomado. Había muerto a traición y con muerte de traidor. Al mismo tiempo oyose un grito desesperado en el balcón, y la dudosa luz del crepúsculo guió al asesino, que se alejó a buen paso."}]$lira$::jsonb, 1077);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 23, 'VI (8/11)', $lira$[{"type": "p", "text": "V. Consecuencias Quince días más tarde se elevaba una horca en la plaza de Lima. La Real Audiencia no se había andado con pies de plomo, y a guisa de aquel alcalde de casa y corte que previno a sus alguaciles que, cuando no pudiesen haber a mano al delincuente, metiesen en chirona al primer prójimo que encontrasen por el camino, había condenado a hacer zapatetas en el aire al desdichado barbero. Para los jueces el negocio estaba tan claro que más no podía serlo. Constaba de autos que la víctima había sido parroquiano del rapista, y que la víspera de su muerte le prestó oportuno socorro contra varios malsines. Esto era ya un hilo para el tribunal. Una escala al pie del balcón de la tienda no podía haber caído de las nubes, sobre todo cuando Ibirijuitanga tenía sobrina casadera a quien el lance había entontecido. Una muchacha no se vuelve loca tan a humo de pajas. Atemos cabos, se dijeron los oidores, y tejamos cáñamo para la horca; pues importa un ardite que el redomado y socarrón barbero permanezca reacio en negar, aun en el tormento, su participación en el crimen."}, {"type": "p", "text": "Además, las viejas de cuatro cuadras a la redonda declaraban que maese Ibirijuitanga era hombre que les daba tirria, porque sabía hacer mal de ojo, y las doncellas feas y sin noviazgo, que si Dios no lo remediaba serían enterradas con palma, afirmaban con juramento que Transverberación era una mozuela descocada, que andaba a picos pardos con los mancebos de la vecindad, y que se emperejilaba los sábados para asistir con su tío, montada en una caña de escoba, al aquelarre de las brujas. Los incidentes del proceso eran la comidilla obligada de las tertulias. Las mujeres pedían un encierro perpetuo para la escandalosa sobrina, y los hombres la horca para el taimado barbero."}, {"type": "p", "text": "La Audiencia dijo entonces: «Serán usarcedes servidos»; y aunque Ibirijuitanga puso el grito en el cielo, protestando su inocencia, le contestó el verdugo: «¡Calle el vocinglero y déjese despabilar!»."}, {"type": "p", "text": "A la hora misma en que la cuerda apretaba la garganta del pobre diablo y que Transverberación era sepultada en un encierro, las campanas del monasterio de la Concepción, fundado pocos años antes por una cuñada del conquistador Francisco Pizarro, anunciaban que había tomado el velo doña Engracia de Toledo, prometida del infortunado D. Martín."}, {"type": "p", "text": "¡Justicia de los hombres! ¡No en vano te pintan ciega!"}, {"type": "p", "text": "Concluyamos:"}, {"type": "p", "text": "El barbero finó en la horca."}, {"type": "p", "text": "La sobrina remató por perder el poco o mucho juicio con que vino al mundo. Doña Engracia profesó al cabo: diz que con el andar del tiempo alcanzó a abadesa, y que murió tan devotamente como cumplía a una cristiana vieja."}, {"type": "p", "text": "En cuanto a su hermano, desapareció un día de Lima, y..."}, {"type": "p", "text": "¡Cristo con todos! Dios te guarde, lector."}, {"type": "p", "text": "VI. En olor de santidad"}, {"type": "p", "text": "De seguro que vendrían a muchos de mis lectores pujamientos de confirmarse por el más valiente zurcidor de mentiras que ha nacido de madre, si no echase mano de este título para dar a mi relación un carácter histórico apoyándome en el testimonio de algunos cronistas de Indias. Pero no es en Lima donde ha de desenlazarse esta conseja; y el curioso que anhele conocerla hasta el fin, tiene que trasladarse conmigo, en alas del pensamiento, a la villa imperial de Potosí. No se dirá que en los días de mi asendereada vida de narrador dejé colgado un personaje entre cielo y tierra, como diz que se hallan San Hinojo y el alma de Garibay."}, {"type": "p", "text": "Potosí, en el siglo XVI, era el punto de América adonde afluían de preferencia todos aquellos que soñaban improvisar fabulosa fortuna. Descubierto su rico mineral en enero de 1538 por un indio llamado Gualpa, aumentó en importancia y excitó la codicia de nuestros conquistadores desde que, en pocos meses, el capitán Diego Centeno, que trabajaba la famosa mina Descubridora, adquirió un caudal que tendríamos hoy por quimérico, si no nos mereciesen respeto el jesuita Acosta, Antonio de Herrera y la Historia Potosina de Bartolomé de Dueñas. Antes de diez años la población de Potosí ascendió a 15.000 habitantes, triplicándose el número en 1572, cuando en virtud de real cédula se trasladó a la villa la casa de moneda de Lima. Los últimos años de aquel siglo corrieron para Potosí entre el lujo y la opulencia, que a la postre engendró rivalidades entre andaluces, extremeños y criollos contra vascos, navarros y gallegos. Estas contiendas terminaban por batallas sangrientas, en las que la suerte de las armas se inclinó tan pronto a un bando como a otro. Hasta las mujeres llegaron a participar del espíritu belicoso de la época; y Méndez en su Historia de Potosí refiere extensamente los pormenores de un duelo campal a caballo, con lanza y escudo, en que las hermanas doña Juana y doña Luisa Morales mataron a D. Pedro y a D. Graciano González."}, {"type": "p", "text": "No fueron éstas las únicas hembras varoniles de Potosí; pues en 1662, llevándose la justicia presos a D. Ángel Mejía y a don Juan Olivos, salieron al camino las esposas de éstos con dos amigas, armadas las cuatro de puñal y pistola, hirieron al juez, mataron dos soldados y se fugaron para Chile llevándose a sus esposos. Otro tanto hizo en ese año doña Bartolina Villapalma, que con dos hijas doncellas, armadas las tres con lanza y rodela, salió en defensa de su marido que estaba acosado por un grupo de enemigos, y los puso en fuga, después de haber muerto a uno y herido a varios. Pero no queremos componer, por cierto, una historia de Potosí ni de sus guerras civiles; y a quien desee conocer sus casos memorables, le recomendamos la lectura de la obra que, con el título de Anales de la vida Imperial, escribió en 1775 Bartolomé Martínez Vela."}, {"type": "p", "text": "VII. Ahora lo veredes"}, {"type": "p", "text": "Promediaba el año de 1625."}, {"type": "p", "text": "En las primeras horas de una fresca mañana el pueblo se precipitaba en la iglesia parroquial de la villa."}, {"type": "p", "text": "En el centro de ella se alzaba un ataúd alumbrado por cuatro cirios."}, {"type": "p", "text": "Dentro del ataúd yacía un cadáver con las manos cruzadas sobre el pecho y sosteniendo una calavera."}, {"type": "p", "text": "El difunto había muerto en olor de santidad, y los notarios formalizaban ya expediente para constatarlo y transmitirlo más tarde a Roma. ¡Quizá el calendario, donde figuran Tomás de Torquemada, Pedro Arbués y Domingo de Guzmán, se iba a aumentar con un nombre!"}]$lira$::jsonb, 1068);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 24, 'VI (9/11)', $lira$[{"type": "p", "text": "Y el pueblo, el sencillo pueblo, creía firmemente en la santidad de aquel a quien, durante muchos años, había visto cruzar sus calles con un burdo sayal de penitente, crecida barba de anacoreta, alimentándose de hierbas, durmiendo en una cueva y llevando consigo una calavera, como para tener siempre a la vista el deleznable fin de la mísera existencia humana. Y ¡lo que pueden el fanatismo y la preocupación! Muchos de los circunstantes afirmaban que el cadáver despedía olor a rosas."}, {"type": "p", "text": "Pero cuando ya se había terminado el expediente y se trataba de sepultar en la iglesia al difunto, vínole en antojo a uno de los notarios registrar la calavera, y entre sus apretados dientes encontró un pequeño pergamino sutilmente enrollado, al que dio lectura en público. Decía así:"}, {"type": "p", "text": "«Yo, D. Juan de Toledo, a quien todos hubisteis por santo, y que usé hábito penitencial, no por virtud, sino por dañada malicia, declaro en la hora suprema: que habrá poco menos de veinte años que, por agravios que me hizo D. Martín de Salazar en menoscabo de la honra que Dios me dio, le quité la vida a traición, y después que lo enterraron tuve medios de abrir su sepultura, comer a bocados su corazón, cortarle la cabeza, y habiéndole vuelto a enterrar me llevé su calavera, con la que he andado sin apartarla de mi presencia, en recuerdo de mi venganza y de mi agravio. ¡Así Dios le haya perdonado y perdonarme quiera!»."}, {"type": "p", "text": "Los notarios hicieron añicos el expediente, y los que tres minutos antes encontraban olor a rosas en el difunto se esparcieron por la villa, asegurando que el cadáver del de Toledo estaba putrefacto y nauseabundo, y que no volverían a fiarse de las apariencias."}, {"type": "p", "text": "La fiesta de San Simón Garabatillo"}, {"type": "p", "text": "Faustino Guerra habíase encontrado en la batalla de Ayacucho en condición de soldado raso. Afianzada la independencia, obtuvo licencia final y retirose a la provincia de su nacimiento, donde consiguió ser nombrado maestro de escuela de la villa de Lampa."}, {"type": "p", "text": "El buen Faustino no era ciertamente hombre de letras; mas para el desempeño de su cargo y tener contentos a los padres de familia, bastábale con leer medianamente, hacer regulares palotes y enseñar de coro a los muchachos la doctrina cristiana. La escuela estaba situada en la calle Ancha, en una casa que entonces era propiedad del Estado y que hoy pertenece a la familia Montesinos."}, {"type": "p", "text": "Contra la costumbre general de los dómines de aquellos tiempos, don Faustino hacía poco uso del látigo, al que había él bautizado con el nombre de San Simón Garabatillo. Teníalo más bien como signo de autoridad que como instrumento de castigo, y era preciso que fuese muy grave la falta cometida por un escolar para que el maestro le aplicase un par de azoticos, de esos que ni sacan sangre ni levantan roncha. El 28 de octubre de 1826, día de San Simón y Judas por más señas, celebrose con grandes festejos en las principales ciudades del Perú. Las autoridades habían andado empeñosas y mandaron oficialmente que el pueblo se alegrase. Bolívar estaba entonces en todo su apogeo, aunque sus planes de vitalicia empezaban ya a eliminarle el afecto de los buenos peruanos."}, {"type": "p", "text": "Sólo en Lampa no se hizo manifestación alguna de regocijo. Fue ese para los lampeños día de trabajo, como otro cualquiera del año, y los muchachos asistieron, como de costumbre, a la escuela."}, {"type": "p", "text": "Era ya más de mediodía cuando don Faustino mandó cerrar la puerta de la calle, dirigiose con los alumnos al corral de la casa, los hizo poner en línea, y llamando a dos robustos indios que para su servicio tenía, les mandó que cargasen a los niños. Desde el primero hasta el último, todos sufrieron una docena de latigazos, a calzón quitado, aplicados por mano de maestro."}, {"type": "p", "text": "La gritería fue como para ensordecer, y hubo llanto general para una hora. Cuando llegó el instante de cerrar la escuela y de enviar los chicos a casa de sus padres, les dijo don Faustino:"}, {"type": "p", "text": "—¡Cuenta, pícaros godos, con que vayan a contar lo que ha pasado! Al primero que descubra yo que ha ido con el chisme lo tundo vivo."}, {"type": "p", "text": "«¿Si se habrá vuelto loco su merced?», se preguntaban los muchachos; pero no contaron a sus familias lo sucedido, si bien el escozor de los ramalazos los traía aliquebrados."}, {"type": "p", "text": "¿Qué mala mosca había picado al magister, que de suyo era manso de genio, para repartir tan furiosa azotaina? Ya lo sabremos."}, {"type": "p", "text": "Al siguiente día presentáronse los chicos en la escuela, no sin recelar que se repitiese la función. Por fin, don Faustino hizo señal de que iba a hablar."}, {"type": "p", "text": "—Hijos míos —les dijo—, estoy seguro de que todavía se acuerdan del rigor con que los traté ayer, contra mi costumbre. Tranquilícense, que estas cosas sólo las hago yo una vez al año. ¿Y saben ustedes por qué? Con franqueza, hijos, digan si lo saben."}, {"type": "p", "text": "—No, señor maestro —contestaron en coro los muchachos."}, {"type": "p", "text": "—Pues han de saber ustedes que ayer fue el santo del libertador de la patria, y no teniendo yo otra manera de festejarlo y de que lo festejasen ustedes, ya que los lampeños han sido tan desagradecidos con el que los hizo gentes, he recurrido al chicote. Así, mientras ustedes vivan, tendrán grabado en la memoria el recuerdo del día de San Simón. Ahora a estudiar su lección y ¡viva la patria!"}, {"type": "p", "text": "Y la verdad es que los pocos que aun existen de aquel centenar de muchachos se reúnen en Lampa el 28 de octubre y celebran una comilona, en la cual se brinda por Bolívar, por don Faustino Guerra y por San Simón Garabatillo, el más milagroso de los santos de achaques de refrescar la memoria y calentar partes pósteras."}, {"type": "p", "text": "Un predicador de lujo"}, {"type": "p", "text": "El padre Samamé, de la orden dominica, en treinta años que tuvo de conventual no predicó más que una vez; pero esa bastó para su fama. De lo bendito poquito. Lo que voy a contar pasó en la tierra donde el diablo se hizo cigarrero, y no le fue del todo mal en el oficio."}, {"type": "p", "text": "Huacho era, en el siglo anterior, un villorrio de pescadores y labriegos, gente de letras gordas o de poca sindéresis, pero vivísima para vender gato por liebre. Ellos, por arte de birlibirloque o con ayuda de los polvos de pirlimpimpim, que no sabemos se vendan en la botica, transformaban un róbalo en corvina y aprovechaban la cáscara de la naranja para hacer naranjas hechizas."}]$lira$::jsonb, 1080);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 25, 'VI (10/11)', $lira$[{"type": "p", "text": "Los huachanos de ahora no sirven, en punto a habilidad e industria, ni para descalzar a sus abuelos. Decididamente las razas degeneran."}, {"type": "p", "text": "A los huachanos de hoy no les atañe ni les llega a la pestaña mi cuento. Hablo de gente del otro siglo y que ya está criando malvas con el cogote. Y hago esta salvedad para que no brinque alguno y me arme proceso, que de esas cosas se han visto, y ya estoy escamado de humanas susceptibilidades y tonterías."}, {"type": "p", "text": "Aconteció por entonces que aproximándose la semana santa, el cura del lugar hallábase imposibilitado para predicar el sermón de tres horas por causa de un pícaro reumatismo. En tal conflicto, escribió a un amigo de Lima, encargándole que le buscase para el Viernes Santo un predicador que tuviese siquiera dos bes, es decir, bueno y barato."}, {"type": "p", "text": "El amigo anduvo hecho un trotaconventos sin encontrar fraile que se decidiera a hacer por poca plata viaje de cincuenta leguas entre ida y regreso."}, {"type": "p", "text": "Perdida ya toda esperanza, dirigiose el comisionado al padre Samamé, cuya vida era tan licenciosa, que casi siempre estaba preso en la cárcel del convento y suspenso en el ejercicio de sus funciones sacerdotales. El padre Samamé tenía fama de molondro y, no embargante ser de la orden de predicadores, jamás había subido al púlpito. Pero si no entendía jota de lugares teológicos ni de oratoria sagrada, era en cambio eximio catador de licores, y váyase lo uno por lo otro."}, {"type": "p", "text": "Abocose con él el comisionado, lo contrató entre copa y copa, y sin darle tiempo para retractarse lo hizo cabalgar, y sirviéndole él mismo de guía y acompañante salieron ambos caminito de Chancay."}, {"type": "p", "text": "Llegados a Huacho, alborotose el vecindario con la noticia de que iba a haber sermón de tres horas y predicado por un fraile de muchas campanillas y traído al propósito de Lima. Así es que el Viernes Santo no quedó en Laurima, Huara y demás pueblos de cinco leguas a la redonda bicho viviente que no se trasladara a Huacho para oír a aquel pico de oro de la comunidad dominica."}, {"type": "p", "text": "El padre Samamé subió al sagrado púlpito; invocó como pudo al Espíritu Santo, y se despachó como a Dios plugo ayudarle."}, {"type": "p", "text": "Al ocuparse de aquellas palabras de Cristo, hoy serás conmigo en el paraíso, dijo su reverencia, sobre poco más o menos: «A Dimas, el buen ladrón, lo salvó su fe; pero a Gestas, el mal ladrón, lo perdió su falta de fe. Mucho me temo, queridos huachanos y oyentes míos, que os condenéis por malos ladrones»."}, {"type": "p", "text": "Un sordo rumor de protestas levantose en el católico auditorio. Los huachanos se ofendieron, y con justicia, de oírse llamar malos ladrones. Lo de ladrones, por sí solo, era una injuria, aunque podía pasar como floreo de retórica; pero aquel apéndice, aquel calificativo de malos, era para sublevar el amor propio de cualquiera. El reverendo, que notó la fatal impresión que sus palabras habían producido, se apresuró a rectificar: «Pero Dios es grande, omnipotente y misericordioso, hijos míos, y en él espero que con su ayuda soberana y vuestras felices disposiciones llegaréis a tener fe y a ser todos sin excepción buenos, muy buenos ladrones»."}, {"type": "p", "text": "A no estar en el templo el auditorio habría palmoteado; pero tuvo que limitarse a manifestar su contento con una oleada que parecía un aplauso. Aquella dedada de miel fue muy al gusto de todos los paladares."}, {"type": "p", "text": "Entretanto, el cura estaba en la sacristía echando chispas, y esperando que descendiese el predicador para reconvenirlo por la insolencia con que había tratado a sus feligreses."}, {"type": "p", "text": "—Es mucha desvergüenza, reverendo padre, decirles en su cara lo que les ha dicho."}, {"type": "p", "text": "—¿Y qué les dije? —preguntó el fraile sin inmutarse."}, {"type": "p", "text": "—Que eran malos ladrones..."}, {"type": "p", "text": "—¿Eso les dije? Pues, señor cura, ¡me los mamé!"}, {"type": "p", "text": "—Gracias a que después tuvo su paternidad el tino suficiente para dorarles la píldora."}, {"type": "p", "text": "—¿Y qué les dije?"}, {"type": "p", "text": "—Que andando los tiempos, y Dios mediante, serían buenos ladrones..."}, {"type": "p", "text": "—¿Eso les dije? Pues, señor cura, ¡me los volví a mamar!"}, {"type": "p", "text": "Y colorín, colorado, aquí el cuento ha terminado."}, {"type": "p", "text": "Predestinación"}, {"type": "p", "text": "(A Carlos Augusto Salaverry)"}, {"type": "p", "text": "El siglo XIX estaba aún en mantillas (lo que importa, lector amigo, decirte que la acción de este capítulo pasa en 1801) y perdona lo alambicado de la frase. Salamanca, la de la famosa Universidad, ardía de entusiasmo, en cierta noche de aquel año, porque un gallardo mozo de la chusma estudiantil había colgado el raído manteo, cambiando a Cicerón y las Pandectas por las comedias del buen Lope y del romántico Calderón. En una de las tabernas de la universitaria ciudad hallábanse congregados, al olor de un suculento jigote y de descomunales jarros de Valdepeñas no bautizado, gran número de estudiantes, cómicos y mujerzuelas, gente toda así lista para un fregado como para un barrido, a la que tanto se le daba de lo de arriba como de lo de abajo. Y a un extremo de la sala y al calor del brasero, veíase una muchacha que ejercía a la vez los oficios de cantora y lazarillo de un pobre ciego de gitanesca estampa. Degollación, que tal era el nombre de la mocita, tenía una cara más fea que el pecado de usura, y una voz de caña rota que el ciego rascador de guitarra sabía hacer soportable por la sal de su punteado."}, {"type": "p", "text": "—¡Ea! ¡Degollación, hija mía! Échale una seguidilla al lucero de los claustros de Salamanca, al Sr. Rafael, que así Dios me salve si no ha de exceder, con tercio y quinto, al mismísimo Isidoro."}, {"type": "p", "text": "La muchacha tosió dos veces para limpiarse los arrabales de la garganta, el ciego rasqueó de lo lindo y, suspendiéndose por un rato el general batiburrillo, se hizo la chusma toda oídos para atender a lo sentencioso del cantar:"}, {"type": "p", "text": "«Las monjas en el coro"}, {"type": "p", "text": "dicen cantando:"}, {"type": "p", "text": "entre tantas hermanas"}, {"type": "p", "text": "no hay un hermano."}, {"type": "p", "text": "¡Y al estribillo!"}, {"type": "p", "text": "¿quién vio chocolatera"}, {"type": "p", "text": "sin molinillo?»."}, {"type": "p", "text": "—¡Víctor por la real moza! —exclamó en coro la estudiantina, echando al aire los chafados sombreros."}, {"type": "p", "text": "Pero el estudiante a quien el ciego había llamado el Sr. Rafael, y que al parecer era el héroe de la noche, había tomado un aire taciturno. Sus compañeros de mesa pretendían, con su aturdimiento, sacarlo de su distracción; y las mujeres lo miraban desvergonzadamente y con ojos de codicia, porque al cabo era un buen mozo que, a mayor abundamiento, acababa de ser aplaudido con frenesí, debutando en las Paredes oyen del correcto Alarcón."}]$lira$::jsonb, 1073);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 26, 'VI (11/11)', $lira$[{"type": "p", "text": "Cuando el vino sacó de caja todos los cerebros, Rafael abandonó la taberna, sin que su desaparición fuese notada nada más que por el comediante Antonio Espejo, quien penetró en el cuarto de su compañero y lo encontró en el mismo estado de preocupación que le había observado en el festín."}, {"type": "p", "text": "—Rafael, amigo mío, tú sufres."}, {"type": "p", "text": "—Es verdad, Espejo. En medio de ese banquete he sido presa de una alucinación fatal. Escúchame, Desde que estrechamos nuestra amistad, se reveló en mí deseo vivísimo de merecer sobre la escena los aplausos del pueblo, de ser fiel intérprete de nuestros grandes poetas y arrebatar de entusiasmo al mundo, alcanzando las coronas reservadas al genio. Y esta noche, cuando alistado ya en tu compañía, he hecho mi primera presentación y alcanzado mi primer triunfo, se despertó en mí el recuerdo de mis padres que me desdeñan y creen que el título de cómico es un borrón que arrojo en los cuarteles de mi ilustre familia. Ya no es posible retroceder. Abandono mi apellido, y desde hoy me llamaré Rafael Cebada... Pero en medio de ese banquete, un cuadro sombrío apareció de pronto a mi imaginación. Figurábame estar en una gran plaza y rodeado de inmenso pueblo... Todas las miradas estaban fijas en mí... Yo era el protagonista de esa fiesta... En el centro de la plaza se alzaba un cadalso... y dos hombres subieron a él junto conmigo... Uno era el verdugo, y el otro era un sacerdote...: Eras tú, Espejo, tú, que me has abierto las puertas a la existencia afanosa del cómico y que me acompañabas hasta el dintel de la tumba!..."}, {"type": "p", "text": "Y Rafael Cebada, entregado a la violencia del delirio, cayó sin sentido en los brazos de su amigo."}]$lira$::jsonb, 289);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 27, 'II', $lira$[{"type": "p", "text": "Pasados eran los días en que el atrio de la catedral servía de escenario para la representación de Autos sacramentales. Lima poseía el teatro incómodo y nada elegante al que hoy concurre nuestro público, ávido siempre de espectáculos, teatro cuyo ridículo aspecto le ha conquistado el nombre de gallinero. El teatro actual había sustituido a otro que, desde 1602 hasta 1661, existió en la calle de San Agustín, en la casa conocida aún por la de la Comedia vieja y en cuya fábrica se habían gastado cincuenta y ocho mil pesos. La del actual costó sesenta mil pesos, y su refección, después del terremoto de 1746, importó poco más de cuarenta mil. Fue el ilustre limeño Olavide quien estuvo encargado de dirigir la reedificación del teatro, notable por sus buenas condiciones acústicas más que por la pobreza de su arquitectura. Con el nuevo proscenio, los habitantes de Lima no sólo habían ganado en localidad, sino en el mérito de los artistas y en la variedad de las funciones. Era indispensable que, tras de Orestes o el Diablo predicador, una pareja de baile luciese el encanto sensual de la danza española. Venía luego el Alcalde torero o algún sainete de Ramón de la Cruz, y sólo se retiraba el espectador después de aplaudir la tonadilla, especie de zarzuela en andadores. Y las empresas de teatro que por seis reales ofrecían al concurrente declamación, baile y canto, no se atrevieron a solicitar jamás una alza de precios. ¡Lo que va de tiempo a tiempo!"}, {"type": "p", "text": "En el telón del teatro de Lima veíase pintado el Parnaso, y hasta 1824 se leía en él la siguiente octava, original del conde de las Torres, literato de pobre literatura, a juzgar por la octava que de él conocemos y que, sin lisonja, es de lo malo lo mejorcito: Útiles de este Pindo refulgente"}, {"type": "p", "text": "Son auxilio a hospitálica indigencia"}, {"type": "p", "text": "Que Apolo, como médico excelente,"}, {"type": "p", "text": "Si aquí da el metro, allá la Providencia."}, {"type": "p", "text": "Mi farsa es una acción grave y decente"}, {"type": "p", "text": "De honorosa política e influencia,"}, {"type": "p", "text": "Y el que otro viso hallare en el que inflama"}, {"type": "p", "text": "Aproveche la luz, deje la llama."}, {"type": "p", "text": "¿Has entendido, lector? Pues yo tampoco."}, {"type": "p", "text": "La primera vez que los limeños disfrutaron de ópera italiana fue en 1814. La compañía era diminuta, y así el tenor, Pedro Angelini, como la soprano, Carolina Grijoni, de escasísimo mérito. El espectáculo no fue del gusto público y por ello fue reducido el número de funciones. Sólo desde 18 40, en que tuvimos a las inolvidables Clorinda Pantanelli y Teresina Rossi, empezaron a ocupar la escena lírica artistas de reputación merecida."}, {"type": "p", "text": "Por el año de 1814, época en que principia nuestro relato, el primer actor de la compañía dramática era el famoso Roldán, discípulo de Isidoro Máiquez, figurando en segunda escala el gracioso Rodríguez, Cebada como galán joven y Barbeito en los papeles de traidor. Cuando alguna vez hemos aplaudido a O'Loghlin en Ricardo III y Sullivan, a Manuel Dench en el Cardenal Montalto, a Jiménez en Dos horas de favor, a Casacuberta en los Escalones del crimen, a Aníbal Ramírez en las comedias de Rodríguez Rubí, a Lutgardo Gómez en Traidor, inconfeso y mártir, a Torres en Luis XI, a Valero en el Músico de la murga o a Burón en el Drama nuevo, y manifestado nuestro entusiasmo a un anciano que la casualidad nos deparaba por vecino de luneta, siempre hirió nuestros oídos esta contestación: «¡Psche! No está mal ese actor... Pero si usted hubiera conocido a Roldán... ¡Oh, Roldán!... Eso era lo que había que ver». Cuando Emilia Hernández, Aurora Fedriani, Matilde Duclós, Amalia Pérez, Ventura Mur o Carolina Civili han arrancado un ¡bravo! a nuestros labios y un aplauso a nuestras manos, también hemos sido interrumpidos por una voz cascada y catarrienta: «¡Qué fosfórica es esta juventud! Bien se conoce que no oyeron a la Moreno!... ¡Oh, la Moreno!... ¡Cosa mejor, ni en la gloria!»."}, {"type": "p", "text": "Y en efecto, Roldán, que en la comedia era una apreciable medianía, no ha encontrado hasta hoy, en nuestro proscenio, según el sentir de muy entendidos críticos, un digno rival en la tragedia. En cuanto a la Moreno, sólo sabemos que había llegado a ser una buena actriz, sin que, por entonces, tuviera mérito bastante para que se la considerase como una notabilidad. Y no es concebible la importancia que quieren darla nuestros antecesores, desde que se sabe que su educación fue tan descuidada que aprendió a leer de corrido entre los bastidores del teatro y a la edad de diez y ocho años."}]$lira$::jsonb, 754);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 28, 'III', $lira$[{"type": "p", "text": "María Moreno nació en Guayaquil en 1794. Rafael Cebada la conoció al pasar por esa ciudad en 1812. Se apasiono vivamente de su hermosura y recurrió a la tercería de una apergaminada vieja para dirigir billeticos a la joven. Cebada era, a la sazón, un andaluz de treinta años, de blonda y rica cabellera, de grandes ojos negros y de gallardo cuerpo. Sin embargo de su varonil hermosura, revelaba en la palidez del rostro ese sello que frecuentemente dejan los vicios. Ello es que María encontró al galán muy de su gusto, y para dar un fin romancesco a los preliminares, concertó con él una escapatoria de la casa materna."}, {"type": "p", "text": "Embarcose la enamorada pareja en un buque próximo a zarpar de la ría. Peregrinaron por Trujillo y Cajamarca, y soñando con que todo el monte era orégano y demás lindezas con que diz que sueñan los amantes, despertaron una mañana en la tres veces coronada ciudad de los reyes. Cebada se había consagrado a educar a su querida, la que dio tales muestras de habilidad que, en menos de dos meses, alcanzó a leer la letra de cadenilla con que se copiaban los papeles de comedia y estuvo expedita para hacer su primera salida en un teatrillo de pueblo."}, {"type": "p", "text": "Al llegar a Lima contaba la joven actriz muy cerca de diez y nueve años y era de fisonomía bella y simpática. Imagínese el lector un rostro ligeramente ovalado entre un marco de negros y sedosos cabellos; una frente tersa y arqueadas cejas sobre magníficos y relucientes ojos garzos, capaces de incendiar un corazón de caucho; unos labios purpúreos, pequeños e incitantes, hombros mórbidos y seno voluptuoso. Y si a estos rápidos detalles añade una sonrisa, a la que aumentaba gracia una linda trinidad de hoyuelos y una voz dulce como una esperanza de amor, fácil es de adivinarse el cúmulo de simpatías y de adoradores que conquistaría en la escena la mujer que se presentaba con tales recomendaciones físicas. El mismo virrey Abascal, a pesar de su gravedad, años y achaques, quemaba, de vez en cuando, el incienso del galanteo a las plantas de la cómica."}, {"type": "p", "text": "Créese quo no son virtudes muy sólidas las de la gente del teatro; y aunque nunca han sido los bastidores escuela de moralidad, es consolador para la gloria del arte afirmar que no han escaseado en ellos mujeres dignas y hombres honrados. Esta errada creencia aumentó el número de pretendientes de María, que esperaban hallar en ella una fácil conquista; y los celos de Cebada se alarmaron, hasta el punto de abofetear a la actriz en el vestuario una noche en que la vio recibir de manos del marqués de C*** un precioso ramillete. Entonces María hizo entender a su amante que estaba resuelta a recobrar su libertad y que desde ese día iba a habitar en casa de una amiga."}]$lira$::jsonb, 477);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 29, 'IV (1/2)', $lira$[{"type": "p", "text": "Existía por aquellos años, en mitad de la calle de las Mantas, una casa de dos pisos con ínfulas de callejón, casa que conocimos convertida en fonda y posada, y que hoy, gracias a la influencia del buen gusto, forma los elegantes almacenes de Lynch y Ortiz. La casa, de mezquina apariencia, la constituían dos hileras de cuartos con una temblona escalera al fondo que guiaba a unas habitaciones altas, donde, con la holgura de una reina en su palacio, residía la más salerosa andaluza que hasta entonces hubiera pisado las orillas del Rimac."}, {"type": "p", "text": "Paca Rodríguez era una garrida muchacha de veinte eneros, con unos ojos del color del mar, decidores como una tentación y hermosos como la luz. Su tez era un poco morena y fresca como el terciopelo del lirio, y sus labios encendidos estaban sombreados de ese bozo, imperceptible casi, que revela la organización vigorosa de una mujer. Para completar el retrato de Paca digamos que su cuerpo era ágil, esbelto y que respiraba voluptuosidad, gracia y soltura por todos sus poros. Siendo ella bailarina, nos hallábamos obligados a poner al descubierto sus torneadas piernas; pero si hemos de hablar, lector, en puridad de amigos, creemos que mejor es no meneallo y que, pasándolas por alto, te libertamos de un pecado venial."}, {"type": "p", "text": "Pero a pesar de lo picaresco de sus ojos, Paca pertenecía a las nobles excepciones de las mujeres de teatro, en lo que nuestra pluma de cronista se da la enhorabuena. ¡Líbrela Dios de verse impelida de sacar a la vergüenza a las Magdalenas de bastidores! Los apasionados de la bailarina decían, a voz en cuello, que era incapaz de ser razonable y darse a partido, porque tenía la tonta debilidad de estar enamorada de su marido, el actor bufo Rodríguez, el cual hace más de veinte años que murió ejemplarmente en la ermita del Barranco, próxima a Chorrillos. Su memoria no es olvidada aun por los que, hombres ya, recordamos que él supo deleitar nuestra edad de rosa, arrancando no pocas sonrisas a los labios del niño."}, {"type": "p", "text": "Decíamos que Paca traía al retortero y desesperados a un enjambre de galanes. Sin dejar de ostentar esa festiva locuacidad ingénita al carácter andaluz, jamás otorgó una esperanza ni dio motivo para que se la tildase de coqueta. Que una mujer decante virtud porque no ha tenido ocasión de ponerla a prueba, es cosa que se encuentra al torcer cada esquina, y para nosotros es una virtud hechiza y de poca ley. La que no esquiva el peligro y sale de la lucha inmaculada es, perdónese nuestra opinión en gracia de la franqueza, la mujer de virtud real. Convengamos en que la de Paca era una virtud sólida, a prueba de oro y de ataques nerviosos, con lo cual está todo dicho. Las preocupaciones sociales, por otra parte, en una época en que todavía estaban calientes las cenizas de la hoguera inquisitorial y cuando se creía que el cómico era un excomulgado indigno de sepultura eclesiástica, hacían de las mujeres consagradas al teatro corazones quebradizos como el barro y sin más religión que la vida sensual. Una mujer de teatro se miraba entonces como una alhaja a la que el capricho, la moda y la vanidad dan precio. Era plato de ricos como el pavo trufado y las costillas de conejo. Paca huyendo de ese gazofilacio de prostitución y vicio, junto al que el destino la colocara, se arrojaba todas las semanas a los pies de un sacerdote que, bastante ilustrado para no rechazarla, la fortificaba con sus consejos y la brindaba los consuelos del cristianismo. Y la esperanza le tendía sus brazos y el amor de la esposa al esposo salvaba su honra de la calumnia."}, {"type": "p", "text": "Tal era Paca la bailarina, ángel que en medio del lodazal supo conservar la blancura de sus alas. Tal era la honesta mujer que abrió las puertas de su casa a la infeliz María. Era el 2 de agosto de 1814 y el pueblo se dirigía en tropel a la Alameda de los Descalzos (fundada en 1611), que no ostentaba el magnífico jardín enverjado ni las marmóreas estatuas que hoy la embellecen. Calles de sauces plantados sin simetría, algunos toscos bancos de adobes y una pila de bronce al costado del conventillo de Santa Liberata constituían la Alameda, que sin embargo de su pobreza, era el sitio más poético de Lima. Contémplanse desde él las pintorescas lomas de Amancaes; el empinado San Cristóbal, cuya forma hizo presumir que encerrase en su seno un volcán, y el pequeño cerro de las Ramas, donde contaban las buenas gentes que solía aparecerse el diablo, en cuya busca subió más de un crédulo desesperado. Y en el fondo de la Alameda, como invitando al espíritu a la contemplación religiosa, severo en la sencilla arquitectura de su fachada y misterioso como el dedo de Dios, se destaca el templo de la recolección de los misioneros descalzos, fundada en 1592 por el hermano lego fray Andrés Corzo."}]$lira$::jsonb, 831);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 30, 'IV (2/2)', $lira$[{"type": "p", "text": "Ni la iglesia ni el convento con su espaciosa huerta, que mide más de cinco fanegadas, ofrecen gran cosa que admirar. En uno de los claustros están la celda que durante algún tiempo ocupó San Francisco Solano, que fue el primer guardián que tuvo el convento, y la que en 1830 habitara el padre Guatemala, que murió en Ica, nueve años más tarde, en olor de santidad. En la portería y bajo un lienzo que representa el misterio de la Concepción de la Virgen, se leen estas palabras apenas comprensibles para los profanos en teología:"}, {"type": "p", "text": "Potuit,"}, {"type": "p", "text": "Decuit,"}, {"type": "p", "text": "Ergo fecit."}, {"type": "p", "text": "¿Pudo el Omnipotente"}, {"type": "p", "text": "a su Madre preservar?"}, {"type": "p", "text": "Hízolo: era muy decente."}, {"type": "p", "text": "O quiso y no pudo Dios,"}, {"type": "p", "text": "o pudo Dios y no quiso."}, {"type": "p", "text": "Si quiso y no pudo, no es Dios;"}, {"type": "p", "text": "ni hijo, si pudo y no quiso."}, {"type": "p", "text": "Digan, pues, que pudo y quiso."}, {"type": "p", "text": "Aquella tarde tenía lugar la fiesta de la Porciúncula, y desde las doce de la mañana estaban ocupados los bancos por esas huríes veladas, que la imitación de costumbres europeas ha desterrado —hablamos de las tapadas—. ¡Dolorosa observación! La saya y manto ha desaparecido llevándose consigo la sal epigramática, la espiritual travesura de la limeña. ¿Estará condenado nuestro pueblo a perder de día en día todo lo que lleva un sello de nacionalismo?"}, {"type": "p", "text": "La portería del convento estaba poblada de gente pobre, que recibía de manos de un lego escudillas de comida. ¡Verdadero festín de mendigos en que hacía el gasto la caridad cristiana! También la clase acomodada, hermosas mujeres y elegantes donceles, se acercaba a pedir al fraile un trozo de pan bendito. Y no se diga que era el sentimiento de la humildad que encomia el evangelista el que los guiaba, sino la costumbre y la imitación. Allí para nada entraba el sentimiento religioso. Entre la apiñada multitud se veía una linda joven, sencillamente vestida de negro, que ayudaba a los legos a repartir las viandas y socorría con pequeñas limosnas de dinero a los mendigos. Un hombre, que se hallaba confundido entre los grupos de curiosos, la miró fijamente y murmuró:"}, {"type": "p", "text": "—¿No es aquélla la Paca? ¿Y ha venido sola?... Esto, quiere decir que María ha quedado en la casa y podré verla sin testigos."}, {"type": "p", "text": "Y aquel hombre, embozándose en su larga capa española, salió de la Alameda con paso precipitado. Quien se hubiera entonces fijado en sus ojos, habría leído en ellos un pensamiento siniestro."}, {"type": "p", "text": "De pronto se encontró detenido por un vendedor de suertes."}, {"type": "p", "text": "—¡Patrón! Este número me queda —lo dijo el suertero, que para servir a usarcedes era el honrado Chombo, el decano de este gremio de vendedores de billetes de lotería, a quien todos los limeños conocemos."}, {"type": "p", "text": "Chombo es un pobre viejo que, como el jorobadito Lumbreras, no ha sabido en su vida sino asentar suertes. Cuenta hoy más de setenta años; y Chombo a imitación de Ashavero, sentenciado por la justicia divina a errar sobre la tierra hasta el fin de los siglos, está condenado por la fatalidad a vender billetes de lotería hasta que se acabe el pábilo de su vida."}, {"type": "p", "text": "El embozado, al sentir que le hablaban, pareció volver de una idea que lo preocupaba, y contestó con acento reconcentrado:"}, {"type": "p", "text": "—Una suerte... ¡Ah!... Ponga usted... para hacer bien por el alma de una que va a morir."}, {"type": "p", "text": "Chombo lo miró asustado; y a la postre, echando cuentas consigo mismo, escribió el mote que le dictaban, cobró, entregó el respectivo billete, y el hombre de la capa se alejó a buen paso."}]$lira$::jsonb, 584);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 31, 'VI', $lira$[{"type": "p", "text": "Melancólica como la predestinación estaba aquella tarde María en las habitaciones de Paca, recostada en un canapé de terciopelo. Tristes pensamientos dominaban su alma, y acaso entre ellos iba alguno consagrado a la mujer que la llevó en su seno y cuya ternura había olvidado seducida por los halagos de un hombre."}, {"type": "p", "text": "Desde que María se acogió al amparo de su amiga, Cebada no omitió súplicas ni extremos para obligarla a reanudar un lazo que su cobarde imprudencia había roto. Pero mientras más rogaba él, más crecía la negativa de su querida; que achaque de mujer ha sido siempre desdeñar al que se humilla. Esa tarde María permaneció inalterable, como la fatalidad, a las amenazas y ruegos, hasta que su amante, en un arrebato de desesperación, exclamó: «Pues bien, María, si no has de pertenecerme, no quiero que ningún hombre llegue a poseer tu belleza»."}, {"type": "p", "text": "Y seis veces clavó su puñal en el cuerpo de la desventurada joven..."}, {"type": "p", "text": "Tres días después circulaba este soneto en honor de María Moreno, y que es atribuido a D. Bernardino Ruiz, literato de esa época en que brillaban D. Hipólito Unánue, Valdez y el festivo clérigo Larriva."}, {"type": "p", "text": "«Lloren las musas con acerbo llanto"}, {"type": "p", "text": "el desgraciado fin de la que un día,"}, {"type": "p", "text": "a Melpomene grata y a Talía,"}, {"type": "p", "text": "de nuestra escena fue lustre y encanto."}, {"type": "p", "text": "Su primor y despejo pudo tanto"}, {"type": "p", "text": "para darla opinión y nombradía,"}, {"type": "p", "text": "que el culto espectador ya se creía"}, {"type": "p", "text": "pasar desde el placer hasta el espanto."}, {"type": "p", "text": "En la flor de su edad encantadora,"}, {"type": "p", "text": "osó en vano apagarle su luz pura"}, {"type": "p", "text": "y el sepulcro le abrió mano traidora."}, {"type": "p", "text": "Pues, por vengarla, de esta losa dura"}, {"type": "p", "text": "labró el genio un altar en donde mora"}, {"type": "p", "text": "el talento, la gracia y la hermosura»."}, {"type": "p", "text": "El soneto no es, en verdad, la octava maravilla; pero lo consignamos a guisa de comprobante histórico."}]$lira$::jsonb, 305);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 32, 'VII', $lira$[{"type": "p", "text": "Rafael Cebada, después de perpetrar el asesinato, tomó asilo en el convento de los descalzos. Grande fue la sensación que su crimen produjo en los habitantes de Lima, que reclamaban el pronto castigo de quien con tanta crueldad había dado muerte a la actriz favorita del público. Pero los días volaban, y no se habría alcanzado a descubrir el paradero del asesino sin una circunstancia providencial."}, {"type": "p", "text": "Recordará el lector que Cebada, pocos momentos antes de penetrar en casa de Paca, compró un billete de lotería. Cinco días después hízose la extracción, y el billete resultó agraciado. Cebada mandó llamar con un lego del convento a su amigo el actor Manuel García y le entregó el número, encargándole el cobro de la suerte. El infeliz soñaba proporcionarse con ese dinero los precisos recursos para huir de Lima. Los amigos se parecen a las navajas de barba: sale una buena entro diez. García se dirigió sin vacilar a casa de D. Juan Bautista de Lavalle y le denunció el asilo de Cebada, de donde fue extraído después de largas tramitaciones y formal resistencia del prelado."}, {"type": "p", "text": "D. Juan Bautista de Lavalle fue el primer alcalde ordinario que tuvo Lima por elección del pueblo. La Constitución dictada por las Cortes españolas en 1812, otorgó a las colonias esta liberal prerrogativa. Encomendada la causa al Sr. de Lavalle, éste desplegó gran celo y actividad para su pronta terminación; y cuatro meses más tarde la Real Audiencia aprobaba y mandaba ejecutar la sentencia. Vanos fueron los argumentos que en su favor expuso el reo, a quien por primera vez en Lima se permitió hablar ante los tribunales. La conciencia pública, en la que domina una mayoría de partidarios de la ley del talión, exigía el castigo del asesino; y cuando se temió que la influencia y el indisputable talento de D. Jerónimo Vivar, abogado chileno y defensor del reo, hicieran vacilar a los jueces, empezaron a aparecer pasquines en las fachadas del cabildo y del palacio. He aquí uno de ellos:"}, {"type": "p", "text": "«¿Sabes qué harán con Cebada?"}, {"type": "p", "text": "¡Nada! ¡Nada! ¡Nada! ¡Nada!»."}, {"type": "p", "text": "La defensa de Vivar, que corre impresa, basta por sí sola para formar la reputación literaria de un hombre. Es una pieza elocuente y galana en la forma."}, {"type": "p", "text": "Copiemos otro de los pasquines que tuvimos la fortuna de hallar en el curioso archivo del Sr. Odriozola:"}, {"type": "p", "text": "«Si una traición desvelada"}, {"type": "p", "text": "contra inocencia dormida"}, {"type": "p", "text": "en tiempo no es castigada,"}, {"type": "p", "text": "muy lejos de arrepentida"}, {"type": "p", "text": "siempre quedará... cebada»."}, {"type": "p", "text": "En el mismo sitio en que apareció el anterior, los amigos del reo, para despertar la clemencia de los jueces, colocaron otra quintilla de iguales consonantes: «La justicia desvelada"}, {"type": "p", "text": "por la inocencia dormida,"}, {"type": "p", "text": "no quiere sea castigada"}, {"type": "p", "text": "la culpa, si arrepentida"}, {"type": "p", "text": "puede quedar no cebada.»"}, {"type": "p", "text": "Y por fin en la pared de uno de los corredores de palacio se leía este pareado, escrito con carbón:"}, {"type": "p", "text": "«¡Abascal! ¡Abascal!"}, {"type": "p", "text": "Si ahorcas a Cebada te irá mal»."}, {"type": "p", "text": "Cuentan que la última comedia que representara Rafael en nuestro coliseo fue la titulada El juez compasivo, y que aludiendo a ella el señor de Lavalle, al tomar al reo la declaración instructiva le dijo: «Vengo a representar, a la de veras, el último papel que hizo usted en el teatro»."}]$lira$::jsonb, 534);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 33, 'VIII', $lira$[{"type": "p", "text": "La espléndida defensa de Vivar, unánimemente aplaudida, no alcanzó a torcer la disposición de la ley ni a disminuir en el pueblo la odiosidad contra el amante de María Moreno, que al cabo fue puesto en capilla el jueves 26 de enero de 1815. El 28 a la una del día salió de la cárcel resignado y valiente.—Fue el segundo y el último a quien el verdugo dio en Lima muerte de garrote."}]$lira$::jsonb, 73);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 34, 'IX', $lira$[{"type": "p", "text": "Cuando el gentío empezó a despejar la plaza, el sacerdote que había acompañado al reo se bajó la capucha, se arrodilló ante el cadáver y principió a amortajarlo murmurando: «¡Pobre Rafael! Tu sueño de Salamanca fue la revelación de tu destino... Se ha cumplido para los dos... ¡Estaba escrito!»."}, {"type": "p", "text": "Aquel religioso se llamaba fray Antonio Espejo."}, {"type": "p", "text": "Dos millones El 16 de julio de 1826 fue día de gran agitación en Lima y el Callao. Por todas partes se encontraban grupos en animada charla. No era en verdad un cataclismo ni un gran acontecimiento político lo que motivaba esta excitación, sino la noticia de haber desaparecido del fondeadero el bergantín inglés Peruvian, cargado con dos millones de pesos en oro, barras de plata y moneda sellada."}, {"type": "p", "text": "El buque debía zarpar en ese día para Europa; pero su capitán había ido la víspera a Lima a recibir las últimas instrucciones de sus armadores, permitiendo también a varios de los tripulantes que pasasen la noche en tierra."}, {"type": "p", "text": "En el Peruvian se encontraban sólo el piloto y seis marineros, cuando a las dos de la madrugada fue abordado por una lancha con trece hombres, los que procedieron con tal cautela y rapidez, que la ronda del resguardo no pudo advertir lo que acontecía. Inmediatamente levaron ancla, y el Peruvian se hizo a la vela."}, {"type": "p", "text": "A las tres de la tarde, un bote del Peruvian llegó a Callao conduciendo al piloto y sus seis marineros, puestos en libertad por los piratas."}, {"type": "p", "text": "La historia del audaz jefe de esta empresa y el éxito del tesoro que contenía el Peruvian es lo que hoy nos proponemos narrar rápidamente, remitiendo al lector que anhele mayor copia de datos a la hora del capitán Lafond, titulada Voyages dans les Amériques."}, {"type": "p", "text": "Por los años de 1817 un joven escocés, de aire bravo y simpático, se presentó a las autoridades de Valparaíso solicitando un puesto en la marina de Chile, y comprobando que había servido como aspirante en la armada real de Inglaterra. Destinado de oficial en uno de los buques, el joven Robertson se distinguió en breve por su pericia en la maniobra y su coraje en los combates. El esforzado Guisse, que mandaba el bergantín Galvarino, pidió a Robertson para su primer teniente."}, {"type": "p", "text": "Era Robertson valiente hasta el heroísmo, de mediana estatura, rojizos cabellos y penetrante mirada. Su carácter fogoso y apasionado lo arrastraba a ser feroz. Pero eso, en 1822, cuando al mando de un bergantín chileno tomó prisioneros setenta hombres de la banda realista de Benavídez, los hizo colgar de las ramas de los árboles. No es éste un artículo a propósito para extendernos en la gloriosa historia de las hazañas navales que Cochrane y Guisse realizaron contra la formidable escuadra española."}, {"type": "p", "text": "En el encuentro de Quilca, entre la Quintanilla y el Congreso, Robertson, que había cambiado la escarapela chilena por la de Perú y que a la sazón tenía el grado de capitán de fragata, fue el segundo comandante del bergantín que mandaba el valiente Young."}, {"type": "p", "text": "En el famoso sitio del Callao, cuyas fortalezas eran defendidas por el general español Rodil, quien se sostuvo en ellas trece meses de la batalla de Ayacucho, cupo a Robertson ejecutar muy distinguidas acciones."}, {"type": "p", "text": "Todo le hacía esperar un espléndido porvenir, y acaso habría alcanzado el alto rango de almirante si el diablo, en forma de una linda limeña, no se hubiera encargado de perderlo. Dijo bien el que dijo que el amor es un envenenamiento del espíritu. Teresa Méndez era en 1826 una preciosa joven de veintiún años, de ojos grandes, negros, decidores, labios de fuego, brevísima cintura, hechicero donaire, todas las gracias, en fin, y perfecciones que han hecho proverbial la belleza de las limeñas. Parece que me explico, picarillas, y que soy lo que se llama un cronista galante. Viuda de un rico español, se había despertado en ella la fiebre del lujo, y su casa se convirtió en el centro de la juventud elegante. Teresa Méndez hacía y deshacía la moda."}, {"type": "p", "text": "Su felicidad consistía en tiranizar a los cautivos que suspiraban presos en el Argel de sus encantos. Jamás pudo amartelado galán vanagloriarse de haber merecido de ella favores que revelan predilección por un hombre. Teresa era una mezcla de ángel y demonio, una de aquellas mujeres que nacieron para ejercer autocrático despotismo sobre los que las rodean; en una palabra, pertenecía al número de aquellos seres sin corazón que Dios echó al mundo para infierno y condenación de hombres."}, {"type": "p", "text": "Roberto conoció a Teresa Méndez en la procesión del Corpus, y desde ese día el arrogante marino la echó bandera de parlamento, se puso al habla con ella, y se declaró buena presa de la encantadora limeña. Ella empleó para con el nuevo adorador la misma táctica que para con los otros, y un día en que Roberto quiso pecar de exigente, obtuvo de los labios de cereza de la joven este categórico ultimátum:"}, {"type": "p", "text": "—Pierde usted su tiempo, comandante. Yo no perteneceré sino al hombre que sea grande por su fortuna o por su posición, aunque su grandeza sea hija del crimen. Viuda de un coronel, no acepto a un simple comandante."}, {"type": "p", "text": "Robertson se retiró despechado, y en su exaltación confió a varios de sus camaradas el éxito de sus amores."}, {"type": "p", "text": "Pocas noches después tomaba té en casa del capitán de puerto del Callao, en unión de otros marinos, y como la conversación rodase sobre la desdeñosa limeña, uno de los oficiales dijo en tono de chanza:"}, {"type": "p", "text": "—Desde que la guerra con los chapetones ha concluido no hay esperanza de que el comandante logre enarbolar la insignia del almirantazgo. En cuanto a hacer fortuna, la ocasión se le viene a la mano. Dos millones de pesos hay a bordo de un bergantín. Robertson pareció no dar importancia a la broma, y se limitó a preguntar:"}, {"type": "p", "text": "—Teniente Vieyra, ¿cómo dice usted que se llama ese barco que tiene millones por lastre?"}, {"type": "p", "text": "—El Peruvian, bergantín inglés."}, {"type": "p", "text": "—Pues poca plata es, porque más vale Teresa —repuso el comandante, y dio sesgo distinto a la conversación."}, {"type": "p", "text": "Tres horas después Robertson era dueño del tesoro embarcado en el Peruvian."}]$lira$::jsonb, 1018);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 35, 'II', $lira$[{"type": "p", "text": "Al salir de la casa de capitán de puerto, Robertson se había dirigido a una posada de marineros y escogido entre ellos doce hombres resueltos y que le eran personalmente conocidos por haberlos manejado a bordo del Galvarino y del Congreso."}, {"type": "p", "text": "Realizado el abordaje, pensó el pirata que no le convenía hacer partícipes a tantos cómplices de los millones robados, y resolvió no detenerse en la senda del crimen a fin de eliminarlos. Asoció a su plan a dos irlandeses, Jorge y Guillermo, e hizo rumbo a Oceanía."}, {"type": "p", "text": "En la primera isla que encontraron desembarcó con algunos marineros, se encenagó con ellos en los desórdenes de un lupanar, y ya avanzada la noche regresó con todos a bordo. El vino había producido su efecto en esos desventurados. El capitán los dejó durmiendo en la chalupa, levó ancla, y cuando el bergantín se hallaba a treinta millas de la costa, cortó la amarra, abandonando seis hombres en pleno y embravecido Océano."}, {"type": "p", "text": "Además de los dos irlandeses, sólo había perdonado, por el momento, a cuatro de los tripulantes que le eran precisos para la maniobra."}, {"type": "p", "text": "Entonces desembarcó y enterró el tesoro en la desierta isla de Agrigán, y con sólo treinta mil pesos en oro se dirigió en el Peruvian a las islas Sandwich. En esta travesía, una noche dio a beber un narcótico a los marineros, los encerró en la bodega y barrenó el buque. Al día siguiente, en un bote arribaron a la isla de Wahou, Robertson, Guillermo y Jorge, contando que el buque había zozobrado."}, {"type": "p", "text": "La Providencia lo había dispuesto de otro modo. El Peruvian tardó mucho tiempo en sumergirse, y encontrado por un buque ballenero, fue salvado uno de los cuatro tripulantes; pues sus compañeros habían sucumbido al hambre y la sed."}, {"type": "p", "text": "De Wahou pasaron los tres piratas a Río Janeiro. En esta ciudad desapareció para siempre el irlandés Jorge, víctima de sus compañeros."}, {"type": "p", "text": "Después de peregrinar por Sidney, pasaron a Hobartoun, capital de Van-Diemen. Allí propusieron a un viejo inglés, llamado Thompson, patrón de una goletilla pescadora, que los condujese a las islas Marianas. La goleta no tenía más que dos muchachos de tripulación, y Thompson aceptó la propuesta."}, {"type": "p", "text": "El viaje fue largo y sembrado de peligros. El calor era excesivo, y los cinco habitantes de la goleta dormían sobre el puente. Una noche, después de haberse embriagado todos menos Robertson, a quien tocaba la guardia, cayó Guillermo al mar. El viejo Thompson despertó a los desesperados gritos que éste daba. Robertson fingió esforzarse para socorrerlo; pero la obscuridad, la corriente y la carencia de bote hicieron imposible todo auxilio."}, {"type": "p", "text": "Robertson quedaba sin cómplice, mas le eran indispensables los servicios de Thompson. No le fue difícil inventar una fábula, revelando a medias su secreto al rudo patrón de la goleta y ofreciéndole una parte del tesoro."}, {"type": "p", "text": "Al tocar en la isla Tinián para procurarse víveres, el capitán de una fragata española visitó la goleta. Súpolo Robertson, al regresar de tierra, y receló que el viejo hubiese hablado más de lo preciso."}, {"type": "p", "text": "Apenas se desprendía de la rada la embarcación, cuando Robertson, olvidando su habitual prudencia, se lanzó sobre el viejo patrón y lo arrojó al agua."}, {"type": "p", "text": "Robertson ignoraba que se las había con un lobo marino, excelente nadador. Pocos días después la fragata española, a cuyo bordo iba el viejo Thompson, descubría a la goletilla pescadora oculta en una ensenada de Saipán."}, {"type": "p", "text": "Preso Robertson, nada pudo alcanzarse de él con sagacidad, y el capitán español dispuso entonces que fuese azotado sobre cubierta."}, {"type": "p", "text": "Eran transcurridos cerca de dos años, y las gacetas todas de Europa habían anunciado la desaparición del Peruvian, acusando al comandante Robertson. El marinero milagrosamente salvado en Wahou había también hecho una extensa declaración. Los armadores ingleses y el almirantazgo ofrecían buena recompensa al que capturase al pirata. El crimen del aventurero escocés había producido gran ruido e indignación. Cuando iba a ser flagelado, pareció Robertson mostrarse más razonable. Convino en conducir a sus guardianes al sitio donde tenía enterrados los dos millones; pero al poner el pie en la borda del bote, se arrepintió de su debilidad y se dejó caer al fondo del mar, llevándose consigo su secreto."}]$lira$::jsonb, 695);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 36, 'III (1/2)', $lira$[{"type": "p", "text": "Una noticia importante, por vía de conclusión, para los que aspiren a salir de pobres. La isla de Agrigán, en las Marianas, está situada en la latitud Norte 19º 0', longitud al Este del meridiano de París 142º 0'."}, {"type": "p", "text": "Dos millones no son para despreciados."}, {"type": "p", "text": "Conque así, lectores míos, buen ánimo, fe en Dios y a las Marianas, sin más equipaje. Las cayetanas"}, {"type": "p", "text": "Arma atroz es el ridículo, y tanto que, hasta tratándose de las cosas buenas, puede ser matadora."}, {"type": "p", "text": "Por los años de 1704, un clérigo filipense, nombrado D. Gregorio Cabañas, empleó ochenta mil pesos, de su peculio y limosnas de los fieles, en la fundación de un beaterio, mientras conseguía de Roma y del monarca español las respectivas licencias para elevarlo a la categoría de monasterio. Todo iba a pedir de boca para el entusiasta padre Cabañas, que contaba con influencias en la aristocracia y con la buena voluntad del católico pueblo. El siglo era de fundaciones monásticas, y los habitantes de esta ciudad de los reyes soñaban con la dicha de poseer, ya que no una iglesia, siquiera una capilla en cada calle."}, {"type": "p", "text": "Frecuente era entonces leer sobre el portal o arco del zaguán de las casas, y en gordos caracteres, esta inscripción u otras parecidas: Alabado sea el Santísimo Sacramento, lo que daba a los edificios un no sé qué de conventual."}, {"type": "p", "text": "Los vecinos de Abajo el Puente, que no tenían en su circunscripción ningún monasterio, eran los que más empeño tomaban para que el proyecto del padre Gregorio fuese en breve realidad."}, {"type": "p", "text": "Por fin, inaugurose la fundación con diez y seis beatas, número suficiente para prometerse rápido progreso y despertar la envidia de los otros beaterios y aun de las monjas."}, {"type": "p", "text": "Pero cuando empezaron a salir a la calle las cayetanas o teatinas, los muchachos dieron en rechiflarlas, y las vecinas en reírse del hábito que vestían las nuevas beatas. Francamente, que el padre Gregorio anduvo desacertado en la elección de uniforme para sus hijas de espíritu."}, {"type": "p", "text": "Con decir que el hábito de las cayetanas era una sotana de clérigo, digo lo bastante para justificar el ridículo que cayó sobre esas benditas. Usaban el pelo recortado a la altura del hombro y llevaban sombrero de castor. Lucían además una cadeneta de acero al cuello y pendiente de ella un corazón, emblema del de Jesús."}, {"type": "p", "text": "Tales prójimas eran en la calle un mamarracho, un reverendo adefesio."}, {"type": "p", "text": "No pasó un año sin que todas hubiesen desertado, colgando la sotana, cansadas de oír cantar a los muchachos:"}, {"type": "p", "text": "«Con maitines y completas,"}, {"type": "p", "text": "No son lanzas ni chancletas,"}, {"type": "p", "text": "Cayetanas"}, {"type": "p", "text": "Candidonas,"}, {"type": "p", "text": "Con sotanas"}, {"type": "p", "text": "Como monas."}, {"type": "p", "text": "Aunque canten misereres,"}, {"type": "p", "text": "No son hombres ni mujeres,"}, {"type": "p", "text": "Más pelonas"}, {"type": "p", "text": "Que las ranas,"}, {"type": "p", "text": "Candidonas"}, {"type": "p", "text": "Cayetanas»."}, {"type": "p", "text": "Todos los esfuerzos del padre Cabañas por llevar adelante la fundación, se estrellaron ante el ridículo popular; y seis años después, en 1711, tuvo que ceder el local y rentas a los padres mínimos de San Francisco de Paula."}, {"type": "p", "text": "Desde entonces fue estribillo entre las limeñas (estribillo que muchos de mis lectores habrán oído en boca de las viejas) el decir, para calificar de necia o de tonta a una mujer:"}, {"type": "p", "text": "«¿Quién lo dice? ¿Fulana?"}, {"type": "p", "text": "»No le hagas caso, es una... cayetana»."}, {"type": "p", "text": "Los endiablados Pepo Irasusta y Pancho Arellano eran amigos de uña y carne, de cama y rancho. De repente, el pueblo dio en decir que habían hecho pacto con el demonio; y hoy mismo, al hablar de ellos, los llama los Endiablados."}, {"type": "p", "text": "¿Por qué? Esto es lo que el relato popular va a explicarnos."}, {"type": "p", "text": "Entretanto, lector, si te ocurre dar un paseo por San Jerónimo de Ica, hasta las piedras te referirán lo que hoy, alterando nombres por razones que yo me sé, ofrece tema a mi péñola. Añadiré también, para poner fin al introito, que viven todavía en la ciudad de Valverde muchísimas personas que en el decenio de 1830 a 1840 conocieron y trataron a los héroes de esta conseja o sucedido."}]$lira$::jsonb, 655);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 37, 'III (2/2)', $lira$[{"type": "p", "text": "Pancho Arellano era un indio cobrizo, que ganaba el pan de cada día, manejando una pala como peón caminero o mozo de labranza en un viñedo. El infeliz echaba los bofes trabajando de seis a seis para adquirir un salario de dos a tres pesetas e ir pasando la vida a tragos. Parecía destinado a nunca salir de pobre, pues ni siquiera había en él artimaña para constituirse jefe de club eleccionario, ni hígados para capitanear una montonera, cargos que suelen dejar el riñón cubierto."}, {"type": "p", "text": "Un día abandonó Arellano la lampa, y sin que nadie atinara a saber de dónde había sacado dinero, echose a dar plata sobre prendas con el interés judaico de veinticinco por ciento. Y fuele tan propiciamente, en oficio que requiere tener las entrañas de Caín y la socarronería de Judas, que, a poco hacer, se encontró rico como el más acaudalado del lugar."}, {"type": "p", "text": "En medio de su bienandanza, lo único que le cascabeleaba al antiguo patán era que el pueblo le negase el Don; pues grandes y pequeños, lo llamaban Ño Pancho el de la esquina."}, {"type": "p", "text": "—Esto no puede soportarse —se dijo una noche en que estaba desvelado—, es preciso que me reciba de caballero."}, {"type": "p", "text": "Y al efecto, empleó dos meses en preparativos para dar en su casa un gran sarao, al que invitó a todo lo más granado de la sociedad iqueña."}, {"type": "p", "text": "El usurero, picado por el demonche de la vanidad, desató los cordones de la bolsa, gastando algunos miles de pesos en muebles y farolerías que hizo traer de Lima. La fiesta fue de lo más espléndido que cabe. Digo bastante con decir que para asistir a ella emprendieron viaje desde la capital de la república un general, tres diputados a Congreso, el cónsul de su majestad Kamahameha IV, un canónigo, un poeta periodista y varias otras notabilidades."}, {"type": "p", "text": "Terminado el festejo, que duró ocho días, en los que Arellano echó la casa por la ventana para tratar a sus convidados a cuerpo de rey, quedó ejecutoriada su decencia, y todo títere empezó a llamarlo don Francisco. Era ya un caballero hecho y derecho, por mucho que los envidiosos de tan improvisada ascendencia le aplicarán la redondilla:"}, {"type": "p", "text": "«¡Qué hinchado y qué fanfarrón"}, {"type": "p", "text": "entre las ramas habita!"}, {"type": "p", "text": "Pues sepan que fue pepita,"}, {"type": "p", "text": "aunque ya lo ven melón»."}, {"type": "p", "text": "Pasaban los años, aumentaba la riqueza de D. Francisco, y disfrutaba de la general consideración, que en este mundo bellaco alcanza a conquistarse todo el que tiene su pie de altar bien macizo."}, {"type": "p", "text": "Nadie paraba mientes en que el ricacho no cumplía ninguna de las prácticas de buen cristiano, y que lejos de eso, la daba de volteriano, hablando pestes del Papa y de los santos. Mas de la noche a la mañana se le vio confesar muy compungido en la iglesia de San Francisco, hacerse aplicar recios cordonazos por los frailes, beber cántaros de agua bendita y cubrirse el cuerpo de cilicios y escapularios."}, {"type": "p", "text": "Ítem, decía a grito herido que era muy gran pecador, y que el Malo estaba empeñado en llevárselo en cuerpo y alma."}, {"type": "p", "text": "De aquí sacaban en limpio las comadres de Ica, caminando de inducción en inducción, que Arellano para salir de pobre había hecho pacto con el diablo; y que estando para cumplirse el plazo, se le hacía muy cuesta arriba pagar la deuda."}, {"type": "p", "text": "Es testimonio unánime de los que asistieron a los funerales de don Francisco que en la caja mortuoria no había cadáver, porque el diablo cargó hasta con el envoltorio del alma."}]$lira$::jsonb, 582);
insert into public.chapters (book_id, position, title, body, word_count)
values ('tradiciones-peruanas', 38, 'II', $lira$[{"type": "p", "text": "Pepe Irasusta había sido un bravo militar que, cansado de la vida de cuartel colgó el chopo y se estableció en Ica. Aunque no vareaba la plata como su compadre y amigo Arellano, gozaba de cómoda medianía."}, {"type": "p", "text": "Por aquellos años, como hoy mismo, era fray Ramón Rojas (generalmente conocido por el padre Guatemala) la idolatría de los iqueños. Muerto en olor de santidad en julio de 1839, necesitaríamos escribir un libro para dar idea de sus ejemplares virtudes y de los infinitos milagros que le atribuyen."}, {"type": "p", "text": "Irasusta, que hacía alarde de no tener creencias religiosas, dijo un día en un corro de monos bravos y budingas:"}, {"type": "p", "text": "—Desengañarse, amigos. Ese padre Guatemala es un cubiletero que los trae a ustedes embaucados hablándoles de la otra vida. Eso de que haya otro mundo es"}, {"type": "p", "text": "pampirolada; pues los hombres no pasamos de ser como los relojes, que rota la cuerda, ¡crac!, san se acabó."}, {"type": "p", "text": "—Otra cosa dirá usted, D. Pepe, cuando le ronque la olla, que más guapos que usted he visto en ese trance clamar por los auxilios de la iglesia —arguyó uno de los presentes."}, {"type": "p", "text": "—Pues sépase usted, mi amigo, que yo ni después de muerto quiero entrar en la iglesia —insistió Irasusta."}, {"type": "p", "text": "Era la noche del miércoles santo, e Irasusta se sintió repentinamente atacado de un cólico miserere tan violento que, cuando llegó a su lecho el físico para propinarle alguna droga, se encontró con que nuestro hombre había cesado de resollar. No permitiendo el ritual que en jueves ni viernes santo se celebren funerales de cuerpo presente, ni siendo posible soportar la descomposición del cadáver, resolvieron los deudos darle inmediata sepultura en el panteón."}, {"type": "p", "text": "Así quedó cumplida la voluntad del que, ni después de muerto, quería entrar en la casa de Dios."}, {"type": "p", "text": "Pocos días después, en la iglesia de San Francisco y con crecida concurrencia de amigos celebrábanse honras fúnebres por el finado Irasusta."}, {"type": "p", "text": "En el centro de la iglesia y sobre una cortina negra leíase en grandes letras cortadas de un pedazo de género blanco:"}, {"type": "h", "text": "¡¡¡José Irasusta!!!"}, {"type": "p", "text": "En los momentos en que el sacerdote oficiante iba a consagrar la Hostia divina, desprendiose un cirio de la cornisa del templo e incendió la cortina. Los sacristanes y monagos se lanzaron presurosos a impedir que se propagase el fuego; pero a pesar de su actividad, no alcanzaron a evitar que gran parte de la cortina fuese devorada. Cuando se desvaneció el peligro, todos los concurrentes se fijaron en la cortina y vieron con terror que las llamas habían consumido las seis primeras letras de la inscripción, respetando las que forman esta palabra:"}, {"type": "h", "text": "Asusta!!!"}, {"type": "p", "text": "Aquí asustado el cronista, tanto como los espectadores, suelta la pluma, dejando al lector en libertad de hacer a sus anchas los comentarios que su religiosidad le inspire."}]$lira$::jsonb, 461);

