insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('paco-yunque', 'Paco Yunque', 'César Vallejo', 'El primer día de colegio de un niño pobre que entra a un aula donde el hijo del patrón manda hasta sobre el profesor.', 'cuento', 7, 38, array['perú', 'colegio', 'injusticia']::text[], true)
on conflict (id) do update set
  title = excluded.title, author = excluded.author,
  synopsis = excluded.synopsis, category = excluded.category,
  chapter_count = excluded.chapter_count,
  minutes_to_read = excluded.minutes_to_read,
  tags = excluded.tags, is_published = true;

insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 0, 'Parte 1 (1/7)', $lira$[{"type": "p", "text": "aco Yunque"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "Ilustraciones de"}, {"type": "p", "text": "Alicia Garavito"}, {"type": "p", "text": "cc ii"}, {"type": "p", "text": "rr"}, {"type": "p", "text": "ccuullaacciióó"}, {"type": "p", "text": "nn"}, {"type": "p", "text": "lliibbrroo aall"}, {"type": "p", "text": "vviieennttoo"}, {"type": "p", "text": "gg aa"}, {"type": "p", "text": "rraattuuii tt UUnnaa ccaammppaaññaa ddee ffoommeennttoo a la lectura de la secretaría de cultura, recreación y deporte y el instituto distrital"}, {"type": "p", "text": "de las artes – idartes"}, {"type": "p", "text": "Este ejemplar de Libro al Viento es un bien público. Después de leerlo permita que circule entre los demás lectores. l i br o a l v i e n t o i n i c i a l"}, {"type": "h", "text": "Aco Yunque"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "alcaldía mayor de bogotá"}, {"type": "p", "text": "Claudia Nayibe López Hernández, Alcaldesa Mayor de Bogotá Secretaría de Cultura, Recreación y Deporte Nicolás Francisco Montero Domínguez, Secretario de Cultura, Recreación y Deporte instituto distrital de las artes – idartes Catalina Valencia Tobón, Directora General Astrid Liliana Angulo Cortés, Subdirectora de las Artes Mauricio Galeano Vargas, Subdirector de Equipamientos Culturales Leyla Castillo Ballén, Subdirectora de Formación Artística Adriana María Cruz Rivera, Subdirectora Administrativa y Financiera Adriana Martínez–Villalba García, Gerente de Literatura Carlos Ramírez Pérez, Olga Lucía Forero Rojas, Ricardo Ruiz Roa, María Camila Jaramillo Laverde, María Eugenia Montes Zuluaga, Yenny Mireya Benavídez Martínez, Óscar Javier Gamboa Arévalo. Equipo del Área de Literatura Primera edición: Bogotá, noviembre de 2020 Todos los derechos reservados. Esta obra no puede ser reproducida, parcial o totalmente, por ningún medio de reproducción, sin consentimiento escrito del editor. Imagen carátula e ilustraciones internas: Alicia Garavito © Instituto Distrital de las Artes – Idartes © Fredy Ordóñez, por la presentación Fredy Ordóñez, edición"}, {"type": "p", "text": "Paula Andrea Gutiérrez Roldán, diseño y diagramación 978-958-5595-44-6, isbn"}, {"type": "p", "text": "Formas e Impresos, Impresión Impreso en Colombia"}, {"type": "p", "text": "Gerencia de Literatura Idartes Carrera 8 n.o 15-46"}, {"type": "p", "text": "Bogotá D. C."}, {"type": "p", "text": "Teléfono: 3795750"}, {"type": "p", "text": "www.idartes.gov.co"}, {"type": "p", "text": "contactenos@idartes.gov.co"}, {"type": "p", "text": "f @LibroAlViento t @LibroAlViento"}, {"type": "h", "text": "Presentación"}, {"type": "p", "text": "Este es el relato del primer día de colegio de Paco Yunque. Es una jornada difícil para él, y la sobrelleva con aprensión, miedo y asombro: “¡Qué cosa extraña era estar en el colegio!». Y a la abrumadora realidad a la que se enfrenta, Paco Yunque debe sortear el mismo hecho que lo lleva a ese colegio: acompañar al hijo de la patrona de su mamá. A lo largo del cuento, no se hacen esperar las injusticias, saltan a la vista los desequilibrios sociales y se asoman providenciales gestos de camaradería. Casi que “Paco Yunque” se podría resumir en esos aspectos, pero los cuentos, los buenos cuentos, en realidad no se pueden resumir y más bien tienen la capacidad de renovarse contiFredy Ordóñez"}, {"type": "p", "text": "nuamente a través del tiempo y gracias a las experiencias de cada lector —que un día fue también un niño que entró por primera vez a una clase o fue un alumno tratado injustamente por un profesor—."}, {"type": "p", "text": "César Vallejo, el autor de este cuento, nace en 1892, en Santiago de Chuco, un pueblo a más de tres mil metros en la Cordillera de los Andes en Perú; estudia Letras en la Universidad de Trujillo y se gradúa en 1915 con una tesis sobre el romanticismo en la poesía española; publica los libros de poemas Los Heraldos Negros, en 1919, y Trilce, en 1922 —quizás el relumbrón más desconcertante del canon poético latinoamericano del siglo XX—; un año después se embarca y se dirige a París (Francia); en 1928 viaja por primera vez a la URSS, pero regresa ese mismo año a la capital francesa; en 1930, por su filiación política, es expulsado de Francia; se va a Madrid (España) pero vuelve clandestinamenpresentación"}, {"type": "p", "text": "te a Francia en 1932; nunca para de escribir —poemas, columnas, novelas, cuentos, obras de teatro, reportajes, artículos— y nunca vuelve a Perú; y, como tocado por un don oscuro, murió en París, esa ciudad que ya anunciaba un verso suyo: “Me moriré en París con aguacero, / un día del cual tengo ya el recuerdo”. Valga subrayar un hecho: “Paco Yunque” es una rareza dentro de obra; es su único cuento infantil, y al tiempo es una denuncia social; lo escribió en 1931, en un momento de su vida en el que sintió especialmente el deber vital de contribuir a las luchas sociales, se unió al partido comunista, escribió El tungsteno —una novela proletaria— y publicó su reportaje Rusia en 1931; escribió ese año: “Comparto mi vida entre la inquietud política y social y mi inquietud introspectiva y personal, y mía para adentro”. Aunque nunca fue publicado en vida y se encuentre lejos de los búsquedas lingüísticas que caracterizaron su obra poétiFredy Ordóñez"}, {"type": "p", "text": "ca, César Aira no dudó en llamar a este cuento, narrado con depurada sencillez, una obra maestra."}, {"type": "p", "text": "Fredy Ordóñez"}, {"type": "h", "text": "Aaccoo Yyuunnqquuee"}, {"type": "p", "text": "Cuando Paco Yunque y su madre llegaron a la puerta del colegio, los niños estaban jugando en el patio. La madre le dejó y se fue. Paco, paso a paso, fue adelantándose al centro del patio, con su libro primero, su cuaderno y su lápiz. Paco estaba con miedo, porque era la primera vez que veía a un colegio; nunca había visto a tantos niños juntos. Varios alumnos, pequeños como él, se le acercaron y Paco, cada vez más tímido, se pegó a la pared, y se puso colorado. ¡Qué listos eran todos esos chicos! ¡Qué desenvueltos! Como si estuviesen en su casa. Gritaban. Corrían. Reían hasta reventar. Saltaban. Se daban de puñetazos. Eso era un enredo. César Vallejo"}, {"type": "p", "text": "Paco estaba también atolondrado porque en el campo no oyó nunca sonar tantas voces de personas a la vez. En el campo hablaba primero uno, después otro, después otro y después otro. A veces, oyó hablar hasta cuatro o cinco personas juntas. Era su padre, su madre, don José, el cojo Anselmo y la Tomasa. Eso no era ya voz de personas sino otro ruido. Muy diferente. Y ahora sí que esto del colegio era una bulla fuerte, de muchos. Paco estaba asordado."}, {"type": "p", "text": "Un niño rubio y gordo, vestido de blanco, le estaba hablando. Otro niño más chico, medio ronco y con blusa azul, también le hablaba. De diversos grupos se separaban los alumnos y venían a ver a Paco, haciéndole muchas preguntas. Pero Paco no podía oír nada por la gritería de los demás. Un niño trigueño, cara redonda y con una chaqueta verde muy ceñida en la cintura agarró a Paco por un brazo y quiso arrastrarlo. Pero Paco no se dejó. El trigueño volvió a agarrarlo con más fuerza y César Vallejo"}, {"type": "p", "text": "lo jaló. Paco se pegó más a la pared y se puso más colorado."}, {"type": "p", "text": "En ese momento sonó la campana, y todos entraron a los salones de clase. Dos niños —los hermanos Zumiga— tomaron de una y otra mano a Paco y le condujeron a la sala de primer año. Paco no quiso seguirlos al principio, pero luego obedeció, porque vio que todos hacían lo mismo. Al entrar al salón se puso pálido. Todo quedó repentinamente en silencio y este silencio le dio miedo a Paco. Los Zumiga le estaban jalando, el uno para un lado y el otro para el otro lado, cuando de pronto le soltaron y lo dejaron solo. El profesor entró. Todos los niños estaban de pie, con la mano derecha levantada a la altura de la sien, saludando en silencio y muy erguidos."}]$lira$::jsonb, 1185);
insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 1, 'Parte 1 (2/7)', $lira$[{"type": "p", "text": "Paco, sin soltar su libro, su cuaderno y su lápiz, se había quedado parado en medio del salón, entre las primeras carpetas de los alumnos y el pupitre del profesor. Un remolino se Paco Yunque"}, {"type": "p", "text": "le hacía en la cabeza. Niños. Paredes amarillas. Grupos de niños. Vocerío."}, {"type": "p", "text": "Silencio. Una tracalada de sillas. El profesor. Ahí, solo, parado, en el colegio. Quería llorar. El profesor le tomó de la mano y lo llevó a instalar en una de las carpetas delanteras junto a un niño de su mismo tamaño. El profesor le preguntó:"}, {"type": "p", "text": "—¿Cómo se llama usted?"}, {"type": "p", "text": "Con voz temblorosa, Paco muy bajito:"}, {"type": "p", "text": "—Paco."}, {"type": "p", "text": "—¿Y su apellido? Diga usted todo su nombre."}, {"type": "p", "text": "—Paco Yunque."}, {"type": "p", "text": "—Muy bien."}, {"type": "p", "text": "El profesor volvió a su pupitre y, después de echar una mirada muy seria sobre todos los alumnos, dijo con voz militar:"}, {"type": "p", "text": "—¡Siéntense!"}, {"type": "p", "text": "Un traqueteo de carpetas y todos los alumnos ya estaban sentados. El profesor también se sentó y durante unos momentos escribió en unos libros. Paco Yunque Paco Yunque"}, {"type": "p", "text": "tenía aún en la mano su libro, su cuaderno y su lápiz. Su compañero de carpeta le dijo:"}, {"type": "p", "text": "—Pon tus cosas, como yo, en la carpeta. Paco Yunque seguía muy aturdido y no le hizo caso. Su compañero le quitó entonces sus libros y los puso en la carpeta. Después, le dijo alegremente:"}, {"type": "p", "text": "—Yo también me llamo Paco, Paco Fariña. No tengas pena. Vamos a jugar con mi tablero. Tiene torres negras. Me lo ha comprado mi tía Susana. ¿Dónde está tu familia, la tuya? Paco Yunque no respondía nada. Este otro Paco le molestaba. Como éste eran seguramente todos los demás niños: habladores, contentos y no les daba miedo el colegio. ¿Por qué eran así? Y él, Paco Yunque, ¿por qué tenía tanto miedo? Miraba a hurtadillas al profesor, al pupitre, al muro que había detrás del profesor y al techo. También miró de reojo, a través de la ventana, al patio, que estaba ahora abandonado y en silencio. El sol brillaba afuera. De cuando en cuando, llegaban voces de César Vallejo"}, {"type": "p", "text": "otros salones de clase y ruidos de carretas que pasaban por la calle."}, {"type": "p", "text": "¡Qué cosa extraña era estar en el colegio! Paco Yunque empezaba a volver un poco de su aturdimiento. Pensó en su casa y en su mamá. Le preguntó a Paco Fariña:"}, {"type": "p", "text": "—¿A qué hora nos iremos a nuestras casas?"}, {"type": "p", "text": "—A las once. ¿Dónde está tu casa?"}, {"type": "p", "text": "—Por allá."}, {"type": "p", "text": "—¿Está lejos?"}, {"type": "p", "text": "—Sí… No…"}, {"type": "p", "text": "Paco Yunque Paco Yunque no sabía en qué calle estaba su casa, porque acababan de traerlo, hacía pocos días, del campo y no conocía la ciudad. Sonaron unos pasos de carrera en el patio, apareció en la puerta del salón Humberto, el hijo del señor Dorian Grieve, un inglés, patrón de los Yunque, gerente de los ferrocarriles de la Peruvian Corporation y alcalde del pueblo. Precisamente a Paco le habían hecho venir del campo para que acompañase al colegio a Humberto y para que jugara con él, pues ambos tenían la misma edad. Sólo que Humberto acostumbraba venir tarde al colegio y esta vez, por ser la primera, la señora Grieve le había dicho a la madre de Paco:"}, {"type": "p", "text": "—Lleve usted ya a Paco al colegio. No sirve que llegue tarde el primer día. Desde mañana esperará a que Humberto se levante y los llevará juntos a los dos."}, {"type": "p", "text": "El profesor, al ver a Humberto Grieve, le dijo:"}, {"type": "p", "text": "—¿Hoy otra vez tarde?"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "Humberto, con gran desenfado, respondió:"}, {"type": "p", "text": "—Que me he quedado dormido."}, {"type": "p", "text": "—Bueno —dijo el profesor—. Que esta sea la última vez. Pase a sentarse. Humberto Grieve buscó con la mirada donde estaba Paco Yunque. Al dar con él, se le acercó y le dijo imperiosamente:"}, {"type": "p", "text": "—Ven a mi carpeta conmigo."}, {"type": "p", "text": "Paco Fariña le dijo a Humberto Grieve:"}, {"type": "p", "text": "—No. Porque el señor lo ha puesto aquí."}, {"type": "p", "text": "—¿Y a ti qué te importa? —le increpó Grieve violentamente, arrastrando a Yunque por un brazo a su carpeta."}, {"type": "p", "text": "—¡Señor! —gritó entonces Fariña—, Grieve se está llevando a Paco Yunque a su carpeta."}, {"type": "p", "text": "El profesor cesó de escribir y preguntó con voz enérgica:"}, {"type": "p", "text": "—¡Vamos a ver! ¡Silencio! ¿Qué pasa ahí? Fariña volvió a decir:"}, {"type": "p", "text": "—Grieve se ha llevado a su carpeta a Paco Yunque."}, {"type": "p", "text": "Paco Yunque Humberto Grieve, instalado ya en su carpeta con Paco Yunque, le dijo al profesor:"}, {"type": "p", "text": "—Sí, señor. Porque Paco Yunque es mi muchacho. Por eso."}, {"type": "p", "text": "El profesor lo sabía esto perfectamente y le dijo a Humberto Grieve:"}, {"type": "p", "text": "—Muy bien. Pero yo lo he colocado con Paco Fariña, para que atienda mejor las explicaciones. Déjelo que vuelva a su sitio. Todos los alumnos miraban en silencio al profesor, a Humberto Grieve y a Paco Yunque. Fariña fue y tomó a Paco Yunque por la mano y quiso volverlo a traer a su carpeta, pero Grieve tomó a Paco Yunque por el otro brazo y no lo dejó moverse. El profesor le dijo otra vez a Grieve:"}, {"type": "p", "text": "—¡Grieve! ¿Qué es esto?"}, {"type": "p", "text": "Humberto Grieve, colorado de cólera, dijo:"}, {"type": "p", "text": "—No, señor. Yo quiero que Yunque se quede conmigo."}, {"type": "p", "text": "—Déjelo, le he dicho."}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "—No, señor."}, {"type": "p", "text": "—¿Cómo?"}, {"type": "p", "text": "—No."}, {"type": "p", "text": "El profesor estaba indignado y repetía, amenazador:"}, {"type": "p", "text": "—¡Grieve! ¡Grieve!"}, {"type": "p", "text": "Humberto Grieve tenía bajo los ojos y sujetaba fuertemente por el brazo a Paco Yunque, el cual estaba aturdido y se dejaba jalar como un trapo por Fariña y por Grieve. Paco yunque tenía ahora más miedo a Humberto Paco Yunque"}, {"type": "p", "text": "Grieve que al profesor, que a todos los demás niños y que al colegio entero. ¿Por qué Paco Yunque le tenía miedo a Humberto Grieve? ¿Por qué este Humberto Grieve solía pegarle a Paco Yunque?"}, {"type": "p", "text": "El profesor se acercó a Paco Yunque, le tomó por el brazo y le condujo a la carpeta de Fariña. Grieve se puso a llorar, pataleando furiosamente su banco."}, {"type": "p", "text": "De nuevo se oyeron pasos en el patio y otro alumno, Antonio Gesdres —hijo de un albañil—, apareció a la puerta del salón. El profesor le dijo:"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "—¿Por qué llega usted tarde?"}, {"type": "p", "text": "—Porque fui a comprar pan para el desayuno."}, {"type": "p", "text": "—¿Y por qué no fue usted más temprano?"}, {"type": "p", "text": "—Porque estuve alzando a mi hermanito y mamá está enferma y papá se fue al trabajo."}, {"type": "p", "text": "—Bueno —dijo el profesor, muy serio—. Párese ahí… Y, además, tiene usted una hora de reclusión."}, {"type": "p", "text": "Le señaló un rincón, cerca de la pizarra de ejercicios."}, {"type": "p", "text": "Paco Fariña se levantó entonces y dijo:"}, {"type": "p", "text": "—Grieve también ha llegado tarde, señor."}, {"type": "p", "text": "—Miente, señor —respondió rápidamente Humberto Grieve—. No he llegado tarde. Todos los alumnos dijeron en coro:"}, {"type": "p", "text": "—¡Sí, señor! ¡Sí, señor! ¡Grieve ha llegado tarde!"}, {"type": "p", "text": "—¡Psch! ¡Silencio! —dijo malhumorado el profesor y todos los niños se callaron. El profesor se paseaba pensativo. Fariña le decía a Yunque en secreto:"}]$lira$::jsonb, 1108);
insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 2, 'Parte 1 (3/7)', $lira$[{"type": "p", "text": "—Grieve ha llegado tar-"}, {"type": "p", "text": "de y no lo castigan. Porque su papá tiene plata. Todos"}, {"type": "p", "text": "los días llega tarde. ¿Tú vives en su casa? ¿Cierto que eres su muchacho?"}, {"type": "p", "text": "Yunque respondió:"}, {"type": "p", "text": "—Yo vivo con mi mamá."}, {"type": "p", "text": "—¿En la casa de Hum-"}, {"type": "p", "text": "berto Grieve?"}, {"type": "p", "text": "—Es una casa muy bo-"}, {"type": "p", "text": "nita. Ahí está la patrona y el patrón. Ahí está mi mamá."}, {"type": "p", "text": "Yo estoy con mi mamá."}, {"type": "p", "text": "Humberto Grieve, desde"}, {"type": "p", "text": "su banco del otro lado del salón, miraba con cólera a Paco Yunque y le enseñaba los puños, porque se dejó llevar a la carpeta de Paco Fariña."}, {"type": "p", "text": "Paco Yunque no sabía"}, {"type": "p", "text": "qué hacer. Le pegaría otra vez César Vallejo"}, {"type": "p", "text": "el niño Humberto, porque no se quedó con él, en su carpeta. Cuando saldrían del colegio, el niño Humberto le daría un empujón en el pecho y una patada en la pierna. El niño Humberto era malo y pegaba pronto, a cada rato. En la calle. En el corredor también. Y en la escalera. Y también en la cocina, delante de su mamá y delante de la patrona. Ahora le va a pegar, porque le estaba enseñando los puñetes y le miraba con ojos blancos. Yunque le dijo a Fariña:"}, {"type": "p", "text": "—Me voy a la carpeta del niño Humberto. Y Paco Fariña le decía:"}, {"type": "p", "text": "—No vayas. No seas zonzo. El señor te va a castigar."}, {"type": "p", "text": "Fariña volteó a ver a Grieve y este Grieve le enseñó también a él los puños, refunfuñando no sé qué cosas, a escondidas del profesor."}, {"type": "p", "text": "—¡Señor! —gritó Fariña—. Ahí, ese Grieve me está enseñando los puñetes. El profesor dijo:"}, {"type": "p", "text": "—¡Psc! ¡Psc! ¡Silencio!… ¡Vamos a ver!… Vamos a hablar hoy de los peces, y después, Paco Yunque"}, {"type": "p", "text": "vamos a hacer todos un ejercicio escrito en una hoja de los cuadernos, y después me los dan para verlos. Quiero ver quién hace mejor ejercicio, para que su nombre sea escrito en el Cuaderno de Honor del Colegio, como el mejor alumno del primer año. ¿Me han oído bien? Vamos a hacer lo mismo que hicimos la semana pasada. Exactamente lo mismo. Hay que atender bien a la clase. Hay que copiar bien el ejercicio que voy a escribir después en la pizarra. ¿Me han entendido bien? Los alumnos respondieron en coro:"}, {"type": "p", "text": "—Sí, señor."}, {"type": "p", "text": "—Muy bien —dijo el profesor—. Vamos a ver. Vamos a hablar ahora de los peces. Varios niños quisieron hablar. El profesor le dijo a uno de los Zumiga que hablase."}, {"type": "p", "text": "—Señor —dijo Zumiga—: había en la playa mucha arena. Un día nos metimos entre la arena y encontramos un pez medio vivo y lo llevamos a mi casa. Pero se murió en el camino…"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "Humberto Grieve dijo:"}, {"type": "p", "text": "—Señor: yo he cogido muchos peces y los he llevado a mi casa y los he soltado en mi salón y no se mueren nunca."}, {"type": "p", "text": "El profesor preguntó:"}, {"type": "p", "text": "—Pero… ¿los deja usted en alguna vasija con agua?"}, {"type": "p", "text": "—No, señor. Están sueltos, entre los muebles. Todos los niños se echaron a reír. Un chico, flacucho y pálido, dijo:"}, {"type": "p", "text": "—Mentira, señor. Porque el pez se muere pronto, cuando lo sacan del agua."}, {"type": "p", "text": "—No, señor —decía Humberto Grieve—. Porque en mi salón no se mueren. Porque mi salón es muy elegante. Porque mi papá me dijo que trajera peces y que podía dejarlos sueltos entre las sillas."}, {"type": "p", "text": "Paco Fariña se moría de risa. Los Zumiga también. El chico rubio y gordo, de chaqueta blanca, y el otro cara redonda y chaqueta verde, se reían ruidosamente. ¡Qué Grieve tan divertido! ¡Los peces en su salón! ¡Entre los Paco Yunque"}, {"type": "p", "text": "muebles! ¡Como si fuesen pájaros! Era una gran mentira lo que contaba Grieve. Todos los chicos exclamaban a la vez reventando de risa:"}, {"type": "p", "text": "—¡Ja! ¡Ja! ¡Ja! ¡Ja! ¡Ja! ¡Miente, señor! ¡Ja! ¡Ja! ¡Ja! ¡Ja! ¡Mentira! ¡Mentira! Humberto Grieve se enojó porque no le creían lo que contaba. Todos se burlaban de lo que había dicho. Pero Grieve recordaba que trajo dos peces a su casa y los soltó en el salón y ahí estuvieron muchos días. Los movió y se movían. No estaba seguro si vivieron muchos días o murieron pronto. Grieve, de todos modos, quería que le creyeran lo que decía. En medio de las risas de todos, le dijo a uno de los Zumiga:"}, {"type": "p", "text": "—¡Claro! Porque mi papá tiene mucha plata. Y me ha dicho que va a hacer llevar a mi casa a todos los peces del mar. Para mí. Para que juegue con ellos en mi salón grande. El profesor dijo en alta voz:"}, {"type": "p", "text": "—¡Bueno! ¡Bueno! ¡Silencio! Grieve no se acuerda bien, seguramente. Porque los peces mueren cuando…"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "Los niños añadieron en coro:"}, {"type": "p", "text": "—… se les saca del agua."}, {"type": "p", "text": "—Eso es —dijo el profesor. El niño flacucho y pálido dijo:"}, {"type": "p", "text": "—Porque los peces tienen sus mamás en el agua y, sacándolos, se quedan sin mamás."}, {"type": "p", "text": "—¡No, no, no! —dijo el profesor—. Los peces mueren fuera del agua, porque no pueden respirar. Ellos toman el aire que hay en el agua, y, cuando salen, no pueden absorber el aire que hay afuera."}, {"type": "p", "text": "—Porque ya están como muertos —dijo un niño."}, {"type": "p", "text": "Humberto Grieve dijo:"}, {"type": "p", "text": "—Mi papá puede darles aire en mi casa, porque tiene bastante plata para comprar todo."}, {"type": "p", "text": "El chico vestido de verde dijo:"}, {"type": "p", "text": "—Mi papá también tiene plata."}, {"type": "p", "text": "—Mi papá también —dijo otro chico. Todos los niños dijeron que sus papás tenían mucho dinero. Paco Yunque no decía Paco Yunque"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "Paco Yunque nada y estaba pensando en los peces que morían fuera del agua."}, {"type": "p", "text": "Fariña le dijo a Paco Yunque:"}, {"type": "p", "text": "—Y tú, ¿tu papá no tiene plata? Paco Yunque reflexionó y se acordó haberle visto una vez a su mamá con unas pesetas en la mano. Yunque dijo a Fariña:"}, {"type": "p", "text": "—Mi mamá tiene también mucha plata."}, {"type": "p", "text": "—¿Cuánto? —le preguntó Fariña."}, {"type": "p", "text": "—Como cuatro pesetas."}, {"type": "p", "text": "Fariña dijo al profesor en voz alta:"}, {"type": "p", "text": "—Paco Yunque dice que su mamá tiene también mucha plata."}, {"type": "p", "text": "—¡Mentira, señor! —respondió Humberto Grieve—. Paco Yunque miente, porque su mamá es la sirvienta de mi mamá y no tiene nada."}, {"type": "p", "text": "César Vallejo El profesor tomó la tiza y escribió en la pizarra dando la espalda a los niños. Humberto Grieve, aprovechando de que no le veía el profesor, dio un salto y le jaló de los pelos a Yunque, volviéndose a la carrera a su carpeta. Yunque se puso a llorar."}, {"type": "p", "text": "—¿Qué es eso? —dijo el profesor, volviéndose a ver lo que pasaba. Paco Fariña dijo:"}, {"type": "p", "text": "—Grieve le ha tirado de los pelos, señor."}, {"type": "p", "text": "—No, señor —dijo Grieve—. Yo no he sido. Yo no me he movido de mi sitio."}, {"type": "p", "text": "—¡Bueno, bueno! —dijo el profesor—. ¡Silencio! ¡Cállese, Paco Yunque! ¡Silencio! Siguió escribiendo en la pizarra; y después preguntó a Grieve:"}]$lira$::jsonb, 1106);
insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 3, 'Parte 1 (4/7)', $lira$[{"type": "p", "text": "—Si se le saca del agua, ¿qué sucede con el pez?"}, {"type": "p", "text": "—Va a vivir en mi salón —contestó Grieve. Otra vez se reían de Grieve los niños. Este Grieve no sabía nada. No pensaba más que en Paco Yunque"}, {"type": "p", "text": "su casa y en su salón y en su papá y en su plata. Siempre estaba diciendo tonterías."}, {"type": "p", "text": "—Vamos a ver, usted, Paco Yunque —dijo el profesor—. ¿Qué pasa con el pez, si se le saca del agua?"}, {"type": "p", "text": "Paco Yunque, medio llorando todavía por el jalón de los pelos que le dio Grieve, repitió de una tirada lo que dijo el profesor: César Vallejo"}, {"type": "p", "text": "—Los peces mueren fuera del agua porque les falta aire."}, {"type": "p", "text": "—¡Eso es! —decía el profesor—. Muy bien. Volvió a escribir en la pizarra. Humberto Grieve aprovechó otra vez de que no podía verle el profesor y fue a darle un puñetazo a Paco Fariña en la boca y regresó de un salto a su carpeta. Fariña, en vez de llorar como Paco Yunque, dijo a grandes voces al profesor:"}, {"type": "p", "text": "—¡Señor! ¡Acaba de pegarme Humberto Grieve!"}, {"type": "p", "text": "—¡Sí, señor! ¡Sí, señor! —decían todos los niños a la vez."}, {"type": "p", "text": "Una bulla tremenda había en el salón. El profesor dio un puñetazo en su pupitre y dijo:"}, {"type": "p", "text": "—¡Silencio!"}, {"type": "p", "text": "El salón se sumió en un silencio completo y cada alumno estaba en su carpeta, serio y derecho, mirando ansiosamente al profesor. ¡Las cosas de este Humberto Grieve! ¡Ya ven lo que Paco Yunque"}, {"type": "p", "text": "estaba pasando por su cuenta! ¡Ahora habrá que ver lo que va a hacer el profesor, que estaba colorado de cólera! ¡Y todo por culpa de Humberto Grieve!"}, {"type": "p", "text": "—¿Qué desorden es ése? —preguntó el profesor a Paco Fariña."}, {"type": "p", "text": "Paco Fariña, con los ojos brillantes de rabia, decía:"}, {"type": "p", "text": "—Humberto Grieve me ha pegado un puñetazo en la cara, sin que yo le haga nada."}, {"type": "p", "text": "—¿Verdad, Grieve?"}, {"type": "p", "text": "—No, señor —dijo Humberto Grieve—. Yo no le he pegado."}, {"type": "p", "text": "El profesor miró a todos los alumnos sin saber a qué atenerse. ¿Quién de los dos decía la verdad? ¿Fariña o Grieve?"}, {"type": "p", "text": "—¿Quién lo ha visto? —preguntó el profesor a Fariña."}, {"type": "p", "text": "—¡Todos, señor! Paco Yunque también lo ha visto."}, {"type": "p", "text": "—¿Es verdad lo que dice Paco Fariña? —le preguntó el profesor a Yunque. Paco Yunque"}, {"type": "p", "text": "Paco Yunque miró a Humberto Grieve y no se atrevió a responder, porque si decía sí, el niño Humberto le pegaría a la salida. Yunque no dijo nada y bajó la cabeza. Fariña dijo:"}, {"type": "p", "text": "—Yunque no dice nada, señor, porque Humberto Grieve le pega, porque es su muchacho y vive en su casa."}, {"type": "p", "text": "El profesor preguntó a los otros alumnos:"}, {"type": "p", "text": "—¿Quién otro ha visto lo que dice Fariña?"}, {"type": "p", "text": "—¡Yo, señor! ¡Yo, señor! ¡Yo, señor! El profesor volvió a preguntar a Grieve:"}, {"type": "p", "text": "—¿Entonces, es cierto, Grieve, que le ha pegado usted a Fariña?"}, {"type": "p", "text": "—¡No, señor! Yo no le he pegado."}, {"type": "p", "text": "—Cuidado con mentir, Grieve. ¡Un niño decente como usted no debe mentir!"}, {"type": "p", "text": "—No, señor. Yo no le he pegado."}, {"type": "p", "text": "—Bueno. Yo creo en lo que usted dice. Yo sé que usted no miente nunca. Bueno. Pero tenga usted mucho cuidado en adelante. El profesor se puso a pasear, pensativo, y todos los alumnos seguían circunspectos y derechos en sus bancos."}, {"type": "p", "text": "Paco Fariña gruñía a media voz y como queriendo llorar:"}, {"type": "p", "text": "—No le castigan, porque su papá es rico. Le voy a decir a mi mamá."}, {"type": "p", "text": "El profesor le oyó y se plantó enojado delante de Fariña y le dijo en alta voz:"}, {"type": "p", "text": "—¿Qué está usted diciendo? Humberto Grieve es un buen alumno. No miente nunca. No molesta a nadie. Por eso no le castigo. Aquí todos los niños son iguales, los hijos de ricos y los hijos de pobres. Yo los castigo aunque sean hijos de ricos. Como usted vuelva a decir lo que está diciendo del padre de Grieve, le pondré dos horas de reclusión. ¿Me ha oído usted?"}, {"type": "p", "text": "Paco Fariña estaba agachado. Paco Yunque también. Los dos sabían que era Humberto Grieve quien les había pegado y que era un gran mentiroso."}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "El profesor fue a la pizarra y siguió escribiendo."}, {"type": "p", "text": "—¿Por qué no le dijiste al señor que me ha pegado Humberto Grieve?"}, {"type": "p", "text": "—Porque el niño Humberto me pega."}, {"type": "p", "text": "—Y, ¿por qué no se lo dices a tu mamá?"}, {"type": "p", "text": "—Porque si le digo a mi mamá, también me pega y la patrona se enoja. Mientras el profesor escribía en la pizarra, Humberto Grieve se puso a llenar de dibujos su cuaderno."}, {"type": "p", "text": "Paco Yunque estaba pensando en su mamá. Después se acordó de la patrona y del niño Humberto. ¿Le pegarían al volver a la casa? Yunque miraba a los otros niños y éstos no le pegaban a Yunque ni a Fariña, ni a nadie. Tampoco le querían agarrar a Yunque en las otras carpetas, como quiso hacerlo el niño Humberto. ¿Por qué el niño Humberto era así con él? Yunque se lo diría ahora a su mamá y si el niño Humberto le pegaba, se lo diría al profesor. Pero el profesor no le hacía nada al Paco Yunque"}, {"type": "p", "text": "niño Humberto. Entonces, se lo diría a Paco Fariña."}, {"type": "p", "text": "Le preguntó a Paco Fariña:"}, {"type": "p", "text": "—¿A ti también te pega el niño Humberto?"}, {"type": "p", "text": "—¿A mí? ¡Qué me va a pegar a mí! Le pego un puñetazo en el hocico y le hago sangre. ¡Vas a ver! ¡Como me haga alguna cosa! ¡Déjalo y verás! ¡Y se lo diré a mi mamá! ¡Y vendrá mi papá y le pegará a Grieve y a su papá también, y a todos! Paco Yunque le oía asustado a Paco Fariña lo que decía. ¿Cierto sería que le pegaría al niño Humberto? ¿Y que su papá vendría a pegarle al señor Grieve? Paco Yunque no quería creerlo, porque al niño Humberto no le pegaba nadie. Si Fariña le pegaba, vendría el patrón y le pegaría a Fariña y también al papá de Fariña. Le pegaría el patrón a todos. Porque todos le tenían miedo. Porque el señor Grieve hablaba muy serio y estaba mandando siempre. Y venían a su casa señores y señoras que le tenían mucho miedo y obedecían siempre al patrón y a la patrona. En buena cuenta, el César Vallejo"}, {"type": "p", "text": "señor Grieve podía más que el profesor y más que todos."}, {"type": "p", "text": "Paco Yunque miró al profesor que escribía en la pizarra. ¿Quién era el profesor? ¿Por qué era tan serio y daba tanto miedo? Yunque seguía mirándolo. No era el profesor igual a su papá ni al señor Grieve. Más bien se parecía a otros señores que venían a la casa y hablaban con el patrón. Tenían un pescuezo colorado y su nariz parecía moco de pavo. Sus zapatos hacían risssrisssrisss-risss, cuando caminaba mucho. Yunque empezó a fastidiarse. ¿A qué hora se iría a su casa? Pero el niño Humberto le iba a pegar a la salida del colegio. Y la mamá de Paco Yunque le diría al niño Humberto: “No, niño. No le pegue usted a Paquito. No sea tan malo”. Y nada más le diría. Pero Paco tendría colorada la pierna de la patada del niño Humberto. Y Paco se pondría a llorar. Porque al niño Humberto nadie le hacía nada. Y porque el patrón y la patrona le querían mucho al niño Humberto, y Paco Yunque tenía pena Paco Yunque"}]$lira$::jsonb, 1203);
insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 4, 'Parte 1 (5/7)', $lira$[{"type": "p", "text": "César Vallejo porque el niño Humberto le pegaba mucho. Todos, todos, todos le tenían miedo al niño Humberto y a sus papás. Todos. Todos. Todos. El profesor también. La cocinera, su hija. La mamá de Paco. El Venancio con su mandil. La María que lava las bacinicas. Quebró ayer una bacinica en tres pedazos grandes. ¿Le pegaría también el patrón al papá de Paco Yunque? Qué cosa fea era esto del patrón y del niño Humberto. Paco Yunque quería llorar. ¿A qué hora acabaría de escribir el profesor en la pizarra?"}, {"type": "p", "text": "—¡Bueno! —dijo el profesor, cesando de escribir—. Ahí está el ejercicio escrito. Ahora, todos sacan sus cuadernos y copian lo que hay en la pizarra. Hay que copiarlo exactamente igual. César Vallejo"}, {"type": "p", "text": "—¿En nuestros cuadernos? —preguntó tímidamente Paco Yunque."}, {"type": "p", "text": "—Sí, en sus cuadernos —le respondió el profesor—. ¿Usted sabe escribir un poco?"}, {"type": "p", "text": "—Sí, señor. Porque mi papá me enseñó en el campo."}, {"type": "p", "text": "—Muy bien. Entonces, todos a copiar. Los niños sacaron sus cuadernos y se pusieron a copiar el ejercicio que el profesor había escrito en la pizarra."}, {"type": "p", "text": "—No hay que apurarse —decía el profesor—. Hay que escribir poco a poco, para no equivocarse."}, {"type": "p", "text": "Humberto Grieve preguntó:"}, {"type": "p", "text": "—¿Es, señor, el ejercicio escrito de los peces?"}, {"type": "p", "text": "—Sí. A copiar todo el mundo. El salón se sumió en el silencio. No se oía sino el ruido de los lápices. El profesor se sentó a su pupitre y también se puso a escribir en unos libros."}, {"type": "p", "text": "Humberto Grieve, en vez de copiar su ejercicio, se puso otra vez a hacer dibujos en Paco Yunque"}, {"type": "p", "text": "su cuaderno. Lo llenó completamente de dibujos de peces, de muñecos y de cuadritos. Al cabo de un rato, el profesor se paró y preguntó:"}, {"type": "p", "text": "—¿Ya terminaron?"}, {"type": "p", "text": "—Bueno —dijo el profesor—. Pongan al pie sus nombres bien claros. En ese momento sonó la campana del recreo. Una gran algazara volvieron a hacer los niños y salieron corriendo al patio. Paco Yunque había copiado su ejercicio muy bien y salió al recreo con su libro, su cuaderno y su lápiz."}, {"type": "p", "text": "Ya en el patio, vino Humberto Grieve y agarró a Paco Yunque por un brazo, diciéndole con cólera:"}, {"type": "p", "text": "—Ven para jugar al melo."}, {"type": "p", "text": "Lo echó de un empellón al medio y le hizo derribar su libro, su cuaderno y su lápiz. Yunque hacía lo que le ordenaba Grieve, pero estaba colorado y avergonzado de que los otros niños viesen cómo lo zarandeaba el niño Humberto. Yunque quería llorar. Paco Fariña, los dos Zumigas y otros niños rodeaban a Humberto Grieve y a Paco Yunque. El niño flacucho y pálido recogió el libro, el cuaderno y el lápiz de Yunque, pero Humberto Grieve se los quitó a la fuerza, diciéndole:"}, {"type": "p", "text": "—¡Déjalos! ¡No te metas! Porque Paco Yunque es mi muchacho."}, {"type": "p", "text": "Humberto Grieve llevó al salón de clases las cosas de Paco Yunque y se las guardó en su Paco Yunque"}, {"type": "p", "text": "carpeta. Después, volvió al patio a jugar con Paco Yunque. Le cogió del pescuezo y le hizo doblar la cintura y ponerse en cuatro manos."}, {"type": "p", "text": "—Estate quieto así —le ordenó imperiosamente—. No te muevas hasta que yo te diga. Humberto Grieve se retiró a cierta distancia y desde allí vino corriendo y dio un salto sobre Paco Yunque, apoyando las manos sobre sus espaldas y dándole una patada feroz en las posaderas. Volvió a retirarse y volvió a saltar sobre Paco Yunque, dándole otra patada. Mucho rato estuvo así jugando Humberto Grieve con Paco Yunque. Le dio como veinte saltos y veinte patadas."}, {"type": "p", "text": "De repente se oyó un llanto. Era Yunque que estaba llorando de las fuertes patadas del niño Humberto. Entonces salió Paco Fariña del ruedo formado por los otros niños y se plantó ante Grieve, diciéndole:"}, {"type": "p", "text": "—¡No! ¡No te dejo que saltes sobre Paco Yunque!"}, {"type": "p", "text": "César Vallejo"}, {"type": "p", "text": "Humberto Grieve le respondió amenazándole:"}, {"type": "p", "text": "—¡Oye! ¡Oye! ¡Paco Fariña! ¡Paco Fariña! ¡Te voy a dar un puñetazo!"}, {"type": "p", "text": "Pero Fariña no se movía y estaba tieso delante de Grieve y le decía:"}, {"type": "p", "text": "—¡Porque es tu muchacho le pegas y lo saltas y lo haces llorar! ¡Sáltalo y verás! Los dos hermanos Zumiga abrazaban a Paco Yunque y le decían que ya no llorase y le consolaban diciéndole:"}, {"type": "p", "text": "—¿Por qué te dejas saltar así y dar de patadas? ¡Pégale! ¡Sáltalo tú también! ¿Por qué te dejas? ¡No seas zonzo! ¡Cállate! ¡Ya no llores! ¡Ya nos vamos a ir a nuestras casas! Paco Yunque estaba siempre llorando y sus lágrimas parecían ahogarle. Se formó un tumulto de niños en torno a Paco Yunque y otro tumulto en torno a Humberto Grieve y a Paco Fariña. Grieve le dio un empellón brutal a Fariña y lo derribó al suelo. Vino un alumno más César Vallejo"}, {"type": "p", "text": "grande, del segundo año, y defendió a Fariña, dándole a Grieve un puntapié. Y otro niño del tercer año, más grande que todos, defendió a Grieve dándole una furiosa trompada al alumno del segundo año. Un buen rato llovieron bofetadas y patadas entre varios niños. Eso era un enredo."}, {"type": "p", "text": "Sonó la campana y todos los niños volvieron a sus salones de clase. A Paco Yunque lo llevaron por los brazos los dos hermanos Zumiga."}, {"type": "p", "text": "Paco Yunque Una gran gritería había en el salón del primer año, cuando entró el profesor. Todos se callaron."}, {"type": "p", "text": "El profesor miró a todos muy serios y dijo como un militar:"}, {"type": "p", "text": "—¡Siéntense!"}, {"type": "p", "text": "Un traqueteo de carpetas y todos los alumnos estaban ya sentados. Entonces el profesor se sentó en su pupitre y llamó por lista a los niños para que le entregasen sus cuartillas con los ejercicios César Vallejo"}, {"type": "p", "text": "escritos sobre el tema de los peces. A medida que el profesor recibía las hojas de los cuadernos, las iba leyendo y escribía las notas en unos libros."}, {"type": "p", "text": "Humberto Grieve se acercó a la carpeta de Paco Yunque y le entregó su libro, su cuaderno y su lápiz. Pero antes había arrancado la hoja del cuaderno en que estaba el ejercicio de Paco Yunque y puso en ella su firma. Cuando el profesor dijo: “Humberto Grieve”, Grieve fue y presentó el ejercicio de Paco Yunque como si fuese suyo. Y cuando el profesor dijo: “Paco Yunque”, Yunque se puso a buscar en su cuaderno la hoja en que escribió su ejercicio y no lo encontró."}, {"type": "p", "text": "—¿La ha perdido usted —le preguntó el profesor— o no la ha hecho usted? Pero Paco Yunque no sabía lo que se había hecho la hoja de su cuaderno y, muy avergonzado, se quedó en silencio y bajó la frente. Paco Yunque"}, {"type": "p", "text": "—Bueno —dijo el profesor, y anotó en unos libros la falta de Paco Yunque. Después siguieron los demás entregando sus ejercicios. Cuando el profesor acabó de verlos todos, entró de repente al salón el Director del Colegio."}]$lira$::jsonb, 1117);
insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 5, 'Parte 1 (6/7)', $lira$[{"type": "p", "text": "César Vallejo El profesor y los niños se pusieron de pie respetuosamente. El Director miró como enojado a los alumnos y dijo en voz alta:"}, {"type": "p", "text": "—¡Siéntense!"}, {"type": "p", "text": "El Director le preguntó al profesor:"}, {"type": "p", "text": "—¿Ya sabe usted quién es el mejor alumno de su año? ¿Ya han hecho el ejercicio semanal para calificarlos?"}, {"type": "p", "text": "—Sí, señor Director —dijo el profesor—. Acaban de hacerlo. La nota más alta la ha obtenido Humberto Grieve."}, {"type": "p", "text": "—¿Dónde está su ejercicio?"}, {"type": "p", "text": "—Aquí está, señor Director. El profesor buscó entre todas las hojas de los alumnos y encontró el ejercicio firmado por Humberto Grieve. Se lo dio al Director, que se quedó viendo largo rato la cuartilla."}, {"type": "p", "text": "—Muy bien —dijo el Director, contento. Subió al pupitre y miró severamente a los alumnos. Después les dijo con su voz un poco ronca pero enérgica:"}, {"type": "p", "text": "César Vallejo —De todos los ejercicios que ustedes han hecho, ahora, el mejor es el de Humberto Grieve. Así es que el nombre de este niño va a ser inscrito en el Cuadro de Honor de esta semana, como el mejor alumno del primer año. Salga afuera, Humberto Grieve. Todos los niños miraron ansiosamente a Humberto Grieve, que salió pavoneándose a pararse muy derecho y orgulloso delante del pupitre del profesor. El Director le dio la mano diciéndole:"}, {"type": "p", "text": "Paco Yunque —Muy bien, Humberto Grieve. Lo felicito. Así deben ser los niños. Muy bien. Se volvió el Director a los demás alumnos y les dijo:"}, {"type": "p", "text": "—Todos ustedes deben hacer lo mismo que Humberto Grieve. Deben ser buenos alumnos como él. Deben estudiar y ser aplicados como él. Deben ser serios, formales y buenos niños como él. Y si así lo hacen, recibirá cada uno un premio al fin de año y sus nombres serán también inscritos en el Cuadro de Honor del Colegio, como el de Humberto Grieve. A ver si la semana que viene, hay otro alumno que dé una buena clase y haga un buen ejercicio como el que ha hecho hoy Humberto Grieve. Así lo espero. Se quedó el Director callado un rato. Todos los alumnos estaban pensativos y miraban a Humberto Grieve con admiración. ¡Qué rico Grieve! ¡Qué buen ejercicio ha escrito! ¡Ése sí que era bueno! ¡Era el mejor alumno de todos! ¡Llegando tarde y todo! ¡Y pegándoles a todos! César Vallejo"}, {"type": "p", "text": "¡Pero ya lo estaban viendo! ¡Le había dado la mano al Director! ¡Humberto Grieve, el mejor de todos los del primer año! El Director se despidió del profesor, hizo una venia a los alumnos, que se pararon para despedirlo, y salió."}, {"type": "p", "text": "El profesor dijo después:"}, {"type": "p", "text": "—¡Siéntense!"}, {"type": "p", "text": "Un traqueteo de carpetas y todos los alumnos estaban ya sentados. El profesor ordenó a Grieve:"}, {"type": "p", "text": "—Váyase a su asiento."}, {"type": "p", "text": "Humberto Grieve, muy alegre, volvió a su carpeta. Al pasar junto a Paco Fariña, le echó la lengua."}, {"type": "p", "text": "El profesor subió a su pupitre y se puso a escribir en unos libros."}, {"type": "p", "text": "Paco Fariña le dijo en voz baja a Paco Yunque:"}, {"type": "p", "text": "—Mira al señor, está poniendo tu nombre en su libro, porque no has presentado tu ejercicio. ¡Míralo! Te va a dejar ahora recluso y no Paco Yunque"}, {"type": "p", "text": "vas a ir a tu casa. ¿Por qué has roto tu cuaderno? ¿Dónde lo pusiste?"}, {"type": "p", "text": "Paco Yunque no contestaba nada y estaba con la cabeza agachada."}, {"type": "p", "text": "—¡Anda! —le volvió a decir Paco Fariña—. ¡Contesta! ¿Por qué no contestas? ¿Dónde has dejado tu ejercicio? Paco Fariña se agachó a mirar la cara de Paco Yunque y le vio que estaba llorando. Entonces le consoló diciéndole:"}, {"type": "p", "text": "—¡Déjalo! ¡No llores! ¡Déjalo! ¡No tengas pena! ¡Vamos a jugar con mi tablero! ¡Tiene torres negras! ¡Déjalo! ¡Yo te regalo mi tablero! ¡No seas zonzo! ¡Ya no llores! Pero Paco Yunque seguía llorando agachado."}, {"type": "h", "text": "Nota Sobre Esta Edición"}, {"type": "p", "text": "Esta edición de Paco Yunque se contrastó con la edición del mismo cuento hecha por Editorial Laia, en Barcelona, y publicada en 1979. Para la presentación de este libro, se tuvieron en cuenta especialmente dos libros, que no dudamos en recomendar: César Vallejo (edición de Julio Ortega, Madrid, Taurus, 1981) y Obra poética de César Vallejo (coordinación de Américo Ferrari, Colección Archivos, Ediciones Unesco, 1996)."}, {"type": "p", "text": "l i b r o a l v i e n t o"}, {"type": "p", "text": "Colección Universal Es de color naranja y en ella se agrupan todos los textos que tienen valor universal, que tienen cabida dentro de la tradición literaria sin distinción de fronteras o épocas. Colección Capital"}, {"type": "p", "text": "Es de color morado y en ella se publican los textos que tengan como temática a Bogotá y sus alrededores. Colección Inicial"}, {"type": "p", "text": "Es de color verde limón y está destinada al público infantil y primeros lectores."}, {"type": "p", "text": "Colección Lateral Es de color azul aguamarina y se trata de un espacio abierto a géneros no tradicionales como la novela gráfi ca, la caricatura, los epistolarios, la ilustración y otros géneros. t í t u l o s d e l"}, {"type": "p", "text": "p r o g r a m a"}, {"type": "p", "text": "85 Lazarillo de Tormes Giovanna Pollarolo, Iván Thays, Anónimo Karina Pacheco, Diego Trelles Paz, 86 ¿Sueñan los androides con Gustavo Rodríguez, Raúl Tola alpacas eléctricas? 100 Tres cuentos y una proclama Antología de ciencia ficción Gabriel García Márquez contemporánea latinoamericana 101 Crónicas de Bogotá Jorge Aristizábal Gáfaro, Jorge Enrique Pedro María Ibáñez Lage, Bernardo Fernández bef, José Urriola, Pedro Mairal, 102 De mis libros Carlos Yushimito Álvaro Mutis 87 Las aventuras de Pinocho 103 Carmilla Historia de una marioneta Sheridan Le Fanu Carlo Collodi Traducción de Joe Broderick Traducción de Fredy Ordóñez 104 Caligramas 88 Recetario santafereño Guillaume Apollinaire Selección y prólogo Traducción de Nicolás Rodríguez Galvis de Antonio García Ángel 105 Fábulas de La Fontaine 89 Cartas de tres océanos 1499- Jean de La Fontaine Edición y traducción de Isabel Soler 106 Breviario de la paz"}, {"type": "p", "text": "e Ignacio Vásquez 107 Tres cuentos de Macondo 90 Quillas, mástiles y velas y un discurso Textos portugueses sobre el mar Gabriel García Márquez 91 Once poetas brasileros 108 Carta sobre los ciegos para uso de los que ven"}, {"type": "p", "text": "Selección y prólogo de Sergio Cohn Traducción de John Galán Casanova Denis Diderot Traducción de Nicolás Rodríguez Galvis 92 Recuerdos de Santafé"}, {"type": "p", "text": "Soledad Acosta de Samper 109 Bogotá contada 2.0 Alberto Barrera Tyszka, Diego Zúñiga, 93 Semblanzas poco ejemplares Élmer Mendoza, Gabriela Wiener, Juan José María Cordovez Moure Bonilla, Luis Fayad, Pablo Casacuberta, 94 Fábulas de Samaniego Rodrigo Hasbún, Wendy Guerra Félix María Samaniego 110 50 poemas de amor colombianos 95 Cocorobé: cantos y arrullos 111 El matadero del Pacífico colombiano Esteban Echeverría Selección y prólogo: Ana María Arango 112 Bicicletario"}, {"type": "p", "text": "96 Cronistas de Indias en la Nueva Granada (1536-1731) 113 El castillo de Otranto Gonzalo Jiménez de Quesada, Pedro Horacio Walpole Cieza de León, Fray Pedro Simón, 114 La gruta simbólica Alexandre Olivier Exquemelin, Fray Alonso de Zamora, Joseph Gumilla 115 Fábulas de Iriarte Tomás de Iriarte"}]$lira$::jsonb, 1129);
insert into public.chapters (book_id, position, title, body, word_count)
values ('paco-yunque', 6, 'Parte 1 (7/7)', $lira$[{"type": "p", "text": "97 Bogotá contada"}, {"type": "p", "text": "Carlos Yushimito, Gabriela Alemán, 116 Once poetas holandeses Rodrigo Blanco Calderón, Rodrigo Selección y prólogo de Thomas Rey Rosa, Pilar Quintana, Bernardo Möhlmann. Fernández bef, Adriana Lunardi, Traducción de Diego J. Puls, Fernando Sebastià Jovani, García de la Banda Jorge Enrique Lage, Miguel Ángel y Taller Brockway Manrique, Martín Kohan, Frank Báez, 117 Siete retratos Alejandra Costamagna, Inés Bortagaray, Ximénez Ricardo Silva Romero 118 Bogotá contada 3 98 Poesía satírica y burlesca Fabio Morábito, Daniel Cassany, Fernanda Francisco de Quevedo Trías, Iván Thays, Daniel Valencia 99 Diez cuentos peruanos Caravantes, Luis Noriega, Federico Falco, Enrique Prochazka, Fernando Ampuero, Mayra Santos-Febres Óscar Colchado, Santiago Roncagliolo, 119 Guadalupe años sin cuenta Ilustrado por Geison Castañeda Creación Colectiva Teatro La Candelaria 135 El horla 120 «Preludio» seguido de «La Guy de Maupassant casa de muñecas» Traducción de Luisa Fernanda Espina Katherine Mansfield 136 Hip, hipopótamo vagabundo Traducción de Erna von der Walde Rubén Vélez 121 Sylvie, recuerdos del Valois Ilustrado por Santiago Guevara Gérard de Nerval 137 Shakespeare: una indagación Traducción de Mateo Cardona Vallejo sobre el poder 122 Once poetas franceses Estanislao Zuleta Selección y prólogo de Anne Louyot 138 Versiones de la Independencia Traducción de Andrés Holguín 139 Cuentos míticos del sol, 123 «Piel de asno» y otros cuentos la aurora y la noche Charles Perrault Teófilo Braga Traducción de Mateo Cardona Ilustrados por Eva Giraldo 140 Fábulas de Tamalameque Manuel Zapata Olivella"}, {"type": "p", "text": "124 Bodas de sangre Ilustradas por Rafael Yockteng Federico García Lorca"}, {"type": "p", "text": "141 Cancionero de"}, {"type": "p", "text": "125 Maravillas y horrores Rock al Parque de la Conquista"}, {"type": "p", "text": "Comentarios y notas de Jorge O. Melo 142 Bogotá contada 6 Nicolás Buenaventura, Mercedes 126 Bogotá contada 4 Estramil, Brenda Lozano, Roger Mello, Eduardo Halfon, Horacio Castellanos, Rodrigo Fuentes, Jaime Manrique Hebe Uhart, Marina Perezagua, Ardila, Juan Carlos Méndez Guédez Edmundo Paz Soldán, Lina Meruane, Ricardo Cano Gaviria 143 «Naricita impertinente» y «La finca del pájaro carpintero 127 La historia del buen viejo amarillo» y la bella señorita Monteiro Lobato Italo Svevo Traducción de Mariana Serrano Z. Traducción de Lizeth Burbano Ilustradas por Sindy Elefante 128 La marquesa de O. 144 Novela de ajedrez Heinrich von Kleist Stefan Zweig Traducción de Maritza García Arias Traducción de David Alvarado-Archila 129 Juan Sábalo 145 Relatos de fantasmas Leopoldo Berdella de la Espriella Edith Wharton Ilustrado por Eva Giraldo Traducción de Juan Manuel Caycedo 130 Arte de distinguir 146 Al amparo del bosque a los cursis Antología colombiana de poesía Santiago de Liniers homoafectiva - Investigación & Francisco Silvela"}, {"type": "p", "text": "y compilación de Omar Ardila 131 Versiones del Bogotazo"}, {"type": "p", "text": "Arturo Alape, Felipe González Toledo, 147 Trece relatos nórdicos Herbert Braun, Carlos Cabrera Lozano, Varios autores Hernando Téllez, Lucas Caballero –Klim–, Miguel Torres, Guillermo 148 De sobremesa González Uribe, Víctor Diusabá Rojas, José Asunción Silva María Cristina Alvarado, Aníbal Pérez, María 149 Diez cuentos del Decamerón Luisa Valencia Giovanni Boccaccio 132 Once poetas argentinos"}, {"type": "p", "text": "Selección y prólogo de Susana Szwarc 150 Viaje alrededor de mi 133 Bogotá contada 5 habitación Pedro Mairal, Francisco Hinojosa, Xavier de Maistre Margarita García Robayo,"}, {"type": "p", "text": "Dani Umpi, Ricardo Sumalavia, 151 La calle 10 Yolanda Arroyo Manuel Zapata Olvella 134 La dicha de la palabra dicha Nicolás Buenaventura"}, {"type": "p", "text": "ccoommppaarrttee lliibbrrooss que después de ser leídos, deben quedar libres para llegar a otros lectores, y te deja entrar gratis a una biblioteca digital con la mejor literatura. * * *"}, {"type": "p", "text": "Escanea el código, ingresa a la biblioteca y deja volar tu imaginación. Paco Yunque fue editado por el instituto distrital de las artes —idartes para su biblioteca libro al viento, bajo el número ciento cincuenta, y se imprimió en el mes de octubre del año 2020 en bogotá."}, {"type": "p", "text": "Este"}, {"type": "p", "text": "ejemplar de"}, {"type": "p", "text": "Libro al Viento"}, {"type": "p", "text": "es un bien público."}, {"type": "p", "text": "Después de leerlo"}, {"type": "p", "text": "permita que circule"}, {"type": "p", "text": "entre los demás"}, {"type": "p", "text": "lectores."}, {"type": "p", "text": "«Cuando Paco Yunque y su madre llegaron a la puerttaa ddeell ccoolleeggiioo,, llooss nniiññooss eessttaabbaann jjuuggaannddoo eenn eell ppaattiioo.. LLaa mmaaddrree llee ddeejjóó yy ssee ffuuee.. [[......]] PPaaccoo eessttaabbaa ccoonn mmiieeddoo,, ppoorrqquuee eerraa llaa pprriimmeerraa vveezz qquuee vveeííaa aa uunn ccoolleeggiioo;; nnuunnccaa había visto a tantos niños juntos». César Vallejo"}, {"type": "p", "text": "Para pequeños lectores"}, {"type": "p", "text": "ll ii bb rr oo aa ll vv ii ee nn tt oo ii nn ii cc ii aa ll El Instituto Distrital de las Artes - Idartes le recuerda que este ejemplar de Libro al Viento es un bien público. Después de leerlo permita que circule entre los demás lectores. «La esperanza era para los otros; para sí mismo no tenía ninguna. Para la solidaridad Vallejo no era un extranjerismo, sino una pasión casi rayana en el sufrimiento, en la abnegación». Hans Magnus Enzensberger"}, {"type": "p", "text": "sobre César Vallejo"}]$lira$::jsonb, 766);

