-- ─── Los ríos profundos · José María Arguedas ───
delete from public.chapters where book_id = 'los-rios-profundos';

insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('los-rios-profundos', 'Los ríos profundos', 'José María Arguedas', 'Ernesto entra interno en un colegio de Abancay. Fuera, el mundo quechua de su infancia; dentro, otro que no lo quiere.', 'novela', 79, 457, array['perú', 'andes', 'colegio']::text[], true)
