insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('romeo-y-julieta', 'Romeo y Julieta', 'William Shakespeare', 'Dos familias que se odian, dos hijos que se enamoran en una fiesta y cinco días que lo deciden todo.', 'teatro', 32, 103, array['clásico', 'amor', 'tragedia']::text[], true)
