insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('hamlet', 'Hamlet', 'William Shakespeare', 'El fantasma de su padre le dice quién lo mató. Hamlet pasa la obra entera decidiendo si le cree y qué hacer.', 'teatro', 86, 164, array['clásico', 'venganza', 'tragedia']::text[], true)
on conflict (id) do update set
  title = excluded.title, author = excluded.author,
