insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('edipo-rey', 'Edipo Rey', 'Sófocles', 'Tebas está apestada y el rey jura encontrar al culpable. La investigación avanza hacia el único sitio donde no quería mirar.', 'teatro', 12, 70, array['clásico', 'griego', 'destino']::text[], true)
