insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('fuenteovejuna', 'Fuenteovejuna', 'Lope de Vega', 'Un comandante abusa de un pueblo entero hasta que el pueblo entero responde. Y luego nadie da un solo nombre.', 'teatro', 14, 133, array['clásico', 'pueblo', 'justicia']::text[], true)
