insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('don-juan-tenorio', 'Don Juan Tenorio', 'José Zorrilla', 'Don Juan apuesta en una taberna a que puede conquistar y arruinar a quien quiera. Gana la apuesta. Luego llega la cuenta.', 'teatro', 38, 229, array['clásico', 'apuesta', 'romanticismo']::text[], true)
on conflict (id) do update set
  title = excluded.title, author = excluded.author,
