  minutes_to_read = excluded.minutes_to_read,
  tags = excluded.tags, is_published = true;

insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 0, 'Parte 1', $lira$[{"type": "v", "text": "no está en Sevilla."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Su ausencia\ndura en verdad todavía?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Tal creo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y noticia alguna\nno tienes de él?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Ah! Una historia\nme viene ahora a la memoria\nque os podrá dar..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Oportuna\nluz sobre el caso?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Tal vez."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Habla, pues."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "(Hablando consigo mismo.)\nNo, no me engaño;\nesta noche cumple el año,\nlo había olvidado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Pardiez!\n¿Acabarás con tu cuento?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Perdonad, señor; estaba\nrecordando el hecho."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Acaba,\n¡vive Dios! que me impaciento."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Pues es el caso, señor,\nque el caballero Mejía,\npor quien preguntáis, dio un día\nen la ocurrencia peor\nque ocurrírsele podía."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Suprime lo al hecho extraño;\nque apostaron me es notorio\na quién haría en un año,\ncon más fortuna, más daño,\nLuis Mejía y Juan Tenorio."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿La historia sabéis?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Entera;\npor eso te he preguntado\npor Mejía."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Oh! me pluguiera\nque la apuesta se cumpliera,\nque pagan bien y al contado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y no tienes confianza\nen que don Luis a esta cita\nacuda?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Quiá! ni esperanza;\nel fin del plazo se avanza,\ny estoy cierto que maldita\nla memoria que ninguno\nguarda de ello."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Basta ya.\nToma."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Excelencia, ¿y de alguno\nde ellos sabéis vos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Quizá."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿Vendrán, pues?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Al menos uno;\nmas por si acaso los dos\ndirigen aquí sus huellas\nel uno del otro en pos,\ntus dos mejores botellas\nprevenles."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Mas..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Chito...!. Adiós."}, {"type": "h", "text": "Escena III"}, {"type": "h", "text": "Buttarelli"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Santa Madona! De vuelta\nMejía y Tenorio están\nsin duda... y recogerán\nlos dos la palabra suelta.\n¡Oh! sí; ese hombre tiene traza\nde saberlo a fondo.\n(Ruido adentro.)\nPero\n¿qué es esto?\n(Se asoma a la puerta.)\n¡Anda! el forastero\nestá riñendo en la plaza.\n¡Válgame Dios! ¡Qué bullicio!\n¡Cómo se le arremolina\nchusma... y cómo la acoquina\nél solo! ¡Uf! ¡Qué estropicio!\n¡Cuál corren delante de él!\nNo hay duda, están en Castilla\nlos dos, y anda ya Sevilla\ntoda revuelta. ¡Miguel!"}]$lira$::jsonb, 346);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 1, 'Escena IV', $lira$[{"type": "h", "text": "Escena IV"}, {"type": "v", "text": "BUTTARELLI y MIGUEL."}, {"type": "h", "text": "Miguel"}, {"type": "v", "text": "¿Che comanda?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Presto, qui\nservi una tabola, amico,\ne del Lacryma più antico\nporta due buttiglie."}, {"type": "h", "text": "Miguel"}, {"type": "v", "text": "Si,\nsignor padron."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Micheletto,\napparechia in carità\nlo più ricco, que si fa,\nafrettati!"}, {"type": "h", "text": "Miguel"}, {"type": "v", "text": "Gia mi afretto,\nsignor padrone.\n(Vase.)"}, {"type": "h", "text": "Escena V"}, {"type": "v", "text": "BUTTARELLI y DON GONZALO."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Aquí es.\n¿Patrón?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿Qué se ofrece?"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Quiero\nhablar con el hostelero."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Con él habláis; decid, pues."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Sois vos?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Sí, mas despachad,\nque estoy de priesa."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "En tal caso,\nved si es cabal y de paso\nesa dobla, y contestad."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Oh, excelencia!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Conocéis\na don Juan Tenorio?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Y es cierto que tiene aquí\nhoy una cita?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Oh! ¿seréis\nvos el otro?"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Quién?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Don Luis."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "No; pero estar me interesa\nen su entrevista."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Esta mesa\nles preparo; si os servís\nen esotra colocaros,\npodréis presenciar la cena\nque les daré... ¡Oh! será escena\nque espero que ha de admiraros."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Lo creo."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Son, sin disputa,\nlos dos mozos más gentiles\nde España."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Sí, y los más viles\ntambién."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Bah! Se les imputa\ncuanto malo se hace hoy día;\nmas la malicia lo inventa,\npues nadie paga su cuenta\ncomo Tenorio y Mejía."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Ya!"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Es afán de murmurar,\nporque conmigo, señor,\nninguno lo hace mejor,\ny bien lo puedo jurar."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "No es necesario más..."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Quisiera yo ocultamente\nverlos, y sin que la gente\nme reconociera."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "A fe\nque eso es muy fácil, señor.\nLas fiestas de Carnaval,\nal hombre más principal\npermiten sin deshonor\nde su linaje, servirse\nde un antifaz, y bajo él,\n¿quién sabe, hasta descubrirse,\nde qué carne es el pastel?"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Mejor fuera en aposento\ncontiguo..."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Ninguno cae\naquí."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Pues entonces trae\nel antifaz."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Al momento."}]$lira$::jsonb, 324);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 2, 'Escena VI', $lira$[{"type": "h", "text": "Escena VI"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "No cabe en mi corazón\nque tal hombre pueda haber,\ny no quiero cometer\ncon él una sinrazón.\nYo mismo indagar prefiero\nla verdad... mas, a ser cierta\nla apuesta, primero muerta\nque esposa suya la quiero.\nNo hay en la tierra interés\nque si la daña me cuadre;\nprimero seré buen padre,\nbuen caballero después.\nEnlace es de gran ventaja,\nmas no quiero que Tenorio\ndel velo del desposorio\nla recorte una mortaja."}, {"type": "h", "text": "Escena VII"}, {"type": "v", "text": "DON GONZALO y BUTTARELLI, que trae un antifaz."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Ya está aquí."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Gracias, patrón;\n¿Tardarán mucho en llegar?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Si vienen, no han de tardar;\ncerca de las ocho son."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Esa es la hora señalada?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Cierra el plazo, y es asunto\nde perder quien no esté a punto\nde la primer campanada."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Quiera Dios que sea una chanza,\ny no lo que se murmura."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "No tengo aún por muy segura\nde que cumplan, la esperanza;\npero si tanto os importa\nlo que ello sea saber,\npues la hora está al caer,\nla dilación es ya corta."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Cúbrome, pues, y me siento.\n(Se sienta a una mesa a la derecha, y se pone el antifaz.)"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "(Aparte.)\nCurioso el viejo me tiene\ndel misterio con que viene...\ny no me quedo contento\nhasta saber quién es él.\n(Limpia y trajina, mirándole de reojo.)"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "(Aparte.)\n¡Que un hombre como yo tenga\nque esperar aquí, y se avenga\ncon semejante papel!\nEn fin, me importa el sosiego\nde mi casa, y la ventura\nde una hija sencilla y pura,\ny no es para echarlo a juego."}, {"type": "h", "text": "Escena VIII"}, {"type": "v", "text": "DON GONZALO, BUTTARELLI y DON DIEGO, a la puerta del fondo."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "La seña está terminante,\naquí es; bien me han informado;\nllego pues."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿Otro embozado?"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Ah de esta casa?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Adelante."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿La Hostería del Laurel?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "En ella estáis, caballero."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Está en casa el hostelero?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Estáis hablando con él."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Sois vos Buttarelli?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Yo."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Es verdad que hoy tiene aquí\nTenorio una cita?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Y ha acudido a ella?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "No."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Pero acudirá?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "No sé."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Le esperáis vos?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Por si acaso\nvenir le place."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "En tal caso,\nyo también le esperaré.\n(Se sienta al lado opuesto a DON GONZALO.)"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿Que os sirva vianda alguna\nqueréis mientras?"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "No; tomad."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¿Excelencia?"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Y excusad\nconversación importuna."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Perdonad."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Vais perdonado;\ndejadme, pues."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "(Aparte.)\n¡Jesucristo!\nEn toda mi vida he visto\nhombre más mal humorado."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "(Aparte.)\n¡Que un hombre de mi linaje\ndescienda a tan ruin mansión!\nPero no hay humillación\na que un padre no se baje\npor un hijo. Quiero ver\npor mis ojos la verdad,\ny el monstruo de liviandad\na quien pude dar el ser.\n(BUTTARELLI, que anda arreglando sus trastos, contempla desde el fondo\na DON GONZALO y a DON DIEGO, que permanecerán embozados y en\nsilencio.)"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "¡Vaya un par de hombres de piedra!\nPara éstos sobra mi abasto;\nmas, ¡pardiez!, pagan el gasto\nque no hacen, y así se medra."}]$lira$::jsonb, 538);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 3, 'Escena IX', $lira$[{"type": "h", "text": "Escena IX"}, {"type": "v", "text": "DON GONZALO, DON DIEGO, BUTTARELLI, el Capitán\nCENTELLAS, AVELLANEDA y dos caballeros."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Vinieron, y os aseguro\nque se efectuará la apuesta."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Entremos, pues. ¿Buttarelli?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Señor capitán Centellas,\n¿vos por aquí?"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Sí, Cristófano.\n¿Cuándo aquí sin mi presencia\ntuvieron lugar las orgias\nque han hecho raya en la época?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Como ha tanto tiempo ya\nque no os he visto..."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Las guerras\ndel Emperador a Túnez\nme llevaron; mas mi hacienda\nme vuelve a traer a Sevilla;\ny, según lo que me cuentan,\nllego lo más a propósito\npara renovar añejas\namistades. Conque apróntanos\nluego unas cuantas botellas,\ny en tanto que humedecemos\nla garganta, verdadera\nrelación haznos de un lance\nsobre el cual hay controversia."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Todo se andará; mas antes\ndejadme ir a la bodega."}, {"type": "h", "text": "Varios"}, {"type": "v", "text": "Sí, sí."}, {"type": "h", "text": "Escena X"}, {"type": "v", "text": "Dichos, menos BUTTARELLI."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Sentarse, señores,\ny que siga Avellaneda\ncon la historia de don Luis."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "No hay ya más que decir de ella,\nsino que creo imposible\nque la de Tenorio sea\nmás endiablada, y que apuesto\npor don Luis."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Acaso pierdas.\nDon Juan Tenorio, se sabe\nque es la más mala cabeza\ndel orbe, y no hubo hombre alguno\nque aventajarle pudiera\ncon sólo su inclinación;\nconque, ¿qué hará si se empeña?"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Pues yo sé bien que Mejía\nlas ha hecho tales, que a ciegas\nse puede apostar por él."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Pues el capitán Centellas\npone por don Juan Tenorio\ncuanto tiene."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Pues se acepta\npor don Luis, que es muy mi amigo."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Pues todo en contra se arriesga;\nporque no hay como Tenorio\notro hombre sobre la tierra,\ny es proverbial su fortuna\ny extremadas sus empresas."}, {"type": "h", "text": "Escena XI"}, {"type": "v", "text": "Dichos y BUTTARELLI, con botellas."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Aquí hay Falerno, Borgoña,\nSorrento."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "De lo que quieras\nsirve, Cristófano, y dinos:\n¿Qué hay de cierto en una apuesta,\npor don Juan Tenorio ha un año\ny don Luis Mejía hecha?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Señor capitán, no sé\ntan a fondo la materia,\nque os pueda sacar de dudas;\npero os diré lo que sepa."}, {"type": "h", "text": "Varios"}, {"type": "v", "text": "Habla, habla."}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Yo, la verdad,\naunque fue en mi casa mesma\nla cuestión entre ambos, como\npusieron tan larga fecha\na su plazo, creí siempre\nque nunca a efecto viniera.\nAsí es que ni aun me acordaba\nde tal cosa a la hora de esta.\nMas esta tarde, sería\nal anochecer apenas,\nentrose aquí un caballero\npidiéndome que le diera\nrecado con que escribir\nuna carta, y a sus letras\natento no más, me dio\ntiempo a que charla metiera\ncon un paje que traía\npaisano mío, de Génova.\nNo saqué nada del paje,\nque es por Dios muy brava pesca;\nmas cuando su amo acababa\nla carta, le envió con ella\na quien iba dirigida;\nel caballero en mi lengua\nme habló, y me pidió noticias\nde don Luis; dijo que entera\nsabía de ambos la historia,\ny tenía la certeza\nde que al menos uno de ellos\nacudiría a la apuesta.\nYo quise saber más de él;\nmas púsome dos monedas\nde oro en la mano, diciéndome\n[así, como a la deshecha]:\n«Y por si acaso los dos\nal tiempo aplazado llegan,\nten prevenidas para ambos\ntus dos mejores botellas».\nLargose sin decir más,\ny yo, atento a sus monedas,\nles puse en el mismo sitio\ndonde apostaron, la mesa.\nY vedla allí con dos sillas,\ndos copas y dos botellas."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Pues señor, no hay que dudar;\nera don Luis."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Don Juan era."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¿Tú no le viste la cara?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Si la traía cubierta\ncon un antifaz."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Pero, hombre,\n¿tú a los dos no los recuerdas?\n¿O no sabes distinguir\na las gentes por sus señas\nlo mismo que por sus caras?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "Pues confieso mi torpeza;\nno lo supe conocer,\ny lo procuré de veras.\nPero silencio."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¿Qué pasa?"}, {"type": "h", "text": "Buttarelli"}, {"type": "v", "text": "A dar el reloj comienza\nlos cuartos para las ocho.\n(Dan.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Ved, ved la gente que se entra."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Como que está de este lance\ncuriosa Sevilla entera.\n(Se oyen dar las ocho; varias personas entran y se reparten en silencio por\nla escena; al dar la última campanada, DON JUAN, con antifaz, se llega a la\nmesa que ha preparado BUTTARELLI en el centro del escenario, y se dispone\na ocupar una de las dos sillas que están delante de ella. Inmediatamente\ndespués de él, entra DON LUIS, también con antifaz, y se dirige a la otra.\nTodos los miran.)"}]$lira$::jsonb, 748);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 4, 'Escena XII', $lira$[{"type": "h", "text": "Escena XII"}, {"type": "h", "text": "Don diego, don gonzalo, don juan, don luis,"}, {"type": "v", "text": "BUTTARELLI, CENTELLAS, AVELLANEDA, caballeros, curiosos y\nenmascarados."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "(A CENTELLAS por DON JUAN.)\nVerás aquél, si ellos vienen,\nqué buen chasco que se lleva."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "(A AVELLANEDA por DON LUIS.)\nPues allí va otro a ocupar\nla otra silla; ¡uf! aquí es ella."}, {"type": "h", "text": "Don Juan"}, {"type": "h", "text": "(a Don Luis.)"}, {"type": "v", "text": "Esa silla está comprada,\nhidalgo."}, {"type": "h", "text": "Don Luis"}, {"type": "h", "text": "(a Don Juan.)"}, {"type": "v", "text": "Lo mismo digo,\nhidalgo; para un amigo\ntengo yo esotra pagada."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Que ésta es mía haré notorio."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y yo también que ésta es mía."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Luego sois don Luis Mejía."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Seréis, pues, don Juan Tenorio."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Puede ser."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Vos lo decís."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿No os fiáis?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Yo tampoco."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues no hagamos más el coco."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Yo soy don Juan.\n(Quitándose la máscara.)"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "(Haciendo lo mismo.)\nYo don Luis.\n(Se sientan. El Capitán CENTELLAS, AVELLANEDA, BUTTARELLI y\nalgunos otros se van a ellos y les saludan, abrazan y dan la mano, y hacen\notras semejantes muestras de cariño y amistad. DON JUAN y DON LUIS las\naceptan cortésmente.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Don Juan!"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¡Don Luis!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Caballeros!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Oh, amigos! ¿Qué dicha es ésta?"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Sabíamos vuestra apuesta\ny hemos acudido a veros."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Don Juan y yo tal bondad\nen mucho os agradecemos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "El tiempo no malgastemos,\nDon Luis.\n(A los otros.)\nSillas arrimad.\n(A los que están lejos.)\nCaballeros, yo supongo\nque a ustedes también aquí\nles trae la apuesta, y por mí,\na antojo tal no me opongo."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Ni yo; que aunque nada más\nFue el empeño entre los dos,\nno ha de decirse, por Dios,\nque me avergonzó jamás."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ni a mí, que el orbe es testigo\nde que hipócrita no soy,\npues por doquiera que voy\nva el escándalo conmigo."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Eh! ¿Y esos dos no se llegan\na escuchar? Vos.\n(Por DON DIEGO y DON GONZALO.)"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Yo estoy bien."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Y vos?"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "De aquí oigo también."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Razón tendrán si se niegan.\n(Se sientan todos alrededor de la mesa en que están DON LUIS Mejía y\nDON JUAN Tenorio.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Estamos listos?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Estamos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Como quien somos cumplimos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Veamos, pues, lo que hicimos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Bebamos antes."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Bebamos.\n(Lo hacen.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "La apuesta fue..."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Porque un día\ndije que en España entera\nno habría nadie que hiciera\nlo que hiciera Luis Mejía."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y siendo contradictorio\nal vuestro mi parecer,\nyo os dije: «Nadie ha de hacer\nlo que hará don Juan Tenorio».\n¿No es así?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sin duda alguna;\ny vinimos a apostar\nquién de ambos sabría obrar\npeor, con mejor fortuna,\nen el término de un año;\njuntándonos aquí hoy\na probarlo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y aquí estoy."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y yo."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Empeño bien extraño,\npor vida mía!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Hablad, pues."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No, vos debéis empezar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Como gustéis, igual es,\nque nunca me hago esperar.\nPues señor, yo desde aquí,\nbuscando mayor espacio\npara mis hazañas, dí\nsobre Italia, porque allí\ntiene el placer un palacio.\nDe la guerra y del amor\nantigua y clásica tierra,\ny en ella el Emperador,\ncon ella y con Francia en guerra,\ndíjeme: «¿Dónde mejor?\nDonde hay soldados, hay juego,\nhay pendencias y amoríos».\nDí, pues, sobre Italia luego,\nbuscando a sangre y a fuego\namores y desafíos.\nEn Roma, a mi apuesta fiel,\nfijé entre hostil y amatorio\nen mi puerta este cartel:\n«Aquí está don Juan Tenorio\npara quien quiera algo de él».\nDe aquellos días la historia\na relataros renuncio;\nremítome a la memoria\nque dejé allí, y de mi gloria\npodéis juzgar por mi anuncio.\nLas romanas caprichosas,\nlas costumbres licenciosas,\nyo gallardo y calavera,\nquién a cuento redujera\nmis empresas amorosas.\nSalí de Roma por fin\ncomo os podéis figurar,\ncon un disfraz harto ruin,\ny a lomos de un mal rocín,\npues me querían ahorcar.\nFui al ejército de España;\nmas todos paisanos míos,\nsoldados y en tierra extraña,\ndejé pronto su compaña\ntras cinco o seis desafíos.\nNápoles, rico vergel\nde amor, de placer emporio,\nvio en mi segundo cartel:\n«Aquí está don Juan Tenorio,\ny no hay hombre para él.\nDesde la princesa altiva\na la que pesca en ruin barca,\nno hay hembra a quien no suscriba,\ny cualquiera empresa abarca\nsi en oro o valor estriba.\nBúsquenle los reñidores;\ncérquenle los jugadores;\nquien se precie, que le ataje;\na ver si hay quien le aventaje\nen juego, en lid o en amores».\nEsto escribí; y en medio año\nque mi presencia gozó\nNápoles, no hay lance extraño,\nno hubo escándalo ni engaño\nen que no me hallara yo.\nPor dondequiera que fui,\nla razón atropellé,\nla virtud escarnecí,\na la justicia burlé\ny a las mujeres vendí.\nYo a las cabañas bajé,\nyo a los palacios subí,\nyo los claustros escalé,\ny en todas partes dejé\nmemoria amarga de mí.\nNi reconocí sagrado,\nni hubo razón ni lugar\npor mi audacia respetado;\nni en distinguir me he parado\nal clérigo del seglar.\nA quien quise provoqué,\ncon quien quiso me batí,\ny nunca consideré\nque pudo matarme a mí\naquel a quien yo maté.\nA esto don Juan se arrojó,\ny escrito en este papel\nestá cuanto consiguió,\ny lo que él aquí escribió,\nmantenido está por él."}]$lira$::jsonb, 921);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 5, 'Parte 6', $lira$[{"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Leed, pues."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No; oigamos antes\nvuestros bizarros extremos,\ny si traéis terminantes\nvuestras notas comprobantes,\nlo escrito cotejaremos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Decís bien; cosa es que está,\nDon Juan, muy puesta en razón;\naunque, a mi ver, poco irá\nde una a otra relación."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Empezad, pues."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Allá va.\nBuscando yo, como vos,\na mi aliento empresas grandes,\ndije: «¿Dó iré, ¡vive Dios!\nde amor y lides en pos\nque vaya mejor que a Flandes?\nAllí, puesto que empeñadas\nguerras hay, a mis deseos\nhabrá al par centuplicadas\nocasiones extremadas\nde riñas y galanteos».\nY en Flandes conmigo dí,\nmas con tan negra fortuna,\nque al mes de encontrarme allí\ntodo mi caudal perdí,\ndobla a dobla, una por una.\nEn tan total carestía\nmirándome de dineros,\nde mí todo el mundo huía,\nmas yo busqué compañía\ny me uní a unos bandoleros.\nLo hicimos bien, ¡voto a tal!,\ny fuimos tan adelante,\ncon suerte tan colosal,\nque entramos a saco en Gante\nel palacio episcopal.\n¡Qué noche! Por el decoro\nde la Pascua, el buen obispo\nbajó a presidir el coro,\ny aún de alegría me crispo\nal recordar su tesoro.\nTodo cayó en poder nuestro;\nmas mi capitán, avaro,\npuso mi parte en secuestro;\nreñimos, yo fui más diestro,\ny le crucé sin reparo.\nJurome al punto la gente\ncapitán, por más valiente;\njureles yo amistad franca;\npero a la noche siguiente\nhuí y les dejé sin blanca.\nYo me acordé del refrán\nde que quien roba al ladrón\nha cien años de perdón,\ny me arrojé a tal desmán\nmirando a mi salvación.\nPasé a Alemania opulento,\nmas un Provincial jerónimo,\nhombre de mucho talento,\nme conoció, y al momento\nme delató en un anónimo.\nCompré a fuerza de dinero\nla libertad y el papel;\ny topando en un sendero\nal fraile, le envié certero\nuna bala envuelta en él.\nSalté a Francia, ¡buen país!,\ny como en Nápoles vos,\npuse un cartel en París\ndiciendo: «Aquí hay un don Luis\nque vale lo menos dos.\nParará aquí algunos meses,\ny no trae más intereses\nni se aviene a más empresas,\nque a adorar a las francesas\ny a reñir con los franceses».\nEsto escribí; y en medio año\nque mi presencia gozó\nParís, no hubo lance extraño,\nni hubo escándalo ni daño\ndonde no me hallara yo.\nMas como don Juan, mi historia\ntambién a alargar renuncio;\nque basta para mi gloria\nla magnífica memoria\nque allí dejé con mi anuncio.\nY cual vos, por donde fui\nla razón atropellé,\nla virtud escarnecí,\na la justicia burlé,\ny a las mujeres vendí.\nMi hacienda llevo perdida\ntres veces; mas se me antoja\nreponerla, y me convida\nmi boda comprometida\ncon doña Ana de Pantoja.\nMujer muy rica me dan,\ny mañana hay que cumplir\nlos tratos que hechos están;\nlo que os advierto, don Juan,\npor si queréis asistir.\nA esto don Luis se arrojó,\ny escrito en este papel\nestá lo que consiguió;\ny lo que él aquí escribió\nmantenido está por él."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "La historia es tan semejante\nque está en el fiel la balanza;\nmas vamos a lo importante,\nque es el guarismo a que alcanza\nel papel; conque adelante."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Razón tenéis en verdad.\nAquí está el mío; mirad,\npor una línea apartados\ntraigo los nombres sentados\npara mayor claridad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Del mismo modo arregladas\nmis cuentas traigo en el mío;\nen dos líneas separadas\nlos muertos en desafío\ny las mujeres burladas.\nContad."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Contad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Veintitrés."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Son los muertos. A ver vos.\n¡Por la cruz de San Andrés!\nAquí sumo treinta y dos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Son los muertos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Matar es."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Nueve os llevo."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Me vencéis.\nPasemos a las conquistas."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sumo aquí cincuenta y seis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y yo sumo en vuestras listas\nsetenta y dos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues perdéis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Es increíble, don Juan!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Si lo dudáis, apuntados\nlos testigos ahí están,\nque si fueren preguntados\nos lo testificarán."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Oh! Y vuestra lista es cabal."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Desde una princesa real\na la hija de un pescador,\n¡oh! ha recorrido mi amor\ntoda la escala social.\n¿Tenéis algo que tachar?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sólo una os falta en justicia."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Me la podéis señalar?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sí, por cierto; una novicia\nque esté para profesar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Bah! pues yo os complaceré\ndoblemente, porque os digo\nque a la novicia uniré\nla dama de algún amigo\nque para casarse esté."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Pardiez, que sois atrevido!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Yo os lo apuesto si queréis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Digo que acepto el partido.\n¿Para darlo por perdido,\nqueréis veinte días?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Seis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Por Dios, que sois hombre extraño!\n¿Cuántos días empleáis\nen cada mujer que amáis?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Partid los días del año\nentre las que ahí encontráis.\nUno para enamorarlas,\notro para conseguirlas,\notro para abandonarlas,\ndos para sustituirlas,\ny una hora para olvidarlas.\nPero la verdad a hablaros,\npedir más no se me antoja,\nporque, pues vais a casaros,\nmañana pienso quitaros\na doña Ana de Pantoja."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Don Juan, ¿qué es lo que decís?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Don Luis, lo que oído habéis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Ved, don Juan, lo que emprendéis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Lo que he de lograr, don Luis."}]$lira$::jsonb, 900);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 6, 'Parte 7', $lira$[{"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Gastón!"}, {"type": "h", "text": "Gastón"}, {"type": "v", "text": "Señor."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Ven acá.\n(Habla DON LUIS en secreto con GASTÓN, y éste se va\nprecipitadamente.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ciutti!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Señor."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ven aquí.\n(DON JUAN habla también con CIUTTI, que hace lo mismo.)"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Estáis en lo dicho?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues va la vida."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues va.\n(DON GONZALO, levantándose de la mesa en que ha permanecido\ninmóvil durante la escena anterior, se afronta con DON JUAN y DON LUIS.)"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Insensatos! Vive Dios,\nque a no temblarme las manos,\na palos, como a villanos,\nos diera muerte a los dos.\nDON JUAN y"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Veamos."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Excusado es,\nque he vivido lo bastante\npara no estar arrogante\ndonde no puedo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Idos, pues."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Antes, don Juan, de salir\nde donde oírme podáis,\nes necesario que oigáis\nlo que os tengo que decir.\nVuestro buen padre don Diego,\nporque pleitos acomoda,\nos apalabró una boda\nque iba a celebrarse luego;\npero por mí mismo yo,\nlo que erais queriendo ver,\nvine aquí al anochecer,\ny el veros me avergonzó."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Por Satanás, viejo insano,\nque no sé cómo he tenido\ncalma para haberte oído\nsin asentarte la mano!\n¡Pero di pronto quién eres,\nporque me siento capaz\nde arrancarte el antifaz\ncon el alma que tuvieres!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Don Juan!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Pronto!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Mira, pues."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Don Gonzalo!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "El mismo soy.\nY adiós, don Juan; más desde hoy\nno penséis en doña Inés.\nPorque antes que consentir\nen que se case con vos,\nel sepulcro, ¡juro a Dios!,\npor mi mano la he de abrir."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Me hacéis reír, don Gonzalo;\npues venirme a provocar,\nes como ir a amenazar\na un león con un mal palo.\nY pues hay tiempo, advertir\nos quiero a mi vez a vos\nque, o me la dais, o por Dios\nque a quitárosla he de ir."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Miserable!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Dicho está;\nsólo una mujer como ésta\nme falta para mi apuesta;\nved, pues, que apostada va.\n(DON DIEGO, levantándose de la mesa en que ha permanecido encubierto\nmientras la escena anterior, baja al centro de la escena, encarándose con DON"}, {"type": "h", "text": "Juan.)"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "No puedo más escucharte,\nvil don Juan, porque recelo\nque hay algún rayo en el cielo\npreparado a aniquilarte.\n¡Ah...! No pudiendo creer\nlo que de ti me decían,\nconfiando en que mentían,\nte vine esta noche a ver.\nPero te juro, malvado,\nque me pesa haber venido\npara salir convencido\nde lo que es para ignorado.\nSigue, pues, con ciego afán\nen tu torpe frenesí,\nmas nunca vuelvas a mí;\nno te conozco, don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Quién nunca a ti se volvió,\nni quién osa hablarme así,\nni qué se me importa a mí\nque me conozcas o no?"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Adiós, pues; mas no te olvides\nde que hay un Dios justiciero."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ten.\n(Deteniéndole.)"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Qué quieres?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Verte quiero."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Nunca; en vano me lo pides."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Nunca?"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "No."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Cuando me cuadre."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¿Cómo?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Así.\n(Le arranca el antifaz.)"}, {"type": "h", "text": "Todos"}, {"type": "v", "text": "¡Don Juan!"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "¡Villano!\n¡Me has puesto en la faz la mano!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Válgame Cristo, mi padre!"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Mientes; no lo fui jamás."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Reportaos, con Belcebú!"}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "No; los hijos como tú\nson hijos de Satanás.\nComendador, nulo sea\nlo hablado."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Ya lo es por mí;\nvamos."}, {"type": "h", "text": "Don Diego"}, {"type": "v", "text": "Sí; vamos de aquí,\ndonde tal monstruo no vea.\nDon Juan, en brazos del vicio\ndesolado te abandono;\nme matas... mas te perdono\nde Dios en el santo juicio.\n(Vanse poco a poco DON DIEGO y DON GONZALO.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Largo el plazo me ponéis;\nmas ved que os quiero advertir\nque yo no os he ido a pedir\njamás que me perdonéis.\nConque no paséis afán\nde aquí adelante por mí,\nque como vivió hasta aquí,\nvivirá siempre don Juan."}]$lira$::jsonb, 672);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 7, 'Escena XIII', $lira$[{"type": "h", "text": "Escena XIII"}, {"type": "h", "text": "Don juan, don luis, centellas, avellaneda,"}, {"type": "v", "text": "BUTTARELLI, curiosos y máscaras."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Eh! Ya salimos del paso;\ny no hay que extrañar la homilía;\nson pláticas de familia\nde las que nunca hice caso.\nConque lo dicho, don Luis,\nvan doña Ana y doña Inés\nen puesta."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y el precio es\nla vida."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vos lo decís;\nvamos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Vamos.\n(Al salir, se presenta una ronda que les detiene.)"}, {"type": "h", "text": "Escena XIV"}, {"type": "v", "text": "Dichos y una ronda de Alguaciles."}, {"type": "h", "text": "Alguacil"}, {"type": "v", "text": "¡Alto allá!\n¿Don Juan Tenorio?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Yo soy."}, {"type": "h", "text": "Alguacil"}, {"type": "v", "text": "Sed preso."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Soñando estoy!\n¿Por qué?"}, {"type": "h", "text": "Alguacil"}, {"type": "v", "text": "Después lo verá."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "(Acercándose a DON JUAN y riéndose.)\nTenorio, no lo extrañéis,\npues mirando a lo apostado,\nmi paje os ha delatado\npara que vos no ganéis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Hola! Pues no os suponía\ncon tal despejo, ¡pardiez!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Id, pues; que por esta vez,\ndon Juan, la partida es mía."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vamos, pues.\n(Al salir, les detiene otra ronda que entra en la escena.)"}, {"type": "h", "text": "Escena XV"}, {"type": "v", "text": "Dichos y una ronda."}, {"type": "h", "text": "Alguacil"}, {"type": "v", "text": "(Que entra.)\nTénganse allá.\n¿Don Luis Mejía?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Yo soy."}, {"type": "h", "text": "Alguacil"}, {"type": "v", "text": "Sed preso."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Soñando estoy!\n¡Yo preso!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Soltando la carcajada.)\n¡Ja, ja, ja, ja!\nMejía, no lo extrañéis,\npues mirando a lo apostado,\nmi paje es ha delatado\npara que no me estorbéis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Satisfecho quedaré\naunque ambos muramos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vamos:\nconque, señores, quedamos\nen que la apuesta está en pie.\n(Las rondas se llevan a DON JUAN y a DON LUIS; muchos los siguen. El\nCapitán CENTELLAS, AVELLANEDA y sus amigos quedan en la escena\nmirándose unos a otros.)"}, {"type": "h", "text": "Escena XVI"}, {"type": "v", "text": "El Capitán CENTELLAS, AVELLANEDA y curiosos."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¡Parece un juego ilusorio!"}, {"type": "h", "text": "Centelllas"}, {"type": "v", "text": "¡Sin verlo no lo creería!"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Pues yo apuesto por Mejía."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Y yo pongo por Tenorio."}, {"type": "h", "text": "Acto II"}, {"type": "h", "text": "Destreza"}, {"type": "v", "text": "DON JUAN Tenorio, DON LUIS Mejía, DOÑA ANA de Pantoja,\nCIUTTI, PASCUAL, LUCÍA y BRÍGIDA.\nTres embozados del servicio de DON JUAN.\nExterior de la casa de DOÑA ANA, vista por una esquina. Las dos paredes\nque forman el ángulo se prolongan igualmente por ambos lados, dejando ver\nen la de la derecha una reja, y en la de la izquierda una reja y una puerta."}]$lira$::jsonb, 377);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 8, 'Escena I', $lira$[{"type": "h", "text": "Escena I"}, {"type": "v", "text": "DON LUIS Mejía, embozado."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Ya estoy frente de la casa\nde doña Ana, y es preciso\nque esta noche tenga aviso\nde lo que en Sevilla pasa.\nNo dí con persona alguna\npor dicha mía... ¡Oh, qué afán!\nPor ahora, señor don Juan,\ncada cual con su fortuna.\nSi honor y vida se juega,\nmi destreza y mi valor\npor mi vida y por mi honor\njugarán... mas alguien llega."}, {"type": "h", "text": "Escena II"}, {"type": "h", "text": "Don Luis, Pascual"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¡Quién creyera lance tal!\n¡Jesús, qué escándalo! ¡Presos!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Qué veo! ¿Es Pascual?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Los sesos\nme estrellaría."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Pascual?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Quién me llama tan apriesa?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Yo. Don Luis."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¡Válame Dios!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Qué te asombra?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Que seáis vos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Mi suerte, Pascual, es esa.\nQue a no ser yo quien me soy\ny a no dar contigo ahora,\nel honor de mi señora\ndoña Ana moría hoy."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Qué es lo que decís?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Conoces\na don Juan Tenorio?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Sí.\n¿Quién no le conoce aquí?\nMas, según públicas voces,\nestabais presos los dos.\n¡Vamos, lo que el vulgo miente!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Ahora acertadamente\nhabló el vulgo; y juro a Dios\nque a no ser porque mi primo,\nel tesorero real,\nquiso fiarme, Pascual,\npierdo cuanto más estimo."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Pues cómo?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿En servirme estás?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Hasta morir."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues escucha.\nDon Juan y yo en una lucha\narriesgada por demás\nempeñados nos hallamos;\npero a querer tú ayudarme,\nmás que la vida salvarme\npuedes."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Qué hay que hacer? Sepamos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "En una insigne locura\ndimos tiempo ha; en apostar\ncuál de ambos sabría obrar\npeor, con mejor ventura.\nAmbos nos hemos portado\nbizarramente a cual más;\npero él es un Satanás,\ny por fin me ha aventajado.\nPúsele no sé qué pero,\nDijímonos no sé qué\nsobre ello, y el hecho fue\nque él, mofándose altanero,\nme dijo: «Y si esto no os llena,\npues que os casáis con doña Ana,\nos apuesto a que mañana\nos la quito yo»."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¡Esa es buena!\n¿Tal se ha atrevido a decir?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No es lo malo que lo diga,\nPascual, sino que consiga\nlo que intenta."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Conseguir?\nEn tanto que yo esté aquí,\ndescuidad, don Luis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Te juro\nque si el lance no aseguro,\nno sé qué va a ser de mí."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Por la Virgen del Pilar,\n¿le teméis?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No; ¡Dios testigo!\nMas lleva ese hombre consigo\nalgún diablo familiar."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Dadlo por asegurado."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Oh! Tal es el afán mío\nque ni en mí propio me fío\ncon un hombre tan osado."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Yo os juro, por San Ginés,\nque con toda su osadía,\nle ha de hacer, por vida mía,\nmal tercio un aragonés;\nnos veremos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Ay, Pascual,\nque en qué te metes no sabes!"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "En apreturas más graves\nme he visto, y no salí mal."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Estriba en lo perentorio\ndel plazo, y en ser quien es."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Más que un buen aragonés,\nno ha de valer un Tenorio.\nTodos esos lenguaraces,\nespadachines de oficio,\nno son más que frontispicio\ny de poca alma capaces.\nPara infamar a mujeres\ntienen lengua, y tienen manos\npara osar a los ancianos\no apalear a mercaderes.\nMas cuando una buena espada\npor un buen brazo esgrimida\ncon la muerte les convida,\ntodo su valor es nada.\nY sus empresas y bullas\nse reducen todas ellas\na hablar mal de las doncellas\ny a huir ante las patrullas."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Pascual!"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "No lo hablo por vos,\nque aunque sois un calavera,\ntenéis la alma bien entera\ny reñís bien, ¡voto a bríos!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues si es en mí tan notorio\nel valor, mira, Pascual,\nque el valor es proverbial\nen la raza de Tenorio.\nY porque conozco bien\nde su valor el extremo,\nde sus ardides me temo\nque en tierra con mi honra den."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Pues suelto estáis ya, don Luis,\ny pues que tanto os acucia\nel mal de celos, su astucia\ncon la astucia prevenís.\n¿Qué teméis de él?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No lo sé;\nmas esta noche sospecho\nque ha de procurar el hecho\nconsumar."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Soñáis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Por qué?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿No está preso?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sí que está;\nmas también lo estaba yo,\ny un hidalgo me fió"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Mas, ¿quién a él le fiará?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "En fin, sólo un medio encuentro\nde satisfacerme."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Cuál?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Que de esta casa, Pascual,\nquede yo esta noche dentro."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Mirad que así de doña Ana\ntenéis el honor vendido."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Qué mil rayos! ¿Su marido\nno voy a ser yo mañana?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Mas, señor, ¿no os digo yo\nque os fío con la existencia?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sí; salir de una pendencia,\nmas de un ardid diestro, no.\nY en fin, o paso en la casa\nla noche, o tomo la calle\naunque la justicia me halle."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Señor don Luis, eso pasa\nde terquedad, y es capricho\nque dejar os aconsejo,\ny os irá bien."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No lo dejo,\nPascual."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¡Don Luis!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Está dicho."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¡Vive Dios! ¿Hay tal afán?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Tú dirás lo que quisieres,\nmas yo fío en las mujeres\nmucho menos que en don Juan.\nY pues lance es extremado\npor dos locos emprendido,\nbien será un loco atrevido\npara un loco desalmado."}]$lira$::jsonb, 904);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 9, 'Parte 10', $lira$[{"type": "h", "text": "Pascual"}, {"type": "v", "text": "Mirad bien lo que decís,\nporque yo sirvo a doña Ana\ndesde que nació, y mañana\nseréis su esposo, don Luis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pascual, esa hora llegada\ny ese derecho adquirido,\nyo sabré ser su marido\ny la haré ser bien casada.\nMas en tanto..."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "No habléis más.\nYo os conozco desde niños,\ny sé lo que son cariños,\n¡por vida de Barrabás!\nOíd: mi cuarto es sobrado\npara los dos; dentro de él\nquedad; mas palabra fiel\ndadme de estaros callado."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Te la doy."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Y hasta mañana,\njuntos con doble cautela\nnos quedaremos en vela."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y se salvará doña Ana."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Sea."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues vamos."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Teneos.\n¿Qué vais a hacer?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "A entrar."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¿Ya?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Quién sabe lo que él hará?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Vuestros celosos deseos\nreprimid, que ser no puede\nmientras que no se recoja\nmi amo don Gil de Pantoja\ny todo en silencio quede."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Voto a...!"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "¡Eh! Dad una vez\nbreves treguas al amor."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Y a qué hora ese buen señor\nsuele acostarse?"}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "A las diez;\ny en esa calleja estrecha\nhay una reja; llamad\na las diez, y descuidad\nmientras en mí."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Es cosa hecha."}, {"type": "h", "text": "Pascual"}, {"type": "v", "text": "Don Luis, hasta luego, pues."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Adiós, Pascual, hasta luego."}, {"type": "h", "text": "Escena III"}, {"type": "v", "text": "DON LUIS, solo."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Jamás tal desasosiego\ntuve. Paréceme que es\nesta noche hora menguada\npara mí... y no sé qué vago\npresentimiento, qué estrago\nteme mi alma acongojada.\nPor Dios que nunca pensé\nque a doña Ana amara así,\nni por ninguna sentí\nlo que por ella... ¡Oh! Y a fe\nque de don Juan me amedrenta,\nno el valor, mas la ventura.\nParece que le asegura\nSatanás en cuanto intenta.\nNo, no; es un hombre infernal,\ny téngome para mí\nque si me aparto de aquí\nme burla, pese a Pascual.\nY, aunque me tenga por necio,\nquiero entrar; que con don Juan\nlas precauciones no están\npara vistas con desprecio.\n(Llama a la ventana.)"}]$lira$::jsonb, 341);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 10, 'Escena IV', $lira$[{"type": "h", "text": "Escena IV"}, {"type": "v", "text": "DON LUIS y DOÑA ANA."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "¿Quién va?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿No es Pascual?"}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "¡Don Luis!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Doña Ana!"}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "¿Por la ventana\nllamas ahora?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Ay, doña Ana,\ncuán a buen tiempo salís!"}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "¿Pues qué hay, Mejía?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Un empeño\npor tu beldad con un hombre\nque temo."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "¿Y qué hay que te asombre\nen él, cuando eres tú el dueño\nde mi corazón?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Doña Ana,\nno lo puedes comprender\nde ese hombre sin conocer\nnombre y suerte."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Será vana\nsu buena suerte conmigo;\nya ves, sólo horas nos faltan\npara la boda, y te asaltan\nvanos temores."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Testigo\nme es Dios que nada por mí\nme da pavor mientras tenga\nespada, y ese hombre venga\ncara a cara contra ti.\nMas como el león audaz,\ny cauteloso y prudente\ncomo la astuta serpiente..."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "¡Bah! Duerme, don Luis, en paz,\nque su audacia y su prudencia\nnada lograrán de mí,\nque tengo cifrada en ti\nla gloria de mi existencia."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues bien, Ana, de ese amor\nque me aseguras en nombre,\npara no temer a ese hombre,\nvoy a pedirte un favor."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Di; mas bajo, por si escucha\ntal vez alguno."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Oye, pues."}, {"type": "h", "text": "Escena V"}, {"type": "v", "text": "DOÑA ANA y DON LUIS, a la reja derecha; DON JUAN y CIUTTI, en la\ncalle izquierda."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Señor, por mi vida que es\nvuestra suerte buena y mucha."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ciutti, nadie como yo;\nya viste cuán fácilmente\nel buen Alcaide prudente\nse avino, y suelta me dio.\nMas no hay ya en ello que hablar;\n¿mis encargos has cumplido?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Todos los he concluido\nmejor que pude esperar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿La beata...?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Esta es la llave\nde la puerta del jardín,\nque habrá que escalar al fin;\npues como usarced ya sabe,\nlas tapias de este convento\nno tienen entrada alguna."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y te dio carta?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Ninguna;\nme dijo que aquí al momento\niba a salir de camino;\nque al convento se volvía,\ny que con vos hablaría."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mejor es."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Lo mismo opino."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y los caballos?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Con silla\ny freno los tengo ya."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y la gente?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Cerca está."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Bien, Ciutti; mientras Sevilla\ntranquila en sueño reposa\ncreyéndome encarcelado,\notros dos nombres añado\na mi lista numerosa.\n¡Ja, ja!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Señor."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Callad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué hay, Ciutti?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Al doblar la esquina\nen esa reja vecina\nhe visto un hombre."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Es verdad;\npues ahora sí que es mejor\nel lance; ¿y si es ése...?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "¿Quién?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Don Luis."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Imposible."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Toma!\n¿No estoy yo aquí?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Diferencia\nva de él a vos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Evidencia\nlo creo, Ciutti; allí asoma\ntras de la reja una dama."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Una criada tal vez."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Preciso es verlo, pardiez,\nno perdamos lance y fama.\nMira, Ciutti; a fuer de ronda,\ntú con varios de los míos,\npor esa calle escurríos\ndando vuelta a la redonda\na la casa."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Y en tal caso\ncerrará ella."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues con eso,\nella ignorante y él preso,\nnos dejará franco el paso."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Decís bien."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Corre, y atájale,\nque en ello el vencer consiste."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "¿Mas si el truhán se resiste?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Entonces de un tajo rájale."}]$lira$::jsonb, 573);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 11, 'Escena VI', $lira$[{"type": "h", "text": "Escena VI"}, {"type": "v", "text": "DON JUAN, DOÑA ANA y DON LUIS."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Me das, pues, tu asentimiento?"}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Consiento."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Complácesme de ese modo?"}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "En todo."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues te velaré hasta el día."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Sí, Mejía."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Páguete el cielo, Ana mía,\nsatisfacción tan entera."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Porque me juzgues sincera,\nconsiento en todo, Mejía."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Volveré, pues, otra vez."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Sí, a las diez."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Me aguardarás, Ana?"}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Aquí."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Y tú estarás puntual, ¿eh?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Estaré."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "La llave, pues, te daré."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y dentro yo de tu casa,\nvenga Tenorio."}, {"type": "h", "text": "Doña Ana"}, {"type": "v", "text": "Alguien pasa.\nA las diez."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Aquí estaré."}, {"type": "h", "text": "Escena VII"}, {"type": "v", "text": "DON JUAN y DON LUIS."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Mas se acercan. ¿Quién va allá?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Quien va."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "De quien va así, ¿qué se infiere?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Que quiere..."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Ver si la lengua le arranco?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "El paso franco."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Guardado está."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y yo soy manco?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pidiéraislo en cortesía."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y a quién?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "A don Luis Mejía."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Quien va, quiere el paso franco."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Conocéisme?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Y yo a vos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Los dos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Y en qué estriba el estorballe?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "En la calle."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿De ella los dos por ser amos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Estamos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Dos hay no más que podamos\nnecesitarla a la vez."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Lo sé."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Sois don Juan!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Pardiez!\nLos dos ya en la calle estamos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿No os prendieron?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Como a vos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Vive Dios!\n¿Y huisteis?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Os imité.\n¿Y qué?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Que perderéis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No sabemos."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Lo veremos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "La dama entrambos tenemos\nsitiada; y estáis cogido."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Tiempo hay."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Para vos perdido."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Vive Dios que lo veremos!\n(DON LUIS desenvaina su espada; mas CIUTTI, que ha bajado con los\nsuyos cautelosamente hasta colocarse detrás de él, lo sujeta.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Señor don Luis, vedlo, pues."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Traición es."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "La boca...\n(A los suyos que le tapan a DON LUIS.)"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Oh!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sujeto atrás,\nmás.\n(Le sujetan los brazos.)\nLa empresa es, señor Mejía,\ncomo mía.\n(A los suyos.)\nEncerrádmele hasta el día."}, {"type": "h", "text": "(a Don Luis.)"}, {"type": "v", "text": "La apuesta está ya en mi mano.\nAdiós, don Luis; si os la gano,\ntraición es, mas como mía."}]$lira$::jsonb, 426);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 12, 'Escena VIII', $lira$[{"type": "h", "text": "Escena VIII"}, {"type": "v", "text": "DON JUAN, solo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Buen lance, ¡viven los cielos!\n¡Estos son los que dan fama!\nMientras le soplo la dama,\nél se arrancará los pelos\nencerrado en mi bodega.\n¿Y ella...? Cuando crea hallarse\ncon él... ¡ja! ¡ja!... ¡Oh! y quejarse\nno puede; limpio se juega.\nA la cárcel le llevé,\ny salió; llevome a mí,\ny salí; hallarnos aquí\nera fuerza... ya se ve,\nsu parte en la grave apuesta\ndefendía cada cual.\nMas con la suerte está mal\nMejía, y también pierde ésta.\nSin embargo, y por si acaso,\nno es demás asegurarse\nde Lucía, a desgraciarse\nno vaya por poco el paso.\nMas por allí un bulto negro\nse aproxima... y, a mi ver,\nes el bulto una mujer.\n¿Otra aventura? Me alegro."}, {"type": "h", "text": "Escena IX"}, {"type": "v", "text": "DON JUAN y BRÍGIDA."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Caballero?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Quién va allá?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Sois don Juan?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Por vida de...!\n¡Si es la beata! Y a fe\nque la había olvidado ya.\nLlegaos; don Juan soy yo."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Estáis solo?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Con el diablo."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Jesucristo!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Por vos lo hablo."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Soy yo el diablo?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Creoló."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Vaya! ¡Qué cosas tenéis!\nVos sí que sois un diablillo..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Que te llenará el bolsillo\nsi le sirves."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Lo veréis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Descarga, pues, ese pecho.\n¿Qué hiciste?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Cuanto me ha dicho\nvuestro paje... ¡Y qué mal bicho\nes ese Ciutti!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué ha hecho?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Gran bribón!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿No os ha entregado\nun bolsillo y un papel?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Leyendo estará ahora en él\ndoña Inés."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿La has preparado?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Vaya! Y os la he convencido\ncon tal maña y de manera,\nque irá como una cordera\ntras vos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Tan fácil te ha sido?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Bah! Pobre garza enjaulada,\ndentro la jaula nacida,\n¿qué sabe ella si hay más vida\nni más aire en que volar?\nSi no vio nunca sus plumas\ndel sol a los resplandores,\n¿qué sabe de los colores\nde que se puede ufanar?\nNo cuenta la pobrecilla\ndiez y siete primaveras,\ny aún virgen a las primeras\nimpresiones del amor,\nnunca concibió la dicha\nfuera de su pobre estancia,\ntratada desde la infancia\ncon cauteloso rigor.\nY tantos años monótonos\nde soledad y convento\ntenían su pensamiento\nceñido a punto tan ruin,\na tan reducido espacio\ny a círculo tan mezquino,\nque era el claustro su destino\ny el altar era su fin.\n«Aquí está Dios», la dijeron;\ny ella dijo: «Aquí le adoro».\n«Aquí está el claustro y el coro».\nY pensó: «No hay más allá».\nY sin otras ilusiones\nque sus sueños infantiles,\npasó diez y siete abriles\nsin conocerlo quizá."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y está hermosa?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Oh! como un ángel."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y la has dicho..."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Figuraos\nsi habré metido mal caos\nen su cabeza, don Juan.\nLa hablé del amor, del mundo,\nde la corte y los placeres,\nde cuánto con las mujeres\nerais pródigo y galán.\nLa dije que erais el hombre\npor su padre destinado\npara suyo; os he pintado\nmuerto por ella de amor,\ndesesperado por ella,\ny por ella perseguido,\ny por ella decidido\na perder vida y honor.\nEn fin, mis dulces palabras\nal posarse en sus oídos,\nsus deseos mal dormidos\narrastraron de sí en pos;\ny allá dentro de su pecho\nhan inflamado una llama\nde fuerza tal, que ya os ama\ny no piensa más que en vos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tan incentiva pintura\nlos sentidos me enajena,\ny el alma ardiente me llena\nde su insensata pasión.\nEmpezó por una apuesta,\nsiguió por un devaneo,\nengendró luego un deseo,\ny hoy me quema el corazón.\nPoco es el centro de un claustro;\n¡al mismo infierno bajara,\ny a estocadas la arrancara\nde los brazos de Satán!\n¡Oh, hermosa flor cuyo cáliz\nal rocío aún no se ha abierto!\nA trasplantarte va al huerto\nde sus amores don Juan.\n¡Brígida!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Os estoy oyendo,\ny me hacéis perder el tino;\nyo os creía un libertino\nsin alma y sin corazón."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Eso extrañas? ¿No está claro\nque en un objeto tan noble\nhay que interesarse doble\nque en otros?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Tenéis razón."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Conque ¿a qué hora se recogen\nlas madres?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Ya recogidas\nestarán. ¿Vos prevenidas\ntodas las cosas tenéis?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Todas."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Pues luego que doblen\na las ánimas, con tiento\nsaltando al huerto, al convento\nfácilmente entrar podéis\ncon la llave que os he enviado;\nde un claustro obscuro y estrecho\nes, seguid bien derecho,\ny daréis con poco afán\nen nuestra celda."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y si acierto\na robar tan gran tesoro,\nte he de hacer pesar en oro."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Por mí no queda, don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ve y aguárdame."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Voy, pues,\na entrar por la portería,\ny a cegar a sor María\nla tornera. Hasta después.\n(Vase BRÍGIDA, y un poco antes de concluir esta escena, sale CIUTTI,\nque se para en el fondo esperando.)"}]$lira$::jsonb, 834);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 13, 'Escena X', $lira$[{"type": "h", "text": "Escena X"}, {"type": "v", "text": "DON JUAN y CIUTTI."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Pues señor, soberbio envite!\nMuchas hice hasta esta hora,\nmas, por Dios, que la de ahora\nserá tal que me acredite.\nMas ya veo que me espera\nCiutti. ¡Lebrel!\n(Llamándole.)"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Aquí estoy."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y don Luis?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Libre por hoy\nestáis de él."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ahora quisiera\nver a Lucía."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Llegar\npodéis aquí.\n(A la reja derecha.)\nYo la llamo,\ny al salir a mi reclamo\nla podéis vos abordar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Llama, pues."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "La seña mía\nsabe bien para que dude\nen acudir."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues si acude,\nlo demás es cuenta mía.\n(CIUTTI llama a la reja con una seña que parezca convenida. LUCÍA se\nasoma a ella, y al ver a DON JUAN se detiene un momento.)"}, {"type": "h", "text": "Escena XI"}, {"type": "v", "text": "DON JUAN, LUCÍA y CIUTTI."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Qué queréis, buen caballero?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Quiero."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Qué queréis? Vamos a ver."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ver."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Ver? ¿Qué veréis a esta hora?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "A tu señora."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "Idos, hidalgo, en mal hora:\n¿quién pensáis que vive aquí?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Doña Ana Pantoja, y\nquiero ver a tu señora."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Sabéis que casa doña Ana?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí, mañana."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Y ha de ser tan infiel ya?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí será."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Pues no es de don Luis Mejía?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ca! otro día.\nHoy no es mañana, Lucía;\nyo he de estar hoy con doña Ana,\ny si se casa mañana,\nmañana será otro día."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Ah! ¿En recibiros está?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Podrá."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Qué haré si os he de servir?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Abrir."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Bah! ¿Y quién abre este castillo?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ese bolsillo."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Oro!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pronto te dio el brillo."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Cuánto?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "De cien doblas pasa."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Jesús!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Cuenta, y di: ¿esta casa\npodrá abrir ese bolsillo?"}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Oh! Si es quien me dora el pico..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Muy rico.\n(Interrumpiéndola.)"}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Sí? ¿Qué nombre usa el galán?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Don Juan."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Sin apellido notorio?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tenorio."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Ánimas del purgatorio!\n¿Vos don Juan?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué te amedrenta,\nsi a tus ojos se presenta\nmuy rico don Juan Tenorio?"}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "Rechina la cerradura."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Se asegura."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Y a mí quién? ¡Por Belcebú!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tú."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Y qué me abrirá el camino?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Buen tino."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Bah! Id en brazos del destino..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Dobla el oro."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "Me acomodo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues mira cómo de todo\nse asegura tu buen tino."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¡Dadme algún tiempo, pardiez!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "A las diez."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Dónde os busco, o vos a mí?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Aquí."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "¿Conque estaréis puntual, eh?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Estaré."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "Pues yo una llave os traeré."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y yo otra igual cantidad."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "No me faltéis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No en verdad;\na las diez aquí estaré.\nAdiós, pues, y en mí te fía."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "Y en mí el garboso galán."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Adiós, pues, franca Lucía."}, {"type": "h", "text": "Lucía"}, {"type": "v", "text": "Adiós, pues, rico don Juan.\n(LUCÍA cierra la ventana. CIUTTI se acerca a DON JUAN a una seña de\néste.)"}]$lira$::jsonb, 516);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 14, 'Escena XII', $lira$[{"type": "h", "text": "Escena XII"}, {"type": "v", "text": "DON JUAN y CIUTTI."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Riéndose.)\nCon oro nada hay que falle;\nCiutti, ya sabes mi intento:\na las nueve, en el convento;\na las diez, en esta calle."}, {"type": "h", "text": "Acto III"}, {"type": "h", "text": "Profanación"}, {"type": "v", "text": "DON JUAN, DOÑA INÉS, DON GONZALO, BRÍGIDA, la ABADESA,\nla TORNERA.\nCelda de DOÑA INÉS. Puerta en el fondo y a la izquierda."}, {"type": "h", "text": "Escena I"}, {"type": "v", "text": "DOÑA INÉS y la ABADESA."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿Conque me habéis entendido?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Sí, señora."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Está muy bien;\nla voluntad decisiva\nde vuestro padre, tal es.\nSois joven, cándida y buena;\nvivido en el claustro habéis\ncasi desde que nacisteis;\ny para quedar en él\natada con santos votos\npara siempre, ni aún tenéis,\ncomo otras, pruebas difíciles\nni penitencias que hacer.\nDichosa mil veces vos;\ndichosa, sí, doña Inés,\nque no conociendo el mundo,\nno le debéis de temer.\nDichosa vos, que del claustro\nal pisar en el dintel,\nno os volveréis a mirar\nlo que tras vos dejaréis;\ny los mundanos recuerdos\ndel bullicio y del placer,\nno os turbarán, tentadores,\ndel ara santa a los pies;\npues ignorando lo que hay\ntras esa santa pared,\nlo que tras ella se queda,\njamás apeteceréis.\nMansa paloma, enseñada\nen las palmas a comer\ndel dueño que la ha criado\nen doméstico vergel,\nno habiendo salido nunca\nde la protectora red,\nno ansiaréis nunca las alas\npor el espacio tender.\nLirio gentil, cuyo tallo\nmecieron sólo tal vez\nlas embalsamadas brisas\ndel más florecido mes,\naquí a los besos del aura\nvuestro cáliz abriréis,\ny aquí vendrán vuestras hojas\ntranquilamente a caer.\nY en el pedazo de tierra\nque abarca nuestra estrechez\ny en el pedazo de cielo\nque por las rejas se ve,\nvos no veréis más que un lecho\ndo en dulce sueño yacer,\ny un velo azul suspendido\na las puertas del Edén...\n¡Ay! En verdad que os envidio,\nventurosa doña Inés,\ncon vuestra inocente vida,\nla virtud del no saber.\nMas, ¿por qué estáis cabizbaja?\n¿Por qué no me respondéis\ncomo otras veces, alegre,\ncuando en lo mismo os hablé?\n¿Suspiráis...? ¡Oh!, ya comprendo;\nde vuelta aquí hasta no ver\na vuestra aya, estáis inquieta,\npero nada receléis.\nA casa de vuestro padre\nfue casi al anochecer,\ny abajo en la portería\nestará; yo os la enviaré,\nque estoy de vela esta noche.\nConque, vamos, doña Inés,\nrecogeos, que ya es hora;\nMal ejemplo no me deis\na las novicias, que ha tiempo\nque duermen ya; hasta después."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Id con Dios, madre abadesa."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Adiós, hija."}]$lira$::jsonb, 422);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 15, 'Escena II', $lira$[{"type": "h", "text": "Escena II"}, {"type": "v", "text": "DOÑA INÉS, sola."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "[Ya se fue.]\nNo sé qué tengo, ¡ay de mí!,\nque en tumultuoso tropel\nmil encontradas ideas\nme combaten a la vez.\nOtras noches complacida\nsus palabras escuché,\ny de esos cuadros tranquilos\nque sabe pintar tan bien,\nde esos placeres domésticos\nla dichosa sencillez\ny la calma venturosa,\nme hicieron apetecer\nla soledad de los claustros\ny su santa rigidez.\nMas hoy la oí distraída,\ny en sus pláticas hallé,\nsi no enojosos discursos,\na lo menos aridez.\nY no sé por qué al decirme\nque podría acontecer\nque se acelerase el día\nde mi profesión, temblé,\ny sentí del corazón\nacelerarse el vaivén,\ny teñírseme el semblante\nde amarilla palidez.\n¡Ay de mí...! Pero mi dueña,\n¿dónde estará...? Esa mujer,\ncon sus pláticas, al cabo,\nme entretiene alguna vez.\nY hoy la echo menos... Acaso\nporque la voy a perder,\nque en profesando, es preciso\nrenunciar a cuanto amé.\nMas pasos siento en el claustro;\n¡oh! reconozco muy bien\nsus pisadas... Ya está aquí."}, {"type": "h", "text": "Escena III"}, {"type": "v", "text": "DOÑA INÉS y BRÍGIDA."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Buenas noches, doña Inés."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Cómo habéis tardado tanto?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Voy a cerrar esta puerta."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Hay orden de que esté abierta."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Eso es muy bueno y muy santo\npara las otras novicias\nque han de consagrarse a Dios:\nno, doña Inés, para vos."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Brígida, no ves que vicias\nlas reglas del monasterio,\nque no permiten..."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Bah! ¡bah!\nMás seguro así se está,\ny así se habla sin misterio\nni estorbos: ¿habéis mirado\nel libro que os he traído?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay!, se me había olvidado."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Pues me hace gracia el olvido!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Como la madre abadesa\nse entró aquí inmediatamente!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Vieja más impertinente!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Pues tanto el libro interesa?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Vaya si interesa, mucho.\n¡Pues quedó con poco afán\nel infeliz!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Quién?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Don Juan."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Válgame el cielo! ¡Qué escucho!\n¿Es don Juan quien me le envía?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Por supuesto."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Oh! Yo no debo\ntomarle."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Pobre mancebo!\nDesairarle así, sería\nmatarle."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Qué estás diciendo?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Si ese Horario no tomáis,\ntal pesadumbre le dais,\nque va a enfermar, lo estoy viendo."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ah! No, no; de esa manera\nle tomaré."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Bien haréis."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Y qué bonito es!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Ya veis:\nquien quiere agradar, se esmera."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Con sus manecillas de oro.\n¡Y cuidado, que está prieto!\nA ver, a ver si completo\ncontiene el rezo del coro.\n(Le abre y cae una carta de entre sus hojas.)\nMas ¿qué cayó?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Un papelito."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Una carta!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Claro está;\nen esa carta os vendrá\nofreciendo el regalito."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Qué! ¿Será suyo el papel?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Vaya, que sois inocente!\nPues que os feria, es consiguiente\nque la carta será de él."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay, Jesús!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Qué es lo que os da?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Nada, Brígida, no es nada."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "No, no; si estáis inmutada.\n(Aparte.)\nYa presa en la red está.\n¿Se os pasa?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Eso habrá sido\ncualquier mareíllo vano."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay! Se me abrasa la mano\ncon que el papel he cogido."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Doña Inés, válgame Dios,\njamás os he visto así;\nestáis trémula."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay de mí!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Qué es lo que pasa por vos?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "No sé... El campo de mi mente\nsiento que cruzan perdidas\nmil sombras desconocidas,\nque me inquietan vagamente;\ny ha tiempo al alma me dan\ncon su agitación tortura."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Tiene alguna, por ventura,\nel semblante de don Juan?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "No sé; desde que le vi,\nBrígida mía, y su nombre\nme dijiste, tengo a ese hombre\nsiempre delante de mí.\nPor doquiera me distraigo\ncon su agradable recuerdo,\ny si un instante le pierdo,\nen su recuerdo recaigo.\nNo sé qué fascinación\nen mis sentidos ejerce,\nque siempre hacia él se me tuerce\nla mente y el corazón;\ny aquí, y en el oratorio,\ny en todas partes advierto\nque el pensamiento divierto\ncon la imagen de Tenorio."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Válgame Dios! Doña Inés,\nsegún lo vais explicando,\ntentaciones me van dando\nde creer que eso amor es."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Amor has dicho?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Sí, amor."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "No, de ninguna manera."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Pues por amor lo entendiera\nel menos entendedor;\nmas vamos la carta a ver:\n¿En qué os paráis? ¿Un suspiro?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay! Que cuanto más la miro\nmenos me atrevo a leer.\n(Lee.)\n«Doña Inés del alma mía».\nVirgen santa, ¡qué principio!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Vendrá en verso, y será un ripio\nque traerá la poesía.\nVamos, seguid adelante."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "(Lee.)\n«Luz de donde el sol la toma,\nhermosísima paloma\nprivada de libertad,\nsi os dignáis por estas letras\npasar vuestros lindos ojos,\nno los tornéis con enojos\nsin concluir, acabad»."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Qué humildad y qué finura!\n¿Dónde hay mayor rendimiento?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Brígida, no sé qué siento."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Seguid, seguid la lectura."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "(Lee.)\n«Nuestros padres de consuno\nnuestras bodas acordaron,\nporque los cielos juntaron\nlos destinos de los dos.\nY halagado desde entonces\ncon tan risueña esperanza,\nmi alma, doña Inés, no alcanza\notro porvenir que vos.\nDe amor con ella en mi pecho\nbrotó una chispa ligera,\nque han convertido en hoguera\ntiempo y afición tenaz.\nY esta llama, que en mí mismo\nse alimenta, inextinguible,\ncada día más terrible\nva creciendo y más voraz»."}]$lira$::jsonb, 904);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 16, 'Parte 17', $lira$[{"type": "h", "text": "Brígida"}, {"type": "v", "text": "Es claro; esperar le hicieron\nen vuestro amor algún día,\ny hondas raíces tenía\ncuando a arrancársele fueron.\nSeguid."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "(Lee.)\n«En vano a apagarla\nconcurren tiempo y ausencia,\nque doblando su violencia,\nno hoguera ya, volcán es;\ny yo, que en medio del cráter\ndesamparado batallo,\nsuspendido en él me hallo\nentre mi tumba y mi Inés»."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Lo veis, Inés? Si ese Horario\nle despreciáis, al instante\nle preparan el sudario."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Yo desfallezco."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Adelante."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "(Lee.)\n«Inés, alma de mi alma,\nperpetuo imán de mi vida,\nperla sin concha escondida\nentre las algas del mar;\ngarza que nunca del nido\ntender osastes el vuelo\nal diáfano azul del cielo\npara aprender a cruzar,\nsi es que a través de esos muros\nel mundo apenada miras,\ny por el mundo suspiras,\nde libertad con afán,\nacuérdate que al pie mismo\nde esos muros que te guardan,\npara salvarte te aguardan\nlos brazos de tu don Juan».\n(Representa.)\n¿Qué es lo que me pasa, ¡cielo!,\nque me estoy viendo morir?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "(Aparte.)\nYa tragó todo el anzuelo.\nVamos, que está al concluir."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "(Lee.)\n«Acuérdate de quien llora\nal pie de tu celosía,\ny allí le sorprende el día\ny le halla la noche allí;\nacuérdate de quien vive\nsólo por ti, ¡vida mía!,\ny que a tus pies volaría\nsi le llamaras a ti»."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Lo veis? Vendría."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Vendría!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "A postrarse a vuestros pies."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Puede?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Oh, sí!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Virgen María!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Pero acabad, doña Inés."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "(Lee.)\n«Adiós, oh luz de mis ojos;\nadiós, Inés de mi alma;\nmedita, por Dios, en calma\nlas palabras que aquí van;\ny si odias esa clausura\nque ser tu sepulcro debe,\nmanda, que a todo se atreve\npor tu hermosura don Juan».\n(Representa DOÑA INÉS.)\n¡Ay! ¿Qué filtro envenenado\nme dan en este papel,\nque el corazón desgarrado\nme estoy sintiendo con él?\n¿Qué sentimientos dormidos\nson los que revela en mí;\nqué impulsos jamás sentidos,\nqué luz, que hasta hoy nunca vi?\n¿Qué es lo que engendra en mi alma\ntan nuevo y profundo afán?\n¿Quién roba la dulce calma\nde mi corazón?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Don Juan."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Don Juan dices...! ¿Conque ese hombre\nme ha de seguir por doquier?\n¿Sólo he de escuchar su nombre,\nsólo su sombra he de ver?\n¡Ah! Bien dice: juntó el cielo\nlos destinos de los dos,\ny en mi alma engendró este anhelo\nfatal."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Silencio, por Dios!\n(Se oyen dar las ánimas.)"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Silencio."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Me estremezco."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Oís, doña Inés, tocar?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Sí; lo mismo que otras veces,\nlas ánimas oigo dar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Pues no habléis de él."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Cielo santo!\n¿De quién?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿De quién ha de ser?\nDe ese don Juan que amáis tanto,\nporque puede aparecer."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Me amedrentas! ¿Puede ese hombre\nllegar hasta aquí?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Quizá,\nporque el eco de su nombre\ntal vez llega adonde está."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Cielos! ¿Y podrá...?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Quién sabe!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Es un espíritu, pues?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "No; mas si tiene una llave..."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Dios!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Silencio, doña Inés;\n¿no oís pasos?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay! Ahora\nnada oigo."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Las nueve dan,\nsuben... se acercan... señora...\nYa está aquí."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Quién?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Él."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Don Juan!"}]$lira$::jsonb, 558);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 17, 'Escena IV', $lira$[{"type": "h", "text": "Escena IV"}, {"type": "v", "text": "DOÑA INÉS, DON JUAN y BRÍGIDA."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Qué es esto? ¿Sueño... deliro?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Inés de mi corazón!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Es realidad lo que miro,\no es una fascinación...?\nTenedme, apenas respiro...\nSombra... ¡huye por compasión!\n¡Ay de mí...!\n(Desmáyase DOÑA INÉS, y DON JUAN la sostiene. La carta de DON\nJUAN queda en el suelo abandonada por DOÑA INÉS al desmayarse.)"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "La ha fascinado\nvuestra repentina entrada,\ny el pavor la ha trastornado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mejor, así nos ha ahorrado\nla mitad de la jornada.\n¡Ea! No desperdiciemos\nel tiempo aquí en contemplarla,\nsi perdernos no queremos.\nEn los brazos a tomarla\nvoy, y cuanto antes, ganemos\nese claustro solitario."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Oh! ¿Vais a sacarla así?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Necia, piensas que rompí\nla clausura temerario,\npara dejármela aquí?\nMi gente abajo me espera;\nsígueme."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Sin alma estoy!\n¡Ay! Este hombre es una fiera;\nnada le ataja ni altera...\nSí, sí; a su sombra me voy."}, {"type": "h", "text": "Escena V"}, {"type": "v", "text": "La ABADESA, sola."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Jurara que había oído\npor estos claustros andar;\nhoy a doña Inés velar\nalgo más la he permitido,\ny me temo... mas no están\naquí. ¿Qué pudo ocurrir\na las dos para salir\nde la celda? ¿Dónde irán?\n¡Hola! Yo las ataré\ncorto para que no vuelvan\na enredar y me revuelvan\na las novicias... sí a fe.\nMas siento por allá fuera\npasos. ¿Quién es?"}, {"type": "h", "text": "Escena VI"}, {"type": "v", "text": "La ABADESA y la TORNERA."}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "Yo, señora."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¡Vos en el claustro a esta hora!\n¿Qué es esto, hermana Tornera?"}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "Madre Abadesa, os buscaba."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿Qué hay? Decid."}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "Un noble anciano\nquiere hablaros."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Es en vano."}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "Dice que es de Calatrava\ncaballero; que sus fueros\nle autorizan a este paso,\ny que la urgencia del caso\nle obliga al instante a veros."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿Dijo su nombre?"}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "El señor\ndon Gonzalo Ulloa."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿Qué\npuede querer...? Ábrale,\nhermana, es Comendador\nde la Orden, y derecho\ntiene en el claustro de entrada."}]$lira$::jsonb, 331);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 18, 'Escena VII', $lira$[{"type": "h", "text": "Escena VII"}, {"type": "v", "text": "La ABADESA y DON GONZALO, después."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿A una hora tan avanzada\nvenir así...? No sospecho\nqué pueda ser... mas me place,\npues no hallando a su hija aquí,\nla reprenderá, y así\nmirará otra vez lo que hace."}, {"type": "h", "text": "Escena VIII"}, {"type": "v", "text": "La ABADESA, DON GONZALO y la TORNERA, a la puerta."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Perdonad, madre Abadesa,\nque en hora tal os moleste;\nmas para mí, asunto es éste\nque honra y vida me interesa."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¡Jesús!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Oíd."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Hablad, pues."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Yo guardé hasta hoy un tesoro\nde más quilates que el oro,\ny ese tesoro es mi Inés."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "A propósito..."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Escuchad.\nSe me acaba de decir\nque han visto a su dueña ir\nha poco por la ciudad\nhablando con el criado\nde un don Juan, de tal renombre,\nque no hay en la tierra otro hombre\ntan audaz y tan malvado.\nEn tiempo atrás se pensó\ncon él a mi hija casar,\ny hoy, que se la fui a negar,\nrobármela me juró.\nQue por el torpe doncel\nganada la dueña está,\nno puedo dudarlo ya;\ndebo, pues, guardarme de él;\ny un día, una hora quizás\nde imprevisión le bastara\npara que mi honor manchara\nese hijo de Satanás.\nHe aquí mi inquietud cuál es;\npor la dueña, en conclusión,\nvengo; vos la profesión\nabreviad de doña Inés."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Sois padre, y es vuestro afán\nmuy justo, Comendador;\nmas ved que ofende a mi honor."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "No sabéis quién es don Juan."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Aunque le pintáis tan malo,\nyo os puedo decir de mí,\nque mientra Inés esté aquí,\nsegura está, don Gonzalo."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Lo creo; mas las razones\nabreviemos: entregadme\nesa dueña, y perdonadme\nmis mundanas opiniones.\nSi vos de vuestra virtud\nme respondéis, yo me fundo\nen que conozco del mundo\nla insensata juventud."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Se hará como lo exigís.\nHermana Tornera, id pues\na buscar a doña Inés\ny a su dueña.\n(Vase la TORNERA.)"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Qué decís,\nseñora? O traición me ha hecho\nmi memoria, o yo sé bien\nque esta es hora de que estén\nambas a dos en su lecho."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "Ha un punto sentí a las dos\nsalir de aquí, no sé a qué."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Ay! Por qué tiemblo no sé.\nMas, ¡qué veo, Santo Dios!\nUn papel... me lo decía\na voces mi mismo afán.\n(Leyendo.)\n«Doña Inés del alma mía...»\nY la firma de don Juan.\nVed... ved... esa prueba escrita.\nLeed ahí... ¡Oh! Mientras que vos\npor ella rogáis a Dios,\nviene el diablo y os la quita."}]$lira$::jsonb, 433);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 19, 'Escena IX', $lira$[{"type": "h", "text": "Escena IX"}, {"type": "v", "text": "La ABADESA, DON GONZALO y la TORNERA."}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "Señora..."}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "Vengo muerta."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Concluid."}, {"type": "h", "text": "Tornera"}, {"type": "v", "text": "No acierto a hablar...\nHe visto a un hombre saltar\npor las tapias de la huerta."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Veis? Corramos; ¡ay de mí!"}, {"type": "h", "text": "Abadesa"}, {"type": "v", "text": "¿Dónde vais, Comendador?"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Imbécil! Tras de mi honor,\nque os roban a vos de aquí."}, {"type": "h", "text": "Acto IV"}, {"type": "h", "text": "El diablo a las puertas del cielo"}, {"type": "h", "text": "Don juan, doña inés, don gonzalo, don luis, ciutti,"}, {"type": "v", "text": "BRÍGIDA, ALGUACIL 1.º y ALGUACIL 1.º\nQuinta de DON JUAN Tenorio, cerca de Sevilla y sobre el Guadalquivir.\nBalcón en el fondo. Dos puertas a cada lado."}, {"type": "h", "text": "Escena I"}, {"type": "v", "text": "BRÍGIDA y CIUTTI."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Qué noche, válgame Dios!\nA poderlo calcular,\nno me meto yo a servir\na tan fogoso galán.\n¡Ay, Ciutti! Molida estoy;\nno me puedo menear."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Pues, ¿qué os duele?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Todo el cuerpo,\ny toda el alma además."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "¡Ya! No estáis acostumbrada\nal caballo, es natural."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Mil veces pensé caer;\n¡Uf! ¡Qué mareo! ¡Qué afán!\nVeía yo unos tras otros\nante mis ojos pasar\nlos árboles como en alas\nllevados de un huracán,\ntan apriesa y produciéndome\nilusión tan infernal,\nque perdiera los sentidos\nsi tardamos en parar."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Pues de estas cosas veréis,\nsi en esta casa os quedáis,\nlo menos seis por semana."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Jesús!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Y esa niña, ¿está\nreposando todavía?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Y a qué se ha de despertar?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Sí; es mejor que abra los ojos\nen los brazos de don Juan."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Preciso es que tu amo tenga\nalgún diablo familiar."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Yo creo que sea él mismo\nun diablo en carne mortal,\nporque a lo que él, solamente\nse arrojara Satanás."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Oh! ¡El lance ha sido extremado!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Pero al fin logrado está."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Salir así de un convento\nen medio de una ciudad\ncomo Sevilla!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Es empresa\ntan sólo para hombre tal;\nmas, ¡qué diablos!, si a su lado\nla fortuna siempre va,\ny encadenado a sus pies\nduerme sumiso el azar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Sí; decís bien."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "No he visto hombre\nde corazón más audaz;\nno halla riesgo que le espante,\nni encuentra dificultad\nque al empeñarse en vencer,\nle haga un punto vacilar.\nA todo osado se arroja,\nde todo se ve capaz;\nni mira dónde se mete,\nni lo pregunta jamás.\n«Allí hay un lance», le dicen;\ny él dice: «Allá va don Juan».\nMas ya tarda, ¡vive Dios!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Las doce en la catedral\nhan dado ha tiempo."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Y de vuelta\ndebía a las doce estar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Pero, ¿por qué no se vino\ncon nosotros?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Tiene allá\nen la ciudad todavía\ncuatro cosas que arreglar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Para el viaje?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Por supuesto;\naunque muy fácil será\nque esta noche a los infiernos\nle hagan a él mismo viajar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Jesús, qué ideas!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "¡Pues digo!\n¿Son obras de caridad\nen las que nos empleamos,\npara mejor esperar?\nAunque seguros estamos\ncomo vuelva por acá."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿De veras, Ciutti?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Venid\na este balcón, y mirad.\n¿Qué veis?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Veo un bergantín\nque anclado en el río está."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Pues su patrón sólo aguarda\nlas órdenes de don Juan,\ny salvos en todo caso\na Italia nos llevará."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Cierto?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Y nada receléis\npor nuestra seguridad,\nque es el barco más velero\nque boga sobre la mar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Chist! Ya siento a doña Inés."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Pues yo me voy, que don Juan\nencargó que sola vos\ndebíais con ella hablar."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Y encargó bien, que yo entiendo\nde esto."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Adiós, pues."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Vete en paz."}]$lira$::jsonb, 595);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 20, 'Escena II', $lira$[{"type": "h", "text": "Escena II"}, {"type": "v", "text": "DOÑA INÉS y BRÍGIDA."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Dios mío, cuánto he soñado!\n¡Loca estoy! ¿Qué hora será?\nPero ¿qué es esto? ¡Ay de mí!\nNo recuerdo que jamás\nhaya visto este aposento.\n¿Quién me trajo aquí?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Don Juan."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Siempre don Juan...\n¿Aquí tú también estás,\nBrígida?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Sí, doña Inés."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Pero dime en caridad,\n¿dónde estamos? Este cuarto\n¿es del convento?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "No tal;\naquello era un cuchitril\nen donde no había más\nque miseria."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Pero, en fin,\n¿en dónde estamos?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Mirad,\nmirad por este balcón,\ny alcanzaréis lo que va\ndesde un convento de monjas\na una quinta de don Juan."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Es de don Juan esta quinta?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Y creo que vuestra ya."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Pero no comprendo, Brígida,\nlo que dices."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Escuchad.\nEstabais en el convento\nleyendo con mucho afán\nuna carta de don Juan,\ncuando estalló en un momento\nun incendio formidable."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Jesús!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Espantoso, inmenso;\nel humo era ya tan denso,\nque el aire se hizo palpable."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Pues no recuerdo..."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Las dos,\ncon la carta entretenidas,\nolvidamos nuestras vidas,\nyo oyendo, y leyendo vos.\nY estaba en verdad tan tierna,\nque entrambas a su lectura,\nachacamos la tortura\nque sentíamos interna.\nApenas ya respirar\npodíamos, y las llamas\nprendían en nuestras camas;\nnos íbamos a asfixiar,\ncuando don Juan, que os adora,\ny que rondaba el convento,\nal ver crecer con el viento\nla llama devastadora,\ncon inaudito valor,\nviendo que ibais a abrasaros,\nse metió para salvaros\npor donde pudo mejor.\nVos, al verle así asaltar\nla celda tan de improviso,\nos desmayasteis... preciso;\nla cosa era de esperar.\nY él, cuando os vio caer así,\nen sus brazos os tomó\ny echó a huir, yo le seguí,\ny del fuego nos sacó.\n¿Dónde íbamos a esta hora?\nVos seguíais desmayada;\nyo estaba ya casi ahogada.\nDijo, pues: «Hasta la aurora\nen mi casa las tendré».\nY henos, doña Inés, aquí."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Conque ésta es su casa?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Pues nada recuerdo a fe.\nPero... ¡en su casa...! ¡Oh! Al punto\nsalgamos de ella... yo tengo\nla de mi padre."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Convengo\ncon vos; pero es el asunto..."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Que no podemos ir."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Oír tal me maravilla."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Nos aparta de Sevilla..."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Quién?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Vedlo, el Guadalquivir."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿No estamos en la ciudad?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "A una legua nos hallamos\nde sus murallas."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Oh! ¡Estamos\nperdidas!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡No sé en verdad\npor qué!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Me estás confundiendo,\nBrígida... y no sé qué redes\nson las que entre estas paredes\ntemo que me estás tendiendo.\nNunca el claustro abandoné,\nni sé del mundo exterior\nlos usos, mas tengo honor;\nnoble soy, Brígida, y sé\nque la casa de don Juan\nno es buen sitio para mí;\nme lo está diciendo aquí\nno sé qué escondido afán.\nVen, huyamos."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Doña Inés,\nla existencia os ha salvado."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Sí, pero me ha envenenado\nel corazón."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¿Le amáis, pues?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "No sé... mas, por compasión,\nhuyamos pronto de ese hombre,\ntras de cuyo solo nombre\nse me escapa el corazón.\n¡Ah! Tú me diste un papel\nde manos de ese hombre escrito,\ny algún encanto maldito\nme diste encerrado en él.\nUna sola vez le vi\npor entre unas celosías,\ny que estaba, me decías,\nen aquel sitio por mí.\nTú, Brígida, a todas horas\nme venías de él a hablar,\nhaciéndome recordar\nsus gracias fascinadoras.\nTú me dijiste que estaba\npara mío destinado\npor mi padre, y me has jurado\nen su nombre que me amaba.\n¿Que le amo dices...? Pues bien;\nsi esto es amar, sí, le amo;\npero yo sé que me infamo\ncon esa pasión también.\nY si el débil corazón\nse me va tras de don Juan,\ntirándome de él están\nmi honor y mi obligación.\nVamos, pues, vamos de aquí\nprimero que ese hombre venga;\npues fuerza acaso no tenga\nsi le veo junto a mí.\nVamos, Brígida."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Esperad.\n¿No oís?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Ruido de remos."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Sí, dices bien; volveremos\nen un bote a la ciudad."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Mirad, mirad, doña Inés."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Acaba... por Dios, partamos."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Ya, imposible que salgamos."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Por qué razón?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Porque él es\nquien en ese barquichuelo\nse adelanta por el río."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ay! ¡Dadme fuerzas, Dios mío!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Ya llegó; ya está en el suelo.\nSus gentes nos volverán\na casa; mas antes de irnos,\nes preciso despedirnos\na lo menos de don Juan."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Sea, y vamos al instante.\nNo quiero volverle a ver."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "(Aparte.)\nLos ojos te hará volver\nal encontrarle delante.\nVamos."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Vamos."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "(Dentro.)\nAquí están."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Dentro.)\nAlumbra."}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "¡Nos busca!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Él es."}]$lira$::jsonb, 811);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 21, 'Escena III', $lira$[{"type": "h", "text": "Escena III"}, {"type": "v", "text": "Dichas y DON JUAN."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Adónde vais, doña Inés?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Dejadme salir, don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Que os deje salir?"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Señor,\nsabiendo ya el accidente\ndel fuego, estará impaciente\npor su hija el Comendador."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡El fuego! ¡Ah! No os dé cuidado\npor don Gonzalo, que ya\ndormir tranquilo le hará\nel mensaje que le he enviado."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Le habéis dicho...?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Que os hallabais\nbajo mi amparo segura,\ny el aura del campo pura\nlibre por fin respirabais.\n(Vase BRÍGIDA.)\nCálmate, pues, vida mía;\nreposa aquí, y un momento\nolvida de tu convento\nla triste cárcel sombría.\n¡Ah! ¿No es cierto, ángel de amor,\nque en esta apartada orilla\nmás pura la luna brilla\ny se respira mejor?\nEsta aura que vaga llena\nde los sencillos olores\nde las campesinas flores\nque brota esa orilla amena;\nesa agua limpia y serena\nque atraviesa sin temor\nla barca del pescador\nque espera cantando el día,\n¿no es cierto, paloma mía,\nque están respirando amor?\nEsa armonía que el viento\nrecoge entre esos millares\nde floridos olivares,\nque agita con manso aliento,\nese dulcísimo acento\ncon que trina el ruiseñor\nde sus copas morador\nllamando al cercano día,\n¿no es verdad, gacela mía,\nque están respirando amor?\nY estas palabras que están\nfiltrando insensiblemente\ntu corazón, ya pendiente\nde los labios de don Juan,\ny cuyas ideas van\ninflamando en su interior\nun fuego germinador\nno encendido todavía,\n¿no es verdad, estrella mía,\nque están respirando amor?\nY esas dos líquidas perlas\nque se desprenden tranquilas\nde tus radiantes pupilas\nconvidándome a beberlas,\nevaporarse a no verlas\nde sí mismas al calor,\ny ese encendido color\nque en tu semblante no había,\n¿no es verdad, hermosa mía,\nque están respirando amor?\n¡Oh! sí, bellísima Inés,\nespejo y luz de mis ojos;\nescucharme sin enojos\ncomo lo haces, amor es;\nmira aquí a tus plantas, pues,\ntodo el altivo rigor\nde este corazón traidor\nque rendirse no creía,\nadorando, vida mía,\nla esclavitud de tu amor."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Callad, por Dios, ¡oh don Juan!,\nque no podré resistir\nmucho tiempo sin morir\ntan nunca sentido afán.\n¡Ah! Callad, por compasión,\nque oyéndoos me parece\nque mi cerebro enloquece\ny se arde mi corazón.\n¡Ah! Me habéis dado a beber\nun filtro infernal sin duda,\nque a rendiros os ayuda\nla virtud de la mujer.\nTal vez poseéis, don Juan,\nun misterioso amuleto,\nque a vos me atrae en secreto\ncomo irresistible imán.\nTal vez Satán puso en vos\nsu vista fascinadora,\nsu palabra seductora\ny el amor que negó a Dios.\n¿Y qué he de hacer, ¡ay de mí!,\nsino caer en vuestros brazos,\nsi el corazón en pedazos\nme vais robando de aquí?\nNo, don Juan; en poder mío\nresistirte no está ya;\nyo voy a ti, como va\nsorbido al mar ese río.\nTu presencia me enajena,\ntus palabras me alucinan,\ny tus ojos me fascinan,\ny tu aliento me envenena.\n¡Don Juan! ¡Don Juan! Yo lo imploro\nde tu hidalga compasión:\no arráncame el corazón,\no ámame, porque te adoro."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Alma mía! Esa palabra\ncambia de modo mi ser,\nque alcanzo que puede hacer\nhasta que el Edén se me abra.\nNo es, doña Inés, Satanás\nquien pone este amor en mí;\nes Dios, que quiere por ti\nganarme para Él quizás.\nNo; el amor que hoy se atesora\nen mi corazón mortal,\nno es un amor terrenal\ncomo el que sentí hasta ahora;\nno es esa chispa fugaz\nque cualquier ráfaga apaga;\nes incendio que se traga\ncuanto ve, inmenso, voraz.\nDesecha, pues, tu inquietud,\nbellísima doña Inés,\nporque me siento a tus pies\ncapaz aún de la virtud.\nSí; iré mi orgullo a postrar\nante el buen Comendador,\ny, o habrá de darme tu amor,\no me tendrá que matar."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Don Juan de mi corazón!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Silencio! ¿Habéis escuchado?"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí; una barca ha atracado\ndebajo de ese balcón.\nUn hombre embozado de ella\nsalta... Brígida, al momento\n(Entra BRÍGIDA.)\npasad a esotro aposento;\ny perdonad, Inés bella,\nsi solo me importa estar."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¿Tardarás?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Poco ha de ser."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "A mi padre hemos de ver."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí; en cuanto empiece a clarear.\nAdiós."}]$lira$::jsonb, 719);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 22, 'Escena IV', $lira$[{"type": "h", "text": "Escena IV"}, {"type": "v", "text": "DON JUAN y CIUTTI."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Señor."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué sucede,\nCiutti?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Ahí está un embozado\nen veros muy empeñado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Quién es?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Dice que no puede\ndescubrirse más que a vos,\ny que es cosa de tal priesa,\nque en ella se os interesa\nla vida a entrambos a dos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y en él no has reconocido\nmarca ni señal alguna\nque nos oriente?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Ninguna;\nmas a veros decidido\nviene."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Trae gente?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "No más\nque los remeros del bote."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Que entre."}, {"type": "h", "text": "Escena V"}, {"type": "v", "text": "DON JUAN. Luego CIUTTI y DON LUIS, embozado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Jugamos a escote\nla vida...! Mas, si es quizás\nun traidor que hasta mi quinta\nme viene siguiendo el paso...\nhálleme, pues, por si acaso,\ncon las armas en la cinta.\n(Se ciñe la espada y suspende al cinto un par de pistolas, que habrá\ncolocado sobre la mesa a su salida en la escena tercera. Al momento sale\nCIUTTI conduciendo a DON LUIS, que, embozado hasta los ojos, espera a\nque se queden solos. DON JUAN hace a CIUTTI una seña para que se retire.\nLo hace.)"}, {"type": "h", "text": "Escena VI"}, {"type": "v", "text": "DON JUAN y DON LUIS."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Aparte.)\nBuen talante. Bien venido,\ncaballero."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Bien hallado,\nseñor mío."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sin cuidado\nhablad."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Jamás lo he tenido."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Decid, pues: ¿a qué venís\na esta hora y con tal afán?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Vengo a mataros, don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Según eso, sois don Luis?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No os engañó el corazón,\ny el tiempo no malgastemos,\ndon Juan; los dos no cabemos\nya en la tierra."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "En conclusión,\nseñor Mejía, es decir\nque, porque os gané la apuesta,\n¿queréis que acabe la fiesta\ncon salirnos a batir?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Estáis puesto en la razón;\nla vida apostado habemos,\ny es fuerza que nos paguemos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Soy de la misma opinión.\nMas ved que os debo advertir\nque sois vos quien la ha perdido."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues por eso os la he traído;\nmas no creo que morir\ndeba nunca un caballero\nque lleva en el cinto espada,\ncomo una res destinada\npor su dueño al matadero."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ni yo creo que resquicio\nhabréis jamás encontrado\npor donde me hayáis tomado\npor un cortador de oficio."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "De ningún modo, y ya veis\nque, pues os vengo a buscar,\nmucho en vos debo fiar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No más de lo que podéis.\nY por mostraros mejor\nmi generosa hidalguía,\ndecid si aún puedo, Mejía,\nsatisfacer vuestro honor.\nLeal la apuesta os gané\nmas si tanto os ha escocido,\nmirad si halláis conocido\nremedio, y le aplicaré."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "No hay más que el que os he propuesto,\ndon Juan. Me habéis maniatado,\ny habéis la casa asaltado\nusurpándome mi puesto;\ny pues el mío tomasteis\npara triunfar de doña Ana,\nno sois vos, don Juan, quien gana,\nporque por otro jugasteis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ardides del juego son."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues no os los quiero pasar,\ny por ellos a jugar\nvamos ahora el corazón."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Le arriesgáis, pues, en revancha\nde doña Ana de Pantoja?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sí; y lo que tardo me enoja\nen lavar tan fea mancha.\nDon Juan, yo la amaba, sí;\nmas con lo que habéis osado,\nimposible la hais dejado\npara vos y para mí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Por qué la apostasteis, pues?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Porque no pude pensar\nque la pudierais lograr.\nY... vamos, por San Andrés,\na reñir, que me impaciento."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Bajemos a la ribera."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Aquí mismo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Necio fuera;\n¿no veis que en este aposento\nprendieran al vencedor?\nVos traéis una barquilla."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues que lleve a Sevilla\nal que quede."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Eso es mejor;\nSalgamos, pues."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Esperad."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¿Qué sucede?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ruido siento."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pues no perdamos momento."}]$lira$::jsonb, 655);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 23, 'Escena VII', $lira$[{"type": "h", "text": "Escena VII"}, {"type": "v", "text": "DON JUAN, DON LUIS y CIUTTI."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Señor, la vida salvad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué hay, pues?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "El Comendador,\nque llega con gente armada."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Déjale franca la entrada,\npero a él solo."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Mas, señor..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Obedéceme.\n(Vase CIUTTI.)"}, {"type": "h", "text": "Escena VIII"}, {"type": "v", "text": "DON JUAN y DON LUIS."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Don Luis,\npues de mí os habéis fiado\ncuanto dejáis demostrado\ncuando, a mi casa venís,\nno dudaré en suplicaros,\npues mi valor conocéis,\nque un instante me aguardéis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Yo nunca puse reparos\nen valor que es tan notorio;\nmas no me fío de vos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ved que las partes son dos\nde la apuesta con Tenorio,\ny que ganadas están."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "¡Lograsteis a un tiempo...!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí;\nla del convento está aquí;\ny pues viene de don Juan\na reclamarla quien puede,\ncuando me podéis matar,\nno debo asunto dejar\ntras mí que pendiente quede."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pero mirad que meter\nquien puede el lance impedir\nentre los dos, puede ser..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Excusaros de reñir."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Miserable...! De don Juan\npodéis dudar sólo vos;\nmas aquí entrad, vive Dios,\ny no tengáis tanto afán\npor vengaros, que este asunto\narreglado con ese hombre,\ndon Luis, yo os juro a mi nombre\nque nos batimos al punto."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Pero..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Con una legión\nde diablos! Entrad aquí,\nque harta nobleza es en mí\naún daros satisfacción.\nDesde ahí ved y escuchad;\nfranca tenéis esa puerta;\nsi veis mi conducta incierta,\ncomo os acomode obrad."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Me avengo, si muy reacio\nno andáis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Calculadlo vos\na placer; mas, ¡vive Dios!,\n¡que para todo hay espacio!\n(Entra DON LUIS en el cuarto que DON JUAN le señala.)\nYa suben.\n(DON JUAN escucha.)"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "(Dentro.)\n¿Dónde está?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Él es."}, {"type": "h", "text": "Escena IX"}, {"type": "v", "text": "DON JUAN y DON GONZALO."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Adónde está ese traidor?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Aquí está, Comendador."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿De rodillas?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y a tus pies."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Vil eres hasta en tus crímenes."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Anciano, la lengua ten,\ny escúchame un solo instante."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Qué puede en tu lengua haber\nque borre lo que tu mano\nescribió en este papel?\n¡Ir a sorprender, infame,\nla cándida sencillez\nde quien no pudo el veneno\nde esas letras precaver!\n¡Derramar en su alma virgen\ntraidoramente la hiel\nen que rebosa la tuya\nseca de virtud y fe!\n¡Proponerse así enlodar\nde mis timbres la alta prez,\ncomo si fuera un harapo\nque desecha un mercader!\n¿Ese es el valor, Tenorio,\nde que blasonas? ¿Esa es\nla proverbial osadía\nque te da a el vulgo a temer?\n¿Con viejos y con doncellas\nlas muestras...? ¿Y para qué?\n¡Vive Dios! Para venir\nsus plantas así a lamer,\nmostrándote a un tiempo ajeno\nde valor y de honradez."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Comendador!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Miserable!\nTú has robado a mi hija Inés\nde su convento, y yo vengo\npor tu vida o por mi bien."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Jamás delante de un hombre\nmi alta cerviz incliné,\nni he suplicado jamás,\nni a mi padre, ni a mi rey.\nY pues conservo a tus plantas\nla postura en que me ves,\nconsidera, don Gonzalo,\nque razón debo tener."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Lo que tienes es pavor\nde mi justicia."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Pardiez!\nÓyeme, Comendador,\no tenerme no sabré,\ny seré quien siempre he sido\nno queriéndolo ahora ser."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Vive Dios!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Comendador,\nyo idolatro a doña Inés,\npersuadido de que el cielo\nme la quiso conceder\npara enderezar mis pasos\npor el sendero del bien.\nNo amé la hermosura en ella\nni sus gracias adoré;\nlo que adoro es la virtud,\ndon Gonzalo, en doña Inés.\nLo que justicias ni obispos\nno pudieron de mí hacer\ncon cárceles y sermones,\nlo pudo su candidez.\nSu amor me torna en otro hombre\nregenerando mi ser,\ny ella puede hacer un ángel\nde quien un demonio fue.\nEscucha, pues, don Gonzalo,\nlo que te puede ofrecer\nel audaz don Juan Tenorio\nde rodillas a tus pies.\nYo seré esclavo de tu hija,\nen tu casa viviré,\ntú gobernarás mi hacienda\ndiciéndome esto ha de ser.\nEl tiempo que señalares,\nen reclusión estaré;\ncuantas pruebas exigieres\nde mi audacia o mi altivez,\ndel modo que me ordenares\ncon sumisión te daré.\nY cuando estime tu juicio\nque la pueda merecer,\nyo la daré un buen esposo\ny ella me dará el Edén."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Basta, don Juan; no sé cómo\nme he podido contener\noyendo tan torpes pruebas\nde tu infame avilantez.\nDon Juan, tú eres un cobarde\ncuando en la ocasión te ves,\ny no hay bajeza a que no oses\ncomo te saque con bien."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Don Gonzalo!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "Y me avergüenzo\nde mirarte así a mis pies,\nlo que apostabas por fuerza\nsuplicando por merced."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Todo así se satisface,\ndon Gonzalo, de una vez."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Nunca! ¡Nunca! ¿Tú su esposo?\nPrimero la mataré.\nEa, entregádmela al punto,\no, sin poderme valer,\nen esa postura vil\nel pecho te cruzaré."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Míralo bien, don Gonzalo,\nque vas a hacerme perder\ncon ella hasta la esperanza\nde mi salvación tal vez."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Y qué tengo yo, don Juan,\ncon tu salvación que ver?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Comendador, que me pierdes!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Mi hija!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Considera bien\nque por cuantos medios pude\nte quise satisfacer;\ny que con armas al cinto\ntus denuestos toleré,\nproponiéndote la paz\nde rodillas a tus pies."}]$lira$::jsonb, 924);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 24, 'Escena X', $lira$[{"type": "h", "text": "Escena X"}, {"type": "v", "text": "Dichos y DON LUIS, soltando una carcajada de burla."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Muy bien, don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Vive Dios!"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¿Quién es ese hombre?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Un testigo\nde su miedo, y un amigo,\nComendador, para vos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Don Luis!"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Ya he visto bastante,\ndon Juan, para conocer\ncuál uso puedes hacer\nde tu valor arrogante;\ny quien hiere por detrás\ny se humilla en la ocasión,\nes tan vil como el ladrón\nque roba y huye."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Esto más?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Y pues la ira soberana\nde Dios junta, como ves,\nal padre de doña Inés\ny al vengador de doña Ana,\nmira el fin que aquí te espera\ncuando a igual tiempo te alcanza\naquí dentro su venganza\ny la justicia allá fuera."}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "¡Oh! Ahora comprendo... ¿Sois vos\nel que...?"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Soy don Luis Mejía,\na quien a tiempo os envía\npor vuestra venganza Dios."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Basta, pues, de tal suplicio!\nSi con hacienda y honor\nni os muestro ni doy valor\na mi franco sacrificio,\ny la leal solicitud\ncon que ofrezco cuanto puedo\ntomáis, vive Dios, por miedo\ny os mofáis de mi virtud,\nos acepto el que me dais\nplazo breve y perentorio\npara mostrarme el Tenorio\nde cuyo valor dudáis."}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "Sea, y cae a nuestros pies\ndigno al menos de esa fama\nque por tan bravo te aclama."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y venza el infierno, pues.\n¡Ulloa, pues mi alma así\nvuelves a hundir en el vicio,\ncuando Dios me llame a juicio\ntú responderás por mí!\n(Le da un pistoletazo.)"}, {"type": "h", "text": "Don Gonzalo"}, {"type": "v", "text": "(Cayendo.)\n¡Asesino!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Y tú, insensato,\nque me llamas vil ladrón,\ndi en prueba de tu razón\nque cara a cara te mato!\n(Riñen, y le da una estocada.)"}, {"type": "h", "text": "Don Luis"}, {"type": "v", "text": "(Cayendo.)\n¡Jesús!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tarde tu fe ciega\nacude al cielo, Mejía,\ny no fue por culpa mía.\nPero la justicia llega,\ny a fe que ha de ver quién soy."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "(Dentro.)\n¡Don Juan!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Asomándose al balcón.)\n¿Quién es?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "(Dentro.)\nPor aquí;\nSalvaos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Hay paso?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Sí:\narrojaos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Allá voy.\nLlamé al cielo, y no me oyó,\ny pues sus puertas me cierra,\nde mis pasos en la tierra\nresponda el cielo, y no yo.\n(Se arroja por el balcón, y se le oye caer en el agua del río; al mismo\ntiempo que el ruido de los remos muestra la rapidez del barco en que parte, se\noyen golpes en las puertas de la habitación; poco después entra la justicia,\nsoldados, etc.)"}]$lira$::jsonb, 434);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 25, 'Escena XI', $lira$[{"type": "h", "text": "Escena XI"}, {"type": "v", "text": "Alguaciles, soldados. Luego DOÑA INÉS y BRÍGIDA.\nALGUACIL 1.º\nEl tiro ha sonado aquí.\nALGUACIL 2.º\nAún hay humo.\nALGUACIL 1.º\n¡Santo Dios!\nAquí hay un cadáver.\nALGUACIL 2º\nDos.\nALGUACIL 1.º\n¿Y el matador?\nALGUACIL 2.º\nPor allí.\n(Abren el cuarto en que están DOÑA INÉS y BRÍGIDA, y las sacan a la\nescena; DOÑA INÉS reconoce el cadáver de su padre).\nALGUACIL 1.º\n¡Dos mujeres!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ah! ¡Qué horror!\n¡Padre mío!\nALGUACIL 1.º\n¡Es su hija!"}, {"type": "h", "text": "Brígida"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Ah! ¿Dó estás, don Juan, que aquí\nme olvidas en tal dolor?\nALGUACIL 1.º\nÉl le asesinó."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "¡Dios mío!\n¿Me guardabas esto más?\nALGUACIL 2.º\nPor aquí ese Satanás\nse arrojó sin duda al río.\nALGUACIL 1.º\nMiradlos... a bordo están\ndel bergantín calabrés."}, {"type": "h", "text": "Todos"}, {"type": "v", "text": "Justicia por doña Inés."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Pero no contra don Juan.\n(Esta escena puede suprimirse en la representación, terminando el acto con\nel último verso de la anterior.)\n****"}, {"type": "h", "text": "Parte II"}, {"type": "h", "text": "Acto I"}, {"type": "h", "text": "La sombra de doña inés"}, {"type": "v", "text": "DON JUAN, el Capitán CENTELLAS, don Rafael de AVELLANEDA, un\nESCULTOR, la SOMBRA de doña Inés.\nPanteón de la familia Tenorio. El teatro representa un magnífico\ncementerio, hermoseado a manera de jardín. En primer término, aislados y de\nbulto, los sepulcros de DON GONZALO de Ulloa, de DOÑA INÉS y de DON\nLUIS Mejía, sobre los cuales se ven sus estatuas de piedra. El sepulcro de\nDON GONZALO a la derecha, y su estatua de rodillas; el de DON LUIS a la\nizquierda, y su estatua también de rodillas; el de DOÑA INÉS en el centro, y\nsu estatua al pie. En segundo término otros dos sepulcros en la forma que\nconvenga; y en tercer término y en puesto elevado el sepulcro y la estatua del\nfundador, DON DIEGO Tenorio, en cuya figura remata la perspectiva de los\nsepulcros. Una pared llena de nichos y lápidas circuye el cuadro hasta el\nhorizonte. Dos llorones a cada lado de la tumba de doña Inés, dispuestos a\nservir de la manera que a su tiempo exige el juego escénico. Cipreses y flores\nde todas clases embellecen la decoración, que no debe tener nada horrible. La\nacción se supone en una tranquila noche de verano, y alumbrada por una\nclarísima luna."}]$lira$::jsonb, 378);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 26, 'Escena I', $lira$[{"type": "h", "text": "Escena I"}, {"type": "v", "text": "El ESCULTOR, disponiéndose a marchar."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Pues señor, es cosa hecha;\nel alma del buen don Diego\npuede, a mi ver, con sosiego\nreposar muy satisfecha.\nLa obra está ya rematada\ncon cuanta suntuosidad\nsu postrera voluntad\ndejó al mundo encomendada.\nY ya quisieran, ¡pardiez!,\ntodos los ricos que mueren\nque su voluntad cumplieren\nlos vivos, como esta vez.\nMas ya de marcharme es hora;\ntodo corriente lo dejo,\ny de Sevilla me alejo\nal despuntar de la aurora.\n¡Ah, mármoles que mis manos\npulieron con tanto afán!\nMañana os contemplarán\nlos absortos sevillanos;\ny al mirar de este panteón\nlas gigantes proporciones,\ntendrán las generaciones\nla nuestra en veneración.\nMas yendo y viniendo días,\nse hundirán unas tras otras,\nmientra en pie estaréis vosotras,\npóstumas memorias mías.\n¡Oh, frutos de mis desvelos,\npeñas a quien yo animé,\ny por quienes arrostré\nla intemperie de los cielos!\nEl que forma y ser os dio\nva ya a perderos de vista;\nvelad mi gloria de artista,\npues viviréis más que yo.\nMas... ¿quién llega?"}, {"type": "h", "text": "Escena II"}, {"type": "v", "text": "El ESCULTOR y DON JUAN, que entra embozado."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Caballero..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Dios le guarde."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Perdonad,\nmas ya es tarde, y..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Aguardad\nun instante, porque quiero\nque me expliquéis..."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Por acaso\nsois forastero?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Años ha\nque falto de España ya,\ny me chocó el ver al paso,\ncuando a esas verjas llegué,\nque encontraba este recinto\nenteramente distinto\nde cuando yo lo dejé."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Ya lo creo! Como que esto\nera entonces un palacio,\ny hoy es panteón el espacio\ndonde aquél estuvo puesto."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡El palacio hecho panteón!"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Tal fue de su antiguo dueño\nla voluntad, y fue empeño\nque dio al mundo admiración."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Y, por Dios, que es de admirar!"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Es una famosa historia,\na la cual debo mi gloria."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Me la podéis relatar?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Sí; aunque muy sucintamente,\npues me aguardan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sea."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Oíd\nla verdad pura."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Decid,\nque me tenéis impaciente."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Pues habitó esta ciudad\ny este palacio, heredado,\nun varón muy estimado\npor su noble calidad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Don Diego Tenorio."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "El mismo.\nTuvo un hijo este don Diego\npeor mil veces que el fuego,\nun aborto del abismo.\nUn mozo sangriento y cruel,\nque con tierra y cielo en guerra,\ndicen que nada en la tierra\nfue respetado por él.\nQuimerista, seductor\ny jugador con ventura,\nno hubo para él segura\nvida, ni hacienda, ni honor.\nAsí le pinta la historia,\ny si tal era, por cierto\nque obró cuerdamente el muerto\npara ganarse la gloria."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Pues cómo obró?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Dejó entera\nsu hacienda al que la empleara\nen un panteón que asombrara\na la gente venidera.\nMas con condición, que dijo,\nque se enterraran en él\nlos que a la mano cruel\nsucumbieron de su hijo.\nY mirad en derredor\nlos sepulcros de los más\nde ellos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y vos sois quizás\nel conserje?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "El escultor\nde estas obras encargado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ah! ¿Y las habéis concluido?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Ha un mes; mas me he detenido\nhasta ver ese enverjado\ncolocado en su lugar;\npues he querido impedir\nque pueda el vulgo venir\neste sitio a profanar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Mirando.)\n¡Bien empleó sus riquezas\nEl difunto!"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Ya lo creo!\nMiradle allí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ya le veo."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Le conocisteis?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Piezas\nson todas muy parecidas,\ny a conciencia trabajadas."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Cierto que son extremadas!"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Os han sido conocidas\nlas personas?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Todas ellas."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Y os parecen bien?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sin duda,\nsegún lo que a ver me ayuda\nel fulgor de las estrellas."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Oh! Se ven como de día\ncon esta luna tan clara.\nEsta es mármol de Carrara.\n(Señalando a la de DON LUIS.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Buen busto es el de Mejía!\n¡Hola! Aquí el Comendador\nse representa muy bien."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Yo quise poner también\nla estatua del matador\nentre sus víctimas; pero\nno pude a manos haber\nsu retrato. Un Lucifer\ndicen que era el caballero\ndon Juan Tenorio."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Muy malo!\nMas, como pudiera hablar,\nle había algo de abonar\nla estatua de don Gonzalo."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿También habéis conocido\na don Juan?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mucho."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Don Diego\nle abandonó desde luego\ndesheredándole."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ha sido\npara don Juan poco daño\nése, porque la fortuna\nva tras él desde la cuna."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Dicen que ha muerto."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Es engaño;\nvive."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Y dónde?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Aquí, en Sevilla."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Y no teme que el furor\npopular...?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "En su valor\nno ha echado el miedo semilla."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Mas cuando vea el lugar\nen que está ya convertido\nel solar que suyo ha sido,\nno osará en Sevilla estar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Antes ver tendrá a fortuna\nen su casa reunidas\npersonas de él conocidas,\npuesto que no odia a ninguna."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Creéis que ose aquí venir?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Por qué no? Pienso, a mi ver,\nque donde vino a nacer\njusto es que venga a morir.\nY pues le quitan su herencia\npara enterrar a éstos bien,\na él es muy justo también\nque le entierren con decencia."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Sólo a él le está prohibida\nen este panteón la entrada."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Trae don Juan muy buena espada,\ny no sé quién se lo impida."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Jesús! ¡Tal profanación!"}]$lira$::jsonb, 900);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 27, 'Parte 28', $lira$[{"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Hombre es don Juan que, a querer,\nvolverá el palacio hacer\nencima del panteón."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Tan audaz ese hombre es\nque aún a los muertos se atreve?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué respetos gastar debe\ncon los que tendió a sus pies?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Pero no tiene conciencia\nni alma ese hombre?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tal vez no;\nque al cielo una vez llamó\ncon voces de penitencia,\ny el cielo en trance tan fuerte\nallí mismo le metió,\nque a dos inocentes dio,\npara salvarse, la muerte."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Qué monstruo, supremo Dios!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Podéis estar convencido\nde que Dios no le ha querido."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Tal será.\n(Aparte.)\n¿Y quién será el que a don Juan\nabona con tanto brío?\nCaballero, a pesar mío,\ncomo aguardándome están..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Idos, pues, enhorabuena."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "He de cerrar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No cerréis,\ny marchaos."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Mas no veis...?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Veo una noche serena\ny un lugar que me acomoda\npara gozar su frescura,\ny aquí he de estar a mi holgura,\nsi pesa a Sevilla toda."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "(Aparte.)\n¿Si acaso padecerá\nde locura desvaríos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Dirigiéndose a las estatuas.)\nYa estoy aquí, amigos míos."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿No lo dije? Loco está."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mas, ¡cielos!, ¿qué es lo que veo?\n¡O es ilusión de mi vista,\no a doña Inés el artista\naquí representa creo!"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Sin duda."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿También murió?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Dicen que de sentimiento\ncuando de nuevo al convento\nabandonada volvió\npor don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y yace aquí?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿La visteis muerta vos?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Cómo estaba?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Por Dios,\nque dormida la creí!\nLa muerte fue tan piadosa\ncon su cándida hermosura,\nque la envió con frescura\ny las tintas de la rosa."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ah! Mal la muerte podría\ndeshacer con torpe mano\nel semblante soberano\nque un ángel envidiaría.\n¡Cuán bella y cuán parecida\nsu efigie en el mármol es!\n¡Quién pudiera, doña Inés,\nvolver a darte la vida!\n¿Es obra del cincel vuestro?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Como todas las demás."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues bien merece algo más\nun retrato tan maestro.\nTomad."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿Qué me dais aquí?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿No lo veis?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Mas... caballero...\n¿por qué razón...?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Porque quiero\nyo que os acordéis de mí."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Mirad que están bien pagadas."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Así lo estarán mejor."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Mas vamos de aquí, señor,\nque aún las llaves entregadas\nno están, y al salir la aurora\ntengo que partir de aquí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Entregádmelas a mí,\ny marchaos desde ahora."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¿A vos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "A mí; ¿qué dudáis?"}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Como no tengo el honor..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ea, acabad, escultor."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "Si el nombre al menos que usáis\nsupiera..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Viven los cielos!\nDejad a don Juan Tenorio\nvelar el lecho mortuorio\nen que duermen sus abuelos."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "¡Don Juan Tenorio!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Yo soy,\ny si no me satisfaces,\ncompañía juro que haces\na tus estatuas desde hoy."}, {"type": "h", "text": "Escultor"}, {"type": "v", "text": "(Alargándole las llaves.)\nTomad.\n(Aparte.)\nNo quiero la piel\ndejar aquí entre sus manos.\nAhora que los sevillanos\nse las compongan con él."}]$lira$::jsonb, 515);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 28, 'Escena III', $lira$[{"type": "h", "text": "Escena III"}, {"type": "v", "text": "DON JUAN, solo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mi buen padre empleó en esto\nentera la hacienda mía;\nhizo bien; yo al otro día\nla hubiera a una carta puesto.\n(Pausa.)\nNo os podréis quejar de mí,\nvosotros a quien maté;\nsi buena vida os quité,\nbuena sepultura os dí.\n¡Magnífica es en verdad\nla idea del tal panteón!\nY... siento que el corazón\nme halaga esta soledad.\n¡Hermosa noche...! ¡Ay de mí!\n¡Cuántas como ésta tan puras\nen infames aventuras\ndesatinado perdí!\n¡Cuántas al mismo fulgor\nde esa luna transparente,\narranqué a algún inocente\nla existencia o el honor!\nSí; después de tantos años\ncuyos recuerdos espantan,\nsiento que aquí se levantan\n(Señalando a la frente.)\npensamientos en mí extraños.\n¡Oh! Acaso me los inspira\ndesde el cielo, en donde mora,\nesa sombra protectora\nque por mi mal no respira.\n(Se dirige a la estatua de DOÑA INÉS, hablándola con respeto.)\n¡Mármol en quien doña Inés\nen cuerpo sin alma existe,\ndeja que el alma de un triste\nllore un momento a tus pies!\nDe azares mil a través\nconservé tu imagen pura;\ny pues la mala ventura\nte asesinó de don Juan,\ncontempla con cuánto afán\nvendrá hoy a tu sepultura.\nEn ti nada más pensó\ndesde que se fue de ti;\ny desde que huyó de aquí,\nsólo en volver meditó.\nDon Juan tan sólo esperó\nde doña Inés su ventura,\ny hoy que en pos de su hermosura\nvuelve el infeliz don Juan,\nmira cuál será su afán\nal dar con tu sepultura.\nInocente doña Inés,\ncuya hermosa juventud\nencerró en el ataúd\nquien llorando está a tus pies;\nsi de esa piedra a través\npuedes mirar la amargura\ndel alma que tu hermosura\nadoró con tanto afán,\nprepara un lado a don Juan\nen tu misma sepultura.\nDios te crió por mi bien,\npor ti pensé en la virtud,\nadoré su excelsitud,\ny anhelé su santo Edén.\nSí; aún hoy mismo en ti también\nmi esperanza se asegura,\ny oigo una voz que murmura\nen derredor de don Juan\npalabras con que su afán\nse calma en tu sepultura.\n¡Oh, doña Inés de mi vida!\nSi esa voz con quien deliro\nes el postrimer suspiro\nde tu eterna despedida;\nsi es que de ti desprendida\nllega esa voz a la altura,\ny hay un Dios tras de esa anchura\npor donde los astros van,\ndile que mire a don Juan\nllorando en tu sepultura.\n(Se apoya en el sepulcro, ocultando el rostro; y mientras se conserva en\nesta postura, un vapor que se levanta del sepulcro oculta la estatua de DOÑA\nINÉS. Cuando el vapor se desvanece, la estatua ha desaparecido. DON JUAN\nsale de su enajenamiento.)\nEste mármol sepulcral\nadormece mi vigor,\ny sentir creo en redor\nun ser sobrenatural.\nMas... ¡cielos! ¡El pedestal\nno mantiene su escultura!\n¿Qué es esto? Aquella figura\n¿fue creación de mi afán?"}]$lira$::jsonb, 483);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 29, 'Escena IV', $lira$[{"type": "h", "text": "Escena IV"}, {"type": "v", "text": "DON JUAN y la SOMBRA de doña Inés. El llorón y las flores de la\nizquierda del sepulcro de DOÑA INÉS se cambian en una apariencia, dejando\nver dentro de ella, y en medio de resplandores, la SOMBRA de doña Inés."}, {"type": "h", "text": "Sombra"}, {"type": "v", "text": "No; mi espíritu, don Juan,\nte aguardó en mi sepultura."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(De rodillas.)\n¡Doña Inés! ¡Sombra querida,\nalma de mi corazón,\nno me quites la razón\nsi me has de dejar la vida!\nSi eres imagen fingida,\nsólo hija de mi locura,\nno aumentes mi desventura\nburlando mi loco afán."}, {"type": "h", "text": "Sombra"}, {"type": "v", "text": "Yo soy doña Inés, don Juan,\nque te oyó en su sepultura."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Conque vives?"}, {"type": "h", "text": "Sombra"}, {"type": "v", "text": "Para ti;\nmas tengo mi purgatorio\nen ese mármol mortuorio\nque labraron para mí.\nYo a Dios mi alma ofrecí\nen precio de tu alma impura;\ny Dios, al ver la ternura\ncon que te amaba mi afán,\nme dijo: «Espera a don Juan\nen tu misma sepultura.\nY pues quieres ser tan fiel\na un amor de Satanás,\ncon don Juan te salvarás,\no te perderás con él.\nPor él vela; mas si cruel\nte desprecia tu ternura,\ny en su torpeza y locura\nsigue con bárbaro afán,\nllévese tu alma don Juan\nde tu misma sepultura»."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Fascinado.)\n¡Yo estoy soñando quizás\ncon las sombras de un Edén!"}, {"type": "h", "text": "Sombra"}, {"type": "v", "text": "No; y ve que si piensas bien,\na tu lado me tendrás;\nmas si obras mal, causarás\nnuestra eterna desventura.\nY medita con cordura\nque es esta noche, don Juan,\nel espacio que nos dan\npara buscar sepultura.\nAdiós, pues; y en la ardua lucha\nen que va a entrar tu existencia,\nde tu dormida conciencia\nla voz que va a alzarse escucha,\nporque es de importancia mucha\nmeditar con sumo tiento\nla elección de aquel momento\nque, sin poder evadirnos,\nal mal o al bien ha de abrirnos\nla losa del monumento.\n(Se cierra la apariencia; desaparece DOÑA INÉS, y todo queda como al\nprincipio del acto, menos la estatua de DOÑA INÉS, que no vuelve a su lugar.\nDON JUAN queda atónito.)"}]$lira$::jsonb, 349);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 30, 'Escena V', $lira$[{"type": "h", "text": "Escena V"}, {"type": "v", "text": "DON JUAN, solo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Cielos! ¿Qué es lo que escuché?\n¡Hasta los muertos así\ndejan sus tumbas por mí!\nMas, sombra, delirio fue.\nYo en mi mente lo forjé;\nla imaginación le dio\nla forma en que se mostró,\ny ciego, vine a creer\nen la realidad de un ser\nque mi mente fabricó.\nMas nunca de modo tal\nfanatizó mi razón\nmi loca imaginación\ncon su poder ideal.\nSí; algo sobrenatural\nvi en aquella doña Inés\ntan vaporosa, a través\naun de esa enramada espesa;\nmas... ¡bah!, circunstancia es ésa\nque propia de sombra es.\n¿Qué más diáfano y sutil\nque las quimeras de un sueño?\n¿Dónde hay nada más risueño,\nmás flexible y más gentil?\n¿Y no pasa veces mil\nque, en febril exaltación,\nve nuestra imaginación\ncomo ser y realidad\nla vacía vanidad\nde una anhelada ilusión?\n¡Sí, por Dios; delirio fue!\nMas su estatua estaba aquí.\nSí; yo la vi y la toqué,\ny aun en albricias le dí\nal escultor, no sé qué.\n¡Y ahora sólo el pedestal\nveo en la urna funeral!\n¡Cielos! ¿La mente me falta,\no de improviso me asalta\nalgún vértigo infernal?\n¿Qué dijo aquella visión?\n¡Oh! Yo la oí claramente,\ny su voz triste y doliente\nresonó en mi corazón.\n¡Ah! ¡Y breves las horas son\ndel plazo que nos augura!\n¡No, no; de mi calentura\ndelirio insensato es!\nMi fiebre fue a doña Inés\nquien abrió la sepultura.\n¡Pasad y desvaneceos;\npasad, siniestros vapores\nde mis perdidos amores\ny mis fallidos deseos!\n¡Pasad, vanos devaneos\nde un amor muerto al nacer;\nno me volváis a traer\nentre vuestro torbellino\nese fantasma divino\nque recuerda a una mujer!\n¡Ah!, estos sueños me aniquilan,\nmi cerebro se enloquece...\n¡y esos mármoles parece\nque estremecidos vacilan!\n(Las estatuas se mueven lentamente, y vuelven la cabeza hacia él.)\n¡Sí, sí; sus bustos oscilan,\nsu vago contorno medra...!\nPero don Juan no se arredra.\n¡Alzaos, fantasmas vanos,\ny os volveré con mis manos\na vuestros lechos de piedra!\nNo; no me causan pavor\nvuestros semblantes esquivos;\njamás, ni muertos ni vivos,\nhumillaréis mi valor.\nYo soy vuestro matador,\ncomo al mundo es bien notorio;\nsi en vuestro alcázar mortuorio\nme aprestáis venganza fiera,\ndaos prisa, que aquí os espera\notra vez don Juan Tenorio."}]$lira$::jsonb, 383);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 31, 'Escena VI', $lira$[{"type": "h", "text": "Escena VI"}, {"type": "v", "text": "DON JUAN, el Capitán CENTELLAS y AVELLANEDA."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Don Juan Tenorio?\n(Dentro.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Volviendo en sí.)\n¿Qué es eso?\n¿Quién me repite mi nombre?"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "(Saliendo.)\n¿Veis a alguien?"}, {"type": "h", "text": "(a Centellas.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "(Saliendo.)\nSí; allí hay un hombre."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Quién va?"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Él es."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "(Yéndose a DON JUAN.)\nYo pierdo el seso\ncon la alegría. ¡Don Juan!"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¡Señor Tenorio!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Apartaos,\nvanas sombras!"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Reportaos,\nseñor don Juan... Los que están\nen vuestra presencia ahora,\nno son sombras, hombres son,\ny hombres cuyo corazón\nvuestra amistad atesora.\nA la luz de las estrellas\nos hemos reconocido,\ny un abrazo hemos venido\na daros."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Gracias, Centellas."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Mas... ¿qué tenéis? Por mi vida\nque os tiembla el brazo, y está\nvuestra faz descolorida."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "La luna tal vez lo hará.\n(Recobrando su aplomo.)"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Mas, don Juan, ¿qué hacéis aquí?\n¿Este sitio conocéis?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿No es un panteón?"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Y sabéis\na quién pertenece?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "A mí;\nmirad a mi alrededor,\ny no veréis más que amigos\nde mi niñez, o testigos\nde mi audacia y mi valor."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Pero os oímos hablar:\n¿con quién estabais?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Con ellos."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Venís aún a escarnecellos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No; los vengo a visitar.\nMas un vértigo insensato\nque la mente me asaltó,\nun momento me turbó;\ny a fe que me dio un mal rato.\nEsos fantasmas de piedra\nme amenazaban tan fieros,\nque a mí acercado no haberos\npronto..."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Ja! ¡ja! ¡ja! ¿Os arredra,\ndon Juan, como a los villanos,\nel temor de los difuntos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No a fe; contra todos juntos\ntengo aliento y tengo manos.\nSi volvieran a salir\nde las tumbas en que están,\na las manos de don Juan\nvolverían a morir.\nY desde aquí en adelante\nsabed, señor capitán,\nque yo soy siempre don Juan,\ny no hay cosa que me espante.\nUn vapor calenturiento\nun punto me fascinó,\nCentellas, mas ya pasó;\ncualquiera duda un momento.\nAVELLANEDA y"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Es verdad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vamos de aquí."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Vamos, y nos contaréis\ncómo a Sevilla volvéis\ntercera vez."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Lo haré así.\nSi mi historia os interesa,\na fe que oírse merece,\naunque mejor me parece\nque la oigáis de sobremesa.\n¿No opináis...?\nAVELLANEDA y"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Como gustéis."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues bien; cenaréis conmigo,\ny en mi casa."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Pero digo:\n¿es cosa de que dejéis\nalgún huésped por nosotros?\n¿No tenéis gato encerrado?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Bah! Si apenas he llegado;\nno habrá allí más que vosotros\nesta noche."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Y no hay tapada\na quien algún plantón demos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Los tres solos cenaremos.\nDigo, si de esta jornada\nno quiere igualmente ser\nalguno de éstos.\n(Señalando a las estatuas de los sepulcros.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Don Juan,\ndejad tranquilos yacer\na los que con Dios están."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Hola! ¿Parece que vos\nsois ahora el que teméis\ny mala cara ponéis\na los muertos? ¡Mas, por Dios,\nque ya que de mí os burlasteis\ncuando me visteis así,\nen lo que penda de mí\nos mostraré cuánto errasteis!\nPor mí, pues, no ha de quedar;\ny, a poder ser, estad ciertos\nque cenaréis con los muertos,\ny os los voy a convidar."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Dejaos de esas quimeras."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Duda en mi valor ponerme,\ncuando hombre soy para hacerme\nplatos de sus calaveras?\nYo a nada tengo pavor;\n(Dirigiéndose a la ESTATUA de don Gonzalo, que es la que tiene más\ncerca.)\ntú eres el más ofendido:\nmas, si quieres, te convido\na cenar, Comendador.\nQue no lo puedas hacer\ncreo, y es lo que me pesa;\nmas, por mi parte, en la mesa\nte haré un cubierto poner.\nY a fe que favor me harás,\npues podré saber de ti\nsi hay más mundo que el de aquí\ny otra vida, en que jamás,\na decir verdad, creí."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Don Juan, eso no es valor:\nlocura, delirio es."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Como lo juzguéis mejor;\nyo cumplo así. Vamos, pues.\nLo dicho, Comendador."}]$lira$::jsonb, 672);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 32, 'Acto II', $lira$[{"type": "h", "text": "Acto II"}, {"type": "h", "text": "La estatua de don gonzalo"}, {"type": "v", "text": "DON JUAN, CENTELLAS, AVELLANEDA, CIUTTI, la SOMBRA de\ndoña Inés, la ESTATUA de don Gonzalo.\nAposento de DON JUAN Tenorio. Dos puertas en el fondo a derecha e\nizquierda preparadas para el juego escénico del acto. Otra puerta en el bastidor\nque cierra la decoración por la izquierda. Ventana en el de la derecha. Al\nalzarse el telón están sentados a la mesa DON JUAN, CENTELLAS y\nAVELLANEDA. La mesa ricamente servida, el mantel cogido con guirnaldas\nde flores, etc. Enfrente del espectador, DON JUAN, y a su izquierda\nAVELLANEDA; en el lado izquierdo de la mesa, CENTELLAS, y en el de\nenfrente de éste, una silla y un cubierto desocupado."}, {"type": "h", "text": "Escena I"}, {"type": "v", "text": "DON JUAN, el Capitán CENTELLAS, AVELLANEDA, CIUTTI y un"}, {"type": "h", "text": "Paje"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tal es mi historia, señores;\npagado de mi valor,\nquiso el mismo Emperador\ndispensarme sus favores.\nY aunque oyó mi historia entera,\ndijo: «Hombre de tanto brío\nmerece el amparo mío;\nvuelva a España cuando quiera»;\ny heme aquí en Sevilla ya."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Y con qué lujo y riqueza!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Siempre vive con grandeza\nquien hecho a grandeza está."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "A vuestra vuelta."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Bebamos."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Lo que no acierto a creer\nes cómo llegando ayer\nya establecido os hallamos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Fue el adquirirme, señores,\ntal casa con tal boato,\nporque se vendió a barato\npara pago de acreedores.\nY como al llegar aquí\ndesheredado me hallé,\ntal como está la compré."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Amueblada y todo?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí;\nun necio que se arruinó\npor una mujer, vendiola."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Y vendió la hacienda sola?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y el alma al diablo."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Murió?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "De repente; y la justicia,\nque iba a hacer de cualquier modo\npronto despacho de todo,\nviendo que yo su codicia\nsaciaba, pues los dineros\nofrecía dar al punto,\ncediome el caudal por junto\ny estafó a los usureros."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Y la mujer, ¿qué fue de ella?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Un escribano la pista\nla siguió, pero fue lista\ny escapó."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Moza?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y muy bella."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Entrar hubiera debido\nen los muebles de la casa."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Don Juan Tenorio no pasa\nmoneda que se ha perdido.\nCasa y bodega he comprado;\ndos cosas que, no os asombre,\npueden bien hacer a un hombre\nvivir siempre acompañado;\ncomo lo puede mostrar\nvuestra agradable presencia,\nque espero que con frecuencia\nme hagáis ambos disfrutar."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Y nos haréis honra inmensa."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Y a mí vos. ¡Ciutti!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Señor."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pon vino al Comendador.\n(Señalando al vaso del puesto vacío.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Don Juan, ¿aún en eso piensa\nvuestra locura?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Sí, a fe!\nQue si él no puede venir,\nde mí no podréis decir\nque en ausencia no le honré."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Ja! ¡ja! ¡ja! Señor Tenorio,\ncreo que vuestra cabeza\nva menguando en fortaleza."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Fuera en mí contradictorio\ny ajeno de mi hidalguía\na un amigo convidar,\ny no guardarle el lugar\nmientras que llegar podría.\nTal ha sido mi costumbre\nsiempre, y siempre ha de ser ésa;\ny al mirar sin él la mesa,\nme da en verdad pesadumbre.\nPorque si el Comendador\nes difunto tan tenaz\ncomo vivo, es muy capaz\nde seguirnos el humor."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Brindemos a su memoria,\ny más en él no pensemos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sea."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Brindemos.\nAVELLANEDA y"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Brindemos."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "A que Dios le dé su gloria."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mas yo, que no creo que haya\nmás gloria que esta mortal,\nno hago mucho en brindis tal;\nmas por complaceros, ¡vaya!\nY brindo a que Dios te dé\nla gloria, Comendador.\n(Mientras beben se oye lejos un aldabonazo, que se supone dado en la\npuerta de la calle.)\nMas, ¿llamaron?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Sí, señor."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Ve quién."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "(Asomándose por la ventana.)\nA nadie se ve.\n¿Quién va allá? Nadie responde."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Algún chusco."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Algún menguado\nque al pasar habrá llamado\nsin mirar siquiera dónde."}, {"type": "h", "text": "Don Juan"}, {"type": "h", "text": "(a Ciutti.)"}, {"type": "v", "text": "Pues cierra y sirve licor.\n(Llaman otra vez más recio.)\nMas llamaron otra vez."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vuelve a mirar."}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "¡Pardiez!\nA nadie veo, señor."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues, por Dios, que del bromazo\nquien es no se ha de alabar.\nCiutti, si vuelve a llamar,\nsuéltale un pistoletazo.\n(Llaman otra vez, y se oye un poco más cerca.)\n¿Otra vez?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "¡Cielos!\nAVELLANEDA y"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Qué pasa?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Que esa aldabada postrera\nha sonado en la escalera,\nno en la puerta de la casa.\nAVELLANEDA y"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Qué dices?\n(Levantándose asombrados.)"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Digo lo cierto,\nnada más; dentro han llamado\nde la casa."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Qué os ha dado?\n¿Pensáis que sea ya el muerto?\nMis armas cargué con bala;\nCiutti, sal a ver quién es.\n(Vuelven a llamar más cerca.)"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¿Oisteis?"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Por San Ginés,\nque eso ha sido en la antesala."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ah! Ya lo entiendo, me habéis\nvosotros mismos dispuesto\nesta comedia, supuesto\nque lo del muerto sabéis."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Yo os juro, don Juan..."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Y yo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Bah! Diera en ello el más topo;\ny apuesto a que ese galopo\nlos medios para ello os dio."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Señor don Juan, escondido\nalgún misterio hay aquí.\n(Vuelven a llamar más cerca.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Llamaron otra vez!"}, {"type": "h", "text": "Ciutti"}, {"type": "v", "text": "Sí,\ny ya en el salón ha sido."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ya! Mis llaves en manojo\nhabréis dado a la fantasma,\ny que entre así no me pasma;\nmas no saldrá a vuestro antojo,\nni me han de impedir cenar\nvuestras farsas desdichadas.\n(Se levanta y corre los cerrojos de la puerta del fondo, volviendo a su\nlugar.)\nYa están las puertas cerradas;\nahora el coco, para entrar,\ntendrá que echarlas al suelo,\ny en el punto que lo intente,\nque con los muertos se cuente,\ny apele después al cielo."}]$lira$::jsonb, 968);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 33, 'Parte 34', $lira$[{"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Qué diablos, tenéis razón!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Pues no temblabais?"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Confieso\nque en tanto que no dí en eso,\ntuve un poco de aprensión."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Declaráis, pues, vuestro enredo?"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Por mi parte nada sé."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Ni yo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pues yo volveré\ncontra el inventor el miedo.\nMas, sigamos con la cena;\nvuelva cada uno a su puesto,\nque luego sabremos de esto."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Tenéis razón."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(Sirviendo a CENTELLAS.)\nCariñena;\nsé que os gusta, capitán."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Como que somos paisanos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "(A AVELLANEDA, sirviéndole de otra botella.)\nJerez a los sevillanos,\ndon Rafael."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Hais, don Juan,\ndado a entrambos por el gusto;\nmas, ¿con cuál brindaréis vos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Yo haré justicia a los dos."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Vos siempre estáis en lo justo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sí, a fe; bebamos.\nAVELLANEDA y CENTELLAS\nBebamos.\n(Llaman a la misma puerta de la escena, fondo derecha.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pesada me es ya la broma;\nmas veremos quién asoma\nmientras en la mesa estamos.\n(A CIUTTI, que se manifiesta asombrado.)\n¿Y qué haces tú ahí, bergante?\n¡Listo! Trae otro manjar;\n(Vase CIUTTI.)\nmas me ocurre en este instante\nque nos podemos mofar\nde los de afuera, invitándoles\na probar su sutileza,\nentrándose hasta esta pieza\ny sus puertas no franqueándoles."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Bien dicho."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Idea brillante.\n(Llaman fuerte, fondo derecha.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Señores! ¿A qué llamar?\nLos muertos se han de filtrar\npor la pared; adelante.\n(La ESTATUA de don Gonzalo pasa por la puerta, sin abrirla y sin hacer\nruido.)"}, {"type": "h", "text": "Escena II"}, {"type": "v", "text": "DON JUAN, CENTELLAS, AVELLANEDA y la ESTATUA de don\nGonzalo."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Jesús!"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¡Dios mío!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Qué es esto!"}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Yo desfallezco.\n(Cae desvanecido.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Yo expiro.\n(Cae lo mismo.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Es realidad, o deliro!\nEs su figura... su gesto."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "¿Por qué te causa pavor\nquien convidado a tu mesa\nviene por ti?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Dios! ¿No es ésa\nla voz del Comendador?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Siempre supuse que aquí\nno me habías de esperar."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Mientes, porque hice arrimar\nesa silla para ti.\nLlega, pues, para que veas\nque, aunque dudé en un extremo\nde sorpresa, no te temo,\naunque el mismo Ulloa seas."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "¿Aún lo dudas?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No lo sé."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Pon, si quieres, hombre impío,\ntu mano en el mármol frío\nde mi estatua."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Para qué?\nMe basta oírlo de ti;\ncenemos, pues; mas te advierto..."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "¿Qué?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Que si no eres el muerto,\nlo vas a salir de aquí.\n¡Ea! Alzad.\n(A CENTELLAS y a AVELLANEDA.)"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "No pienses, no,\nque se levanten, don Juan,\nporque en sí no volverán\nhasta que me ausente yo.\nQue la divina clemencia\ndel Señor para contigo,\nno requiere más testigo\nque tu juicio y tu conciencia.\nAl sacrílego convite\nque me has hecho en el panteón,\npara alumbrar tu razón\nDios asistir me permite.\nY heme que vengo en su nombre\na enseñarte la verdad;\ny es: que hay una eternidad\ntras de la vida del hombre.\nQue numerados están\nlos días que has de vivir,\ny que tienes que morir\nmañana mismo, don Juan.\nMas, como esto que a tus ojos\nestá pasando, supones\nser del alma aberraciones\ny de la aprensión antojos,\nDios en su santa clemencia\nte concede todavía\nun plazo hasta el nuevo día\npara ordenar tu conciencia.\nY su justicia infinita\npor que conozcas mejor,\nespero de tu valor\nque me pagues la visita.\n¿Irás, don Juan?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Iré, sí;\nmas me quiero convencer\nde lo vago de tu ser\nantes que salgas de aquí.\n(Coge una pistola.)"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Tu necio orgullo delira,\ndon Juan; los hierros más gruesos\ny los muros más espesos\nse abren a mi paso; mira.\n(Desaparece la ESTATUA sumiéndose por la pared.)"}]$lira$::jsonb, 627);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 34, 'Escena III', $lira$[{"type": "h", "text": "Escena III"}, {"type": "v", "text": "DON JUAN, AVELLANEDA y CENTELLAS."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Cielos! ¡Su esencia se trueca\nel muro hasta penetrar\ncual mancha de agua que seca\nel ardor canicular!\n¿No me dijo: «El mármol toca\nde mi estatua»? ¿Cómo, pues,\nse desvanece una roca?\n¡Imposible! Ilusión es.\nAcaso su antiguo dueño\nmis cubas envenenó,\ny el licor tan vano ensueño\nen mi mente levantó.\nMas si estas que sombras creo\nespíritus reales son\nque por celestial empleo\nllaman a mi corazón,\nentonces, para que iguale\nsu penitencia don Juan\ncon sus delitos, ¿qué vale\nel plazo ruin que le dan...?\n¡Dios me da tan sólo un día...!\nSi fuese Dios en verdad,\na más distancia pondría\nsu aviso a mi eternidad.\n«Piensa bien que al lado tuyo\nme tendrás...», dijo de Inés\nla sombra; y si bien arguyo,\npues no la veo, sueño es.\n(Transparéntase en la pared la SOMBRA de doña Inés.)"}, {"type": "h", "text": "Escena IV"}, {"type": "v", "text": "DON JUAN, la SOMBRA de doña Inés, CENTELLAS y AVELLANEDA\ndormidos."}, {"type": "h", "text": "Sombra"}, {"type": "v", "text": "Aquí estoy."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Cielos!"}, {"type": "h", "text": "Sombra"}, {"type": "v", "text": "Medita\nlo que al buen Comendador\nhas oído, y ten valor\npara acudir a su cita.\nUn punto se necesita\npara morir con ventura:\nelígele con cordura,\nporque mañana, don Juan,\nnuestros cuerpos dormirán\nen la misma sepultura.\n(Desaparece la SOMBRA.)"}, {"type": "h", "text": "Escena V"}, {"type": "v", "text": "DON JUAN, CENTELLAS y AVELLANEDA."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tente, doña Inés, espera;\ny si me amas en verdad,\nhazme al fin la realidad\ndistinguir de la quimera.\nAlguna más duradera\nseñal dame, que segura\nme pruebe que no es locura\nlo que imagina mi afán,\npara que baje don Juan\ntranquilo a la sepultura.\nMas ya me irrita, por Dios,\nel verme siempre burlado,\ncorriendo desatentado\nde varias sombras en pos.\n¡Oh! Tal vez todo esto ha sido\npor estos dos preparado,\ny mientras se ha ejecutado\nsu privación han fingido.\nMas, por Dios, que, si es así,\nse han de acordar de don Juan.\n¡Eh! don Rafael, capitán,\nya basta: alzaos de ahí.\n(DON JUAN mueve a CENTELLAS y a AVELLANEDA, que se levantan\ncomo quien vuelve de un profundo sueño.)"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Quién va?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Levantad."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¿Qué pasa?\nHola, ¿sois vos?"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¿Dónde estamos?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Caballeros, claro vamos.\nYo os he traído a mi casa,\ny temo que a ella al venir\ncon artificio apostado\nhabéis sin duda pensado\na costa mía reír;\nmas basta ya de ficción,\ny concluid de una vez."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Yo no os entiendo."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "¡Pardiez!\nTampoco yo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "En conclusión:\n¿nada habéis visto ni oído?\nAVELLANEDA y CENTELLAS\n¿De qué?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No finjáis más."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Yo no he fingido jamás,\nseñor don Juan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Habrá sido\nrealidad! ¿Contra Tenorio\nlas piedras se han animado,\ny su vida han acortado\ncon plazo tan perentorio?\nHablad, pues, por compasión."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Voto va Dios! ¡Ya comprendo\nlo que pretendéis!"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Pretendo\nque me deis una razón\nde lo que ha pasado aquí,\nseñores, o juro a Dios\nque os haré ver a los dos\nque no hay quien me burle a mí."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Pues ya que os formalizáis,\ndon Juan, sabed que sospecho\nque vos la burla habéis hecho\nde nosotros."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Me insultáis!"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "No, por Dios; mas si cerrado\nseguís en que aquí han venido\nfantasmas, lo sucedido\noíd cómo me he explicado.\nYo he perdido aquí del todo\nlos sentidos, sin exceso\nde ninguna especie, y eso\nlo entiendo yo de este modo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "A ver, decídmelo, pues."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Vos habéis compuesto el vino,\nsemejante desatino\npara encajarnos después."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Centellas!"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Vuestro valor\nal extremo por mostrar,\nconvidasteis a cenar\ncon vos al Comendador.\nY para poder decir\nque a vuestro convite exótico\nasistió, con un narcótico\nnos habéis hecho dormir.\nSi es broma, puede pasar;\nmas a ese extremo llevada,\nni puede probarnos nada,\nni os la hemos de tolerar."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Soy de la misma opinión."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Mentís!"}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Vos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vos, capitán."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Esa palabra, don Juan..."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "La he dicho de corazón.\nMentís; no son a mis bríos\nmenester falsos portentos,\nporque tienen mis alientos\nsu mejor prueba en ser míos.\nAVELLANEDA y CENTELLAS\nVeamos.\n(Ponen mano a las espadas.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Poned a tasa\nvuestra furia, y vamos fuera,\nno piense después cualquiera\nque os asesiné en mi casa."}, {"type": "h", "text": "Avellaneda"}, {"type": "v", "text": "Decís bien... mas somos dos."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Reñiremos, si os fiáis,\nel uno del otro en pos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "O los dos, como queráis."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "¡Villano fuera, por Dios!\nElegid uno, don Juan,\npor primero."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Sedlo vos."}, {"type": "h", "text": "Centellas"}, {"type": "v", "text": "Vamos."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Vamos, capitán."}]$lira$::jsonb, 761);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 35, 'Acto III', $lira$[{"type": "h", "text": "Acto III"}, {"type": "v", "text": "DON JUAN, la ESTATUA de don Gonzalo, DOÑA INÉS.\nSombras, estatuas, espectros, ángeles.\nPanteón de la familia Tenorio. Como estaba en el acto primero de la\nsegunda parte, menos las estatuas de DOÑA INÉS y DON GONZALO, que no\nestán en su lugar."}, {"type": "h", "text": "Escena I"}, {"type": "v", "text": "DON JUAN, embozado y distraído, entra en la escena lentamente."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Culpa mía no fue; delirio insano\nme enajenó la mente acalorada.\nNecesitaba víctimas mi mano\nque inmolar a mi fe desesperada,\ny al verlos en mitad de mi camino,\npresa les hice allí de mi locura.\n¡No fui yo, vive Dios! ¡Fue su destino!\nSabían mi destreza y mi ventura.\n¡Oh! Arrebatado el corazón me siento\npor vértigo infernal... Mi alma perdida\nva cruzando el desierto de la vida\ncual hoja seca que arrebata el viento.\nDudo... temo... vacilo... en mi cabeza\nsiento arder un volcán... muevo la planta\nsin voluntad, y humilla mi grandeza\nun no sé qué de grande que me espanta.\n(Un momento de pausa.)\nJamás mi orgullo concibió que hubiere\nNada más que el valor... Que se aniquila\nel alma con el cuerpo cuando muere\ncreí... mas hoy mi corazón vacila.\n¡Jamás creí en fantasmas...! ¡Desvaríos!\nMas del fantasma aquel, pese a mi aliento\nlos pies de piedra caminando siento\npor doquiera que voy tras de los míos.\n¡Oh! Y me trae a este sitio irresistible\nmisterioso poder...\n(Levanta la cabeza y ve que no está en su pedestal la ESTATUA de don\nGonzalo.)\nPero, ¡qué veo!\n¡Falta de allí su estatua...! Sueño horrible,\ndéjame de una vez... ¡No, no te creo!\nSal; huye de mi mente fascinada,\nfatídica ilusión... estás en vano\ncon pueriles asombros empeñada\nen agotar mi aliento sobrehumano.\nSi todo es ilusión, mentido sueño,\nnadie me ha de aterrar con trampantojos;\nsi es realidad, querer es necio empeño\naplacar de los cielos los enojos.\nNo; sueño o realidad, del todo anhelo\nvencerle o que me venza; y si piadoso\nbusca tal vez mi corazón el cielo,\nque le busque más franco y generoso.\nLa efigie de esa tumba me ha invitado\na venir a buscar prueba más cierta\nde la verdad en que dudé obstinado...\nHeme aquí, pues; Comendador, despierta.\n(Llama al sepulcro del Comendador. Este sepulcro se cambia en una mesa,\nque parodia horriblemente la mesa en que comieron, en el acto anterior, DON\nJUAN, CENTELLAS y AVELLANEDA. En vez de las guirnaldas que cogían\nen pabellones sus manteles, de sus flores y lujoso servicio, culebras, huesos y\nfuego, etc. (A gusto del pintor.) Encima de esta mesa aparece un plato de\nceniza, una copa de fuego y un reloj de arena. Al cambiarse este sepulcro,\ntodos los demás se abren y dejan paso a las osamentas de las personas que se\nsuponen enterradas en ellos, envueltas en sus sudarios. Sombras, espectros y\nespíritus pueblan el fondo de la escena. La tumba de DOÑA INÉS\npermanece.)"}]$lira$::jsonb, 484);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 36, 'Escena II', $lira$[{"type": "h", "text": "Escena II"}, {"type": "v", "text": "DON JUAN, la ESTATUA de don Gonzalo y las sombras."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Aquí me tienes, don Juan,\ny he aquí que vienen conmigo\nlos que tu eterno castigo\nde Dios reclamando están."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Jesús!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "¿Y de qué te alteras,\nsi nada hay que a ti te asombre,\ny para hacerte eres hombre\nplatos con sus calaveras?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ay de mí!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "¿Qué? ¿El corazón\nte desmaya?"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "No lo sé;\nconcibo que me engañé;\nno son sueños... ¡ellos son!\n(Mirando a los espectros.)\nPavor jamás conocido\nel alma fiera me asalta,\ny aunque el valor no me falta,\nme va faltando el sentido."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Eso es, don Juan, que se va\nconcluyendo tu existencia,\ny el plazo de tu sentencia\nfatal ha llegado ya."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Qué dices!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Lo que hace poco\nque doña Inés te avisó,\nlo que te he avisado yo,\ny lo que olvidaste loco.\nMas el festín que me has dado\ndebo volverte, y así,\nllega, don Juan, que yo aquí\ncubierto te he preparado."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y qué es lo que ahí me das?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Aquí fuego, allí ceniza."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "El cabello se me eriza."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Te doy lo que tú serás."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Fuego y ceniza he de ser!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Cual los que ves en redor;\nen eso para el valor,\nla juventud y el poder."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Ceniza bien; pero fuego...!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "El de la ira omnipotente,\ndo arderás eternamente\npor tu desenfreno ciego."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Conque hay otra vida más\ny otro mundo que el de aquí?\n¿Conque es verdad, ¡ay de mí!,\nlo que no creí jamás?\n¡Fatal verdad que me hiela\nla sangre en el corazón!\n¡Verdad que mi perdición\nsolamente me revela!\n¿Y ese reloj?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Es la medida\nde tu tiempo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Expira ya?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Sí; en cada grano se va\nun instante de tu vida."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y esos me quedan no más?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Injusto Dios! Tu poder\nme haces ahora conocer,\ncuando tiempo no me das\nde arrepentirme."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Don Juan,\nun punto de contrición\nda a un alma la salvación,\ny ese punto aún te le dan."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Imposible! ¡En un momento\nborrar treinta años malditos\nde crímenes y delitos!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Aprovéchale con tiento,\n(Tocan a muerto.)\nporque el plazo va a expirar,\ny las campanas doblando\npor ti están, y están cavando\nla fosa en que te han de echar.\n(Se oye a lo lejos el oficio de difuntos.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Conque por mí doblan?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Sí."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y esos cantos funerales?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Los salmos penitenciales\nque están cantando por ti.\n(Se ve pasar por la izquierda luz de hachones, y rezan dentro.)"}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Y aquel entierro que pasa?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Es el tuyo."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Muerto yo!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "El capitán te mató\na la puerta de tu casa."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Tarde la luz de la fe\npenetra en mi corazón,\npues crímenes mi razón\na su luz tan sólo ve.\nLos ve... y con horrible afán,\nporque al ver su multitud,\nve a Dios en su plenitud\nde su ira contra don Juan.\n¡Ah! Por doquiera que fui,\nla razón atropellé,\nla virtud escarnecí\ny a la justicia burlé.\nY emponzoñé cuanto vi,\ny a las cabañas bajé,\ny a los palacios subí,\ny los claustros escalé;\ny pues tal mi vida fue,\nno, no hay perdón para mí.\n¡Mas ahí estáis todavía\n(A los fantasmas.)\nCon quietud tan pertinaz!\nDejadme morir en paz\na solas con mi agonía.\nMas con esa horrenda calma,\n¿qué me auguráis, sombras fieras?\n¿Qué esperáis de mí?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Que mueras\npara llevarse tu alma.\nY adiós, don Juan; ya tu vida\ntoca a su fin, y pues vano\ntodo fue, dame la mano\nen señal de despedida."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¿Muéstrasme ahora amistad?"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Sí; que injusto fui contigo,\ny Dios me manda tu amigo\nvolver a la eternidad."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Toma, pues."}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Ahora, don Juan,\npues desperdicias también\nel momento que te dan,\nconmigo al infierno ven."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Aparta, piedra fingida!\nSuelta, suéltame esa mano,\nque aún queda el último grano\nen el reloj de mi vida.\nSuéltala, que si es verdad\nque un punto de contrición\nda a un alma la salvación\nde toda una eternidad,\nyo, santo Dios, creo en ti;\nsi es mi maldad inaudita,\ntu piedad es infinita...\n¡Señor, ten piedad de mí!"}, {"type": "h", "text": "Estatua"}, {"type": "v", "text": "Ya es tarde.\n(DON JUAN se hinca de rodillas, tendiendo al cielo la mano que le deja\nlibre la ESTATUA. Las sombras, esqueletos, etc., van a abalanzarse sobre él,\nen cuyo momento se abre la tumba de DOÑA INÉS y aparece ésta. DOÑA\nINÉS toma la mano que DON JUAN tiende al cielo.)"}]$lira$::jsonb, 789);
insert into public.chapters (book_id, position, title, body, word_count)
values ('don-juan-tenorio', 37, 'Escena III', $lira$[{"type": "h", "text": "Escena III"}, {"type": "v", "text": "DON JUAN, la ESTATUA de don Gonzalo, DOÑA INÉS, sombras, etc."}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "No; heme ya aquí,\ndon Juan; mi mano asegura\nesta mano que a la altura\ntendió tu contrito afán,\ny Dios perdona a don Juan\nal pie de mi sepultura."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Dios clemente! ¡Doña Inés!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Fantasmas, desvaneceos:\nSu fe nos salva... volveos\na vuestros sepulcros, pues\nla voluntad de Dios es;\nde mi alma con la amargura\npurifiqué su alma impura,\ny Dios concedió a mi afán\nla salvación de don Juan\nal pie de la sepultura."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "¡Inés de mi corazón!"}, {"type": "h", "text": "Doña Inés"}, {"type": "v", "text": "Yo mi alma he dado por ti,\ny Dios te otorga por mí\ntu dudosa salvación.\nMisterio es que en comprensión\nno cabe de criatura,\ny sólo en vida más pura\nlos justos comprenderán\nque el amor salvó a don Juan\nal pie de la sepultura.\nCesad, cantos funerales;\n(Cesa la música y salmodia.)\ncallad, mortuorias campanas;\n(Dejan de tocar a muerto.)\nocupad, sombras livianas,\nvuestras urnas sepulcrales;\n(Vuelven los esqueletos a sus tumbas, que se cierran.)\nvolved a los pedestales\nanimadas esculturas;\n(Vuelven las estatuas a sus lugares.)\ny las celestes venturas\nen que los justos están,\nempiecen para don Juan\nen las mismas sepulturas.\n(Las flores se abren y dan paso a varios angelitos, que rodean a DOÑA\nINÉS y a DON JUAN, derramando sobre ellos flores y perfumes, y al son de\nuna música dulce y lejana, se ilumina el teatro con luz de aurora. DOÑA INÉS\ncae sobre un lecho de flores, que quedará a la vista, en lugar de su tumba, que\ndesaparece.)"}, {"type": "h", "text": "Escena IV"}, {"type": "v", "text": "DOÑA INÉS, DON JUAN y los ángeles."}, {"type": "h", "text": "Don Juan"}, {"type": "v", "text": "Clemente Dios, ¡gloria a Ti!\nMañana a los sevillanos\naterrará el creer que a manos\nde mis víctimas caí.\nMas es justo; quede aquí\nal universo notorio,\nque pues me abre el purgatorio\nun punto de penitencia,\nes el Dios de la clemencia\nel Dios de DON JUAN TENORIO.\n(Cae DON JUAN a los pies de DOÑA INÉS, y mueren ambos. De sus\nbocas salen sus almas, representadas en dos brillantes llamas que se pierden en\nel espacio al son de la música. Cae el telón.)\n¿Te gustó este libro?\nPara más e-Books GRATUITOS visita freeditorial.com/es"}]$lira$::jsonb, 378);

