insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('la-casa-de-bernarda-alba', 'La casa de Bernarda Alba', 'Federico García Lorca', 'Muere el marido y Bernarda ordena ocho años de luto encerradas. Cinco hijas, una casa y una sola puerta.', 'teatro', 12, 64, array['clásico', 'encierro', 'tragedia']::text[], true)
on conflict (id) do update set
  title = excluded.title, author = excluded.author,
  synopsis = excluded.synopsis, category = excluded.category,
  chapter_count = excluded.chapter_count,
  minutes_to_read = excluded.minutes_to_read,
  tags = excluded.tags, is_published = true;

insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 0, 'Parte 1 (1/12)', $lira$[{"type": "p", "text": "La casa de Bernarda Alba."}, {"type": "p", "text": "Drama de mujeres en los pueblos de España"}, {"type": "p", "text": "Personajes"}, {"type": "p", "text": "María Josefa, madre de Bernarda, 80"}, {"type": "p", "text": "Bernarda, 60 años."}, {"type": "p", "text": "años."}, {"type": "p", "text": "Angustias, (hija), 39 años. La Poncia, 60 años. Mujer 1"}, {"type": "p", "text": "Magdalena, (hija), 30 años. Criada, 50 años. Mujer 2"}, {"type": "p", "text": "Amelia, (hija), 27 años. Mendiga, con niña. Mujer 3"}, {"type": "p", "text": "Martirio, (hija), 24 años. Mujeres de luto. Mujer 4"}, {"type": "p", "text": "Adela, (hija), 20 años. Muchacha"}, {"type": "p", "text": "El poeta advierte que estos tres actos tienen la intención de un documental fotográfico. Acto primero"}, {"type": "p", "text": "Habitación blanquísima del interior de la casa de Bernarda. Muros gruesos. Puertas en arco con cortinas de yute rematadas con madroños y volantes. Sillas de anea. Cuadros con paisajes inverosímiles de ninfas o reyes de leyenda. Es verano. Un gran silencio umbroso se extiende por la escena. Al levantarse el telón está la escena sola. Se oyen doblar las campanas."}, {"type": "p", "text": "(Sale la Criada)"}, {"type": "p", "text": "Criada: Ya tengo el doble de esas campanas metido entre las sienes."}, {"type": "p", "text": "La Poncia: (Sale comiendo chorizo y pan) Llevan ya más de dos horas de gori-gori. Han venido curas de todos los pueblos. La iglesia está hermosa. En el primer responso se desmayó la Magdalena."}, {"type": "p", "text": "Criada: Es la que se queda más sola."}, {"type": "p", "text": "La Poncia: Era la única que quería al padre. ¡Ay! ¡Gracias a Dios que estamos solas un poquito! Yo he venido a comer."}, {"type": "p", "text": "Criada: ¡Si te viera Bernarda...!"}, {"type": "p", "text": "La Poncia: ¡Quisiera que ahora, que no come ella, que todas nos muriéramos de hambre! ¡Mandona! ¡Dominanta! ¡Pero se fastidia! Le he abierto la orza de chorizos. Criada: (Con tristeza, ansiosa) ¿Por qué no me das para mi niña, Poncia?"}, {"type": "p", "text": "La Poncia: Entra y llévate también un puñado de garbanzos. ¡Hoy no se dará cuenta! Voz (Dentro): ¡Bernarda!"}, {"type": "p", "text": "La Poncia: La vieja. ¿Está bien cerrada?"}, {"type": "p", "text": "Criada: Con dos vueltas de llave."}, {"type": "p", "text": "La Poncia: Pero debes poner también la tranca. Tiene unos dedos como cinco ganzúas. Voz: ¡Bernarda!"}, {"type": "p", "text": "La Poncia: (A voces) ¡Ya viene! (A la Criada) Limpia bien todo. Si Bernarda no ve relucientes las cosas me arrancará los pocos pelos que me quedan."}, {"type": "p", "text": "Criada: ¡Qué mujer!"}, {"type": "p", "text": "La Poncia: Tirana de todos los que la rodean. Es capaz de sentarse encima de tu corazón y ver cómo te mueres durante un año sin que se le cierre esa sonrisa fría que lleva en su maldita cara. ¡Limpia, limpia ese vidriado!"}, {"type": "p", "text": "Criada: Sangre en las manos tengo de fregarlo todo."}, {"type": "p", "text": "La Poncia: Ella, la más aseada; ella, la más decente; ella, la más alta. Buen descanso ganó su pobre marido."}, {"type": "p", "text": "(Cesan las campanas.)"}, {"type": "p", "text": "Criada: ¿Han venido todos sus parientes?"}, {"type": "p", "text": "La Poncia: Los de ella. La gente de él la odia. Vinieron a verlo muerto, y le hicieron la cruz."}, {"type": "p", "text": "Criada: ¿Hay bastantes sillas?"}, {"type": "p", "text": "La Poncia: Sobran. Que se sienten en el suelo. Desde que murió el padre de Bernarda no han vuelto a entrar las gentes bajo estos techos. Ella no quiere que la vean en su dominio. ¡Maldita sea!"}, {"type": "p", "text": "Criada: Contigo se portó bien."}, {"type": "p", "text": "La Poncia: Treinta años lavando sus sábanas; treinta años comiendo sus sobras; noches en vela cuando tose; días enteros mirando por la rendija para espiar a los vecinos y llevarle el cuento; vida sin secretos una con otra, y sin embargo, ¡maldita sea! ¡Mal dolor de clavo le pinche en los ojos!"}, {"type": "p", "text": "Criada: ¡Mujer!"}, {"type": "p", "text": "La Poncia: Pero yo soy buena perra; ladro cuando me lo dice y muerdo los talones de los que piden limosna cuando ella me azuza; mis hijos trabajan en sus tierras y ya están los dos casados, pero un día me hartaré."}, {"type": "p", "text": "Criada: Y ese día..."}, {"type": "p", "text": "La Poncia: Ese día me encerraré con ella en un cuarto y le estaré escupiendo un año entero. \"Bernarda, por esto, por aquello, por lo otro\", hasta ponerla como un lagarto machacado por los niños, que es lo que es ella y toda su parentela. Claro es que no le envidio la vida. La quedan cinco mujeres, cinco hijas feas, que quitando a Angustias, la mayor, que es la hija del primer marido y tiene dineros, las demás mucha puntilla bordada, muchas camisas de hilo, pero pan y uvas por toda herencia."}, {"type": "p", "text": "Criada: ¡Ya quisiera tener yo lo que ellas!"}, {"type": "p", "text": "La Poncia: Nosotras tenemos nuestras manos y un hoyo en la tierra de la verdad. Criada: Ésa es la única tierra que nos dejan a las que no tenemos nada."}, {"type": "p", "text": "La Poncia: (En la alacena) Este cristal tiene unas motas."}, {"type": "p", "text": "Criada: Ni con el jabón ni con bayeta se le quitan."}, {"type": "p", "text": "(Suenan las campanas)"}, {"type": "p", "text": "La Poncia: El último responso. Me voy a oírlo. A mí me gusta mucho cómo canta el párroco. En el \"Pater noster\" subió, subió, subió la voz que parecía un cántaro llenándose de agua poco a poco. ¡Claro es que al final dio un gallo, pero da gloria oírlo! Ahora que nadie como el antiguo sacristán, Tronchapinos. En la misa de mi madre, que esté en gloria, cantó. Retumbaban las paredes, y cuando decía amén era como si un lobo hubiese entrado en la iglesia. (Imitándolo) ¡Ameeeén! (Se echa a toser)"}, {"type": "p", "text": "Criada: Te vas a hacer el gaznate polvo."}, {"type": "p", "text": "La Poncia: ¡Otra cosa hacía polvo yo! (Sale riendo)"}, {"type": "p", "text": "(La Criada limpia. Suenan las campanas)"}, {"type": "p", "text": "Criada: (Llevando el canto) Tin, tin, tan. Tin, tin, tan. ¡Dios lo haya perdonado! Mendiga: (Con una niña) ¡Alabado sea Dios!"}, {"type": "p", "text": "Criada: Tin, tin, tan. ¡Que nos espere muchos años'. Tin, tin, tan."}, {"type": "p", "text": "Mendiga: (Fuerte con cierta irritación) ¡Alabado sea Dios!"}, {"type": "p", "text": "Criada: (Irritada) ¡Por siempre!"}, {"type": "p", "text": "Mendiga: Vengo por las sobras."}, {"type": "p", "text": "(Cesan las campanas)"}, {"type": "p", "text": "Criada: Por la puerta se va a la calle. Las sobras de hoy son para mí."}, {"type": "p", "text": "Mendiga: Mujer, tú tienes quien te gane. ¡Mi niña y yo estamos solas!"}, {"type": "p", "text": "Criada: También están solos los perros y viven."}, {"type": "p", "text": "Mendiga: Siempre me las dan."}, {"type": "p", "text": "Criada: Fuera de aquí. ¿Quién os dijo que entrarais? Ya me habéis dejado los pies señalados. (Se van. Limpia.) Suelos barnizados con aceite, alacenas, pedestales, camas de acero, para que traguemos quina las que vivimos en las chozas de tierra con un plato y una cuchara. ¡Ojalá que un día no quedáramos ni uno para contarlo! (Vuelven a sonar las campanas) Sí, sí, ¡vengan clamores! ¡venga caja con filos dorados y toallas de seda para llevarla!; ¡que lo mismo estarás tú que estaré yo! Fastídiate, Antonio María Benavides, tieso con tu traje de paño y tus botas enterizas. ¡Fastídiate! ¡Ya no volverás a levantarme las enaguas detrás de la puerta de tu corral! (Por el fondo, de dos en dos, empiezan a entrar mujeres de luto con pañuelos grandes, faldas y abanicos negros. Entran lentamente hasta llenar la escena) (Rompiendo a gritar) ¡Ay Antonio María Benavides, que ya no verás estas paredes, ni comerás el pan de esta casa! Yo fui la que más te quiso de las que te sirvieron. (Tirándose del cabello) ¿Y he de vivir yo después de verte marchar? ¿Y he de vivir?"}]$lira$::jsonb, 1141);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 1, 'Parte 1 (2/12)', $lira$[{"type": "p", "text": "(Terminan de entrar las doscientas mujeres y aparece Bernarda y sus cinco hijas) Bernarda: (A la Criada) ¡Silencio!"}, {"type": "p", "text": "Criada: (Llorando) ¡Bernarda!"}, {"type": "p", "text": "Bernarda: Menos gritos y más obras. Debías haber procurado que todo esto estuviera más limpio para recibir al duelo. Vete. No es éste tu lugar. (La Criada se va sollozando) Los pobres son como los animales. Parece como si estuvieran hechos de otras sustancias."}, {"type": "p", "text": "Mujer 1: Los pobres sienten también sus penas."}, {"type": "p", "text": "Bernarda: Pero las olvidan delante de un plato de garbanzos."}, {"type": "p", "text": "Muchacha 1: (Con timidez) Comer es necesario para vivir."}, {"type": "p", "text": "Bernarda: A tu edad no se habla delante de las personas mayores."}, {"type": "p", "text": "Mujer 1: Niña, cállate."}, {"type": "p", "text": "Bernarda: No he dejado que nadie me dé lecciones. Sentarse. (Se sientan. Pausa) (Fuerte) Magdalena, no llores. Si quieres llorar te metes debajo de la cama. ¿Me has oído?"}, {"type": "p", "text": "Mujer 2: (A Bernarda) ¿Habéis empezado los trabajos en la era?"}, {"type": "p", "text": "Bernarda: Ayer."}, {"type": "p", "text": "Mujer 3: Cae el sol como plomo."}, {"type": "p", "text": "Mujer 1: Hace años no he conocido calor igual."}, {"type": "p", "text": "(Pausa. Se abanican todas)"}, {"type": "p", "text": "Bernarda: ¿Está hecha la limonada?"}, {"type": "p", "text": "La Poncia: (Sale con una gran bandeja llena de jarritas blancas, que distribuye.) Sí, Bernarda."}, {"type": "p", "text": "Bernarda: Dale a los hombres."}, {"type": "p", "text": "La Poncia: Ya están tomando en el patio."}, {"type": "p", "text": "Bernarda: Que salgan por donde han entrado. No quiero que pasen por aquí."}, {"type": "p", "text": "Muchacha: (A Angustias) Pepe el Romano estaba con los hombres del duelo."}, {"type": "p", "text": "Angustias: Allí estaba."}, {"type": "p", "text": "Bernarda: Estaba su madre. Ella ha visto a su madre. A Pepe no lo ha visto ni ella ni yo."}, {"type": "p", "text": "Muchacha: Me pareció..."}, {"type": "p", "text": "Bernarda: Quien sí estaba era el viudo de Darajalí. Muy cerca de tu tía. A ése lo vimos todas."}, {"type": "p", "text": "Mujer 2: (Aparte y en baja voz) ¡Mala, más que mala!"}, {"type": "p", "text": "Mujer 3: (Aparte y en baja voz) ¡Lengua de cuchillo!"}, {"type": "p", "text": "Bernarda: Las mujeres en la iglesia no deben mirar más hombre que al oficiante, y a ése porque tiene faldas. Volver la cabeza es buscar el calor de la pana."}, {"type": "p", "text": "Mujer 1: (En voz baja) ¡Vieja lagarta recocida!"}, {"type": "p", "text": "La Poncia: (Entre dientes) ¡Sarmentosa por calentura de varón!"}, {"type": "p", "text": "Bernarda: (Dando un golpe de bastón en el suelo) ¡Alabado sea Dios!"}, {"type": "p", "text": "Todas: (Santiguándose) Sea por siempre bendito y alabado."}, {"type": "p", "text": "Bernarda:"}, {"type": "p", "text": "¡Descansa en paz con la santa"}, {"type": "p", "text": "compaña de cabecera!"}, {"type": "p", "text": "Todas:"}, {"type": "p", "text": "¡Descansa en paz!"}, {"type": "p", "text": "Bernarda:"}, {"type": "p", "text": "Con el ángel San Miguel"}, {"type": "p", "text": "y su espada justiciera"}, {"type": "p", "text": "Todas:"}, {"type": "p", "text": "¡Descansa en paz!"}, {"type": "p", "text": "Bernarda:"}, {"type": "p", "text": "Con la llave que todo lo abre"}, {"type": "p", "text": "y la mano que todo lo cierra."}, {"type": "p", "text": "Todas:"}, {"type": "p", "text": "¡Descansa en paz!"}, {"type": "p", "text": "Bernarda:"}, {"type": "p", "text": "Con los bienaventurados"}, {"type": "p", "text": "y las lucecitas del campo."}, {"type": "p", "text": "Todas:"}, {"type": "p", "text": "¡Descansa en paz!"}, {"type": "p", "text": "Bernarda:"}, {"type": "p", "text": "Con nuestra santa caridad"}, {"type": "p", "text": "y las almas de tierra y mar."}, {"type": "p", "text": "Todas:"}, {"type": "p", "text": "¡Descansa en paz!"}, {"type": "p", "text": "Bernarda: Concede el reposo a tu siervo Antonio María Benavides y dale la corona de tu santa gloria."}, {"type": "p", "text": "Todas:"}, {"type": "p", "text": "Amén."}, {"type": "p", "text": "Bernarda: (Se pone de pie y canta)"}, {"type": "p", "text": "\"Réquiem aeternam dona eis, Domine\"."}, {"type": "p", "text": "Todas: (De pie y cantando al modo gregoriano)"}, {"type": "p", "text": "\"Et lux perpetua luceat eis\"."}, {"type": "p", "text": "(Se santiguan)"}, {"type": "p", "text": "Mujer 1: Salud para rogar por su alma."}, {"type": "p", "text": "(Van desfilando)"}, {"type": "p", "text": "Mujer 3: No te faltará la hogaza de pan caliente."}, {"type": "p", "text": "Mujer 2: Ni el techo para tus hijas."}, {"type": "p", "text": "(Van desfilando todas por delante de Bernarda y saliendo. Sale Angustias por otra puerta, la que da al patio)"}, {"type": "p", "text": "Mujer 4: El mismo trigo de tu casamiento lo sigas disfrutando."}, {"type": "p", "text": "La Poncia: (Entrando con una bolsa) De parte de los hombres esta bolsa de dineros para responsos."}, {"type": "p", "text": "Bernarda: Dales las gracias y échales una copa de aguardiente."}, {"type": "p", "text": "Muchacha: (A Magdalena) Magdalena..."}, {"type": "p", "text": "Bernarda: (A Magdalena, que inicia el llanto) Chist. (Golpea con el bastón.) (Salen todas.) (A las que se han ido) ¡Andar a vuestras cuevas a criticar todo lo que habéis visto! Ojalá tardéis muchos años en pasar el arco de mi puerta."}, {"type": "p", "text": "La Poncia: No tendrás queja ninguna. Ha venido todo el pueblo."}, {"type": "p", "text": "Bernarda: Sí, para llenar mi casa con el sudor de sus refajos y el veneno de sus lenguas."}, {"type": "p", "text": "Amelia: ¡Madre, no hable usted así!"}, {"type": "p", "text": "Bernarda: Es así como se tiene que hablar en este maldito pueblo sin río, pueblo de pozos, donde siempre se bebe el agua con el miedo de que esté envenenada."}, {"type": "p", "text": "La Poncia: ¡Cómo han puesto la solería!"}, {"type": "p", "text": "Bernarda: Igual que si hubiera pasado por ella una manada de cabras. (La Poncia limpia el suelo) Niña, dame un abanico."}, {"type": "p", "text": "Amelia: Tome usted. (Le da un abanico redondo con flores rojas y verdes.)"}, {"type": "p", "text": "Bernarda: (Arrojando el abanico al suelo) ¿Es éste el abanico que se da a una viuda? Dame uno negro y aprende a respetar el luto de tu padre."}, {"type": "p", "text": "Martirio: Tome usted el mío."}, {"type": "p", "text": "Bernarda: ¿Y tú?"}, {"type": "p", "text": "Martirio: Yo no tengo calor."}, {"type": "p", "text": "Bernarda: Pues busca otro, que te hará falta. En ocho años que dure el luto no ha de entrar en esta casa el viento de la calle. Haceros cuenta que hemos tapiado con ladrillos puertas y ventanas. Así pasó en casa de mi padre y en casa de mi abuelo. Mientras, podéis empezar a bordaros el ajuar. En el arca tengo veinte piezas de hilo con el que podréis cortar sábanas y embozos. Magdalena puede bordarlas."}, {"type": "p", "text": "Magdalena: Lo mismo me da."}, {"type": "p", "text": "Adela: (Agria) Si no queréis bordarlas irán sin bordados. Así las tuyas lucirán más. Magdalena: Ni las mías ni las vuestras. Sé que yo no me voy a casar. Prefiero llevar sacos al molino. Todo menos estar sentada días y días dentro de esta sala oscura. Bernarda: Eso tiene ser mujer"}, {"type": "p", "text": "Magdalena: Malditas sean las mujeres."}, {"type": "p", "text": "Bernarda: Aquí se hace lo que yo mando. Ya no puedes ir con el cuento a tu padre. Hilo y aguja para las hembras. Látigo y mula para el varón. Eso tiene la gente que nace con posibles."}, {"type": "p", "text": "(Sale Adela.)"}, {"type": "p", "text": "Voz: ¡Bernarda!, ¡déjame salir!"}, {"type": "p", "text": "Bernarda: (En voz alta) ¡Dejadla ya! (Sale la Criada.)"}, {"type": "p", "text": "Criada: Me ha costado mucho trabajo sujetarla. A pesar de sus ochenta años tu madre es fuerte como un roble."}, {"type": "p", "text": "Bernarda: Tiene a quien parecérsele. Mi abuelo fue igual."}, {"type": "p", "text": "Criada: Tuve durante el duelo que taparle varias veces la boca con un costal vacío porque quería llamarte para que le dieras agua de fregar siquiera, para beber, y carne de perro, que es lo que ella dice que tú le das."}, {"type": "p", "text": "Martirio: ¡Tiene mala intención!"}, {"type": "p", "text": "Bernarda: (A la Criada.) Déjala que se desahogue en el patio."}, {"type": "p", "text": "Criada: Ha sacado del cofre sus anillos y los pendientes de amatistas, se los ha puesto y me ha dicho que se quiere casar."}]$lira$::jsonb, 1062);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 2, 'Parte 1 (3/12)', $lira$[{"type": "p", "text": "(Las hijas ríen.)"}, {"type": "p", "text": "Bernarda: Ve con ella y ten cuidado que no se acerque al pozo."}, {"type": "p", "text": "Criada: No tengas miedo que se tire."}, {"type": "p", "text": "Bernarda: No es por eso... Pero desde aquel sitio las vecinas pueden verla desde su ventana."}, {"type": "p", "text": "(Sale la Criada.)"}, {"type": "p", "text": "Martirio: Nos vamos a cambiar la ropa."}, {"type": "p", "text": "Bernarda: Sí, pero no el pañuelo de la cabeza. ( Entra Adela.) ¿Y Angustias? Adela: (Con retintín.) La he visto asomada a la rendija del portón. Los hombres se acababan de ir."}, {"type": "p", "text": "Bernarda: ¿Y tú a qué fuiste también al portón?"}, {"type": "p", "text": "Adela: Me llegué a ver si habían puesto las gallinas."}, {"type": "p", "text": "Bernarda: ¡Pero el duelo de los hombres habría salido ya!"}, {"type": "p", "text": "Adela: (Con intención) Todavía estaba un grupo parado por fuera."}, {"type": "p", "text": "Bernarda: (Furiosa) ¡Angustias! ¡Angustias!"}, {"type": "p", "text": "Angustias: (Entrando.) ¿Qué manda usted?"}, {"type": "p", "text": "Bernarda: ¿Qué mirabas y a quién?"}, {"type": "p", "text": "Angustias: A nadie."}, {"type": "p", "text": "Bernarda: ¿Es decente que una mujer de tu clase vaya con el anzuelo detrás de un hombre el día de la misa de su padre? ¡Contesta! ¿A quién mirabas?"}, {"type": "p", "text": "(Pausa.)"}, {"type": "p", "text": "Angustias: Yo..."}, {"type": "p", "text": "Bernarda: ¡Tú!"}, {"type": "p", "text": "Angustias: ¡A nadie!"}, {"type": "p", "text": "Bernarda: (Avanzando con el bastón) ¡Suave! ¡dulzarrona! (Le da)"}, {"type": "p", "text": "La Poncia: (Corriendo) ¡Bernarda, cálmate! (La sujeta) (Angustias llora.)"}, {"type": "p", "text": "Bernarda: ¡Fuera de aquí todas! (Salen)"}, {"type": "p", "text": "La Poncia: Ella lo ha hecho sin dar alcance a lo que hacía, que está francamente mal. ¡Ya me chocó a mí verla escabullirse hacia el patio! Luego estuvo detrás de una ventana oyendo la conversación que traían los hombres, que, como siempre, no se puede oír. Bernarda: ¡A eso vienen a los duelos! (Con curiosidad) ¿De qué hablaban?"}, {"type": "p", "text": "La Poncia: Hablaban de Paca la Roseta. Anoche ataron a su marido a un pesebre y a ella se la llevaron a la grupa del caballo hasta lo alto del olivar."}, {"type": "p", "text": "Bernarda: ¿Y ella?"}, {"type": "p", "text": "La Poncia: Ella, tan conforme. Dicen que iba con los pechos fuera y Maximiliano la llevaba cogida como si tocara la guitarra. ¡Un horror!"}, {"type": "p", "text": "Bernarda: ¿Y qué pasó?"}, {"type": "p", "text": "La Poncia: Lo que tenía que pasar. Volvieron casi de día. Paca la Roseta traía el pelo suelto y una corona de flores en la cabeza."}, {"type": "p", "text": "Bernarda: Es la única mujer mala que tenemos en el pueblo."}, {"type": "p", "text": "La Poncia: Porque no es de aquí. Es de muy lejos. Y los que fueron con ella son también hijos de forasteros. Los hombres de aquí no son capaces de eso."}, {"type": "p", "text": "Bernarda: No, pero les gusta verlo y comentarlo, y se chupan los dedos de que esto ocurra."}, {"type": "p", "text": "La Poncia: Contaban muchas cosas más."}, {"type": "p", "text": "Bernarda: (Mirando a un lado y a otro con cierto temor) ¿Cuáles?"}, {"type": "p", "text": "La Poncia: Me da vergüenza referirlas."}, {"type": "p", "text": "Bernarda: Y mi hija las oyó."}, {"type": "p", "text": "La Poncia: ¡Claro!"}, {"type": "p", "text": "Bernarda: Ésa sale a sus tías; blancas y untosas que ponían ojos de carnero al piropo de cualquier barberillo. ¡Cuánto hay que sufrir y luchar para hacer que las personas sean decentes y no tiren al monte demasiado!"}, {"type": "p", "text": "La Poncia: ¡Es que tus hijas están ya en edad de merecer! Demasiada poca guerra te dan. Angustias ya debe tener mucho más de los treinta."}, {"type": "p", "text": "Bernarda: Treinta y nueve justos."}, {"type": "p", "text": "La Poncia: Figúrate. Y no ha tenido nunca novio..."}, {"type": "p", "text": "Bernarda: (Furiosa) ¡No, no ha tenido novio ninguna, ni les hace falta! Pueden pasarse muy bien."}, {"type": "p", "text": "La Poncia: No he querido ofenderte."}, {"type": "p", "text": "Bernarda: No hay en cien leguas a la redonda quien se pueda acercar a ellas. Los hombres de aquí no son de su clase. ¿Es que quieres que las entregue a cualquier gañán? La Poncia: Debías haberte ido a otro pueblo."}, {"type": "p", "text": "Bernarda: Eso, ¡a venderlas!"}, {"type": "p", "text": "La Poncia: No, Bernarda, a cambiar... ¡Claro que en otros sitios ellas resultan las pobres!"}, {"type": "p", "text": "Bernarda: ¡Calla esa lengua atormentadora!"}, {"type": "p", "text": "La Poncia: Contigo no se puede hablar. ¿Tenemos o no tenemos confianza?"}, {"type": "p", "text": "Bernarda: No tenemos. Me sirves y te pago. ¡Nada más!"}, {"type": "p", "text": "Criada: (Entrando.) Ahí está don Arturo, que viene a arreglar las particiones. Bernarda: Vamos. (A la Criada.) Tú empieza a blanquear el patio. (A la Poncia.) Y tú ve guardando en el arca grande toda la ropa del muerto."}, {"type": "p", "text": "La Poncia: Algunas cosas las podríamos dar..."}, {"type": "p", "text": "Bernarda: Nada. ¡Ni un botón! ¡Ni el pañuelo con que le hemos tapado la cara! (Sale lentamente apoyada en el bastón y al salir vuelve la cabeza y mira a sus criadas. Las criadas salen después.)"}, {"type": "p", "text": "(Entran Amelia y Martirio.)"}, {"type": "p", "text": "Amelia: ¿Has tomado la medicina?"}, {"type": "p", "text": "Martirio: ¡Para lo que me va a servir!"}, {"type": "p", "text": "Amelia: Pero la has tomado."}, {"type": "p", "text": "Martirio: Yo hago las cosas sin fe, pero como un reloj."}, {"type": "p", "text": "Amelia: Desde que vino el médico nuevo estás más animada."}, {"type": "p", "text": "Martirio: Yo me siento lo mismo."}, {"type": "p", "text": "Amelia: ¿Te fijaste? Adelaida no estuvo en el duelo."}, {"type": "p", "text": "Martirio: Ya lo sabía. Su novio no la deja salir ni al tranco de la calle. Antes era alegre; ahora ni polvos echa en la cara."}, {"type": "p", "text": "Amelia: Ya no sabe una si es mejor tener novio o no."}, {"type": "p", "text": "Martirio: Es lo mismo."}, {"type": "p", "text": "Amelia: De todo tiene la culpa esta crítica que no nos deja vivir. Adelaida habrá pasado mal rato."}, {"type": "p", "text": "Martirio: Le tienen miedo a nuestra madre. Es la única que conoce la historia de su padre y el origen de sus tierras. Siempre que viene le tira puñaladas el asunto. Su padre mató en Cuba al marido de primera mujer para casarse con ella. Luego aquí la abandonó y se fue con otra que tenía una hija y luego tuvo relaciones con esta muchacha, la madre de Adelaida, y se casó con ella después de haber muerto loca la segunda mujer. Amelia: Y ese infame, ¿por qué no está en la cárcel?"}, {"type": "p", "text": "Martirio: Porque los hombres se tapan unos a otros las cosas de esta índole y nadie es capaz de delatar."}, {"type": "p", "text": "Amelia: Pero Adelaida no tiene culpa de esto."}, {"type": "p", "text": "Martirio: No, pero las cosas se repiten. Y veo que todo es una terrible repetición. Y ella tiene el mismo sino de su madre y de su abuela, mujeres las dos del que la engendró. Amelia: ¡Qué cosa más grande!"}, {"type": "p", "text": "Martirio: Es preferible no ver a un hombre nunca. Desde niña les tuve miedo. Los veía en el corral uncir los bueyes y levantar los costales de trigo entre voces y zapatazos, y siempre tuve miedo de crecer por temor de encontrarme de pronto abrazada por ellos. Dios me ha hecho débil y fea y los ha apartado definitivamente de mí."}, {"type": "p", "text": "Amelia: ¡Eso no digas! Enrique Humanes estuvo detrás de ti y le gustabas."}, {"type": "p", "text": "Martirio: ¡Invenciones de la gente! Una vez estuve en camisa detrás de la ventana hasta que fue de día, porque me avisó con la hija de su gañán que iba a venir, y no vino. Fue todo cosa de lenguas. Luego se casó con otra que tenía más que yo."}]$lira$::jsonb, 1110);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 3, 'Parte 1 (4/12)', $lira$[{"type": "p", "text": "Amelia: ¡Y fea como un demonio!"}, {"type": "p", "text": "Martirio: ¡Qué les importa a ellos la fealdad! A ellos les importa la tierra, las yuntas y una perra sumisa que les dé de comer."}, {"type": "p", "text": "Amelia: ¡Ay!"}, {"type": "p", "text": "(Entra Magdalena.)"}, {"type": "p", "text": "Magdalena: ¿Qué hacéis?"}, {"type": "p", "text": "Martirio: Aquí."}, {"type": "p", "text": "Amelia: ¿Y tú?"}, {"type": "p", "text": "Magdalena: Vengo de correr las cámaras. Por andar un poco. De ver los cuadros bordados en cañamazo de nuestra abuela, el perrito de lanas y el negro luchando con el león, que tanto nos gustaba de niñas. Aquélla era una época más alegre. Una boda duraba diez días y no se usaban las malas lenguas. Hoy hay más finura. Las novias se ponen velo blanco como en las poblaciones, y se bebe vino de botella, pero nos pudrimos por el qué dirán."}, {"type": "p", "text": "Martirio: ¡Sabe Dios lo que entonces pasaría!"}, {"type": "p", "text": "Amelia: (A Magdalena.) Llevas desabrochados los cordones de un zapato."}, {"type": "p", "text": "Magdalena: ¡Qué más da!"}, {"type": "p", "text": "Amelia: ¡Te los vas a pisar y te vas a caer!"}, {"type": "p", "text": "Magdalena: ¡Una menos!"}, {"type": "p", "text": "Martirio: ¿Y Adela?"}, {"type": "p", "text": "Magdalena: ¡Ah! Se ha puesto el traje verde que se hizo para estrenar el día de su cumpleaños, se ha ido al corral y ha comenzado a voces: \"¡Gallinas, gallinas, miradme!\" ¡Me he tenido que reír!"}, {"type": "p", "text": "Amelia: ¡Si la hubiera visto madre!"}, {"type": "p", "text": "Magdalena: ¡Pobrecilla! Es la más joven de nosotras y tiene ilusión. ¡Daría algo por verla feliz!"}, {"type": "p", "text": "(Pausa. Angustias cruza la escena con unas toallas en la mano.)"}, {"type": "p", "text": "Angustias: ¿Qué hora es?"}, {"type": "p", "text": "Magdalena: Ya deben ser las doce."}, {"type": "p", "text": "Angustias: ¿Tanto?"}, {"type": "p", "text": "Amelia: ¡Estarán al caer!"}, {"type": "p", "text": "(Sale Angustias.) Magdalena: (Con intención.) ¿Sabéis ya la cosa...? (Señalando a Angustias.) Amelia: No."}, {"type": "p", "text": "Magdalena: ¡Vamos!"}, {"type": "p", "text": "Martirio: ¡No sé a qué cosa te refieres...!"}, {"type": "p", "text": "Magdalena: Mejor que yo lo sabéis las dos. Siempre cabeza con cabeza como dos ovejitas, pero sin desahogaros con nadie. ¡Lo de Pepe el Romano!"}, {"type": "p", "text": "Martirio: ¡Ah!"}, {"type": "p", "text": "Magdalena: (Remedándola.) ¡Ah! Ya se comenta por el pueblo. Pepe el Romano viene a casarse con Angustias. Anoche estuvo rondando la casa y creo que pronto va a mandar un emisario."}, {"type": "p", "text": "Martirio: ¡Yo me alegro! Es buen hombre."}, {"type": "p", "text": "Amelia: Yo también. Angustias tiene buenas condiciones."}, {"type": "p", "text": "Magdalena: Ninguna de las dos os alegráis."}, {"type": "p", "text": "Martirio: ¡Magdalena! ¡Mujer!"}, {"type": "p", "text": "Magdalena: Si viniera por el tipo de Angustias, por Angustias como mujer, yo me alegraría, pero viene por el dinero. Aunque Angustias es nuestra hermana aquí estamos en familia y reconocemos que está vieja, enfermiza, y que siempre ha sido la que ha tenido menos méritos de todas nosotras, porque si con veinte años parecía un palo vestido, ¡qué será ahora que tiene cuarenta!"}, {"type": "p", "text": "Martirio: No hables así. La suerte viene a quien menos la aguarda."}, {"type": "p", "text": "Amelia: ¡Después de todo dice la verdad! Angustias tiene el dinero de su padre, es la única rica de la casa y por eso ahora, que nuestro padre ha muerto y ya se harán particiones, vienen por ella!"}, {"type": "p", "text": "Magdalena: Pepe el Romano tiene veinticinco años y es el mejor tipo de todos estos contornos. Lo natural sería que te pretendiera a ti, Amelia, o a nuestra Adela, que tiene veinte años, pero no que venga a buscar lo más oscuro de esta casa, a una mujer que, como su padre habla con la nariz."}, {"type": "p", "text": "Martirio: ¡Puede que a él le guste!"}, {"type": "p", "text": "Magdalena: ¡Nunca he podido resistir tu hipocresía!"}, {"type": "p", "text": "Martirio: ¡Dios nos valga!"}, {"type": "p", "text": "(Entra Adela.)"}, {"type": "p", "text": "Magdalena: ¿Te han visto ya las gallinas?"}, {"type": "p", "text": "Adela: ¿Y qué querías que hiciera?"}, {"type": "p", "text": "Amelia: ¡Si te ve nuestra madre te arrastra del pelo!"}, {"type": "p", "text": "Adela: Tenía mucha ilusión con el vestido. Pensaba ponérmelo el día que vamos a comer sandías a la noria. No hubiera habido otro igual."}, {"type": "p", "text": "Martirio: ¡Es un vestido precioso!"}, {"type": "p", "text": "Adela: Y me está muy bien. Es lo que mejor ha cortado Magdalena."}, {"type": "p", "text": "Magdalena: ¿Y las gallinas qué te han dicho?"}, {"type": "p", "text": "Adela: Regalarme unas cuantas pulgas que me han acribillado las piernas. (Ríen) Martirio: Lo que puedes hacer es teñirlo de negro."}, {"type": "p", "text": "Magdalena: Lo mejor que puedes hacer es regalárselo a Angustias para la boda con Pepe el Romano."}, {"type": "p", "text": "Adela: (Con emoción contenida.) ¡Pero Pepe el Romano...!"}, {"type": "p", "text": "Amelia: ¿No lo has oído decir?"}, {"type": "p", "text": "Adela: No."}, {"type": "p", "text": "Magdalena: ¡Pues ya lo sabes!"}, {"type": "p", "text": "Adela: ¡Pero si no puede ser!"}, {"type": "p", "text": "Magdalena: ¡El dinero lo puede todo!"}, {"type": "p", "text": "Adela: ¿Por eso ha salido detrás del duelo y estuvo mirando por el portón? (Pausa) Y ese hombre es capaz de..."}, {"type": "p", "text": "Magdalena: Es capaz de todo."}, {"type": "p", "text": "(Pausa)"}, {"type": "p", "text": "Martirio: ¿Qué piensas, Adela?"}, {"type": "p", "text": "Adela: Pienso que este luto me ha cogido en la peor época de mi vida para pasarlo. Magdalena: Ya te acostumbrarás."}, {"type": "p", "text": "Adela: (Rompiendo a llorar con ira) ¡No , no me acostumbraré! Yo no quiero estar encerrada. No quiero que se me pongan las carnes como a vosotras. ¡No quiero perder mi blancura en estas habitaciones! ¡Mañana me pondré mi vestido verde y me echaré a pasear por la calle! ¡Yo quiero salir!"}, {"type": "p", "text": "(Entra la Criada.)"}, {"type": "p", "text": "Magdalena: (Autoritaria.) ¡Adela!"}, {"type": "p", "text": "Criada: ¡La pobre! ¡Cuánto ha sentido a su padre! (Sale)"}, {"type": "p", "text": "Martirio: ¡Calla!"}, {"type": "p", "text": "Amelia: Lo que sea de una será de todas."}, {"type": "p", "text": "(Adela se calma.)"}, {"type": "p", "text": "Magdalena: Ha estado a punto de oírte la criada."}, {"type": "p", "text": "Criada: (Apareciendo.) Pepe el Romano viene por lo alto de la calle."}, {"type": "p", "text": "(Amelia, Martirio y Magdalena corren presurosas.)"}, {"type": "p", "text": "Magdalena: ¡Vamos a verlo!"}, {"type": "p", "text": "(Salen rápidas.)"}, {"type": "p", "text": "Criada: (A Adela.) ¿Tú no vas?"}, {"type": "p", "text": "Adela: No me importa."}, {"type": "p", "text": "Criada: Como dará la vuelta a la esquina, desde la ventana de tu cuarto se verá mejor. (Sale la Criada.)"}, {"type": "p", "text": "(Adela queda en escena dudando. Después de un instante se va también rápida hacia su habitación. Salen Bernarda y la Poncia.)"}, {"type": "p", "text": "Bernarda: ¡Malditas particiones!"}, {"type": "p", "text": "La Poncia: ¡Cuánto dinero le queda a Angustias!"}, {"type": "p", "text": "Bernarda: Sí."}, {"type": "p", "text": "La Poncia: Y a las otras, bastante menos."}, {"type": "p", "text": "Bernarda: Ya me lo has dicho tres veces y no te he querido replicar. Bastante menos, mucho menos. No me lo recuerdes más."}, {"type": "p", "text": "(Sale Angustias muy compuesta de cara.)"}, {"type": "p", "text": "Bernarda: ¡Angustias!"}, {"type": "p", "text": "Angustias: Madre."}, {"type": "p", "text": "Bernarda: ¿Pero has tenido valor de echarte polvos en la cara? ¿Has tenido valor de lavarte la cara el día de la misa de tu padre?"}, {"type": "p", "text": "Angustias: No era mi padre. El mío murió hace tiempo. ¿Es que ya no lo recuerda usted?"}, {"type": "p", "text": "Bernarda: ¡Más debes a este hombre, padre de tus hermanas, que al tuyo! Gracias a este hombre tienes colmada tu fortuna."}, {"type": "p", "text": "Angustias: ¡Eso lo teníamos que ver!"}, {"type": "p", "text": "Bernarda: ¡Aunque fuera por decencia! ¡Por respeto!"}, {"type": "p", "text": "Angustias: Madre, déjeme usted salir."}, {"type": "p", "text": "Bernarda: ¿Salir? Después que te hayas quitado esos polvos de la cara. ¡Suavona! ¡Yeyo! ¡Espejo de tus tías! (Le quita violentamente con su pañuelo los polvos) ¡Ahora vete!"}]$lira$::jsonb, 1070);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 4, 'Parte 1 (5/12)', $lira$[{"type": "p", "text": "La Poncia: ¡Bernarda, no seas tan inquisitiva!"}, {"type": "p", "text": "Bernarda: Aunque mi madre esté loca yo estoy con mis cinco sentidos y sé"}, {"type": "p", "text": "perfectamente lo que hago."}, {"type": "p", "text": "(Entran todas.)"}, {"type": "p", "text": "Magdalena: ¿Qué pasa?"}, {"type": "p", "text": "Bernarda: No pasa nada."}, {"type": "p", "text": "Magdalena: (A Angustias.) Si es que discutís por las particiones, tú, que eres la más rica, te puedes quedar con todo."}, {"type": "p", "text": "Angustias: ¡Guárdate la lengua en la madriguera!"}, {"type": "p", "text": "Bernarda: (Golpeando con el bastón en el suelo.) ¡No os hagáis ilusiones de que vais a poder conmigo. ¡Hasta que salga de esta casa con los pies adelante mandaré en lo mío y en lo vuestro!"}, {"type": "p", "text": "(Se oyen unas voces y entra en escena María Josefa, la madre de Bernarda, viejísima, ataviada con flores en la cabeza y en el pecho.)"}, {"type": "p", "text": "María Josefa: Bernarda, ¿dónde está mi mantilla? Nada de lo que tengo quiero que sea para vosotras, ni mis anillos, ni mi traje negro de moaré, porque ninguna de vosotras se va a casar. ¡Ninguna! ¡Bernarda, dame mi gargantilla de perlas!"}, {"type": "p", "text": "Bernarda: (A la Criada.) ¿Por qué la habéis dejado entrar?"}, {"type": "p", "text": "Criada: (Temblando.) ¡Se me escapó!"}, {"type": "p", "text": "María Josefa: Me escapé porque me quiero casar, porque quiero casarme con un varón hermoso de la orilla del mar, ya que aquí los hombres huyen de las mujeres. Bernarda: ¡Calle usted, madre!"}, {"type": "p", "text": "María Josefa: No, no callo. No quiero ver a estas mujeres solteras, rabiando por la boda, haciéndose polvo el corazón, y yo me quiero ir a mi pueblo. ¡Bernarda, yo quiero un varón para casarme y tener alegría!"}, {"type": "p", "text": "Bernarda: ¡Encerradla!"}, {"type": "p", "text": "María Josefa: ¡Déjame salir, Bernarda!"}, {"type": "p", "text": "(La Criada coge a María Josefa.)"}, {"type": "p", "text": "Bernarda: ¡Ayudarla vosotras!"}, {"type": "p", "text": "(Todas arrastran a la vieja.)"}, {"type": "p", "text": "María Josefa: ¡Quiero irme de aquí! ¡Bernarda! ¡A casarme a la orilla del mar, a la orilla del mar!"}, {"type": "p", "text": "Telón rápido."}, {"type": "p", "text": "Acto segundo Habitación blanca del interior de la casa de Bernarda. Las puertas de la izquierda dan a los dormitorios. Las hijas de Bernarda están sentadas en sillas bajas, cosiendo. Magdalena borda. Con ellas está la Poncia."}, {"type": "p", "text": "Angustias: Ya he cortado la tercer sábana."}, {"type": "p", "text": "Martirio: Le corresponde a Amelia."}, {"type": "p", "text": "Magdalena: Angustias, ¿pongo también las iniciales de Pepe?"}, {"type": "p", "text": "Angustias: (Seca.) No."}, {"type": "p", "text": "Magdalena: (A voces.) Adela, ¿no vienes?"}, {"type": "p", "text": "Amelia: Estará echada en la cama."}, {"type": "p", "text": "La Poncia: Ésa tiene algo. La encuentro sin sosiego, temblona, asustada, como si tuviera una lagartija entre los pechos."}, {"type": "p", "text": "Martirio: No tiene ni más ni menos que lo que tenemos todas."}, {"type": "p", "text": "Magdalena: Todas, menos Angustias."}, {"type": "p", "text": "Angustias: Yo me encuentro bien, y al que le duela que reviente."}, {"type": "p", "text": "Magdalena: Desde luego hay que reconocer que lo mejor que has tenido siempre ha sido el talle y la delicadeza."}, {"type": "p", "text": "Angustias: Afortunadamente pronto voy a salir de este infierno."}, {"type": "p", "text": "Magdalena: ¡A lo mejor no sales!"}, {"type": "p", "text": "Martirio: ¡Dejar esa conversación!"}, {"type": "p", "text": "Angustias: Y, además, ¡mas vale onza en el arca que ojos negros en la cara! Magdalena: Por un oído me entra y por otro me sale."}, {"type": "p", "text": "Amelia: (A la Poncia.) Abre la puerta del patio a ver si nos entra un poco el fresco. (La Poncia lo hace.)"}, {"type": "p", "text": "Martirio: Esta noche pasada no me podía quedar dormida del calor."}, {"type": "p", "text": "Amelia: ¡Yo tampoco!"}, {"type": "p", "text": "Magdalena: Yo me levanté a refrescarme. Había un nublo negro de tormenta y hasta cayeron algunas gotas."}, {"type": "p", "text": "La Poncia: Era la una de la madrugada y salía fuego de la tierra. También me levanté yo. Todavía estaba Angustias con Pepe en la ventana."}, {"type": "p", "text": "Magdalena: (Con ironía.) ¿Tan tarde? ¿A qué hora se fue?"}, {"type": "p", "text": "Angustias: Magdalena, ¿a qué preguntas, si lo viste?"}, {"type": "p", "text": "Amelia: Se iría a eso de la una y media."}, {"type": "p", "text": "Angustias: Sí. ¿Tú por qué lo sabes?"}, {"type": "p", "text": "Amelia: Lo sentí toser y oí los pasos de su jaca."}, {"type": "p", "text": "La Poncia: ¡Pero si yo lo sentí marchar a eso de las cuatro!"}, {"type": "p", "text": "Angustias: ¡No sería él!"}, {"type": "p", "text": "La Poncia: ¡Estoy segura!"}, {"type": "p", "text": "Amelia: A mí también me pareció..."}, {"type": "p", "text": "Magdalena: ¡Qué cosa más rara!"}, {"type": "p", "text": "(Pausa.) La Poncia: Oye, Angustias, ¿qué fue lo que te dijo la primera vez que se acercó a tu ventana?"}, {"type": "p", "text": "Angustias: Nada. ¡Qué me iba a decir? Cosas de conversación."}, {"type": "p", "text": "Martirio: Verdaderamente es raro que dos personas que no se conocen se vean de pronto en una reja y ya novios."}, {"type": "p", "text": "Angustias: Pues a mí no me chocó."}, {"type": "p", "text": "Amelia: A mí me daría no sé qué."}, {"type": "p", "text": "Angustias: No, porque cuando un hombre se acerca a una reja ya sabe por los que van y vienen, llevan y traen, que se le va a decir que sí."}, {"type": "p", "text": "Martirio: Bueno, pero él te lo tendría que decir."}, {"type": "p", "text": "Angustias: ¡Claro!"}, {"type": "p", "text": "Amelia: (Curiosa.) ¿Y cómo te lo dijo?"}, {"type": "p", "text": "Angustias: Pues, nada: \"Ya sabes que ando detrás de ti, necesito una mujer buena, modosa, y ésa eres tú, si me das la conformidad.\""}, {"type": "p", "text": "Amelia: ¡A mí me da vergüenza de estas cosas!"}, {"type": "p", "text": "Angustias: Y a mí, ¡pero hay que pasarlas!"}, {"type": "p", "text": "La Poncia: ¿Y habló más?"}, {"type": "p", "text": "Angustias: Sí, siempre habló él."}, {"type": "p", "text": "Martirio: ¿Y tú?"}, {"type": "p", "text": "Angustias: Yo no hubiera podido. Casi se me salía el corazón por la boca. Era la primera vez que estaba sola de noche con un hombre."}, {"type": "p", "text": "Magdalena: Y un hombre tan guapo."}, {"type": "p", "text": "Angustias: No tiene mal tipo."}, {"type": "p", "text": "La Poncia: Esas cosas pasan entre personas ya un poco instruidas, que hablan y dicen y mueven la mano... La primera vez que mi marido Evaristo el Colorín vino a mi ventana... ¡Ja, ja, ja!"}, {"type": "p", "text": "Amelia: ¿Qué pasó?"}, {"type": "p", "text": "La Poncia: Era muy oscuro. Lo vi acercarse y, al llegar, me dijo: \"Buenas noches.\" \"Buenas noches\", le dije yo, y nos quedamos callados más de media hora. Me corría el sudor por todo el cuerpo. Entonces Evaristo se acercó, se acercó que se quería meter por los hierros, y dijo con voz muy baja: \"¡Ven que te tiente!\""}, {"type": "p", "text": "(Ríen todas. Amelia se levanta corriendo y espía por una puerta.)"}, {"type": "p", "text": "Amelia: ¡Ay! Creí que llegaba nuestra madre."}, {"type": "p", "text": "Magdalena: ¡Buenas nos hubiera puesto! (Siguen riendo.)"}, {"type": "p", "text": "Amelia: Chisst... ¡Que nos va a oír!"}, {"type": "p", "text": "La Poncia: Luego se portó bien. En vez de darle por otra cosa, le dio por criar colorines hasta que murió. A vosotras, que sois solteras, os conviene saber de todos modos que el hombre a los quince días de boda deja la cama por la mesa, y luego la mesa por la tabernilla. Y la que no se conforma se pudre llorando en un rincón."}, {"type": "p", "text": "Amelia: Tú te conformaste."}, {"type": "p", "text": "La Poncia: ¡Yo pude con él!"}, {"type": "p", "text": "Martirio: ¿Es verdad que le pegaste algunas veces?"}, {"type": "p", "text": "La Poncia: Sí, y por poco lo dejo tuerto."}, {"type": "p", "text": "Magdalena: ¡Así debían ser todas las mujeres!"}]$lira$::jsonb, 1067);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 5, 'Parte 1 (6/12)', $lira$[{"type": "p", "text": "La Poncia: Yo tengo la escuela de tu madre. Un día me dijo no sé qué cosa y le maté todos los colorines con la mano del almirez. (Ríen)"}, {"type": "p", "text": "Magdalena: Adela, niña, no te pierdas esto."}, {"type": "p", "text": "Amelia: Adela. (Pausa.)"}, {"type": "p", "text": "Magdalena: ¡Voy a ver! (Entra.)"}, {"type": "p", "text": "La Poncia: ¡Esa niña está mala!"}, {"type": "p", "text": "Martirio: Claro, ¡no duerme apenas!"}, {"type": "p", "text": "La Poncia: Pues, ¿qué hace?"}, {"type": "p", "text": "Martirio: ¡Yo qué sé lo que hace!"}, {"type": "p", "text": "La Poncia: Mejor lo sabrás tú que yo, que duermes pared por medio."}, {"type": "p", "text": "Angustias: La envidia la come."}, {"type": "p", "text": "Amelia: No exageres."}, {"type": "p", "text": "Angustias: Se lo noto en los ojos. Se le está poniendo mirar de loca."}, {"type": "p", "text": "Martirio: No habléis de locos. Aquí es el único sitio donde no se puede pronunciar esta palabra."}, {"type": "p", "text": "(Sale Magdalena con Adela.)"}, {"type": "p", "text": "Magdalena: Pues, ¿no estabas dormida?"}, {"type": "p", "text": "Adela: Tengo mal cuerpo."}, {"type": "p", "text": "Martirio: (Con intención.) ¿Es que no has dormido bien esta noche?"}, {"type": "p", "text": "Adela: Sí."}, {"type": "p", "text": "Martirio: ¿Entonces?"}, {"type": "p", "text": "Adela: (Fuerte.) ¡Déjame ya! ¡Durmiendo o velando, no tienes por qué meterte en lo mío! ¡Yo hago con mi cuerpo lo que me parece!"}, {"type": "p", "text": "Martirio: ¡Sólo es interés por ti!"}, {"type": "p", "text": "Adela: Interés o inquisición. ¿No estabais cosiendo? Pues seguir. ¡Quisiera ser invisible, pasar por las habitaciones sin que me preguntarais dónde voy!"}, {"type": "p", "text": "Criada: (Entra.) Bernarda os llama. Está el hombre de los encajes. (Salen.) (Al salir, Martirio mira fijamente a Adela.)"}, {"type": "p", "text": "Adela: ¡No me mires más! Si quieres te daré mis ojos, que son frescos, y mis espaldas, para que te compongas la joroba que tienes, pero vuelve la cabeza cuando yo pase. (Se va Martirio.)"}, {"type": "p", "text": "La Poncia: ¡Adela, que es tu hermana, y además la que más te quiere!"}, {"type": "p", "text": "Adela: Me sigue a todos lados. A veces se asoma a mi cuarto para ver si duermo. No me deja respirar. Y siempre: \"¡Qué lástima de cara! ¡Qué lástima de cuerpo, que no va a ser para nadie!\" ¡Y eso no! Mi cuerpo será de quien yo quiera!"}, {"type": "p", "text": "La Poncia: (Con intención y en voz baja.) De Pepe el Romano, ¿no es eso?"}, {"type": "p", "text": "Adela: (Sobrecogida.) ¿Qué dices?"}, {"type": "p", "text": "La Poncia: ¡Lo que digo, Adela!"}, {"type": "p", "text": "Adela: ¡Calla!"}, {"type": "p", "text": "La Poncia: (Alto.) ¿Crees que no me he fijado?"}, {"type": "p", "text": "Adela: ¡Baja la voz!"}, {"type": "p", "text": "La Poncia: ¡Mata esos pensamientos!"}, {"type": "p", "text": "Adela: ¿Qué sabes tú?"}, {"type": "p", "text": "La Poncia: Las viejas vemos a través de las paredes. ¿Dónde vas de noche cuando te levantas?"}, {"type": "p", "text": "Adela: ¡Ciega debías estar!"}, {"type": "p", "text": "La Poncia: Con la cabeza y las manos llenas de ojos cuando se trata de lo que se trata. Por mucho que pienso no sé lo que te propones. ¿Por qué te pusiste casi desnuda con la luz encendida y la ventana abierta al pasar Pepe el segundo día que vino a hablar con tu hermana?"}, {"type": "p", "text": "Adela: ¡Eso no es verdad!"}, {"type": "p", "text": "La Poncia: ¡No seas como los niños chicos! Deja en paz a tu hermana y si Pepe el Romano te gusta te aguantas. (Adela llora.) Además, ¿quién dice que no te puedas casar con él? Tu hermana Angustias es una enferma. Ésa no resiste el primer parto. Es estrecha de cintura, vieja, y con mi conocimiento te digo que se morirá. Entonces Pepe hará lo que hacen todos los viudos de esta tierra: se casará con la más joven, la más hermosa, y ésa eres tú. Alimenta esa esperanza, olvídalo. Lo que quieras, pero no vayas contra la ley de Dios."}, {"type": "p", "text": "Adela: ¡Calla!"}, {"type": "p", "text": "La Poncia: ¡No callo!"}, {"type": "p", "text": "Adela: Métete en tus cosas, ¡oledora! ¡pérfida!"}, {"type": "p", "text": "La Poncia: ¡Sombra tuya he de ser!"}, {"type": "p", "text": "Adela: En vez de limpiar la casa y acostarte para rezar a tus muertos, buscas como una vieja marrana asuntos de hombres y mujeres para babosear en ellos."}, {"type": "p", "text": "La Poncia: ¡Velo! Para que las gentes no escupan al pasar por esta puerta."}, {"type": "p", "text": "Adela: ¡Qué cariño tan grande te ha entrado de pronto por mi hermana!"}, {"type": "p", "text": "La Poncia: No os tengo ley a ninguna, pero quiero vivir en casa decente. ¡No quiero mancharme de vieja!"}, {"type": "p", "text": "Adela: Es inútil tu consejo. Ya es tarde. No por encima de ti, que eres una criada, por encima de mi madre saltaría para apagarme este fuego que tengo levantado por piernas y boca. ¿ Qué puedes decir de mí? Que me encierro en mi cuarto y no abro la puerta? ¿Que no duermo? ¡Soy más lista que tú! Mira a ver si puedes agarrar la liebre con tus manos."}, {"type": "p", "text": "La Poncia: No me desafíes. ¡Adela, no me desafíes! Porque yo puedo dar voces, encender luces y hacer que toquen las campanas."}, {"type": "p", "text": "Adela: Trae cuatro mil bengalas amarillas y ponlas en las bardas del corral. Nadie podrá evitar que suceda lo que tiene que suceder."}, {"type": "p", "text": "La Poncia: ¡Tanto te gusta ese hombre!"}, {"type": "p", "text": "Adela: ¡Tanto! Mirando sus ojos me parece que bebo su sangre lentamente."}, {"type": "p", "text": "La Poncia: Yo no te puedo oír."}, {"type": "p", "text": "Adela: ¡Pues me oirás! Te he tenido miedo. ¡Pero ya soy más fuerte que tú!"}, {"type": "p", "text": "(Entra Angustias.)"}, {"type": "p", "text": "Angustias: ¡Siempre discutiendo!"}, {"type": "p", "text": "La Poncia: Claro, se empeña en que, con el calor que hace, vaya a traerle no sé qué cosa de la tienda."}, {"type": "p", "text": "Angustias: ¿Me compraste el bote de esencia?"}, {"type": "p", "text": "La Poncia: El más caro. Y los polvos. En la mesa de tu cuarto los he puesto. (Sale Angustias.)"}, {"type": "p", "text": "Adela: ¡Y chitón!"}, {"type": "p", "text": "La Poncia: ¡Lo veremos!"}, {"type": "p", "text": "(Entran Martirio, Amelia y Magdalena)"}, {"type": "p", "text": "Magdalena: (A Adela) ¿Has visto los encajes?"}, {"type": "p", "text": "Amelia: Los de Angustias para sus sábanas de novia son preciosos."}, {"type": "p", "text": "Adela: (A Martirio, que trae unos encajes) ¿Y éstos?"}, {"type": "p", "text": "Martirio: Son para mí. Para una camisa."}, {"type": "p", "text": "Adela: (Con sarcasmo.) ¡Se necesita buen humor!"}, {"type": "p", "text": "Martirio: (Con intención) Para verlos yo. No necesito lucirme ante nadie."}, {"type": "p", "text": "La Poncia: Nadie la ve a una en camisa."}, {"type": "p", "text": "Martirio: (Con intención y mirando a Adela.) ¡A veces! Pero me encanta la ropa interior. Si fuera rica la tendría de holanda. Es uno de los pocos gustos que me quedan. La Poncia: Estos encajes son preciosos para las gorras de niño, para mantehuelos de cristianar. Yo nunca pude usarlos en los míos. A ver si ahora Angustias los usa en los suyos. Como le dé por tener crías vais a estar cosiendo mañana y tarde."}, {"type": "p", "text": "Magdalena: Yo no pienso dar una puntada."}, {"type": "p", "text": "Amelia: Y mucho menos cuidar niños ajenos. Mira tú cómo están las vecinas del callejón, sacrificadas por cuatro monigotes."}, {"type": "p", "text": "La Poncia: Ésas están mejor que vosotras. ¡Siquiera allí se ríe y se oyen porrazos! Martirio: Pues vete a servir con ellas."}, {"type": "p", "text": "La Poncia: No. ¡Ya me ha tocado en suerte este convento!"}, {"type": "p", "text": "(Se oyen unos campanillos lejanos, como a través de varios muros.)"}]$lira$::jsonb, 1069);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 6, 'Parte 1 (7/12)', $lira$[{"type": "p", "text": "Magdalena: Son los hombres que vuelven al trabajo."}, {"type": "p", "text": "La Poncia: Hace un minuto dieron las tres."}, {"type": "p", "text": "Martirio: ¡Con este sol!"}, {"type": "p", "text": "Adela: (Sentándose) ¡Ay, quién pudiera salir también a los campos!"}, {"type": "p", "text": "Magdalena: (Sentándose) ¡Cada clase tiene que hacer lo suyo!"}, {"type": "p", "text": "Martirio: (Sentándose) ¡Así es!"}, {"type": "p", "text": "Amelia: (Sentándose) ¡Ay!"}, {"type": "p", "text": "La Poncia: No hay alegría como la de los campos en esta época. Ayer de mañana llegaron los segadores. Cuarenta o cincuenta buenos mozos."}, {"type": "p", "text": "Magdalena: ¿De dónde son este año?"}, {"type": "p", "text": "La Poncia: De muy lejos. Vinieron de los montes. ¡Alegres! ¡Como árboles quemados! ¡Dando voces y arrojando piedras! Anoche llegó al pueblo una mujer vestida de lentejuelas y que bailaba con un acordeón, y quince de ellos la contrataron para llevársela al olivar. Yo los vi de lejos. El que la contrataba era un muchacho de ojos verdes, apretado como una gavilla de trigo."}, {"type": "p", "text": "Amelia: ¿Es eso cierto?"}, {"type": "p", "text": "Adela: ¡Pero es posible!"}, {"type": "p", "text": "La Poncia: Hace años vino otra de éstas y yo misma di dinero a mi hijo mayor para que fuera. Los hombres necesitan estas cosas."}, {"type": "p", "text": "Adela: Se les perdona todo."}, {"type": "p", "text": "Amelia: Nacer mujer es el mayor castigo."}, {"type": "p", "text": "Magdalena: Y ni nuestros ojos siquiera nos pertenecen."}, {"type": "p", "text": "(Se oye un canto lejano que se va acercando.)"}, {"type": "p", "text": "La Poncia: Son ellos. Traen unos cantos preciosos."}, {"type": "p", "text": "Amelia: Ahora salen a segar."}, {"type": "p", "text": "Coro:"}, {"type": "p", "text": "Ya salen los segadores"}, {"type": "p", "text": "en busca de las espigas;"}, {"type": "p", "text": "se llevan los corazones"}, {"type": "p", "text": "de las muchachas que miran."}, {"type": "p", "text": "(Se oyen panderos y carrañacas. Pausa. Todas oyen en un silencio traspasado por el sol.)"}, {"type": "p", "text": "Amelia: ¡Y no les importa el calor!"}, {"type": "p", "text": "Martirio: Siegan entre llamaradas."}, {"type": "p", "text": "Adela: Me gustaría segar para ir y venir. Así se olvida lo que nos muerde."}, {"type": "p", "text": "Martirio: ¿Qué tienes tú que olvidar?"}, {"type": "p", "text": "Adela: Cada una sabe sus cosas."}, {"type": "p", "text": "Martirio: (Profunda.) ¡Cada una!"}, {"type": "p", "text": "La Poncia: ¡Callar! ¡Callar!"}, {"type": "p", "text": "Coro: (Muy lejano.)"}, {"type": "p", "text": "Abrir puertas y ventanas"}, {"type": "p", "text": "las que vivís en el pueblo;"}, {"type": "p", "text": "el segador pide rosas"}, {"type": "p", "text": "para adornar su sombrero."}, {"type": "p", "text": "La Poncia: ¡Qué canto!"}, {"type": "p", "text": "Martirio: (Con nostalgia.)"}, {"type": "p", "text": "Abrir puertas y ventanas"}, {"type": "p", "text": "las que vivís en el pueblo..."}, {"type": "p", "text": "Adela: (Con pasión.)"}, {"type": "p", "text": "... el segador pide rosas"}, {"type": "p", "text": "para adornar su sombrero."}, {"type": "p", "text": "(Se va alejando el cantar.)"}, {"type": "p", "text": "La Poncia: Ahora dan la vuelta a la esquina."}, {"type": "p", "text": "Adela: Vamos a verlos por la ventana de mi cuarto."}, {"type": "p", "text": "La Poncia: Tened cuidado con no entreabrirla mucho, porque son capaces de dar un empujón para ver quién mira."}, {"type": "p", "text": "(Se van las tres. Martirio queda sentada en la silla baja con la cabeza entre las manos.) Amelia: (Acercándose.) ¿Qué te pasa?"}, {"type": "p", "text": "Martirio: Me sienta mal el calor."}, {"type": "p", "text": "Amelia: ¿No es más que eso?"}, {"type": "p", "text": "Martirio: Estoy deseando que llegue noviembre, los días de lluvia, la escarcha; todo lo que no sea este verano interminable."}, {"type": "p", "text": "Amelia: Ya pasará y volverá otra vez."}, {"type": "p", "text": "Martirio: ¡Claro! (Pausa.) ¿A qué hora te dormiste anoche?"}, {"type": "p", "text": "Amelia: No sé. Yo duermo como un tronco. ¿Por qué?"}, {"type": "p", "text": "Martirio: Por nada, pero me pareció oír gente en el corral."}, {"type": "p", "text": "Amelia: ¿Sí?"}, {"type": "p", "text": "Martirio: Muy tarde."}, {"type": "p", "text": "Amelia: ¿Y no tuviste miedo?"}, {"type": "p", "text": "Martirio: No. Ya lo he oído otras noches."}, {"type": "p", "text": "Amelia: Debíamos tener cuidado. ¿No serían los gañanes?"}, {"type": "p", "text": "Martirio: Los gañanes llegan a las seis."}, {"type": "p", "text": "Amelia: Quizá una mulilla sin desbravar."}, {"type": "p", "text": "Martirio: (Entre dientes y llena de segunda intención.) ¡Eso, eso!, una mulilla sin desbravar."}, {"type": "p", "text": "Amelia: ¡Hay que prevenir!"}, {"type": "p", "text": "Martirio: ¡No, no! No digas nada. Puede ser un barrunto mío."}, {"type": "p", "text": "Amelia: Quizá."}, {"type": "p", "text": "(Pausa. Amelia inicia el mutis.)"}, {"type": "p", "text": "Martirio: Amelia."}, {"type": "p", "text": "Amelia: (En la puerta.) ¿Qué?"}, {"type": "p", "text": "(Pausa.)"}, {"type": "p", "text": "Martirio: Nada."}, {"type": "p", "text": "(Pausa.)"}, {"type": "p", "text": "Amelia: ¿Por qué me llamaste?"}, {"type": "p", "text": "(Pausa)"}, {"type": "p", "text": "Martirio: Se me escapó. Fue sin darme cuenta."}, {"type": "p", "text": "(Pausa)"}, {"type": "p", "text": "Amelia: Acuéstate un poco."}, {"type": "p", "text": "Angustias: (Entrando furiosa en escena, de modo que haya un gran contraste con los silencios anteriores.) ¿Dónde está el retrato de Pepe que tenía yo debajo de mi almohada? ¿Quién de vosotras lo tiene?"}, {"type": "p", "text": "Martirio: Ninguna."}, {"type": "p", "text": "Amelia: Ni que Pepe fuera un San Bartolomé de plata."}, {"type": "p", "text": "Angustias: ¿Dónde está el retrato?"}, {"type": "p", "text": "(Entran La Poncia, Magdalena y Adela.)"}, {"type": "p", "text": "Adela: ¿Qué retrato?"}, {"type": "p", "text": "Angustias: Una de vosotras me lo ha escondido."}, {"type": "p", "text": "Magdalena: ¿Tienes la desvergüenza de decir esto?"}, {"type": "p", "text": "Angustias: Estaba en mi cuarto y no está."}, {"type": "p", "text": "Martirio: ¿Y no se habrá escapado a medianoche al corral? A Pepe le gusta andar con la luna."}, {"type": "p", "text": "Angustias: ¡No me gastes bromas! Cuando venga se lo contaré."}, {"type": "p", "text": "La Poncia: ¡Eso, no! ¡Porque aparecerá! (Mirando Adela.)"}, {"type": "p", "text": "Angustias: ¡Me gustaría saber cuál de vosotras lo tiene!"}, {"type": "p", "text": "Adela: (Mirando a Martirio.) ¡Alguna! ¡Todas, menos yo!"}, {"type": "p", "text": "Martirio: (Con intención.) ¡Desde luego!"}, {"type": "p", "text": "Bernarda: (Entrando con su bastón.) ¿Qué escándalo es éste en mi casa y con el silencio del peso del calor? Estarán las vecinas con el oído pegado a los tabiques. Angustias: Me han quitado el retrato de mi novio."}, {"type": "p", "text": "Bernarda: (Fiera.) ¿Quién? ¿Quién?"}, {"type": "p", "text": "Angustias: ¡Éstas!"}, {"type": "p", "text": "Bernarda: ¿Cuál de vosotras? (Silencio.) ¡Contestarme! (Silencio. A Poncia.) Registra los cuartos, mira por las camas. Esto tiene no ataros más cortas. ¡Pero me vais a soñar! (A Angustias.) ¿Estás segura?"}, {"type": "p", "text": "Angustias: Sí."}, {"type": "p", "text": "Bernarda: ¿Lo has buscado bien?"}, {"type": "p", "text": "Angustias: Sí, madre."}, {"type": "p", "text": "(Todas están en medio de un embarazoso silencio.)"}, {"type": "p", "text": "Bernarda: Me hacéis al final de mi vida beber el veneno más amargo que una madre puede resistir. (A Poncia.) ¿No lo encuentras?"}, {"type": "p", "text": "La Poncia: (Saliendo.) Aquí está."}, {"type": "p", "text": "Bernarda: ¿Dónde lo has encontrado?"}, {"type": "p", "text": "La Poncia: Estaba..."}, {"type": "p", "text": "Bernarda: Dilo sin temor."}, {"type": "p", "text": "La Poncia: (Extrañada.) Entre las sábanas de la cama de Martirio."}, {"type": "p", "text": "Bernarda: (A Martirio.) ¿Es verdad?"}, {"type": "p", "text": "Martirio: ¡Es verdad!"}, {"type": "p", "text": "Bernarda: (Avanzando y golpeándola con el bastón.) ¡Mala puñalada te den, mosca muerta! ¡Sembradura de vidrios!"}, {"type": "p", "text": "Martirio: (Fiera.) ¡No me pegue usted, madre!"}, {"type": "p", "text": "Bernarda: ¡Todo lo que quiera!"}, {"type": "p", "text": "Martirio: ¡Si yo la dejo! ¿Lo oye? ¡Retírese usted!"}, {"type": "p", "text": "La Poncia: No faltes a tu madre."}, {"type": "p", "text": "Angustias: (Cogiendo a Bernarda.) Déjela. ¡Por favor!"}, {"type": "p", "text": "Bernarda: Ni lágrimas te quedan en esos ojos."}, {"type": "p", "text": "Martirio: No voy a llorar para darle gusto."}, {"type": "p", "text": "Bernarda: ¿Por qué has cogido el retrato?"}, {"type": "p", "text": "Martirio: ¿Es que yo no puedo gastar una broma a mi hermana? ¿Para qué otra cosa lo iba a querer?"}, {"type": "p", "text": "Adela: (Saltando llena de celos.) No ha sido broma, que tú no has gustado nunca de juegos. Ha sido otra cosa que te reventaba el pecho por querer salir. Dilo ya claramente. Martirio: ¡Calla y no me hagas hablar, que si hablo se van a juntar las paredes unas con otras de vergüenza!"}, {"type": "p", "text": "Adela: ¡La mala lengua no tiene fin para inventar!"}, {"type": "p", "text": "Bernarda: ¡Adela!"}, {"type": "p", "text": "Magdalena: Estáis locas."}, {"type": "p", "text": "Amelia: Y nos apedreáis con malos pensamientos."}, {"type": "p", "text": "Martirio: Otras hacen cosas más malas."}, {"type": "p", "text": "Adela: Hasta que se pongan en cueros de una vez y se las lleve el río."}]$lira$::jsonb, 1068);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 7, 'Parte 1 (8/12)', $lira$[{"type": "p", "text": "Bernarda: ¡Perversa!"}, {"type": "p", "text": "Angustias: Yo no tengo la culpa de que Pepe el Romano se haya fijado en mí. Adela: ¡Por tus dineros!"}, {"type": "p", "text": "Angustias: ¡Madre!"}, {"type": "p", "text": "Bernarda: ¡Silencio!"}, {"type": "p", "text": "Martirio: Por tus marjales y tus arboledas."}, {"type": "p", "text": "Magdalena: ¡Eso es lo justo!"}, {"type": "p", "text": "Bernarda: ¡Silencio digo! Yo veía la tormenta venir, pero no creía que estallara tan pronto. ¡Ay, qué pedrisco de odio habéis echado sobre mi corazón! Pero todavía no soy anciana y tengo cinco cadenas para vosotras y esta casa levantada por mi padre para que ni las hierbas se enteren de mi desolación. ¡Fuera de aquí! (Salen. Bernarda se sienta desolada. La Poncia está de pie arrimada a los muros. Bernarda reacciona, da un golpe en el suelo y dice:) ¡Tendré que sentarles la mano! Bernarda, ¡acuérdate que ésta es tu obligación!"}, {"type": "p", "text": "La Poncia: ¿Puedo hablar?"}, {"type": "p", "text": "Bernarda: Habla. Siento que hayas oído. Nunca está bien una extraña en el centro de la familia."}, {"type": "p", "text": "La Poncia: Lo visto, visto está."}, {"type": "p", "text": "Bernarda: Angustias tiene que casarse en seguida."}, {"type": "p", "text": "La Poncia: Hay que retirarla de aquí."}, {"type": "p", "text": "Bernarda: No a ella. ¡A él!"}, {"type": "p", "text": "La Poncia: ¡Claro, a él hay que alejarlo de aquí! Piensas bien."}, {"type": "p", "text": "Bernarda: No pienso. Hay cosas que no se pueden ni se deben pensar. Yo ordeno. La Poncia: ¿Y tú crees que él querrá marcharse?"}, {"type": "p", "text": "Bernarda: (Levantándose.) ¿Qué imagina tu cabeza?"}, {"type": "p", "text": "La Poncia: Él, claro, ¡se casará con Angustias!"}, {"type": "p", "text": "Bernarda: Habla. Te conozco demasiado para saber que ya me tienes preparada la cuchilla."}, {"type": "p", "text": "La Poncia: Nunca pensé que se llamara asesinato al aviso."}, {"type": "p", "text": "Bernarda: ¿Me tienes que prevenir algo?"}, {"type": "p", "text": "La Poncia: Yo no acuso, Bernarda. Yo sólo te digo: abre los ojos y verás."}, {"type": "p", "text": "Bernarda: ¿Y verás qué?"}, {"type": "p", "text": "La Poncia: Siempre has sido lista. Has visto lo malo de las gentes a cien leguas. Muchas veces creí que adivinabas los pensamientos. Pero los hijos son los hijos. Ahora estás ciega."}, {"type": "p", "text": "Bernarda: ¿Te refieres a Martirio?"}, {"type": "p", "text": "La Poncia: Bueno, a Martirio... (Con curiosidad.) ¿Por qué habrá escondido el retrato? Bernarda: (Queriendo ocultar a su hija.) Después de todo ella dice que ha sido una broma. ¿Qué otra cosa puede ser?"}, {"type": "p", "text": "La Poncia: (Con sorna.) ¿Tú lo crees así?"}, {"type": "p", "text": "Bernarda: (Enérgica.) No lo creo. ¡Es así!"}, {"type": "p", "text": "La Poncia: Basta. Se trata de lo tuyo. Pero si fuera la vecina de enfrente, ¿qué sería? Bernarda: Ya empiezas a sacar la punta del cuchillo."}, {"type": "p", "text": "La Poncia: (Siempre con crueldad.) No, Bernarda, aquí pasa una cosa muy grande. Yo no te quiero echar la culpa, pero tú no has dejado a tus hijas libres. Martirio es enamoradiza, digas lo que tú quieras. ¿Por qué no la dejaste casar con Enrique Humanes? ¿Por qué el mismo día que iba a venir a la ventana le mandaste recado que no viniera?"}, {"type": "p", "text": "Bernarda: (Fuerte.) ¡Y lo haría mil veces! Mi sangre no se junta con la de los Humanes mientras yo viva! Su padre fue gañán."}, {"type": "p", "text": "La Poncia: ¡Y así te va a ti con esos humos!"}, {"type": "p", "text": "Bernarda: Los tengo porque puedo tenerlos. Y tú no los tienes porque sabes muy bien cuál es tu origen."}, {"type": "p", "text": "La Poncia: (Con odio.) ¡No me lo recuerdes! Estoy ya vieja, siempre agradecí tu protección."}, {"type": "p", "text": "Bernarda: (Crecida.) ¡No lo parece!"}, {"type": "p", "text": "La Poncia: (Con odio envuelto en suavidad.) A Martirio se le olvidará esto. Bernarda: Y si no lo olvida peor para ella. No creo que ésta sea la «cosa muy grande» que aquí pasa. Aquí no pasa nada. ¡Eso quisieras tú! Y si pasara algún día estáte segura que no traspasaría las paredes."}, {"type": "p", "text": "La Poncia: ¡Eso no lo sé yo! En el pueblo hay gentes que leen también de lejos los pensamientos escondidos."}, {"type": "p", "text": "Bernarda: ¡Cómo gozarías de vernos a mí y a mis hijas camino del lupanar!"}, {"type": "p", "text": "La Poncia: ¡Nadie puede conocer su fin!"}, {"type": "p", "text": "Bernarda: ¡Yo sí sé mi fin! ¡Y el de mis hijas! El lupanar se queda para alguna mujer ya difunta..."}, {"type": "p", "text": "La Poncia: (Fiera.) ¡Bernarda! ¡Respeta la memoria de mi madre!"}, {"type": "p", "text": "Bernarda: ¡No me persigas tú con tus malos pensamientos!"}, {"type": "p", "text": "(Pausa.)"}, {"type": "p", "text": "La Poncia: Mejor será que no me meta en nada."}, {"type": "p", "text": "Bernarda: Eso es lo que debías hacer. Obrar y callar a todo. Es la obligación de los que viven a sueldo."}, {"type": "p", "text": "La Poncia: Pero no se puede. ¿A ti no te parece que Pepe estaría mejor casado con Martirio o... ¡sí!, con Adela?"}, {"type": "p", "text": "Bernarda: No me parece."}, {"type": "p", "text": "La Poncia: (Con intención.) Adela. ¡Ésa es la verdadera novia del Romano!"}, {"type": "p", "text": "Bernarda: Las cosas no son nunca a gusto nuestro."}, {"type": "p", "text": "La Poncia: Pero les cuesta mucho trabajo desviarse de la verdadera inclinación. A mí me parece mal que Pepe esté con Angustias, y a las gentes, y hasta al aire. ¡Quién sabe si se saldrán con la suya!"}, {"type": "p", "text": "Bernarda: ¡Ya estamos otra vez!... Te deslizas para llenarme de malos sueños. Y no quiero entenderte, porque si llegara al alcance de todo lo que dices te tendría que arañar. La Poncia: ¡No llegará la sangre al río!"}, {"type": "p", "text": "Bernarda: ¡Afortunadamente mis hijas me respetan y jamás torcieron mi voluntad! La Poncia: ¡Eso sí! Pero en cuanto las dejes sueltas se te subirán al tejado. Bernarda: ¡Ya las bajaré tirándoles cantos!"}, {"type": "p", "text": "La Poncia: ¡Desde luego eres la más valiente!"}, {"type": "p", "text": "Bernarda: ¡Siempre gasté sabrosa pimienta!"}, {"type": "p", "text": "La Poncia: ¡Pero lo que son las cosas! A su edad. ¡Hay que ver el entusiasmo de Angustias con su novio! ¡Y él también parece muy picado! Ayer me contó mi hijo mayor que a las cuatro y media de la madrugada, que pasó por la calle con la yunta, estaban hablando todavía."}, {"type": "p", "text": "Bernarda: ¡A las cuatro y media!"}, {"type": "p", "text": "Angustias: (Saliendo.) ¡Mentira!"}, {"type": "p", "text": "La Poncia: Eso me contaron."}, {"type": "p", "text": "Bernarda: (A Angustias.) ¡Habla!"}, {"type": "p", "text": "Angustias: Pepe lleva más de una semana marchándose a la una. Que Dios me mate si miento."}, {"type": "p", "text": "Martirio: (Saliendo.) Yo también lo sentí marcharse a las cuatro."}, {"type": "p", "text": "Bernarda: Pero, ¿lo viste con tus ojos?"}, {"type": "p", "text": "Martirio: No quise asomarme. ¿No habláis ahora por la ventana del callejón? Angustias: Yo hablo por la ventana de mi dormitorio."}, {"type": "p", "text": "(Aparece Adela en la puerta.)"}, {"type": "p", "text": "Martirio: Entonces..."}, {"type": "p", "text": "Bernarda: ¿Qué es lo que pasa aquí?"}, {"type": "p", "text": "La Poncia: ¡Cuida de enterarte! Pero, desde luego, Pepe estaba a las cuatro de la madrugada en una reja de tu casa."}, {"type": "p", "text": "Bernarda: ¿Lo sabes seguro?"}, {"type": "p", "text": "La Poncia: Seguro no se sabe nada en esta vida."}, {"type": "p", "text": "Adela: Madre, no oiga usted a quien nos quiere perder a todas."}, {"type": "p", "text": "Bernarda: ¡Yo sabré enterarme! Si las gentes del pueblo quieren levantar falsos testimonios se encontrarán con mi pedernal. No se hable de este asunto. Hay a veces una ola de fango que levantan los demás para perdernos."}]$lira$::jsonb, 1084);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 8, 'Parte 1 (9/12)', $lira$[{"type": "p", "text": "Martirio: A mí no me gusta mentir."}, {"type": "p", "text": "La Poncia: Y algo habrá."}, {"type": "p", "text": "Bernarda: No habrá nada. Nací para tener los ojos abiertos. Ahora vigilaré sin cerrarlos ya hasta que me muera."}, {"type": "p", "text": "Angustias: Yo tengo derecho de enterarme."}, {"type": "p", "text": "Bernarda: Tú no tienes derecho más que a obedecer. Nadie me traiga ni me lleve. (A la Poncia.) Y tú te metes en los asuntos de tu casa. ¡Aquí no se vuelve a dar un paso que yo no sienta!"}, {"type": "p", "text": "Criada: (Entrando.) ¡En lo alto de la calle hay un gran gentío y todos los vecinos están en sus puertas!"}, {"type": "p", "text": "Bernarda: (A Poncia.) ¡Corre a enterarte de lo que pasa! (Las mujeres corren para salir.) ¿Dónde vais? Siempre os supe mujeres ventaneras y rompedoras de su luto. ¡Vosotras al patio!"}, {"type": "p", "text": "(Salen y sale Bernarda. Se oyen rumores lejanos. Entran Martirio y Adela, que se quedan escuchando y sin atreverse a dar un paso más de la puerta de salida.) Martirio: Agradece a la casualidad que no desaté mi lengua."}, {"type": "p", "text": "Adela: También hubiera hablado yo."}, {"type": "p", "text": "Martirio: ¿Y qué ibas a decir? ¡Querer no es hacer!"}, {"type": "p", "text": "Adela: Hace la que puede y la que se adelanta. Tú querías, pero no has podido. Martirio: No seguirás mucho tiempo."}, {"type": "p", "text": "Adela: ¡Lo tendré todo!"}, {"type": "p", "text": "Martirio: Yo romperé tus abrazos."}, {"type": "p", "text": "Adela: (Suplicante.) ¡Martirio, déjame!"}, {"type": "p", "text": "Martirio: ¡De ninguna!"}, {"type": "p", "text": "Adela: ¡Él me quiere para su casa!"}, {"type": "p", "text": "Martirio: ¡He visto cómo te abrazaba!"}, {"type": "p", "text": "Adela: Yo no quería. He ido como arrastrada por una maroma."}, {"type": "p", "text": "Martirio: ¡Primero muerta!"}, {"type": "p", "text": "(Se asoman Magdalena y Angustias. Se siente crecer el tumulto.)"}, {"type": "p", "text": "La Poncia: (Entrando con Bernarda.) ¡Bernarda!"}, {"type": "p", "text": "Bernarda: ¿Qué ocurre?"}, {"type": "p", "text": "La Poncia: La hija de la Librada, la soltera, tuvo un hijo no se sabe con quién. Adela: ¿Un hijo?"}, {"type": "p", "text": "La Poncia: Y para ocultar su vergüenza lo mató y lo metió debajo de unas piedras; pero unos perros, con más corazón que muchas criaturas, lo sacaron y como llevados por la mano de Dios lo han puesto en el tranco de su puerta. Ahora la quieren matar. La traen arrastrando por la calle abajo, y por las trochas y los terrenos del olivar vienen los hombres corriendo, dando unas voces que estremecen los campos."}, {"type": "p", "text": "Bernarda: Sí, que vengan todos con varas de olivo y mangos de azadones, que vengan todos para matarla."}, {"type": "p", "text": "Adela: ¡No, no, para matarla no!"}, {"type": "p", "text": "Martirio: Sí, y vamos a salir también nosotras."}, {"type": "p", "text": "Bernarda: Y que pague la que pisotea su decencia."}, {"type": "p", "text": "(Fuera su oye un grito de mujer y un gran rumor.)"}, {"type": "p", "text": "Adela: ¡Que la dejen escapar! ¡No salgáis vosotras!"}, {"type": "p", "text": "Martirio: (Mirando a Adela.) ¡Que pague lo que debe!"}, {"type": "p", "text": "Bernarda: (Bajo el arco.) ¡Acabar con ella antes que lleguen los guardias! ¡Carbón ardiendo en el sitio de su pecado!"}, {"type": "p", "text": "Adela: (Cogiéndose el vientre.) ¡No! ¡No!"}, {"type": "p", "text": "Bernarda: ¡Matadla! ¡Matadla!"}, {"type": "p", "text": "Telón rápido."}, {"type": "p", "text": "Acto tercero Cuatro paredes blancas ligeramente azuladas del patio interior de la casa de Bernarda. Es de noche. El decorado ha de ser de una perfecta simplicidad. Las puertas, iluminadas por la luz de los interiores, dan un tenue fulgor a la escena. En el centro, una mesa con un quinqué, donde están comiendo Bernarda y sus hijas. La Poncia las sirve. Prudencia está sentada aparte."}, {"type": "p", "text": "(Al levantarse el telón hay un gran silencio, interrumpido por el ruido de platos y cubiertos.)"}, {"type": "p", "text": "Prudencia: Ya me voy. Os he hecho una visita larga. (Se levanta.)"}, {"type": "p", "text": "Bernarda: Espérate, mujer. No nos vemos nunca."}, {"type": "p", "text": "Prudencia: ¿Han dado el último toque para el rosario?"}, {"type": "p", "text": "La Poncia: Todavía no."}, {"type": "p", "text": "(Prudencia se sienta.)"}, {"type": "p", "text": "Bernarda: ¿Y tu marido cómo sigue?"}, {"type": "p", "text": "Prudencia: Igual."}, {"type": "p", "text": "Bernarda: Tampoco lo vemos."}, {"type": "p", "text": "Prudencia: Ya sabes sus costumbres. Desde que se peleó con sus hermanos por la herencia no ha salido por la puerta de la calle. Pone una escalera y salta las tapias del corral."}, {"type": "p", "text": "Bernarda: Es un verdadero hombre. ¿Y con tu hija...?"}, {"type": "p", "text": "Prudencia: No la ha perdonado."}, {"type": "p", "text": "Bernarda: Hace bien."}, {"type": "p", "text": "Prudencia: No sé qué te diga. Yo sufro por esto."}, {"type": "p", "text": "Bernarda: Una hija que desobedece deja de ser hija para convertirse en una enemiga. Prudencia: Yo dejo que el agua corra. No me queda más consuelo que refugiarme en la iglesia, pero como me estoy quedando sin vista tendré que dejar de venir para que no jueguen con una los chiquillos. (Se oye un gran golpe, como dado en los muros.) ¿Qué es eso?"}, {"type": "p", "text": "Bernarda: El caballo garañón, que está encerrado y da coces contra el muro. (A voces.) ¡Trabadlo y que salga al corral! ( En voz baja.) Debe tener calor."}, {"type": "p", "text": "Prudencia: ¿Vais a echarle las potras nuevas?"}, {"type": "p", "text": "Bernarda: Al amanecer."}, {"type": "p", "text": "Prudencia: Has sabido acrecentar tu ganado."}, {"type": "p", "text": "Bernarda: A fuerza de dinero y sinsabores."}, {"type": "p", "text": "La Poncia: (Interviniendo.) ¡Pero tiene la mejor manada de estos contornos! Es una lástima que esté bajo de precio."}, {"type": "p", "text": "Bernarda: ¿Quieres un poco de queso y miel?"}, {"type": "p", "text": "Prudencia: Estoy desganada."}, {"type": "p", "text": "(Se oye otra vez el golpe.)"}, {"type": "p", "text": "La Poncia: ¡Por Dios!"}, {"type": "p", "text": "Prudencia: ¡Me ha retemblado dentro del pecho!"}, {"type": "p", "text": "Bernarda: (Levantándose furiosa) ¿Hay que decir las cosas dos veces? ¡Echadlo que se revuelque en los montones de paja! (Pausa, y como hablando con los gañanes.) Pues encerrad las potras en la cuadra, pero dejadlo libre, no sea que nos eche abajo las paredes. (Se dirige a la mesa y se sienta otra vez.) ¡Ay, qué vida!"}, {"type": "p", "text": "Prudencia: Bregando como un hombre."}, {"type": "p", "text": "Bernarda: Así es. (Adela se levanta de la mesa.) ¿Dónde vas?"}, {"type": "p", "text": "Adela: A beber agua."}, {"type": "p", "text": "Bernarda: (En alta voz.) Trae un jarro de agua fresca. (A Adela.) Puedes sentarte. (Adela se sienta.)"}, {"type": "p", "text": "Prudencia: Y Angustias, ¿cuándo se casa?"}, {"type": "p", "text": "Bernarda: Vienen a pedirla dentro de tres días."}, {"type": "p", "text": "Prudencia: ¡Estarás contenta!"}, {"type": "p", "text": "Angustias: ¡Claro!"}, {"type": "p", "text": "Amelia: (A Magdalena.) ¡Ya has derramado la sal!"}, {"type": "p", "text": "Magdalena: Peor suerte que tienes no vas a tener."}, {"type": "p", "text": "Amelia: Siempre trae mala sombra."}, {"type": "p", "text": "Bernarda: ¡Vamos!"}, {"type": "p", "text": "Prudencia: (A Angustias.) ¿Te ha regalado ya el anillo?"}, {"type": "p", "text": "Angustias: Mírelo usted. (Se lo alarga.)"}, {"type": "p", "text": "Prudencia: Es precioso. Tres perlas. En mi tiempo las perlas significaban lágrimas.. Angustias: Pero y a las cosas han cambiado."}, {"type": "p", "text": "Adela: Yo creo que no. Las cosas significan siempre lo mismo. Los anillos de pedida deben ser de diamantes."}, {"type": "p", "text": "Prudencia: Es más propio."}, {"type": "p", "text": "Bernarda: Con perlas o sin ellas las cosas son como una se las propone."}, {"type": "p", "text": "Martirio: O como Dios dispone."}, {"type": "p", "text": "Prudencia: Los muebles me han dicho que son preciosos."}, {"type": "p", "text": "Bernarda: Dieciséis mil reales he gastado."}, {"type": "p", "text": "La Poncia: (Interviniendo.) Lo mejor es el armario de luna."}, {"type": "p", "text": "Prudencia: Nunca vi un mueble de éstos."}, {"type": "p", "text": "Bernarda: Nosotras tuvimos arca."}, {"type": "p", "text": "Prudencia: Lo preciso es que todo sea para bien."}]$lira$::jsonb, 1069);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 9, 'Parte 1 (10/12)', $lira$[{"type": "p", "text": "Adela: Que nunca se sabe."}, {"type": "p", "text": "Bernarda: No hay motivo para que no lo sea."}, {"type": "p", "text": "(Se oyen lejanísimas unas campanas.)"}, {"type": "p", "text": "Prudencia: El último toque. (A Angustias.) Ya vendré a que me enseñes la ropa. Angustias: Cuando usted quiera."}, {"type": "p", "text": "Prudencia: Buenas noches nos dé Dios."}, {"type": "p", "text": "Bernarda: Adiós, Prudencia."}, {"type": "p", "text": "Las cinco a la vez: Vaya usted con Dios."}, {"type": "p", "text": "(Pausa. Sale Prudencia.)"}, {"type": "p", "text": "Bernarda: Ya hemos comido. (Se levantan.)"}, {"type": "p", "text": "Adela: Voy a llegarme hasta el portón para estirar las piernas y tomar un poco el fresco. (Magdalena se sienta en una silla baja retrepada contra la pared.)"}, {"type": "p", "text": "Amelia: Yo voy contigo."}, {"type": "p", "text": "Martirio: Y yo."}, {"type": "p", "text": "Adela: (Con odio contenido.) No me voy a perder."}, {"type": "p", "text": "Amelia: La noche quiere compaña."}, {"type": "p", "text": "(Salen. Bernarda se sienta y Angustias está arreglando la mesa.)"}, {"type": "p", "text": "Bernarda: Ya te he dicho que quiero que hables con tu hermana Martirio. Lo que pasó del retrato fue una broma y lo debes olvidar."}, {"type": "p", "text": "Angustias: Usted sabe que ella no me quiere."}, {"type": "p", "text": "Bernarda: Cada uno sabe lo que piensa por dentro. Yo no me meto en los corazones, pero quiero buena fachada y armonía familiar. ¿Lo entiendes?"}, {"type": "p", "text": "Angustias: Sí."}, {"type": "p", "text": "Bernarda: Pues ya está."}, {"type": "p", "text": "Magdalena: (Casi dormida.) Además, ¡si te vas a ir antes de nada! (Se duerme.) Angustias: Tarde me parece."}, {"type": "p", "text": "Bernarda: ¿A qué hora terminaste anoche de hablar?"}, {"type": "p", "text": "Angustias: A las doce y media."}, {"type": "p", "text": "Bernarda: ¿Qué cuenta Pepe?"}, {"type": "p", "text": "Angustias: Yo lo encuentro distraído. Me habla siempre como pensando en otra cosa. Si le pregunto qué le pasa, me contesta: «Los hombres tenemos nuestras"}, {"type": "p", "text": "preocupaciones.»"}, {"type": "p", "text": "Bernarda: No le debes preguntar. Y cuando te cases, menos. Habla si él habla y míralo cuando te mire. Así no tendrás disgustos."}, {"type": "p", "text": "Angustias: Yo creo, madre, que él me oculta muchas cosas."}, {"type": "p", "text": "Bernarda: No procures descubrirlas, no le preguntes y, desde luego, que no te vea llorar jamás."}, {"type": "p", "text": "Angustias: Debía estar contenta y no lo estoy."}, {"type": "p", "text": "Bernarda: Eso es lo mismo."}, {"type": "p", "text": "Angustias: Muchas veces miro a Pepe con mucha fijeza y se me borra a través de los hierros, como si lo tapara una nube de polvo de las que levantan los rebaños. Bernarda: Eso son cosas de debilidad."}, {"type": "p", "text": "Angustias: ¡Ojalá!"}, {"type": "p", "text": "Bernarda: ¿Viene esta noche?"}, {"type": "p", "text": "Angustias: No. Fue con su madre a la capital."}, {"type": "p", "text": "Bernarda: Así nos acostaremos antes. ¡Magdalena!"}, {"type": "p", "text": "Angustias: Está dormida."}, {"type": "p", "text": "(Entran Adela, Martirio y Amelia.)"}, {"type": "p", "text": "Amelia: ¡Qué noche más oscura!"}, {"type": "p", "text": "Adela: No se ve a dos pasos de distancia."}, {"type": "p", "text": "Martirio: Una buena noche para ladrones, para el que necesite escondrijo."}, {"type": "p", "text": "Adela: El caballo garañón estaba en el centro del corral. ¡Blanco! Doble de grande, llenando todo lo oscuro."}, {"type": "p", "text": "Amelia: Es verdad. Daba miedo. ¡Parecía una aparición!"}, {"type": "p", "text": "Adela: Tiene el cielo unas estrellas como puños."}, {"type": "p", "text": "Martirio: Ésta se puso a mirarlas de modo que se iba a tronchar el cuello."}, {"type": "p", "text": "Adela: ¿Es que no te gustan a ti?"}, {"type": "p", "text": "Martirio: A mí las cosas de tejas arriba no me importan nada. Con lo que pasa dentro de las habitaciones tengo bastante."}, {"type": "p", "text": "Adela: Así te va a ti."}, {"type": "p", "text": "Bernarda: A ella le va en lo suyo como a ti en lo tuyo."}, {"type": "p", "text": "Angustias: Buenas noches."}, {"type": "p", "text": "Adela: ¿Ya te acuestas?"}, {"type": "p", "text": "Angustias: Sí, esta noche no viene Pepe. (Sale.)"}, {"type": "p", "text": "Adela: Madre, ¿por qué cuando se corre una estrella o luce un relámpago se dice: Santa Bárbara bendita,"}, {"type": "p", "text": "que en el cielo estás escrita"}, {"type": "p", "text": "con papel y agua bendita?"}, {"type": "p", "text": "Bernarda: Los antiguos sabían muchas cosas que hemos olvidado."}, {"type": "p", "text": "Amelia: Yo cierro los ojos para no verlas."}, {"type": "p", "text": "Adela: Yo no. A mí me gusta ver correr lleno de lumbre lo que está quieto y quieto años enteros."}, {"type": "p", "text": "Martirio: Pero estas cosas nada tienen que ver con nosotros."}, {"type": "p", "text": "Bernarda: Y es mejor no pensar en ellas."}, {"type": "p", "text": "Adela: ¡Qué noche más hermosa! Me gustaría quedarme hasta muy tarde para disfrutar el fresco del campo."}, {"type": "p", "text": "Bernarda: Pero hay que acostarse. ¡Magdalena!"}, {"type": "p", "text": "Amelia: Está en el primer sueño."}, {"type": "p", "text": "Bernarda: ¡Magdalena!"}, {"type": "p", "text": "Magdalena: (Disgustada.) ¡Dejarme en paz!"}, {"type": "p", "text": "Bernarda: ¡A la cama!"}, {"type": "p", "text": "Magdalena: (Levantándose malhumorada.) ¡No la dejáis a una tranquila! (Se va refunfuñando.)"}, {"type": "p", "text": "Amelia: Buenas noches. (Se va.)"}, {"type": "p", "text": "Bernarda: Andar vosotras también."}, {"type": "p", "text": "Martirio: ¿Cómo es que esta noche no viene el novio de Angustias?"}, {"type": "p", "text": "Bernarda: Fue de viaje."}, {"type": "p", "text": "Martirio: (Mirando a Adela.) ¡Ah!"}, {"type": "p", "text": "Adela: Hasta mañana. (Sale.)"}, {"type": "p", "text": "(Martirio bebe agua y sale lentamente mirando hacia la puerta del corral. Sale La Poncia.)"}, {"type": "p", "text": "La Poncia: ¿Estás todavía aquí?"}, {"type": "p", "text": "Bernarda: Disfrutando este silencio y sin lograr ver por parte alguna « la cosa tan grande» que aquí pasa, según tú."}, {"type": "p", "text": "La Poncia: Bernarda, dejemos esa conversación."}, {"type": "p", "text": "Bernarda: En esta casa no hay un sí ni un no. Mi vigilancia lo puede todo."}, {"type": "p", "text": "La Poncia: No pasa nada por fuera. Eso es verdad. Tus hijas están y viven como metidas en alacenas. Pero ni tú ni nadie puede vigilar por el interior de los pechos. Bernarda: Mis hijas tienen la respiración tranquila."}, {"type": "p", "text": "La Poncia: Eso te importa a ti, que eres su madre. A mí, con servir tu casa tengo bastante."}, {"type": "p", "text": "Bernarda: Ahora te has vuelto callada."}, {"type": "p", "text": "La Poncia: Me estoy en mi sitio, y en paz."}, {"type": "p", "text": "Bernarda: Lo que pasa es que no tienes nada que decir. Si en esta casa hubiera hierbas, ya te encargarías de traer a pastar las ovejas del vecindario."}, {"type": "p", "text": "La Poncia: Yo tapo más de lo que te figuras."}, {"type": "p", "text": "Bernarda: ¿Sigue tu hijo viendo a Pepe a las cuatro de la mañana? ¿Siguen diciendo todavía la mala letanía de esta casa?"}, {"type": "p", "text": "La Poncia: No dicen nada."}, {"type": "p", "text": "Bernarda: Porque no pueden. Porque no hay carne donde morder. ¡A la vigilia de mis ojos se debe esto!"}, {"type": "p", "text": "La Poncia: Bernarda, yo no quiero hablar porque temo tus intenciones. Pero no estés segura."}, {"type": "p", "text": "Bernarda: ¡Segurísima!"}, {"type": "p", "text": "La Poncia: ¡A lo mejor, de pronto, cae un rayo! ¡A lo mejor, de pronto, un golpe de sangre te para el corazón!"}, {"type": "p", "text": "Bernarda: Aquí no pasará nada. Ya estoy alerta contra tus suposiciones."}, {"type": "p", "text": "La Poncia: Pues mejor para ti."}, {"type": "p", "text": "Bernarda: ¡No faltaba más!"}, {"type": "p", "text": "Criada: (Entrando.) Ya terminé de fregar los platos. ¿Manda usted algo, Bernarda? Bernarda: (Levantándose.) Nada. Yo voy a descansar."}, {"type": "p", "text": "La Poncia: ¿A qué hora quiere que la llame?"}, {"type": "p", "text": "Bernarda: A ninguna. Esta noche voy a dormir bien. (Se va.)"}, {"type": "p", "text": "La Poncia: Cuando una no puede con el mar lo más fácil es volver las espaldas para no verlo."}, {"type": "p", "text": "Criada: Es tan orgullosa que ella misma se pone una venda en los ojos."}, {"type": "p", "text": "La Poncia: Yo no puedo hacer nada. Quise atajar las cosas, pero ya me asustan demasiado. ¿Tú ves este silencio? Pues hay una tormenta en cada cuarto. El día que estallen nos barrerán a todas. Yo he dicho lo que tenía que decir."}]$lira$::jsonb, 1084);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 10, 'Parte 1 (11/12)', $lira$[{"type": "p", "text": "Criada: Bernarda cree que nadie puede con ella y no sabe la fuerza que tiene un hombre entre mujeres solas."}, {"type": "p", "text": "La Poncia: No es toda la culpa de Pepe el Romano. Es verdad que el año pasado anduvo detrás de Adela, y ésta estaba loca por él, pero ella debió estarse en su sitio y no provocarlo. Un hombre es un hombre."}, {"type": "p", "text": "Criada: Hay quien cree que habló muchas noches con Adela."}, {"type": "p", "text": "La Poncia: Es verdad. (En voz baja) Y otras cosas."}, {"type": "p", "text": "Criada: No sé lo que va a pasar aquí."}, {"type": "p", "text": "La Poncia: A mí me gustaría cruzar el mar y dejar esta casa de guerra.."}, {"type": "p", "text": "Criada: Bernarda está aligerando la boda y es posible que nada pase."}, {"type": "p", "text": "La Poncia: Las cosas se han puesto ya demasiado maduras. Adela está decidida a lo que sea, y las demás vigilan sin descanso."}, {"type": "p", "text": "Criada: ¿Y Martirio también?"}, {"type": "p", "text": "La Poncia: Ésa es la peor. Es un pozo de veneno. Ve que el Romano no es para ella y hundiría el mundo si estuviera en su mano."}, {"type": "p", "text": "Criada: ¡Es que son malas!"}, {"type": "p", "text": "La Poncia: Son mujeres sin hombre, nada más. En estas cuestiones se olvida hasta la sangre. ¡Chisssssss! (Escucha.)"}, {"type": "p", "text": "Criada: ¿Qué pasa?"}, {"type": "p", "text": "La Poncia: (Se levanta.) Están ladrando los perros."}, {"type": "p", "text": "Criada: Debe haber pasado alguien por el portón."}, {"type": "p", "text": "(Sale Adela en enaguas blancas y corpiño.)"}, {"type": "p", "text": "La Poncia: ¿No te habías acostado?"}, {"type": "p", "text": "Adela: Voy a beber agua. (Bebe en un vaso de la mesa.)"}, {"type": "p", "text": "La Poncia: Yo te suponía dormida."}, {"type": "p", "text": "Adela: Me despertó la sed. Y vosotras, ¿no descansáis?"}, {"type": "p", "text": "Criada: Ahora."}, {"type": "p", "text": "(Sale Adela.)"}, {"type": "p", "text": "La Poncia: Vámonos."}, {"type": "p", "text": "Criada: Ganado tenemos el sueño. Bernarda no me deja descansar en todo el día. La Poncia: Llévate la luz."}, {"type": "p", "text": "Criada: Los perros están como locos."}, {"type": "p", "text": "La Poncia: No nos van a dejar dormir."}, {"type": "p", "text": "(Salen. La escena queda casi a oscuras. Sale María Josefa con una oveja en los brazos.)"}, {"type": "p", "text": "María Josefa:"}, {"type": "p", "text": "Ovejita, niño mío,"}, {"type": "p", "text": "vámonos a la orilla del mar."}, {"type": "p", "text": "La hormiguita estará en su puerta,"}, {"type": "p", "text": "yo te daré la teta y el pan."}, {"type": "p", "text": "Bernarda,"}, {"type": "p", "text": "cara de leoparda."}, {"type": "p", "text": "Magdalena,"}, {"type": "p", "text": "cara de hiena."}, {"type": "p", "text": "¡Ovejita!"}, {"type": "p", "text": "Meee, meee."}, {"type": "p", "text": "Vamos a los ramos del portal de Belén.(Ríe)"}, {"type": "p", "text": "Ni tú ni yo queremos dormir."}, {"type": "p", "text": "La puerta sola se abrirá"}, {"type": "p", "text": "y en la playa nos meteremos"}, {"type": "p", "text": "en una choza de coral."}, {"type": "p", "text": "Bernarda,"}, {"type": "p", "text": "cara de leoparda."}, {"type": "p", "text": "Magdalena,"}, {"type": "p", "text": "cara de hiena."}, {"type": "p", "text": "¡Ovejita!"}, {"type": "p", "text": "Meee, meee."}, {"type": "p", "text": "Vamos a los ramos del portal de Belén!"}, {"type": "p", "text": "(Se va cantando. Entra Adela. Mira a un lado y otro con sigilo, y desaparece por la puerta del corral. Sale Martirio por otra puerta y queda en angustioso acecho en el centro de la escena. También va en enaguas. Se cubre con un pequeño mantón negro detalle. Sale por enfrente de ella María Josefa.)"}, {"type": "p", "text": "Martirio: Abuela, ¿dónde va usted?"}, {"type": "p", "text": "María Josefa: ¿Vas a abrirme la puerta? ¿Quién eres tú?"}, {"type": "p", "text": "Martirio: ¿Cómo está aquí?"}, {"type": "p", "text": "María Josefa: Me escapé. ¿Tú quién eres?"}, {"type": "p", "text": "Martirio: Vaya a acostarse."}, {"type": "p", "text": "María Josefa: Tú eres Martirio, ya te veo. Martirio, cara de martirio. ¿Y cuándo vas a tener un niño? Yo he tenido éste."}, {"type": "p", "text": "Martirio: ¿Dónde cogió esa oveja?"}, {"type": "p", "text": "María Josefa: Ya sé que es una oveja. Pero, ¿por qué una oveja no va a ser un niño? Mejor es tener una oveja que no tener nada. Bernarda, cara de leoparda. Magdalena, cara de hiena."}, {"type": "p", "text": "Martirio: No dé voces."}, {"type": "p", "text": "María Josefa: Es verdad. Está todo muy oscuro. Como tengo el pelo blanco crees que no puedo tener crías, y sí, crías y crías y crías. Este niño tendrá el pelo blanco y tendrá otro niño, y éste otro, y todos con el pelo de nieve, seremos como las olas, una y otra y otra. Luego nos sentaremos todos, y todos tendremos el cabello blanco y seremos espuma. ¿Por qué aquí no hay espuma? Aquí no hay más que mantos de luto."}, {"type": "p", "text": "Martirio: Calle, calle."}, {"type": "p", "text": "María Josefa: Cuando mi vecina tenía un niño yo le llevaba chocolate y luego ella me lo traía a mí, y así siempre, siempre, siempre. Tú tendrás el pelo blanco, pero no vendrán las vecinas. Yo tengo que marcharme, pero tengo miedo de que los perros me muerdan. ¿Me acompañarás tú a salir del campo? Yo quiero campo. Yo quiero casas, pero casas abiertas, y las vecinas acostadas en sus camas con sus niños chiquitos, y los hombres fuera, sentados en sus sillas. Pepe el Romano es un gigante. Todas lo queréis. Pero él os va a devorar, porque vosotras sois granos de trigo. No granos de trigo, no. ¡Ranas sin lengua!"}, {"type": "p", "text": "Martirio: (Enérgica.) Vamos, váyase a la cama. (La empuja.)"}, {"type": "p", "text": "María Josefa: Sí, pero luego tú me abrirás, ¿verdad?"}, {"type": "p", "text": "Martirio: De seguro."}, {"type": "p", "text": "María Josefa: (Llorando.)"}, {"type": "p", "text": "Ovejita, niño mío,"}, {"type": "p", "text": "vámonos a la orilla del mar."}, {"type": "p", "text": "La hormiguita estará en su puerta,"}, {"type": "p", "text": "yo te daré la teta y el pan."}, {"type": "p", "text": "(Sale. Martirio cierra la puerta por donde ha salido María Josefa y se dirige a la puerta del corral. Allí vacila, pero avanza dos pasos más.)"}, {"type": "p", "text": "Martirio: (En voz baja.) Adela. (Pausa. Avanza hasta la misma puerta. En voz alta.) ¡Adela!"}, {"type": "p", "text": "(Aparece Adela. Viene un poco despeinada.)"}, {"type": "p", "text": "Adela: ¿Por qué me buscas?"}, {"type": "p", "text": "Martirio: ¡Deja a ese hombre!"}, {"type": "p", "text": "Adela: ¿Quién eres tú para decírmelo?"}, {"type": "p", "text": "Martirio: No es ése el sitio de una mujer honrada."}, {"type": "p", "text": "Adela: ¡Con qué ganas te has quedado de ocuparlo!"}, {"type": "p", "text": "Martirio: (En voz alta.) Ha llegado el momento de que yo hable. Esto no puede seguir así."}, {"type": "p", "text": "Adela: Esto no es más que el comienzo. He tenido fuerza para adelantarme. El brío y el mérito que tú no tienes. He visto la muerte debajo de estos techos y he salido a buscar lo que era mío, lo que me pertenecía."}, {"type": "p", "text": "Martirio: Ese hombre sin alma vino por otra. Tú te has atravesado."}, {"type": "p", "text": "Adela: Vino por el dinero, pero sus ojos los puso siempre en mí."}, {"type": "p", "text": "Martirio: Yo no permitiré que lo arrebates. El se casará con Angustias."}, {"type": "p", "text": "Adela: Sabes mejor que yo que no la quiere."}, {"type": "p", "text": "Martirio: Lo sé."}, {"type": "p", "text": "Adela: Sabes, porque lo has visto, que me quiere a mí."}, {"type": "p", "text": "Martirio: (Desesperada.) Sí."}, {"type": "p", "text": "Adela: (Acercándose.) Me quiere a mí, me quiere a mí."}, {"type": "p", "text": "Martirio: Clávame un cuchillo si es tu gusto, pero no me lo digas más."}, {"type": "p", "text": "Adela: Por eso procuras que no vaya con él. No te importa que abrace a la que no quiere. A mí, tampoco. Ya puede estar cien años con Angustias. Pero que me abrace a mí se te hace terrible, porque tú lo quieres también, ¡lo quieres!"}]$lira$::jsonb, 1068);
insert into public.chapters (book_id, position, title, body, word_count)
values ('la-casa-de-bernarda-alba', 11, 'Parte 1 (12/12)', $lira$[{"type": "p", "text": "Martirio: (Dramática.) ¡Sí! Déjame decirlo con la cabeza fuera de los embozos. ¡Sí! Déjame que el pecho se me rompa como una granada de amargura. ¡Le quiero!"}, {"type": "p", "text": "Adela: (En un arranque, y abrazándola.) Martirio, Martirio, yo no tengo la culpa. Martirio: ¡No me abraces! No quieras ablandar mis ojos. Mi sangre ya no es la tuya, y aunque quisiera verte como hermana no te miro ya más que como mujer. (La rechaza.) Adela: Aquí no hay ningún remedio. La que tenga que ahogarse que se ahogue. Pepe el Romano es mío. Él me lleva a los juncos de la orilla."}, {"type": "p", "text": "Martirio: ¡No será!"}, {"type": "p", "text": "Adela: Ya no aguanto el horror de estos techos después de haber probado el sabor de su boca. Seré lo que él quiera que sea. Todo el pueblo contra mí, quemándome con sus dedos de lumbre, perseguida por los que dicen que son decentes, y me pondré delante de todos la corona de espinas que tienen las que son queridas de algún hombre casado. Martirio: ¡Calla!"}, {"type": "p", "text": "Adela: Sí, sí. (En voz baja.) Vamos a dormir, vamos a dejar que se case con Angustias. Ya no me importa. Pero yo me iré a una casita sola donde él me verá cuando quiera, cuando le venga en gana."}, {"type": "p", "text": "Martirio: Eso no pasará mientras yo tenga una gota de sangre en el cuerpo."}, {"type": "p", "text": "Adela: No a ti, que eres débil: a un caballo encabritado soy capaz de poner de rodillas con la fuerza de mi dedo meñique."}, {"type": "p", "text": "Martirio: No levantes esa voz que me irrita. Tengo el corazón lleno de una fuerza tan mala, que sin quererlo yo, a mí misma me ahoga."}, {"type": "p", "text": "Adela: Nos enseñan a querer a las hermanas. Dios me ha debido dejar sola, en medio de la oscuridad, porque te veo como si no te hubiera visto nunca."}, {"type": "p", "text": "(Se oye un silbido y Adela corre a la puerta, pero Martirio se le pone delante.) Martirio: ¿Dónde vas?"}, {"type": "p", "text": "Adela: ¡Quítate de la puerta!"}, {"type": "p", "text": "Martirio: ¡Pasa si puedes!"}, {"type": "p", "text": "Adela: ¡Aparta! (Lucha.)"}, {"type": "p", "text": "Martirio: (A voces.) ¡Madre, madre!"}, {"type": "p", "text": "Adela: ¡Déjame!"}, {"type": "p", "text": "(Aparece Bernarda. Sale en enaguas con un mantón negro.)"}, {"type": "p", "text": "Bernarda: Quietas, quietas. ¡Qué pobreza la mía, no poder tener un rayo entre los dedos!"}, {"type": "p", "text": "Martirio: (Señalando a Adela.) ¡Estaba con él! ¡Mira esas enaguas llenas de paja de trigo!"}, {"type": "p", "text": "Bernarda: ¡Esa es la cama de las mal nacidas! (Se dirige furiosa hacia Adela.) Adela: (Haciéndole frente.) ¡Aquí se acabaron las voces de presidio! (Adela arrebata un bastón a su madre y lo parte en dos.) Esto hago yo con la vara de la dominadora. No dé usted un paso más. ¡En mí no manda nadie más que Pepe!"}, {"type": "p", "text": "(Sale Magdalena.)"}, {"type": "p", "text": "Magdalena: ¡Adela!"}, {"type": "p", "text": "(Salen la Poncia y Angustias.)"}, {"type": "p", "text": "Adela: Yo soy su mujer. (A Angustias.) Entérate tú y ve al corral a decírselo. Él dominará toda esta casa. Ahí fuera está, respirando como si fuera un león."}, {"type": "p", "text": "Angustias: ¡Dios mío! Bernarda: ¡La escopeta! ¿Dónde está la escopeta? (Sale corriendo.)"}, {"type": "p", "text": "(Aparece Amelia por el fondo, que mira aterrada, con la cabeza sobre la pared. Sale detrás Martirio.)"}, {"type": "p", "text": "Adela: ¡Nadie podrá conmigo! (Va a salir.)"}, {"type": "p", "text": "Angustias: (Sujetándola.) De aquí no sales con tu cuerpo en triunfo, ¡ladrona! ¡deshonra de nuestra casa!"}, {"type": "p", "text": "Magdalena: ¡Déjala que se vaya donde no la veamos nunca más!"}, {"type": "p", "text": "(Suena un disparo.)"}, {"type": "p", "text": "Bernarda: (Entrando.) Atrévete a buscarlo ahora."}, {"type": "p", "text": "Martirio: (Entrando.) Se acabó Pepe el Romano."}, {"type": "p", "text": "Adela: ¡Pepe! ¡Dios mío! ¡Pepe! (Sale corriendo.)"}, {"type": "p", "text": "La Poncia: ¿Pero lo habéis matado?"}, {"type": "p", "text": "Martirio: ¡No! ¡Salió corriendo en la jaca!"}, {"type": "p", "text": "Bernarda: No fue culpa mía. Una mujer no sabe apuntar."}, {"type": "p", "text": "Magdalena: ¿Por qué lo has dicho entonces?"}, {"type": "p", "text": "Martirio: ¡Por ella! Hubiera volcado un río de sangre sobre su cabeza."}, {"type": "p", "text": "La Poncia: Maldita."}, {"type": "p", "text": "Magdalena: ¡Endemoniada!"}, {"type": "p", "text": "Bernarda: Aunque es mejor así. (Se oye como un golpe.) ¡Adela! ¡Adela!"}, {"type": "p", "text": "La Poncia: (En la puerta.) ¡Abre!"}, {"type": "p", "text": "Bernarda: Abre. No creas que los muros defienden de la vergüenza."}, {"type": "p", "text": "Criada: (Entrando.) ¡Se han levantado los vecinos!"}, {"type": "p", "text": "Bernarda: (En voz baja, como un rugido.) ¡Abre, porque echaré abajo la puerta! (Pausa. Todo queda en silencio) ¡Adela! (Se retira de la puerta.) ¡Trae un martillo! (La Poncia da un empujón y entra. Al entrar da un grito y sale.) ¿Qué?"}, {"type": "p", "text": "La Poncia: (Se lleva las manos al cuello.) ¡Nunca tengamos ese fin!"}, {"type": "p", "text": "(Las hermanas se echan hacia atrás. La Criada se santigua. Bernarda da un grito y avanza.)"}, {"type": "p", "text": "La Poncia: ¡No entres!"}, {"type": "p", "text": "Bernarda: No. ¡Yo no! Pepe: irás corriendo vivo por lo oscuro de las alamedas, pero otro día caerás. ¡Descolgarla! ¡Mi hija ha muerto virgen! Llevadla a su cuarto y vestirla como si fuera doncella. ¡Nadie dirá nada! ¡Ella ha muerto virgen! Avisad que al amanecer den dos clamores las campanas."}, {"type": "p", "text": "Martirio: Dichosa ella mil veces que lo pudo tener."}, {"type": "p", "text": "Bernarda: Y no quiero llantos. La muerte hay que mirarla cara a cara. ¡Silencio! (A otra hija.) ¡A callar he dicho! (A otra hija.) Las lágrimas cuando estés sola. ¡Nos hundiremos todas en un mar de luto! Ella, la hija menor de Bernarda Alba, ha muerto virgen. ¿Me habéis oído? ¡Silencio, silencio he dicho! ¡Silencio!"}, {"type": "p", "text": "Día viernes 19 de junio, 1936."}, {"type": "p", "text": "Telón rápido."}, {"type": "h", "text": "Fin"}]$lira$::jsonb, 842);

