insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 0, 'Inicio', $lira$[{"type": "h", "text": "—El Avaro -"}, {"type": "p", "text": "Molière"}, {"type": "h", "text": "Personajes"}, {"type": "p", "text": "HARPAGÓN, padre de Cleanto y de Elisa y enamorado de Mariana"}, {"type": "p", "text": "CLEANTO, hijo de Harpagón, amante de Mariana"}, {"type": "p", "text": "ELISA, hija de Harpagón, amante de Valerio"}, {"type": "p", "text": "VALERIO, hijo de Anselmo y amante de Elisa"}, {"type": "p", "text": "MARIANA, amante de Cleanto y amada por Harpagón"}, {"type": "p", "text": "ANSELMO, padre de Valerio y de Mariana"}, {"type": "p", "text": "FROSINA, mujer intrigante"}, {"type": "p", "text": "MAESE SIMÓN, corredor"}, {"type": "p", "text": "MAESE SANTIAGO, cocinero y cochero de Harpagón"}, {"type": "p", "text": "FLECHA, criado de Cleanto"}, {"type": "p", "text": "DOÑA CLAUDIA, sirvienta de Harpagón"}, {"type": "p", "text": "MIAJAVENA y MERLUZA, lacayos de Harpagón"}, {"type": "p", "text": "EL COMISARIO y su ESCRIBIENTE"}, {"type": "p", "text": "La escena en París, en casa de Harpagón"}]$lira$::jsonb, 94);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 1, 'Acto primero · Escena primera', $lira$[{"type": "p", "text": "VALERIO y ELISA"}, {"type": "p", "text": "VALERIO. ¡Cómo, encantadora Elisa, os sentís melancólica después de las amables seguridades que habéis tenido la bondad de darme sobre vuestra felicidad! Os veo suspirar, ¡ay!, en medio de mi alegría. ¿Es que acaso lamentáis, decidme, haberme hecho dichoso? ¿Y os arrepentís de esta promesa, a la que mi pasión ha podido obligaros?"}, {"type": "p", "text": "ELISA. No, Valerio; no puedo arrepentirme de todo cuanto hago por vos. Me siento movida a ello por un poder demasiado dulce, y no tengo siquiera fuerza para desear que las cosas no sucedieran así. Mas, a deciros verdad, el buen fin me causa inquietud, y temo grandemente amaros algo más de lo que debiera."}, {"type": "p", "text": "VALERIO. ¡Eh! ¿Qué podéis temer, Elisa, de las bondades que habéis tenido conmigo? ELISA. ¡Ah! Cien cosas a la vez; el arrebato de un padre, los reproches de una familia, las censuras del mundo; pero más que nada, Valerio, la mudanza de vuestro corazón y esa frialdad criminal con la que los de vuestro sexo pagan las más de las veces los testimonios demasiado ardientes de un amor inocente."}, {"type": "p", "text": "VALERIO. ¡Ah, no me hagáis el agravio de juzgarme por los demás! Creedme capaz de todo, Elisa, menos de faltar a lo que os debo. Os amo en demasía para eso, y mi amor por vos durará tanto como mi vida."}, {"type": "p", "text": "ELISA. ¡AH, Valerio! ¡Todos dicen lo mismo! Todos los hombres son semejantes por sus palabras; y son tan sólo sus acciones las que los muestran diferentes. VALERIO. Puesto que únicamente las acciones revelan lo que somos, esperad entonces, al menos, a juzgar de mi corazón por ellas, y no queráis buscar crímenes en los injustos temores de una enojosa previsión. No me asesinéis, os lo ruego, con las sensibles acometidas de una sospecha ultrajante, y dadme tiempo para convenceros, con mil y mil pruebas, de la honradez de mi pasión."}, {"type": "p", "text": "ELISA. ¡Ay! ¡Con qué facilidad se deja una persuadir por las personas a quienes ama! Sí, Valerio; juzgo a vuestro corazón incapaz de engañarme. Creo que me amáis con verdadero amor y que me seréis fiel; no quiero dudar de ello en modo alguno, y limito mi pesar al temor de las censuras que puedan hacerme."}, {"type": "p", "text": "VALERIO. Mas ¿por qué esa inquietud?"}, {"type": "p", "text": "ELISA. No tendría nada que temer si todo el mundo os viera con los ojos con que os miro; y encuentro en vuestra persona motivos para hacer las cosas que por vos hago. Mi corazón tiene en su defensa todo vuestro mérito, fortalecido por la gratitud a que el Cielo me empeña con vos. Me represento en todo momento ese peligro extraño que comenzó por enfrentarnos a nuestras mutuas miradas; esa generosidad sorprendente que os hizo arriesgar la vida para salvar la mía del furor de las ondas; esos tiernos cuidados que me prodigasteis después de haberme sacado del agua, y los homenajes asiduos de este ardiente amor que ni el tiempo ni las dificultades han entibiado y que, haciéndoos olvidar padres y patria, detiene vuestros pasos en estos lugares, mantiene aquí, en favor mío, vuestra fortuna encubierta, y os obliga, para verme, a ocupar el puesto de criado de mi padre. Todo esto produce en mí, sin duda, un efecto maravilloso, y ello basta a mis ojos para justificar la promesa a que he consentido; mas no es suficiente, tal vez, para justificarla ante los demás, y no estoy segura de que no intervengan en mis sentimientos."}, {"type": "p", "text": "VALERIO. De todo cuanto habéis dicho, tan sólo por mi amor pretendo, con vos, merecer algo; y en cuanto a los escrúpulos que sentís, vuestro propio padre os justifica sobradamente ante todo el mundo; su excesiva avaricia y el modo austero de vivir con sus hijos podrían autorizar cosas más extrañas. Perdonadme, encantadora Elisa, si hablo así ante vos. Ya sabéis que a ese respecto no se puede decir nada bueno. Mas, en fin, si puedo, como espero, encontrar a mis padres, no nos costará mucho trabajo hacérnosle propicio. Espero noticias de ellos con impaciencia, y yo mismo iré a buscarlas si tardan en llegar."}, {"type": "p", "text": "ELISA. ¡Ah, Valerio! No os mováis de aquí, os lo ruego, y pensad tan sólo en situaros favorablemente en el ánimo de mi padre."}, {"type": "p", "text": "VALERIO. Ya veis cómo me las compongo y las hábiles complacencias que he debido emplear para introducirme en su servidumbre; bajo qué máscara de simpatía y de sentimientos adecuados me disfrazo para agradarle, y qué personaje represento a diario con él a fin de lograr su afecto. Hago en ello progresos admirables, y veo que, para conquistar a los hombres, no hay mejor camino que adornarse, a sus ojos, con sus inclinaciones, convenir en sus máximas, ensalzar sus defectos y aplaudir cuanto hacen. Por mucho que se exagere la complacencia y por visible que sea la manera de engañarlos, los más ladinos son grandes incautos ante el halago, y no hay nada tan impertinente y tan ridículo que no se haga tragar cuando se lo sazona con alabanzas. La sinceridad padece un poco con el oficio que realizo; mas cuando necesita uno a los hombres, hay que adaptarse a ellos, y ya que no puede conquistárselos más que por ese medio, no es culpa de los que adulan, sino de los que quieren ser adulados. ELISA. Mas ¿por qué intentáis conseguir también el apoyo de mi hermano, en caso de que a la sirvienta se le ocurriera revelar nuestro secreto?"}, {"type": "p", "text": "VALERIO. No se puede contentar a uno y a otro; y el espíritu del padre y del hijo son tan opuestos, que es difícil concertar esas dos confianzas. Mas vos, por vuestra parte, influid sobre vuestro hermano y servíos de la amistad que hay entre vosotros dos para ponerle de nuestra parte. Aquí viene. Me retiro. Emplead este tiempo en hablarle, y no le reveléis nuestro negocio sino lo que os parezca oportuno."}, {"type": "p", "text": "ELISA. No sé si tendré fuerzas para hacerle esa confesión."}]$lira$::jsonb, 983);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 2, 'Acto primero · Escena II', $lira$[{"type": "p", "text": "CLEANTO y ELISA"}, {"type": "p", "text": "CLEANTO. Me complace mucho encontraros sola, hermana mía, y ardía en deseos de hablaros para descubriros un secreto."}, {"type": "p", "text": "ELISA. Heme dispuesta a escucharos, hermano. ¿Qué tenéis que decirme?"}, {"type": "p", "text": "CLEANTO. Muchas cosas, hermana mía, envueltas en una palabra: amo."}, {"type": "p", "text": "ELISA. ¿Amáis?"}, {"type": "p", "text": "CLEANTO. Sí, amo. Mas, antes de seguir, ya sé que dependo de un padre y que el nombre de hijo me somete a sus voluntades; que no debemos empeñar nuestra palabra sin el consentimiento de los que nos dieron la vida; que el Cielo les ha hecho dueños de nuestros deseos, y que nos está ordenado no disponer de ellos sino por su gobierno; que, al no hallarse influidos por ningún loco ardor, están en disposición de errar bastante menos que nosotros y de ver mucho mejor lo que nos conviene; que debe prestarse más crédito a las luces de su prudencia que a la ceguera de nuestra pasión, y que el arrebato de la juventud nos arrastra, con frecuencia, a enojosos precipicios. Os digo todo esto, hermana mía, para que no os toméis el trabajo de decírmelo, ya que, en fin, mi amor no quiere oír nada, y os ruego que no me reprendáis."}, {"type": "p", "text": "ELISA. ¿Os habéis comprometido, hermano mío, con la que amáis?"}, {"type": "p", "text": "CLEANTO. No; mas estoy decidido a hacerlo, y os emplazo, una vez más, a que no aleguéis razones para disuadirme de ello."}, {"type": "p", "text": "ELISA. ¿Soy, hermano, una persona tan rara?"}, {"type": "p", "text": "CLEANTO. No, hermana mía; mas no amáis. Desconocéis la dulce violencia que ejerce un tierno amor sobre nuestros corazones, y temo a vuestra cordura."}, {"type": "p", "text": "ELISA. ¡Ah, hermano mío! No hablemos de mi cordura; no hay nadie que no la tenga, por lo menos, una vez en su vida; y si os abro mi corazón, quizá sea a vuestros ojos mucho menos cuerda que vos."}, {"type": "p", "text": "CLEANTO. ¡Ah! Pluguiese al Cielo que vuestra alma, como la mía..."}, {"type": "p", "text": "ELISA. Terminemos antes vuestro negocio y decidme quién es la que amáis. CLEANTO. Una joven que habita desde hace poco en estos arrabales, y que parece haber sido creada para enamorar a todos cuantos la ven. La Naturaleza, hermana mía, no ha hecho nada más adorable, y me sentí embelesado desde el momento en que la vi. Llámase Mariana y vive bajo el gobierno de una buena madre, que está casi siempre enferma y por quien esta amable joven experimenta unos sentimientos de cariño inimaginables. La sirve, la compadece y la consuela con una ternura que conmovería vuestra alma. Se dedica con el aire más encantador del mundo a las cosas que hace, y se ven brillar mil gracias en todas sus acciones, una dulzura llena de hechizos, una bondad muy atrayente, una honestidad adorable, una... ¡Ah, hermana mía, quisiera que la hubierais visto!"}, {"type": "p", "text": "ELISA. Mucho veo ya, hermano mío, en las cosas que me decís; y para comprender lo que es, me basta con que la améis."}, {"type": "p", "text": "CLEANTO. He descubierto secretamente que no están en muy buena posición, y que a su discreta manera de vivir le es difícil atender a todas las necesidades con el peculio que puedan tener. Figuraos, hermana mía, la dicha que puede existir en rehacer la fortuna del ser amado, en aportar hábilmente algún pequeño socorro a las modestas necesidades de una virtuosa familia, e imaginad el disgusto que para mí representa ver que, por la avaricia de un padre, estoy en la imposibilidad de gozar esa dicha y de dar a esta beldad alguna prueba de mi amor."}, {"type": "p", "text": "ELISA. Sí; me imagino con bastante claridad cuál debe ser vuestro pesar. CLEANTO. ¡Ah, hermana mía! Es mayor de lo que pudiera creerse, ya que..., en fin, ¿cabe nada más cruel que ese riguroso ahorro que se realiza a costa nuestra, que esta extraña sequedad en que se nos hace languidecer? ¡Eh! ¿De qué nos servirá tener un caudal si no ha de llegar a nosotros hasta en la época en que no estemos ya en edad de gozar de él, y si hasta para mantenerme tengo ahora que entramparme por todos lados, si me veo obligado, lo mismo que vos, a recurrir diariamente a los mercaderes para poder llevar unas ropas decentes? En fin, he querido hablaros para que me ayudéis a sondear a mi padre sobre esos sentimientos que me embargan, y si le encuentro opuesto a ellos, he decidido marchar a otros lugares con esa amable persona a gozar de la suerte que el Cielo quiera ofrecernos. Y con tal propósito hago buscar por todas partes dinero a préstamo; y si vuestros negocios, hermana mía, son parecidos a los míos y ha de oponerse nuestro padre a nuestros deseos, le abandonaremos ambos sin dilación y nos libertaremos de esta tiranía en que nos tiene desde hace tanto tiempo su avaricia insoportable."}, {"type": "p", "text": "ELISA. Verdad es que todos los días nos da más y más motivos para deplorar la muerte de nuestra madre, y que..."}, {"type": "p", "text": "CLEANTO. Oigo su voz; alejémonos un poco para terminar nuestra confidencia, y uniremos después nuestras fuerzas para venir a atacar la crueldad de su ánimo."}]$lira$::jsonb, 838);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 3, 'Acto primero · Escena III', $lira$[{"type": "p", "text": "HARPAGÓN y FLECHA"}, {"type": "p", "text": "HARPAGÓN. ¡Fuera de aquí al momento y que no se me replique! Vamos, toma el pendingue de mi casa, gran maese fullero, verdadera carne de horca."}, {"type": "p", "text": "FLECHA. (Aparte.) No he visto nunca nada tan perverso como este maldito viejo; y creo, con perdón, que tiene el demonio en el cuerpo."}, {"type": "p", "text": "HARPAGÓN. ¿Refunfuñas entre dientes?"}, {"type": "p", "text": "FLECHA. ¿Por qué me echáis?"}, {"type": "p", "text": "HARPAGÓN. ¿Vas a pedirme explicaciones tú, so bigardo? Sal de prisa, antes que te acogote."}, {"type": "p", "text": "FLECHA. ¿Qué os he hecho?"}, {"type": "p", "text": "HARPAGÓN. Pues me has hecho... desear que te marches."}, {"type": "p", "text": "FLECHA. Mi amo, vuestro hijo me ha ordenado esperarle."}, {"type": "p", "text": "HARPAGÓN. Vete a esperarle a la calle y no permanezcas en mi casa, plantado como un poste, observando lo que pasa y aprovechándote de todo. No quiero tener delante sin cesar un espía de mis negocios, un traidor cuyos condenados ojos asedian todos mis actos, devoran lo que poseo y huronean por todos lados para ver si hay algo que robar. FLECHA. ¿Cómo diantre queréis que se las compongan para robaros? ¿Sois un hombre robable cuando todo lo encerráis y estáis de centinela día y noche?"}, {"type": "p", "text": "HARPAGÓN. Quiero encerrar lo que se me antoja y estar de centinela como me plazca. ¿No hay soplones que se preocupan de lo que uno hace? (Bajo, aparte.) Tiemblo por si habrá sospechado algo de mi dinero. (Alto.) ¿No eres tú de esos hombres que corren el rumor de que tengo dinero en mi casa?"}, {"type": "p", "text": "FLECHA. ¿Tenéis dinero escondido?"}, {"type": "p", "text": "HARPAGÓN. No, pillo, no; no digo eso. (Aparte.) Me sofoca la rabia. (Alto.) Pregunto si no vas por ahí haciendo correr maliciosamente el rumor de que lo tengo. FLECHA. ¡Eh! ¿Qué nos importa que lo tengáis o que no lo tengáis, si para nosotros es lo mismo?"}, {"type": "p", "text": "HARPAGÓN. (Levantando la mano para dar un bofetón a Flecha.) ¡Te las echas de razonador! Ya te daré yo razonamiento en las orejas. Sal de aquí, repito. FLECHA. ¡Bueno! Me marcharé."}, {"type": "p", "text": "HARPAGÓN. Espera. ¿No te llevas nada?"}, {"type": "p", "text": "FLECHA. ¿Qué voy a llevarme?"}, {"type": "p", "text": "HARPAGÓN. Anda, ven aquí que lo vea. Enséñame las manos."}, {"type": "p", "text": "FLECHA. Aquí están."}, {"type": "p", "text": "HARPAGÓN. Las otras."}, {"type": "p", "text": "FLECHA. ¿Las otras?"}, {"type": "p", "text": "HARPAGÓN. Sí."}, {"type": "p", "text": "FLECHA. Aquí están."}, {"type": "p", "text": "HARPAGÓN. (Señalando las calzas de Flecha.) ¿No has metido nada ahí dentro? FLECHA. Vedlo vos mismo."}, {"type": "p", "text": "HARPAGÓN. (Palpando las calzas de Flecha.) Estas anchas calzas son apropiadas para convertirse en ocultadoras de las cosas robadas, y quisiera yo que hubieran ahorcado a alguien por eso."}, {"type": "p", "text": "FLECHA. (Aparte.) ¡Ah, cómo se merecía un hombre así lo que teme! ¡Y qué gozo tendría yo en robarle!"}, {"type": "p", "text": "HARPAGÓN. ¿Eh?"}, {"type": "p", "text": "FLECHA. ¿Cómo?"}, {"type": "p", "text": "HARPAGÓN. ¿Qué hablas de robar?"}, {"type": "p", "text": "FLECHA. Os decía que registraseis bien por todas partes para ver si os he robado. HARPAGÓN. Eso es lo que quiero hacer. (Harpagón registra los bolsillos de Flecha.) FLECHA. (Aparte.) ¡Mal haya la avaricia y los avarientos!"}, {"type": "p", "text": "HARPAGÓN. ¿Cómo? ¿Qué dices?"}, {"type": "p", "text": "FLECHA. ¿Qué digo?"}, {"type": "p", "text": "HARPAGÓN. Sí. ¿Qué dices de avaricia y de avarientos?"}, {"type": "p", "text": "FLECHA. Digo que mal haya la avaricia y los avarientos."}, {"type": "p", "text": "HARPAGÓN. ¿A quién te refieres?"}, {"type": "p", "text": "FLECHA. A los avarientos."}, {"type": "p", "text": "HARPAGÓN. ¿Y quiénes son esos avarientos?"}, {"type": "p", "text": "FLECHA. Unos ruines y unos miserables."}, {"type": "p", "text": "HARPAGÓN. Mas, ¿a quién te refieres?"}, {"type": "p", "text": "FLECHA. ¿Por qué os preocupáis de ellos?"}, {"type": "p", "text": "HARPAGÓN. Me preocupo de lo que debo."}, {"type": "p", "text": "FLECHA. ¿Creéis, acaso, que me refiero a vos?"}, {"type": "p", "text": "HARPAGÓN. Creo lo que creo; mas quiero que me digas a quién hablas al decir eso. FLECHA. Pues hablo..., hablo para mi capote."}, {"type": "p", "text": "HARPAGÓN. Y yo podría hablar para tu gorro."}, {"type": "p", "text": "FLECHA. ¿Vais a impedir que maldiga a los avarientos?"}, {"type": "p", "text": "HARPAGÓN. No; mas te impediré cotorrear y ser insolente. Cállate."}, {"type": "p", "text": "FLECHA. Yo no nombro a nadie."}, {"type": "p", "text": "HARPAGÓN. Te apalearé si hablas."}, {"type": "p", "text": "FLECHA. A quien le pique, que se rasque."}, {"type": "p", "text": "HARPAGÓN. ¿Te callarás?"}, {"type": "p", "text": "FLECHA. Sí, aunque me pese."}, {"type": "p", "text": "HARPAGÓN. ¡Ja, ja!"}, {"type": "p", "text": "FLECHA. (Mostrando a Harpagón uno de los bolsillos de su ropilla.) Mirad: aquí hay otro bolsillo. ¿Estáis satisfecho?"}, {"type": "p", "text": "HARPAGÓN. Vamos, devuélvemelo sin registrarte."}, {"type": "p", "text": "FLECHA. ¿El qué?"}, {"type": "p", "text": "HARPAGÓN. Lo que me has quitado."}, {"type": "p", "text": "FLECHA. Yo no os he quitado nada absolutamente."}, {"type": "p", "text": "HARPAGÓN. ¿De veras?"}, {"type": "p", "text": "FLECHA. De veras."}, {"type": "p", "text": "HARPAGÓN. Adiós. Vete al diablo."}, {"type": "p", "text": "FLECHA. (Aparte.) Buena despedida."}, {"type": "p", "text": "HARPAGÓN. ¡A tu conciencia lo dejo cuando menos!"}]$lira$::jsonb, 686);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 4, 'Acto primero · Escena IV', $lira$[{"type": "p", "text": "HARPAGÓN, solo HARPAGÓN. Este bigardo de criado me molesta mucho; no me gusta nada ver a este condenado cojitranco. En verdad, no es poco trabajo el de guardar en casa una gran suma de dinero, y bienaventurados aquellos que tienen su caudal bien colocado ¡y no conservan más que lo necesario para su gasto! Bastante trastorno es éste de tener que inventar, en toda una casa, un escondite fiel; pues, por mi parte, las cajas fuertes me resultan sospechosas, y no quiero nunca fiarme de ellas. Me parece realmente un claro cebo para los ladrones, y es siempre lo primero que éstos van a atacar."}]$lira$::jsonb, 105);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 5, 'Acto primero · Escena V', $lira$[{"type": "p", "text": "HARPAGÓN, ELISA y CLEANTO. Hablando juntos,"}, {"type": "p", "text": "permanecen en el fondo de la escena"}, {"type": "p", "text": "HARPAGÓN. (Creyéndose solo.) Sin embargo, no sé si habré hecho bien enterrando en mi jardín los diez mil escudos que me devolvieron ayer. Diez mil escudos de oro en casa de uno son una suma bastante... (Aparte, al ver a Elisa y a Cleanto.) ¡Oh, cielos! ¿Me habré traicionado a mí mismo? ¡ Arrebatado por el furor, creo que he hablado en voz alta al razonar a solas! (A Cleanto y a Elisa.) ¿Qué pasa?"}, {"type": "p", "text": "CLEANTO. Nada, padre."}, {"type": "p", "text": "HARPAGÓN. ¿Hace mucho que estáis ahí?"}, {"type": "p", "text": "ELISA. Acabamos de llegar."}, {"type": "p", "text": "HARPAGÓN. ¿Habéis oído?"}, {"type": "p", "text": "CLEANTO. ¿El qué, padre mío?"}, {"type": "p", "text": "HARPAGÓN. Eso..."}, {"type": "p", "text": "ELISA. ¿Qué?"}, {"type": "p", "text": "HARPAGÓN. Lo que acabo de decir."}, {"type": "p", "text": "CLEANTO. No."}, {"type": "p", "text": "HARPAGÓN. Sí tal."}, {"type": "p", "text": "ELISA. Perdonadme."}, {"type": "p", "text": "HARPAGÓN. Ya veo que habéis oído algunas palabras. Es que pensaba, en mi interior, lo difícil que es hoy día encontrar dinero, y decía que dichoso el que puede tener diez mil escudos en su casa."}, {"type": "p", "text": "CLEANTO. Vacilábamos en abordaros, temiendo interrumpiros."}, {"type": "p", "text": "HARPAGÓN. Me satisface deciros esto, para que no vayáis a tomar las cosas al revés y a imaginaros que decía yo que tengo diez mil escudos."}, {"type": "p", "text": "CLEANTO. No nos metemos en vuestros negocios."}, {"type": "p", "text": "HARPAGÓN. ¡Pluguiera al Cielo que tuviese yo esos diez mil escudos!"}, {"type": "p", "text": "CLEANTO. No creo."}, {"type": "p", "text": "HARPAGÓN. Sería un buen negocio para mí..."}, {"type": "p", "text": "ELISA. Son cosas..."}, {"type": "p", "text": "HARPAGÓN. Buena falta me harían."}, {"type": "p", "text": "CLEANTO. Yo creo que..."}, {"type": "p", "text": "HARPAGÓN. Eso me arreglaría, en verdad."}, {"type": "p", "text": "ELISA. Sois..."}, {"type": "p", "text": "HARPAGÓN. Y no me quejaría, como ahora, de que los tiempos son míseros. CLEANTO. ¡Dios mío! ¡Padre, no tenéis motivos para quejaros, y ya se sabe que poseéis bastante caudal!"}, {"type": "p", "text": "HARPAGÓN. ¡Cómo! ¿Que tengo bastante caudal? Quienes lo digan mienten. No hay nada más falso, y son unos bribones los que hacen correr todos esos rumores. ELISA. No os encolericéis."}, {"type": "p", "text": "HARPAGÓN. Es singular que mis propios hijos me traicionen y se conviertan en enemigos míos."}, {"type": "p", "text": "CLEANTO. ¿Es ser enemigo vuestro el decir que tenéis caudal?"}, {"type": "p", "text": "HARPAGÓN. Sí. Tales discursos y los gastos que hacéis serán la causa de que uno de estos días vengan a mi casa a cortarme el cuello, con la idea de que estoy forrado de doblones."}, {"type": "p", "text": "CLEANTO. ¿Qué gran gasto hago yo?"}, {"type": "p", "text": "HARPAGÓN. ¿Cuál? ¿Hay nada más escandaloso que ese suntuoso boato que paseáis por la ciudad? Reñía ayer a vuestra hermana; mas hay algo peor. Esto sí que clama al Cielo; y si se os despojase desde los pies a la cabeza, habría con ello para constituir una buena renta. Ya os he dicho veinte veces, hijo mío, que todas vuestras maneras me desagradan grandemente; sentís una afición desmedida a echároslas de marqués, y para ir vestido así, preciso es que me robéis."}, {"type": "p", "text": "CLEANTO. ¡Eh! ¿Y cómo robaros?"}, {"type": "p", "text": "HARPAGÓN. ¡Y qué sé yo! ¿De dónde sacáis para sostener el vestuario que lleváis? CLEANTO. ¿Yo, padre mío? Es que juego, y, como soy muy afortunado, gasto en mí todo el dinero que gano."}, {"type": "p", "text": "HARPAGÓN. Muy mal hecho. Si sois afortunado en el juego, deberíais sacar provecho de ello y colocar a un interés decente el dinero que ganáis, a fin de encontrároslo algún día. Quisiera yo saber, para no referirme a lo demás, de qué sirven todas esas cintas con que vais cubierto de pies a cabeza y si media docena de agujetas no bastan para sostener unas calzas. ¿Es muy necesario gastar dinero en pelucas cuando pueden llevarse cabellos propios que no cuestan nada? Apostaría a que en pelucas y cintas hay, por lo menos, veinte pistolas, y veinte pistolas rentan al año dieciocho libras, seis sueldos y ocho denarios con sólo colocarlas al doce por ciento."}, {"type": "p", "text": "CLEANTO. Tenéis razón."}, {"type": "p", "text": "HARPAGÓN. Dejemos eso y hablemos de otra cosa. (Sorprendiendo a Cleanto y a Elisa, que se hacen señas.) ¡Eh! (Bajo, aparte.) Me parece que se hacen señas uno a otro para robarme mi bolsa. (Alto.) ¿Qué quieren decir esos gestos?"}, {"type": "p", "text": "ELISA. Dudamos mi hermano y yo en quién hablará primero; los dos tenemos algo que deciros."}, {"type": "p", "text": "HARPAGÓN. Yo también tengo que deciros algo a los dos."}, {"type": "p", "text": "CLEANTO. Deseamos hablaros de matrimonio, padre."}, {"type": "p", "text": "HARPAGÓN. Y yo también quiero hablaros de matrimonio."}, {"type": "p", "text": "ELISA. ¡Ah, padre mío!"}, {"type": "p", "text": "HARPAGÓN. ¿Por qué ese grito? ¿Es la palabra o la cosa lo que os atemoriza, hija mía?"}, {"type": "p", "text": "CLEANTO. El matrimonio puede atemorizarnos a los dos, de la manera que podéis entenderlo, y tememos que nuestros sentimientos no estén de acuerdo con vuestra elección."}, {"type": "p", "text": "HARPAGÓN. Un poco de paciencia; no os alarméis. Sé lo que os es necesario a los dos, y no tendréis, ni uno ni otra, motivo de queja con lo que pretendo hacer; y para empezar por este lado (a Cleanto), ¿habéis visto, decidme, una joven llamada Mariana, que habita no lejos de aquí?"}, {"type": "p", "text": "CLEANTO. Sí, padre mío."}, {"type": "p", "text": "HARPAGÓN. ¿Y vos?"}, {"type": "p", "text": "ELISA. He oído hablar de ella."}, {"type": "p", "text": "HARPAGÓN. ¿Cómo encontráis a esa joven, hijo mío?"}, {"type": "p", "text": "CLEANTO. La encuentro encantadora."}, {"type": "p", "text": "HARPAGÓN. ¿Y su fisonomía?"}, {"type": "p", "text": "CLEANTO. Muy honesta y llena de talento."}, {"type": "p", "text": "HARPAGÓN. ¿Su aspecto y sus maneras?"}, {"type": "p", "text": "CLEANTO. Admirables, sin duda."}, {"type": "p", "text": "HARPAGÓN. ¿No creéis que una joven así merecería que se pensase en ella? CLEANTO. Sí, padre mío."}, {"type": "p", "text": "HARPAGÓN. ¿Y que sería un partido deseable?"}, {"type": "p", "text": "CLEANTO. Muy deseable."}, {"type": "p", "text": "HARPAGÓN. ¿Que tiene aspecto de ser una buena esposa?"}, {"type": "p", "text": "CLEANTO. Sin duda."}, {"type": "p", "text": "HARPAGÓN. ¿Y que se hallaría satisfecho con ella un marido?"}, {"type": "p", "text": "CLEANTO. Seguramente."}, {"type": "p", "text": "HARPAGÓN. Hay una pequeña dificultad, y es que tengo miedo de que no se consiga con ella todo el caudal que podría pretenderse."}, {"type": "p", "text": "CLEANTO. ¡Ah, padre mío! ¡No debe considerarse el caudal cuando se trata de casarse con una persona honrada!"}, {"type": "p", "text": "HARPAGÓN. Perdonadme, perdonadme. Mas lo que hay que decir es que si no se encuentra con ella todo el caudal que se desea, puede uno intentar resarcirse en otra cosa."}, {"type": "p", "text": "CLEANTO. Se comprende."}, {"type": "p", "text": "HARPAGÓN. En fin, me satisface ver que compartís mi opinión, pues su honesta apostura y su bondad han conquistado mi alma, y estoy resuelto a casarme con ella, con tal que posea algún caudal."}, {"type": "p", "text": "CLEANTO. ¿Eh?"}, {"type": "p", "text": "HARPAGÓN. ¿Cómo?"}, {"type": "p", "text": "CLEANTO. ¿Estáis resuelto, decís, a...?"}, {"type": "p", "text": "HARPAGÓN. A casarme con Mariana."}, {"type": "p", "text": "CLEANTO. ¿Quién? ¿Vos, vos?"}, {"type": "p", "text": "HARPAGÓN. ¡Sí, yo, yo, yo! ¿Qué quiere decir esto?"}, {"type": "p", "text": "CLEANTO. Me acomete de pronto un vahído, y me retiro de aquí.."}, {"type": "p", "text": "HARPAGÓN. No será nada; id pronto a beber un vaso de agua clara a la cocina."}]$lira$::jsonb, 1047);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 6, 'Acto primero · Escena VI', $lira$[{"type": "p", "text": "HARPAGÓN y ELISA"}, {"type": "p", "text": "HARPAGÓN. Ved estos donceles alfeñiques, que tienen el vigor de unas gallinas. Esto es lo que he resuelto, hija mía, por mi parte. Respecto a tu hermano, le destino cierta viuda de la que han venido a hablarme esta mañana, y en cuanto a ti, te destino al señor Anselmo."}, {"type": "p", "text": "ELISA. ¿Al señor Anselmo?"}, {"type": "p", "text": "HARPAGÓN. Sí; un hombre maduro, cuerdo y prudente, que no tiene más de cincuenta años y cuyo caudal es muy alabado."}, {"type": "p", "text": "ELISA. (Haciendo una reverencia.) No quiero casarme, padre mío, si os place. HARPAGÓN. (Imitando a Elisa.) Y yo, hijita mía querida, quiero que os caséis, si os place."}, {"type": "p", "text": "ELISA. (Haciendo una reverencia.) Os pido perdón, padre mío."}, {"type": "p", "text": "HARPAGÓN. (Imitando a Elisa.) Os pido perdón, hija mía."}, {"type": "p", "text": "ELISA. Soy la humildísima servidora del señor Anselmo; pero (haciendo otra reverencia), con vuestro permiso, no me casaré con él."}, {"type": "p", "text": "HARPAGÓN. Soy vuestro humildísimo servidor; pero (imitando a Elisa), os casaréis con él esta noche."}, {"type": "p", "text": "ELISA. ¿Esta noche?"}, {"type": "p", "text": "HARPAGÓN. Esta noche."}, {"type": "p", "text": "ELISA. (Haciendo otra reverencia.) No sucederá tal, padre mío."}, {"type": "p", "text": "HARPAGÓN. (Imitando a Elisa.) Sí sucederá tal, hija mía."}, {"type": "p", "text": "ELISA. No."}, {"type": "p", "text": "HARPAGÓN. Sí. ELISA. Os"}, {"type": "p", "text": "digo que no. HARPAGÓN. Os"}, {"type": "p", "text": "digo que sí."}, {"type": "p", "text": "ELISA. Es una cosa a la que no me obligaréis."}, {"type": "p", "text": "Harpagón. Es una cosa a la que te obligaré."}, {"type": "p", "text": "ELISA. Me mataré antes que casarme con semejante marido."}, {"type": "p", "text": "HARPAGÓN. No te matarás y será tu marido. ¡Qué osadía! ¿Se ha visto nunca a una hija hablar así a su padre?"}, {"type": "p", "text": "ELISA. ¿Y se ha visto nunca a un padre casar así a su hija?"}, {"type": "p", "text": "HARPAGÓN. Es un partido del que no hay nada que decir, y apuesto a que todo el mundo aprobará mi elección."}, {"type": "p", "text": "ELISA. Y yo apuesto a que no puede aprobarlo ninguna persona razonable. HARPAGÓN. (Viendo a Valerio, desde lejos.) Aquí está Valerio. ¿Quieres que le hagamos juez de este negocio?"}, {"type": "p", "text": "ELISA. Accedo a ello."}, {"type": "p", "text": "HARPAGÓN. ¿Te atendrás a su juicio?"}, {"type": "p", "text": "ELISA. Sí; pasaré por lo que él diga."}, {"type": "p", "text": "HARPAGÓN. Pues hecho."}]$lira$::jsonb, 332);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 7, 'Acto primero · Escena VII', $lira$[{"type": "p", "text": "VALERIO, HARPAGÓN y ELISA"}, {"type": "p", "text": "HARPAGÓN. Ven aquí, Valerio. Te hemos elegido para que nos digas quién tiene razón, si mi hija o yo."}, {"type": "p", "text": "VALERIO. Vos, señor, sin disputa."}, {"type": "p", "text": "HARPAGÓN. ¿Sabes de lo que hablamos?"}, {"type": "p", "text": "VALERIO. No. Mas no podéis equivocaros, y toda la razón será vuestra."}, {"type": "p", "text": "HARPAGÓN. Quiero esta noche darle por esposo un hombre tan rico como probo, y la pícara me dice en mis narices que no lo acepta. ¿Qué te parece?"}, {"type": "p", "text": "VALERIO. ¿Qué me parece?"}, {"type": "p", "text": "HARPAGÓN. Sí."}, {"type": "p", "text": "VALERIO. ¡Vaya, vaya!"}, {"type": "p", "text": "HARPAGÓN. ¿Cómo?"}, {"type": "p", "text": "VALERIO. Digo que, en el fondo, soy de vuestro parecer, y es imposible que no tengáis razón. Aunque también no es ella culpable del todo y..."}, {"type": "p", "text": "HARPAGÓN. ¿Cómo? El señor Anselmo es un partido notable; es un caballero noble, tierno, sentado, probo, muy rico y a quien no le queda ningún hijo de su primer matrimonio. ¿Qué mejor podría ella encontrar?"}, {"type": "p", "text": "VALERIO. Eso es cierto. Mas ella podría deciros que es precipitar un poco las cosas y que sería necesario cierto tiempo, al menos, para ver si su inclinación puede avenirse con..."}, {"type": "p", "text": "HARPAGÓN. Es una ocasión que hay que coger por los pelos. Encuentro en esto unas ventajas que no encontraría por otra parte; y se compromete a tomarla sin dote1... VALERIO. ¿Sin dote?"}, {"type": "p", "text": "HARPAGÓN. Sí."}, {"type": "p", "text": "VALERIO. ¡Ah! Entonces no digo nada. ¿Veis? Ésa es una razón absolutamente convincente; hay que inclinarse ante ello."}, {"type": "p", "text": "HARPAGÓN. Es para mí un ahorro considerable."}, {"type": "p", "text": "VALERIO. Seguramente; es innegable. Verdad es que vuestra hija puede alegar que el matrimonio es un negocio mucho más importante de lo que puede creerse; que va en él la felicidad o la desdicha para toda la vida, y que un compromiso que ha de durar hasta la muerte no debe efectuarse nunca sino con grandes precauciones."}, {"type": "p", "text": "HARPAGÓN. ¡Sin dote!"}, {"type": "p", "text": "VALERIO. Tenéis razón. Eso lo decide todo, ya se comprende. Hay gentes que podrían deciros que, en tales ocasiones, el amor de una joven es cosa que debe tenerse en cuenta y que esa gran diferencia de edad, de carácter y de sentimientos hace un matrimonio propenso a incidentes muy enojosos."}, {"type": "p", "text": "HARPAGÓN. ¡Sin dote!"}, {"type": "p", "text": "VALERIO. ¡Ah! Bien sabemos que eso no admite réplica. ¿Quién diantres puede oponerse a ello? No quiero decir que no existan muchos padres que prefieran atender a la satisfacción de sus hijas más que al dinero que pudieran entregar; que no quieren sacrificarlas al interés, y que procuran, más que nada, crear en un matrimonio esa tierna conformidad que mantiene en él sin cesar el honor, la tranquilidad y la alegría, y que... HARPAGÓN. ¡Sin dote!"}, {"type": "p", "text": "VALERIO. Es cierto; eso cierra la boca en absoluto. ¡Sin dote! ¡No hay modo de resistir a tal razón!"}, {"type": "p", "text": "HARPAGÓN. (Mirando hacia el jardín y aparte.) ¡Hola! Paréceme oír el ladrido de un perro. ¿No estará amenazado mi dinero? (A Valerio.) No os mováis; vuelvo al instante. (Vase.)"}]$lira$::jsonb, 474);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 8, 'Acto primero · Escena VIII', $lira$[{"type": "p", "text": "ELISA y VALERIO"}, {"type": "p", "text": "ELISA. ¿ Queréis chancearos2, Valerio, hablándole así?"}, {"type": "p", "text": "VALERIO. Era para no enojarle y por lograr mejor éxito. Chocar de frente con su criterio sería el medio de echarlo todo a perder, y existen ciertos espíritus que sólo deben atacarse con rodeos; temperamentos enemigos de toda resistencia; caracteres reacios a los que encocora la verdad, que se rebelan siempre contra el camino recto de la razón y a los que sólo se puede llevar con rodeos a donde quiere uno conducirlos. Fingid que accedéis a lo que él quiere; conseguiréis mejor vuestro fin, y... ELISA. Pero ¿y ese casamiento, Valerio?"}, {"type": "p", "text": "VALERIO. Ya buscaremos medios para desbaratarlo."}, {"type": "p", "text": "ELISA. Mas ¿qué inventaremos, si ha de efectuarse esta noche?"}, {"type": "p", "text": "VALERIO. Hay que solicitar un aplazamiento y fingir alguna enfermedad."}, {"type": "p", "text": "ELISA. Pero descubrirán el engaño si llaman a los médicos."}, {"type": "p", "text": "VALERIO. ¿Os chanceáis? ¿Es que los galenos saben algo? Vamos, vamos; con ellos podéis tener la dolencia que os plazca; encontrarán razones para deciros de qué proviene."}]$lira$::jsonb, 165);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 9, 'Acto primero · Escena IX', $lira$[{"type": "p", "text": "HARPAGÓN, ELISA y VALERIO"}, {"type": "p", "text": "HARPAGÓN. (Aparte, al fondo de la escena.) No era nada, a Dios gracias. VALERIO. (Sin ver a Harpagón.) En fin, nuestro último recurso es que la fuga puede ponernos a cubierto de todo; y si vuestro amor, bella Elisa, es capaz de tener entereza... (Viendo a Harpagón.) Sí; una hija tiene que obedecer a su padre. No debe mirar cómo está hecho un marido; y cuando la gran razón de sin dote coincide en ello, debe estar dispuesta a aceptar cuanto le den."}, {"type": "p", "text": "HARPAGÓN. ¡Bueno! ¡Eso es hablar bien!"}, {"type": "p", "text": "VALERIO. Señor, os pido perdón si me acaloro un poco y tengo la osadía de hablarle así."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo! ¡Si eso me encanta y deseo que adquieras un influjo absoluto sobre ella! (A Elisa.) Sí; aunque intentes huir, le concedo la autoridad que el Cielo me da sobre ti y quiero que hagas todo cuanto él te diga."}, {"type": "p", "text": "VALERIO. (A Elisa.) Después de esto, ¡resistíos a mis amonestaciones!"}]$lira$::jsonb, 161);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 10, 'Acto primero · Escena X', $lira$[{"type": "p", "text": "HARPAGÓN y VALERIO"}, {"type": "p", "text": "VALERIO. Señor, voy a seguirla, para continuar con ella las lecciones que le estaba dando."}, {"type": "p", "text": "HARPAGÓN. Sí; te quedaré agradecido. Realmente..."}, {"type": "p", "text": "VALERIO. Es conveniente tirarle un poco de la brida."}, {"type": "p", "text": "HARPAGÓN. Ciertamente. Es preciso..."}, {"type": "p", "text": "VALERIO. Nos os preocupéis. Creo que conseguiré dominarla."}, {"type": "p", "text": "HARPAGÓN. Hazlo, hazlo. Voy a dar una vueltecita por la ciudad y vuelvo en seguida. VALERIO. (Dirigiéndose a Elisa y marchándose por donde ella salió.) Sí; el dinero es lo más preciado del mundo, y debéis dar gracias al Cielo por el digno padre que os ha concedido. Él sabe lo que es vivir. Cuando se ofrece uno a tomar a una joven sin dote, no se debe mirar más allá. Todo se encierra en eso; y sin dote equivale a belleza, juventud, alcurnia, honor, sapiencia y probidad."}, {"type": "p", "text": "HARPAGÓN. ¡Ah, qué buen mozo! Eso es hablar como un oráculo. ¡Dichoso aquel que puede tener un criado de este género!"}]$lira$::jsonb, 154);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 11, 'Acto segundo · Escena primera (1/2)', $lira$[{"type": "p", "text": "CLEANTO y FLECHA"}, {"type": "p", "text": "CLEANTO. ¡Ah, felón! ¿Dónde te has metido? ¿No te había yo mandado...?"}, {"type": "p", "text": "FLECHA. Sí, señor, y he venido aquí para esperaros a pie firme; pero vuestro señor padre, el más incivil de los hombres, me ha echado a la fuerza y he corrido el riesgo de ser apaleado."}, {"type": "p", "text": "CLEANTO. ¿Cómo va vuestro negocio? Las cosas urgen más que nunca, y, después de haberte visto, he descubierto que mi padre es mi rival."}, {"type": "p", "text": "FLECHA. ¿Vuestro padre enamorado?"}, {"type": "p", "text": "CLEANTO. Sí, y me ha costado gran trabajo ocultarle la turbación que me ha producido esa noticia."}, {"type": "p", "text": "FLECHA. ¡Él, dedicarse a amar! ¿En qué diablos piensa? ¿Se burla del mundo? ¿Y se ha hecho el amor para gentes como él?"}, {"type": "p", "text": "CLEANTO. Para castigo mío, se le ha metido en la cabeza esta pasión."}, {"type": "p", "text": "FLECHA. Mas ¿por qué razón le ocultáis vuestro amor?"}, {"type": "p", "text": "CLEANTO. Para no suscitar sus sospechas y reservarme, en caso necesario, medios más fáciles con los cuales desbaratar ese matrimonio. ¿Qué respuesta te han dado? FLECHA. A fe mía, señor, los que piden prestado son muy desgraciados; y hay que soportar cosas extrañas cuando se ve uno obligado, como vos, a pasar por las manos de unos usureros sin entrañas."}, {"type": "p", "text": "CLEANTO. ¿No se realizará el negocio?"}, {"type": "p", "text": "FLECHA. Perdonad. Nuestro maese Simón, el corredor que nos han dado, hombre activo y lleno de celo, dice que os ha tomado muy a pecho, y asegura que vuestra sola cara ha conquistado su corazón."}, {"type": "p", "text": "CLEANTO. ¿Tendré los quince mil francos que pido?"}, {"type": "p", "text": "FLECHA. Sí; mas con algunas pequeñas condiciones, que habréis de aceptar si deseáis que las cosas se lleven a efecto."}, {"type": "p", "text": "CLEANTO. ¿Te ha hecho hablar con el que debe prestar dinero?"}, {"type": "p", "text": "FLECHA. ¡Ah! Realmente, no es así. Pone él aún más cuidado que vos en ocultarse, y son estos misterios mayores de lo que pensáis. No quiere en modo alguno decir su nombre, y debe hoy reunirse con vos en una casa prestada, para informarse por vuestra propia boca sobre vuestro caudal y vuestra familia; y no dudo que el solo nombre de vuestro padre facilitará las cosas."}, {"type": "p", "text": "CLEANTO. Y, sobre todo, habiendo muerto nuestra madre, cuya herencia no pueden quitarme."}, {"type": "p", "text": "FLECHA. He aquí algunas cláusulas que él mismo ha dictado a nuestro intermediario para que os sean enseñadas antes de hacer nada: «Supuesto que el prestamista confirme todas sus garantías y que el prestatario sea mayor de edad y de una familia con caudal amplio, sólido, asegurado, claro y libre de toda traba, se extenderá un acta auténtica y exacta ante un notario que sea lo más honrado posible, y el cual, para esos efectos, será escogido por el prestamista, a quien interesa más que esa acta esté debidamente redactada.»"}, {"type": "p", "text": "CLEANTO. Nada hay que decir a esto."}, {"type": "p", "text": "FLECHA. «El prestamista, para no cargar su conciencia con ningún escrúpulo, pretende no dar su dinero más que al cinco y medio por ciento.»"}, {"type": "p", "text": "CLEANTO. ¿Al cinco y medio? ¡Pardiez! Eso es honrado. No puede uno quejarse. FLECHA. Es cierto. «Mas como el mencionado prestamista no tiene en su casa la suma de que se trata, y, para complacer al prestatario, se ve obligado él también a pedirla prestada a otro, sobre la base del veinte por ciento, convendrá que el referido primero prestatario abone ese interés, sin perjuicio del resto, considerando que sólo por complacerle el susodicho prestamista se compromete a ese préstamo.»"}, {"type": "p", "text": "CLEANTO. ¡Cómo, diablo! ¿Quién es ese árabe? Así resulta más del veinticinco por ciento."}, {"type": "p", "text": "FLECHA. Es cierto, y así lo he dicho. Tenéis que pensarlo."}]$lira$::jsonb, 587);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 12, 'Acto segundo · Escena primera (2/2)', $lira$[{"type": "p", "text": "CLEANTO. ¿Qué quieres que piense? Necesito dinero, y tengo que acceder a todo. FLECHA. Ésa ha sido mi respuesta."}, {"type": "p", "text": "CLEANTO. ¿Hay algo más?"}, {"type": "p", "text": "FLECHA. Escuchad. Se trata sólo de una pequeña cláusula: «De los quince mil francos solicitados, el prestamista no podrá entregar en dinero más que unas doce mil libras; y para los mil escudos restantes tendrá el prestatario que aceptar las ropas de vestir y de la casa, y las joyas, cuyo inventario va a continuación, y que el referido prestamista ha justipreciado, de buena fe, en el precio más módico que le ha sido posible.» CLEANTO. ¿Qué quiere decir eso?"}, {"type": "p", "text": "FLECHA. Escuchad el inventario: «Primeramente, un lecho de cuatro patas con cenefas de punto de Hungría, sobrepuestas con gran primor sobre una sábana color aceituna, con seis sillas y el cobertor de lo mismo; todo ello bien dispuesto y forrado de tafetán tornasolado rojo y azul. Más un dosel de cola, de buena sarga de Aumale, rosa seco, con el fleco y los galones de seda.»"}, {"type": "p", "text": "CLEANTO. ¿Qué quiere decir eso?"}, {"type": "p", "text": "FLECHA. Esperad: «Más un tapiz de los Amores de Gambaud y Macea. Más una gran mesa de nogal, de doce columnas o pilares torneados, que se alarga por los dos extremos, provista, además, de sus seis escabeles.»"}, {"type": "p", "text": "CLEANTO. ¿Con quién trato, pardiez?"}, {"type": "p", "text": "FLECHA. Tened paciencia. «Más tres grandes mosquetes guarnecidos de nácar de perlas, con las horquillas correspondientes haciendo juego. Más un horno de ladrillo, con dos retortas y tres recipientes, muy útiles para los aficionados a destilar.» CLEANTO. ¡Me sofoca la rabia!"}, {"type": "p", "text": "FLECHA. Calma. «Más un laúd de Bolonia, provisto de todas sus cuerdas o poco menos. Más un juego de boliches y un tablero para damas con un juego de la oca, modernizado desde los griegos, muy apropiado para pasar el tiempo cuando no se tiene nada que hacer. Más una piel de lagarto de tres pies y medio, rellena de heno, curiosidad agradable para colgar del techo de una estancia. Todo lo mencionado anteriormente vale honradamente más de cuatro mil quinientas libras, y queda rebajado a la suma de mil escudos, por consideración del prestamista.»"}, {"type": "p", "text": "CLEANTO. ¡Que se lleve el diablo con su consideración a ese traidor y verdugo! ¿Hase visto jamás usura semejante? Y, no contento con el enorme interés que exige, ¿quiere aún obligarme a aceptar por tres mil libras las inútiles antiguallas que ha recogido? No sacaré ni doscientos escudos por todo eso, y, sin embargo, tengo que pasar por lo que quiere, pues está en situación de hacérmelo aceptar todo y me pone, el bandido, el puñal en el cuello."}, {"type": "p", "text": "FLECHA. Os veo, señor, aunque ello os desagrade, tomar el mismo camino que seguía Panurgo para arruinarse, tomando dinero anticipado, comprando caro, vendiendo barato y dilapidando su hacienda por adelantado."}, {"type": "p", "text": "CLEANTO. ¿Y qué quieres que le haga? A esto se ven reducidos los jóvenes de hoy por la maldita avaricia de los padres, ¡y luego se extrañan de que los hijos deseen su muerte! FLECHA. Hay que confesar que el vuestro irritaría con su ruindad al hombre más prudente del mundo. No tengo, a Dios gracias, inclinaciones muy patibularias, y entre mis compañeros, a los que veo entremeterse en muchos pequeños comercios, sé zafarme hábilmente y apartarme de todas las galanterías que huelen levemente a horca; mas, a deciros verdad, me daría, con sus procedimientos, tentaciones de robarle; y creería, al hacerlo, que realizaba una acción meritoria."}, {"type": "p", "text": "CLEANTO. Trae acá ese inventario, que lo vuelva a leer."}]$lira$::jsonb, 578);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 13, 'Acto segundo · Escena II', $lira$[{"type": "p", "text": "HARPAGÓN, MAESE SIMÓN, CLEANTO y FLECHA al fondo de la escena"}, {"type": "p", "text": "MAESE SIMÓN. Sí, señor; es un joven que necesita dinero; sus negocios le apremian a encontrarlo, y pasará por todo cuanto le prescribáis."}, {"type": "p", "text": "HARPAGÓN. Pero ¿creéis, maese Simón, que no se corre ningún riesgo? ¿Y sabéis el nombre, los bienes y la familia de ese por quien habláis?"}, {"type": "p", "text": "MAESE SIMÓN. No; no puedo informaros de ello muy a fondo, y sólo por casualidad me han dirigido a él; mas él mismo os lo aclarará todo, y su presentador me ha asegurado que os satisfará conocerle. Todo cuanto puedo deciros es que su familia es muy rica, que él no tiene ya madre y que os garantiza, si queréis, que su padre morirá antes de ocho meses."}, {"type": "p", "text": "HARPAGÓN. Eso ya es algo. La caridad, maese Simón, nos obliga a complacer a las personas cuando nos es posible."}, {"type": "p", "text": "MAESE SIMÓN. Eso ya se sabe."}, {"type": "p", "text": "FLECHA. (Bajo, a Cleanto, al reconocer a maese Simón.) ¿Qué quiere decir esto? ¡Nuestro maese Simón hablando con vuestro padre!"}, {"type": "p", "text": "CLEANTO. (Bajo, a Flecha.) ¿Le habrán dicho quién soy? ¿Y estarás tú aquí para traicionarme?"}, {"type": "p", "text": "MAESE SIMÓN. ¡Ah, ah! ¡Buena prisa tenéis! ¿Quién os ha dicho que era aquí? (A Harpagón.) No he sido yo, señor, al menos, quien les ha revelado vuestro nombre y casa; mas, a mi juicio, no hay gran daño en esto; son personas discretas, y podéis explicaros aquí reunidos."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo!"}, {"type": "p", "text": "MAESE SIMÓN. (Señalando a Cleanto.) El señor es la persona que quiere pediros prestadas las quince mil libras de que os he hablado."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo, bigardo! ¿Eres tú quien te entregas a estos ocultos extremos? CLEANTO. ¡Cómo, padre mío! ¿Sois vos quien realizáis estas acciones vergonzosas? (Maese Simón huye y Flecha va a esconderse.)"}]$lira$::jsonb, 293);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 14, 'Acto segundo · Escena III', $lira$[{"type": "p", "text": "HARPAGÓN y CLEANTO"}, {"type": "p", "text": "HARPAGÓN. ¿Y eres tú el que quiere arruinarse con préstamos tan condenables? CLEANTO. ¿Y sois vos el que procuráis enriqueceros con tan criminales usuras? HARPAGÓN. ¿Te atreves, después de esto, a aparecer ante mí?"}, {"type": "p", "text": "CLEANTO. ¿Y vos os atrevéis, después de esto, a presentaros ante los ojos del mundo? HARPAGÓN. ¿No te avergüenza, di, llegar a estos excesos, lanzarte a gastos espantosos y llevar a cabo un afrentoso derroche del caudal que tus padres te han reunido con tantos sudores?"}, {"type": "p", "text": "CLEANTO. ¿Y no os sonroja deshonrar vuestro linaje con las especulaciones que hacéis, sacrificar gloria y reputación al deseo insaciable de amontonar escudo sobre escudo, superando, en lo tocante a interés, las más infames sutilezas que hayan inventado nunca los más famosos usureros?"}, {"type": "p", "text": "HARPAGÓN. ¡Quítate de mi vista, bergante; quítate de mi vista!"}, {"type": "p", "text": "CLEANTO. ¿Quién es más criminal a vuestro juicio: el que adquiere un dinero que necesita o el que roba un dinero que no le hace falta?"}, {"type": "p", "text": "HARPAGÓN. Vete, te digo, y no me hagas perder los estribos. (Solo.) No me enoja esta aventura, y me servirá de advertencia para estar más alerta que nunca ante todos sus actos."}]$lira$::jsonb, 194);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 15, 'Acto segundo · Escena V', $lira$[{"type": "p", "text": "FLECHA y FROSINA"}, {"type": "p", "text": "FLECHA. (Sin ver a Frosina.) ¡Es muy chusca la aventura! Debe de tener en alguna parte un gran almacén de ropas, pues no hemos reconocido nada en el inventario que tenemos."}, {"type": "p", "text": "FROSINA. ¡Ah, mi pobre Flecha! ¿A qué se debe este encuentro?"}, {"type": "p", "text": "FLECHA. ¡Ah, ah! ¿Eres tú, Frosina? ¿Qué vienes a hacer aquí?"}, {"type": "p", "text": "FROSINA. Lo que hago en todas partes: entremeterme en asuntos, hacerme servicial a la gente y sacar el mejor provecho que me es posible de las pequeñas aptitudes que pueda yo poseer. Ya sabes que en este mundo hay que vivir con habilidad, y que a las personas como yo el Cielo no nos ha dado más renta que la intriga y el ingenio. FLECHA. ¿Tienes algún negocio con el amo de la casa?"}, {"type": "p", "text": "FROSINA. Sí. Intervengo por él en cierto negocio, del que espero lograr una recompensa."}, {"type": "p", "text": "FLECHA. ¿A él? ¡Ah! A fe mía, bien lista serás si le sacas algo; y te advierto que el dinero, aquí dentro, es carísimo."}, {"type": "p", "text": "FROSINA. Hay ciertos servicios que se pagan maravillosamente."}, {"type": "p", "text": "FLECHA. Soy criado suyo, y no conoces todavía al señor Harpagón. El señor Harpagón es, de todos los humanos, el menos humano; de todos los mortales el más duro y el más avaro. No hay servicio que incite su gratitud hasta hacerle abrir la mano. Alabanzas, aprecio, benevolencia de palabra y amistad, todo lo que queráis; mas dinero, en absoluto. No hay nada más seco y más árido que su buena acogida y sus arrumacos, y dar es una palabra por la que siente tal aversión, que no dice nunca: os doy, sino os presto los buenos días."}, {"type": "p", "text": "FROSINA. ¡Dios mío! Conozco el arte de sonsacar dinero a los hombres; poseo el secreto de lograr su cariño, cosquillear sus corazones y encontrar los puntos por donde son vulnerables."}, {"type": "p", "text": "FLECHA. ¡Bagatelas en este vaso! Te desafío a que enternezcas, por el lado del dinero, al hombre de que se trata. Es un ser inflexible en eso; de una dureza que desespera a todo el mundo; y ya puede uno reventar, que él no se conmueve. En una palabra: ama al dinero más que a la reputación, al honor y a la virtud, y sólo la vista de un pedigüeño le produce convulsiones. Es herirle en su sitio mortal; es atravesarle el corazón, arrancarle las entrañas; y si... Mas aquí vuelve; me retiro."}]$lira$::jsonb, 397);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 16, 'Acto segundo · Escena VI (1/2)', $lira$[{"type": "p", "text": "HARPAGÓN y FROSINA"}, {"type": "p", "text": "HARPAGÓN. (Bajo.) Todo marcha como es debido. (Alto.) ¿Qué hay, Frosina? FROSINA. ¡Ah, Dios mío! ¡Qué bien estáis, y qué cara más saludable que tenéis! HARPAGÓN. ¿Quién, yo?"}, {"type": "p", "text": "FROSINA. No he visto nunca un cutis tan lozano y saludable."}, {"type": "p", "text": "HARPAGÓN. ¿De veras?"}, {"type": "p", "text": "FROSINA. ¡Cómo! No habéis estado jamás en vuestra vida tan joven como ahora, y veo mozos de veinticinco años más viejos que vos."}, {"type": "p", "text": "HARPAGÓN. Sin embargo, Frosina, tengo sesenta bien cumplidos."}, {"type": "p", "text": "FROSINA. ¿Y qué? ¿Qué son sesenta años? ¡Vaya una cosa! Es la flor de la edad, y entráis ahora en la más bella época del hombre."}, {"type": "p", "text": "HARPAGÓN. Es cierto; pero veinte años menos, sin embargo, no me perjudicarían, creo yo."}, {"type": "p", "text": "FROSINA. ¿Os burláis? No necesitáis eso, y sois de una madera como para vivir hasta los cien años."}, {"type": "p", "text": "HARPAGÓN. ¿Lo creéis así?"}, {"type": "p", "text": "FROSINA. Con seguridad. Tenéis todos los indicios de ello. Erguíos. ¡Oh! Ahí está, entre vuestros ojos, una señal de larga vida."}, {"type": "p", "text": "HARPAGÓN. ¿Eres entendida en eso?"}, {"type": "p", "text": "FROSINA. Sin duda. Mostradme vuestra mano. ¡Ah, Dios mío, qué línea de vida! HARPAGÓN. ¿Cómo?"}, {"type": "p", "text": "FROSINA. ¿No veis hasta dónde llega esta línea?"}, {"type": "p", "text": "HARPAGÓN. ¿Y qué quiere decir eso?"}, {"type": "p", "text": "FROSINA. A fe mía, he dicho cien años; pero ¡si vais a pasar de los ciento veinte! HARPAGÓN. ¿Es posible?"}, {"type": "p", "text": "FROSINA. Habrá que mataros, digo, y enterraréis a vuestros hijos y a los hijos de vuestros hijos."}, {"type": "p", "text": "HARPAGÓN. ¡Tanto mejor...! ¿Cómo marcha nuestro negocio?"}, {"type": "p", "text": "FROSINA. ¿Es necesario preguntarlo? ¿E intervengo yo en algo que no alcance éxito? Tengo, para los casamientos sobre todo, un talento especial; no hay partido en el mundo que no encuentre yo medio de emparejar en poco tiempo, y creo que, si se me metiera en la cabeza, casaría al Gran Turco con la República de Venecia. No había, indudablemente, grandes dificultades en este negocio. Como tengo trato con ellas, las he hablado a ambas a fondo de vos, y he dicho a la madre la pasión que habéis concebido por Mariana al verla pasar por la calle y tomar el aire en su ventana."}, {"type": "p", "text": "HARPAGÓN. .¿Y qué ha contestado?"}, {"type": "p", "text": "FROSINA. Ha recibido la proposición con alegría, y cuando la he manifestado que deseabais grandemente que su hija asistiera esta noche al contrato de esponsales que debe firmarse para la vuestra, ha accedido ella gustosa y me la ha confiado para eso. HARPAGÓN. Es que me veo obligado, Frosina, a dar de cenar al señor Anselmo, y me alegraría mucho que participase ella del festín."}, {"type": "p", "text": "FROSINA. Tenéis razón. Debe ella, después de comer, visitar a vuestra hija, y desde aquí tiene el propósito de dar una vuelta por la feria, para venir luego a la cena. HARPAGÓN.. Pues bien: irán juntas en mi carroza, que les prestaré."}, {"type": "p", "text": "FROSINA. Eso le parecerá muy bien."}, {"type": "p", "text": "HARPAGÓN. Pero, Frosina, ¿has hablado a la madre respecto a la dote que pueda dar a su hija? ¿Le has dicho que era necesario que ayudase un poco, que hiciese algún esfuerzo, que se exprimiera en una ocasión como ésta? Porque, eso sí, no se puede uno casar con una joven sin que aporte algo."}, {"type": "p", "text": "FROSINA. ¡Cómo! Es una joven que os aportará doce mil libras de renta."}, {"type": "p", "text": "HARPAGÓN. ¡Doce mil libras de renta!"}, {"type": "p", "text": "FROSINA. Sí. Ante todo, está alimentada y educada con un gran ahorro de estómago. Es una joven acostumbrada a vivir de ensalada, de leche, de queso y manzanas, y que no necesitará, por consiguiente, ni mesa bien servida, ni caldos exquisitos, ni cebadas mondadas constantes, ni las demás delicadas fruslerías que requeriría cualquier otra mujer; y esto no representa tan poco que no ascienda todos los años a tres mil francos, por lo menos. Aparte de esto, sólo le preocupa un aseo muy sencillo y no le gustan los vestidos costosos, ni las ricas joyas, ni los muebles suntuosos, a los que tan apasionadamente aficionadas son las de su sexo; y este capítulo equivale a más de cuatro mil libras al año. Además, siente una aversión horrible por el juego, lo cual no es corriente en las mujeres de hoy; y conozco a una de nuestro barrio que ha perdido al treinta y cuarenta veinte mil francos este año. Mas no contemos sino la cuarta parte. Cinco mil francos al juego, por año, y cuatro mil en vestidos y joyas, suman nueve mil libras; y poniendo mil escudos para la comida, ¿no tenéis ahora los doce mil francos contantes y sonantes, al año?"}, {"type": "p", "text": "HARPAGÓN. Sí; no está mal; mas esa cuenta no tiene nada de real."}, {"type": "p", "text": "FROSINA. Perdonadme. ¿No es algo real aportaros en matrimonio una gran sobriedad, la herencia de un gran afán por la sencillez del atavío y la adquisición de un gran caudal de odio al juego?"}, {"type": "p", "text": "HARPAGÓN. Es una chanza querer formar su dote con todos los gastos que ella no hará. No voy a dar recibo de lo que no me han dado, y tengo que percibir algo. FROSINA. ¡Dios mío! Ya percibiréis bastante; y ellas me han hablado de cierto lugar donde tienen bienes, que pasarán a ser vuestros."}, {"type": "p", "text": "HARPAGÓN. Habrá que verlo. Pero queda, Frosina, otra cosa que me inquieta. La moza es joven, como ves, y las jóvenes, generalmente, sólo aman a los de su edad y buscan únicamente su compañía; temo que un hombre de mi edad no sea de su gusto y que esto ocasione en mi casa ciertos pequeños desórdenes que no me convendrían. FROSINA. ¡Ah, qué mal la conocéis! Ésa es otra particularidad que pensaba deciros. Tiene una aversión espantosa por todos los jóvenes, y sólo siente amor por los viejos. HARPAGÓN. ¿Ella?"}]$lira$::jsonb, 929);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 17, 'Acto segundo · Escena VI (2/2)', $lira$[{"type": "p", "text": "FROSINA. Sí, ella. Quisiera que la hubierais oído hablar acerca de eso. No puede soportar en absoluto la vista de un joven, pero siente el mayor encanto, dice ella, cuando logra ver a un apuesto viejo con una barba majestuosa. Los más viejos son para ella los más seductores, y os aconsejo que no os hagáis con ella más joven de lo que sois. Quiere, cuando menos, que sea uno sexagenario; y no hace todavía cuatro meses, estando a punto de casarse, rompió el compromiso matrimonial porque descubrió que su amante sólo contaba cincuenta y seis años y no usó antiparras3 para firmar el contrato. HARPAGÓN. ¿Por eso tan sólo?"}, {"type": "p", "text": "FROSINA. Sí. Dijo que a ella no le satisfacían cincuenta y seis años solamente, y que le agradaban, sobre todo, las narices que sostenían anteojos."}, {"type": "p", "text": "HARPAGÓN. En verdad, me dices una cosa muy nueva."}, {"type": "p", "text": "FROSINA. Eso va más allá de lo que os pudiera decir. Tiene en su cuarto algunos cuadros y estampas; mas ¿qué creéis que son: Adonis, Céfalo, Paris y Apolo? No. Bellos retratos de Saturno, del rey Príamo, del anciano Néstor y del buen padre Anquises, a hombros de su hijo."}, {"type": "p", "text": "HARPAGÓN. ¡Es admirable! No lo hubiera imaginado nunca; y me satisface mucho saber que es así su carácter. En efecto: de haber sido yo mujer, no me hubieran gustado los jóvenes."}, {"type": "p", "text": "FROSINA. Lo creo. ¡Linda cosa para amarlos! ¡Son unos mocosos, unos presumidos, para sentir antojos por ellos! ¡Y me gustaría saber qué atractivo pueden ofrecer! HARPAGÓN. Yo, por mi parte, no los comprendo en absoluto, y no sé cómo hay mujeres que los aman tanto."}, {"type": "p", "text": "FROSINA. Hay que estar loca de remate. Encontrar amable a la juventud, ¿es tener juicio? ¿Son hombres unos boquirrubios y puede sentirse apego por esos animales? HARPAGÓN. Es lo que digo yo todos los días: ¡con su voz feble, sus tres pelos de barba levantados como los de un gato, sus pelucas de estopa, sus calzas caídas y sus estómagos desarreglados!"}, {"type": "p", "text": "FROSINA. ¡Eh! ¡Bien formados resultan junto a una persona como vos! Vos sois un hombre de verdad, que recrea la vista, y hay que estar hecho y vestido así para engendrar amor."}, {"type": "p", "text": "HARPAGÓN. ¿Me encuentras bien?"}, {"type": "p", "text": "FROSINA. ¡Cómo! Embelesáis, y vuestro rostro es digno de ser pintado. Volveos un poco, por favor. No puede haber nada mejor. Que os vea andar. He aquí un cuerpo modelado, libre y desenvuelto como es debido y que no altera dolencia alguna. HARPAGÓN. No padezco ninguna grave, a Dios gracias. Tan sólo mi fluxión me ataca de cuando en cuando."}, {"type": "p", "text": "FROSINA. ¡Ah, eso no es nada! Vuestra fluxión no os sienta mal, y toséis con gracia. HARPAGÓN. Y, dime: ¿Mariana no me ha visto aún? ¿No se ha fijado en mí al pasar? FROSINA. No; mas hemos hablado mucho de vos. Le he hecho un retrato de vuestra persona, y no he dejado de alabarle vuestro mérito y lo beneficioso que para ella sería tener un marido como vos."}, {"type": "p", "text": "HARPAGÓN. Has hecho bien, y te lo agradezco."}, {"type": "p", "text": "FROSINA. Quisiera, señor, haceros un pequeño ruego. Tengo un pleito y estoy a punto de perder por falta de algún dinero (Harpagón adopta un aire serio.), y podríais fácilmente proporcionarme la ganancia de este pleito si tuvierais alguna bondad conmigo. No os podéis imaginar el placer que tendrá ella en veros. (Harpagón recobra su aire alegre.) ¡ Ah, cómo le gustaréis! ¡Vuestra gorguera a la antigua producirá un efecto admirable sobre su ánimo! Mas, sobre todo, le encantarán vuestras calzas atadas a la ropilla con cordones. Es para volverla loca por vos; y un amante acordonado así será para ella un incentivo maravilloso."}, {"type": "p", "text": "HARPAGÓN. En verdad, me encantas diciéndome esto."}, {"type": "p", "text": "FROSINA. Os aseguro, señor, que el resultado de este pleito es para mí decisivo. (Harpagón recobra su aire serio.) Estoy arruinada si lo pierdo; y una pequeña ayuda reharía mis negocios. Quisiera yo que hubierais visto el embeleso en que se hallaba oyéndome hablar de vos. (Harpagón recobra su aire alegre.) La dicha estalla en sus ojos ante el relato de vuestras cualidades; y la he dejado con una impaciencia suma al ver ese casamiento enteramente concertado."}, {"type": "p", "text": "HARPAGÓN. Me has dado un gran placer, Frosina, y te debo, lo confieso, todas las gratitudes del mundo."}, {"type": "p", "text": "FROSINA. Os ruego, señor, que me entreguéis el pequeño socorro que os pido. (Harpagón recobra de nuevo su aire serio.) Esto me repondrá y os quedaré eternamente agradecida."}, {"type": "p", "text": "HARPAGÓN. Adiós; voy a terminar mi correspondencia."}, {"type": "p", "text": "FROSINA. Os aseguro, señor, que no podríais socorrerme en una mayor necesidad. HARPAGÓN. Ordenaré que mi carroza esté preparada para llevaros a la fiesta. FROSINA. No os importunaría si no me viese obligada a ello por la necesidad. HARPAGÓN. Y cuidaré de que se cene temprano para que no os sintáis desfallecida. FROSINA. No me neguéis el favor que os pido. No os podéis imaginar, señor, el gran placer que..."}, {"type": "p", "text": "HARPAGÓN. Me voy. Ahora me llaman. Hasta luego."}, {"type": "p", "text": "FROSINA. (Sola.) ¡Que te den unas fiebres, maldito perro de todos los diablos! El muy avaro se ha cerrado a todos mis ataques; mas no hay que abandonar, sin embargo, la negociación; me queda la otra parte, en último caso, de donde estoy segura que sacaré una buena recompensa."}]$lira$::jsonb, 871);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 18, 'Acto tercero · Escena primera', $lira$[{"type": "p", "text": "HARPAGÓN, CLEANTO, ELISA, VALERIO, DOÑA CLAUDIA, con una escoba;"}, {"type": "p", "text": "MAESE SANTIAGO, MERLUZA y MIAJAVENA"}, {"type": "p", "text": "HARPAGÓN. Vamos, venid aquí todos que os comunique mis órdenes para luego y señale a cada cual su cometido. Acercaos, doña Claudia, y empecemos por vos. Bien; héteos ya con las armas en la mano. Os recomiendo el trabajo de limpiar por todas partes, y, sobre todo, tened cuidado de no frotar los muebles con demasiada fuerza, por miedo a desgastarlos. Además de eso, os encargo que administréis las botellas durante la cena; y si se extravía alguna o se rompe algo, os haré responsables de ello y lo descontaré de vuestro salario."}, {"type": "p", "text": "MAESE SANTIAGO. (Aparte.) Hábil castigo."}, {"type": "p", "text": "HARPAGÓN. (A doña Claudia.) Idos."}]$lira$::jsonb, 117);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 19, 'Acto tercero · Escena II', $lira$[{"type": "p", "text": "Los mismos, menos DOÑA CLAUDIA"}, {"type": "p", "text": "HARPAGÓN. A vos, Miajavena, y a vos, Merluza, os encargo de lavar los vasos y de servir de beber; mas sólo cuando tengan sed y no siguiendo la costumbre de ciertos lacayos impertinentes, que van a provocar a las gentes avisándolas de que beban cuando no pensaban hacerlo. Esperad a que os lo pidan más de una vez y acordaos de servir siempre mucha agua."}, {"type": "p", "text": "MAESE SANTIAGO. (Aparte.) Sí; el vino puro se sube a la cabeza."}, {"type": "p", "text": "MERLUZA. ¿Nos quitamos los casacones de cuadra?"}, {"type": "p", "text": "HARPAGÓN. Si; cuando veáis llegar a las personas, y guardaos mucho de deteriorar vuestros trajes."}, {"type": "p", "text": "MIAJAVENA. Ya sabéis, señor, que uno de los delanteros de mi ropilla tiene una gran mancha de aceite de la lámpara."}, {"type": "p", "text": "MERLUZA. Y que yo, señor, tengo mis calzas rotas por detrás y que se me ve, dicho sea con vuestra licencia..."}, {"type": "p", "text": "HARPAGÓN. (A Merluza.) ¡Basta! Colocaos hábilmente contra la pared y mostraos siempre de frente. (A Miajavena, enseñándole cómo debe colocar su sombrero delante de su ropilla para tapar la mancha de aceite.) Y vos, sostened así vuestro sombrero cuando sirváis."}]$lira$::jsonb, 186);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 20, 'Acto tercero · Escena III', $lira$[{"type": "p", "text": "HARPAGÓN, CLEANTO, ELISA, VALERIO y MAESE SANTIAGO"}, {"type": "p", "text": "HARPAGÓN. En cuanto a vos, hija mía, no perdáis de vista lo que se retire de la mesa y tened cuidado de que no haya ningún estropicio. Esto corresponde a las hijas. Mas, entretanto, preparaos a recibir bien a mi dueña, que debe venir a visitaros y a llevaros con ella a la feria. ¿Entendéis lo que os digo?"}, {"type": "p", "text": "ELISA. Sí, padre."}]$lira$::jsonb, 69);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 21, 'Acto tercero · Escena IV', $lira$[{"type": "p", "text": "HARPAGÓN, CLEANTO, VALERIO y MAESE SANTIAGO"}, {"type": "p", "text": "HARPAGÓN. Y vos, hijo mío, el galancete a quien tengo la bondad de perdonar la historia reciente, no vayáis tampoco a ponerle mala cara."}, {"type": "p", "text": "CLEANTO. ¿Yo, padre mío? ¡Mala cara! ¿Y por qué razón?"}, {"type": "p", "text": "HARPAGÓN. ¡Dios mío! Ya sabemos la disposición de los hijos cuyos padres se vuelven a casar y con qué ojos acostumbran mirar a la que se denomina madrastra. Mas si deseáis que olvide vuestra última ventolera, os recomiendo, sobre todo, que festejéis con buen talante a esa persona y que la dispenséis, en fin, la mejor acogida que os sea posible."}, {"type": "p", "text": "CLEANTO. A deciros verdad, padre, no puedo prometeros sentirme muy satisfecho de que llegue ella a ser mi madrastra. Mentiría, si os lo dijera; pero en lo que se refiere a recibirla bien y a ponerla buena cara os prometo obedeceros puntualmente en tal capítulo."}, {"type": "p", "text": "HARPAGÓN. Poned atención en ello, al menos."}, {"type": "p", "text": "CLEANTO. Ya veréis como no tendréis ocasión de quejaros"}, {"type": "p", "text": "HARPAGÓN. Haréis bien."}]$lira$::jsonb, 165);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 22, 'Acto tercero · Escena V (1/2)', $lira$[{"type": "p", "text": "HARPAGÓN, VALERIO y MAESE SANTIAGO"}, {"type": "p", "text": "HARPAGÓN. Valerio, ayudadme en esto. Veamos, maese Santiago; os he dejado para el último."}, {"type": "p", "text": "MAESE SANTIAGO. ¿Es a vuestro cochero, señor, o vuestro cocinero, a quien queréis hablar? Pues yo soy lo uno y lo otro."}, {"type": "p", "text": "HARPAGÓN. Es a los dos."}, {"type": "p", "text": "MAESE SANTIAGO. Mas, ¿a cuál de los dos primero?"}, {"type": "p", "text": "HARPAGÓN. Al cocinero."}, {"type": "p", "text": "MAESE SANTIAGO. Esperad entonces, por favor. (Maese Santiago se quita su casaca de cochero y aparece vestido de cocinero.)"}, {"type": "p", "text": "HARPAGÓN. ¿Qué diantre de ceremonia es ésta?"}, {"type": "p", "text": "MAESE SANTIAGO. No tenéis más que hablar."}, {"type": "p", "text": "HARPAGÓN. Me he comprometido, maese Santiago, a dar una cena esta noche. MAESE SANTIAGO. (Aparte.) ¡Gran maravilla!"}, {"type": "p", "text": "HARPAGÓN. Dime: ¿nos darás bien de comer?"}, {"type": "p", "text": "MAESE SANTIAGO. Sí; si me facilitáis dinero."}, {"type": "p", "text": "HARPAGÓN. ¡Qué diablo, siempre dinero! Parece que no saben decir otra cosa: ¡dinero, dinero, dinero! ¡Ah! ¡Sólo tienen esa palabra en la boca: dinero! ¡Hablar siempre de dinero! El dinero es su muletilla."}, {"type": "p", "text": "VALERIO. No he oído nunca una respuesta más impertinente que ésta. ¡Vaya una maravilla dar una buena comida con mucho dinero! Es la cosa más fácil del mundo, y no hay mísero ingenio que no haga otro tanto; mas para obrar como un hombre hábil hay que saber ofrecer una buena comida con poco dinero."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Buena comida con poco dinero!"}, {"type": "p", "text": "VALERIO. Sí."}, {"type": "p", "text": "MAESE SANTIAGO. (A Valerio.) A fe mía, señor intendente, os quedaremos muy agradecidos si nos reveláis ese secreto y ocupáis mi puesto de cocinero; así seréis dentro el factoton."}, {"type": "p", "text": "HARPAGÓN. Callaos. ¿ Qué necesitaremos?"}, {"type": "p", "text": "MAESE SANTIAGO. Aquí tenéis a vuestro señor intendente, que os dará bien de comer por poco dinero."}, {"type": "p", "text": "HARPAGÓN. ¡Arre! Quiero que me respondas."}, {"type": "p", "text": "MAESE SANTIAGO. ¿Cuántas personas seréis en la mesa?"}, {"type": "p", "text": "HARPAGÓN. Seremos ocho o diez; mas sólo hay que contar ocho. Donde comen ocho pueden comer muy bien diez."}, {"type": "p", "text": "VALERIO. Eso por descontado."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Pues bien! Se necesitarán cuatro grandes ollas de sopa y cinco platos... Sopas... Principios..."}, {"type": "p", "text": "HARPAGÓN. ¡Diablo! Eso es para dar de comer a una ciudad entera."}, {"type": "p", "text": "MAESE SANTIAGO. Asa..."}, {"type": "p", "text": "HARPAGÓN. (Tapando la boca de Maese Santiago con la mano.) ¡Ah, traidor! Te comerás mi fortuna."}, {"type": "p", "text": "MAESE SANTIAGO. Entremeses..."}, {"type": "p", "text": "HARPAGÓN. (Volviendo a poner su mano sobre la boca de Maese Santiago.) ¿Más aún?"}, {"type": "p", "text": "VALERIO. (A Maese Santiago.) ¿Es que pensáis atiborrar a todo e1 mundo? ¿Y el señor ha invitado a unas personas para asesinarlas a fuerza de condumio? Id a leer un rato los preceptos de la salud y a preguntar a los médicos si hay algo más perjudicial para el hombre que comer con exceso."}, {"type": "p", "text": "HARPAGÓN. Tiene razón."}, {"type": "p", "text": "VALERIO. Sabed, maese Santiago, vos y vuestros compañeros, que resulta una ladronera una mesa llena de viandas en demasía; que para mostrarse verdaderamente amigo de los que uno invita es preciso que la frugalidad reine en las comidas que se den, y que, según el dicho antiguo, «hay que comer para vivir y no vivir para comer». HARPAGÓN. ¡Ah, qué bien dicho está eso! Acércate que te abrace por esa frase. Es la más hermosa sentencia que he oído en mi vida: Hay que vivir para comer y no comer para vi... No; no es eso. ¿Cómo has dicho?"}, {"type": "p", "text": "VALERIO. Que hay que comer para vivir y no vivir para comer."}, {"type": "p", "text": "HARPAGÓN. (A Maese Santiago.) Sí. ¿Lo oyes? (A Valerio.) ¿Quién es el gran hombre que ha dicho eso?"}, {"type": "p", "text": "VALERIO. No recuerdo ahora su nombre."}, {"type": "p", "text": "HARPAGÓN. Acuérdate de escribirme esas palabras: quiero hacerlas grabar en letras de oro sobre la chimenea de mi estancia."}, {"type": "p", "text": "VALERIO. No dejaré de hacerlo. Y en cuanto a vuestra cena, no tenéis más que dejarme hacer; yo lo dispondré todo como es debido."}, {"type": "p", "text": "HARPAGÓN. Hazlo, pues."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Tanto mejor! Menos trabajo tendré."}, {"type": "p", "text": "HARPAGÓN. (A Valerio.) Harán falta cosas de esas que se comen apenas y que hartan en seguida; unas buenas judías magras con algún pastel en olla, bien provisto de castañas."}, {"type": "p", "text": "VALERIO. Confiad en mí."}, {"type": "p", "text": "HARPAGÓN. Y ahora, maese Santiago, hay que limpiar mi carroza."}, {"type": "p", "text": "MAESE SANTIAGO. Esperad; esto va dirigido al cochero. (Maese Santiago se vuelve a poner su casaca.) ¿Decíais...?"}]$lira$::jsonb, 677);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 23, 'Acto tercero · Escena V (2/2)', $lira$[{"type": "p", "text": "HARPAGÓN. Que hay que limpiar mi carroza y tener preparados mis caballos para llevar a la feria..."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Vuestros caballos, señor! ¡Pardiez!, no se encuentran en estado de caminar. No os diré que estén echados en su cama: los pobres animales no la tienen, y sería mentir; mas los hacéis observar unos ayunos tan severos, que ya no son más que ideas, fantasmas o figuraciones de caballos."}, {"type": "p", "text": "HARPAGÓN. ¡Van a estar muy enfermos no haciendo nada!"}, {"type": "p", "text": "MAESE SANTIAGO. Y, aunque no se haga nada, señor, ¿es que no se necesita comer? Mejor les valdría a las pobres bestias trabajar mucho y comer lo mismo. Me parte el corazón verlos así, extenuados. Pues, en fin: siento tal cariño por mis caballos, que me parece que soy yo mismo, cuando los veo sufrir. Me quito para ellos, todos los días, las cosas de la boca; y es tener, señor, un temple muy duro no sentir piedad alguna por el prójimo."}, {"type": "p", "text": "HARPAGÓN. No será un trabajo grande ir hasta la feria."}, {"type": "p", "text": "MAESE SANTIAGO. No, señor; no tengo valor para llevarlos, ni podría darles latigazos; en el estado en que se hallan, ¿cómo queréis que arrastren la carroza? ¡Si no pueden tirar de ellos mismos!"}, {"type": "p", "text": "VALERIO. Señor, rogaré al vecino Picard que se encargue de guiarlos, y de este modo podremos contar con éste aquí para preparar la cena."}, {"type": "p", "text": "MAESE SANTIAGO. Sea. ¡Prefiero que se mueran bajo la mano de otro que bajo la mía!"}, {"type": "p", "text": "VALERIO. Maese Santiago es muy sensato."}, {"type": "p", "text": "MAESE SANTIAGO. Y el señor intendente muy dispuesto y decidido."}, {"type": "p", "text": "HARPAGÓN. ¡Haya paz!"}, {"type": "p", "text": "MAESE SANTIAGO. Señor, no puedo soportar a los aduladores; y veo que lo que él hace, sus continuas requisas sobre el pan y el vino, la leña, la sal y las velas son únicamente para halagaros y haceros la corte. Eso me enfurece, y me enoja oír a diario lo que se dice de vos, pues, en fin, os tengo afecto a mi pesar y, después de mis caballos, sois la persona a la que quiero más."}, {"type": "p", "text": "HARPAGÓN. ¿Podría yo saber de vuestros labios, maese Santiago, lo que se dice de mí?"}, {"type": "p", "text": "MAESE SANTIAGO. Sí, señor, si tuviera la seguridad de que eso no os iba a enojar. HARPAGÓN. No; en modo alguno."}, {"type": "p", "text": "MAESE SANTIAGO. Perdonadme; sé muy bien que os encolerizaría."}, {"type": "p", "text": "HARPAGÓN. En absoluto. Al contrario, es darme gusto, y me complace saber cómo hablan de mí."}, {"type": "p", "text": "MAESE SANTIAGO. Señor, ya que lo deseáis, os diré francamente que se burlan en todas partes de vos, que nos lanzan cien pullas a cuenta vuestra y que nada los embelesa tanto como morderos y estar murmurando siempre sobre vuestra tacañería. El uno dice que mandáis imprimir almanaques especiales, en los que hacéis duplicar las Témporas y las Vigilias, a fin de aprovecharos de los ayunos a que obligáis a vuestra gente; el otro, que siempre tenéis preparada una riña con vuestros criados en época de aguinaldos, o cuando salen de vuestra casa, para tener así un motivo de no darles nada. Aquél cuenta que una vez hicisteis emplazar judicialmente al gato de vuestro vecino por haberse comido en vuestra cocina los restos de una pierna de cordero. Éste, que se os ha sorprendido una noche sustrayendo vos mismo la avena a vuestros caballos, y que vuestro cochero, mi antecesor en el puesto, os dio en la oscuridad no se cuántos palos, lo cual no quisisteis divulgar. En fin: ¿queréis que os lo diga? No se puede ir a ningún sitio donde no se oiga haceros trizas. Sois el tema de irrisión de todo el mundo, y siempre se os designa bajo los nombres de avaro, roñoso, ruin y usurero. HARPAGÓN. (Golpeando a Maese Santiago.) Sois un necio, un bergante, un pícaro y un descarado."}, {"type": "p", "text": "MAESE SANTIAGO. ¿Lo veis? ¿No lo había yo adivinado? No quisisteis creerme. Ya os dije que os enojaríais al deciros la verdad."}, {"type": "p", "text": "HARPAGÓN. Aprended a hablar."}]$lira$::jsonb, 650);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 24, 'Acto tercero · Escena VI', $lira$[{"type": "p", "text": "VALERIO y MAESE SANTIAGO"}, {"type": "p", "text": "VALERIO. (Riendo.) Por lo que puedo ver, maese Santiago, pagan mal vuestra franqueza."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Pardiez!, señor recién llegado, que os las echáis de importante, eso no es cuenta vuestra. Reíos de los palos que os den, y no vengáis a reíros de los míos."}, {"type": "p", "text": "VALERIO. ¡Ah, maese Santiago, no os enojéis, por favor!"}, {"type": "p", "text": "MAESE SANTIAGO. (Aparte.) Se amilana. Voy a echarlas de bravucón, y si es lo bastante necio para tenerme miedo, le vapulearé un poco. (Alto.) ¿No sabéis, señor risueño, que yo no me río y que si me calentáis la cabeza os haré reír de otro modo? (Maese Santiago empuja a Valerio hasta el fondo de la escena, amenazándole.) VALERIO. ¡Eh! ¡Poco a poco!"}, {"type": "p", "text": "MAESE SANTIAGO. ¡ Cómo! ¿ Poco a poco? ¡No me da la gana!"}, {"type": "p", "text": "VALERIO. ¡Por favor!"}, {"type": "p", "text": "MAESE SANTIAGO. Sois un impertinente."}, {"type": "p", "text": "VALERIO. Señor maese Santiago..."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Nada de señor maese Santiago! ¡Si cojo un palo, os voy a zurrar de lo lindo!"}, {"type": "p", "text": "VALERIO. ¡Cómo! ¿Un palo? (Valerio hace retroceder a Maese Santiago a su vez.) MAESE SANTIAGO. ¡Eh! No hablaba de eso."}, {"type": "p", "text": "VALERIO. ¿No sabéis, señor fatuo, que soy lo bastante hombre para zurraros a mi vez? MAESE SANTIAGO. No lo dudo."}, {"type": "p", "text": "VALERIO. ¿Y que no sois, en resumidas cuentas, más que un cocinero bergante? MAESE SANTIAGO. Ya lo sé."}, {"type": "p", "text": "VALERIO. ¿Y que no me conocéis todavía?"}, {"type": "p", "text": "MAESE SANTIAGO. Perdonadme."}, {"type": "p", "text": "VALERIO. ¿Me vais a zurrar?"}, {"type": "p", "text": "MAESE SANTIAGO. Lo decía en broma."}, {"type": "p", "text": "VALERIO. Pues a mí no me gustan vuestras bromas. (Dando de palos a Maese Santiago.) Así sabréis que sois un mal bromista."}, {"type": "p", "text": "MAESE SANTIAGO. (Solo.) ¡Mal haya sea la sinceridad! Condenado oficio es. De aquí en adelante renuncio a él y no volveré a decir la verdad. Pase aún en mi amo; tiene cierto derecho a pegarme; mas en cuanto a este señor intendente, me vengaré de él si puedo."}]$lira$::jsonb, 313);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 25, 'Acto tercero · Escena VIII', $lira$[{"type": "p", "text": "MARIANA y FROSINA"}, {"type": "p", "text": "MARIANA. ¡Ah, Frosina! En qué extraño estado me encuentro, y, si he de decir lo que siento, ¡tengo miedo a esta presentación!"}, {"type": "p", "text": "FROSINA. Pero ¿por qué? ¿Cuál es vuestra inquietud?"}, {"type": "p", "text": "MARIANA. ¡Ay! ¿Y me lo preguntáis? ¿No os figuráis las zozobras de una persona enteramente preparada a ver el suplicio al que quieren atarla?"}, {"type": "p", "text": "FROSINA. Bien veo que, para morir agradablemente, Harpagón no es el suplicio al que quisierais entregaros, y conozco en vuestra cara que ese mozo rubio de que me habéis hablado os viene algunas veces a la memoria."}, {"type": "p", "text": "MARIANA. Sí. Es una cosa, Frosina, de la que no quiero defenderme; y las respetuosas visitas que ha hecho a nuestra casa han causado, os lo confieso, cierto afecto en mi alma."}, {"type": "p", "text": "FROSINA. Mas ¿habéis sabido quién es...?"}, {"type": "p", "text": "MARIANA. No; no sé quién es. Mas sé que su aspecto le hace digno de ser amado; que si pudiera dejar las cosas a mi elección, le escogería mejor que a otro, y que contribuye, y no poco, a hacerme encontrar un tormento atroz en el esposo que quieren darme. FROSINA. ¡Dios mío! Todos esos boquirrubios son agradables y recitan bien su papel; mas la mayoría son pobres como ratas, y es preferible para vos escoger un marido viejo que os aporte un buen caudal. Os confieso que los sentimientos no hallan tan buena satisfacción por el lado que digo, y que habréis de soportar algunas pequeñas repugnancias con tal esposo; mas esto no durará mucho, y su muerte, creedme, os pondrá muy pronto en situación de tomar otro más agradable, que lo enmendará todo. MARIANA. ¡Dios mío, Frosina! Extraño negocio éste, en el que, para ser feliz, hay que desear o esperar el fallecimiento de alguien; y la muerte no sigue siempre a los proyectos que forjamos."}, {"type": "p", "text": "FROSINA. ¿Queréis chancearos? Os casáis con él a condición tan sólo de que os deje viuda pronto y ésta habrá de ser una de las cláusulas del contrato. Sería muy impertinente si no muriese a los tres meses. Aquí llega en persona."}, {"type": "p", "text": "MARIANA. ¡Ah, Frosina, qué cara!"}]$lira$::jsonb, 347);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 26, 'Acto tercero · Escena IX', $lira$[{"type": "p", "text": "HARPAGÓN, MARIANA y FROSINA"}, {"type": "p", "text": "HARPAGÓN. (A Mariana.) No os ofendáis, encanto mío, si os recibo con anteojos. Sé que vuestros hechizos saltan harto a la vista, son lo bastante visibles por sí mismos y que no se necesitan anteojos para verlos; mas, en fin, con anteojos se observan los astros, y yo sostengo y garantizo que sois un astro, pero un astro que es el más bello del país de los astros. (A Frosina.) Frosina, no me contesta nada; no demuestra, al parecer, ninguna alegría al verme."}, {"type": "p", "text": "FROSINA. Es que está sobrecogida de sorpresa, y, además, a las doncellas les sonroja siempre revelar en seguida lo que encierra su alma."}, {"type": "p", "text": "HARPAGÓN. (A Frosina.) Tienes razón. (A Mariana.) Aquí está, linda niña, mi hija, que viene a saludaros."}]$lira$::jsonb, 127);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 27, 'Acto tercero · Escena X', $lira$[{"type": "p", "text": "HARPAGÓN, MARIANA, ELISA y FROSINA"}, {"type": "p", "text": "MARIANA. Efectúo, señora, tardíamente esta visita."}, {"type": "p", "text": "ELISA. Habéis dicho, señora, lo que debí yo hacer, y me correspondía anticiparme. HARPAGÓN. Como veis, es muy alta; pero la mala hierba crece sin cesar."}, {"type": "p", "text": "MARIANA. (Bajo, a Frosina.) ¡Oh, qué hombre más desagradable!"}, {"type": "p", "text": "HARPAGÓN. (Bajo, a Frosina.) ¿Qué dice la beldad?"}, {"type": "p", "text": "FROSINA. Que os encuentra admirable."}, {"type": "p", "text": "HARPAGÓN. Me hacéis demasiado honor, admirable encanto."}, {"type": "p", "text": "MARIANA. (Aparte.) ¡Qué animal!"}, {"type": "p", "text": "HARPAGÓN. Os quedo muy agradecido por esos sentimientos."}, {"type": "p", "text": "MARIANA. (Aparte.) Yo no puedo resistir más."}]$lira$::jsonb, 85);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 28, 'Acto tercero · Escena XI', $lira$[{"type": "p", "text": "HARPAGÓN, MARIANA, CLEANTO, ELISA, VALERIO, FROSINA y"}, {"type": "h", "text": "Miajavena"}, {"type": "p", "text": "HARPAGÓN. Aquí está también mi hijo, que viene a cumplimentaros."}, {"type": "p", "text": "MARIANA. (Bajo, a Frosina.) ¡Ah, Frosina, qué encuentro! Es precisamente el joven de quien te hablé."}, {"type": "p", "text": "FROSINA. (A Mariana.) La aventura es maravillosa."}, {"type": "p", "text": "HARPAGÓN. Veo que os extraña ver que tengo unos hijos tan mayores; mas dentro de poco me desharé de ambos."}, {"type": "p", "text": "CLEANTO. (A Mariana.) Señora, a deciros verdad, es ésta una aventura que no me esperaba, sin duda, y mi padre me ha sorprendido bastante al decirme hace un rato el propósito que había forjado."}, {"type": "p", "text": "MARIANA. Yo puedo decir lo mismo. Es un encuentro imprevisto que me asombra tanto como a vos, y no estaba preparada para semejante aventura."}, {"type": "p", "text": "CLEANTO. Cierto es, señora, que mi padre no puede hacer mejor elección y que representa para mí una gran alegría sensible el veros; mas, con todo, no os aseguro que me regocije el deseo que podéis sentir de convertiros en mi madrastra. El parabién, os lo confieso, resulta harto difícil para mí, y es un título, con vuestra licencia, que no os deseo en modo alguno. Este discurso parecerá brutal a los ojos de ciertas personas; mas estoy seguro de que vos lo tomaréis como es debido; éste es un casamiento, señora, que, como os imaginaréis, me causa aversión; no ignoráis, sabiendo lo que soy, que ofende mis intereses; y tendré, en fin, que deciros, con permiso de mi padre, que, si las cosas dependiesen de mí, este himeneo no se celebraría."}, {"type": "p", "text": "HARPAGÓN. ¡Vaya un cumplido impertinente! ¡Linda confesión le hacéis!"}, {"type": "p", "text": "MARIANA. Y yo, para contestaros, debo deciros que las cosas son muy semejantes y que, si os causa aversión considerarme como vuestra madrastra, no la sentiré yo menor, sin duda, considerándoos como hijastro mío. No creáis, os lo ruego, que soy yo quien intenta produciros esa inquietud. Me disgustaría grandemente causaros enojo, y, de no yerme obligada a ello por una fuerza irresistible, os doy mi palabra que no accederé en modo alguno al casamiento que os apesadumbra."}, {"type": "p", "text": "HARPAGÓN. Tiene razón. A cumplido necio debe darse una respuesta a tono. Os pido perdón, encanto mío, por la impertinencia de mi hijo; es un joven necio que no conoce todavía el alcance de las palabras que pronuncia."}, {"type": "p", "text": "MARIANA. Os aseguro que lo que me ha dicho no me ha ofendido en absoluto; al contrario, me complace que me explique así sus verdaderos sentimientos. Me agrada en él semejante confesión, y si hubiese hablado de otro modo, le estimaría mucho menos. HARPAGÓN. Es harta bondad en vos querer disculpar así sus faltas. El tiempo le hará más cuerdo, y ya veréis cómo cambia de sentimientos."}, {"type": "p", "text": "CLEANTO. No, padre mío; no soy capaz de cambiar, y ruego encarecidamente a esta señora que me crea."}, {"type": "p", "text": "HARPAGÓN. ¿Hase visto semejante extravagancia? (Eleva aún más el tono.) CLEANTO. ¿Queréis que traicione mi corazón?"}, {"type": "p", "text": "HARPAGÓN. ¡Y dale! ¿Vais a cambiar de una vez de discurso?"}, {"type": "p", "text": "CLEANTO. ¡Pues bien! Ya que deseáis que hable de otra manera, permitid, señora, que me coloque en el lugar de mi padre y que os confiese que no he visto nada en el mundo tan encantador como vos; que no concibo nada igual a la dicha de agradaros, y que el título de esposo vuestro es una gloria, una felicidad que yo preferiría al destino de los más grandes príncipes de la Tierra... Sí, señora; la aventura de poseeros es, a mis ojos, la más bella de todas las fortunas; en ella cifro toda mi ambición. Nada hay que no sea capaz de hacer por tan preciada conquista; y los más poderosos obstáculos... HARPAGÓN. Poco a poco, hijo mío, por favor."}, {"type": "p", "text": "CLEANTO. Es un cumplido que hago a esta señora en nombre vuestro."}, {"type": "p", "text": "HARPAGÓN. ¡Dios mío! Tengo lengua para explicarme por mí mismo, y no necesito un intermediario como vos. Vamos, traed sillas."}, {"type": "p", "text": "FROSINA. No; es mejor que vayamos ahora a la feria, a fin de volver antes y tener todo el tiempo después para conversar."}, {"type": "p", "text": "HARPAGÓN. (A Miajavena.) Que enganchen entonces los caballos a la carroza."}]$lira$::jsonb, 675);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 29, 'Acto tercero · Escena XII', $lira$[{"type": "p", "text": "HARPAGÓN, MARIANA, ELISA, CLEANTO, VALERIO y FROSINA"}, {"type": "p", "text": "HARPAGÓN. (A Mariana.) Os ruego que me disculpéis, amor mío, por no haberos hecho servir una ligera colación antes de partir."}, {"type": "p", "text": "CLEANTO. Ya me he ocupado de eso, padre mío, y he mandado traer aquí unas fuentes con naranjas de la China, limones y confituras que he enviado a buscar de parte vuestra. HARPAGÓN. (Bajo, a Valerio.) ¡Valerio!"}, {"type": "p", "text": "VALERIO. (A Harpagón.) Ha perdido la cabeza."}, {"type": "p", "text": "CLEANTO. ¿Acaso os parece, padre mío, que no es bastante? Señora, tened la bondad de disculparnos, por favor."}, {"type": "p", "text": "MARIANA. No era necesario."}, {"type": "p", "text": "CLEANTO. ¿Habéis visto nunca, señora, un diamante con más destellos que ese que lleva mi padre en el dedo?"}, {"type": "p", "text": "MARIANA. En verdad, rebrilla mucho."}, {"type": "p", "text": "CLEANTO. (Quitando el diamante del dedo de su padre y dándoselo a Mariana.) Tenéis que verlo de cerca."}, {"type": "p", "text": "MARIANA. Es bellísimo, sin duda, y despide innumerables destellos."}, {"type": "p", "text": "CLEANTO. (Poniéndose delante de Mariana, que quiere devolverle el diamante.) De ningún modo, señora; está en unas manos harto bellas. Es un regalo que os hace mi padre."}, {"type": "p", "text": "HARPAGÓN. ¿Yo?"}, {"type": "p", "text": "CLEANTO. ¿No es cierto, padre mío, que queréis que esta señora lo conserve como prenda de vuestro amor?"}, {"type": "p", "text": "HARPAGÓN. (Bajo, a su hijo.) ¿Cómo?"}, {"type": "p", "text": "CLEANTO. (A Mariana.) ¡Linda pregunta! Me hace señas de que os lo haga aceptar. MARIANA. No quiero."}, {"type": "p", "text": "CLEANTO. (A Mariana.) ¿Os burláis? No piensa volver a tomarlo."}, {"type": "p", "text": "HARPAGÓN. (Aparte.) ¡Me sofoca el furor!"}, {"type": "p", "text": "MARIANA. Sería..."}, {"type": "p", "text": "CLEANTO. (Impidiendo siempre a Mariana que devuelva el diamante.) No, os digo, lo tomaría como una ofensa."}, {"type": "p", "text": "MARIANA. Por favor..."}, {"type": "p", "text": "CLEANTO. De ningún modo."}, {"type": "p", "text": "HARPAGÓN. (Aparte.) ¡Maldito sea!"}, {"type": "p", "text": "CLEANTO. Mirad cómo le escandaliza vuestra negativa."}, {"type": "p", "text": "HARPAGÓN. (Bajo, a su hijo.) ¡Ah, traidor!"}, {"type": "p", "text": "CLEANTO. (A Mariana.) Vedle desesperado."}, {"type": "p", "text": "HARPAGÓN. (Bajo, a su hijo, amenazándole.) ¡Qué verdugo eres!"}, {"type": "p", "text": "CLEANTO. Padre, no es mía la culpa. Hago lo que puedo para obligarla a quedarse con él; mas es tenaz."}, {"type": "p", "text": "HARPAGÓN. (Bajo, a su hijo, amenazándole.) ¡Bergante!"}, {"type": "p", "text": "CLEANTO. Señora, sois causa de que mi padre me reprenda."}, {"type": "p", "text": "HARPAGÓN. (A Mariana.) Haréis que caiga enfermo. Por favor, señora, no lo rechacéis más."}, {"type": "p", "text": "FROSINA. (A Mariana.) ¡Dios mío, qué melindres! Quedaos con la sortija, puesto que el señor lo desea!"}, {"type": "p", "text": "MARIANA. (A Harpagón.) Por no encolerizaros, me quedo con ella ahora, y ya buscaré ocasión de devolvérosla."}]$lira$::jsonb, 375);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 30, 'Acto tercero · Escena XIII', $lira$[{"type": "p", "text": "HARPAGÓN, MARIANA, ELISA, CLEANTO, VALERIO, FROSINA y"}, {"type": "h", "text": "Miajavena"}, {"type": "p", "text": "MIAJAVENA. Señor, ahí está un hombre que quiere hablaros."}, {"type": "p", "text": "HARPAGÓN. Decidle que estoy ocupado y que vuelva otra vez."}, {"type": "p", "text": "MIAJAVENA. Dice que os trae dinero."}, {"type": "p", "text": "HARPAGÓN. (A Mariana.) Os pido perdón; vuelvo al instante."}]$lira$::jsonb, 42);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 31, 'Acto tercero · Escena XIV', $lira$[{"type": "p", "text": "HARPAGÓN, MARIANA, CLEANTO, ELISA, VALERIO, FROSINA y MERLUZA"}, {"type": "p", "text": "MERLUZA. (Corriendo y derribando a Harpagón.) Señor..."}, {"type": "p", "text": "HARPAGÓN. ¡Ah, yo muero!"}, {"type": "p", "text": "CLEANTO. ¿Qué ocurre, padre mío? ¡Oh!, ¿os habéis hecho daño?"}, {"type": "p", "text": "HARPAGÓN. Al traidor le habrán dado seguramente dinero mis deudores para que me rompiese el cuello."}, {"type": "p", "text": "VALERIO. (A Harpagón.) No será nada..."}, {"type": "p", "text": "MERLUZA. (A Harpagón.) Os pido perdón, señor; creí obrar bien acudiendo de prisa. HARPAGÓN. ¿Qué vienes a hacer aquí, verdugo?"}, {"type": "p", "text": "MERLUZA. A deciros que vuestros dos caballos están desherrados."}, {"type": "p", "text": "HARPAGÓN. Que los lleven pronto al herrador."}, {"type": "p", "text": "CLEANTO. Mientras los hierran voy a hacer por vos, padre mío, los honores de la casa y a acompañar a la señora al jardín, adonde diré que lleven la colación."}]$lira$::jsonb, 117);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 32, 'Acto cuarto · Escena primera', $lira$[{"type": "p", "text": "CLEANTO, MARIANA, ELISA y FROSINA"}, {"type": "p", "text": "CLEANTO. Volvamos aquí; estaremos mucho mejor. No hay ya a nuestro alrededor persona sospechosa, y podemos hablar libremente."}, {"type": "p", "text": "ELISA. Sí, señora; mi hermano me ha confesado la pasión que siente por vos. Sé las penas y disgustos que son capaces de causar tales reveses, y os aseguro que me intereso por vuestra aventura con sumo afecto."}, {"type": "p", "text": "MARIANA. Es un dulce consuelo ver que una persona como vos toma parte en nuestros intereses, y os suplico, señora, que me conservéis siempre esa generosa amistad, tan capaz de suavizar la crueldad de la fortuna."}, {"type": "p", "text": "FROSINA. Sois, a fe mía, gentes desdichadas unos y otros por no haberme enterado, antes de ocurrir todo esto, de vuestra aventura. Os hubiera, sin duda, evitado esta inquietud, y no habría dejado llegar las cosas al punto en que están."}, {"type": "p", "text": "CLEANTO. ¿Qué queréis? Es mi mala fortuna la que lo ha querido así. Mas ¿cuál es vuestra decisión, bella Mariana?"}, {"type": "p", "text": "MARIANA. ¡Ay! ¿Estoy yo, acaso, en situación de tomar decisiones? Y en la subordinación en que me veo, ¿puedo forjar otra cosa que no sean anhelos? CLEANTO. ¿Y no hay otro apoyo para mí en vuestro corazón que esos simples anhelos? ¿Ninguna piedad oficiosa? ¿Ninguna bondad compasiva? ¿Ningún afecto activo?"}, {"type": "p", "text": "MARIANA. ¿Qué podría deciros? Poneos en mi lugar y ved qué puedo hacer. Pensad, ordenad vos mismo: en vuestras manos me pongo; y os creo harto razonable para querer exigir de mí tan sólo lo que pueda estarme permitido por el honor y el decoro. CLEANTO. ¡Ay! ¡A qué me reducís al remitirme a lo que quieran permitir los enojosos sentimientos de un rígido honor y de un escrupuloso decoro!"}, {"type": "p", "text": "MARIANA. Mas ¿qué queréis que haga? Aunque saltase por encima de numerosos miramientos a que está obligado nuestro sexo, tengo respeto a mi madre. Me ha educado siempre con suma ternura y no podría decidirme a ocasionarle ningún disgusto. Haced, actuad cerca de ella; emplead todos vuestros afanes en ganar su ánimo. Podéis hacer y decir todo cuanto queráis, os lo permito; y si sólo estriba en declararme en vuestro favor, accedo gustosa a hacerle yo misma una confesión de todo cuanto por vos siento."}, {"type": "p", "text": "CLEANTO. Frosina, mi pobre Frosina, ¿querrías ayudarnos?"}, {"type": "p", "text": "FROSINA. A fe mía, ¿es necesario preguntarlo? Quisiera hacerlo de todo corazón. Ya sabéis que soy, por naturaleza, bastante humanitaria. El Cielo no me ha dado un alma de bronce, y siento tan sólo harta ternura en prestar pequeños servicios cuando veo a personas que se aman con toda rectitud y honor. ¿Qué podríamos hacer en esto? CLEANTO. Piensa un poco, te lo ruego."}, {"type": "p", "text": "MARIANA. Iluminadnos."}, {"type": "p", "text": "ELISA. Busca alguna invención para desbaratar lo que has hecho."}, {"type": "p", "text": "FROSINA. Esto es bastante difícil. (A Mariana.) Vuestra madre no es del todo irrazonable, y tal vez se la podría convencer y decidirla a que traspasara al hijo el don que quiere hacer al padre. (A Cleanto.) Mas lo malo de esto es que vuestro padre es vuestro padre."}, {"type": "p", "text": "CLEANTO. Eso, por descontado."}, {"type": "p", "text": "FROSINA. Quiero decir que sentirá despecho si ve que le rechazan y que luego no estará de humor para dar su consentimiento a vuestro casamiento. Sería preciso, obrando hábilmente, que la negativa partiese de él mismo, intentando por algún medio que se sintiera defraudado de vuestra persona."}, {"type": "p", "text": "CLEANTO. Tienes razón."}, {"type": "p", "text": "FROSINA. Sí; tengo razón, ya lo sé. Eso es lo que habría que hacer; mas el diantre es poder encontrar los medios para ello. Esperad; si contásemos con alguna mujer de cierta edad que tuviera mi talento y supiese representar lo suficientemente bien para imitar a una dama de alcurnia, con ayuda de un boato prontamente preparado y de un raro título de marquesa o vizcondesa que supondríamos oriundo de la Baja Bretaña, tendría yo la suficiente habilidad para hacer creer a vuestro padre que era ésa una personalidad poseedora, además de dos casas, de cien mil escudos en dinero contante y sonante; que estaba locamente enamorada de él, y deseaba ser su esposa hasta el punto de entregarle todo su caudal por contrato de esponsales, es para mí indudable que prestaría oídos a la proposición puesto que, en fin, os ama mucho, ya lo sé; pero ama un poco más el dinero; y cuando, deslumbrados por esa añagaza, hubiera consentido ya en lo que os interesa, poco importaría después que se desengañase, al descubrir claramente los bienes de vuestra marquesa."}, {"type": "p", "text": "CLEANTO. Todo eso está muy bien pensado."}, {"type": "p", "text": "FROSINA. Dejarme hacer. Acabo de acordarme de una amiga mía, que es la que nos conviene."}, {"type": "p", "text": "CLEANTO. Ten por segura, Frosina, mi gratitud, si logras éxito en la cosa. Pero, encantadora Mariana, empecemos, os lo ruego, por ganarnos a vuestra madre; sería ya mucho que consiguiéramos romper el casamiento. Emplead en ello, por vuestra parte, os lo suplico, todos los esfuerzos que podáis. Servíos de todo el ascendiente que sobre ella os da ese afecto que os tiene. Desplegad, sin reserva, las gracias elocuentes, los encantos todopoderosos que el Cielo ha puesto en vuestros ojos y en vuestra boca, y no olvidéis, por favor, ninguna de esas tiernas palabras, de esas dulces súplicas, de esas caricias conmovedoras a las que estoy seguro que no podría negarse nada."}, {"type": "p", "text": "MARIANA. Haré todo cuanto pueda, y nada olvidaré."}]$lira$::jsonb, 872);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 33, 'Acto cuarto · Escena II', $lira$[{"type": "p", "text": "HARPAGÓN, CLEANTO, MARIANA, ELISA y FROSINA"}, {"type": "p", "text": "HARPAGÓN. (Aparte, sin que le vean.) ¡Cómo! Mi hijo besa la mano de su presunta madrastra, ¡y su presunta madrastra lo tolera sin demasiada repulsa! ¿Habrá algún misterio en esto?"}, {"type": "p", "text": "ELISA. Aquí está mi padre."}, {"type": "p", "text": "HARPAGÓN. La carroza está dispuesta; podéis partir cuando queráis."}, {"type": "p", "text": "CLEANTO. Puesto que vos no vais, padre mío, las acompañaré yo."}, {"type": "p", "text": "HARPAGÓN. No; quedaos. Irán ellas solas; os necesito."}]$lira$::jsonb, 69);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 34, 'Acto cuarto · Escena III', $lira$[{"type": "p", "text": "HARPAGÓN y CLEANTO"}, {"type": "p", "text": "HARPAGÓN. Veamos; interés de madrastra aparte, ¿qué te parece a ti esa persona? CLEANTO. ¿Qué me parece?"}, {"type": "p", "text": "HARPAGÓN. Sí; su aire, su talle, su belleza, su ingenio..."}, {"type": "p", "text": "CLEANTO. Así, así..."}, {"type": "p", "text": "HARPAGÓN. ¿Y qué más?"}, {"type": "p", "text": "CLEANTO. Hablándoos con franqueza, no me ha parecido aquí lo que había creído. Su aire es el de una indudable coqueta, su talle bastante basto, su belleza muy mediana y su ingenio de lo más vulgar. No creáis, padre mío, que lo digo para apartaros de ella, pues, madrastra por madrastra, tanto se me da ésta como otra."}, {"type": "p", "text": "HARPAGÓN. Sin embargo, hace poco le decías..."}, {"type": "p", "text": "CLEANTO. Le he dicho unas cuantas galanterías en vuestro nombre; mas era por agradaros."}, {"type": "p", "text": "HARPAGÓN. ¿No sientes, entonces, inclinación hacia ella?"}, {"type": "p", "text": "CLEANTO. ¿Yo? En absoluto."}, {"type": "p", "text": "HARPAGÓN. Eso me disgusta, pues echa por tierra una idea que se me había ocurrido. Contemplándola así, he reflexionado sobre mi edad, y he pensado que podrían murmurar viendo que me casaba con tan juvenil persona. Esta consideración me ha hecho renunciar a tal propósito, y como la he hecho pedir y estoy comprometido de palabra con ella, te la hubiera cedido, de no haber confesado tú esa aversión. CLEANTO. ¿A mí?"}, {"type": "p", "text": "HARPAGÓN. A ti."}, {"type": "p", "text": "CLEANTO. ¿En matrimonio?"}, {"type": "p", "text": "HARPAGÓN. En matrimonio."}, {"type": "p", "text": "CLEANTO. Escuchad. Verdad es que no resulta muy de mi gusto; mas, por"}, {"type": "p", "text": "complaceros, padre mío, estoy decidido a casarme con ella, si queréis."}, {"type": "p", "text": "HARPAGÓN. Yo soy más razonable de lo que crees. No pienso en modo alguno forzar tu inclinación."}, {"type": "p", "text": "CLEANTO. Perdonadme; haré ese esfuerzo por afecto a vos."}, {"type": "p", "text": "HARPAGÓN. No, no. Un matrimonio no puede ser feliz si no existe inclinación. CLEANTO. Esa es una cosa, padre mío, que tal vez venga después; y, según dicen, el amor es, con frecuencia, fruto del matrimonio."}, {"type": "p", "text": "HARPAGÓN. No. Por el lado del hombre, no debe correr riesgo el negocio; y hay consecuencias enojosas, a las que no quiero exponerme. Si hubieras sentido alguna inclinación hacia ella, enhorabuena te habrías casado en mi lugar; mas, no siendo así, seguiré mi primer propósito, y seré yo quien me case con ella."}, {"type": "p", "text": "CLEANTO. Pues bien, padre mío; ya que las cosas se ponen así, es preciso descubriros mi corazón y revelaros nuestro secreto. La verdad es que la amo desde el día en que la vi en un paseo; que mi deseo era, hace poco, pedírosla por esposa, y que tan sólo me ha contenido la declaración de vuestros sentimientos y el temor a enojaros. HARPAGÓN. ¿La habéis ido a visitar?"}, {"type": "p", "text": "CLEANTO. Sí, padre mío."}, {"type": "p", "text": "HARPAGÓN. ¿Muchas veces?"}, {"type": "p", "text": "CLEANTO. Bastantes para el tiempo transcurrido."}, {"type": "p", "text": "HARPAGÓN. ¿Os ha recibido bien?"}, {"type": "p", "text": "CLEANTO. Muy bien; mas sin saber quién era yo, y esto es lo que ha producido, hace un momento, esa sorpresa a Mariana."}, {"type": "p", "text": "HARPAGÓN. ¿Le habéis declarado vuestra pasión y el deseo que sentíais de casaros con ella?"}, {"type": "p", "text": "CLEANTO. Sin duda; e incluso algo había ya dejado traslucir a su madre. HARPAGÓN. ¿Y la hija corresponde fogosamente a vuestro amor?"}, {"type": "p", "text": "CLEANTO. Si he de creer en las apariencias, estoy convencido, padre, de que siente cierta debilidad por mí."}, {"type": "p", "text": "HARPAGÓN. (Bajo, aparte.) Me satisface haber sabido este secreto, y esto era precisamente lo que yo ansiaba. (Alto.) Vaya, hijo mío: ¿sabéis lo que pasa? Pues que debéis pensar, si os parece, en desprenderos de vuestro amor, en cesar todas vuestras persecuciones a una persona que deseo para mí y en casaros dentro de poco con la mujer que os destine."}, {"type": "p", "text": "CLEANTO. Sí, padre mío; ¡así es como me engañáis! ¡Pues bien! Ya que las cosas han llegado a este punto, os declaro que no abandonaré la pasión que siento por Mariana; que no habrá extremo al que no me entregue para disputaros su conquista, y que, si tenéis de vuestra parte el consentimiento de una madre, yo tendré, quizás, otras ayudas, que lucharán por mí."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo, bergante! ¿Tienes la osadía de entrar en rivalidad conmigo? CLEANTO. Sois vos el que lo hace conmigo; soy el primero conforme a fecha. HARPAGÓN. ¿No soy tu padre y no me debes respeto?"}, {"type": "p", "text": "CLEANTO. Éstas no son cosas en que los hijos estén obligados a ceder ante los padres, y el amor no conoce a nadie."}, {"type": "p", "text": "HARPAGÓN. Ya te haré conocerme bien, merced a unos buenos palos."}, {"type": "p", "text": "CLEANTO. Todas vuestras amenazas no servirán de nada."}, {"type": "p", "text": "HARPAGÓN. ¿Renunciarás a Mariana?"}, {"type": "p", "text": "CLEANTO. En modo alguno."}, {"type": "p", "text": "HARPAGÓN. ¡Traedme un palo en seguida!"}]$lira$::jsonb, 729);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 35, 'Acto cuarto · Escena IV', $lira$[{"type": "p", "text": "HARPAGÓN, CLEANTO y MAESE SANTIAGO"}, {"type": "p", "text": "MAESE SANTIAGO. ¡Eh, eh, señores! ¿Qué es esto? ¿En qué pensáis?"}, {"type": "p", "text": "CLEANTO. Me río de eso."}, {"type": "p", "text": "MAESE SANTIAGO. (A Cleanto.) ¡Ah, señor! ¡Cuidado!"}, {"type": "p", "text": "HARPAGÓN. ¡Hablarme con ese descaro!"}, {"type": "p", "text": "MAESE SANTIAGO. (A Harpagón.) ¡Ah, señor, por favor!"}, {"type": "p", "text": "CLEANTO. No desistiré nunca."}, {"type": "p", "text": "MAESE SANTIAGO. (A Cleanto.) ¡Eh! ¿Cómo? ¿A vuestro padre...?"}, {"type": "p", "text": "HARPAGÓN. Déjame hacer."}, {"type": "p", "text": "MAESE SANTIAGO. (A Harpagón.) ¡Eh! ¿Cómo? ¿A vuestro hijo...? Conmigo pase todavía."}, {"type": "p", "text": "HARPAGÓN. Quiero hacerte a ti, maese Santiago, juez en este asunto, para demostrar que tengo razón."}, {"type": "p", "text": "MAESE SANTIAGO. Accedo a ello. (A Cleanto.) Alejaos un poco."}, {"type": "p", "text": "HARPAGÓN. Amo a una joven con la que quiero casarme, y ese bergante tiene la insolencia de amarla también y de pretenderla, pese a mis órdenes."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Ah! Hace mal."}, {"type": "p", "text": "HARPAGÓN. ¿No es cosa horrenda el que un hijo quiera entrar en rivalidad con su padre? ¿Y no debe él, por respeto, abstenerse de enfrentarse con mis inclinaciones? MAESE SANTIAGO. Tenéis razón. Dejadme hablar, y quedaos aquí."}, {"type": "p", "text": "CLEANTO. (A Maese Santiago, que se acerca a él.) ¡Pues bien, sí! Ya que quiere escogerte como juez, no retrocedo; no me importa, quienquiera que sea; y deseo también remitirme a ti, maese Santiago, en nuestro litigio."}, {"type": "p", "text": "MAESE SANTIAGO. Es mucho honor el que me hacéis."}, {"type": "p", "text": "CLEANTO. Estoy enamorado de una joven que corresponde a mis afanes y recibe con ternura las ofrendas de mi fidelidad, y a mi padre se le ocurre venir a trastornar nuestro amor con esa petición que ha mandado hacer."}, {"type": "p", "text": "MAESE SANTIAGO. Hace mal, seguramente."}, {"type": "p", "text": "CLEANTO. ¿No le avergüenza, a su edad, pensar en casarse? ¿Resulta propio en él sentirse aún enamorado? ¿Y no debería dejar semejante ocupación a los jóvenes? MAESE SANTIAGO. Tenéis razón. Se está burlando. Dejadme que le diga dos palabras. (A Harpagón.) ¡Pues bien! Vuestro hijo no es tan raro como decís, y se pone en razón. Dice que sabe el respeto que os debe. Que se ha acalorado en el primer impulso, y que no se niega a someterse a lo que os plazca, con tal de que le tratéis mejor que hasta ahora, y le deis una persona en matrimonio con la que se sienta satisfecho. HARPAGÓN. ¡Ah! Dile, maese Santiago, que, siendo así, podrá esperarlo todo de mí y que, excepto a Mariana, le dejo en libertad para elegir la que quiera."}, {"type": "p", "text": "MAESE SANTIAGO. Dejadme hacer. (A Cleanto.) ¡Pues bien! Vuestro padre es más razonable de lo que decís, y me ha demostrado que son vuestros arrebatos los que le han encolerizado; que sólo encuentra mal vuestra manera de obrar, y que está enteramente dispuesto a concederos lo que deseáis, con tal que lo solicitéis por las buenas, guardándole las diferencias, los respetos y la sumisión que debe un hijo a su padre. CLEANTO. ¡Ah, maese Santiago! Puedes asegurarle que si me concede a Mariana, encontrará siempre en mí al más sumiso de todos los hombres, y que no haré nunca nada contrario a sus deseos."}, {"type": "p", "text": "MAESE SANTIAGO. (A Harpagón.) Hecho. Consiente en lo que decís."}, {"type": "p", "text": "HARPAGÓN. Esto marcha lo mejor del mundo."}, {"type": "p", "text": "MAESE SANTIAGO. (A Cleanto.) Todo está arreglado; le satisfacen vuestras promesas."}, {"type": "p", "text": "CLEANTO. ¡Alabado sea el Cielo!"}, {"type": "p", "text": "MAESE SANTIAGO. Señores, no tenéis ya más que poneros a hablar; héteos ahora de acuerdo, e ibais a reñir por no saber entenderos."}, {"type": "p", "text": "CLEANTO. Mi pobre maese Santiago, te estaré agradecido toda mi vida."}, {"type": "p", "text": "MAESE SANTIAGO. No hay de qué, señor."}, {"type": "p", "text": "HARPAGÓN. Me has dado una alegría, maese Santiago, y esto merece una"}, {"type": "p", "text": "recompensa. (Harpagón se registra el bolsillo; maese Santiago alarga la mano, pero Harpagón saca tan sólo su pañuelo, diciendo): Vete; no lo olvidaré, te lo aseguro. MAESE SANTIAGO. Os beso las manos."}]$lira$::jsonb, 609);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 36, 'Acto cuarto · Escena V', $lira$[{"type": "p", "text": "HARPAGÓN y CLEANTO"}, {"type": "p", "text": "CLEANTO. Os pido perdón, padre mío, por el arrebato que he padecido."}, {"type": "p", "text": "HARPAGÓN. Eso no es nada."}, {"type": "p", "text": "CLEANTO. Os aseguro que lo lamento profundamente."}, {"type": "p", "text": "HARPAGÓN. Y yo siento el mayor gozo del mundo viéndote razonable."}, {"type": "p", "text": "CLEANTO. ¡Qué bondad la vuestra olvidando tan pronto mi falta!"}, {"type": "p", "text": "HARPAGÓN. Se olvidan fácilmente las faltas de los hijos cuando éstos vuelven a sus deberes."}, {"type": "p", "text": "CLEANTO. ¡Cómo! ¿Sin guardar ningún resentimiento a todas mis extravagancias? HARPAGÓN. Es una cosa a la que me obligas con la sumisión y el respeto en que te colocas."}, {"type": "p", "text": "CLEANTO. Os prometo, padre mío, que conservaré hasta la tumba en mi corazón el recuerdo de vuestras bondades."}, {"type": "p", "text": "HARPAGÓN. Y yo te prometo que no habrá cosa alguna que no logres de mí. CLEANTO. ¡Ah, padre mío! Ya no os pido nada; y es haberme ya dado bastante el concederme a Mariana."}, {"type": "p", "text": "HARPAGÓN. ¿Cómo?"}, {"type": "p", "text": "CLEANTO. Digo, padre mío, que estoy harto contento de vos y que lo encuentro todo en vuestra bondad concediéndome a Mariana."}, {"type": "p", "text": "HARPAGÓN. ¿Quién habla de concederte a Mariana?"}, {"type": "p", "text": "CLEANTO. Vos, padre mío."}, {"type": "p", "text": "HARPAGÓN. ¿Yo?"}, {"type": "p", "text": "CLEANTO. Sin duda."}, {"type": "p", "text": "HARPAGÓN. ¿Cómo? Eres tú quien ha prometido renunciar a ella."}, {"type": "p", "text": "CLEANTO. ¿Yo renunciar a ella?"}, {"type": "p", "text": "HARPAGÓN. Sí."}, {"type": "p", "text": "CLEANTO. En modo alguno."}, {"type": "p", "text": "HARPAGÓN. ¿No has desistido de tu pretensión?"}, {"type": "p", "text": "CLEANTO. Al contrario: estoy más decidido que nunca a realizarla."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo, bergante! ¿Otra vez?"}, {"type": "p", "text": "CLEANTO. Nada podrá hacerme variar."}, {"type": "p", "text": "HARPAGÓN. ¡Déjame hacer, traidor!"}, {"type": "p", "text": "CLEANTO. Haced cuanto os plazca."}, {"type": "p", "text": "HARPAGÓN. Te prohíbo que vuelvas jamás a verme."}, {"type": "p", "text": "CLEANTO. Bien está."}, {"type": "p", "text": "HARPAGÓN. Te abandono..."}, {"type": "p", "text": "CLEANTO. Abandonadme."}, {"type": "p", "text": "HARPAGÓN. Te repudio como hijo."}, {"type": "p", "text": "CLEANTO. Sea."}, {"type": "p", "text": "HARPAGÓN. Te desheredo."}, {"type": "p", "text": "CLEANTO. Todo cuanto queráis."}, {"type": "p", "text": "HARPAGÓN. Y lanzo sobre ti mi maldición."}, {"type": "p", "text": "CLEANTO. No me importan vuestros dones."}]$lira$::jsonb, 283);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 37, 'Acto cuarto · Escena VI', $lira$[{"type": "p", "text": "CLEANTO y FLECHA"}, {"type": "p", "text": "FLECHA. (Saliendo del jardín con una arquilla.) ¡Ah, señor, qué oportunamente os encuentro! Seguidme de prisa."}, {"type": "p", "text": "CLEANTO. ¿Qué sucede?"}, {"type": "p", "text": "FLECHA. Seguidme, os digo; estamos de suerte."}, {"type": "p", "text": "CLEANTO. ¿Cómo?"}, {"type": "p", "text": "FLECHA. Aquí está vuestra solución."}, {"type": "p", "text": "CLEANTO. ¿Qué?"}, {"type": "p", "text": "FLECHA. He estado echándole el ojo a esto todo el día."}, {"type": "p", "text": "CLEANTO. ¿Qué es esto?"}, {"type": "p", "text": "FLECHA. El tesoro de vuestro padre, que he birlado."}, {"type": "p", "text": "CLEANTO. ¿Cómo te las has compuesto...?"}, {"type": "p", "text": "FLECHA. Lo sabréis todo. Huyamos; le oigo gritar."}]$lira$::jsonb, 76);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 38, 'Acto cuarto · Escena VII', $lira$[{"type": "p", "text": "HARPAGÓN, solo HARPAGÓN. (Llega gritando desde el jardín y sin sombrero.) ¡Al ladrón! ¡Al ladrón! ¡Al ladrón! ¡Al asesino! ¡Al criminal! ¡Justicia, justo Cielo! ¡Estoy perdido! ¡Asesinado! ¡Me han cortado el cuello! ¡Me han robado mi dinero! ¿Quién podrá ser? ¿Qué ha sido de él? ¿Dónde está? ¿Dónde se esconde? ¿Qué haré para encontrarlo? ¿Adónde correr? ¿Adónde no correr? ¿No está ahí? ¿No está ahí? ¿Quién es? ¡Detente! ¡Devuélveme mi dinero, bandido!... (A sí mismo, cogiéndose del brazo.) ¡Ah, soy yo! Mi ánimo está trastornado; no sé dónde me encuentro, ni quién soy, ni lo que hago. ¡Ay! ¡Mi pobre! ¡Mi pobre dinero! ¡Mi más querido amigo! Me han privado de ti, y, puesto que me has sido arrebatado, he perdido mi sostén, mi consuelo, mi alegría; se ha acabado todo para mí, y ya no tengo nada que hacer en el mundo. Sin ti no puedo vivir. Se acabó; ya no puedo más; me muero; estoy muerto; estoy enterrado. ¿No hay nadie que quiera resucitarme, devolviéndome mi dinero o diciéndome quién lo ha cogido? ¡Eh! ¿Qué decís? No hay nadie. Es preciso que quienquiera que sea el que ha dado el golpe haya acechado el momento con mucho cuidado, y han escogido precisamente el rato en que hablaba yo con el traidor de mi hijo. Salgamos. Voy en busca de la Justicia, y haré que den tormento a todos los de mi casa: a sirvientas, a criados, al hijo, a la hija y también a mí. ¡Cuánta gente reunida! No pongo la mirada en nadie que no suscite mis sospechas, y todos me parecen ser el ladrón. ¡Eh! ¿De qué han hablado ahí? ¿Del que me ha robado? ¿Qué ruido hacen arriba? ¿Está ahí mi ladrón? Por favor, si saben noticias de mi ladrón, suplico que me las digan. ¿No está escondido entre vosotros? Todos me miran y se echan a reír. Ya veréis cómo han tomado parte, sin duda, en el robo de que he sido víctima. ¡Vamos, de prisa, comisarios, alguaciles, prebostes, jueces, tormentos, horcas y verdugos! Quiero hacer colgar a todo el mundo, y si no encuentro mi dinero, me ahorcaré yo mismo después."}]$lira$::jsonb, 358);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 39, 'Acto quinto · Escena primera', $lira$[{"type": "p", "text": "HARPAGÓN, el COMISARIO y su ESCRIBIENTE"}, {"type": "p", "text": "COMISARIO. Dejadme hacer; conozco mi oficio, a Dios gracias. No es hoy la primera vez que intervengo para descubrir robos, y quisiera yo tener tantos sacos de mil francos como personas he mandado ahorcar."}, {"type": "p", "text": "HARPAGÓN. Todos los magistrados están interesados en llevar este asunto; y si no me hacen recuperar mi dinero, pediré justicia de la Justicia."}, {"type": "p", "text": "COMISARIO. Hay que efectuar todas las indagaciones requeridas. ¿Decíais que había en esa arquilla...?"}, {"type": "p", "text": "HARPAGÓN. Diez mil escudos bien contados."}, {"type": "p", "text": "COMISARIO. ¡Diez mil escudos!"}, {"type": "p", "text": "HARPAGÓN. Diez mil escudos."}, {"type": "p", "text": "COMISARIO. ¡El robo es importante!"}, {"type": "p", "text": "HARPAGÓN. No existe suplicio bastante grande para la enormidad de ese crimen, y si queda impune, las cosas más sagradas no estarán ya seguras."}, {"type": "p", "text": "COMISARIO. ¿Y en qué monedas estaba esa suma?"}, {"type": "p", "text": "HARPAGÓN. En buenos luises de oro y en pistolas de peso corrido. COMISARIO. ¿Quién sospecháis que pueda ser el autor de este robo? HARPAGÓN. Todo el mundo; y quiero que encarceléis a la ciudad y los arrabales."}, {"type": "p", "text": "COMISARIO. Es necesario, creedme, no asustar a nadie y procurar atrapar con cautela algunas pruebas, a fin de proceder luego con todo rigor a la recuperación de las monedas que os han sido robadas."}]$lira$::jsonb, 199);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 40, 'Acto quinto · Escena II', $lira$[{"type": "p", "text": "HARPAGÓN, el COMISARIO, su ESCRIBIENTE y MAESE SANTIAGO"}, {"type": "p", "text": "MAESE SANTIAGO. (Al fondo de la escena, volviéndose hacia el lado por donde ha salido.) Ahora vuelvo. Que lo degüellen en seguida, que le tuesten los pies, que lo pongan en agua hirviendo y que lo cuelguen del techo."}, {"type": "p", "text": "HARPAGÓN. (A Maese Santiago.) ¿A quién? ¿Al que me ha robado?"}, {"type": "p", "text": "MAESE SANTIAGO. Hablo de un lechoncillo que acaba de enviarme vuestro"}, {"type": "p", "text": "intendente y que voy a aderezar a mi manera."}, {"type": "p", "text": "HARPAGÓN. No se trata de eso, y aquí está el señor con quien hay que hablar de otra cosa."}, {"type": "p", "text": "COMISARIO. (A Maese Santiago.) No os asustéis. No soy hombre que os difame, y las cosas marcharán sin tropiezos."}, {"type": "p", "text": "MAESE SANTIAGO. ¿El señor está invitado a cenar?"}, {"type": "p", "text": "COMISARIO. Es preciso, mi querido amigo, no ocultar nada a vuestro amo. MAESE SANTIAGO. A fe mía, señor, mostraré todo cuanto sé hacer y os trataré lo mejor que sea posible."}, {"type": "p", "text": "HARPAGÓN. No se trata de eso."}, {"type": "p", "text": "MAESE SANTIAGO. Si no os obsequio como quisiera, es culpa del señor intendente, que me ha recortado las alas con las tijeras de su economía."}, {"type": "p", "text": "HARPAGÓN. ¡Traidor! No se trata ahora de la cena, y quiero que me des noticias del dinero que me han quitado."}, {"type": "p", "text": "MAESE SANTIAGO. ¿Os han quitado dinero?"}, {"type": "p", "text": "HARPAGÓN. Sí, truhán; y voy a hacer que te ahorquen si no me lo devuelves. COMISARIO. (A Harpagón.) ¡Dios mío! No le maltratéis. Veo por su cara que es un hombre honrado, y que, sin necesidad de meterlo en la cárcel, os descubrirá lo que queréis saber. Sí, amigo mío; si nos confesáis la cosa, no se os hará ningún daño y seréis recompensado como es debido por vuestro amo. Le han quitado hoy su dinero, y tenéis que saber alguna noticia de ese asunto."}, {"type": "p", "text": "MAESE SANTIAGO. (Bajo, aparte.) He aquí justamente lo que necesito para vengarme de nuestro intendente. Desde que ha entrado aquí es el favorito; sólo se escuchan sus consejos, y tengo también contra él el agravio de los palos recientes."}, {"type": "p", "text": "HARPAGÓN. ¿Qué estás rumiando?"}, {"type": "p", "text": "COMISARIO. (A Harpagón.) Dejadme hacer. Se dispone a complaceros, y ya os he dicho que era un hombre honrado."}, {"type": "p", "text": "MAESE SANTIAGO. Señor, si queréis que os diga las cosas, creo que es vuestro querido intendente quien ha dado el golpe."}, {"type": "p", "text": "HARPAGÓN. ¿Valerio?"}, {"type": "p", "text": "MAESE SANTIAGO. Sí."}, {"type": "p", "text": "HARPAGÓN. ¡Él que me parecía tan fiel!"}, {"type": "p", "text": "MAESE SANTIAGO. Sí; él mismo. Creo que ha sido quien os ha robado."}, {"type": "p", "text": "HARPAGÓN. ¿Y por qué lo crees?"}, {"type": "p", "text": "MAESE SANTIAGO. ¿Por qué?"}, {"type": "p", "text": "HARPAGÓN. Sí..."}, {"type": "p", "text": "MAESE SANTIAGO Lo creo... porque lo creo."}, {"type": "p", "text": "COMISARIO. Mas es preciso decir los indicios que tenéis."}, {"type": "p", "text": "HARPAGÓN. ¿Le has visto merodear alrededor del sitio donde había yo puesto mi dinero?"}, {"type": "p", "text": "MAESE SANTIAGO. Sí, en verdad. ¿Dónde estaba vuestro dinero?"}, {"type": "p", "text": "HARPAGÓN. En el jardín."}, {"type": "p", "text": "MAESE SANTIAGO. Justamente; le he visto merodear por el jardín. ¿Y dónde estaba guardado ese dinero?"}, {"type": "p", "text": "HARPAGÓN. En una arquilla."}, {"type": "p", "text": "MAESE SANTIAGO. Ahí está el asunto. Le he visto con una arquilla."}, {"type": "p", "text": "HARPAGÓN. ¿Y cómo era esa arquilla? Veré si es la mía."}, {"type": "p", "text": "MAESE SANTIAGO. ¿Cómo es?"}, {"type": "p", "text": "HARPAGÓN. Sí."}, {"type": "p", "text": "MAESE SANTIAGO. Es... es como una arquilla."}, {"type": "p", "text": "COMISARIO. Por supuesto. Mas describidla un poco para que veamos..."}, {"type": "p", "text": "MAESE SANTIAGO. Es una arquilla grande."}, {"type": "p", "text": "HARPAGÓN. La que me han robado es pequeña."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Ah, sí! Es pequeña si se quiere tomarlo por ahí; mas yo la llamo grande por lo que contiene."}, {"type": "p", "text": "COMISARIO. ¿Y de qué color es?"}, {"type": "p", "text": "MAESE SANTIAGO. ¿De qué color?"}, {"type": "p", "text": "COMISARIO. Sí."}, {"type": "p", "text": "MAESE SANTIAGO. Es de color...; eso es, de cierto color... ¿No podríais ayudarme a hablar?"}, {"type": "p", "text": "HARPAGÓN. ¡Pchs!"}, {"type": "p", "text": "MAESE SANTIAGO. ¿No es roja?"}, {"type": "p", "text": "HARPAGÓN. No; gris."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Ah, sí! Roja-gris, eso es lo que quería decir."}, {"type": "p", "text": "HARPAGÓN. No hay duda alguna; es ella evidentemente. Escribid, señor, escribid su declaración. ¡Cielos! ¿De quién fiarse en lo sucesivo? No hay que decir nunca de esta agua no beberé; creo, después de esto, que acabaré por robarme a mí mismo. MAESE SANTIAGO. (A Harpagón.) Señor, aquí vuelve. No vayáis a decirle, por lo menos, que soy yo quien os ha descubierto eso."}]$lira$::jsonb, 674);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 41, 'Acto quinto · Escena III', $lira$[{"type": "p", "text": "HARPAGÓN, el COMISARIO, su ESCRIBIENTE, VALERIO y MAESE SANTIAGO"}, {"type": "p", "text": "HARPAGÓN. Acércate; ven a confesar la más negra acción, el atentado más horrible que se haya cometido nunca."}, {"type": "p", "text": "VALERIO. ¿Qué queréis, señor?"}, {"type": "p", "text": "HARPAGÓN. ¡Cómo, traidor! ¿No te avergüenzas de tu crimen?"}, {"type": "p", "text": "VALERIO. ¿De qué crimen queréis hablar?"}, {"type": "p", "text": "HARPAGÓN. ¿De qué crimen quiero hablar, infame? ¡Como si no supieras lo que quiero decir! Es inútil que pretendas encubrirlo; está descubierto el asunto y acaban de contármelo todo. ¡Cómo! ¡Abusar así de mi bondad, introducirte deliberadamente en mi casa para traicionarme y hacerme una jugarreta de esta naturaleza!"}, {"type": "p", "text": "VALERIO. Señor, puesto que os han descubierto todo, no quiero emplear rodeos ni negaros la acción."}, {"type": "p", "text": "MAESE SANTIAGO. (Aparte.) ¡Oh, oh! ¿Habré yo adivinado sin saberlo?"}, {"type": "p", "text": "VALERIO. Era propósito mío hablaros de ello, y quería esperar para hacerlo a unas circunstancias favorables; mas puesto que es así, os ruego que no os enojéis y que accedáis a escuchar mis razones."}, {"type": "p", "text": "HARPAGÓN. ¿Y qué lindas razones puedes darme, infame ladrón?"}, {"type": "p", "text": "VALERIO. ¡Ah, señor! No merezco esos nombres. Cierto es que he cometido una ofensa contra vos; mas, después de todo, mi culpa es perdonable."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo...! ¿Perdonable! ¿Una traición, un asesinato de este género...? VALERIO. Por favor, no os encolericéis. Cuando me hayáis oído, veréis que el daño no es tan grande como creéis."}, {"type": "p", "text": "HARPAGÓN. ¡Que no es tan grande el daño como creo! ¡Cómo! ¡Mi sangre, mis entrañas, bergante!"}, {"type": "p", "text": "VALERIO. Vuestra sangre, señor, no ha caído en malas manos. Soy de una clase que no la perjudicará, y no hay nada, en todo esto, que no pueda yo reparar."}, {"type": "p", "text": "HARPAGÓN. Esa es mi intención, y que me restituyas lo que me has quitado. VALERIO. Vuestra honra, señor, quedará plenamente satisfecha."}, {"type": "p", "text": "HARPAGÓN. No se trata aquí de la honra. Mas dime: ¿quién te ha impulsado a esa acción?"}, {"type": "p", "text": "VALERIO. ¡Ay! ¿Me lo preguntáis?"}, {"type": "p", "text": "HARPAGÓN. Sí; te lo pregunto, en efecto."}, {"type": "p", "text": "VALERIO. Un dios que lleva en sí la disculpa de todo cuanto obliga a hacer: el Amor. HARPAGÓN. ¿El amor?"}, {"type": "p", "text": "VALERIO. Sí."}, {"type": "p", "text": "HARPAGÓN. ¡Bonito amor, bonito amor, a fe mía! ¡El amor a mis luises de oro! VALERIO. No, señor; no son vuestras riquezas las que me han tentado; no es eso lo que me ha deslumbrado, y os aseguro que no aspiro, en modo alguno, a vuestros bienes, con tal que me dejéis el que poseo."}, {"type": "p", "text": "HARPAGÓN. ¡No lo haré, por todos los diablos! No te lo dejaré. ¡Mas ved su insolencia queriendo quedarse con lo que me ha robado!"}, {"type": "p", "text": "VALERIO. ¿Y llamáis a eso robo?"}, {"type": "p", "text": "HARPAGÓN. ¿Que si lo llamo robo? ¡Un tesoro como éste!"}, {"type": "p", "text": "VALERIO. Es un tesoro, verdaderamente, y el más preciado que poseéis, sin duda; mas no lo perderéis dejándomelo. Os pido de rodillas ese tesoro lleno de encantos, y si queréis obrar bien, habréis de concedérmelo."}, {"type": "p", "text": "HARPAGÓN. No haré tal. ¿Qué quiere esto decir?"}, {"type": "p", "text": "VALERIO. Nos hemos prometido fidelidad mutua y hemos jurado no separarnos. HARPAGÓN. ¡Admirable juramento y divertida promesa!"}, {"type": "p", "text": "VALERIO. Sí; nos hemos comprometido a ser el uno del otro para siempre. HARPAGÓN. Os lo impediré; estad seguro."}, {"type": "p", "text": "VALERIO. Solamente la muerte puede separarnos."}, {"type": "p", "text": "HARPAGÓN. ¡Eso es estar maniático por mi dinero!"}, {"type": "p", "text": "VALERIO. Ya os he dicho, señor, que no era el interés lo que me había empujado a hacer lo que he hecho. Mi corazón no ha obrado por los móviles que imagináis, y un motivo más noble me ha inspirado esta resolución."}, {"type": "p", "text": "HARPAGÓN. ¡Ya veréis cómo resulta que quiere quedarse con mi caudal por caridad cristiana! Mas yo tomare mis medidas, y la Justicia, descarado bergante, va a ampararme en todo."}, {"type": "p", "text": "VALERIO. Empleadla como queráis; estoy dispuesto a sufrir cuantas violencias os plazcan; mas os ruego que creáis, al menos, que si existe perjuicio, sólo debe acusárseme a mí, y que vuestra hija no tiene culpa en todo ello."}, {"type": "p", "text": "HARPAGÓN. Así lo creo, realmente; sería muy extraño que mi hija hubiera estado complicada en este crimen. Mas quiero recuperar mi fortuna y que me confieses adónde la has llevado."}, {"type": "p", "text": "VALERIO. ¿Yo? No la he llevado a ningún sitio; sigue en vuestra casa."}, {"type": "p", "text": "HARPAGÓN. (Aparte.) ¡Oh, mi querida arquilla! (Alto.) ¿No ha salido de mi casa? VALERIO. No, señor."}, {"type": "p", "text": "HARPAGÓN. ¡Eh! Dime entonces: ¿no la has tocado?"}, {"type": "p", "text": "VALERIO. ¡Tocarla yo! ¡Ah!, la ofendéis, e igualmente a mí. Y la pasión que por ella siento es muy pura y muy respetuosa."}, {"type": "p", "text": "HARPAGÓN. (Aparte.) ¡Que siente pasión por mi arquilla!"}, {"type": "p", "text": "VALERIO. Preferiría morir antes que dedicarle un pensamiento ofensivo: es ella demasiado digna y no menos honesta para eso."}, {"type": "p", "text": "HARPAGÓN. (Aparte.) ¡Que mi arquilla es demasiado honesta!"}, {"type": "p", "text": "VALERIO. Todos mis deseos se han reducido a gozar de su contemplación, y nada que sea criminal ha profanado la pasión que sus bellos ojos me han inspirado. HARPAGÓN. ¡Los bellos ojos de mi arquilla! Habla de ella como un enamorado de su amada."}, {"type": "p", "text": "VALERIO. Doña Claudia, señor, sabe la verdad de esta aventura, y ella puede atestiguar..."}, {"type": "p", "text": "HARPAGÓN. ¡Cómo! ¿Mi sirvienta es cómplice del negocio?"}, {"type": "p", "text": "VALERIO. Sí, señor; ha sido testigo de nuestro compromiso, y sólo después de conocer la honestidad de mi pasión me ha ayudado a convencer a vuestra hija de que me entregase su palabra y de que aceptara la mía."}, {"type": "p", "text": "HARPAGÓN. (Aparte.) ¡Eh! ¿Es que el miedo a la Justicia le hace desvariar? (A Valerio.) ¿Por qué mezclar a mi hija en esto?"}, {"type": "p", "text": "VALERIO. Digo, señor, que me ha costado grandísimo trabajo hacer que consintiera su pudor en lo que mi amor deseaba."}, {"type": "p", "text": "HARPAGÓN. El pudor, ¿de quién?"}, {"type": "p", "text": "VALERIO. De vuestra hija, y tan sólo desde ayer ha querido dedicarse a que firmásemos una promesa de casamiento."}, {"type": "p", "text": "HARPAGÓN. ¿Mi hija te ha firmado una promesa de casamiento?"}, {"type": "p", "text": "VALERIO. Sí, señor, y yo, por mi parte, le he firmado otra."}, {"type": "p", "text": "HARPAGÓN. ¡Oh, cielos, otra gran desdicha!"}, {"type": "p", "text": "MAESE SANTIAGO. (Al Comisario.) Escribid, señor, escribid."}, {"type": "p", "text": "HARPAGÓN. ¡Agravación del mal! ¡Acrecimiento de la desesperación! (Al"}, {"type": "p", "text": "Comisario.) Vamos, señor; desempeñad el deber de vuestro cargo e instruidle una querella por ladrón y por seductor."}, {"type": "p", "text": "MAESE SANTIAGO. Por ladrón y por seductor..."}, {"type": "p", "text": "VALERIO. Esos son nombres que no me corresponden, y cuando sepan quién soy..."}]$lira$::jsonb, 1012);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 42, 'Acto quinto · Escena IV', $lira$[{"type": "p", "text": "HARPAGÓN, ELISA, MARIANA, VALERIO, FROSINA, MAESE SANTIAGO, el"}, {"type": "p", "text": "COMISARIO y su ESCRIBIENTE"}, {"type": "p", "text": "HARPAGÓN. ¡Ah, hija malvada! ¡Hija indigna de un padre como yo! ¿Así es como pones en práctica las lecciones que te he dado? ¿Te enamoras de un infame ladrón y te comprometes con él sin mi consentimiento? Mas vais a quedar chasqueados el uno y el otro. (A Elisa.) Cuatro buenos muros me responderán de tu conducta. (A Valerio.) Y una buena horca domeñará tu osadía."}, {"type": "p", "text": "VALERIO. No será vuestra pasión la que juzgue el asunto, y, cuando menos, me escucharán antes de condenarme."}, {"type": "p", "text": "HARPAGÓN. Me he engañado al decir una horca: te descuartizarán vivo."}, {"type": "p", "text": "ELISA. (De rodillas ante Harpagón.) ¡Ah, padre mío! Mostrad unos sentimientos más humanos, os lo ruego, y no llevéis las cosas a las últimos extremos de la potestad paterna. No os dejéis arrastrar por los primeros arrebatos de vuestra pasión y emplead algún tiempo en reflexionar sobre lo que queréis hacer. Tomaos el trabajo de ver mejor al que consideráis ofensor vuestro. Es totalmente distinto de lo que se figuran vuestros ojos, y os parecerá menos extraño que me haya prometido a él cuando sepáis que sin él no me tendríais ya hace mucho tiempo. Sí, padre mío; él es quien me salvó de aquel gran peligro que, como sabéis, corrí en el agua, y a quien debéis la vida de esta hija, cuyo..."}, {"type": "p", "text": "HARPAGÓN. Todo eso no es nada, y valía más para mí que te hubiera dejado ahogar que hacer lo que ha hecho."}, {"type": "p", "text": "ELISA. Padre mío, os suplico, por el amor paterno, que me..."}, {"type": "p", "text": "HARPAGÓN. No, no; no quiero oír nada, y es preciso que la Justicia cumpla su deber. MAESE SANTIAGO. (Aparte.) ¡Me pagarás mis palos!"}, {"type": "p", "text": "FROSINA. (Aparte.) ¡Vaya un extraño enredo!"}]$lira$::jsonb, 293);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 43, 'Acto quinto · Escena V (1/2)', $lira$[{"type": "p", "text": "ANSELMO, HARPAGÓN, ELISA, MARIANA, FROSINA, VALERIO, el"}, {"type": "p", "text": "COMISARIO, su ESCRIBIENTE y MAESE SANTIAGO"}, {"type": "p", "text": "ANSELMO. ¿Qué pasa, señor Harpagón? Os veo todo emocionado."}, {"type": "p", "text": "HARPAGÓN. ¡Ah, señor Anselmo! Soy el más desventurado de los hombres, ¡y he aquí un trastorno y un desorden grande para el contrato que venía a formalizar! Me asesinan en mi fortuna y en mi honor, y aquí tenéis un traidor, un malvado, que, violando los sagrados derechos, se ha introducido en mi casa bajo el título de criado para robarme mi dinero y seducir a mi hija."}, {"type": "p", "text": "VALERIO. ¡Quién piensa en vuestro dinero, con el que me estáis haciendo un embrollo!"}, {"type": "p", "text": "HARPAGÓN. Sí; se han dado uno a otro promesa de casamiento. Esta afrenta os concierne, señor Anselmo, y sois vos quien debéis alzaros contra él y utilizar todas las persecuciones de la Justicia para vengaros de su insolencia."}, {"type": "p", "text": "ANSELMO. No es mi deseo hacer que se case conmigo a la fuerza. No solicitar nada de un corazón que se ha entregado ya; mas, en cuanto a vuestros intereses, estoy dispuesto a defenderlos como si fueran míos."}, {"type": "p", "text": "HARPAGÓN. Aquí tenéis al señor, que es un honrado comisario y que no olvidará nada, según me ha dicho, en las funciones de su cargo. (Al Comisario, señalando a Valerio.) Encartadle como es debido, señor, y haced que los hechos tengan la mayor criminalidad."}, {"type": "p", "text": "VALERIO. No veo qué crimen pueden imputarme por la pasión que siento hacia vuestra hija, ni tampoco comprendo a qué suplicio creéis que puedo ser condenado por nuestro compromiso cuando se sepa quién soy..."}, {"type": "p", "text": "HARPAGÓN. Me río de todos vuestros cuentos, y el mundo está hoy lleno de estos ladrones de nobleza, de estos impostores que sacan provecho de su oscuridad y se revisten insolentemente con el primer nombre ilustre que se les ocurre adoptar. VALERIO. Sabed que poseo un corazón demasiado digno para adornarme con algo que no sea mío, y que todo Nápoles puede dar fe de mi alcurnia."}, {"type": "p", "text": "ANSELMO. ¡Poco a poco! Tened cuidado con lo que vais a decir. Arriesgáis aquí más de lo que pensáis, y estáis hablando delante de un hombre que conoce a todo Nápoles, y a quien le será fácil discernir con claridad en la historia que contáis. VALERIO. (Cubriéndose altivamente.) Soy hombre que no tiene nada que temer, y si conocéis a Nápoles, sabréis quién era don Tomás de Alburci."}, {"type": "p", "text": "ANSELMO. Sin duda que lo sé, y pocas personas le han conocido mejor que yo. HARPAGÓN. Me tienen sin cuidado don Tomás o don Martín. (Harpagón ve que están encendidas dos velas y apaga una.)"}, {"type": "p", "text": "ANSELMO. Por favor, dejadle hablar; veremos lo que quiere decir."}, {"type": "p", "text": "VALERIO. Quiero decir que él fue quien me dio la vida."}, {"type": "p", "text": "ANSELMO. ¡Él!"}, {"type": "p", "text": "VALERIO. Sí."}, {"type": "p", "text": "ANSELMO. Vamos, bromeáis. Buscad otro cuento que pueda resultaros mejor y no pretendáis salvaros con esa impostura."}, {"type": "p", "text": "VALERIO. Cuidad vuestras palabras. No es ninguna impostura, y no anticipo nada que no me sea fácil justificar."}, {"type": "p", "text": "ANSELMO. ¿Cómo? ¡Os atrevéis a llamaros hijo de don Tomás de Alburci?"}, {"type": "p", "text": "VALERIO. Sí; me atrevo a ello, y estoy dispuesto a sostener esta verdad ante quien sea. ANSELMO. ¡Maravillosa osadía! Sabed, para confusión vuestra, que hace dieciséis años, cuando menos, el hombre de quien nos habláis pereció en el mar con sus hijos y su esposa al querer salvar sus vidas de las persecuciones que acompañaron las revueltas de Nápoles y que hicieron expatriarse a varias nobles familias."}, {"type": "p", "text": "VALERIO. Sí; mas sabed, para confundiros, a mi vez, que su hijo, de siete años de edad, fue salvado, en unión de un criado, de ese naufragio, por un navío español, y que este hijo salvado es el que os habla. Sabed también que el capitán de ese navío, conmovido ante mi suerte, me consagró su amistad, me hizo educar como su propio hijo, y que las armas fueron mi ocupación en cuanto estuve en aptitud de ello; que he sabido hace poco que mi padre no había muerto, como yo creí siempre; que, al pasar por aquí para ir en su busca, una aventura, concertada por el Cielo, me hizo ver a la encantadora Elisa; que este encuentro me hizo esclavo de sus bellezas y que la violencia de mi amor y las severidades de su padre me hicieron tomar la resolución de introducirme en su casa y de enviar a otro en busca de mi padre."}]$lira$::jsonb, 725);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 44, 'Acto quinto · Escena V (2/2)', $lira$[{"type": "p", "text": "ANSELMO. Mas ¿qué nuevas pruebas aparte de vuestras palabras, pueden"}, {"type": "p", "text": "garantizarnos de que no sea ésta acaso una fábula que hayáis edificado sobre una verdad?"}, {"type": "p", "text": "VALERIO. El capitán español; un sello de rubíes, que era de mi padre; un brazalete de ágata, que mi madre me había puesto en el brazo, y el viejo Pedro, ese criado que se salvó conmigo del naufragio."}, {"type": "p", "text": "MARIANA. ¡Ah! Puedo responder aquí de vuestras palabras, yo, a quien no engañáis, y todo cuanto decís me hace saber claramente que sois mi hermano."}, {"type": "p", "text": "VALERIO. ¡Vos mi hermana!"}, {"type": "p", "text": "MARIANA. Sí. Mi corazón se ha conmovido no bien abristeis la boca, y nuestra madre, a quien vais a cautivar, me habló mil veces de los infortunios de nuestra familia. El Cielo no nos hizo perecer tampoco en ese triste naufragio; mas nos salvó la vida y nos privó de libertad: fueron unos corsarios los que nos recogieron a mi madre y a mí sobre unos restos de nuestro navío. Después de diez años de esclavitud, una suerte venturosa nos devolvió nuestra libertad y regresamos a Nápoles, donde encontramos todos nuestros bienes vendidos, sin que pudiéramos saber allí noticias de nuestro padre. Nos trasladamos a Génova, adonde mi madre fue a recoger los míseros residuos de una herencia que había sido anulada, y desde allí, huyendo de la bárbara injusticia de sus parientes, vino ella a estos lugares, en donde ha vivido tan sólo una vida casi mísera. ANSELMO. ¡Oh, Cielos! ¡Qué rasgos los de tu poder y cuán claramente haces ver que sólo a ti te pertenece el don de hacer milagros! Abrazadme, hijos míos, y unid vuestros transportes a los de vuestro padre."}, {"type": "p", "text": "VALERIO. ¿Sois nuestro padre?"}, {"type": "p", "text": "MARIANA. ¿Sois vos al que mi madre ha llorado tanto?"}, {"type": "p", "text": "ANSELMO. Sí, hija mía; sí, hijo mío; soy don Tomás de Alburci, a quien el Cielo preservó de las ondas con todo el dinero que llevaba, y que, creyéndoos muertos a todos, durante dieciséis años, se disponía ahora, después de largos viajes, a buscar en el himeneo con una dulce y discreta persona el consuelo de una nueva familia. La escasa seguridad que para mi vida he podido apreciar si volvía a Nápoles me ha hecho renunciar a ello para siempre, y habiendo sabido encontrar medios de hacer que se vendiera allí lo que poseía, me he acostumbrado a vivir aquí, donde, bajo el nombre de Anselmo, he querido alejar de mí las penas de ese otro nombre, que tantos sinsabores me ocasionó."}, {"type": "p", "text": "HARPAGÓN. (A Anselmo.) ¿Éste es vuestro hijo?"}, {"type": "p", "text": "ANSELMO. Sí."}, {"type": "p", "text": "HARPAGÓN. Os emplazo entonces a que me paguéis diez mil escudos que me ha robado."}, {"type": "p", "text": "ANSELMO. ¿Que os ha robado él?"}, {"type": "p", "text": "HARPAGÓN. Él en persona."}, {"type": "p", "text": "VALERIO. ¿Quién os ha dicho eso?"}, {"type": "p", "text": "HARPAGÓN. Maese Santiago."}, {"type": "p", "text": "VALERIO. (A Maese Santiago.) ¿Lo has dicho tú?"}, {"type": "p", "text": "MAESE SANTIAGO. Como veis, yo no digo nada."}, {"type": "p", "text": "HARPAGÓN. Sí. Aquí está el señor comisario, que le ha tomado declaración escrita. VALERIO. ¿Podéis creerme capaz de tan cobarde acción?"}, {"type": "p", "text": "HARPAGÓN. Capaz o no, yo quiero recuperar mi dinero."}]$lira$::jsonb, 503);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-avaro', 45, 'Acto quinto · Escena VI', $lira$[{"type": "p", "text": "HARPAGÓN, ANSELMO, ELISA, MARIANA, CLEANTO, VALERIO, FROSINA,"}, {"type": "p", "text": "el COMISARIO, su ESCRIBIENTE, MAESE SANTIAGO y FLECHA"}, {"type": "p", "text": "CLEANTO. No os atormentéis padre mío, ni acuséis a nadie. He conseguido noticias de vuestro asunto, y vengo a deciros que si queréis decidiros a dejarme casar con Mariana, vuestro dinero os será devuelto."}, {"type": "p", "text": "HARPAGÓN. ¿Dónde está?"}, {"type": "p", "text": "CLEANTO. No os aflijáis. Está en un sitio del que respondo, y todo depende de mí. A vos toca decirme lo que decidís, y podéis escoger entre darme a Mariana o perder vuestra arquilla."}, {"type": "p", "text": "HARPAGÓN. ¿No han quitado nada de ella?"}, {"type": "p", "text": "CLEANTO. Nada en absoluto. Ved si es vuestra intención suscribir este casamiento y unir vuestro consentimiento al de su madre, que la deja en libertad de hacer su elección entre nosotras dos."}, {"type": "p", "text": "MARIANA. (A Cleanto.) Mas no sabéis que no basta con ese consentimiento, y que el Cielo (señalando a Valerio), con el hermano que aquí veis, acaba de devolverme un padre (señalando a Anselmo), a quien debéis pedirme."}, {"type": "p", "text": "ANSELMO. El Cielo, hijos míos, no ha vuelto a traerme entre vosotros para que contraríe vuestros anhelos. Señor Harpagón, claramente comprendéis que la elección de una joven recaerá en el hijo antes que en el padre; vamos, no hagáis que os diga lo que no es necesario que escuchéis, y consentid, como yo, en este doble himeneo. HARPAGÓN. Para buscar consejo tengo que ver mi arquilla."}, {"type": "p", "text": "CLEANTO. La veréis sana e íntegra."}, {"type": "p", "text": "HARPAGÓN. No tengo dinero que dar en matrimonio a mis hijos."}, {"type": "p", "text": "ANSELMO. Pues bien, yo lo tengo para los dos; no os preocupéis por esto. HARPAGÓN. ¿Os comprometéis a correr con todos los gastos de estos dos"}, {"type": "p", "text": "casamientos?"}, {"type": "p", "text": "ANSELMO. Sí, me comprometo a ello. ¿Estáis satisfecho?"}, {"type": "p", "text": "HARPAGÓN. Sí, con tal que me encarguéis un traje para las bodas."}, {"type": "p", "text": "ANSELMO. De acuerdo. Vamos a gozar de la dicha que este día feliz nos depara. COMISARIO. ¡Hola, señores, hola! Poco a poco, si os place. ¿Quién me abonará mis escritos?"}, {"type": "p", "text": "HARPAGÓN. De nada nos sirven vuestros escritos."}, {"type": "p", "text": "COMISARIO. ¡Sí! Mas yo no tengo la intención de haberlos hecho gratuitamente. HARPAGÓN. (Señalando a Maese Santiago.) Como pago, os entrego a este hombre para que le mandéis ahorcar."}, {"type": "p", "text": "MAESE SANTIAGO. ¡Ah! ¿Cómo hay que proceder entonces? ¡Me apalean por decir la verdad y quieren colgarme por mentir!"}, {"type": "p", "text": "ANSELMO. ¡Señor Harpagón, hay que perdonarle esa impostura!"}, {"type": "p", "text": "HARPAGÓN. ¿Pagaréis, entonces, al comisario?"}, {"type": "p", "text": "ANSELMO. Sea. Vamos pronto a participar nuestra alegría a vuestra madre. HARPAGÓN. Y yo, a ver mi arquilla querida."}, {"type": "h", "text": "Fin"}, {"type": "p", "text": "Notas 1. Dote: Bienes que aporta la mujer al matrimonio o que dan a los esposos sus padres o terceras personas, en vista de su matrimonio."}, {"type": "p", "text": "2. Chanza: Broma, burla."}, {"type": "p", "text": "3. Antiparras: Anteojos, gafas."}]$lira$::jsonb, 444);

insert into public.activities (book_id, chapter_id, kind, prompt, hint)
select 'el-avaro', c.id, 'crear', 'Elige la ropa de un personaje. Tres prendas.', null from public.chapters c
where c.book_id = 'el-avaro' and c.position = 0;
