-- ─── El sí de las niñas · Leandro Fernández de Moratín ───
delete from public.chapters where book_id = 'el-si-de-las-ninas';

insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('el-si-de-las-ninas', 'El sí de las niñas', 'Leandro Fernández de Moratín', 'A una chica de dieciséis la casan con un hombre de cincuenta y todos le preguntan si está de acuerdo. Ella dice que sí.', 'teatro', 43, 100, array['clásico', 'comedia', 'libertad']::text[], true)
on conflict (id) do update set
  title = excluded.title, author = excluded.author,
  synopsis = excluded.synopsis, category = excluded.category,
  chapter_count = excluded.chapter_count,
  minutes_to_read = excluded.minutes_to_read,
  tags = excluded.tags, is_published = true;

insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 0, 'Inicio', $lira$[{"type": "p", "text": "D. D . No, yo ya sé lo que dirán, pero... Dirán que la boda es desigual,"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que no hay proporcion en la edad, que..."}, {"type": "p", "text": "S . Vamos que no me parece tan notable la diferencia. Siete ú ocho"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "años, á lo mas..."}, {"type": "p", "text": "D. D . ¿Qué, hombre? ¿Qué hablas de siete ú ocho años? Si ella ha"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "cumplido diez y seis años pocos meses ha."}, {"type": "p", "text": "S . ¿Y bien, que?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Y yo, aunque gracias á Dios estoy robusto y... Con todo eso, mis"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "cincuenta y nueve años no hay quien me los quite."}, {"type": "p", "text": "S . Pero si yo no hablo de eso."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Pues ¿de qué hablas?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Decia que... Vamos, ó usted no acaba de esplicarse, ó yo lo"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "entiendo al revés... En suma, esta Doña Paquita, ¿con quién se casa?"}, {"type": "p", "text": "D. D . ¿Ahora estamos ahí? Conmigo."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Con usted?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Conmigo."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¡Medrados quedamos!"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . ¿Qué dices?... Vamos, ¿qué?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¡Y pensaba yo haber adivinado!"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Pues ¿qué creias? ¿Para quien juzgaste que la destinaba yo?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Para D. Cárlos, su sobrino de usted: mozo de talento, instruido,"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "excelente soldado, amabilísimo por todas sus circunstancias... Para ese juzgué que se guardaba la tal niña."}, {"type": "p", "text": "D. D . Pues no señor."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Pues bien está."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . ¡Mire usted qué idea! ¡Con el otro la habia de ir á casar!... No"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "señor, que estudie sus matemáticas."}, {"type": "p", "text": "S . Ya las estudia, ó por mejor decir, ya las enseña."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Que se haga hombre de valor y..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¡Valor! ¿Todavía pide usted mas valor á un oficial que en la"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "última guerra, con muy pocos que se atrevieron á seguirle, tomó dos baterías, clavó los cañones, hizo algunos prisioneros, y volvió al campo lleno de heridas y cubierto de sangre?... Pues bien satisfecho quedó usted entonces del valor de su sobrino; y yo le ví á usted mas de cuatro veces llorar de alegría, cuando el Rey le premió con el grado de teniente coronel y una cruz de Alcántara. D. D . Sí, señor: todo eso es verdad; pero no viene á cuento. Yo soy el"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que me caso."}, {"type": "p", "text": "S . Si está usted bien seguro de que ella le quiere, si no la asusta la"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "diferencia de la edad, si su elecciones libre..."}, {"type": "p", "text": "D. D . ¿Pues no ha de serlo?... Y ¿qué sacarian con engañarme? Ya ves"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "tú la religiosa de Guadalajara si es mujer de juicio: esta de Alcalá, aunque no la conozco, sé que es una señora de escelentes prendas: mira tú si Doña Irene querrá el bien de su hija, pues todas ellas me han dado cuantas seguridades puedo apetecer... La criada, que la ha servido en Madrid y mas de cuatro años en el convento, se hace lenguas de ella, y sobre todo, me ha informado de que jamás observó en esta criatura la mas remota inclinacion á ninguno de los pocos hombres que ha podido ver en aquel encierro. Bordar, coser, leer libros devotos, oir misa y correr por la huerta detrás de las mariposas, y hechar agua en los agujeros de las hormigas, estas han sido su ocupacion y sus diversiones... ¿Qué dices?"}, {"type": "p", "text": "S . Yo nada, señor."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Y no pienses tú que, á pesar de tantas seguridades, no aprovecho"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "las ocasiones que se presentan para ir ganando su amistad y su confianza, y lograr que se esplique conmigo en absoluta libertad... Bien que aun hay tiempo... Solo que aquella Doña Irene siempre la interrumpe: todo se lo habla... Y es muy buena muger, buena... S . En fin, señor, yo desearé que salga como usted apetece."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí, yo espero en Dios que no ha de salir mal. Aunque el novio no"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "es muy de tu gusto... ¡Y qué fuera de tiempo me recomendabas al tal sobrinito! ¿Sabes tú lo enfadado que estoy con él?"}, {"type": "p", "text": "S . Pues ¿qué ha hecho?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Una de las suyas... Y hasta pocos dias há no lo he sabido. El año"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "pasado, ya lo viste, estuvo dos meses en Madrid... Y me costó buen dinero la tal visita... En fin, es mi sobrino, bien dado está; pero voy al asunto. Llegó el caso de irse á Zaragoza á su regimiento... Ya te acuerdas de que á muy pocos dias de haber salido de Madrid, recibí la noticia de su llegada."}, {"type": "p", "text": "S . Sí, señor."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Y que siguió escribiéndome, aunque algo perezoso, siempre con la"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "data de Zaragoza."}, {"type": "p", "text": "S . Así es la verdad."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Pues el picaron no estaba allí cuando me escribia las tales cartas."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Qué dice usted?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí, señor. El dia tres de julio salió de mi casa, y á fines de"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "setiembre aun no habia llegado á sus pabellones... ¿No te parece que para ir por la posta hizo muy buena diligencia?"}, {"type": "p", "text": "S . Tal vez se pondria malo en el camino, y por no darle á usted"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "pesadumbre..."}, {"type": "p", "text": "D. D . Nada de eso. Amores del señor oficial y devaneos que le traen"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "loco... Por ahí en esas ciudades puede que... ¿quien sabe?... Si encuentra un par de ojos negros, ya es hombre perdido... ¡No permita Dios que me le engañe alguna bribona de estas que truecan el honor por el matrimonio!"}, {"type": "p", "text": "S . ¡Oh! No hay que temer... Y si tropieza con alguna fullera de amor,"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "buenas cartas ha de tener para que le engañe."}, {"type": "p", "text": "D. D . Me parece que están ahí... Sí. Gracias á Dios. Busca al mayoral y"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "dile que venga, para quedar de acuerdo en la hora á que"}, {"type": "p", "text": "deberemos salir mañana."}, {"type": "p", "text": "S . Bien está."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Ya te he dicho que no quiero que esto se trasluzca, ni... ¿Estamos?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . No haya miedo que á nadie lo cuente."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "(Simon se va por la puerta del foro. Salen por la misma las tres mugeres con mantillas y basquiñas. Rita deja un pañuelo atado sobre la mesa y recoge las mantillas y las dobla.)"}]$lira$::jsonb, 1065);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 1, 'Escena II.', $lira$[{"type": "h", "text": "Doña Irene, Doña Francisca, Rita, D. Diego."}, {"type": "p", "text": "D.ª F . Ya estamos acá."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . ¡Ay! ¡qué escalera!"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Muy bien venidas, señoras."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¿Con que usted, á lo que parece, no ha salido?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "(Se sientan Doña Irene y D. Diego.)"}, {"type": "p", "text": "D. D . No, señora. Luego, mas tarde, daré una vueltecilla por ahí... He"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "leido un rato. Traté de dormir; pero en esta posada no se duerme. D.ª F . Es verdad que no... ¡Y que mosquitos! mala peste en ellos."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "Anoche no me dejaron parar... Pero, mire usted. Mire usted (Desata el pañuelo y manifiesta algunas cosas de las que indica el diálogo.) cuántas cosillas traigo. Rosarios de nacar, cruces de ciprés, la regla de S. Benito, una pililla de cristal.... Mire usted que bonita. Y dos corazones de talco... ¡Qué sé yo cuanto viene aquí!... ¡Ay! y una campanilla de barro bendito para los truenos... ¡Tantas cosas!"}, {"type": "p", "text": "D.ª I . Chucherías que la han dado las madres. Locas estaban con ella."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . ¡Cómo me quieren todas! Y mi tia, mi pobre tia, ¡lloraba tanto!..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "Es ya muy viejecita."}, {"type": "p", "text": "D.ª I . Ha sentido mucho no conocer á usted."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Sí, es verdad, Decia: ¿por qué no ha venido aquel señor?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . El pobre capellan y el rector de los Verdes nos han venido"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "acompañando hasta la puerta."}, {"type": "p", "text": "D.ª F . Toma, (Vuelve á atar el pañuelo y se le dá á Rita, la cual se va"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "con él y con las mantillas al cuarto de Doña Irene.) guárdamelo todo allí, en la escusabaraja. Mira, llévalo así de las puntas... ¡Válgate Dios, eh, ya se ha roto la Santa Gertrudis de alcorza! R . No importa, yo me la comeré."}, {"type": "h", "text": "Ita"}]$lira$::jsonb, 306);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 2, 'Escena III.', $lira$[{"type": "h", "text": "Doña Irene, Doña Francisca, D. Diego."}, {"type": "p", "text": "D.ª F . ¿Nos vamos adentro, mamá, ó nos quedamos aquí?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Ahora, niña, que quiero descansar un rato."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Hoy se ha dejado sentir el calor en forma."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Y ¡qué fresco tienen aquel locutorio! Vaya, está hecho un cielo."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Pues con todo, (Sentándose junto á Doña Irene.) aquella monja"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "tan gorda, que se llama la Madre Angustias, bien sudaba... ¡Ay, como sudaba la pobre mujer!"}, {"type": "p", "text": "D.ª I . Mi hermana es la que está bastante delicadita... Ha padecido"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "mucho este invierno... Pero, vaya, no sabia que hacerse con su sobrina la buena señora.... Está muy contenta de nuestra eleccion. D. D . Yo celebro que sea tan á gusto de aquellas personas, á quienes"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "debe usted particulares obligaciones."}, {"type": "p", "text": "D.ª I . Sí, Trinidad está muy contenta, y en cuanto á Circuncision, ya lo"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "ha visto usted. La ha costado mucho despegarse de ella; pero ha conocido que siendo para su bien estar, es necesario pasar por todo... Ya se acuerda usted de lo espresiva que estuvo y... D. D . Es verdad. Solo falta que la parte interesada tenga la misma"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "satisfaccion que manifiestan cuantos la quieren bien."}, {"type": "p", "text": "D.ª I . Es hija obediente, y no se apartará jamás de lo que determine su"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "madre."}, {"type": "p", "text": "D. D . Todo eso es cierto; pero..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Es de buena sangre, y ha de pensar bien, y ha de proceder con el"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "honor que la corresponde."}, {"type": "p", "text": "D. D . Sí, ya estoy; pero ¿no pudiera, sin faltar á su honor ni á su"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "sangre?..."}, {"type": "p", "text": "D.ª F . ¿Me voy, mamá?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "(Se levanta y vuelve á sentarse.)"}, {"type": "p", "text": "D.ª I . No pudiera, no, señor. Una niña bien educada, hija de buenos"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "padres, no puede menos de conducirse en todas ocasiones como es conveniente y debido. Un vivo retrato es la chica, ahí donde usted la ve, de su abuela, que Dios perdone, Doña Gerónima de"}, {"type": "p", "text": "Peralta... En casa tengo el cuadro, ya le habrá usted visto. Y le hicieron, segun me contaba su merced, para enviársele á su tio carnal el padre fray Serapion de S. Juan Crisóstomo, electo obispo de Mechoacan."}, {"type": "p", "text": "D. D . Ya."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Y murió en el mar, el buen religioso: que fué un quebranto para"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "toda la familia... Hoy es, y todavía estamos sintiendo su muerte: particularmente mi primo D. Cucufate, regidor perpétuo de Zamora, no puede oir hablar de su Ilustrísima sin deshacerse en lágrimas."}, {"type": "p", "text": "D.ª F . ¡Válgate Dios! que moscas tan..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Pues murió en olor de santidad."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Eso bueno es."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Sí, señor; pero como la familia ha venido tan á menos.... ¿Qué"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "quiere usted? Donde no hay facultades... Bien que, por lo que puede tronar, ya se le está escribiendo la vida; y quien sabe que el dia de mañana no se imprima, con el favor de Dios."}, {"type": "p", "text": "D. D . Sí, pues ya se ve. Todo se imprime."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Lo cierto es que el autor, que es sobrino de mi hermano político,"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "el canónigo de Castrojeriz, no la deja de la mano, y á la hora de esta lleva ya escritos nueve tomos en fólio, que comprenden los nueve años primeros de la vida del santo obispo."}, {"type": "p", "text": "D. D . ¿Con que para cada año un tomo?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Sí, señor, ese plan se ha propuesto."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Y ¿de qué edad murió el venerable?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . De ochenta y dos años, tres meses y catorce dias."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . ¿Me voy mamá?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Anda vete. ¡Válgate Dios, que prisa tienes!"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . ¿Quiere usted (Se levanta, y despues de hacer una graciosa"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "cortesía á D. Diego, da un beso á Doña Irene y se va al cuarto de esta.) que le haga una cortesía á la francesa, señor Don Diego? D. D . Sí, hija mia. A ver."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Mire usted, así."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¡Graciosa niña! Viva la Paquita, viva."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Para usted una cortesía, y para mi mamá, un beso."}, {"type": "h", "text": "Ca"}]$lira$::jsonb, 724);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 3, 'Escena IV.', $lira$[{"type": "h", "text": "Doña Irene, Don Diego."}, {"type": "p", "text": "Es muy gitana y muy mona, mucho."}, {"type": "p", "text": "D.ª I ."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "Tiene un donaire natural que arrebata."}, {"type": "h", "text": "D. D . Ie"}, {"type": "p", "text": "¿Qué quiere usted? Criada sin artificio ni embelecos de mundo, D.ª I RE . contenta de verse otra vez al lado de su madre, y mucho mas de considerar tan inmediata su colocacion; no es maravilla que cuanto hace y dice sea una gracia, y máxime á los ojos de usted, que tanto se ha empeñado en favorecerla."}, {"type": "p", "text": "D. D . Quisiera solo que se esplicase libremente acerca de nuestra"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "proyectada union, y..."}, {"type": "p", "text": "D.ª I . Oiria usted lo mismo que le he dicho ya."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Sí, no lo dudo; pero el saber que la merezco alguna inclinacion,"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "oyéndoselo decir con aquella boquilla tan graciosa que tiene, seria para mí una satisfaccion imponderable."}, {"type": "p", "text": "D.ª I . No tenga usted sobre ese particular la mas leve desconfianza; pero"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "hágase usted cargo de que á una niña no la es lícito decir con ingenuidad lo que siente. Mal pareceria, señor D. Diego, que una doncella de vergüenza y criada como Dios manda, se atreviese á decirle á un hombre: yo le quiero á usted."}, {"type": "p", "text": "D. D . Bien: si fuese un hombre á quien hallara por casualidad en la calle"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "y le espetara ese favor de buenas á primeras, cierto que la doncella haria muy mal; pero á un hombre con quien ha de casarse dentro de pocos dias, ya pudiera decirle alguna cosa que... Además, que hay ciertos modos de esplicarse..."}, {"type": "p", "text": "D.ª I . Conmigo usa de mas franqueza. A cada instante hablamos de"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "usted, y en todo manifiesta el particular cariño que á usted le tiene... ¡Con que juicio hablaba ayer noche, despues que usted se fué á recoger! No sé lo que hubiera dado porque hubiese podido oirla."}, {"type": "p", "text": "D. D . ¿Y qué? ¿Hablaba de mí?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Y que bien piensa, acerca de lo preferible que es para una criatura"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "de sus años un marido de cierta edad, esperimentado, maduro y de conducta..."}, {"type": "p", "text": "D. D . ¡Calle! ¿Eso decia?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . No, esto se lo decia yo, y me escuchaba con una atencion como si"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "fuera una muger de cuarenta años, lo mismo... ¡Buenas cosas la dije! Y ella que tiene mucha penetracion, aunque me esté mal el decirlo... ¿Pues no da lástima, señor, el ver como se hacen los matrimonios hoy en el dia? Casan á una muchacha de quince años con un arrapiezo de diez y ocho, á una de diez y siete con otro de veinte y dos: ella niña, sin juicio ni esperiencia, y él niño tambien, sin asomo de cordura ni conocimiento de lo que es mundo. Pues señor, (que es lo que yo digo), ¿quién ha de gobernar la casa? ¿Quién ha de mandar á los criados? ¿Quién ha de enseñar y corregir á los hijos? Porque sucede tambien, que estos"}, {"type": "p", "text": "atolondrados de chicos, suelen plagarse de criaturas en un instante, que da compasion."}, {"type": "p", "text": "D. D . Cierto que es un dolor el ver rodeados de hijos á muchos que"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "carecen del talento, de la esperiencia y de la virtud que son necesarias para dirigir su educacion."}, {"type": "p", "text": "D.ª I . Lo que sé decirle á usted es, que aun no habia cumplido los diez y"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "nueve, cuando me casé de primeras nupcias con mi difunto D. Epifanio, que esté en el cielo. Y era un hombre que, mejorando lo presente, no es posible hallarle de mas respeto, mas caballeroso... Y al mismo tiempo, mas divertido y decidor. Pues, para servir á usted, ya tenia los cincuenta y seis, muy largos detalle cuando se casó conmigo."}, {"type": "p", "text": "D. D . Buena edad... No era un niño, pero..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Pues á eso voy... Ni á mí podia convenirme en aquel entónces un"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "boquirrubio, con los cascos á la gineta... No señor... Y no es decir tampoco que estuviese achacoso ni quebrantado de salud; nada de eso. Sanito estaba, gracias á Dios, como una manzana; ni en su vida conoció otro mal, sino una especie de alferecía que le amagaba de cuando en cuando. Pero luego que nos casamos dió en darle tan á menudo y tan de recio, que á los siete meses me hallé viuda, y en cinta de una criatura que nació despues; y al cabo y al fin se me murió de alfombrilla."}, {"type": "p", "text": "D. D . ¡Oiga!... Mire usted si dejó sucesion el bueno de D. Epifanio."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Sí, señor, ¿pues por qué no?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Lo digo porque luego saltan con... Bien que si uno hubiera de"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "hacer caso... Y ¿fué niño ó niña?"}, {"type": "p", "text": "D.ª I . Un niño muy hermoso. Como una plata era el angelito."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Cierto que es consuelo tener, así, una criatura y..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¡Ay, señor! Dan malos ratos; pero ¿qué importa? Es mucho gusto,"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "mucho."}, {"type": "p", "text": "D. D . Yo lo creo."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Sí, señor."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Ya se ve que será una delicia y...."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Pues ¿no ha de ser?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Un embeleso el verlos juguetear y reir, y acariciarlos, y merecer"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "sus fiestecillas inocentes."}, {"type": "p", "text": "D.ª I . ¡Hijos de mi vida! Veinte y dos he tenido en los tres matrimonios"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "que llevo hasta ahora, de los cuales solo esta niña me ha venido á quedar; pero le aseguro á usted que..."}]$lira$::jsonb, 927);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 4, 'Escena V.', $lira$[{"type": "p", "text": "SIMON, (Sale por la puerta del foro.) DOÑA IRENE, D. DIEGO. S . Señor, el mayoral está esperando."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Dile que voy allá... ¡Ah! Tráeme primero el sombrero y el baston,"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que quisiera dar una vuelta por el campo. (Entra Simon al cuarto de D. Diego, saca un sombrero y un baston, se los da á su amo, y al fin de la escena se va con él por la puerta del foro.) ¿Con que, supongo que mañana tempranito saldremos?"}, {"type": "p", "text": "D.ª I . No hay dificultad. A la hora que á usted le parezca."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . A eso de las seis. ¿Eh?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Muy bien."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . El sol nos da de espaldas... Le diré que venga una media hora"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "antes."}, {"type": "p", "text": "D.ª I . Sí, que hay mil chismes que acomodar."}, {"type": "h", "text": "Re"}]$lira$::jsonb, 144);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 5, 'Escena VI.', $lira$[{"type": "h", "text": "Doña Irene, Rita."}, {"type": "p", "text": "D.ª I . Válgame Dios, ahora que me acuerdo... Rita... Me le habrán"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "dejado morir. Rita."}, {"type": "p", "text": "R . Señora."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "(Sacará Rita unas sábanas y almohadas debajo del brazo.) D.ª I . ¿Qué has hecho del tordo? ¿Le diste de comer?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . Sí, señora. Más ha comido que un avestruz. Ahí le puse en la"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "ventana del pasillo."}, {"type": "p", "text": "D.ª I . ¿Hiciste las camas?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . La de usted ya está. Voy á hacer esotras antes que anochezca,"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "porque si no, como no hay mas alumbrado que el del candil, y no tiene garabato, me veo perdida."}, {"type": "p", "text": "D.ª I . Y aquella chica ¿qué hace?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . Está desmenuzando un bizcocho para dar de cenar á Don"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Periquito."}, {"type": "p", "text": "D.ª I . ¡Qué pereza tengo de escribir! (Se levanta y se entra en su"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "cuarto.) Pero es preciso, que estará con mucho cuidado la pobre Circuncision."}, {"type": "p", "text": "R . ¡Qué chapucerías! No ha dos horas, como quien dice, que salimos"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "de allá, y ya empiezan á ir y venir correos. ¡Qué poco me gustan á mí las mugeres gazmoñas y zalameras!"}, {"type": "p", "text": "(Éntrase en el cuarto de Doña Francisca.)"}]$lira$::jsonb, 199);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 6, 'Escena VII.', $lira$[{"type": "p", "text": "CALAMOCHA (Sale por la puerta del foro con unas maletas, látigo y botas; lo deja todo sobre la mesa y se sienta.)"}, {"type": "p", "text": "C . ¿Con que ha de ser el número tres? Vaya en gracia... Ya, ya"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "conozco el tal número tres. Coleccion de bichos mas abundante no la tiene el Gabinete de Historia natural.... Miedo me da de entrar... ¡Ay! ¡ay!... Y ¡qué agujetas! Estas sí que son agujetas... Paciencia, pobre Calamocha, paciencia... Y gracias á que los caballitos dijeron no podemos mas, que si no, por esta vez no veia yo el número tres, ni las plagas de Faraon que tiene dentro... En fin, como los animales amanezcan vivos, no será poco.... Rebentados están.... (Canta Rita desde adentro, Calamocha se levanta desperezándose.) ¡Oiga!... ¿Seguidillitas?... Y no canta mal... Vaya, aventura tenemos... ¡Ay! que desvencijado estoy."}]$lira$::jsonb, 138);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 7, 'Escena VIII.', $lira$[{"type": "h", "text": "Rita, Calamocha."}, {"type": "p", "text": "Mejor es cerrar, no sea que nos alivien de ropa y... (Forcejeando"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "para echar la llave.) Pues cierto que está bien acondicionada la llave."}, {"type": "p", "text": "C . ¿Gusta usted de que eche una mano, mi vida?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . Gracias, mi alma."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . ¡Calle!... Rita."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . Calamocha."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . ¿Qué hallazgo es este?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . ¿Y tu amo?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . Los dos acabamos de llegar."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . ¿De veras?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . No que es chanza. Apenas recibió la carta de Doña Paquita, yo no"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "se adónde fué, ni con quien habló, ni como lo dispuso; solo sé decirte que aquella tarde salimos de Zaragoza. Hemos venido como dos centellas, por ese camino. Llegamos esta mañana á Guadalajara, y á las primeras diligencias nos hallamos con que los pájaros volaron ya. A caballo otra vez y vuelta á correr y á sudar y á dar chasquidos... En suma, molidos los rocines y nosotros á medio moler, hemos parado aquí con ánimo de salir mañana... Mi teniente se ha ido al colegio mayor á ver á un amigo, mientras se dispone algo que cenar.... Esta es la historia."}, {"type": "p", "text": "R . ¿Con que le tenemos aquí?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . Y enamorado mas que nunca, zeloso, amenazando vidas..."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "Aventurado á quitar el hipo á cuantos le disputen la posesion de su Currita idolatrada."}, {"type": "p", "text": "R . ¿Qué dices?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . Ni mas ni menos."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . ¡Qué gusto me das!... Ahora sí se conoce que la tiene amor."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . ¿Amor?... ¡Friolera!.... El moro Gazul fué para él un pelele,"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "Medoro un zascandil, y Gaiferos un chiquillo de la doctrina. R . ¡Ay cuando la señorita lo sepa!"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . Pero acabemos. ¿Cómo te hallo aquí? ¿Con quién estás? ¿Cuando"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "llegaste? Que..."}, {"type": "p", "text": "R . Yo te lo diré. La madre de Doña Paquita dió en escribir cartas y"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "mas cartas, diciendo que tenia concertado su casamiento en Madrid con un caballero rico, honrado, bien quisto, en suma cabal y perfecto, que no habia mas que apetecer. Acosada la señorita con tales propuestas, y angustiada incesantemente con los sermones de aquella bendita monja, se vió en la necesidad de responder que estaba pronta á todo lo que la mandasen... Pero no te puedo ponderar cuánto lloró la pobrecita, que afligida estuvo. Ni queria comer, ni podia dormir... Y al mismo tiempo era preciso disimular para que su tia no sospechára la verdad del caso. Ello es que cuando, pasado el primer susto, hubo lugar de discurrir escapatorias y arbitrios, no hallamos otro que el de avisar á tu amo; esperando que si era su cariño tan verdadero y de buena ley como nos habia ponderado, no consentiria que su pobre Paquita pasára á manos de un desconocido, y se perdiesen para siempre tantas caricias, tantas lágrimas y tantos suspiros, estrellados en las tapias del corral. A pocos dias de haberle escrito, cata el coche de colleras y el mayoral Gasparet con sus medias azules, y la madre y el novio que vienen por ella: recogimos á toda prisa nuestros meriñaques, se atan los cofres, nos despedimos de aquellas buenas mugeres, y en dos latigazos llegamos antes de ayer á Alcalá. La detencion ha sido para que la señorita visite á otra tia monja que tiene aquí, tan arrugada y tan sorda como la que dejamos allá. Ya la ha visto, ya la han besado bastante una por una todas las religiosas, y creo que mañana temprano saldremos. Pero esta casualidad nos..."}, {"type": "p", "text": "C . Sí. No digas mas... Pero... ¿Con que el novio está en la posada?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . Ese es su cuarto, (Señalando el cuarto de D. Diego, el de Doña"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Irene y el de Doña Francisca.) este el de la madre, y aquel el nuestro."}, {"type": "p", "text": "C . ¿Cómo nuestro? ¿Tuyo y mio?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . No por cierto. Aquí dormiremos esta noche la señorita y yo;"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "porque ayer, metidas las tres en ese de enfrente, ni cabíamos de pié, ni pudimos dormir un instante, ni respirar siquiera. C . Bien... A Dios. (Recoge los trastos que puso sobre la mesa, en"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "ademan de irse.)"}, {"type": "p", "text": "R . ¿Y adónde?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . Yo me entiendo... Pero el novio ¿trae consigo criados, amigos ó"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "deudos que le quiten la primera zambullida que le amenaza? R . Un criado viene con él."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . ¡Poca cosa!... Mira, dile en caridad que se disponga, porque está"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "de peligro. A Dios."}, {"type": "p", "text": "R . ¿Y volverás presto?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . Se supone. Estas cosas piden diligencia; y aunque apenas puedo"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "moverme, es necesario que mi teniente deje la visita y venga á cuidar de su hacienda, disponer el entierro de ese hombre, y... ¿Con que ese es nuestro cuarto, eh?"}, {"type": "p", "text": "R . Sí. De la señorita y mio."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . ¡Bribona!"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "R . ¡Botarate! A Dios."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "C . A Dios, aborrecida. (Éntrase con los trastos al cuarto de D."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "Cárlos.)"}]$lira$::jsonb, 841);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 8, 'Escena IX. (1/2)', $lira$[{"type": "h", "text": "Doña Francisca, Rita."}, {"type": "p", "text": "R . Qué malo es... Pero... ¡Válgame Dios! ¡D. Felix aquí! Sí, la"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "quiere, bien se conoce... (Sale Calamocha del cuarto de D. Cárlos, y se va por la puerta del foro.) ¡Oh! por mas que digan, los hay muy finos, y entonces, ¿qué ha de hacer una?... Quererlos: no tiene remedio, quererlos... Pero ¿qué dirá la señorita cuando le vea, que está ciega por él? ¡Pobrecita! Pues no seria una lástima que... Ella es. (Sale Doña Francisca.)"}, {"type": "p", "text": "D.ª F . ¡Ay, Rita!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . ¿Qué es eso? ¿Ha llorado usted?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Pues no he de llorar! Si vieras mi madre... Empeñada está en que"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "he de querer mucho á ese hombre... Si ella supiera lo que sabes tú, no me mandaria cosas imposibles... Y que es tan bueno, y que es rico y que me irá tan bien con él... Se ha enfadado tanto, y me ha llamado picarona, inobediente... ¡Pobre de mí! Porque no miento, ni sé fingir, por eso me llaman picarona."}, {"type": "p", "text": "R . Señorita, por Dios, no se aflija usted."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Ya, como tú no lo has oido... Y dice que D. Diego se queja de que"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "yo no le digo nada... Harto le digo, y bien he procurado hasta ahora mostrarme contenta delante de él, que no lo estoy por cierto, y reirme y hablar de niñerías... Y todo, por dar gusto á mi madre, que si no... Pero bien sabe la Vírgen que no me sale del corazon. (Se va obscureciendo lentamente el teatro.)"}, {"type": "p", "text": "R . Vaya, vamos, que no hay motivos todavía para tanta angustia..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "¿Quién sabe?... ¿No se acuerda usted ya de aquel dia de asueto que tuvimos el año pasado en la casa de campo del intendente? D.ª F . ¡Ay! ¿cómo puedo olvidarlo?... ¿Pero qué me vas á contar?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Quiero decir que aquel caballero que vimos allí con aquella cruz"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "verde, tan galan, tan fino..."}, {"type": "p", "text": "D.ª F . ¡Qué rodeos!... D. Felix. ¿Y qué?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Que nos fué acompañando hasta la ciudad..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Y bien... Y luego volvió, y le ví, por mi desgracia, muchas veces..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "mal aconsejada de tí."}, {"type": "p", "text": "R . ¿Por qué, señora?... ¿A quién dimos escándalo? Hasta ahora nadie"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "lo ha sospechado en el convento. Él no entró jamás por las puertas, y cuando de noche hablaba con usted, mediaba entre los dos una distancia tan grande, que usted la maldijo, no pocas veces... Pero esto no es del caso. Lo que voy á decir es, que un amante como aquel no es posible que se olvide tan presto de su querida Paquita... Mire usted que todo cuanto hemos leido á hurtadillas en las novelas, no equivale á lo que hemos visto en él... ¿Se acuerda usted de aquellas tres palmadas que se oian entre once y doce de la noche, de aquella sonora punteada con tanta delicadeza y espresion?"}, {"type": "p", "text": "D.ª F . ¡Ay, Rita! Sí, de todo me acuerdo, y mientras viva conservaré la"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "memoria... Pero está ausente... Y entretenido acaso con nuevos amores."}, {"type": "p", "text": "R . Eso no lo puedo yo creer."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Es hombre al fin, y todos ellos..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . ¡Qué bobería! Desengáñese usted, señorita. Con los hombres y las"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "mujeres sucede lo mismo que con los melones de Añover. Hay de todo; la dificultad está en saber escogerlos. El que se lleva chasco en la eleccion, quéjese de su mala suerte, pero no desacredite la mercancía... Hay hombres muy embusteros, muy picarones; pero no es creible que lo sea el que ha dado pruebas tan repetidas de perseverancia y amor. Tres meses duró el terrero y la"}]$lira$::jsonb, 625);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 9, 'Escena IX. (2/2)', $lira$[{"type": "p", "text": "conversacion á obscuras, y en todo aquel tiempo, bien sabe usted que no vimos en él una accion descompuesta, ni oimos de su boca una palabra indecente ni atrevida."}, {"type": "p", "text": "D.ª F . Es verdad. Por eso le quise tanto, por eso le tengo tan fijo aquí..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "aquí... (Señalando el pecho.) ¿Qué habrá dicho al ver la carta?... ¡Oh! Yo bien sé lo que habrá dicho... ¡Válgate Dios! ¡Es lástima!... Cierto. ¡Pobre Paquita!... Y se acabó... No habrá dicho mas... nada mas."}, {"type": "p", "text": "R . No señora, no ha dicho eso."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Qué sabes tú?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Bien lo sé. Apenas haya leido la carta se habrá puesto en camino,"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "y vendrá volando á consolar á su amiga... Pero..."}, {"type": "p", "text": "(Acercándose á la puerta del cuarto de D.ª Irene.)"}, {"type": "p", "text": "D.ª F . ¿Adónde vas?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Quiero ver si..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Está escribiendo."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Pues ya presto habrá de dejarlo, que empieza á anochecer..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Señorita, lo que la he dicho á usted es la verdad pura. D. Felix está ya en Alcalá."}, {"type": "p", "text": "D.ª F . ¿Qué dices? no me engañes."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Aquel es su cuarto... Calamocha acaba de hablar conmigo."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿De veras?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Sí, señora... Y le ha ido á buscar para..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Con que me quiere?... ¡Ay Rita! Mira tú si hicimos bien de"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "avisarle... ¿Pero ves qué fineza?... ¿Si vendrá bueno?... ¡Correr tantas leguas solo por verme... porque yo se lo mando!... ¡Qué agradecida le debo estar!... ¡Oh! yo le prometo que no se quejará de mí. Para siempre agradecimiento y amor."}, {"type": "p", "text": "R . Voy á traer luces. Procuraré detenerme por allá abajo hasta que"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "vuelvan... Veré lo que dice y qué piensa hacer, porque"}, {"type": "p", "text": "hallándonos todos aquí, pudiera haber una de Satanás entre la madre, la hija, el novio y el amante; y si no ensayamos bien esta contradanza, nos hemos de perder en ella."}, {"type": "p", "text": "D.ª F . Dices bien... Pero no, él tiene resolucion y talento, y sabrá"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "determinar lo mas conveniente... ¿Y como has de avisarme?... Mira que así que llegue le quiero ver."}, {"type": "p", "text": "R . No hay que dar cuidado. Yo le traeré por acá, y en dándome"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "aquella tosecilla seca... ¿Me entiende usted?"}, {"type": "p", "text": "D.ª F . Sí, bien."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Pues entonces no hay mas que salir con cualquiera excusa. Yo me"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "quedaré con la señora mayor, la hablaré de todos sus maridos y de sus concuñados, y del obispo que murió en el mar... Además, que si está allí D. Diego..."}, {"type": "p", "text": "D.ª F . Bien, anda, y así que llegue..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Al instante."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Que no se te olvide toser."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . No haya miedo."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Si vieras que consolada estoy!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Sin que usted lo jure lo creo."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Te acuerdas cuando me decia que era imposible apartarme de su"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "memoria, que no habria peligros que le detuvieran, ni dificultades que no atropellara por mí?"}, {"type": "p", "text": "R . Sí, bien me acuerdo."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Ah!... Pues mira como me dijo la verdad. (Doña Francisca se va"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "al cuarto de Doña Irene. Rita por la puerta del foro.)"}]$lira$::jsonb, 549);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 10, 'Acto segundo. · Escena I.', $lira$[{"type": "h", "text": "Teatro Oscuro."}, {"type": "p", "text": "D.ª F . Nadie parece aun... (Acércase á la puerta del foro y vuelve.) ¡Qué"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "impaciencia tengo!... Y dice mi madre que soy una simple, que solo pienso en jugar y reir, y que no sé lo que es amor... Sí, diez y siete años y no cumplidos; pero ya sé lo que es querer bien, y la inquietud y las lágrimas que cuesta."}]$lira$::jsonb, 67);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 11, 'Acto segundo. · Escena II.', $lira$[{"type": "h", "text": "Doña Irene, Doña Francisca."}, {"type": "p", "text": "D.ª I . Sola y á obscuras me habeis dejado allí."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Como estaba usted acabando su carta, mamá, por no estorbarla me"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "he venido aquí, que está mucho mas fresco."}, {"type": "p", "text": "D.ª I . ¿Pero aquella muchacha qué hace, que no trae una luz? Para"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "cualquiera cosa se está un año... Y yo que tengo un genio como una pólvora... (Siéntase.) Sea todo por Dios... ¿Y D. Diego no ha venido?"}, {"type": "p", "text": "D.ª F . Me parece que no."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Pues cuenta, niña, con lo que te he dicho ya. Y mira que no gusto"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "de repetir una cosa dos veces. Este caballero está sentido, y con muchísima razon..."}, {"type": "p", "text": "D.ª F . Bien, sí señora, ya lo sé. No me riña usted mas."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . No es esto reñirte, hija mia, esto es aconsejarte. Porque como tú"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "no tienes conocimiento para considerar el bien que se nos ha entrado por las puertas... Y lo atrasada que me coge, que yo no sé lo que hubiera sido de tu pobre madre... Siempre cayendo y levantando... Médicos, botica... Que se dejaba pedir aquel caribe de D. Bruno (Dios le haya coronado de gloria) los veinte y los treinta reales por cada papelillo de píldoras de coloquíntida y asafétida... Mira que un casamiento como el que vas á hacer, muy pocas le consiguen. Bien que á las oraciones de tus tias, que son unas bienaventuradas, debemos agradecer esta fortuna, y no á tus méritos ni á mi diligencia... ¿Qué dices?"}, {"type": "p", "text": "D.ª F . Yo nada, mamá."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Pues nunca dices nada. ¡Válgame Dios, señor!... En hablándote de"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "esto, no te ocurre nada que decir."}]$lira$::jsonb, 290);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 12, 'Acto segundo. · Escena III.', $lira$[{"type": "p", "text": "RITA, (Sale de la puerta del foro con luces y las pone encima de la mesa.) DOÑA"}, {"type": "h", "text": "Irene, Doña Francisca."}, {"type": "p", "text": "D.ª I . Vaya, muger, yo pensé que en toda la noche no venias."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . Señora, he tardado porque han tenido que ir á comprar las velas."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Como el tufo del velon la hace á usted tanto daño."}, {"type": "p", "text": "D.ª I . Seguro que me hace muchísimo mal, con esta jaqueca que"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "padezco... Los parches de alcanfor al cabo tuve que quitármelos; si no me sirvieron de nada. Con las obleas me parece que me va mejor... Mira, deja una luz ahí y llévate la otra á mi cuarto, y corre la cortina, no se me llene todo de mosquitos."}, {"type": "p", "text": "R . Muy bien. (Toma una luz y hace que se va.)"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . (Aparte á Rita.) ¿No ha venido?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Vendrá."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª I . Oyes, aquella carta que está sobre la mesa, dásela al mozo de la"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "posada para que la lleve al instante al correo... (Vase Rita al cuarto de Doña Irene.) Y tú, niña, ¿qué has de cenar? Porque será menester recojernos presto para salir mañana de madrugada. D.ª F . Como las monjas me hicieron merendar..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Con todo eso... Siquiera unas sopas del puchero para el abrigo del"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "estómago... (Sale Rita con una carta en la mano, y hasta el fin de la escena hace que se va y vuelve segun lo indica el diálogo.) Mira, has de calentar el caldo que apartamos al mediodia, y haznos un par de tazas de sopas, y tráetelas luego que estén. R . ¿Y nada mas?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª I . No, nada mas... ¡Ah! y házmelas bien caldositas."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . Sí, ya lo sé."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª I . Rita."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . Otra. ¿Qué manda usted?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª I . Encarga mucho al mozo que lleve la carta al instante... Pero, no"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "señor, mejor es... No quiero que la lleve él, que son unos borrachones, que no se les puede... Has de decir á Simon, que digo yo, que me haga el gusto de echarla en el correo. ¿Lo entiendes? R . Sí, señora."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª I . ¡Ah! mira."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "R . Otra."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª I . Bien que ahora no corre prisa... Es menester que luego me saques"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "de ahí al tordo y colgarle por aquí, de modo que no se caiga y se me lastime... (Vase Rita por la puerta del foro.) ¡Qué noche tan mala me dió!... ¡Pues no se estuvo el animal toda la noche de Dios rezando el Gloria Patri y la oracion del Santo Sudario!... Ello por otra parte edificaba, cierto... Pero cuando se trata de dormir."}]$lira$::jsonb, 462);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 13, 'Acto segundo. · Escena IV.', $lira$[{"type": "h", "text": "Doña Irene, Doña Francisca."}, {"type": "p", "text": "D.ª I . Pues mucho será que D. Diego no haya tenido algun encuentro"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "por ahí y eso le detenga. Cierto que es un señor muy mirado, muy puntual... ¡Tan buen cristiano! ¡Tan atento! ¡Tan bien hablado! ¡Y con que garbo y generosidad se porta!... Ya se ve, un sugeto de bienes y de posibles... Y ¡qué casa tiene!... Como un ascua de oro la tiene... Es mucho aquello. ¡Qué ropa blanca! ¡Qué batería de cocina! ¡Y qué despensa, llena de cuanto Dios crió!... Pero tú no parece que atiendes á lo que estoy diciendo."}, {"type": "p", "text": "D.ª F . Sí, señora, bien lo oigo; pero no la queria interrumpir á usted."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Allí estarás, hija mia, como el pez en el agua: pajaritas del aire"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "que apetecieras, las tendrias, porque como él te quiere tanto, y es un caballero tan de bien y tan temeroso de Dios... Pero mira, Francisquita, que me cansa de veras el que siempre que te hablo de esto, hayas dado en la flor de no responderme palabra... Pues no es cosa particular, señor."}, {"type": "p", "text": "D.ª F . Mamá, no se enfade usted."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . No es buen empeño de... ¿Y te parece á tí que no sé yo muy bien"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "de dónde viene todo eso?... ¿No ves que conozco las locuras que se te han metido en esa cabeza de chorlito?... Perdóneme Dios. D.ª F . Pero... Pues ¿qué sabe usted?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . ¿Me quieres engañar á mí, eh? ¡Ay hija! He vivido mucho, y"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "tengo yo mucha trastienda y mucha penetracion para que tú me engañes."}, {"type": "p", "text": "D.ª F . (Aparte.) ¡Perdida soy!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Sin contar con su madre... Como si tal madre no tuviera... Yo te"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "aseguro, que aunque no hubiera sido con esta ocasion, de todos modos era ya necesario sacarte del convento. Aunque hubiera tenido que ir á pié y sola por ese camino, te hubiera sacado de allí... ¡Mire usted qué juicio de niña este! Que, porque ha vivido un poco de tiempo entre monjas, ya se la puso en la cabeza el ser ella monja tambien... Ni qué entiende ella de eso, ni que... En todos los estados se sirve á Dios, Frasquita; pero el complacer á su madre, asistirla, acompañarla y ser el consuelo de sus trabajos, esa es la primera obligacion de una hija obediente. Y sépalo usted, si no lo sabe."}, {"type": "p", "text": "D.ª F . Es verdad, mamá... Pero yo nunca he pensado abandonarla á"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "usted."}, {"type": "p", "text": "D.ª I . Sí, que no sé yo..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . No señora. Créame usted. La Paquita nunca se apartará de su"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "madre, ni la dará disgustos."}, {"type": "p", "text": "D.ª I . Mira si es cierto lo que dices."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Sí, señora, que yo no sé mentir."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . Pues hija, ya sabes lo que te he dicho. Ya ves lo que pierdes, y la"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "pesadumbre que me darás si no te portas en un todo como"}, {"type": "p", "text": "corresponde. Cuidado con ello."}, {"type": "p", "text": "D.ª F . ¡Pobre de mí! (Aparte.)"}, {"type": "h", "text": "Ca"}]$lira$::jsonb, 521);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 14, 'Acto segundo. · Escena V. (1/2)', $lira$[{"type": "p", "text": "D. DIEGO, (Sale por la puerta del foro, y deja sobre la mesa sombrero y baston.)"}, {"type": "h", "text": "Doña Irene, Doña Francisca."}, {"type": "p", "text": "¿Pues cómo tan tarde?"}, {"type": "p", "text": "D.ª I ."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "Apenas salí, tropecé con el padre guardian de San Diego y el"}, {"type": "h", "text": "D. D . Ie"}, {"type": "p", "text": "doctor Padilla, y hasta que me han hartado bien de chocolate y bollos no me han querido soltar... (Siéntase junto á Doña Irene.) Y á todo esto, ¿cómo va?"}, {"type": "p", "text": "D.ª I . Muy bien."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . ¿Y Doña Paquita?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Doña Paquita siempre acordándose de sus monjas. Ya la digo que"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "es tiempo de mudar de bisiesto, y pensar solo en dar gusto á su madre y obedecerla."}, {"type": "p", "text": "D. D . ¡Qué diantre! Con que tanto se acuerda de..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¿Qué se admira usted? Son niñas... No saben lo que quieren, ni lo"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "que aborrecen... En una edad, así tan..."}, {"type": "p", "text": "D. D . No, poco á poco, eso no. Precisamente en esa edad son las"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "pasiones algo mas enérgicas y decisivas que en la nuestra; y por cuanto la razon se halla todavía imperfecta y débil, los ímpetus del corazon son mucho mas violentos... (Asiendo de una mano á Doña Francisca la hace sentar inmediata á él.) Pero de veras, Doña Paquita, ¿se volveria usted al convento de buena gana?... La verdad."}, {"type": "p", "text": "D.ª I . Pero si ella no..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Déjela usted, señora, que ella responderá."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Bien sabe usted lo que acabo de decirla... No permita Dios que yo"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "la dé que sentir."}, {"type": "p", "text": "D. D . Pero eso lo dice usted tan afligida y..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Si es natural, señor. No ve usted que..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Calle usted por Dios, Doña Irene, y no me diga usted á mí lo que"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "es natural... Lo que es natural es que la chica esté llena de miedo y no se atreve á decir una palabra, que se oponga á lo que su madre quiere que diga... Pero si esto hubiese, por vida mia, que estábamos lucidos."}, {"type": "p", "text": "D.ª F . No señor, lo que dice su merced, eso digo yo, lo mismo. Porque"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "en todo lo que me mande la obedeceré."}, {"type": "p", "text": "D. D . ¡Mandar, hija mia!... En estas materias tan delicadas, los padres"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que tienen juicio no mandan. Insinúan, proponen, aconsejan; eso sí, todo eso sí; ¡pero mandar!... Y ¿quién ha de evitar despues las resultas funestas de lo que mandaron?... Pues ¿cuántas veces vemos matrimonios infelices, uniones monstruosas, verificadas solamente porque un padre tonto se metió á mandar lo que no debiera?... ¿Cuántas veces una desdichada muger halla anticipada la muerte en el encierro de un claustro porque su madre ó su tio se empeñaron en regalar á Dios lo que Dios no queria?... ¡Eh! No señor, eso no va bien... Mire usted, Doña Paquita, yo no soy de aquellos hombres que se disimulan los defectos. Yo sé que ni mi figura, ni mi edad son para enamorar perdidamente á nadie; pero tampoco he creido imposible que una muchacha de juicio y bien criada, llegase á quererme con aquel amor tranquilo y constante que tanto se parece á la amistad, y es el único que puede hacer los matrimonios felices. Para conseguirlo, no he ido á buscar ninguna hija de familia de estas que viven en una decente libertad... Decente: que yo no culpo lo que no se opone al ejercicio de la virtud. ¿Pero cuál seria entre todas ellas la que no estuviese ya prevenida en favor de otro amante mas apetecible que yo? Y en Madrid, figúrese usted en un Madrid... Lleno de estas ideas, me pareció que tal vez hallaria en usted todo cuanto yo deseaba. D.ª I . Y puede usted creer, señor D. Diego, que..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Voy á acabar, señora, déjeme usted acabar. Yo me hago cargo,"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "querida Paquita, de lo que habrán influido en una niña tan bien inclinada como usted las santas costumbres que ha visto practicar en aquel inocente asilo de la devocion y la virtud; pero si á pesar de todo esto la imaginacion acalorada, las circunstancias imprevistas la hubiesen hecho elegir sugeto mas digno, sepa usted que yo no quiero nada con violencia. Yo soy ingénuo: mi corazon y mi lengua no se contradicen jamás. Esto mismo la pido á usted, Paquita, sinceridad. El cariño que á usted la tengo no la debe hacer infeliz... Su madre de usted no es capaz de querer una injusticia, y sabe muy bien que á nadie se le hace dichoso por fuerza. Si usted no halla en mí prendas que la inclinen, si siente algun otro cuidadillo en su corazon, créame usted, la menor disimulacion en esto nos daria á todos muchísimo que sentir. D.ª I . ¿Puedo hablar ya, señor?"}]$lira$::jsonb, 811);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 15, 'Acto segundo. · Escena V. (2/2)', $lira$[{"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Ella, ella debe hablar, y sin apuntador, y sin intérprete."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Cuando yo se lo mande."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Pues ya puede usted mandárselo, porque á ella la toca responder..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Con ella he de casarme, con usted no."}, {"type": "p", "text": "D.ª I . Yo creo, señor D. Diego, que ni con ella ni conmigo. ¿En qué"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "concepto nos tiene usted?... Bien dice su padrino, y bien claro me lo escribió pocos dias há, cuando le dí parte de este casamiento. Que aunque no la ha vuelto á ver desde que la tuvo en la pila, la quiere muchísimo; y á cuantos pasan por el Burgo de Osma les pregunta cómo está, y contínuamente nos envia memorias con el ordinario."}, {"type": "p", "text": "D. D . Y bien, señora, ¿qué escribió el padrino?... O por mejor decir,"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "¿qué tiene que ver nada de eso con lo que estamos hablando? D.ª I . Sí señor que tiene que ver, sí señor. Y aunque yo lo diga, le"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "aseguro á usted que ni un padre de Atocha hubiera puesto una carta mejor que la que él me envió sobre el matrimonio de la niña... Y no es ningun catedrático, ni bachiller, ni nada de eso; sino un cualquiera, como quien dice, un hombre de capa y espada con un empleillo infeliz en el ramo del viento, que apenas le da para comer... Pero es muy ladino, y sabe de todo, y tiene una labia, y escribe que da gusto... Casi toda la carta venia en latin, no le parezca á usted, y muy buenos consejos que me daba en ella. Que no es posible sino que adivinase lo que nos está sucediendo. D. D . Pero, señora, si no sucede nada, ni hay cosa que á usted la deba"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "disgustar."}, {"type": "p", "text": "D.ª I . ¿Pues no quiere usted que me disguste oyéndole hablar de mi hija"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "en unos términos que?... ¡Ella otros amores ni otros cuidados!... Pues si tal hubiera... ¡Válgame Dios!... La mataba á golpes, mire usted... Respóndele, una vez que quiere que hables y que yo no chiste. Cuéntale los novios que dejaste en Madrid cuando tenias doce años, y los que has adquirido en el convento al lado de aquella santa muger. Díselo para que se tranquilice y... D. D . Yo, señora, estoy mas tranquilo que usted."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Respóndele."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Yo no sé qué decir. Si ustedes se enfadan."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . No, hija mia; esto es dar alguna expresion á lo que se dice; pero"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "enfadarnos, no por cierto. Doña Irene sabe lo que yo la estimo. D.ª I . Sí, señor, que lo sé, y estoy sumamente agradecida á los favores"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "que usted nos hace... Por eso mismo..."}, {"type": "p", "text": "D. D . No se hable de agradecimiento: cuanto yo puedo hacer, todo es"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "poco... Quiero que Doña Paquita esté contenta."}, {"type": "p", "text": "D.ª I . ¿Pues no ha de estarlo? Responde."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Sí, señor, que lo estoy."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Y que la mudanza de estado que se la previene, no la cueste el"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "menor sentimiento."}, {"type": "p", "text": "D.ª I . No señor, todo al contrario... Boda mas á gusto de todos no se"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "pudiera imaginar."}, {"type": "p", "text": "D. D . En esa inteligencia, puedo asegurarla que no tendrá motivos de"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "arrepentirse despues. En nuestra compañía vivirá querida y adorada; y espero que á fuerza de beneficios he de merecer su estimacion y su amistad."}, {"type": "p", "text": "D.ª F . Gracias, señor D. Diego... ¡A una huérfana, pobre, desvalida como"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "yo!..."}, {"type": "p", "text": "D. D . Pero de prendas tan estimables, que la hacen á usted digna todavía"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "de mayor fortuna."}, {"type": "p", "text": "D.ª I . Ven aquí, ven... Ven aquí, Paquita."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . ¡Mamá!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "(Levántase Doña Francisca, abraza á su madre y se acarician mutuamente.)"}, {"type": "p", "text": "D.ª I . ¿Ves lo que te quiero?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Sí, señora."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . ¿Y cuánto procuro tu bien, que no tengo otro pío sino el de verte"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "colocada antes que yo falte?"}, {"type": "p", "text": "D.ª F . Bien lo conozco."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . ¡Hija de mi vida!... ¿Has de ser buena?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . Sí, señora."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . ¡Ay, que no sabes tú lo que te quiere tu madre!"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . ¿Pues que no la quiero yo á usted?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Vamos, vamos de aquí. (Levántase Don Diego y despues Doña"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Irene.) No venga alguno y nos halle á los tres llorando como tres chiquillos."}, {"type": "p", "text": "D.ª I . Sí, dice usted bien."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "(Vanse los dos al cuarto de Doña Irene. Doña Francisca va detrás, y Rita que sale por la puerta del foro la hace detener.)"}]$lira$::jsonb, 796);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 16, 'Acto segundo. · Escena VI.', $lira$[{"type": "h", "text": "Rita, Doña Francisca."}, {"type": "p", "text": "R . Señorita... ¡Eh! chit... señorita."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Qué quieres?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Ya ha venido."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Cómo?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Ahora mismo acaba de llegar. Le he dado un abrazo, con licencia"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "de usted, y ya sube por la escalera."}, {"type": "p", "text": "D.ª F . ¡Ay Dios!... ¿Y qué debo hacer?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . ¡Donosa pregunta!... Vaya, lo que importa es no gastar el tiempo"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "en melindres de amor... Al asunto... y juicio. Y mire usted que en el paraje en que estamos la conversacion no puede ser muy larga... Ahí está."}, {"type": "p", "text": "D.ª F . Sí... Él es."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Voy á cuidar de aquella gente... Valor, señorita, y resolucion."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "(Rita se va al cuarto de Doña Irene.)"}, {"type": "p", "text": "D.ª F . No, no, que yo tambien... Pero no lo merece."}, {"type": "h", "text": "Ca"}]$lira$::jsonb, 142);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 17, 'Acto segundo. · Escena VII.', $lira$[{"type": "p", "text": "D. CARLOS, (Sale por la puerta del foro.) DOÑA FRANCISCA. D. C . ¡Paquita!... ¡Vida mia! Ya estoy aquí... ¿Cómo va, hermosa, cómo"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "va?"}, {"type": "p", "text": "D.ª F . Bien venido."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . ¿Cómo tan triste?... ¿No merece mi llegada mas alegría?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Es verdad, pero acaban de sucederme cosas que me tienen fuera"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "de mí... Sabe usted... Sí, bien lo sabe usted... Despues de escrita aquella carta, fueron por mí... Mañana á Madrid... Ahí está mi madre."}, {"type": "p", "text": "D. C . ¿En dónde?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Ahí, en ese cuarto. (Señalando al cuarto de Doña Irene.)"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . ¿Sola?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . No señor."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Estará en compañía del prometido esposo. (Se acerca al cuarto de"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª Irene, se detiene y vuelve.) Mejor... ¿Pero no hay nadie mas con ella?"}, {"type": "p", "text": "D.ª F . Nadie mas, solos están... ¿Qué piensa usted hacer?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Si me dejase llevar de mi pasion y de lo que esos ojos me inspiran,"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "una temeridad... Pero tiempo hay... Él tambien será hombre de honor, y no es justo insultarle porque quiere bien á una muger tan digna de ser querida... Yo no conozco á su madre de usted, ni... Vamos, ahora nada se puede hacer... Su decoro de usted merece la primera atencion."}, {"type": "p", "text": "D.ª F . Es mucho el empeño que tiene en que me case con él."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . No importa."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Quiere que esta boda se celebre así que lleguemos á Madrid."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . ¿Cuál?... No. Eso no."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Los dos están de acuerdo, y dicen..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Bien... Dirán... Pero no puede ser."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Mi madre no me habla contínuamente de otra materia... Me"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "amenaza, me ha llenado de temor... Él insta por su parte, me ofrece tantas cosas, me..."}, {"type": "p", "text": "D. C . ¿Y usted qué esperanza le da?... ¿Ha prometido quererle mucho?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . ¡Ingrato!... ¿Pues no sabe usted que?... ¡Ingrato!..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Sí, no lo ignoro, Paquita... Yo he sido el primer amor."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Y el último."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Y antes perderé la vida, que renunciar al lugar que tengo en ese"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "corazon... Todo él es mio... ¿Digo bien?"}, {"type": "p", "text": "(Asiéndola de las manos.)"}, {"type": "p", "text": "D.ª F . ¿Pues de quién ha de ser?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . ¡Hermosa! ¡Qué dulce esperanza me anima!... Una sola palabra de"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "esa boca me asegura... Para todo me da valor... En fin, ya estoy aquí. ¿Usted me llama para que la defienda, la libre, la cumpla una obligacion mil y mil veces prometida? Pues á eso mismo vengo yo... Si ustedes se van á Madrid mañana, yo voy tambien. Su madre de usted sabrá quién soy... Allí puedo contar con el favor de un anciano respetable y virtuoso, á quien mas que tio, debo llamar amigo y padre. No tiene otro deudo mas inmediato, ni mas querido que yo: es hombre muy rico, y si los dones de la fortuna tuviesen para usted algun atractivo, esta circunstancia añadiria felicidades á nuestra union."}, {"type": "p", "text": "D.ª F . ¿Y qué vale para mí toda la riqueza del mundo?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Ya lo sé. La ambicion no puede agitar á un alma tan inocente."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Querer y ser querida... Ni apetezco mas, ni conozco mayor"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "fortuna."}, {"type": "p", "text": "D. C . Ni hay otra... Pero usted debe serenarse, y esperar que la suerte"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "mude nuestra afliccion presente en durables dichas."}, {"type": "p", "text": "D.ª F . ¿Y qué se ha de hacer para que á mi pobre madre no la cueste una"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "pesadumbre?... ¡Me quiere tanto!... Sí, acabo de decirla que no la disgustaré, ni me apartaré de su lado jamás: que siempre seré obediente y buena... ¡Y me abrazaba con tanta ternura! Quedó tan consolada con lo poco que acerté á decirla... Yo no sé, no sé qué camino ha de hallar usted para salir de estos ahogos."}, {"type": "p", "text": "D. C . Yo le buscaré... ¿No tiene usted confianza en mí?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . ¿Pues no he de tenerla? ¿Piensa usted que estuviera yo viva, si esa"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "esperanza no me animase? Sola y desconocida de todo el mundo, ¿qué habia yo de hacer? Si usted no hubiese venido, mis"}, {"type": "p", "text": "melancolías me hubieran muerto, sin tener á quien volver los ojos, ni poder comunicar á nadie la causa de ellas... Pero usted ha sabido proceder como caballero y amante, y acaba de darme con su venida la prueba mayor de lo mucho que me quiere."}, {"type": "p", "text": "(Se enternece y llora.)"}, {"type": "p", "text": "D. C . ¡Qué llanto!... ¿Cómo me persuade?... Sí, Paquita, yo solo basto"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "para defender á usted de cuantos quieran oprimirla. A un amante favorecido, ¿quién puede oponérsele? Nada hay que temer. D.ª F . ¿Es posible?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Nada... Amor ha unido nuestras almas en estrechos nudos, y solo"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "el brazo de la muerte bastará á dividirlas."}]$lira$::jsonb, 839);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 18, 'Acto segundo. · Escena VIII.', $lira$[{"type": "h", "text": "Rita, D. Carlos, Doña Francisca."}, {"type": "p", "text": "R . Señorita, adentro. La mamá pregunta por usted. Voy á traer la"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "cena, y se van á recoger al instante... Y usted, señor galan, ya puede tambien disponer de su persona."}, {"type": "p", "text": "D. C . Sí, que no conviene anticipar sospechas... Nada tengo que añadir."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Ni yo."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Hasta mañana. Con la luz del dia veremos á este dichoso"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "competidor."}, {"type": "p", "text": "R . Un caballero muy honrado, muy rico, muy prudente: con su chupa"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "larga, su camisola limpia y sus sesenta años debajo del peluquin. (Se va por la puerta del foro.)"}, {"type": "p", "text": "D.ª F . Hasta mañana."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . A Dios, Paquita."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . Acuéstese usted, y descanse."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . ¿Descansar con zelos?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . ¿De quién?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Buenas noches... Duerma usted bien, Paquita."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . ¿Dormir con amor?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . A Dios, vida mia."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D.ª F . A Dios. (Éntrase al cuarto de Doña Irene.)"}, {"type": "h", "text": "Ca"}]$lira$::jsonb, 177);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 19, 'Acto segundo. · Escena IX.', $lira$[{"type": "h", "text": "D. Carlos, Calamocha, Rita."}, {"type": "p", "text": "D. C . ¡Quitármela! (Paseándose con inquietud.) No... Sea quien fuere,"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "no me la quitará. Ni su madre ha de ser tan imprudente que se obstine en verificar este matrimonio repugnándolo su hija... mediando yo... ¡Sesenta años!... Precisamente será muy rico... ¡El dinero!... Maldito él sea, que tantos desórdenes origina. C . (Sale Calamocha por la puerta del foro.) Pues señor, tenemos un"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "medio cabrito asado, y... A lo menos parece cabrito. Tenemos una magnífica ensalada de berros, sin anapelos, ni otra materia extraña, bien lavada, escurrida y condimentada por estas manos pecadoras, que no hay mas que pedir. Pan de Meco, vino de la Tercia... Con que si hemos de cenar y dormir, me parece que seria bueno..."}, {"type": "p", "text": "D. C . Vamos... ¿Y adónde ha de ser?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "C . Abajo... Allí he mandado disponer una angosta y fementida mesa,"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "que parece un banco de herrador."}, {"type": "p", "text": "(Sale Rita por la puerta del foro con unos platos, taza, cucharas y servilleta.)"}, {"type": "p", "text": "R . ¿Quién quiere sopas?"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D. C . Buen provecho."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "C . Si hay alguna real moza que guste de cenar cabrito, levante el"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "dedo."}, {"type": "p", "text": "R . La real moza se ha comido ya media cazuela de albondiguillas..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Pero lo agradece, señor militar."}, {"type": "p", "text": "(Éntrase en el cuarto de Doña Irene.)"}, {"type": "p", "text": "C . Agradecida te quiero yo, niña de mis ojos."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "D. C . ¿Con que vamos?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "C . ¡Ay! ¡ay! ¡ay! (Calamocha se encamina á la puerta del foro y"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "vuelve: se acerca á D. Cárlos, y hablan con reserva hasta el fin de la escena, en que Calamocha se adelanta á saludar á Simon.) ¡Eh! chit, digo..."}, {"type": "p", "text": "D. C . ¿Qué?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "C . ¿No ve usted lo que viene por allí?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "D. C . ¿Es Simon?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "C . Él mismo... ¿Pero, quién diablos le?..."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "D. C . ¿Y qué haremos?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "C . ¿Qué sé yo?... Sonsacarle, mentir y... ¿Me da usted licencia para"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "que?..."}, {"type": "p", "text": "D. C . Sí, miente lo que quieras... ¿A qué habrá venido este hombre?"}, {"type": "h", "text": "Ar"}]$lira$::jsonb, 351);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 20, 'Acto segundo. · Escena X.', $lira$[{"type": "p", "text": "SIMON, (Sale por la puerta del foro.) CALAMOCHA, D. CARLOS. C . Simon, ¿tú por aquí?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "S . A Dios, Calamocha. ¿Cómo va?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "C . Lindamente."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "S . Cuánto me alegro de..."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. C . ¿Hombre, tú en Alcalá? ¿Pues qué novedad es esta?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "S . ¡Oh, que estaba usted ahí, señorito! ¡Voto á sanes!"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. C . ¿Y mi tio?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "S . Tan bueno."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "C . ¿Pero se ha quedado en Madrid, ó?..."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "S . ¿Quién me habia de decir á mí?... ¡Cosa como ella! Tan ageno"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "estaba yo ahora de... Y usted de cada vez mas guapo... ¿Con que usted irá á ver al tio, eh?"}, {"type": "p", "text": "C . Tú habrás venido con algun encargo del amo."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "S . ¡Y qué calor traje, y que polvo por ese camino! ¡Ya, ya!"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "C . ¿Alguna cobranza tal vez, eh?"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "D. C . Puede ser. Como tiene mi tio ese poco de hacienda en Ajalvir..."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "¿No has venido á eso?"}, {"type": "p", "text": "S . ¡Y qué buena maula le ha salido el tal administrador! Labriego"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "mas marrullero y mas bellaco no le hay en toda la campiña... ¿Con que usted viene ahora de Zaragoza?"}, {"type": "p", "text": "D. C . Pues... Figúrate tú."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "S . ¿O va usted allá?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. C . ¿Adónde?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "S . A Zaragoza. ¿No está allí el regimiento?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "C . Pero, hombre, si salimos el verano pasado de Madrid, ¿no"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "habíamos de haber andado mas de cuatro leguas?"}, {"type": "p", "text": "S . ¿Qué sé yo? Algunos van por la posta y tardan mas de cuatro"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "meses en llegar... Debe de ser un camino muy malo."}, {"type": "p", "text": "C . Maldito (Aparte, separándose de Simon.) seas tú y tu camino, y la"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "bribona que te dió papilla."}, {"type": "p", "text": "D. C . Pero aun no me has dicho si mi tio está en Madrid ó en Alcalá, ni"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "á qué has venido, ni..."}, {"type": "p", "text": "S . Bien, á eso voy... Sí, señor, voy á decir á usted... Con que... Pues"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "el amo me dijo..."}]$lira$::jsonb, 348);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 21, 'Acto segundo. · Escena XI.', $lira$[{"type": "h", "text": "D. Diego, D. Carlos, Simon, Calamocha."}, {"type": "p", "text": "D. D . (Desde adentro.) No, no es menester: si hay luz aquí. Buenas"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "noches, Rita. (D. Cárlos se turba y se aparta á un extremo del teatro.)"}, {"type": "p", "text": "D. C . ¡Mi tio!... (Sale D. Diego del cuarto de Doña Irene"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "encaminándose al suyo: repara en D. Cárlos y se acerca á él. Simon le alumbra y vuelve á dejar la luz sobre la mesa.) D. D . Simon."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Aquí estoy, señor."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. C . ¡Todo se ha perdido!"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Vamos... Pero... ¿Quién es?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Un amigo de usted, señor."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. C . Yo estoy muerto."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Cómo un amigo?... ¡Qué!... Acerca esa luz."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Tio. (En ademan de besarle la mano á D. Diego, que le aparta de"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "sí con enojo.)"}, {"type": "p", "text": "D. D . Quítate de ahí."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Señor."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Quítate... No sé como no le... ¿Qué haces aquí?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Si usted se altera y..."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Qué haces aquí?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Mi desgracia me ha traido."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¡Siempre dándome que sentir, siempre! Pero... (Acercándose á D."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Cárlos.) ¿Qué dices? De veras, ¿ha ocurrido alguna desgracia? Vamos... ¿Qué te sucede?... ¿Por qué estás aquí?"}, {"type": "p", "text": "C . Porque le tiene á usted ley, y le quiere bien, y..."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "D. D . A tí no te pregunto nada... ¿Por qué has venido de Zaragoza sin"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que yo lo sepa?... ¿Por qué te asusta el verme?... Algo has hecho: sí, alguna locura has hecho que le habrá de costar la vida á tu pobre tio."}, {"type": "p", "text": "D. C . No señor, que nunca olvidaré las máximas de honor y prudencia"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "que usted me ha inspirado tantas veces."}, {"type": "p", "text": "D. D . ¿Pues á qué veniste?... ¿Es desafio? ¿Son deudas? ¿Es algun"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "disgusto con tus gefes?... Sácame de esta inquietud, Cárlos... Hijo mio, sácame de este afan."}, {"type": "p", "text": "C . Si todo ello no es mas que..."}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "D. D . Ya he dicho que calles... Ven acá. (Asiendo una mano á D."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Cárlos, se aparta con él á un extremo del teatro, y le habla en voz baja.) Dime qué ha sido."}, {"type": "p", "text": "D. C . Una ligereza, una falta de sumision á usted. Venir á Madrid sin"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "pedirle licencia primero... Bien arrepentido estoy, considerando la pesadumbre que le ha dado al verme."}, {"type": "p", "text": "D. D . ¿Y qué otra cosa hay?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Nada mas, señor."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Pues qué desgracia era aquella de que me hablaste?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Ninguna. La de hallarle á usted en este parage... y haberle"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "disgustado tanto, cuando yo esperaba sorprenderle en Madrid, estar en su compañía algunas semanas, y volverme contento de haberle visto."}, {"type": "p", "text": "D. D . ¿No hay mas?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . No señor."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Míralo bien."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . No señor... A eso venia. No hay nada mas."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Pero no me digas tú á mí... Sí, es imposible que estas escapadas"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "se... No señor... ¿Ni quién ha de permitir que un oficial se vaya cuando se le antoje, y abandone de ese modo sus banderas?... Pues si tales ejemplos se repitieran mucho, á Dios disciplina militar... Vamos... Eso no puede ser."}, {"type": "p", "text": "D. C . Considere usted, tio, que estamos en tiempo de paz: que en"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "Zaragoza no es necesario un servicio tan exacto como en otras plazas, en que no se permite descanso á la guarnicion..... Y en fin, puede usted creer que este viaje supone la aprobacion y licencia de mis superiores, que yo tambien miro por mi estimacion, y que cuando me he venido, estoy seguro de que no hago falta."}, {"type": "p", "text": "D. D . Un oficial siempre hace falta á sus soldados. El rey le tiene allí"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "para que los instruya, los proteja y les dé ejemplos de"}, {"type": "p", "text": "subordinacion, de valor, de virtud..."}, {"type": "p", "text": "D. C . Bien está, pero ya he dicho los motivos..."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Todos esos motivos no valen nada... ¡Porque le dió la gana de ver"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "al tio!... Lo que quiere su tio de usted no es verle cada ocho dias, sino saber que es hombre de juicio y que cumple con sus"}, {"type": "p", "text": "obligaciones. Eso es lo que quiere... Pero (Alza la voz y se pasea inquieto.) yo tomaré mis medidas para que estas locuras no se repitan otra vez... Lo que usted ha de hacer ahora es marcharse inmediatamente."}, {"type": "p", "text": "D. C . Señor, si..."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . No hay remedio... Y ha de ser al instante. Usted no ha de dormir"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "aquí."}, {"type": "p", "text": "C . Es que los caballos no están ahora para correr... Ni pueden"}, {"type": "h", "text": "Alam"}, {"type": "p", "text": "moverse."}, {"type": "p", "text": "D. D . Pues con ellos (A Calamocha) y con las maletas al meson de"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "afuera... Usted (A D. Cárlos.) no ha de dormir aquí... Vamos (A Calamocha) tú, buena pieza, menéate. Abajo con todo. Pagar el gasto que se haya hecho, sacar los caballos, y marchar... Ayúdale tú... (A Simon.) ¿Qué dinero tienes ahí?..."}, {"type": "p", "text": "S . Tendré unas cuatro ó seis onzas (Saca de un bolsillo algunas"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "monedas, y se las dá á D. Diego.)"}, {"type": "p", "text": "D. D . Dámelas acá... Vamos, ¿qué haces?... (A Calamocha) ¿No he"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "dicho que ha ser al instante?... Volando. Y tú (A Simon.) ve con él, ayúdale, y no te me apartes de allí hasta que se hayan ido. (Los dos criados entran en el cuarto de D. Cárlos.)"}]$lira$::jsonb, 935);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 22, 'Acto segundo. · Escena XII.', $lira$[{"type": "h", "text": "D. Diego, D. Carlos."}, {"type": "p", "text": "D. D . Tome usted. (Le dá el dinero.) Con eso hay bastante para el"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "camino... Vamos, que cuando yo lo dispongo así, bien sé lo que me hago... ¿No conoces que es todo por tu bien, y que ha sido un desatino el que acabas de hacer?... Y no hay que afligirse por eso, ni creas que es falta de cariño... Ya sabes lo que te he querido siempre, y en obrando tú segun corresponde, seré tu amigo como lo he sido hasta aquí."}, {"type": "p", "text": "D. C . Ya lo sé."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Pues bien: ahora obedece lo que te mando."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Lo haré sin falta."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Al meson de afuera. (A los dos criados que salen con los trastos"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "del cuarto de D. Cárlos, y se van por la puerta del foro.) Allí puedes dormir mientras los caballos comen y descansan... Y no me vuelvas aquí por ningun pretexto, ni entres en la ciudad... cuidado. Y á eso de las tres ó las cuatro marchar. Mira que he de saber á la hora que sales. ¿Lo entiendes?"}, {"type": "p", "text": "D. C . Sí, señor."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Mira que lo has de hacer."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Sí, señor, haré lo que usted manda."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Muy bien... A Dios... Todo te lo perdono... Vete con Dios... Y yo"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "sabré tambien cuando llegas á Zaragoza, no te parezca que estoy ignorante de lo que hiciste la vez pasada."}, {"type": "p", "text": "D. C . ¿Pues qué hice yo?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Si te digo que lo sé, y que te lo perdono, ¿qué mas quieres? No es"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "tiempo ahora de tratar de eso. Vete."}, {"type": "p", "text": "D. C . Quede usted con Dios. (Hace que se va y vuelve.)"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Sin besar la mano á su tio, eh?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . No me atreví. (Besa la mano á D. Diego y se abrazan.)"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Y dame un abrazo por si no nos volvemos á ver."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . ¿Qué dice usted? No lo permita Dios."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¡Quién sabe, hijo mio! ¿tienes algunas deudas? ¿Te falta algo?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . No señor, ahora no."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Mucho es, porque tú siempre tiras por largo... Como cuentas con"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "la bolsa del tio... Pues bien, yo escribiré al señor Aznar para que te dé cien doblones de órden mia. Y mira cómo lo gastas... ¿Juegas? D. C . No señor, en mi vida."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Cuidado con eso... Con que buen viage. Y no te acalores: jornadas"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "regulares y nada mas... ¿Vas contento?"}, {"type": "p", "text": "D. C . No señor, porque usted me quiere mucho, me llena de beneficios,"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "y yo le pago mal."}, {"type": "p", "text": "D. D . No se hable ya de lo pasado... A Dios..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . ¿Queda usted enojado conmigo?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . No, no por cierto... Me disgusté bastante, pero ya se acabó... No"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "me des que sentir. (Poniéndole ambas manos sobre los hombros.) Portarse como hombre de bien."}, {"type": "p", "text": "D. C . No lo dude usted."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Como oficial de honor."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Así lo prometo."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . A Dios, Cárlos. (Abrazándose.)"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . ¡Y la dejo!... (Aparte al irse por la puerta del foro.) ¡Y la pierdo"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "para siempre!"}]$lira$::jsonb, 575);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 23, 'Acto segundo. · Escena XIII.', $lira$[{"type": "p", "text": "D. D . Demasiado bien se ha compuesto... Luego lo sabrá, enhorabuena..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Pero no es lo mismo escribírselo, que... Despues de hecho, no importa nada... ¡Pero siempre aquel respeto al tio!... Como una malva es."}, {"type": "p", "text": "(Se enjuga las lágrimas, toma la luz y se va á su cuarto. El teatro queda solo y obscuro por un breve espacio.)"}]$lira$::jsonb, 59);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 24, 'Acto segundo. · Escena XIV.', $lira$[{"type": "h", "text": "Doña Francisca, Rita."}, {"type": "p", "text": "(Salen del cuarto de Doña Irene. Rita sacará una luz y la pone encima de la mesa.)"}, {"type": "p", "text": "R . Mucho silencio hay por aquí."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Se habrán recogido ya... Estarán rendidos."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Precisamente."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Un camino tan largo!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . ¡A lo que obliga el amor, señorita!"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Sí, bien puedes decirlo, amor... ¿Y yo qué no hiciera por él?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Y deje usted, que no ha de ser éste el último milagro. Cuando"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "lleguemos á Madrid, entonces será ella... ¡El pobre D. Diego qué chasco se va á llevar! Y por otra parte, vea usted qué señor tan bueno, que cierto da lástima..."}, {"type": "p", "text": "D.ª F . Pues en eso consiste todo. Si él fuese un hombre despreciable, ni"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "mi madre hubiera admitido su pretension, ni yo tendria que disimular mi repugnancia... Pero ya es otro tiempo, Rita. D. Felix ha venido, y ya no temo á nadie. Estando mi fortuna en su mano, me considero la mas dichosa de las mugeres."}, {"type": "p", "text": "R . ¡Ay! ahora que me acuerdo... Pues poquito me lo encargó... Ya se"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "ve, si con estos amores tengo yo tambien la cabeza... Voy por él. (Encaminándose al cuarto de Doña Irene.)"}, {"type": "p", "text": "D.ª F . ¿A qué vas?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . El tordo, que ya se me olvidaba sacarle de allí."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Sí, tráele, no empiece á rezar como anoche... Allí quedó junto á la"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "ventana... Y ve con cuidado no despierte mamá."}, {"type": "p", "text": "R . Sí, mire usted el estrépito de caballerías que anda por allá abajo..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Hasta que lleguemos á nuestra calle del Lobo, número siete, cuarto segundo, no hay que pensar en dormir... Y ese maldito porton que rechina, que..."}, {"type": "p", "text": "D.ª F . Te puedes llevar la luz."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . No es menester, que ya sé donde está."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "(Vase al cuarto de Doña Irene.)"}]$lira$::jsonb, 326);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 25, 'Acto segundo. · Escena XV.', $lira$[{"type": "p", "text": "SIMON, (Sale por la puerta del foro.) DOÑA FRANCISCA."}, {"type": "p", "text": "D.ª F . Yo pensé que estaban ustedes acostados."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "S . El amo ya habrá hecho esa diligencia, pero yo todavía no sé en"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "donde he de tender el rancho... Y buen sueño que tengo."}, {"type": "p", "text": "D.ª F . ¿Qué gente nueva ha llegado ahora?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "S . Nadie. Son unos que estaban ahí, y se han ido."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D.ª F . ¿Los arrieros?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "S . No señora. Un oficial y un criado suyo, que parece que se van á"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "Zaragoza."}, {"type": "p", "text": "D.ª F . ¿Quiénes dice usted que son?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "S . Un teniente coronel y su asistente."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D.ª F . ¿Y estaban aquí?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "S . Sí, señora, ahí en ese cuarto."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D.ª F . No los he visto."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "S . Parece que llegaron esta tarde y... A la cuenta habrán despachado"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "ya la comision que traían. Con que se han ido... Buenas noches, señorita. (Vase al cuarto de D. Diego.)"}]$lira$::jsonb, 168);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 26, 'Acto segundo. · Escena XVI.', $lira$[{"type": "h", "text": "Rita, Doña Francisca."}, {"type": "p", "text": "D.ª F . ¡Dios mio de mi alma! ¿Qué es esto?... No puedo sostenerme..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "¡Desdichada!"}, {"type": "p", "text": "(Siéntase en una silla inmediata á la mesa.)"}, {"type": "p", "text": "R . Señorita, yo vengo muerta. (Saca la jaula del tordo y la deja"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "encima de la mesa, abre la puerta del cuarto de D. Cárlos y vuelve.)"}, {"type": "p", "text": "D.ª F . ¡Ay que es cierto!... ¿Tú lo sabes tambien?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Deje usted, que todavía no creo lo que he visto... Aquí no hay"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "nadie... Ni maletas, ni ropa, ni... ¿Pero cómo podia engañarme? Si yo misma los he visto salir."}, {"type": "p", "text": "D.ª F . ¿Y eran ellos?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Sí, señora. Los dos."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Pero se han ido fuera de la ciudad?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Si no los he perdido de vista hasta que salieron por la puerta de"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "Mártires... Como está un paso de aquí."}, {"type": "p", "text": "D.ª F . ¿Y es ese el camino de Aragon?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Ese es."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Indigno!... ¡Hombre indigno!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Señorita."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿En qué te ha ofendido esta infeliz?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Yo estoy temblando toda... Pero... si es incomprensible... Si no"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "alcanzo á discurrir qué motivos ha podido haber para esta novedad."}, {"type": "p", "text": "D.ª F . ¿Pues no le quise mas que á mi vida? ¿No me ha visto loca de"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "amor?"}, {"type": "p", "text": "R . No sé qué decir al considerar una accion tan infame."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Qué has de decir? Que no me ha querido nunca ni es hombre de"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "bien... ¿Y vino para esto? ¿Para engañarme, para abandonarme así?"}, {"type": "p", "text": "(Levántanse, y Rita la sostiene.)"}, {"type": "p", "text": "R . Pensar que su venida fué con otro designio, no me parece"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "natural... Celos... ¿Por qué ha de tener celos?... Y aun eso mismo debiera enamorarle mas... Él no es cobarde, y no hay que decir que habrá tenido miedo de su competidor."}, {"type": "p", "text": "D.ª F . Te cansas en vano... Dí que es un pérfido, dí que es un monstruo"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "de crueldad, y todo lo has dicho."}, {"type": "p", "text": "R . Vamos de aquí que puede venir alguien y..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Sí, vámonos... Vamos á llorar... ¡Y en qué situacion me deja! Pero"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "¿ves qué malvado?"}, {"type": "p", "text": "R . Sí, señora, ya lo conozco."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Qué bien supo fingir!... ¿Y con quién? Conmigo... ¿Pues yo"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "merecí ser engañada tan alevosamente?... ¿Mereció mi cariño este galardon?... ¡Dios de mi vida! ¿Cuál es mi delito, cuál es? (Rita coge la luz, y se van entrambas al cuarto de Doña"}, {"type": "p", "text": "Francisca.)"}]$lira$::jsonb, 434);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 27, 'Acto tercero. · Escena I.', $lira$[{"type": "h", "text": "D. Diego, Simon."}, {"type": "p", "text": "(Teatro obscuro. Sobre la mesa habrá un candelero con vela apagada y la jaula del tordo. Simon duerme tendido en el banco. Sale D. Diego de su cuarto acabándose de poner la bata.) D. D . Aquí, á lo menos, ya que no duerma no me derretiré... Vaya, si"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "alcoba como ella, no se... ¡Cómo ronca éste! Guardémosle el sueño hasta que venga el dia, que ya poco puede tardar... (Simon despierta, y al oir á D. Diego se incorpora y se levanta.) ¿Qué es eso? Mira no te caigas, hombre."}, {"type": "p", "text": "S . ¿Qué estaba usted ahí, señor?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí, aquí me he salido, porque allí no se puede parar."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Pues yo, á Dios gracias, aunque la cama es algo dura, he dormido"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "como un emperador."}, {"type": "p", "text": "D. D . Mala comparacion. Dí que has dormido como un pobre hombre,"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que no tiene ni dinero, ni ambicion, ni pesadumbres, ni"}, {"type": "p", "text": "remordimientos."}, {"type": "p", "text": "S . En efecto, dice usted bien... ¿Y qué hora será ya?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Poco há que sonó el reloj de San Justo, y si no conté mal dió las"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "tres."}, {"type": "p", "text": "S . ¡Oh! pues ya nuestros caballeros irán por ese camino adelante"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "echando chispas."}, {"type": "p", "text": "D. D . Sí, ya es regular que hayan salido... Me lo prometió, y espero que"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "lo hará."}, {"type": "p", "text": "S . ¡Pero si usted viera qué apesadumbrado le dejé, qué triste!"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Ha sido preciso."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Ya lo conozco."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . ¿No ves qué venida tan intempestiva?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Es verdad... Sin permiso de usted, sin avisarle, sin haber un"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "motivo urgente... Vamos, hizo muy mal... Bien que por otra parte, él tiene prendas suficientes para que se le perdone esta ligereza... Digo... Me parece que el castigo no pasará adelante, ¿eh? D. D . ¡No, qué! No señor. Una cosa es que le haya hecho volver... Ya"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "ves en que circunstancias nos cogia... Te aseguro que cuando se fué me quedó un ánsia en el corazon... (Suenan á lo léjos tres palmadas, y poco despues se oye que puntean un instrumento.) ¿Qué ha sonado?"}, {"type": "p", "text": "S . No sé... Gente que pasa por la calle. Seran labradores."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Calla."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Vaya, música tenemos segun parece."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí, como la hagan bien."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Y quién será el amante infeliz que se viene á puntear á estas"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "horas en ese callejon tan puerco?... Apostaré que son amores con la moza de la posada, que parece un mico."}, {"type": "p", "text": "D. D . Puede ser."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Ya empiezan, oigamos... (Tocan una sonata desde adentro.) Pues"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "dígole á usted que toca muy lindamente el pícaro del barberillo. D. D . No, no hay barbero que sepa hacer esto, por muy bien que afeite."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Quiere usted que nos asomemos un poco, á ver?..."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . No, dejarlos... ¡Pobre gente! ¡Quién sabe la importancia que darán"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "ellos á la tal música!... No gusto yo de incomodar á nadie. (Sale de su cuarto Doña Francisca y Rita con ella. Las dos se encaminan á la ventana. D. Diego y Simon se retiran á un lado y observan.)"}, {"type": "p", "text": "S . Señor... ¡Eh!... Presto, aquí á un ladito."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . ¿Qué quieres?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Que han abierto la puerta de esa alcoba, y huele á faldas que"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "trasciende."}, {"type": "p", "text": "D. D . ¿Sí?... Retirémonos."}, {"type": "h", "text": "Ie"}]$lira$::jsonb, 588);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 28, 'Acto tercero. · Escena II.', $lira$[{"type": "h", "text": "Doña Francisca, Rita, D. Diego, Simon."}, {"type": "p", "text": "R . Con tiento, señorita."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Siguiendo la pared, no voy bien?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "(Vuelven á probar el instrumento.)"}, {"type": "p", "text": "R . Sí, señora... Pero vuelven á tocar... Silencio."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . No te muevas... Deja... Sepamos primero si es él."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . ¿Pues no ha de ser?... La seña no puede mentir."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Calla... (Repiten desde adentro la sonata anterior.) Sí, él es..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "¡Dios mio!... (Acércase Rita á la ventana, abre la vidriera, y da tres palmadas. Cesa la música.) Ve, responde... Albricias, corazon. Él es."}, {"type": "p", "text": "S . ¿Ha oido usted?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Que querrá decir esto?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Calla."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . (Doña Francisca se asoma á la ventana, Rita se queda detrás de"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "ella. Los puntos suspensivos indican las interrupciones mas ó menos largas que deben hacerse.)"}, {"type": "p", "text": "Yo soy... ¿Y qué habia de pensar viendo lo que usted acaba de hacer?... ¿Qué fuga es esta?... Rita (Apartándose de la ventana vuelve despues.) amiga, por Dios, ten cuidado y si oyeres algun rumor, al instante avísame... ¿Para siempre? ¡Triste de mí!... Bien está tírela usted... Pero yo no acabo de entender... ¡Ay! D. Felix, nunca le he visto á usted tan tímido... (Tiran desde adentro una carta que cae por la ventana al teatro. Doña Francisca hace ademan de buscarla, y no hallándola, vuelve á asomarse.) No, no la he cogido, pero aquí está sin duda... ¿Y no he de saber yo hasta que llegue el dia los motivos que tiene usted para dejarme muriendo?... Sí, yo quiero saberlo de su boca de usted. Su Paquita de usted se lo manda... ¿Y cómo le parece á usted que estará el mio?... No me cabe en el pecho... Diga usted."}, {"type": "p", "text": "(Simon se adelanta un poco, tropieza en la jaula y la deja caer.) R . Señorita, vamos de aquí... Presto, que hay gente."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Infeliz de mí!... Guíame."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Vamos... (Al retirarse tropieza Rita con Simon. Las dos se van"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "apresuradamente al cuarto de Doña Francisca.) ¡Ay!"}, {"type": "p", "text": "D.ª F . ¡Muerta voy!"}, {"type": "h", "text": "Ca"}]$lira$::jsonb, 363);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 29, 'Acto tercero. · Escena III.', $lira$[{"type": "h", "text": "D. Diego, Simon."}, {"type": "p", "text": "D. D . ¿Qué grito fué ese?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Una de las fantasmas, que al retirarse tropezó conmigo."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Acércate á esa ventana, y mira si hallas en el suelo un papel..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "¡Buenos estamos!"}, {"type": "p", "text": "S . No encuentro nada, señor."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "(Tentando por el suelo cerca de la ventana.)"}, {"type": "p", "text": "D. D . Búscale bien, que por ahí ha de estar."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Le tiraron desde la calle?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí... ¿Qué amante es este?... ¡Y diez y seis años, y criada en un"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "convento! Acabó ya toda mi ilusion."}, {"type": "p", "text": "S . Aquí está."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "(Halla la carta y se la dá á D. Diego.)"}, {"type": "p", "text": "D. D . Vete abajo y enciende una luz... En la caballeriza ó en la cocina..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Por ahí habrá algun farol... Y vuelve con ella al instante. (Vase Simon por la parte del foro.)"}]$lira$::jsonb, 151);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 30, 'Acto tercero. · Escena IV.', $lira$[{"type": "p", "text": "D. D . ¿Y á quién debo culpar? (Apoyándose en el respaldo de una silla.)"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "¿Es ella la delincuente, ó su madre, ó sus tias, ó yo?... ¿Sobre quién, sobre quien ha de caer esta cólera, que por mas que lo procuro, no la sé reprimir?... ¡La naturaleza la hizo tan amable á mis ojos!... ¡Qué esperanzas tan alagüeñas concebí! ¡Qué felicidades me prometia!... ¡Zelos!... ¿Yo?... ¡En que edad tengo zelos!... Vergüenza es... ¿Pero esta inquietud que yo siento, esta indignacion, estos deseos de venganza de qué provienen? ¿Cómo he de llamarlos? Otra vez parece que... (Advirtiendo que suena ruido en la puerta del cuarto de Doña Francisca, se retira á un extremo del teatro.) Sí."}]$lira$::jsonb, 117);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 31, 'Acto tercero. · Escena V.', $lira$[{"type": "h", "text": "Rita, D. Diego, Simon."}, {"type": "p", "text": "R . Ya se han ido... (Rita observa y escucha, asómase despues á la"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "ventana y busca la carta por el suelo.) ¡Válgame Dios!... El papel estará muy bien escrito; pero el señor D. Felix es un grandísimo picaron... ¡Pobrecita de mi alma!... Se muere sin remedio... Nada, ni perros parecen por la calle... ¡Ojalá no los hubiéramos conocido! ¿Y este maldito papel?... Pues buena la hiciéramos si no pareciese... ¿Qué dirá?... Mentiras, mentiras, y todo mentira. S . Ya tenemos luz. (Sale con luz. Rita se sorprende.)"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "R . ¡Perdida soy!"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D. D . ¡Rita! ¿Pues tú aquí? (Acercándose.)"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "R . Sí, señor, porque..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D. D . ¿Qué buscas á estas horas?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "R . Buscaba... Yo le diré á usted... Porque oimos un ruido tan"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "grande..."}, {"type": "p", "text": "S . ¿Sí, eh?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "R . Cierto... Un ruido y... Y mire usted (Alza la jaula que está en el"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "suelo.) era la jaula del tordo... Pues la jaula era, no tiene duda... ¡Válgate Dios! ¿Si se habrá muerto?... No, vivo está, vaya... Algún gato habrá sido. Preciso."}, {"type": "p", "text": "S . Sí, algun gato."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "R . ¡Pobre animal! Y qué asustadillo se conoce que está todavía."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "S . Y con mucha razon... ¿No te parece si le hubiera pillado el gato?..."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "R . Se le hubiera comido."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "(Cuelga la jaula de un clavo que habrá en la pared.)"}, {"type": "p", "text": "S . Y sin pebre... Ni plumas hubiera dejado."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Tráeme esa luz."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "R . ¡Ah! Deje usted encenderemos esta, (Enciende la vela que está"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "sobre la mesa.) que ya lo que no se ha dormido..."}, {"type": "p", "text": "D. D . ¿Y Doña Paquita duerme?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "R . Sí, señor."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "S . Pues mucho es que con el ruido del tordo..."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Vamos. (D. Diego se entra en su cuarto. Simon va con él"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "llevándose una de las luces.)"}]$lira$::jsonb, 328);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 32, 'Acto tercero. · Escena VI.', $lira$[{"type": "h", "text": "Doña Francisca, Rita."}, {"type": "p", "text": "D.ª F . ¿Ha parecido el papel?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . No señora."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¿Y estaban aquí los dos cuando saliste?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Yo no lo sé. Lo cierto es que el criado sacó una luz, y me hallé de"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "repente como por máquina, entre él y su amo, sin poder escapar, ni saber qué disculpa darles. (Rita coge la luz y vuelve á buscar la carta cerca de la ventana.)"}, {"type": "p", "text": "D.ª F . Ellos eran sin duda... Aquí estarian cuando yo hablé desde la"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "ventana... ¿Y ese papel?"}, {"type": "p", "text": "R . Yo no lo encuentro, señorita."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Le tendrán ellos, no te canses... Si es lo único que faltaba á mi"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "desdicha... No le busques. Ellos le tienen."}, {"type": "p", "text": "R . A lo menos por aquí..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Yo estoy loca! (Siéntase.)"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Sin haberse esplicado este hombre, ni decir siquiera..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Cuando iba á hacerlo, me avisaste y fué preciso retirarnos... ¿Pero"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "sabes tú con qué temor me habló, qué agitacion mostraba? Me dijo que en aquella carta veria yo los motivos justos que le precisaban á volverse: que la habia escrito para dejársela á persona fiel que la pusiera en mis manos, suponiendo que el verme seria imposible. Todo engaños, Rita, de un hombre aleve que prometió lo que no pensaba cumplir... Vino, halló un competidor, y diria: pues yo ¿para qué he de molestar á nadie, ni hacerme ahora defensor de una muger?... ¡Hay tantas mugeres!... Cásenla... ¡Yo nada pierdo!... Primero es mi tranquilidad que la vida de esa infeliz... ¡Dios mio, perdon!... ¡Perdon de haberle querido tanto!"}, {"type": "p", "text": "R . ¡Ay señorita! (Mirando hácia el cuarto de D. Diego.) que parece"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "que salen ya."}, {"type": "p", "text": "D.ª F . No importa, déjame."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "R . Pero si D. Diego la ve á usted de esa manera..."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . Si todo se ha perdido ya, ¿qué puedo temer?... ¿Y piensas tú que"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "tengo alientos para levantarme?... Que vengan, nada importa."}]$lira$::jsonb, 343);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 33, 'Acto tercero. · Escena VII.', $lira$[{"type": "h", "text": "D. Diego, Simon, Doña Francisca, Rita."}, {"type": "p", "text": "S . Voy enterado, no es menester mas."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Mira, y haz que ensillen inmediatamente al Moro, mientras tú vas"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "allá. Si han salido vuelves, montas á caballo, y en una buena carrera que des, los alcanzas... ¿Las dos aquí, eh?... Con que vete, no se pierda tiempo. (Despues de hablar los dos, inmediatos á la puerta del cuarto de D. Diego, se va Simon por la del foro.) S . Voy allá."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Mucho se madruga, Doña Paquita."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Sí, señor."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Ha llamado ya Doña Irene?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . No señor... Mejor es que vayas allá, por si ha despertado y se"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "quiere vestir. (Rita se va al cuarto de Doña Irene.)"}]$lira$::jsonb, 135);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 34, 'Acto tercero. · Escena VIII. (1/2)', $lira$[{"type": "h", "text": "D. Diego, Doña Francisca."}, {"type": "p", "text": "D. D . ¿Usted no habrá dormido bien esta noche?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . No señor. ¿Y usted?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Tampoco."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Ha hecho demasiado calor."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Está usted desazonada?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Alguna cosa."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Qué siente usted?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "(Siéntase junto á Doña Francisca.)"}, {"type": "p", "text": "D.ª F . No es nada... Así un poco de... Nada... no tengo nada."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Algo será; porque la veo á usted muy abatida, llorosa, inquieta..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "¿Qué tiene usted, Paquita? ¿No sabe usted que la quiero tanto? D.ª F . Sí, señor."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Pues por qué no hace usted mas confianza de mí? ¿Piensa usted"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que no tendré yo mucho gusto en hallar ocasiones de"}, {"type": "p", "text": "complacerla?"}, {"type": "p", "text": "D.ª F . Ya lo sé."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Pues cómo, sabiendo que tiene usted un amigo, no desahoga con"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "él su corazon?"}, {"type": "p", "text": "D.ª F . Porque eso mismo me obliga á callar."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Eso quiere decir que tal vez yo soy la causa de su pesadumbre de"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "usted."}, {"type": "p", "text": "D.ª F . No señor, usted en nada me ha ofendido... No es de usted de quien"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "yo me debo quejar."}, {"type": "p", "text": "D. D . ¿Pues de quién, hija mia?... Venga usted acá... (Acércase mas.)"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Hablemos siquiera una vez sin rodeos ni disimulacion... Dígame usted, ¿no es cierto que usted mira con algo de repugnancia este casamiento que se la propone? ¿Cuánto va que si la dejasen á usted entera libertad para la eleccion, no se casaria conmigo? D.ª F . Ni con otro."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Será posible que usted no conozca otro mas amable que yo, que"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "la quiera bien, y que la corresponda como usted merece?"}, {"type": "p", "text": "D.ª F . No señor, no señor."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Mírelo usted bien."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . ¿No le digo á usted que no?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Y he de creer, por dicha, que conserve usted tal inclinacion al"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "retiro en que se ha criado, que prefiera la austeridad del convento á una vida mas..."}, {"type": "p", "text": "D.ª F . Tampoco, no señor... Nunca he pensado así."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . No tengo empeño de saber mas... Pero de todo lo que acabo de oir"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "resulta una gravísima contradiccion. Usted no se halla inclinada al estado religioso, segun parece. Usted me asegura que no tiene queja ninguna de mí, que está persuadida de lo mucho que la estimo, que no piensa casarse con otro, ni debo recelar que nadie me dispute su mano... ¿Pues qué llanto es ese? ¿De dónde nace esa tristeza profunda, que en tan poco tiempo ha alterado su semblante de usted, en términos que apenas le reconozco? ¿Son estas las señales de quererme exclusivamente á mí, de casarse gustosa conmigo dentro de pocos dias? ¿Se anuncian así la alegría y el amor? (Vase iluminando lentamente el teatro, suponiendo que viene la luz del dia.)"}, {"type": "p", "text": "D.ª F . ¿Y qué motivos le he dado á usted para tales desconfianzas?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Pues qué? Si yo prescindo de estas consideraciones, si apresuro"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "las diligencias de nuestra union, si su madre de usted sigue aprobándola, y llega el caso de..."}, {"type": "p", "text": "D.ª F . Haré lo que mi madre me manda, y me casaré con usted."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Y despues, Paquita?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Despues... Y mientras me dure la vida seré mujer de bien."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Eso no lo puedo yo dudar... Pero si usted me considera como el"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "que ha de ser hasta la muerte su compañero y su amigo, dígame usted, estos títulos ¿no me dan algun derecho para merecer de usted mayor confianza? ¿No he de lograr que usted me diga la causa de su dolor? Y no para satisfacer una impertinente curiosidad, sino para emplearme todo en su consuelo, en mejorar su suerte, en hacerla dichosa, si mi conato y mis diligencias pudiesen tanto."}]$lira$::jsonb, 672);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 35, 'Acto tercero. · Escena VIII. (2/2)', $lira$[{"type": "p", "text": "D.ª F . ¡Dichas para mí!... Ya se acabaron."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¿Por qué?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Nunca diré por qué."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . ¡Pero qué obstinado, qué imprudente silencio!... Cuando usted"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "misma debe presumir que no estoy ignorante de lo que hay. D.ª F . Si usted lo ignora, señor D. Diego, por Dios no finja que lo sabe; y"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "si en efecto lo sabe usted, no me lo pregunte."}, {"type": "p", "text": "D. D . Bien está. Una vez que no hay nada que decir, que esa afliccion y"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "esas lágrimas son voluntarias, hoy llegaremos á Madrid, y dentro de ocho dias será usted mi muger."}, {"type": "p", "text": "D.ª F . Y daré gusto á mi madre."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Y vivirá usted infeliz."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Ya lo sé."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Ve aquí los frutos de la educacion. Esto es lo que se llama criar"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "bien á una niña; enseñarla á que desmienta y oculte las pasiones mas inocentes con una pérfida disimulacion. Las juzgan honestas luego que las ven instruidas en el arte de callar y mentir. Se obstinan en que el temperamento, la edad ni el genio no han de tener influencia alguna en sus inclinaciones, ó en que su voluntad ha de torcerse al capricho de quien las gobierna. Todo se las permite, menos la sinceridad. Con tal que no digan lo que sienten, con tal que finjan aborrecer lo que mas desean, con tal que se presten á pronunciar, cuando se lo manden, un sí perjuro, sacrílego, origen de tantos escándalos, ya están bien criadas; y se llama escelente educacion la que inspira en ellas el temor, la astucia y el silencio de un esclavo."}, {"type": "p", "text": "D.ª F . Es verdad... Todo eso es cierto... Eso exigen de nosotras, eso"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "aprendemos en la escuela que se nos da... Pero el motivo de mi aflicciones mucho mas grande."}, {"type": "p", "text": "D. D . Sea cual fuere, hija mia, es menester que usted se anime... Si la ve"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "á usted su madre de esa manera, ¿qué ha de decir?... Mire usted que ya parece que se ha levantado."}, {"type": "p", "text": "D.ª F . ¡Dios mio!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Sí, Paquita: conviene mucho que usted vuelva un poco sobre sí..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "No abandonarse tanto... Confianza en Dios... Vamos, que no siempre nuestras desgracias son tan grandes como la imaginacion las pinta... ¡Mire usted qué desórden este! ¡Qué agitacion! ¡Que lágrimas! Vaya, ¿me da usted palabra de presentarse así?... Con cierta serenidad y... ¿Eh?"}, {"type": "p", "text": "D.ª F . Y usted, señor... Bien sabe usted el genio de mi madre. Si usted no"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "me defiende, ¿á quién he de volver los ojos? ¿Quién tendrá compasion de esta desdichada?"}, {"type": "p", "text": "D. D . Su buen amigo de usted... Yo... ¿Cómo es posible que yo la"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "abandonase, criatura, en la situacion dolorosa en que la veo? (Asiéndola de las manos.)"}, {"type": "p", "text": "D.ª F . ¿De veras?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Mal conoce usted mi corazon."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Bien lo conozco."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "(Quiere arrodillarse, D. Diego se lo estorba, y ambos se levantan.)"}, {"type": "p", "text": "D. D . ¿Qué hace usted, niña?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Yo no sé... ¡Qué poco merece toda esa bondad una muger tan"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "ingrata para con usted!... No, ingrata no, infeliz... ¡Ay, qué infeliz soy, señor Don Diego!"}, {"type": "p", "text": "D. D . Yo bien sé que usted agradece como puede el amor que la tengo..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Lo demas todo ha sido... ¿Qué sé yo?... Una equivocacion mia, y no otra cosa... Pero usted, inocente, usted no ha tenido la culpa. D.ª F . Vamos... ¿No viene usted?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Ahora no, Paquita. Dentro de un rato iré por allá."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª F . Vaya usted presto."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "(Encaminándose al cuarto de Doña Irene, vuelve y se despide de D. Diego besándole las manos.)"}, {"type": "p", "text": "D. D . Sí, presto iré."}, {"type": "h", "text": "Ie"}]$lira$::jsonb, 649);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 36, 'Acto tercero. · Escena IX.', $lira$[{"type": "h", "text": "Simon, D. Diego."}, {"type": "p", "text": "S . Ahí están, señor."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . ¿Qué dices?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Cuando yo salia de la puerta, los ví á lo léjos que iban ya de"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "camino. Empecé á dar voces y hacer señas con el pañuelo: se detuvieron, y apenas llegué y le dije al señorito lo que usted mandaba, volvió las riendas, y está abajo. Le encargué que no subiera hasta que le avisára yo, por si acaso habia gente aquí, y usted no queria que le viesen."}, {"type": "p", "text": "D. D . ¿Y qué dijo cuando le diste el recado?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Ni una sola palabra... Muerto viene... Ya digo, ni una sola"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "palabra... A mí me ha dado compasion el verle así tan... D. D . No me empieces ya á interceder por él."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . ¿Yo, señor?"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Sí, que no te entiendo yo... ¡Compasion!... Es un pícaro."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "S . Como yo no sé lo que ha hecho."}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "D. D . Es un bribon, que me ha de quitar la vida... Ya te he dicho que no"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "quiero intercesores."}, {"type": "p", "text": "S . Bien está, señor. (Vase por la puerta del foro. D. Diego se sienta,"}, {"type": "h", "text": "Imon"}, {"type": "p", "text": "manifestando inquietud y enojo.)"}, {"type": "p", "text": "D. D . Dile que suba."}, {"type": "h", "text": "Ie"}]$lira$::jsonb, 215);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 37, 'Acto tercero. · Escena X. (1/2)', $lira$[{"type": "h", "text": "D. Diego, D. Carlos."}, {"type": "p", "text": "D. D . Venga usted acá, señorito, venga usted... ¿En dónde has estado"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "desde que no nos vemos?"}, {"type": "p", "text": "D. C . En el meson de afuera."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Y no has salido de allí en toda la noche, eh?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Sí, señor, entré en la ciudad y..."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿A qué?... Siéntese usted."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Tenia precision de hablar con un sugeto... (Siéntase.)"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¡Precision!"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Sí, señor... Le debo muchas atenciones, y no era posible volverme"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "á Zaragoza sin estar primero con él."}, {"type": "p", "text": "D. D . Ya. En habiendo tantas obligaciones de por medio... Pero venirle á"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "ver á las tres de la mañana, me parece mucho desacuerdo... ¿Por qué no le escribiste un papel?... Mira, aquí he de tener... Con este papel que le hubieras enviado en mejor ocasion, no habia necesidad de hacerle trasnochar, ni molestar á nadie."}, {"type": "p", "text": "(Dándole el papel que tiraron á la ventana. Don Cárlos luego que le reconoce, se le vuelve y se levanta en ademan de irse.) D. C . Pues si todo lo sabe usted, ¿para qué me llama? ¿Por qué no me"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "permite seguir mi camino y se evitaria una contestacion, de la cual ni usted ni yo quedaremos contentos?"}, {"type": "p", "text": "D. D . Quiere saber su tio de usted lo que hay en esto, y quiere que usted"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "se lo diga."}, {"type": "p", "text": "D. C . ¿Para qué saber mas?"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Porque yo lo quiero y lo mando. ¡Oiga!"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Bien está."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Siéntate ahí... (Siéntase D. Cárlos) ¿En dónde has conocido á esa"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "niña?... ¿Qué amor es este? ¿Qué circunstancias han ocurrido? ¿Qué obligaciones hay entre los dos? ¿Dónde, cuándo la viste? D. C . Volviéndome á Zaragoza el año pasado, llegué á Guadalajara sin"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "ánimo de detenerme; pero el intendente, en cuya casa de campo nos apeamos, se empeñó en que habia de quedarme allí todo aquel dia, por ser cumpleaños de su parienta, prometiéndome que al siguiente me dejaria proseguir mi viaje. Entre las gentes convidadas hallé á Doña Paquita, á quien la señora habia sacado aquel dia del convento para que se esparciese un poco... Yo no sé qué ví en ella, que excitó en mí una inquietud, un deseo constante, irresistible de mirarla, de oirla, de hallarme á su lado, de hablar con ella, de hacerme agradable á sus ojos... El intendente dijo entre otras cosas... burlándose... que yo era muy enamorado, y le ocurrió fingir que me llamaba Don Felix de Toledo, nombre que dió Calderon á algunos amantes de sus comedias. Yo sostuve esta ficcion, porque desde luego concebí la idea de permanecer algun tiempo en aquella ciudad, evitando que llegase á noticia de usted... Observé que Doña Paquita me trató con un agrado particular, y cuando por la noche nos separamos, yo quedé lleno de vanidad y de esperanzas, viéndome preferido á todos los concurrentes de aquel dia, que fueron muchos. En fin... Pero no quisiera ofender á usted refiriéndole..."}, {"type": "p", "text": "D. D . Prosigue."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Supe que era hija de una señora de Madrid, viuda pobre, pero de"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "gente muy honrada... Fué necesario fiar de mi amigo los proyectos de amor que me obligaban á quedarme en su compañía: y él, sin aplaudirlos ni desaprobarlos, halló disculpas las mas ingeniosas para que ninguno de su familia extrañára mi detencion. Como su casa de campo está inmediata á la ciudad, fácilmente iba y venia de noche... Logré que Doña Paquita leyese algunas cartas mias, y con las pocas respuestas que de ella tuve, acabé de precipitarme en una pasion, que mientras viva me hará infeliz."}, {"type": "p", "text": "D. D . Vaya... Vamos, sigue adelante."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Mi asistente (que como usted sabe, es hombre de travesura, y"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "conoce el mundo) con mil artificios que á cada paso le ocurrian, facilitó los muchos estorbos que al principio hallábamos... La seña era dar tres palmadas, á las cuales respondian con otras tres desde una ventanilla que daba al corral de las monjas. Hablábamos todas las noches, muy á deshora, con el recato y las precauciones que ya se dejan entender... Siempre fuí para ella D. Felix de Toledo, oficial de un regimiento, estimado de mis gefes, y hombre de honor. Nunca la dije mas, ni la hablé de mis parientes, ni de mis esperanzas, ni la dí á entender que casándose conmigo podria aspirar á mejor fortuna: porque ni me convenia nombrarle á usted, ni quise exponerla á que las miras de interés, y no el amor, la inclinasen á favorecerme. De cada vez la hallé mas fina, mas hermosa, mas digna de ser adorada... Cerca de tres meses me detuve allí; pero al fin, era necesario separarnos, y una noche funesta me despedí, la dejé rendida á un desmayo mortal, y me fuí ciego de amor adónde mi obligacion me llamaba... Sus cartas consolaron por algun tiempo mi ausencia triste, y en una que recibí pocos dias ha, me dijo como su madre trataba de casarla, que primero perderia la vida que dar su mano á otro que á mí: me acordaba mis juramentos, me exortaba á cumplirlos... Monté á caballo, corrí precipitado el camino, llegué á Guadalajara; no la encontré, vine aquí... Lo demas bien lo sabe usted, no hay para que decírselo."}]$lira$::jsonb, 908);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 38, 'Acto tercero. · Escena X. (2/2)', $lira$[{"type": "p", "text": "D. D . ¿Y qué proyectos eran los tuyos en esta venida?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Consolarla, jurarla de nuevo un eterno amor: pasar á Madrid, verle"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "á usted, echarme á sus piés, referirle todo lo ocurrido, y pedirle, no riquezas, ni herencias, ni protecciones, ni... eso no... Solo su consentimiento y su bendicion para verificar un enlace tan suspirado, en que ella y yo fundábamos toda nuestra felicidad. D. D . Pues ya ves, Cárlos, que es tiempo de pensar muy de otra manera."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Sí, señor."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Si tú la quieres, yo la quiero tambien. Su madre y toda su familia"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "aplauden este casamiento. Ella... y sean las que fueren las promesas que á tí te hizo... ella misma, no ha media hora, me ha dicho que está pronta á obedecer á su madre y darme la mano así que..."}, {"type": "p", "text": "D. C . Pero no el corazon. (Levántase.)"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Qué dices?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . No, eso no... Seria ofenderla... Usted celebrará sus bodas cuando"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "guste: ella se portará siempre como conviene á su honestidad y á su virtud; pero yo he sido el primero, el único objeto de su cariño, lo soy y lo seré... Usted se llamará su marido, pero si alguna ó muchas veces la sorprende, y ve sus ojos hermosos inundados en lágrimas, por mí las vierte... No la pregunte usted jamás el motivo de sus melancolías... Yo, yo seré la causa... Los suspiros, que en vano procurará reprimir, serán finezas dirigidas á un amigo ausente."}, {"type": "p", "text": "D. D . ¿Qué temeridad es esta?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "(Se levanta con mucho enojo, encaminándose hácia D. Cárlos el cual se va retirando.)"}, {"type": "p", "text": "D. C . Ya se lo dije á usted.... Era imposible que yo hablase una palabra"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "sin ofenderle... Pero acabemos esta odiosa conversacion... Viva usted feliz y no me aborrezca, que yo en nada le he querido disgustar... La prueba mayor que yo puedo darle de mi obediencia y mi respeto, es la de salir de aquí inmediatamente... Pero no se me niegue á lo menos el consuelo de saber que usted me perdona. D. D . ¿Con que en efecto te vas?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Al instante, señor... Y esta ausencia será bien larga."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¿Por qué?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Porque no me conviene verla en mi vida... Si las voces que corren"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "de una próxima guerra se llegaran á verificar... Entonces... D. D . ¿Qué quieres decir?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "(Asiendo de un brazo á D. Cárlos, le hace venir mas adelante.) D. C . Nada... que apetezco la guerra, porque soy soldado."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . ¡Cárlos!... ¡Qué horror!... ¿Y tienes corazon para decírmelo?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Alguien viene... (Mirando con inquietud hácia el cuarto de Doña"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "Irene, se desprende de D. Diego, y hace ademan de irse por la puerta del foro. D. Diego va detrás de él y quiere impedírselo.) Tal vez será ella... Quede usted con Dios."}, {"type": "p", "text": "D. D . ¿Adónde vas?... No señor, no has de irte."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Es preciso... Yo no he de verla... Una sola mirada nuestra pudiera"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "causarle á usted inquietudes crueles."}, {"type": "p", "text": "D. D . Ya he dicho que no ha de ser... Entra en ese cuarto."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D. C . Pero si..."}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Haz lo que te mando."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "(Éntrase D. Cárlos en el cuarto de D. Diego.)"}]$lira$::jsonb, 579);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 39, 'Acto tercero. · Escena XI. (1/2)', $lira$[{"type": "h", "text": "Doña Irene, D. Diego."}, {"type": "p", "text": "D.ª I . Con que, señor D. Diego, ¿es ya la de vámonos?... Buenos dias..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "(Apaga la luz que está sobre la mesa.) ¿Reza usted?"}, {"type": "p", "text": "D. D . Sí, para rezar estoy ahora. (Paseándose con inquietud.)"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Si usted quiere, ya pueden ir disponiendo el chocolate, y que"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "avisen al mayoral para que enganchen luego que... ¡Pero qué tiene usted, señor!... ¿Hay alguna novedad?"}, {"type": "p", "text": "D. D . Sí, no deja de haber novedades."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Pues qué... Dígalo usted por Dios... ¡Vaya, vaya!... No sabe usted"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "lo asustada que estoy... Cualquiera cosa, así repentina, me remueve toda y me... Desde el último mal parto que tuve quedé tan sumamente delicada de los nervios... Y va ya para diez y nueve años, si no son veinte; pero desde entonces, ya digo, cualquiera friolera me trastorna... Ni los baños, ni caldos de culebra, ni la conserva de tamarindos, nada me ha servido, de manera que..."}, {"type": "p", "text": "D. D . Vamos, ahora no hablemos de malos partos ni de conservas... Hay"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "otra cosa mas importante de que tratar... ¿Qué hacen esas muchachas?"}, {"type": "p", "text": "D.ª I . Están recogiendo la ropa y haciendo el cofre, para que todo esté á"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "la vela, y no haya detencion."}, {"type": "p", "text": "D. D . Muy bien. Siéntese usted... Y no hay que asustarse ni alborotarse"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "(Siéntanse los dos.) por nada de lo que yo diga: y cuenta, no nos abandone el juicio cuando mas le necesitamos... Su hija de usted está enamorada."}, {"type": "p", "text": "D.ª I . ¿Pues no lo he dicho ya mil veces? Sí señor que lo está, y bastaba"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "que yo lo dijese para que..."}, {"type": "p", "text": "D. D . ¡Este vicio maldito de interrumpir á cada paso! Déjeme usted"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "hablar."}, {"type": "p", "text": "D.ª I . Bien, vamos, hable usted."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Está enamorada; pero no está enamorada de mí."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¿Qué dice usted?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Lo que usted oye."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¿Pero quien le ha contado á usted esos disparates?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Nadie. Yo lo sé, yo lo he visto, nadie me lo ha contado, y cuando"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "se lo digo á usted, bien seguro estoy de que es verdad... Vaya, ¿qué llanto es ese?"}, {"type": "p", "text": "D.ª I . ¡Pobre de mí! (Llora.)"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . ¿A qué viene eso?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¡Porque me ven sola y sin medios, y porque soy una pobre viuda,"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "parece que todos me desprecian y se conjuran contra mí!"}, {"type": "p", "text": "D. D . Señora Doña Irene..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Al cabo de mis años y de mis achaques, verme tratada de esta"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "manera, como un estropajo, como una puerca cenicienta, vamos al decir... ¿quién lo creyera de usted?... ¡Válgame Dios!... ¡Si vivieran mis tres difuntos!... Con el último difunto que me viviera, que tenia el genio como una serpiente..."}, {"type": "p", "text": "D. D . Mire usted, señora, que se me acaba ya la paciencia."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Que lo mismo era replicarle que se ponía hecho una furia del"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "infierno, y un dia del Corpus, y no sé por qué friolera, hartó de mojicones á un comisario ordenador, y si no hubiera sido por dos padres del Cármen que se pusieron de por medio, le estrella contra un poste en los portales de Santa Cruz."}]$lira$::jsonb, 560);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 40, 'Acto tercero. · Escena XI. (2/2)', $lira$[{"type": "p", "text": "D. D . ¿Pero es posible que no ha de atender usted á lo que voy á decirla?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . ¡Ay! no señor, que bien lo sé, que no tengo pelo de tonta, no"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "señor... Usted ya no quiere á la niña, y busca pretextos para zafarse de la obligacion en que está... ¡Hija de mi alma y de mi corazon!"}, {"type": "p", "text": "D. D . Señora Doña Irene, hágame usted el gusto de oirme, de no"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "replicarme, de no decir despropósitos; y luego que usted sepa lo que hay, llore, y gima, y grite, y diga cuanto quiera... Pero entretanto no me apure usted el sufrimiento, por amor de Dios. D.ª I . Diga usted lo que le dé la gana."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Que no volvamos otra vez á llorar, y á..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . No señor, ya no lloro."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "(Enjugándose las lágrimas con un pañuelo.)"}, {"type": "p", "text": "D. D . Pues hace ya cosa de un año, poco mas ó menos, que Doña"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "Paquita tiene otro amante. Se han hablado muchas veces, se han escrito, se han prometido amor, fidelidad, constancia... Y por último, existe en ambos una pasion tan fina, que las dificultades y la ausencia, léjos de disminuirla, han contribuido eficazmente á hacerla mayor... En este supuesto..."}, {"type": "p", "text": "D.ª I . ¿Pero no conoce usted, señor, que todo es un chisme, inventado"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "por alguna mala lengua que no nos quiere bien?"}, {"type": "p", "text": "D. D . Volvemos otra vez á lo mismo... No señora, no es chisme. Repito"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "de nuevo que lo sé."}, {"type": "p", "text": "D.ª I . ¿Qué ha de saber usted, señor, ni qué traza tiene eso de verdad?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "¡Con que la hija de mis entrañas encerrada en un convento... ayunando los siete reviernes, acompañada de aquellas santas religiosas... ella, que no sabe lo que es mundo, que no ha salido todavía del cascaron, como quien dice!... Bien se conoce que no sabe usted el genio que tiene Circuncision... Pues bonita es ella, para haber disimulado á su sobrina el menor desliz."}, {"type": "p", "text": "D. D . Aquí no se trata de ningun desliz, señora Doña Irene; se trata de"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "una inclinacion honesta, de la cual hasta ahora no habíamos tenido antecedente alguno. Su hija de usted es una niña muy honrada, y no es capaz de deslizarse... Lo que digo es que la madre Circuncision, y la Soledad, y la Candelaria, y todas las madres y usted, y yo el primero, nos hemos equivocado solemnemente. La muchacha se quiere casar con otro, y no conmigo... Hemos llegado tarde: usted ha contado muy de ligero con la voluntad de su hija... Vaya, ¿para qué es cansarnos? Lea usted ese papel, y verá si tengo razón."}, {"type": "p", "text": "(Saca el papel de D. Cárlos y se le dá. Doña Irene, sin leerle, se levanta muy agitada, se acerca á la puerta de su cuarto y llama. Levántase D. Diego y procura en vano contenerla.)"}, {"type": "p", "text": "D.ª I . ¡Yo he de volverme loca!... Francisquita... ¡Vírgen del"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "Tremedal!... Rita, Francisca."}, {"type": "p", "text": "D. D . ¿Pero á qué es llamarlas?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . Sí, señor, que quiero que venga, y que se desengañe la pobrecita"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "de quién es usted."}, {"type": "p", "text": "D. D . Lo echó todo á rodar... Esto le sucede á quien se fia de la"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "prudencia de una muger."}]$lira$::jsonb, 555);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 41, 'Acto tercero. · Escena XII.', $lira$[{"type": "h", "text": "Doña Francisca, Rita, Doña Irene, D. Diego."}, {"type": "p", "text": "Señora."}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "¿Me llamaba usted?"}, {"type": "p", "text": "D.ª F ."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "Sí, hija, sí; porque el señor D. Diego nos trata de un modo que ya D.ª I ."}, {"type": "p", "text": "RE no se puede aguantar. ¿Qué amores tienes, niña? ¿A quién has dado palabra de matrimonio? ¿Qué enredos son estos?... Y tú, picarona... Pues tú tambien lo has de saber... Por fuerza lo sabes... ¿Quién ha escrito este papel? ¿Qué dice?... (Presentando el papel abierto á Doña Francisca.)"}, {"type": "p", "text": "R . Su letra es. (Aparte á Doña Francisca.)"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "D.ª F . ¡Qué maldad!... Señor D. Diego, ¿así cumple usted su palabra?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Bien sabe Dios que no tengo la culpa... Venga usted aquí..."}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "(Asiendo de una mano á Doña Francisca, la pone á su lado.) No hay que temer... Y usted, señora, escuche y calle, y no me ponga en términos de hacer un desatino... Deme usted ese papel... (Quitándola el papel de las manos á Doña Irene.) Paquita, ya se acuerda usted de las tres palmadas de esta noche."}, {"type": "p", "text": "D.ª F . Mientras viva me acordaré."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Pues este es el papel que tiraron á la ventana... No hay que"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "asustarse, ya lo he dicho. (Lee.) «Bien mio: si no consigo hablar con usted, haré lo posible para que llegue á sus manos esta carta. Apenas me separé de usted, encontré en la posada al que yo llamaba mi enemigo, y al verle no sé como no espiré de dolor. Me mandó que saliera inmediatamente de la ciudad, y fué preciso obedecerle. Yo me llamo D. Cárlos, no D. Felix... Don Diego es mi tio. Viva usted dichosa, y olvide para siempre á su infeliz amigo.—Cárlos de Urbina.»"}, {"type": "p", "text": "D.ª I . ¿Con que hay eso?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D.ª F . ¡Triste de mí!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . ¿Con que es verdad lo que decia el señor, grandísima picarona?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "Te has de acordar de mí. (Se encamina hácia Doña Francisca, muy colérica y en ademan de querer maltratarla, Rita y D. Diego procuran estorbarlo.)"}, {"type": "p", "text": "D.ª F . Madre... Perdon."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D.ª I . No señor, que la he de matar."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . ¿Qué locura es esta?"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "D.ª I . He de matarla."}, {"type": "h", "text": "Re"}]$lira$::jsonb, 378);
insert into public.chapters (book_id, position, title, body, word_count)
values ('el-si-de-las-ninas', 42, 'Acto tercero. · Escena XIII.', $lira$[{"type": "h", "text": "D. Carlos, D. Diego, Doña Irene, Doña Francisca, Rita."}, {"type": "p", "text": "D. C . Eso no... (Sale D. Cárlos del cuarto precipitadamente: coge de un"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "brazo á Doña Francisca, se la lleva hácia el fondo del teatro, y se pone delante de ella para defenderla. Doña Irene se asusta y se retira.) delante de mí nadie ha de ofenderla."}, {"type": "p", "text": "D.ª F . ¡Cárlos!"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. C . Disimule (Acercándose á D. Diego.) usted mi atrevimiento... He"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "visto que la insultaban, y no me he sabido contener."}, {"type": "p", "text": "D.ª I . ¡Qué es lo que me sucede, Dios mio!... ¿Quién es usted? ¿Qué"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "acciones son estas? ¿Qué escándalo?"}, {"type": "p", "text": "D. D . Aquí no hay escándalos... Ese es de quien su hija de usted está"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "enamorada... Separarlos y matarlos, viene á ser lo mismo... Cárlos... No importa... Abraza á tu muger."}, {"type": "p", "text": "(D. Cárlos va adónde está D.ª Francisca: se abrazan y ambos se arrodillan á los piés de D. Diego.)"}, {"type": "p", "text": "D.ª I . ¿Con que su sobrino de usted?"}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Sí, señora, mi sobrino: que con sus palmadas, y su música, y su"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "papel, me ha dado la noche mas terrible que he tenido en mi vida... ¿Qué es esto, hijos mios, qué es esto?"}, {"type": "p", "text": "D.ª F . ¿Con que usted nos perdona y nos hace felices?"}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "D. D . Sí, prendas de mi alma... Sí. (Los hace levantar con expresiones"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "de ternura.) D.ª I . ¿Y es posible que usted se determine á hacer un sacrificio?..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Yo pude separarlos para siempre, y gozar tranquilamente la"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "posesion de esta niña amable; pero mi conciencia no lo sufre... ¡Cárlos!... ¡Paquita! ¡Qué dolorosa impresion me deja en el alma el esfuerzo que acabo de hacer!... Porque, al fin, soy hombre miserable y débil."}, {"type": "p", "text": "D. C . Si nuestro amor, (Besándole las manos.) si nuestro"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "agradecimiento puede bastar á consolar á usted en tanta pérdida... D.ª I . ¡Con que el bueno de D. Cárlos! Vaya que..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "D. D . Él y su hija de usted estaban locos de amor, mientras usted y las"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "tias fundaban castillos al aire, y me llenaban la cabeza de ilusiones, que han desaparecido como un sueño... Esto resulta del abuso de la autoridad, de la opresion que la juventud padece: estas son las seguridades que dan los padres y los tutores, y esto lo que se debe fiar en el sí de las niñas... Por una casualidad he sabido á tiempo el error en que estaba. ¡Ay de aquellos que lo saben tarde! D.ª I . En fin, Dios los haga buenos, y que por muchos años se gocen..."}, {"type": "h", "text": "Re"}, {"type": "p", "text": "Venga usted acá, señor, venga usted, que quiero abrazarle... (Abrazándose D. Cárlos y Doña Irene. Doña Francisca se"}, {"type": "p", "text": "arrodilla y la besa la mano.) Hija, Francisquita. ¡Vaya! Buena eleccion has tenido... Cierto que es un mozo muy galan... Morenillo, pero tiene un mirar de ojos muy hechicero."}, {"type": "p", "text": "R . Sí, dígaselo usted, que no lo ha reparado la niña... Señorita, un"}, {"type": "h", "text": "Ita"}, {"type": "p", "text": "millon de besos. (Doña Francisca y Rita se besan manifestando mucho contento.)"}, {"type": "p", "text": "D.ª F . ¿Pero ves qué alegría tan grande?... Y tú, como me quieres tanto..."}, {"type": "h", "text": "Ca"}, {"type": "p", "text": "Siempre, siempre serás mi amiga."}, {"type": "p", "text": "D. D . Paquita hermosa (Abraza á Doña Francisca.) recibe los primeros"}, {"type": "h", "text": "Ie"}, {"type": "p", "text": "abrazos de tu nuevo padre... No temo ya la soledad terrible que amenazaba á mi vejez... Vosotros (Asiendo de las manos á Doña Francisca y á D. Cárlos.) sereis la delicia de mi corazon, y el primer fruto de vuestro amor... Sí, hijos, aquel... No hay remedio, aquel es para mí. Y cuando le acaricie en mis brazos podré decir; á mí me debe su existencia este niño inocente: si sus padres viven, si son felices, yo he sido la causa."}, {"type": "p", "text": "D. C . ¡Bendita sea tanta bondad!"}, {"type": "h", "text": "Ar"}, {"type": "p", "text": "D. D . Hijos, bendita sea la de Dios."}, {"type": "h", "text": "Ie Fin. Índice"}, {"type": "p", "text": "Páginas."}, {"type": "p", "text": "Personas 2"}]$lira$::jsonb, 658);

