insert into public.books (id, title, author, synopsis, category, chapter_count, minutes_to_read, tags, is_published)
values ('poeta-en-nueva-york', 'Poeta en Nueva York', 'Federico García Lorca', 'Lorca llega a Nueva York en 1929 y escribe lo que ve: multitudes, dinero y una ciudad que no duerme ni deja dormir.', 'poesia', 24, 120, array['poesía', 'ciudad', 'vanguardia']::text[], true)
