  tags = excluded.tags, is_published = true;

insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 0, 'Parte 1', $lira$[{"type": "v", "text": "Federico García Lorca"}, {"type": "h", "text": "Poeta en Nueva York"}, {"type": "v", "text": "(1929-1930)"}, {"type": "h", "text": "A bebé y carlos morla"}, {"type": "v", "text": "Los poemas de este\nlibro están escritos en la\nciudad de Nueva York el año\n1929-1930, en que el poeta\nvivió como estudiante en\nColumbia University."}, {"type": "h", "text": "F. G. L"}, {"type": "h", "text": "Poemas de la soledad en columbia"}, {"type": "h", "text": "University"}, {"type": "v", "text": "Furia color de amor\namor color de olvido."}, {"type": "h", "text": "Luis Cernuda"}, {"type": "h", "text": "Vuelta de Paseo"}, {"type": "v", "text": "Asesinado por el cielo,\nentre las formas que van hacia la sierpe\ny las formas que buscan el cristal,\ndejaré crecer mis cabellos.\nCon el árbol de muñones que no canta\ny el niño con el blanco rostro de huevo.\nCon los animalitos de cabeza rota\ny el agua harapienta de los pies secos.\nCon todo lo que tiene cansancio sordomudo\ny mariposa ahogada en el tintero.\nTropezando con mi rostro distinto de cada día.\n¡Asesinado por el cielo!"}, {"type": "h", "text": "(intermedio)"}, {"type": "v", "text": "Aquellos ojos míos de mil novecientos diez\nno vieron enterrar a los muertos,\nni la feria de ceniza del que llora por la madrugada,\nni el corazón que tiembla arrinconado como un caballito de mar.\nAquellos ojos míos de mil novecientos diez\nvieron la blanca pared donde orinaban las niñas,\nel hocico del toro, la seta venenosa\ny una luna incomprensible que iluminaba por los rincones\nlos pedazos de limón seco bajo el negro duro de las botellas.\nAquellos ojos míos en el cuello de la jaca,\nen el seno traspasado de Santa Rosa dormida,\nen los tejados del amor, con gemidos y frescas manos,\nen un jardín donde los gatos se comían a las ranas.\nDesván donde el polvo viejo congrega estatuas y musgos,\ncajas que guardan silencio de cangrejos devorados\nen el sitio donde el sueño tropezaba con su realidad.\nAllí mis pequeños ojos.\nNo preguntarme nada. He visto que las cosas\ncuando buscan su curso encuentran su vacío.\nHay un dolor de huecos por el aire sin gente\ny en mis ojos criaturas vestidas ¡sin desnudo!\nNueva York, agosto 1929"}]$lira$::jsonb, 325);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 1, 'Fábula y rueda de los tres amigos', $lira$[{"type": "h", "text": "Fábula y rueda de los tres amigos"}, {"type": "v", "text": "Enrique,\nEmilio,\nLorenzo,\nEstaban los tres helados:\nEnrique por el mundo de las camas;\nEmilio por el mundo de los ojos y las heridas de las manos,\nLorenzo por el mundo de las universidades sin tejados.\nLorenzo,\nEmilio,\nEnrique,\nEstaban los tres quemados:\nLorenzo por el mundo de las hojas y las bolas de billar;\nEmilio por el mundo de la sangre y los alfileres blancos,\nEnrique por el mundo de los muertos y los periódicos abandonados.\nLorenzo,\nEmilio, Enrique, Estaban los tres enterrados:\nLorenzo en un seno de Flora;\nEmilio en la, yerta ginebra que se olvida en el vaso,\nEnrique en la hormiga, en el mar y en los ojos vacíos de los pájaros.\nLorenzo,\nEmilio,\nEnrique,\nFueron los tres en mis manos\ntres montañas chinas,\ntres sombras de caballo,\ntres paisajes de nieve y una cabaña de azucenas\npor los palomares donde la luna se pone plana bajo el gallo.\nUno\ny uno\ny uno,\nEstaban los tres momificados,\ncon las moscas del invierno,\ncon los tinteros que orina el perro y desprecia el vilano,\ncon la brisa que hiela el corazón de todas las madres,\npor los blancos derribos de Júpiter donde meriendan muerte los borrachos.\nTres\ny dos\ny uno,\nLos vi perderse llorando y cantando\npor un huevo de gallina,\npor la noche que enseñaba su esqueleto de tabaco,\npor mi dolor lleno de rostros y punzantes esquirlas de luna,\npor mi alegría de ruedas dentadas y látigos,\npor mi pecho turbado por las palomas,\npor mi muerte desierta con un solo paseante equivocado.\nYo había matado la quinta luna\ny bebían agua por las fuentes los abanicos y los aplausos.\nTibia leche encerrada de las recién paridas\nagitaba las rosas con un largo dolor blanco.\nEnrique,\nEmilio,\nLorenzo.\nDiana es dura,\npero a veces tiene los pechos nublados.\nPuede la piedra blanca latir en la sangre del ciervo\ny el ciervo puede soñar por los ojos de un caballo.\nCuando se hundieron las formas puras\nbajo el cri cri de las margaritas,\ncomprendí que me habían asesinado.\nRecorrieron los cafés y los cementerios y las iglesias,\nabrieron los toneles y los armarios,\ndestrozaron tres esqueletos para arrancar sus dientes de oro.\nYa no me encontraron.\n¿No me encontraron?\nNo. No me encontraron.\nPero se supo que la sexta luna huyó torrente arriba,\ny que el mar recordó ¡de pronto!\nlos nombres de todos sus ahogados."}]$lira$::jsonb, 409);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 2, 'Tu Infancia en Menton', $lira$[{"type": "h", "text": "Tu Infancia en Menton"}, {"type": "v", "text": "Sí, tu niñez ya fábula de fuentes."}, {"type": "h", "text": "Jorge Guillén"}, {"type": "v", "text": "Sí, tu niñez ya fábula de fuentes.\nEl tren y la mujer que llena el cielo.\nTu soledad esquiva en los hoteles\ny tu máscara pura de otro signo.\nEs la niñez del mar y tu silencio\ndonde los sabios vidrios se quebraban.\nEs tu yerta ignorancia donde estuvo\nmi torso limitado por el fuego.\nNorma de amor te di, hombre de Apolo,\nllanto con ruiseñor enajenado,\npero, pasto de ruina, te afilabas\npara los breves sueños indecisos.\nPensamiento de enfrente, luz de ayer,\níndices y señales del acaso.\nTu cintura de arena sin sosiego\natiende sólo rastros que no escalan.\nPero yo he de buscar por los rincones\ntu alma tibia sin ti que no te entiende,\ncon el dolor de Apolo detenido\ncon que he roto la máscara que llevas.\nAllí, león, allí, furia del cielo,\nte dejaré pacer en mis mejillas;\na11í, caballo azul de mi locura,\npulso de nebulosa y minutero,\nhe de buscar las piedras de alacranes\ny los vestidos de tu madre niña,\nllanto de media noche y paño roto\nque quitó luna de la sien del muerto.\nSí, tu niñez ya fábula de fuentes.\nAlma extraña de mi hueco de venas,\nte he de buscar pequeña y sin raíces.\n¡Amor de siempre, amor, amor de nunca!\n¡Oh, sí! Yo quiero. ¡Amor, amor! Dejadme.\nNo me tapen la boca los que buscan\nespigas de Saturno por la nieve\no castran animales por un cielo,\nclínica y selva de la anatomía.\nAmor, amor, amor Niñez del mar.\nTu alma tibia sin ti que no to entiende.\nAmor, amor, un vuelo de la corza\npor el pecho sin fin de la blancura.\nY tu niñez, amor, y to niñez.\nEl tren y la mujer que llena el cielo.\nNi tú, ni yo, ni el aire, ni las hojas.\nSí, tu niñez ya fábula de fuentes."}]$lira$::jsonb, 322);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 3, 'II', $lira$[{"type": "h", "text": "II"}, {"type": "h", "text": "Los Negros"}, {"type": "v", "text": "Para Ángel del Río."}, {"type": "h", "text": "Norma y paraiso de los negros"}, {"type": "v", "text": "Odian la sombre del pájaro\nsobre el pleamar de la blanca mejilla\ny el conflicto de luz y viento\nen el salón de la nieve fría.\nOdian la flecha sin cuerpo,\nel pañuelo exacto de la despedida,\nla aguja que mantiene presión y rosa\nen el gramíneo tabor de la sonrisa.\nAman el azul desierto,\nlas vacilantes expresiones bovinas,\nla mentirosa luna de los polos,\nla danza curva del agua en 1a orilla.\nCon la ciencia del tronco y del rastro\nllenan de nervios luminosos la arcilla\ny patinan lúbricos por agua y arenas\ngustando la amarga frescura de su milenaria saliva.\nEs por el azul crujiente,\nazul sin un gusano ni una huella dormida,\ndonde los huevos de avestruz quedan eternos\ny deambulan intactas las lluvias bailarinas.\nEs por el azul sin historia,\nazul de una noche sin temor de día,\nazul donde el desnudo del viento va quebrando\nlos camellos sonámbulos de las nubes vacías.\nEs allí donde sueñan los torsos bajo la gula de la hierba.\nA11í los corales empapan la desesperación de la tinta,\nlos durmientes borran sus perfiles bajo la madeja de los caracoles\ny queda el hueco de la danza sobre las últimas cenizas."}, {"type": "h", "text": "El Rey de Harlem"}, {"type": "v", "text": "Con una cuchara\narrancaba los ojos a los cocodrilos\ny golpeaba el trasero de los monos.\nCon una cuchara.\nFuego de siempre dormía en los pedernales\ny los escarabajos borrachos de anís\nolvidaban el musgo de las aldeas.\nAquel viejo cubierto de setas\niba al sitio donde lloraban los negros\nmientras crujía la cuchara del rey\ny llegaban los tanques de agua podrida.\nLas rosas huían por los filos\nde las úitimas curves del aire,\ny en los montones de azafrán\nlos niños machacaban pequeñas ardillas\ncon un rubor de frenesí manchado.\nEs preciso cruzar los puentes\ny llegar al rubor negro\npara que el perfume de pulmón\nnos golpee las sienes con su vestido\nde caliente piña.\nEs preciso matar al rubio vendedor de aguardiente,\na todos los amigos de la manzana y de la arena,\ny es necesario dar con los puños cerrados\na las pequeñas judías que tiemblan llenas de burbujas,\npara que el rey de Harlem cante con su muchedumbre,\npara que los cocodrilos duerman en largas filas\nbajo el amianto de la luna,\ny para que nadie dude de la infinita belleza\nde los plumeros, los ralladores, los cobres y las cacerolas de las cocinas.\n¡Ay, Harlem! ¡Ay, Harlem! ¡Ay, Harlem!\nNo hay angustia comparable a tus rojos oprimidos,\na to sangre estremecida dentro del eclipse oscuro,\na tu violencia granate sordomuda en la penumbra,\na tu gran rey prisionero, con un traje de conserje.\nTenía la noche una hendidura y quietas salamandras de marfil.\nLas muchachas americanas\nllevaban niños y monedas en el vientre\ny los muchachos se desmayaban en la cruz del desperezo.\nEllos son.\nEllos son los que beben el whisky de plata junto a los volcanes\ny tragan pedacitos de corazón por las heladas montañas del oso.\nAquella noche el rey de Harlem con una durísima cuchara\narrancaba los ojos a los cocodrilos\ny golpeaba el trasero de los monos.\nCon una cuchara.\nLos negros lloraban confundidos\nentre paraguas y soles de oro,\nlos mulatos estiraban gomas, ansiosos de llegar al torso blanco,\ny el viento empañaba espejos\ny quebraba las venas de los bailarines.\nNegros, Negros, Negros, Negros.\nLa sangre no tiene puertas en vuestra noche boca arriba.\nNo hay rubor. Sangre furiosa por debajo de las pieles,\nviva en la espina del puñal y en el pecho de los paisajes,\nbajo las pinzas y las retamas de la celeste luna de cáncer.\nSangre que busca por mil caminos muertes enharinadas y ceniza de nardo,\ncielos yertos, en declive, donde las colonias de planetas\nrueden por las playas con los objetos abandonados.\nSangre que mira lenta con el rabo del ojo,\nhecha de espartos exprimidos, néctares de subterráneos.\nSangre que oxida el alisio descuidado en una huella\ny disuelve a las mariposas en los cristales de la ventana.\nEs la sangre que viene, que vendrá\npor los tejados y azoteas, por todas partes,\npara quemar la clorofila de las mujeres rubias,\npara gemir al pie de las camas ante el insomnio de los lavabos\ny estrellarse en una aurora de tabaco y bajo amarillo.\nHay que huir,\nhuir por las esquinas y encerrarse en los últimos pisos,\nporque el tuetano del bosque penetrará por las rendijas\npara dejar en vuestra carne una leve huella de eclipse\ny una falsa tristezá de guante desteñido y rosa química.\nEs por el silencio sapientísimo\ncuando los camareros y los cocineros y los que limpian con la lengua\nlas heridas de los millonarios\nbuscan al rey por las calles o en los ángulos del salitre.\nUn viento sur de madera, oblicuo en el negro fango,\nescupe a las barcas rotas y se clava puntillas en los hombros;\nun viento sur que lleva\ncolmillos, girasoles, alfabetos\ny una pila de Volta con avispas ahogadas.\nEl olvido estaba expresado por tres gotas de tinta sobre el monóculo,\nel amor por un solo rostro invisible a flor de piedra.\nMédulas y corolas componían sobre las nubes\nun desierto de tallos sin una sola rosa:\nA la izquierda, a la derecha, por el sur y por el norte,\nse levanta el muro impasible\npara el topo, la aguja del agua.\nNo busquéis, negros, su grieta\npara hallar la máseara infinita.\nBuscad el gran sol del centro\nhechos una piña zumbadora.\nEl sol que se desliza por los bosques\nseguro de no encontrar una ninfa,\nel sol que destruye números y no ha cruzado nunca un sueño,\nel tatuado sol que baja por el río\ny muge seguido de caimanes.\nNegros, Negros, Negros, Negros.\nJamás sierpe, ni cebra, ni mula\npalidecieron al morir.\nEl leñador no sabe cuándo expiran\nlos clamorosos árboles que corta.\nAguardad bajo la sombra vegetal de vuestro rey\na que cicutas .y cardos y ortigas turben postreras azoteas.\nEntonces, negros, entonces, entonces,\npodréis besar con frenesí las ruedas de las bicicletas,\nponer parejas de microscopios en las cuevas de las ardillas\ny danzar al fin, sin duda, mientras las flores erizadas\nasesinan a nuestro Moisés casi en los juncos del cielo.\n¡Ay, Harlem, disfrazada!\n¡Ay, Harlem, amenazada por un gentío de trajes sin cabeza!\nMe llega tu rumor,\nme llega tu rumor atravesando troncos y ascensores,\na través de láminas grises\ndonde flotan tus automóviles cubiertos de dientes,\na través de los caballos muertos y los crímenes diminutos,\na través de tu gran rey desesperado\ncuyas barbas llegan al mar."}]$lira$::jsonb, 1112);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 4, 'Iglesia Abandonada', $lira$[{"type": "h", "text": "Iglesia Abandonada"}, {"type": "h", "text": "(Balada de la gran guerra)"}, {"type": "v", "text": "Yo tenía un hijo que se llamaba Juan.\nYo tenía un hijo.\nSe perdió por los arcos un viernes de todos los muertos.\nLo vi jugar en las últimas escaleras de la misa\ny echaba un cubito de hojalata en el corazón del sacerdote.\nHe golpeado los ataúdes. ¡Mi hijo! ¡Mi hijo! ¡Mi hijo!\nSaqué una pata de gallina por detrás de la luna y luego\ncomprendí que mi niña era un pez\npor donde se alejan las carretas.\nYo tenía una niña.\nYo tenía un pez muerto bajo la ceniza de los incensarios.\nYo tenía un mar. ¿De qué? ¡Dios mío! ¡Un mar!\nSubí a tocar las campanas, pero las frutas tenían gusanos\ny las cerillas apagadas\nse comían los trigos de la primavera.\nYo vi la transparente cigüeña de alcohol\nmondar las negras cabezas de los soldados agonizantes\ny vi las cabañas de goma\ndonde giraban las copas llenas de lágrimas.\nEn las anémonas del ofertorio to encontraré, ¡corazón mío!,\ncuando el sacerdote levante la mula y el buey con sus fuertes brazos\npara espantar los sapos nocturnos que rondan los helados paisajes del cáliz.\nYo tenía un hijo que era un gigante,\npero los muertos son más fuertes y saben devorar pedazos de cielo.\nSi mi niño hubiera sido un oso,\nyo no temería el siglo de los caimanes,\nni hubiese visto el mar amarrado a los árboles\npara ser fornicado y herido por el tropel de los regimientos.\n¡Si mi niño hubiera sido un oso!\nMe envolveré sobre esta lona dura para no sentir el frío de los musgos.\nSé muy bien que me darán una manga o la corbata;\npero en el centro de la misa yo rompere el timón y entonces\nvendrá a la piedra la locura de pingüinos y gaviotas\nque harán decir a los que duermen y a los que cantan por las esquinas:\nél tenía un hijo.\n¡Un hijo! ¡Un hijo! ¡Un hijo\nque no era más que suyo. porque era su hijo!\n¡Su hijo! ¡Su hijo! ¡Su híjo!"}]$lira$::jsonb, 345);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 5, 'III', $lira$[{"type": "h", "text": "III"}, {"type": "h", "text": "Calles y Sueños"}, {"type": "v", "text": "A Rafael R. Rapún.\nUn pájaro de papel en el pecho\ndice que el tiempo de los besos no ha\nllegado."}, {"type": "h", "text": "Vicente Aleixandre"}, {"type": "h", "text": "Danza de la Muerte"}, {"type": "v", "text": "El mascarón, ¡Mirad el mascarón!\n¡Cómo viene del Africa a New York!\nSe fueron los árboles de la pimienta,\nLos queños botones de fósforo.\nSe fueron los camellos de carne desgarrada\ny los valles de luz que el cisne levantaba con el pico.\nEra el momento de las cosas secas,\nde la espiga en el ojo y el gato laminado,\ndel óxido de hierro de los grandes puentes\ny el definitivo silencio del corcho.\nEra la gran reunión de los animales muertos,\ntraspasados por las espadas de la luz;\nla alegría eterna del hipopótamo con las pezuñas de ceniza\ny de la gacela con una siempreviva en la garganta.\nEn la marchita soledad sin honda\nel abollado mascarón danzaba.\nMedio lado del mundo era de arena,\nmercurio y sol dormido el otro medio.\nEl mascarón. ¡Mirad el mascarón!\n¡Arena, caimán y rniedo sobre Nueva York!\nDesfiladeros de cal aprisionaban un cielo vacío\ndonde sonaban las voces de los que mueren bajo el guano.\nUn cielo mondado y puro, idéntico a sí mismo,\ncon el bozo y lirio agudo de sus montañas invisibles,\nacabó con los más leves tallitos del canto\ny se fue al diluvio empaquetado de la savia,\na través del descanso de los últimos desfiles,\nlevantando con el rabo pedazos de espejo.\nCuando el chino lloraba en el tejado\nsin encontrar el desnudo de su mujer\ny el director del banco observaba el manómetro\nque mide el cruel silencio de la moneda,\nel mascarón llegaba a Wall Street.\nNo es extraño para la danza\neste columbario que pone los ojos amarillos.\nDe la esfinge a la caja de caudales hay un hilo tenso\nque atraviesa el corazón de todos los niños pobres.\nEl ímpetu primitivo baila con el ímpetu mecánico,\nignorantes en su frenesí de la luz original.\nPorque si la rueda olvida su fórmula,\nya puede cantar desnuda con las manadas de caballos;\ny si una llama quema los helados proyectos,\nel cielo tendrá que huir ante el tumulto de las ventanas.\nNo es extraño este sitio para la danza, yo lo digo.\nEl mascarón bailará entre columnas de sangre y de números,\nentre huracanes de oro y gemidos de obreros parados\nque aullarán, noche oscura, por su tiempo sin luces,\n¡oh salvaje Norteamérica! ¡oh impúdica! ¡oh salvaje,\ntendida en la frontera de la nieve!\nEl mascarón. ¡Mirad el mascarón!\n¡Qué ola de fango y luc¡érnaga sobre Nueva York!\nYo estaba en la terraza luchando con la luna.\nEnjambres de ventanas acribillaban un muslo de la noche.\nEn mis ojos bebían las dulces vacas de los cielos.\nY las brisas de largos remos\ngolpeaban los cenicientos cristales de Broadway.\nLa gota de sangre buscaba la luz de la yema del astro\npara fingir una muerta semilla de manzana.\nEl aire de la llanura, empujado por los pastores,\ntemblaba con un miedo de molusco sin concha.\nPero no son los muertos los que bailan,\nestoy seguro.\nLos muertos están embebidos, devorando sus propias manos.\nSon los otros los que bailan con el mascarón y su vihuela;\nson los otros, los borrachos de plata, los hombres fríos,\nlos que crecen en el cruce de los muslos y llamas duras,\nlos que buscan la lombriz en el paisaje de las escaleras,\nlos que beben en el banco lágrimas de niña muerta\no los que comen por las esquinas diminutas pirámides del alba.\n¡Que no baile el Papa!\n¡No, que no baile el Papa!\nNi el Rey,\nni el millonario de dientes azules,\nni las bailarinas secas de las catedrales,\nni constructores, ni esmeraldas, ni locos, ni sodomitas.\nSólo este mascarón,\neste mascarón de vieja escarlatina,\n¡sólo este mascarón!\nQue ya las cobras silbarán por los últimos pisos,\nque ya las ortigas estremecerán patios y terrazas,\nque ya la Bolsa será una pirámide de musgo,\nque ya vendrán lianas después de los fusiles\ny muy pronto, muy pronto, muy pronto. ¡Ay, Wall Street!\nEl mascarón. ¡Mirad el mascarón!\n¡Cómo escupe veneno de bosqué\npor la angustia imperfecta de Nueva York!\nDiciembre, 1929."}]$lira$::jsonb, 702);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 6, 'Paisaje de la multitud que vomita', $lira$[{"type": "h", "text": "Paisaje de la multitud que vomita"}, {"type": "h", "text": "(anochecer Oe Coney Island)"}, {"type": "v", "text": "La mujer gorda venía delante\narrancando las raíces y mojando el pergamino de los tambores,.\nla mujer gorda\nque vuelve del revés los pulpos agonizantes.\nLa mujer gorda, enemiga de la luna,\ncorría por las calles y los pisos deshabitados\ny dejaba por los rincones pequeñas calaveras de paloma\ny levantaba las furias de los banquetes de los siglos últimos\ny llamaba al demonio del pan por las colinas del cielo barrido\ny filtraba un ansia de luz en las circulaciones subterráneas.\nSon los cementerios, lo sé, son los cementerios\ny el dolor de las cocinas enterradas bajo la arena,\nson los muertos, los faisanes y las manzanas de otra hora\nlos que nos empujan en la garganta.\nLlegaban los rumores de la selva del vómito\ncon las mujeres vacías, con niños de cera caliente,\ncon árboles fermentados y camareros incansables\nque sirven platos de sal bajo las arpas de la saliva.\nSin remedio, hijo mío, ¡vomita! No hay remedio.\nNo es el vómito de los húsares sobre los pechos de la prostituta,\nni el vómito del gato que se tragó una rana por descuido.\nSon los muertos que arañan con sus manos de tierra\nlas puertas de pedernal donde se pudren nublos y postres.\nLa mujer gorda venía delante\ncon las gentes de los barcos, de las tabernas y de los jardines.\nEl vómito agitaba delicadamente sus tambores\nentre algunas niñas de sangre\nque pedían protección a la luna.\n¡Ay de mí! ¡Ay de mí! ¡Ay de mí!\nEsta mirada mía fue mía, pero ya no es mía,\nesta mirada que tiembla desnuda por el alcohol\ny despide barcos increíbles\npor las anémonas de los muelles.\nMe defiendo con esta mirada\nque mana de las ondas por donde el alba no se atreve\nyo, poeta sin brazos, perdido\nentre la multitud que vomita,\nsin caballo efusivo que corte\nlos espesos musgos de mis sienes.\nPero la mujer gorda seguía delante\ny la gente buscaba las farmacias\ndonde el amargo trópico se fija.\nSólo cuando izaron la bandera y llegaron los primeros canes\nla ciudad entera se agolpó en las barandillas del embarcadero.\nNew York, 29 de diciembre de 1929."}]$lira$::jsonb, 370);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 7, 'Paisaje de la multitud que orina', $lira$[{"type": "h", "text": "Paisaje de la multitud que orina"}, {"type": "h", "text": "(nocturno de Battery Place)"}, {"type": "v", "text": "Se quedaron solos:\naguardaban la velocidad de las últimas bicicletas.\nSe quedaron solas:\nesperaban la muerte de un niño en el velero japonés.\nSe quedaron solos y solas\nsoñando con los picos abiertos de los pájaros agonizantes,\ncon el agudo quitasol que pincha\nal sapo recién aplastado,\nbajo un silencio con mil orejas\ny diminutas bocas de agua\nen los desfiladeros que resisten\nel ataque violento de la luna.\nLloraba el niño del velero y se quebraban los corazones\nangustiados or el testigo y la vigilia de todas las cosas\ny porque todavía en el suelo celeste de negras huellas\ngritaban nombres oscuros, salivas y radios de níquel.\nNo importa que el niño calle cuando le clavan el último alfiler,\nni importa la derrota de la brisa en la corola del algodón,\nporque hay un mundo de la muerte con marineros definitivos\nque se asomarán a los arcos y os helarán por detrás de los árboles.\nEs inútil buscar el recodo\ndonde la noche olvida su viaje\ny acechar un silencio que no tenga\ntrajes rotos y cáscaras y llanto,\nporque tan sólo el diminuto banquete de la araña\nbasta para romper el equilibrio de todo el cielo.\nNo hay remedio para el gemido del velero japonés,\nni para estas gentes ocultas que tropiezan con las esquinas.\nEl cameo se muerde la cola para unir las raíces en un punto\ny el ovillo busca por la grama su ansia de longitud insatisfecha.\n¡La luna! Los policías. ¡Las sirenas de los trasatlánticos!\nFachadas de crin, de humo; anémonas, guantes de goma.\nTodo está roto por la noche,\nabierta de piernas sobre las terrazas.\nTodo está roto por los tibios caños\nde una terrible fuente silenciosa.\n¡Oh gentes! ¡Oh mujercillas! ¡Oh soldados!\nSerá preciso viajar por los ojos de los idiotas,\ncampos libres donde silban mansas cobras deslumbradas,\npaisajes llenos de sepulcros que producen fresquísimas manzanas,\npara que venga la luz desmedida\nque temen los ricos detrás de sus lupas\nel olor de un solo cuerpo con la doble vertiente de lis y rata\ny para que se quemen estas gentes que pueden orinar alrededor de un gemido\nen los cristales donde se comprenden las olas nunca repetidas."}]$lira$::jsonb, 376);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 8, 'Asesinato', $lira$[{"type": "h", "text": "Asesinato"}, {"type": "h", "text": "(Dos voces de madrugada en river side drive)"}, {"type": "v", "text": "¿Cómo fue?\n—Una grieta en la mejilla.\n¡Eso es todo!\nUna uña que aprieta el tallo.\nUn alfilez que bucea\nhasta encontrar las raicillas del grito.\nY el mar deja de moverse.\n—¿Cómo, cómo fue?\n—Así.\n—¡Déjame! ¿De esa manera?\n—Sí.\nEl corazón salió solo.\n—¡Ay, ay de mí!"}, {"type": "h", "text": "Navidad en el Hudson"}, {"type": "v", "text": "¡Esa esponja gris!\nEse marinero recién degollado.\nEse río grande.\nEsa brisa de límites oscuros.\nEse filo, amor, ese filo.\nEstaban los cuatro marineros luchando con el mundo,\ncon el mundo de aristas que ven todos los ojos,\ncon el mundo que no se puede recorrer sin caballos.\nEstaban uno, cien, mil marineros,\nluchando con el mundo de las agudas velocidades,\nsin enterarse de que el mundo\nestaba solo por el cielo\nEl mundo solo por el cielo solo.\nSon las colinas de martillos y el triunfo de la hierba espesa.\nSon los vivísimos hormigueros y las monedas en el fango.\nEl mundo solo por el cielo solo\ny el aire a la salida de todas las aldeas.\nCantaba la lombriz el terror de la rueda\ny el marinero degollado\ncantaba el oso de agua que lo había de estrechar;\ny todos cantaban aleluya,\naleluya. Cielo desierto.\nEs lo mismo, ¡lo mismo!, aleluya.\nHe pasado toda la noche en los andamios de los arrabales\ndejándome la sangre por la escayola de los proyectos,\nayudando a los marineros a recoger las velas desgarradas.\nY estoy con las manos vacías en el rumor de la desembocadura.\nNo importa que cada minuto\nun niño nuevo agite sus ramitos de venas,\nni que el parto de la vI'bora, desatado bajo las ramas,\ncalme la sed de sangre de los que miran el desnudo.\nLo que importa es esto: hueco. Mundo solo. Desembocadura.\nAlba no. Fábula inerte.\nSólo esto: Desembocadura.\n¡Oh esponja mía gris!\n¡Oh cuello rnío recién degollado!\n¡Oh río grande mío!\n¡Oh brisa mía de límites que no son míos!\n¡Oh filo de mi amor, oh hiriente filo!\nNueva York, 27 de diciembre de 1929."}]$lira$::jsonb, 344);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 9, 'Ciudad sin Sueño', $lira$[{"type": "h", "text": "Ciudad sin Sueño"}, {"type": "h", "text": "(nocturno del Brooklyn Bridge"}, {"type": "v", "text": "No duerme nadie por el cielo. Nadie, nadie.\nNo duerme nadie.\nLas criaturas de la luna huelen y rondan sus cabañas.\nVendrán las iguanas vivas a morder a los hombres que no sueñan\ny el que huye con el corazón roto encontrará por las esquinas\nal increíble cocodrilo quieto bajo la tierna protesta de los astros.\nNo duerme nadie por el mundo. Nadie, nadie.\nNo duerme nadie.\nHay un muerto en el cementerio más lejano\nque se queja tres años\nporque tiene un paisaje seco en la rodilla;\ny el niño que enterraron esta mañana lloraba tanto\nque hubo necesidad de llamar a los perros para que callase.\nNo es sueño la vida. ¡Alerta! ¡Alerta! ¡Alerta!\nNos caemos por las escaleras para comer la tierra húmeda\no subimos al filo de la nieve con el coro de las dalias muertas.\nPero no hay olvido, ni sueño:\ncarne viva. Los besos atan las bocas\nen una maraña de venas recientes\ny al que le duele su dolor le dolerá sin descanso\ny al que teme la muerte la llevará sobre sus hombros.\nUn día\nlos caballos vivirán en las tabernas\nlas hormigas furiosas\natacarán los cielos amarillos que se refugian en los ojos de las vacas.\nOtro día\nveremos la resurrección de las mariposas disecadas\ny aún andando por un paisaje de esponjas grises y barcos mudos\nveremos brillar nuestro anillo y manar rosas de nuestra lengua.\n¡Alerta! ¡Alerta! ¡Alerta!\nA los que guardan todavía huellas de zarpa y aguacero,\na aquel muchacho que llora porque no sabe la invención deí puente\no a aquel muerto que ya no tiene más que la cabeza y un zapato,\nhay que llevarlos al muro donde iguanas y sierpes esperan,\ndonde espera la dentadura del oso,\ndonde espera la mano momificada del niño\ny la piel del camello se eriza con un violento escalofrío azul.\nNo duerme nadie por el cielo. Nadie, nadie.\nNo duerme nadie.\nPero si alguien cierra los ojos,\n¡azotadlo, hijos míos, azotadlo!\nHaya un panorama de ojos abiertos\ny amargas llagas encendidas.\nNo duerme nadie por el mundo. Nadie, nadie.\nYa lo he dicho.\nNo duerme nadie.\nPero si alguien tiene por la noche exceso de musgo en las sienes,\nabrid los escotillones para que vea bajo la luna\nlas copas falsas, el veneno y la calavera de los teatros."}]$lira$::jsonb, 397);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 10, 'Panorama ciego de nueva york', $lira$[{"type": "h", "text": "Panorama ciego de nueva york"}, {"type": "v", "text": "Si no son los pájaros\ncubiertos de ceniza,\nsi no son los gemidos que golpean las ventanas de la boda,\nserán las delicadas criaturas del aire\nque manan la sangre nueva por la oscuridad inextinguible.\nPero no, no son los pájaros,\nporque los pájaros están a punto de ser bueyes;\npueden ser rocas blancas con la ayuda de la luna\ny son siempre muchachos heridos\nantes de que los jueces levanten la tela.\nTodos comprenden el dolor que se relaciona con la muerte,\npero el verdadero dolor no está presente en el espíritu.\nNo está en el aire ni en nuestra vida,\nni en estas terrazas llenas de humo.\nEl verdadero dolor que mantiene despiertas las cosas\nes una pequeña quemadura infinita\nen los ojos inocentes de los otros sistemas.\nUn traje abandonado pesa tanto en los hombros\nque muchas veces el cielo los agrupa en ásperas manadas.\nY las que mueren de parto saben en la última hora\nque todo rumor será piedra y toda huella latido.\nNosotros ignoramos que el pensamiento tiene arrabales\ndonde el filósofo es devorado por los chinos y las orugas.\nY algunos niños idiotas han encontrado por las cocinas\npequeñas golondrinas con muletas\nque sabían pronunciar la palabra amor.\nNo, no son los pájaros.\nNo es un pájaro el que expresa la turbia fiebre de laguna,\nni el ansia de asesinato que nos oprime cada momento,\nni el metálico rumor de suicidio que nos anima cada madrugada.\nEs una cápsula de aire donde nos duele todo el mundo,\nes un pequeño espacio vivo al loco unisón de la luz,\nes una escala indefinible donde las nubes y rosas olvidan\nel griterío chino que bulle por el desembarcadero de la sangre.\nYo muchas veces me he perdido\npara buscar la quemadura que mantiene despiertas las cosas\ny sólo he encontrado marineros echados sobre las barandillas\ny pequeñas criaturas del cielo enterradas bajo la nieve.\nPero el verdadero dolor estaba en otras plazas\ndonde los peces cristalizados agonizaban dentro de los troncos,\nplazas del cielo extraño para las antiguas estatuas ilesas\ny para la tierna intimidad de los volcanes.\nNo hay dolor en la voz. Sólo existen los dientes,\npero dientes que callarán aislados por el raso negro.\nNo hay dolor en la voz. Aquí sólo existe la Tierra.\nLa tierra con sus puertas de siempre\nque llevan al rubor de los frutos."}]$lira$::jsonb, 402);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 11, 'Nacimiento de Cristo', $lira$[{"type": "h", "text": "Nacimiento de Cristo"}, {"type": "v", "text": "Un pastor pide teta por la nieve que ondula\nblancos perros tendidos entre linternas sordas.\nEl Cristito de barro se ha partido los dedos\nen los filos eternos de la madera rota.\n¡Ya vienen las hormigas y los pies ateridos!\nDos hilillos de sangre quiebran el cielo duro.\nLos vientres del demonio resuenan por los valles\ngolpes y resonancias de carne de molusco.\nLobos y sapos cantan en las hogueras verdes\ncoronadas por vivos hormigueros del alba.\nLa luna tiene un sueño de grandes abanicos\ny el toro sueña un toro de agujeros y de agua.\nEl niño llora y mira con un tres en la frente.\nSan José ve en el heno tres espinas de bronce.\nLos pañales exhalan un rumor de desierto\ncon cítaras sin cuerdas y degolladas voces.\nLa nieve de Manhattan empuja los anuncios\ny lleva gracia pura por las falsas ojivas.\nSacerdotes idiotas y querubes de pluma\nvan detrás de Lutero por las altas esquinas."}, {"type": "h", "text": "La Aurora"}, {"type": "v", "text": "La aurora de Nueva York tiene\ncuatro columnas de. cieno\ny un huracán de negras palomas\nque chapotean las aguas podridas.\nLa aurora de Nueva York gime\npor las inmensas escaleras\nbuscando entre las aristas\nnardos de angustia dibujada.\nLa aurora llega y nadie la recibe en su boca\nporque allí no hay mañana ni esperanza posible.\nA veces las monedas en enjambres furiosos\ntaladran y devoran abandonados niños.\nLos primeros que salen comprenden con sus huesos\nque no habrá paraíso ni amores deshojados;\nsaben que van al cieno de números y leyes,\na los juegos sin arte, a sudores sin fruto.\nLa luz es sepultada por cadenas y ruidos\nen impúdico reto de ciencia sin raíces.\nPor los barrios hay gentes que vacilan insomnes\ncomo recién salidas de un naufragio de sangre."}, {"type": "h", "text": "IV"}, {"type": "h", "text": "Poemas del lago edem mills"}, {"type": "v", "text": "A Eduardo Ugarte."}, {"type": "h", "text": "Poema doble del lago edem"}, {"type": "v", "text": "Nuestro ganado pace, el viento espira."}, {"type": "h", "text": "Garcilaso"}, {"type": "v", "text": "Era mi voz antigua\nignorante de los densos jugos amargos.\nLa adivino lamiendo mis pies\nbajo los frágiles helechos mojados.\n¡Ay voz antigua de mi amor,\nay voz de mi verdad,\nay voz de mi abierto costado,\ncuando todas las rosas manaban de mi lengua\ny el césped no conocía la impasible dentadura del caballo!\nEstás aquí bebiendo mi sangre,\nbebiendo mi humor de niño pesado,\nmientras mis ojos se quiebran en el viento\ncon el aluminio y las voces de los borrachos.\nDéjame pasar la puerta\ndonde Eva come hormigas\ny Adán fecunda peces deslumbrados.\nDéjame pasar hombrecillo de los cuernos\nal bosque de los desperezos\ny los alegrísimos saltos.\nYo sé el uso más secreto\nque tiene un viejo alfiler oxidado\ny sé del horror de unos ojos despiertos\nsobre la superficie concreta del plato.\nPero no quiero mundo ni sueño, voz divina,\nquiero mi libertad, mi amor humano\nen el rincón más oscuro de la brisa que nadie quiera.\n¡Mi amor humano!\nEsos perros marinos se persiguen\ny el viento acecha troncos descuidados.\n¡Oh voz antigua, quema con tu lengua\nesta voz de hojalata y de talco!\nQuiero llorar porque me da la gana\ncomo lloran los niños del último banco,\nporque yo no soy un hombre, ni un poeta, ni una hoja,\npero sí un pulso herido que sonda las cosas del otro lado.\nQuiero llorar diciendo mi nombre,\nrosa, niño y abeto a la orilla de este lago,\npara decir mi verdad de hombre de sangre\nmatando en mí la burla y la sugestión del vocablo.\nNo, no, yo no regunto, yo deseo,\nvoz mía liberta que me lames las manos.\nEn el laberinto de biombos es mi desnudo el que recibe\nla luna de castigo y el reloj encenizado.\nAsí hablaba yo.\nAsí hablaba yo cuando Saturno detuvo los trenes\ny la bruma y el sueño y la muerte me estaban buscando.\nMe estaban buscando\nallí donde mugen las vacas que tienen patitas de paje\ny a11í donde flota mi cuerpo entre los equilibrios contrarios."}]$lira$::jsonb, 660);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 12, 'Cielo Vivo', $lira$[{"type": "h", "text": "Cielo Vivo"}, {"type": "v", "text": "Yo no podré quejarme\nsi no encontré lo que buscaba.\nCerca de las piedras sin jugo y los insectos vacíos\nno veré el duelo del sol con las criaturas en carne viva.\nPero me iré al primer .paisaje\nde choques, líquidos y rumores\nque trasmina a niño recién nacido\ny donde toda superficie es evitada,\npara entender que lo que busco tendrá su blanco de alegría\ncuando yo vuele mezclado con el amor y las arenas.\nAllí no llega la escarcha de los ojos apagados\nni el mugido del árbol asesinado por la oruga.\nAllí todas las formas guardan entrelazadas\nuna sola expresión frenética de avance.\nNo puedes avanzar por los enjambres de corolas\nporque el aire disuelve tus dientes de azúcar,\nni puedes acariciar la fugaz hoja del helecho\nsin sentir el asombro definitivo del marfil.\nAllí bajo las raíces y en la médula del aire\nse comprende la verdad de las cosas equivocadas,\nel nadador de níquel que acecha la onda más fina\ny el rebaño de vacas nocturnas con rojas patitas de mujer.\nYo no podré quejarme\nsi no encontré lo que buscaba;\npero me iré al primer paisaje de humedades y latidos\npara entender que lo que busco tendrá su blanco de alegría\ncuando yo vuele mezclado con el amor y las arenas.\nVuelo fresco de siempre sobre lechos vacíos,\nsobre grupos de brisas y barcos encallados.\nTropiezo vacilante por la dura eternidad fija\ny amor al fin sin alba. Amor. ¡Amor visible!\nEdem Mills, Vermont, 24 agosto 1929."}, {"type": "h", "text": "En la cabaña del farmer"}, {"type": "h", "text": "(campo de Newburg)"}, {"type": "v", "text": "A Concha Méndez y Manuel Altolaguirre."}, {"type": "h", "text": "El Niño Stanton"}, {"type": "v", "text": "Do you like me?\n—Yes, and you?\n—Yes, yes.\nCuando me quedo solo\nme quedan todavía tus diez años,\nlos tres caballos ciegos,\ntus quince rostros con el rostro de la pedrada\ny las fiebres pequeñas heladas sobre las hojas del maíz.\nStanton, hijo mío, Stanton.\nA las doce de la noche el cáncer salía por los pasillos\ny hablaba con los caracoles vacíos de los documentos,\nel vivísimo cáncer lleno de nubes y termómetros\ncon su casto afán de manzana para que to piquen los ruiseñores.\nEn la casa donde no hay un cáncer\nse quiebran las blancas paredes en el delirio de la astronomía\ny por los establos más pequeños y en las cruces de los bosques\nbrilla por muchos años el fulgor de la quemadura.\nMi dolor sangraba por las tardes\ncuando tus ojos eran dos muros,\ncuando tus manos eran dos países\ny mi cuerpo rumor de hierba.\nMi agonía buscaba su traje,\npolvorienta, mordida por los perros,\ny tú la acompañaste sin temblar\nhasta la puerta del agua oscura.\n¡Oh, mi Stanton, idiota y bello entre los pequeños animalitos,\ncon tu madre fracturada por los herreros de las aldeas,\ncon un hermano bajo los arcos,\notro comido por los hormigueros,\ny el cáncer sin alambradas latiendo por las habitaciones!\nHay nodrizas que dan a los niños\nríos de musgo y amargura de pie\ny algunas negras suben a los pisos para repartir filtro de rata.\nPorque es verdad palomas la gente\nquiere echar las palomas a las alcantarillas\ny yo sé to que esperan los que por la calle\nnos oprimen de pronto las yemas de los dedos.\nTu ignorancia es un monte de leones, Stanton.\nEl día que el cáncer te dio una paliza\ny te escupió en el dormitorio donde murieron los huéspedes en la epidemia\ny abrió su quebrada rosa de vidrios secos y manos blandas\npara salpicar de lodo las pupilas de los que navegan,\ntú buscaste en la hierba mi agonía,\nmi agonía con flores de terror,\nmientras que el agrio cáncer mudo que quiere acostarse contigo\npulverizaba rojos paisajes por las sábanas de amargura,\ny ponía sobre los ataúdes\nhelados arbolitos de ácido bórico.\nStanton, vete al bosque con tus arpas judías,\nvete para aprender celestiales palabras\nque duermen en los troncos, en nubes, en tortugas,\nen los perros dormidos, en el plomo, en el viento,\nen lirios que no duermen, en aguas que no copian,\npara que aprendas, hijo, lo que tu pueblo olvida.\nCuando empiece el tumulto de la guerra\ndejaré un pedazo de queso para tu perro en la oficina.\nTus diez años serán las hojas\nque vuelan en los trajes de los muertos,\ndiez rosas de azufre débil\nen el hombro de mi madrugada.\nY yo, Stanton, yo solo, en olvido,\ncon tus caras marchitas sobre mi boca,\niré penetrando a voces las verdes estatuas de la Malaria."}]$lira$::jsonb, 755);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 13, 'Vaca', $lira$[{"type": "h", "text": "Vaca"}, {"type": "v", "text": "A Luis Lacasa.\nSe tendió la vaca herida.\nÁrboles y arroyos trepaban por sus cuernos.\nSu hocico sangraba en el cielo.\nSu hocico de abejas\nbajo el bigote lento de la baba.\nUn alarido blanco puso en pie la mañana.\nLas vacas muertas y las vivas,\nrubor de luz o miel de establo,\nbalaban con los ojos entornados.\nQue se enteren las raíces\ny aquel niño que afila su navaja\nde que ya se pueden comer la vaca.\nArriba palidecen\nluces y yugulares.\nCuatro pezuñas tiemblan en el aire.\nQue se entere la luna\ny esa noche de rocas amarillas:\nque ya se fue la vaca de ceniza.\nQue ya se fue balando\npor el derribo de los cielos yertos\ndonde meriendan muerte los borrachos."}, {"type": "h", "text": "Niña ahogada en el pozo"}, {"type": "h", "text": "(granada y Newburg)"}, {"type": "v", "text": "Las estatuas sufren por los ojos con la oscuridad de los ataúdes,\npero sufren mucho más por el agua que no desemboca.\nQue no desemboca.\nE1 pueblo corría por las almenas rompiendo las cañas de los pescadores\n¡Pronto! ¡Los bordes! ¡De prisa! Y croaban las estrellas tiernas\n. ...que no desemboca.\n¡Tranquila en mi recuerdo, astro, círculo, meta,\nlloras por las orillas de un ojo de caballo.\n. . . que no desemboca.\nPero nadie en to oscuro podrá darte distancias,\nsin afilado límite, porvenir de diamante.\n. . . que no desemboca.\nMientras la gente busca silencios de almohada\ntú lates para siempre definida en to anillo.\n...que no desemboca.\nEterna en los finales de unas ondas que aceptan\ncombate de raíces y soledad prevista.\n...que no desemboca.\n¡Ya vienen por las rampas! ¡Levántate del agua!\n¡Cada punto de luz te dará tuna cadena!\n. . . que no desemboca.\nPero el pozo te alarga manecitas de musgo,\ninsospechada ondina de su casta ignorancia.\n. . que no desemboca.\nNo, que no desemboca. Agua fija en un punto,\nrespirando con todos sus violines sin cuerdas\nen la escala de las heridas y los edificios deshabitados.\n¡Agua que no desemboca!"}]$lira$::jsonb, 334);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 14, 'VI', $lira$[{"type": "h", "text": "VI"}, {"type": "h", "text": "Introduccion a la Muerte"}, {"type": "h", "text": "Poemas de la soledad en vermont"}, {"type": "v", "text": "Para Rafael Sánchez Ventura."}, {"type": "h", "text": "Muerte"}, {"type": "v", "text": "¡Qué esfuerzo!\n¡Qué esfuerzo del caballo por ser perro!\n¡Qué esfuerzo del perro por ser golondrina!\n¡Qué esfuerzo de la golondrina por ser abeja!\n¡Qué esfuerzo de la abeja por ser caballo!\nY el caballo,\n¡qué flecha aguda exprime de la rosa!\n¡qué rosa gris levanta de su belfo!\nY la rosa,\n¡qué rebaño de luces y alaridos\nata en el vivo azúcar de su tronco!\nY el azúcar,\n¡qué puñalitos sueña en su vigilia!\nY los puñales diminutos,\n¡qué luna sin establos!, ¡qué desnudos,\npiel eterna y rubor, andan buscando!\nY yo, por los aleros,\n¡qué serafín de llamas busco y soy!\nPero el arco de yeso,\n¡qué grande, qué invisible, qué diminuto,\nsin esfuerzo!"}, {"type": "h", "text": "Nocturno del Hueco"}, {"type": "v", "text": "Para ver que todo se ha ido,\npara ver los huecos y los vestidos,\n¡dame to guante de luna,\ntu otro guante perdido en la hierba,\namor mío!\nPuede el aire arrancar los caracoles\nmuertos sobre el pulmón del elefante\ny soplar los gusanos ateridos\nde las yemas de luz o las manzanas.\nLos rostros bogan impasibles\nbajo el diminuto griterío de las yerbas\ny en el rincón está el pechito de la rana\nturbio de corazón y mandolina.\nEn la gran plaza desierta\nmugía la bovina cabeza recién cortada\ny eran duro cristal definitivo\nlas formas que buscaban el giro de la sierpe.\nPara ver que todo se ha ido\ndame to mudo hueco, ¡amor mío!\nNostalgia de academia y cielo triste.\n¡Para ver que todo se ha ido!\nDentro de ti, amor mío, por tu carne,\n¡qué silencio de trenes bocarriba!\n¡cuánto brazo de momia florecido!\n¡qué cielo sin salida, amor, qué cielo!\nEs la piedra en el agua y es la voz en la brisa\nbordes de amor que escapan de su tronco sangrante.\nBasta tocar el pulso de nuestro amor presente\npara que broten flores sobre los otros niños.\nPara ver que todo se ha ido.\nPara ver los huecos de nubes y ríos.\nDame tus manos de laurel, amor.\n¡Para ver que todo se ha ido!\nRuedan los huecos puros, por mí, por ti, en el alba\nconservando las huellas de las ramas de sangre\ny algún perfil de yeso tranquilo que dibuja\ninstantáneo dolor de luna apuntillada.\nMira formas concretas que buscan su vacío.\nPerros equivocados y manzanas mordidas.\nMira el ansia, la angustia de un triste mundo fósil\nque no encuentra el acento de su primer sollozo.\nCuando busco en la cama los rumores del hilo\nhas venido, amor mío, a cubrir mi tejado.\nEl hueco de una hormiga puede llenar el aire,\npero tú vas gimiendo sin norte por mis ojos.\nNo, por mis ojos no, que ahora me enseñas\ncuatro ríos ceñidos en tu brazo,\nen la dura barraca donde la luna prisionera\ndevora a un marinero delante de los niños.\nPara ver que todo se ha ido\n¡amor inexpugnable, amor huido!\nNo, no me des tu hueco,\n¡que ya va por el aire el mío!\n¡Ay de ti, ay de mí, de la brisa!\nPara ver que todo se ha ido."}]$lira$::jsonb, 526);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 15, 'II', $lira$[{"type": "h", "text": "II"}, {"type": "v", "text": "Yo.\nCon el hueco blanquísimo de un caballo,\ncrines de ceniza. Plaza pura y doblada.\nYo.\nMi hueco traspasado con las axilas rotas.\nPiel seca de uva neutra y amianto de madrugada.\nToda la luz del mundo cabe dentro de un ojo.\nCanta el gallo y su canto dura más que sus alas.\nYo.\nCon el hueco blanquísimo de un caballo. Rodeado\nde espectadores que tienen hormigas en las palabras.\nEn el circo del frío sin perfil mutilado.\nPor los capiteles rotos de las mejillas desangradas.\nYo.\nMi hueco sin ti, ciudad, sin tus muertos que comen.\nEcuestre por mi vida definitivamente anclada.\nYo.\nNo hay siglo nuevo ni luz reciente.\nSólo un caballo azul y una madrugada."}, {"type": "h", "text": "Paisaje con dos tumbas y un perro asirio"}, {"type": "v", "text": "Amigo,\nlevántate para que oigas aullar\nal perro asirio.\nLas tres ninfas del cáncer han estado bailando,\nhijo mío.\nTrajeron unas montañas de lacre rojo\ny unas sábanas duras donde estaba el cáncer dormido.\nEl caballo tenía un ojo en el cuello\ny la luna estaba en un cielo tan frío\nque tuvo que desgarrarse su monte de Venus\ny ahogar en sangre y ceniza los cementerios antiguos.\nAmigo.\ndespierta, que los montes todavía no respiran\ny las hierbas de mi corazón están en otro sitio.\nNo importa que estés lleno de agua de mar.\nYo amé mucho tiempo a un niño\nque tenía una plumilla en la lengua\ny vivimos cien años dentro de un cuchillo.\nDespierta. Calla. Escucha. Incorpórate un poco.\nEl aullido es ima larga lengua morada que deja\nhormigas de espanto y licor da lirios.\nYa viene hacia la roca. ¡No alargues tus raíces!\nSe acerca. Gime. No solloces en sueños, amigo.\n¡Amigo!\nLevántate para que oigas aullar\nal perro asirio."}, {"type": "h", "text": "Ruina"}, {"type": "v", "text": "Sin cncontrarse,\nviajero por su propio torso blanco,\n¡así iba al aire!\nPronto se vio que la luna\nera una calavera de caballo\ny el aire una manzana oscura.\nDetrás de la ventana\ncon látigos y luces se sentía\nla lucha de la arena con el agua.\nYo vi llegar las hierbas\ny les eche un cordero que balaba\nbajo sus dientecillos y lancetas.\nVolaba dentro de una gota\nla cáscara de pluma y celuloide\nde la primer paloma.\nLas nubes en manada\nse quedaron dormidas contemplando\nel duelo de las rocas con el alba.\nVienen las hierbas, hijo.\nYa suenan sus espadas de saliva\npor el cielo vacío.\nMi mano, amor. ¡Las hierbas!\nPor los cristales rotos de la casa\nla sangre desató sus cabelleras.\nTú sólo y yo quedamos.\nPrepara tu esqueleto para el aire.\nYo sólo y tú quedamos.\nPrepara tu esqueleto.\nHay que buscar de prisa, amor, de prisa,\nnuestro perfil sin sueño."}]$lira$::jsonb, 450);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 16, 'Luna y panorama de los insectos', $lira$[{"type": "h", "text": "Luna y panorama de los insectos"}, {"type": "h", "text": "(poema de Amor)"}, {"type": "v", "text": "La luna en el mar riela,\nen la lona gime el viento\ny alza en blando movimiento\nolas de plata y azul."}, {"type": "h", "text": "Espronceda"}, {"type": "v", "text": "Mi corazón tendría la forma de un zapato\nsi cada aldea tuviera una sirena.\nPero la noche es interminable cuando se apoya en los enfermos\ny hay barcos que buscan ser mirados para poder hundirse tranquilos\nSi el aire sopla blandamente mi corazón tiene la orma de una niña.\nSi el aire se niega a salir de los cañaverales\nmi corazón tiene la forma de una milenaria boñiga de toro.\nBogar, bogar, bogar, bogar,\nhacia el batallón de puntas desiguales,\nhacia un paisaje de acechos pulverizados.\nNoche igual de la nieve, de los sistemas suspendidos.\nY la luna.\n¡La luna!\nPero no la luna.\nLa raposa de las tabernas,\nel gallo japonés que se comió los ojos,\nlas hierbas masticadas.\nNo nos salvan las solitarias en los vidrios,\nni los herbolarios donde el metafísico\nencuentra las otras vertientes del cielo.\nSon mentira las formas. Sólo existe\nel círculo de bocas del oxígeno.\nY la luna.\nPero no la luna.\nLos insectos,\nlos muertos diminutos por las riberas,\ndolor en longitud,\nyodo en un punto,\nlas muchedumbres en el alfiler,\nel desnudo que amasa la sangre de todos,\ny mi amor que no es un caballo ni una quemadura,\ncriatura de pecho devorado.\n¡Mi amor!\nYa cantan, gritan, gimen: Rostro, ¡Tu rostro! Rostro.\nLas manzanas son unas,\nlas dalias son idénticas,\nla luz tiene un sabor de metal acabado\ny el campo de todo un lustro cabrá en la mejilla de la moneda.\nPero tu rostro cubre los cielos del banquete.\n¡Ya cantan!, ¡gritan!, ¡gimen!,\n¡cubren!, ¡trepan!, ¡espantan!\nEs necesario caminar, ¡de prisa!, por las ondas, por las ramas,\npor las calles deshabitadas de la edad media que bajan al río,\npor las tiendas de las pieles donde suena un cuerno de vaca herida\npor las escalas, ¡sin miedo!, por las escalas.\nHay un hombre descolorido que se está bañando en el mar;\nes tan tierno que los reflectores le comieron jugando el corazón.\nY en el Perú viven mil mujeres, ¡oh insectos!, que noche y día\nhacen nocturnos y desfiles entrecruzando sus propias venas.\nUn diminuto guante corrosivo me detiene. ¡Basta!\nEn mi pañuelo he sentido el tris\nde la primera vena que se rompe.\nCuida tus pies, amor mío, ¡tus manos!,\nya que yo tengo que entregar mi rostro,\nmi rostro, ¡mi rostro!, ¡ay, mi comido rostro!\nEste fuego casto para mi deseo,\nesta confusión por anhelo de equilibrio,\neste inocente dolor de pólvora en mis ojos,\naliviará la angustia de otro corazón\ndevorado por las nebulosas.\nNo nos salva la gente de las zapaterías,\nni los paisajes que se hacen musica al encontrar las llaves oxidadas.\nSon mentira los aires. Sólo existe\nuna cunita en el desván\nque recuerda todas las cosas.\nY la luna.\nPero no la luna.\nLos insectos,\nlos insectos solos,\ncrepitantes, mordientes, estremecidos, agrupados,\ny la luna\ncon un guante de humo sentada en la puerta de sus derribos.\n¡¡La luna!!\nNueva York, 4 de enero de 1930"}]$lira$::jsonb, 526);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 17, 'VII', $lira$[{"type": "h", "text": "VII"}, {"type": "h", "text": "Vuelta a la Ciudad"}, {"type": "v", "text": "Para Antonio Hernández Soriano."}, {"type": "h", "text": "New York"}, {"type": "h", "text": "Oficina y Denuncia"}, {"type": "v", "text": "Debajo de las multiplicaciones\nhay una gota de sangre de pato.\nDebajo de las divisiones\nhay una gota de sangre de marinero.\nDebajo de las sumas, un río de sangre tierna;\nun río que viene cantando\npor los dormitorios de los arrabales,\ny es plata, cemento o brisa\nen el alba mentida de New York.\nExisten las montañas, lo sé.\nY los anteojos para la sabiduría,\nlo sé. Pero yo no he venido a ver el cielo.\nHe venido para ver la turbia sangre,\nla sangre que lleva las máquinas a las cataratas\ny el espíritu a la lengua de la cobra.\nTodos los días se matan en New York\ncuatro millones de patos,\ncinco millones de cerdos,\ndos mil palomas para el gusto de los agonizantes.\nun millón de vacas,\nun millón de corderos\ny dos millones de gallos\nque dejan los cielos hechos añicos.\nMás vale sollozár afilando la navaja\no asesinar a los perros en las alucinantes cacerías\nque resistir en la madrugada\nlos interminables trenes de leche,\nlos interminables trenes de sangre,\ny los trenes de rosas maniatadas\npor los comerciantes de perfumes.\nLos patos y las palomas\ny los cerdos y los corderos\nponen sus gotas de sangre\ndebajo de las multiplicaclones;\ny los terribles alaridos de las vacas estrujadas\nllenan de dolor el valle\ndonde el Hudson se emborracha con aceite.\nYo denuncio a toda la gente\nque ignora la otra mitad,\nla mitad irredimible\nque levanta sus montes de cemento\ndonde laten los corazones\nde los animalitos que se olvidan\ny donde caeremos todos\nen la última fiesta de los taladros\nOs escupo en la cara.\nLa otra mitad me escucha\ndevorando, cantando, volando en su pureza\ncome los niños de las porterías\nque llevan frágIles palitos\na los huecos donde se oxidan\nlas antenas de los insectos.\nNo es el infierno, es la calle.\nNo es la muerte, es la tienda de frutas.\nHay un mundo de ríos quebrados y distancias inasibles\nen la patita de ese gato quebrada por el automóvil,\ny yo oigo el canto de la lombriz\nen el corazón de muchas niñas.\nÓxido, fermento, tierra estremecida.\nTierra tú mismo que nadas por los números de la oficina.\n¿Qué voy a hacer, ordenar los paisajes?\n¿Ordenar los amores que luego son fotografías,\nque luego son pedazos de madera y bocanadas de sangre?\nNo, no; yo denuncio,\nyo denuncio la conjura\nde estas desiertas oficinas\nque no radian las agonías,\nque borran los programas de la selva,\ny me ofrezco a ser comido por las vacas estrujadas\ncuando sus gritos llenan el valle\ndonde el Hudson se emborracba con aceite."}]$lira$::jsonb, 454);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 18, 'Cementerio Judío', $lira$[{"type": "h", "text": "Cementerio Judío"}, {"type": "v", "text": "Las alegres fiebres huyeron a las maromas de los barcos y el judío empujó la verja con el\npudor helado del interior de la lechuga.\nLos niños de Cristo dormían\ny el agua era una paloma\ny la madera era una garza\ny el plomo era un colibrí\ny aun las vivas prisiones de fuego\nestaban consoladas por el salto de la langosta.\nLos niños de Cristo bogaban y los judíos llenaban los muros\ncon un solo corazón de paloma\npor el que todos querían escapar.\nLas niñas de Cristo cantaban y las judías miraban la muerte\ncon un solo ojo de faisán,\nvidriado por la angustia de un millón de paisajes.\nLos médicos ponen en el níquel sus tijeras y guantes de goma\ncuando los cadáveres sienten en los pies\nla terrible claridad de otra luna enterrada.\nPequeños dolores ilesos se acercan a los hospitales\ny los muertos se van quitando un traje de sangre cada día.\nLas arquitecturas de escarcha,\nlas liras y gemidos que se escapan de las hojas diminutas\nen otoño, mojando las últimas vertientes,\nse apagaban en el negro de los sombreros de copa.\nLa hierba celeste y sola de la que huye con miedo el rocío\ny las blancas entradas de mármol que conducen al aire duro\nmostraban su silencio roto por las huellas dormidas de los zapatos.\nEl judío empujó la verja;\npero el judío no era un puerto\ny las barcas de nieve se agolparon\npor las escalerillas de su corazón:\nlas barcas de nieve que acechan\nun hombre de agua que las ahogue,\nlas barcas de los cementerios\nque a veces dejan ciegos a los visitantes.\nLos niños de Cristo dormían\ny el judío ocupó su litera.\nTres mil judíos lloraban en el espanto de las galerías\nporque reunían entre todos con esfuerzo media paloma,\nporque uno tenía la rueda de un reloj\ny otro un botín con orugas parlantes\ny otro una lluvia nocturna cargada de cadenas\ny otro la uña de un ruiseñor que estaba vivo;\ny porque la media paloma gemía\nderramando una sangre que no era la suya.\nLas alegres fiebres bailaban por las cúpulas humedecidas\ny la luna copiaba en su mármol\nnombres viejos y cintas ajadas.\nLlegó la gente que come por detrás de las yertas columnas\ny los asnos de blancos dientes\ncon los especialistas de las articulaciones.\nVerdes girasoles temblaban\npor los páramos del crepúsculo\ny todo el cementerio era una queja\nde bocas de cartón y trapo seco.\nYa los niños de Cristo se dormían\ncuando el judío, apretando los ojos, s\ne cortó las manos en silencio\nal escuchar los primeros gemidos.\nNueva York, 18 de enero de 1930."}]$lira$::jsonb, 450);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 19, 'VIII', $lira$[{"type": "h", "text": "VIII"}, {"type": "h", "text": "Dos Odas"}, {"type": "h", "text": "Grito Hacia Roma"}, {"type": "v", "text": "A mi editor Armando Guibert."}, {"type": "h", "text": "(Desde la torre del crysler building"}, {"type": "v", "text": "Manzanas levemente heridas\npor finos espadines de plata,\nnubes rasgadas por una mano de coral\nque lleva en el dorso una almendra de fuego,\npeces de arsénico como tiburones,\ntiburones como gotas de llanto para cegar una multitud,\nrosas que hieren\ny agujas instaladas en los caños de la sangre,\nmundos enemigos y amores cubiertos de gusanos\ncaerán sobre ti. Caerán sobre la gran cúpula\nque untan de aceite las lenguas militares\ndonde un hombre se orina en una deslumbrante paloma\ny escupa carbón machacado\nrodeado de miles de campanillas.\nPorque ya no hay quien reparta el pan ni el vino\nni quien cultive hierbas en la boca del muerto,\nni quien abra los linos del reposo,\nni quien llore por las heridas de los elefantes.\nNo hay más que un millón de herreros\nforjando cadenas para los niños que han de venir.\nNo hay más que un millón de carpinteros\nque hacen ataúdes sin cruz.\nNo hay más que un gentío de lamentos\nque se abren las ropas en espera de la bala.\nEl hombre que desprecia la paloma debía hablar,\ndebía gritar desnudo entre las columnas,\ny ponerse una inyección para adquirir la lepra\ny llorar un llanto tan terrible\nque disolviera sus anillos y sus teléfonos de diamante.\nPero el hombre vestido de blanco\nignora el misterio de la espiga,\nignora el gemido de la parturienta,\nignora que Cristo puede dar agua todavía,\nignora que la moneda quema el beso de prodigio\ny da la sangre del cordero al pico idiota del faisán.\nLos maestros enseñan a los niños\nuna luz maravillosa que viene del monte;\npero lo que llega es una reunión de cloacas\ndonde gritan las oscuras ninfas del cólera.\nLos maestros señalan con devoción las enormes cúpulas sahumadas;\npero debajo de las estatuas no hay amor,\nno hay amor bajo los ojos de cristal definitivo.\nEl amor está en las carnes desgarradas por la sed,\nen la choza diminuta que lucha con la inundación;\nel amor está en los fosos donde luchan las sierpes del hambre,\nen el triste mar que mece los cadáveres de las gaviotas\ny en el oscurísimo beso punzante debajo de las almohadas.\nPero a viejo de las manos traslúcidas\ndirá: Amor, amor, amor,\naclamado por millones de moribundos;\ndirá: amor, amor, amor,\nentre el tisú estremecido de ternura;\ndirá: paz, paz, paz,\nentre el tirite de cuchillos y melones de dinamita;\ndirá: amor, amor, amor,\nhasta que se le pongan de plata los labios.\nMientras tanto, mientras tanto ¡ay! mientras tanto,\nlos negros que sacan las escupideras,\nlos muchachos que tiemblan balo el terror pálido de los directores,\nlas mujeres ahogadas en aceites minerales,\nla muchedumbre de martillo, de violín o de nube,\nha de gritar aunque le estrellen los sesos en el muro,\nha de gritar frente a las cúpulas,\nha de gritar loca de fuego,\nha de gritar loca de nieve,\nha de gritar con la cabeza llena de excremento,\nha de gritar como todas las noches juntas,\nha de gritar con voz tan desgarrada\nhasta que las ciudades tiemblen como niñas\ny rompan las prisiones del aceite y la música,\nporque queremos el pan nuestro de cada día,\nflor de aliso y perenne ternura desgranada,\nporque queremos que se cumpla la voluntad de la Tierra\nque da sus frutos para todos."}]$lira$::jsonb, 572);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 20, 'Oda a Walt Whitman', $lira$[{"type": "h", "text": "Oda a Walt Whitman"}, {"type": "v", "text": "Por el East River y el Bronx,\nlos muchachos cantaban enseñando sus cinturas,\ncon la rueda, el aceite, el cuero y el martillo.\nNoventa mil mineros sacaban la plata de las rocas\ny los niños dibujaban escaleras y perspectivas.\nPero ninguno se dormía,\nninguno quería ser el río,\nninguno amaba las hojas grandes,\nninguno la lengua azul de la playa.\nPor el East River y el Queensborough\nlos muchachos luchaban con la industria\ny los judíos vendíán al fauno del río\nla rosa de la circuncisión\ny el cielo desembocaba por los puentes y los tejados\nmanadas de bisontes empujadas por el viento.\nPero ninguno se detenía,\nninguno quería ser nube,\nninguno buscaba los helechos\nni la rueda amarilla del tamboril.\nCuando la luna salga\nlas poleas rodarán para turbar el cielo;\nun límite de agujas cercará la memoria\ny los ataúdes se llevarán a los que no trabajan.\nNueva York de cieno,\nNueva York de alambres y de muerte.\n¿Qué ángel llevas oculto en la mejilla?\n¿Qué voz perfecta dirá las verdades del trigo?\n¿Quién el sueño terrible de tus anémonas manchadas?\nNi un solo momento, viejo hermoso Walt Whitman,\nhe dejado de ver tu barba llena de mariposas,\nni tus hombros de pana gastados por la luna,\nni tus muslos de Apolo virginal,\nni tu voz como una columna de ceniza;\nanciano hermoso como la niebla\nque gemías igual que un pájaro\ncon el sexo atravesado por una aguja,\nenemigo del sátiro,\nenemigo de la vid\ny amante de los cuerpos bajo la burda tela.\nNi un solo momento, hermosura viril\nque en montes de carbón, anuncios y ferrocarriles,\nsoñabas ser un río y dormir como un río\ncon aquel camarada que pondría en tu pecho\nun pequeño dolor de ignorante leopardo.\nNi un solo momento, Adán de sangre, macho,\nhombre solo en el mar, viejo hermoso Walt Whitman,\nporque por las azoteas,\nagrupados en los bares,\nsaliendo en racimos de las alcantarillas,\ntemblando entre las piernas de los chauffeurs\no girando en las plataformas del ajenjo,\nlos maricas, Walt Whitman, te soñaban.\n¡También ése! ¡También! Y se despeñan\nsobre tu barba luminosa y casta,\nrubios del norte, negros de la arena,\nmuchedumbres de gritos y ademanes,\ncomo gatos y como las serpientes,\nlos maricas, Walt Whitman, los maricas\nturbios de lágrinias, carne para fusta,\nbota o mordisco de los domadores.\n¡También ése! ¡También! Dedos teñidos\napuntan a la orilla de tu sueño\ncuando el amigo come tu manzana\ncon un leve sabor de gasolina\ny el sol canta por los ombligos\nde los muchachos que juegan bajo los puentes.\nPero tú no buscabas los ojos arañados,\nni el pantano oscurísimo donde sumergen a los niños,\nni la saliva helada,\nni las curvas heridas como panza de sapo\nque llevan los maricas en coches y terrazas\nmientras la luna los azota por las esquinas del terror.\nTú buscabas un desnudo que fuera como un río,\ntoro y sueño que junte la rueda con el alga,\npadre de tu agonía, camelia de tu muerte,\ny gimiera en las llamas de tu ecuador oculto.\nPorque es justo que el hombre no busque su deleite\nen la selva de sangre de la mañana próxima.\nEl cielo tiene playas donde evitar la vida\ny hay cuerpos que no deben repetirse en la aurora.\nAgonía, agonía, sueño, fermento y sueño.\nÉste es el mundo, amigo, agonía, agonía.\nLos muertos se descomponen bajo el reloj de las ciudades,\nla guerra pasa llorando con un millón de ratas grises,\nlos ricos dan a sus queridas\npequeños moribundos iluminados,\ny la vida no es noble, ni buena, ni sagrada.\nPuede el hombre, si quiere, conducir su deseo\npor vena de coral o celeste desnudo.\nMañana los amores serán rocas y el Tiempo\nuna brisa que viene dormida por las ramas.\nPor eso no levanto mi voz, viejo Walt Whitman,\ncontra el niño que escribe\nnombre de niña en su almohada,\nni contra el muchacho que se viste de novia\nen la oscuridad del ropero,\nni contra los solitarios de los casinos\nque beben con asco el agua de la prostitución,\nni contra los hombres de mirada verde\nque aman al hombre y queman sus labios en silencio.\nPero sí contra vosotros, maricas de las ciudades,\nde carne tumefacta y pensamiento inmundo,\nmadres de lodo, arpías, enemigos sin sueño\ndel Amor que reparte coronas de alegría.\nContra vosotros siempre, que dais a, los muchachos\ngotas de sucia muerte con amargo veneno.\nContra vosotros siempre,\nFaeries de Norteamérica,\nPójaros de la Habana,\nJotos de México,\nSarasas de Cádiz,\nApios de Sevilla,\nCancos de Madrid,\nFloras de Alicante,\nAdelaidas de Portugal.\n¡Maricas de todo el mundo, asesinos de palomas!\nEsclavos de la mujer, perras de sus tocadores,\nabiertos en las plazas con fiebre de abanico\no emboscados en yertos paisajes de cicuta.\n¡No haya cuartel! La muerte\nmana de vuestros ojos\ny agrupa flores grises en la orilla del cieno.\n¡No haya cuartel! ¡Alerta!\nQue los confundidos, los puros,\nlos clásicos, los señalados, los suplicantes\nos cierren las puertas de la bacanal.\nY tú, bello Walt Whitman, duerme a orillas del Hudson.\ncon la barba hacia el polo y las manos abiertas.\nArcilla blanda o nieve, to lengua está llamando\ncamaradas que velen to gacela sin cuerpo.\nDuerme, no queda nada.\nUna danza de muros agita las praderas\ny América se anega de máquinas y llanto.\nQuiero que el aire fuerte de la noche más honda\nquite flores y letras del arco donde duermes\ny un niño negro anuncie a los blancos del oro\nla llegada del reino de la espiga."}]$lira$::jsonb, 936);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 21, 'IX', $lira$[{"type": "h", "text": "IX"}, {"type": "h", "text": "Huida de Nueva York"}, {"type": "h", "text": "Dos valses hacia la civilización"}, {"type": "h", "text": "Pequeño Vals Vienes"}, {"type": "v", "text": "En Viena hay diez muchachas,\nun hombro donde solloza la muerte\ny un bosque de palomas disecadas.\nHay un fragmento de la mañana\nen el museo de la escarcha.\nHay un salón con mil ventanas.\n¡Ay, ay, ay, ay!\nToma este vals con la boca cerrada.\nEste vals, este vals, este vals,\nde sí, de muerte y de coñac\nque moja su cola en el mar.\nTe quiero, te quiero, te quiero,\ncon la butaca y el libro muerto,\npor el melancólico pasillo,\nen el oscuro desván del lirio,\nen nuestra cama de la luna\ny en la danza que sueña la tortuga.\n¡Ay, ay, ay, ay!\nToma este vals de quebrada cintura.\nEn Viena hay cuatro espejos\ndonde juegan tu boca y los ecos.\nHay una muerte para piano\nque pinta de azul a los muchachos.\nHay mendigos por los tejados.\nHay frescas guirnaldas de llanto.\n¡Ay, ay, ay, ay!\nToma este vals que se muere en mis brazos.\nPorque te quiero, te quiero, amor mío,\nen el desván donde juegan los niños,\nsoñando viejas luces de Hungría\npor los rumores de la tarde tibia,\nviendo ovejas y lirios de nieve\npor el silencio oscuro de tu frente.\n¡Ay, ay, sy, ay!\nToma este vals del \"Te quiero siempre\".\nEn Viena bailaré contigo\ncon un disfraz que tenga\ncabeza de río.\n¡Mira qué orillas tengo de jacintos!\nDejaré mi boca entre tus piernas,\nmi alma en fotografías y azucenas,\ny en las ondas oscuras de tu andar\nquiero, amor mío, amor mío dejar,\nviolín y sepulcro, las cintas del vals."}, {"type": "h", "text": "Vals en las Ramas"}, {"type": "v", "text": "Cayó una hoja\ny dos\ny tres.\nPor la luna nadaba un pez.\nEl agua duerme una hora\ny el mar blanco duerme cien.\nLa dama\nestaba muerta en la rama.\nLa monja\ncantaba dentro de la toronja.\nLa niña\niba por el pino a la piña.\nY el pino\nbuscaba la plumilla del trino.\nPero el ruiseñor\nlloraba sus heridas alrededor.\nY yo también\nporque cayó una hoja\ny dos\ny tres.\nY una cabeza de cristal\ny un violín de papel\ny la nieve podría con el mundo\nuna a una\ndos a dos\ny tres a tres.\n¡Oh, duro marfil de carnes invisibles!\n¡Oh, golfo sin hormigas del amanecer!\nCon el numen de las ramas,\ncon el ay de las damas,\ncon el cro de las ranas,\ny el geo amarillo de la miel.\nLlegará un torso de sombra\ncoronado de laurel.\nSerá el cielo para el viento\nduro como una pared\ny las ramas desgajadas\nse irán bailando con él.\nUna a una\nalrededor de la luna,\ndos a dos\nalrededor del sol.\ny tres a tres\npara que los marfiles se duerman bien."}]$lira$::jsonb, 466);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 22, 'El poeta llega a la habana', $lira$[{"type": "h", "text": "El poeta llega a la habana"}, {"type": "v", "text": "A don Fernando Ortiz."}, {"type": "h", "text": "Son de negros en cuba"}, {"type": "v", "text": "Cuando llegue la luna llena iré a Santiago de Cuba,\niré a Santiago,\nen un coche de agua negra.\nIré a Santiago.\nCantarán los techos de palmera.\nIré a Santiago.\nCuando la palma quiere ser cigüeña,\niré a Santiago.\nY cuando quiere ser medusa el plátano,\niré a Santiago.\nIré a Santiago\ncon la rubia cabeza de Fonseca.\nIré a Santiago.\nY con la rosa de Romeo y Julieta\niré a Santiago.\n¡Oh Cuba! ¡Oh ritmo de semillas secas!\nIré a Santiago.\n¡Oh cintura caliente y gota de madera!\nIré a Santiago.\nArpa de troncos vivos. Caimán. Flor de tabaco.\nIré a Santiago.\nSiempre he dicho que yo iría a Santiago\nen un coche de agua negra.\nIré a Santiago.\nBrisa y alcohol en las ruedas,\niré a Santiago.\nMi coral en la tiniebla,\niré a Santiago.\nEl mar ahogado en la arena,\niré a Santiago,\ncalor blanco, fruta muerta,\niré a Santiago.\n¡Oh bovino frescor de cañaveras!\n¡Oh Cuba! ¡Oh curva de suspiro y barro!\nIré a Santiago."}, {"type": "h", "text": "Crucifixion"}, {"type": "v", "text": "La luna pudo detenerse al fin [por] la curva blanquísima de los caballos.\nUn rayo de luz violeta que se escapaba de la herida\nproyectó en el cielo el instante de la circuncisión de un niño muerto.\nLa sangre bajaba por el monte y los ángeles la buscaban,\npero los cálices eran de viento y al fin llenaba los zapatos.\nCojos perros fumaban sus pipas y un olor de cuero caliente\nponía grises los labios redondos de los que vomitaban en las esquinas.\nY llegaban largos alaridos por el Sur de la noche seca.\nEra que la luna quemaba con sus bujías el falo de los caballos.\nUn sastre especialista en púrpura\nhabía encerrado a las tres santas mujeres\ny les enseñaba una calavera [por] los vidrios de la ventana.\nLas tres en el arrabal rodeaban a un camello blanco\nque lloraba porque al alba\ntenía que pasar sin remedio por el ojo de una aguja.\n¡Oh Cruz! ¡Oh clavos! ¡Oh espina!\n¡Oh espina clavada en el hueso hasta que se oxiden los planetas!\nComo nadie volvía la cabeza, el cielo pudo desnudarse.\nEntonces se oyó la gran voz y los fariseos dijeron:\nEsa maldita vaca tiene las tetas llenas de leche.\nLa muchedumbre cerraba las puertas\ny la lluvia bajaba por las calles decidida a mojar el co[razón]\nmientras la tarde se puso turbia de latidos y leñadores\ny la oscura ciudad agonizaba bajo el marttllo de los carpinteros.\nEsa maldita vaca\ntiene las tetas llenas de perdigones,\ndijeron los fariseos.\nPero la sangre mojó sus pies y los espíritus inmundos\nestrellaban ampollas de laguna sobre las paredes del templo.\nSe supo el momento preciso de la salvacion de nuestra vida\nporque la luna lavó con agua\nlas quemaduras de los caballos\ny no la niña viva que callaron en la arena.\n[Entonces salieron los fríos cantando sus canciones\ny las ranas encendieron sus lumbres en la doble orilla del río.]\nEsa maldita vaca, maldita, maldita, maldita\nno nos dejará dormir, dijeron los fariseos,\ny se alejaron a sus casas por el tumulto de la calle\ndando empujones a los borrachos y escupiendo sal de los sacrificios\nmientras la sangre los seguía con un balido de cordero.\nFue entonces\ny la tierra despertó arrojando temblorosos ríos de polilla.\nNueva York, 18 de octubre de 1929."}]$lira$::jsonb, 571);
insert into public.chapters (book_id, position, title, body, word_count)
values ('poeta-en-nueva-york', 23, 'Pequeño Poema Infinito', $lira$[{"type": "h", "text": "Pequeño Poema Infinito"}, {"type": "v", "text": "Para Luis Cardoza y Aragón.\nEquivocar el camino\nes llegar a la nieve\ny llegar a la nieve\nes pacer durante veinte siglos las hierbas de los cementerios.\nEquivocar cl camino\nes llegar a la mujer,\nla mujer que no teme la luz,\nla mujer que mata dos gallos en un segundo,\nla luz que no teme a los gallos\ny los gallos que no saben cantar sobrela nieve.\nPero si la nieve se equivoca de corazón\npuede llegar el viento Austro\ny como el aire no hace caso de los gemidos\ntendremos que pacer otra vez las hierbas de los cementerios.\nYo vi dos dolorosas espigas de cera\nque enterraban un paisaje de volcanes\ny vi dos niños locos que empujaban llorando las pupilas de un asesino.\nPero el dos no ha sido nunca un número\nporque es una angustia y su sombra\nporque es la guitarra donde el amor se desespera,\nporque es la demostración de otro infinito que no es suyo\ny es las murallas del muerto\ny el castigo de la nueva resurrección sin finales.\nLos muertos odian el número dos\npero el número dos adormece a las mujeres\ny como la mujer teme la luz\nla luz tiembla delante de los gallos\ny los gallos sólo saben volar sobre la nieve\ntendrémos que pacer sin descanso las hierbas de los cementerios.\nNueva York, 10 de enero de 1930."}, {"type": "h", "text": "Fin de"}, {"type": "h", "text": "«poeta en Nueva York»"}]$lira$::jsonb, 242);

